window.PACK={"book":{"id":"riyad","title":"رياض الصالحين","type":"hadith","author":"النووي","source":"hadith-json (AhmedBaset) — مأخوذ من sunnah.com","numbering":"ترقيم تسلسلي خاص بالمصدر، وقد يختلف عن الترقيم المطبوع","packVersion":"1c798c9ad809"},"items":[{"id":"riyad:1","bookId":"riyad","type":"hadith","num":1,"kitab":"كتاب الأدب","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم مر على رجل من الأنصار وهو يعظ أخاه في الحياء، فقال رسول الله صلى الله عليه وسلم‏:‏","matn":"\"دعه فإن الحياء من الإيمان\" ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:2","bookId":"riyad","type":"hadith","num":2,"kitab":"كتاب الأدب","isnad":"وعن عمران بن حصين، رضي الله عنهما، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “ الحياء لا يأتى إلا بخير” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لمسلم” ‏","matn":"\"‏الحياءه خير كله”أوقال‏:‏ “الحياء كله خير‏\"‏‏.‏"},{"id":"riyad:3","bookId":"riyad","type":"hadith","num":3,"kitab":"كتاب الأدب","isnad":"-وعن أبى هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “الإيمان بضع وسبعون، أو بضع وستون شعبة، فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:4","bookId":"riyad","type":"hadith","num":4,"kitab":"كتاب الأدب","isnad":"","matn":"وعن أبي سعيد الخدري رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم أشد حياء من العذراء في خدرها، فإذا رأى شيئياً يكرهه عرفناه في وجهه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:5","bookId":"riyad","type":"hadith","num":5,"kitab":"كتاب الأدب","isnad":"عن أبى سعيد الخدرى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن من شر الناس عند الله منزلة يوم القيامة الرجل يفضي إلى المرأة وتفضي إليه ثم ينشر سرها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:6","bookId":"riyad","type":"hadith","num":6,"kitab":"كتاب الأدب","isnad":"","matn":"وعن عبد الله بن عمر رضي الله عنهما أن عمر رضي الله عنه حين تأيمت بنته حفصة قال‏:‏ لقيت عثمان بن عفان رضي الله عنه ، فعرضت عليه حفصة فقلت‏:‏ إن شئت أنكحتك حفصة بنت عمر‏؟‏ قال‏:‏ سأنظر في أمري‏.‏ فلبثت ليالي، ثم لقيني فقال ‎‏:‏ قد بدا لي أن لا أتزوج يومي هذا‏.‏ فلقيت أبا بكر الصديق رضي الله عنه، فلم يرجع إلى شيئاً‏!‏ فكنت عليه أوجد مني على عثمان، فلبثت ليالي، ثم خطبها النبي صلى الله عليه وسلم، فأنكحتها إياه‏.‏ فلقيني أبو بكر فقال‏:‏ لعلك وجدت حين عرضت على حفصة فلم أرجع إليك شيئاً‏؟‏ فقلت‏:‏ نعم‏.‏ قال‏:‏ فإنه لم يمنعني أن أرجع إليك فيما عرضت على إلا أني كنت علمت أن النبي صلى الله عليه وسلم ذكرها، فلم أكن لأفشي سر رسول الله صلى الله عليه وسلم، ولوتركها النبى صلى الله عليه وسلم لقبلتها ‏.‏ ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:7","bookId":"riyad","type":"hadith","num":7,"kitab":"كتاب الأدب","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ كن أزواج النبى صلى الله عليه وسلم عنده، فأقبلت فاطمة رضي الله عنها تمشى، ما تخطئ من مشية رسول الله صلى الله عليه وسلم شيئاً، فلما رآها رحب بها وقال‏:‏ “مرحباً بابنتى” ثم أجلسها عن يمينه أو عن شماله، ثم سارها فبكت بكاء شديداً، فلما رأى جزعها سارها الثانية فضحكت، فقلت لها‏:‏ خصك رسول الله صلى الله عليه وسلم من بين نسائه بالسرار، ثم أنت تبكين ‏!‏ فلما قام رسول الله صلى الله عليه وسلم سألتها‏:‏ ما قال لك رسول الله صلى الله عليه وسلم ‏؟‏ قالت‏:‏ ما كنت لأفشي على رسول الله صلى الله عليه وسلم سره‏.‏ فلما توفي رسول الله صلى الله عليه وسلم قلت‏:‏ عزمت عليك بما لي عليك من الحق، لما حدثتني ما قال لك رسول الله صلى الله عليه وسلم‏؟‏ فقالت‏:‏ أما الآن فنعم، أما حين سارني في المرة الأولى فأخبرني “أن جبريل كان يعارضه القرآن في كل سنة مرة أو مرتين، وأنه عارضه الآن مرتين، وإني لا أرى الأجل إلا قد اقترب، فاتقى الله واصبرى، فغنه نعم السلف أنا لك” فبكيت بكائى الذى رأيت‏.‏ فلما رأى جزعى سارنى الثانية، فقال‏:‏ ‏","matn":"\"‏يا فاطمة أما ترضين أن تكونى سيدة نساء المؤمنين، أو سيدة نساء هذه الأمة” فضحكت ضحكى الذى رأيت‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏(‏‏(‏وهذا لفظ مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:8","bookId":"riyad","type":"hadith","num":8,"kitab":"كتاب الأدب","isnad":"","matn":"وعن ثابت عن أنس، رضي الله عنه قال‏:‏ أتى على رسول الله صلى الله عليه وسلم وأنا ألعب مع الغلمان، فسلم علينا، فبعثنى في حاجةٍ، فأبطأت على أمي‏.‏ فلما جئت قالت‏:‏ ما حبسك‏؟‏ فقلت‏:‏ بعثنى رسول الله صلى الله عليه وسلم لحاجة، قالت‏:‏ ما حاجته‏؟‏ قلت‏:‏ إنها سر‏.‏قالت‏:‏ لا تخبرن بسر رسول الله صلى الله عليه وسلم أحداً‏.‏ قال أنس‏:‏ والله لو حدثت به أحداً لحدثتك به يا ثابت‏.‏ ‏(‏‏(‏رواه مسلم، وروى البخارى بعضه مختصراً‏)‏‏)‏‏.‏"},{"id":"riyad:9","bookId":"riyad","type":"hadith","num":9,"kitab":"كتاب الأدب","isnad":"وعن أبي هريرة رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏آية المنافق ثلاث‏:‏ إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ زاد في ‏(‏‏(‏رواية لمسلم‏)‏‏)‏‏:‏ ‏\"‏وإن صام وصلى وزعم أنه مسلم‏\"‏‏.‏"},{"id":"riyad:10","bookId":"riyad","type":"hadith","num":10,"kitab":"كتاب الأدب","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أربع من كن فيه كان منافقا خالصاً‏.‏ ومن كانت فيه خصلة منهن كانت فيه خصلة من النفاق حتى يدعها ‏:‏ إذا اؤتمن خان ، وإذا حدث كذب، وإذا عاهد غدر، وإذا خاصم فجر‏\"‏‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:11","bookId":"riyad","type":"hadith","num":11,"kitab":"كتاب الأدب","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال لي النبى صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لو قد جاء مال البحرين أعطيتك هكذا وهكذا وهكذا‏\"‏ فلم يجئ مال البحرين حتى قبض النبى صلى الله عليه وسلم، فلما جاء مال البحرين أمر أبو بكر رضي الله عنه فنادي‏:‏ من كان له عند رسول صلى الله عليه وسلم عدة أو دين فليأتنا‏.‏ فأتيته وقلت له‏:‏ إن النبى صلى الله عليه وسلم قال لى كذا وكذا، فحثى لى حثية، فعددتها، فإذا هى خمسمائة، فقال لى‏:‏ خذ مثلها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:12","bookId":"riyad","type":"hadith","num":12,"kitab":"كتاب الأدب","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ يا عبد الله ، لا تكن مثل فلان، كان يقوم الليل فترك قيام الليل ‏!‏‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:13","bookId":"riyad","type":"hadith","num":13,"kitab":"كتاب الأدب","isnad":"عن عدي بن حاتم رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏اتقوا النار ولو بشق تمرة فمن لم يجد فبكلمة طيبة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:14","bookId":"riyad","type":"hadith","num":14,"kitab":"كتاب الأدب","isnad":"وعن أبي هريرة أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏والكلمة الطيبة صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وهو بعض حديث تقدم بطوله‏.‏"},{"id":"riyad:15","bookId":"riyad","type":"hadith","num":15,"kitab":"كتاب الأدب","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تحقرن من المعروف شيئاً، ولو أن تلقى أخاك بوجه طلق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:16","bookId":"riyad","type":"hadith","num":16,"kitab":"كتاب الأدب","isnad":"","matn":"عن أنس رضي الله عنه أن النبى صلى الله عليه وسلم كان إذا تكلم بكلمة أعادها ثلاثاً حتى تفهم عنه، وإذا أتى على قومٍ فسلم عليهم سلم عليهم ثلاثاً‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:17","bookId":"riyad","type":"hadith","num":17,"kitab":"كتاب الأدب","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان كلام رسول الله صلى الله عليه وسلم كلاماً فصلاً يفهمه كل من يسمعه‏.‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:18","bookId":"riyad","type":"hadith","num":18,"kitab":"كتاب الأدب","isnad":"عن جرير بن عبد الله رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم في حجة الوداع‏:‏ ‏","matn":"\"‏استنصت الناس‏\"‏ ثم قال‏:‏ لا ترجعوا بعدي كفاراً يضرب بعضكم رقاب بعض‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:19","bookId":"riyad","type":"hadith","num":19,"kitab":"كتاب الأدب","isnad":"","matn":"عن أبى وائل شقيق بن سلمة قال‏:‏ كان ابن مسعود رضي الله عنه يذكرنا في كل خميس، فقال له رجل‏:‏ يا أبا عبد الرحمن، لوددت أنك ذكرتنا كل يوم، فقال‏:‏ أما إنه يمنعني من ذلك أني أكره أن أملكم وإني أتخولكم بالموعظة، كما كان رسول الله صلى الله عليه وسلم يتخولنا بها مخافة السآمة علينا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:20","bookId":"riyad","type":"hadith","num":20,"kitab":"كتاب الأدب","isnad":"وعن أبى اليقظان عمار بن ياسر رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن طول صلاة الرجل، وقصر خطبته، مئنة من فقهه، فأطيلوا الصلاة، وأقصروا الخطبة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:21","bookId":"riyad","type":"hadith","num":21,"kitab":"كتاب الأدب","isnad":"وعن معاوية بن الحكم السلمي رضي الله عنه قال‏:‏ ‏","matn":"\"‏بينا أنا أصلي مع رسول الله صلى الله عليه وسلم ، إذا عطس رجل من القوم فقلت‏:‏ يرحمك الله، فرماني القوم بأبصارهم ‏!‏ فقلت‏:‏ واثكل أمياه ‏!‏ ما شأنكم تنظرون إلى‏؟‏ فجعلوا يضربون بأيديهم على أفخاذهم ‏!‏ فلما رأيتهم يصمتونني لكنى سكت‏.‏ فلما صلى رسول الله صلى الله عليه وسلم، فبأبي هو وأمي، ما رأيت معلما قبله ولا بعده أحسن تعليماً منه، فوالله ما كهرني ولا ضربني ولا شتمني، قال‏:‏ ‏\"‏إن هذه الصلاة لا يصلح فيها شئ من كلام الناس، إنما هى التسبيح والتكبير، وقراءة القرآن‏\"‏ أو كما قال رسول الله صلى الله عليه وسلم قلت‏:‏ يا رسول الله، إنى حديث عهد بجاهلية، وقد جاء الله بالإسلام، وإن منا رجالً يأتون الكهان‏؟‏ قال‏:‏ ‏\"‏فلا تأتهم، قلت‏:‏ ومنا رجال يتطيرون‏؟‏ قال‏:‏ ذاك شئ يجدونه في صدورهم، فلا يصدهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:22","bookId":"riyad","type":"hadith","num":22,"kitab":"كتاب الأدب","isnad":"","matn":"وعن العرباض بن سارية رضي الله عنه قال‏:‏ وعظنا رسول الله موعظة وجلت منها القلوب، وذرفت منها العيون وذكر الحديث وقد سبق بكماله في باب الأمر بالمحافظة على السنة، وذكرنا أن الترمذي قال‏:‏ ‏(‏‏(‏إنه حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:23","bookId":"riyad","type":"hadith","num":23,"kitab":"كتاب الأدب","isnad":"","matn":"عن عائشة رضي الله عنها قالت‏:‏ ما رأيت رسول الله صلى الله عليه وسلم مستجمعا قط ضاحكاً حتى ترى منه لهواته، إنما كان يتبسم ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:24","bookId":"riyad","type":"hadith","num":24,"kitab":"كتاب الأدب","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “إذا أقيمت الصلاة، فلا تأتوها وأنتم تسعون، وأتوها وأنتم تمشون، وعليكم السكينة، فما أدركتم فصلوا، وما فاتكم فأتموا” ‏(‏‏(‏متفق عليه‏)‏‏)‏ زاد مسلم في رواية له‏:‏ ‏","matn":"\"‏فإن أحدكم إذا كان يعمد إلى الصلاة فهو في صلاة‏\"‏‏.‏"},{"id":"riyad:25","bookId":"riyad","type":"hadith","num":25,"kitab":"كتاب الأدب","isnad":"وعن ابن عباس رضي الله عنهما أنه دفع مع النبي صلى الله عليه وسلم يوم عرفة فسمع النبي صلى الله عليه وسلم وراءه زجراً شديداً وضرباً وصوتاً للإبل، فأشار بسوطه إليهم وقال‏:‏ “أيها الناس عليكم بالسكينة فإن البر ليس بالإيضاع‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري، وروى مسلم بعضه‏)‏‏)‏‏.‏"},{"id":"riyad:26","bookId":"riyad","type":"hadith","num":26,"kitab":"كتاب الأدب","isnad":"عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من كان يؤمن بالله واليوم الآخر فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر فليصل رحمه، ومن كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:27","bookId":"riyad","type":"hadith","num":27,"kitab":"كتاب الأدب","isnad":"وعن أبي شريح خويلد بن عمرو الخزاعي رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من كان يؤمن بالله واليوم الآخر فليكرم ضيفه جائزته‏\"‏ قالوا‏:‏ وما جائزته يا رسول الله صلى الله عليه وسلم قال‏:‏ ‏\"‏يومه وليلته‏.‏ والضيافة ثلاثة أيام، فما كان وراء ذلك فهو صدقة عليه” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي ‏(‏‏(‏رواية لمسلم‏)‏‏)‏‏:‏ ‏\"‏لا يحل لمسلم أن يقيم عند أخيه حتى يؤثمة‏\"‏ قالوا‏:‏ يا رسول الله ، وكيف يؤثمه‏؟‏ قال‏:‏ ‏\"‏يقيم عنده ولا شيء له يقريه به‏\"‏‏.‏"},{"id":"riyad:28","bookId":"riyad","type":"hadith","num":28,"kitab":"كتاب الأدب","isnad":"","matn":"عن أبي إبراهيم- ويقال أبو محمد، ويقال أبو معاوية- عبد الله بن أبي أوفى رضي الله عنه أن رسول الله صلى الله عليه وسلم بشر خديجة، رضي الله عنها، ببيت في الجنة من قصب ، لا صخب فيه ولا نصب‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:29","bookId":"riyad","type":"hadith","num":29,"kitab":"كتاب الأدب","isnad":"وعن أبي موسى الأشعري رضي الله عنه ، أنه توضأ في بيته، ثم خرج فقال‏:‏ لألزمن رسول الله صلى الله عليه وسلم ، ولأكونن معه يومي هذا، فجاء المسجد، فسأل عن النبي صلى الله عليه وسلم الله عليه وسلم ، فقالوا‏:‏ وجه ههنا، قال‏:‏ فخرجت على أثره أسأل عنه ، حتى دخل بئر أريس، فجلست عند الباب حتى قضى رسول الله صلى الله عليه وسلم حاجته وتوضأ، فقمت إليه، فإذا هو قد جلس على بئر أريس وتوسط قفها، وكشف عن ساقيه ودلاهما في البئر، فسلمت عليه ثم انصرفت، فجلست عند الباب فقلت‏:‏ لأكونن بواب رسول الله صلى الله عليه وسلم اليوم، فجاء أبو بكر رضي الله عنه فدفع الباب فقلت‏:‏ من هذا‏؟‏ فقال‏:‏ أبو بكر، فقلت على رسلك، ثم ذهبت فقلت‏:‏ يا رسول الله هذا أبو بكر يستأذن، فقال‏:‏ ‏","matn":"\"‏ائذن له وبشره بالجنة‏\"‏ فأقلبت حتى قلت لأبي بكر‏:‏ ادخل ورسول الله يبشرك بالجنة، فدخل أبو بكر حتى جلس عن يمين النبي صلى الله عليه وسلمى الله عليه وسلم معه في القف، ودلى رجليه في البئر كما صنع رسول الله صلى الله عليه وسلم ، وكشف عن ساقيه، ثم رجعت وجلست، وقد تركت أخي يتوضأ ويلحقني ، فقلت‏:‏ إن يرد الله بفلان -يرد أخاه- خيراً يأت به، فإذا إنسان يحرك الباب، فقلت‏:‏ من هذا‏؟‏ فقال‏:‏ عمر بن الخطاب‏:‏ فقلت‏:‏ على رسلك ، ثم جئت إلى رسول الله صلى الله عليه وسلم ، فسلمت عليه وقلت‏:‏ هذا عمر يستأذن‏؟‏ فقال‏:‏”ائذن له وبشره بالجنة‏\"‏ فجئت عمر، فقلت‏:‏ أذن ويبشرك رسول الله صلى الله عليه وسلم بالجنة، فدخل فجلس مع رسول الله صلى الله عليه وسلم في القف عن يساره، ودلى رجليه في البئر، ثم رجعت فجلست فقلت‏:‏ إن يرد الله بفلان خيراً -يعني أخاه- يأت به، فجاء إنسان فحرك الباب‏.‏ فقلت‏:‏ من هذا ‏؟‏ فقال‏:‏ عثمان بن عفان فقلت‏:‏ على رسلك، وجئت النبي صلى الله عليه وسلم الله عليه وسلم ، فأخبرته فقال‏:‏ ‏\"‏ائذن له وبشره بالجنة مع بلوى تصيبه‏\"‏ فجئت فقلت له‏:‏ ادخل ويبشرك رسول الله صلى الله عليه وسلم بالجنة مع بلوى تصيبك، فدخل فوجد القف قد ملئ، فجلس وجاههم من الشق الآخر‏.‏ قال سعيد بن المسيب‏:‏ فأولتها قبورهم ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وزاد في رواية‏:‏ “وأمرني رسول الله صلى الله عليه وسلم بحفظ الباب‏.‏ وفيها أن عثمان حين بشره حمد الله تعالى، ثم قال‏:‏ الله المستعان‏.‏"},{"id":"riyad:30","bookId":"riyad","type":"hadith","num":30,"kitab":"كتاب الأدب","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ كنا قعوداً حول رسول الله صلى الله عليه وسلم ، ومعنا أبو بكر وعمر رضي الله عنهما في نفر، فقام رسول الله صلى الله عليه وسلم من بين أظهرنا فأبطأ علينا، وخشينا أن يقتطع دوننا وفزعنا فقمنا، فكنت أول من فزع، فخرجت أبتغي رسول الله صلى الله عليه وسلم ، حتى أتيت حائطاً للأنصار لبني النجار، فدرت به هل أجد له باب، فلم أجد، فإذا ربيع يدخل في جوف حائط من بئر خارجه -والربيع‏:‏ الجدول الصغير -فاحتفزت، فدخلت على رسول الله صلى الله عليه وسلم فقال‏:‏ “أبو هريرة‏؟‏” فقلت‏:‏ نعم يا رسول الله ، قال‏:‏ “ما شأنك” قلت‏:‏ كنت بين أظهرنا فقمت فأبطأت علينا، فخشينا أن تقتطع دوننا، ففزعنا، فكنت أول من فزع، فأتيت هذا الحائط فاحتفرت كما يحتفر الثعلب، وهؤلاء الناس ورائي‏.‏ فقال‏:‏ ‏","matn":"\"‏يا أبا هريرة‏\"‏ وأعطاني نعليه فقال‏:‏ ‏\"‏اذهب بنعلي هاتين، فمن لقيت من وراء هذا الحائط يشهد أن لا إله إلا الله مستيقنا بها قلبه، فبشره بالجنة‏\"‏ وذكر الحديث بطوله، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:31","bookId":"riyad","type":"hadith","num":31,"kitab":"كتاب الأدب","isnad":"وعن ابن شماسة قال‏:‏ حضرنا عمرو بن العاص رضي الله عنه ، وهو في سياقة الموت فبكى طويلاً، وحول وجهه إلى الجدار، فجعل ابنه يقول‏:‏ يا أبتاه، أما بشرك رسول الله صلى الله عليه وسلم بكذا‏؟‏ أما بشرك رسول الله صلى الله عليه وسلم بكذا‏؟‏ فأقبل بوجهه فقال‏:‏ إن أفضل ما نعد شهادة أن لا إله إلا الله، وأن محمداً رسول الله ، إني قد كنت على أطباق ثلاث‏:‏ لقد رأيتني وما أحد أشداً بغضاً لرسول الله صلى الله عليه وسلم مني ، ولا أحب إلي من أن أكون قد استمكنت منه فقتلته، فلو مت على تلك الحال لكنت من أهل النار، فلما جعل الله الإسلام في قلبي أتيت النبي صلى الله عليه وسلمى الله عليه وسلم فقلت‏:‏ أبسط يمينك فلأبايعك، فبسط يمينه فقبضت يدي، فقال‏:‏”مالك يا عمرو‏؟‏‏","matn":"\"‏ قلت‏:‏ أردت أن أشترط قال‏:‏ ‏\"‏تشترط ماذا‏؟‏‏\"‏ قلت ‏:‏ أن يغفر لي، قال‏:‏ ‏\"‏أماعلمت أن الإسلام يهدم ما كان قبله، وأن الهجرة تهدم ما كان قبلها، وأن الحج يهدم ما كان قبله” وما كان أحد أحب إلي من رسول الله صلى الله عليه وسلم ، ولا أجل في عيني منه، وما كنت أطيق أن املأ عيني منه إجلالاً له؛ ولو سئلت أن أصفه ما أطقت؛ لأني لم أكن أملاً عيني منه، ولو مت على تلك الحال لرجوت أن أكون من أهل الجنة، ثم ولينا أشياء ما أدري مال حالي فيها‏؟‏ فإذا أنا مت فلا تصحبني نائحة ولا نار، فإذا دفنتموني، فشنوا على التراب شناً، ثم أقيموا حول قبري قدر ما تنحر جزور، ويقسم لحمها، حتى أستأنس بكم، وأنظر ما أراجع به رسل ربي ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:32","bookId":"riyad","type":"hadith","num":32,"kitab":"كتاب الأدب","isnad":"فمنها حديث زيد بن أرقم رضي الله عنه -الذي سبق في باب إكرام أهل بيت رسول الله صلى الله عليه وسلم -قال‏:‏ قام رسول الله صلى الله عليه وسلم فينا خطيباً، فحمد الله، وأثنى عليه، ووعظ وذكر، ثم قال‏:‏ “أما بعد”ألا أيها الناس إنما أنا بشر يوشك أن يأتي رسول الله ربي فأجيب، وأنا تارك فيكم ثقلين ‏:‏‏","matn":"\"‏ أولهما‏:‏ كتاب الله، فيه الهدى والنور، فخذو بكتاب الله، واستمسكوا به” فحث على كتاب الله، ورغب فيه، ثم قال‏:‏ “وأهل بيتي، أذكركم الله في أهل بيتي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ وقد سبق بطوله‏.‏"},{"id":"riyad:33","bookId":"riyad","type":"hadith","num":33,"kitab":"كتاب الأدب","isnad":"وعن أبي سليمان مالك بن الحويرث رضي الله عنه قال‏:‏ أتينا رسول الله صلى الله عليه وسلم ونحن شببه متقاربون، فأقمنا عنده عشرين ليلة، وكان رسول الله صلى الله عليه وسلم رحيماً رفيقاً، فظن أنّا قد اشتقنا أهلنا، فسألنا عمن تركنا من أهلنا، فأخبرناه، فقال‏:‏ “ارجعوا إلى أهليكم، فأقيموا فيهم، وعلموهم ومروهم ، وصلو صلاة كذا في حين كذا، وصلوا كذا في حين كذا، فإذا حضرت الصلاة فليؤذن لكم أحدكم، وليؤمكم أكبركم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏(‏‏(‏زاد البخاري في رواية له‏:‏ ‏","matn":"\"‏ وصلوا كما رأيتموني أصلي‏\"‏‏)‏‏)‏"},{"id":"riyad:34","bookId":"riyad","type":"hadith","num":34,"kitab":"كتاب الأدب","isnad":"وعن عمر بن الخطاب رضي الله عنه قال‏:‏ استأذنت النبي صلى الله عليه وسلم الله عليه وسلم في العمرة، فأذن ، وقال‏:‏‏","matn":"\"‏لا تنسانا يا أخي من دعائك‏\"‏ فقال كلمة ما يسرني أن لي بها الدنيا‏.‏ وفي رواية قال‏:‏ “أشركنا يا أخي في دعائك” ‏(‏‏(‏رواه أبوداود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:35","bookId":"riyad","type":"hadith","num":35,"kitab":"كتاب الأدب","isnad":"","matn":"وعن سالم بن عبد الله بن عمر أن عبد الله بن عمر رضي الله عنهما كان يقول للرجل إذا أراد سفراً‏:‏ ادن مني حتى أودعك كما كان رسول الله صلى الله عليه وسلم يودعنا، فيقول‏:‏ أستودع الله دينك، وأمانتك، وخواتيم عملك‏.‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:36","bookId":"riyad","type":"hadith","num":36,"kitab":"كتاب الأدب","isnad":"وعن عبد الله بن يزيد الخطمي الصحبي رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا أراد أن يودع الجيش قال‏:‏ ‏","matn":"\"‏أستودع الله دينكم، وأماناتكم،وخواتيم أعمالكم‏\"‏‏.‏ حديث صحيح، ‏(‏‏(‏رواه أبو داود وغيره بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:37","bookId":"riyad","type":"hadith","num":37,"kitab":"كتاب الأدب","isnad":"وعن أنس رضي الله عنه قال‏:‏ جاء رجل إلى النبي صلى الله عليه وسلمى الله عليه وسلم فقال يا رسول الله ، إني أريدُ سفراً، فزودني، فقال‏:‏ زودك الله التقوى‏","matn":"\"‏ قال‏:‏ زدني، فقال‏:‏ ‏\"‏وغفر ذنبك‏\"‏ ، قال‏:‏ زدني، قال‏:‏ “ويسر لك الخير حيثما كنت” ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن‏)‏‏)‏"},{"id":"riyad:38","bookId":"riyad","type":"hadith","num":38,"kitab":"كتاب الأدب","isnad":"-وعن جابر رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم يعلمنا الإستخارة في الأمور كلها كالسورة من القرآن ، يقول ‏:‏ إذا همّ أحدكم بالأمر، فليركع ركعتين من غير الفريضة، ثم ليقل، اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم؛ فإنك تقدر ولا أقدر وتعلم ولا أعلم، وأنت علام الغيوب‏.‏ اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري‏","matn":"\"‏ أو قال‏:‏ ‏\"‏عاجل أمري وآجله ، فاقدره لي ويسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري‏\"‏ أو قال‏:‏ ‏\"‏عاجل أمري وآجله، فاصرفه عني ، واصرفني عنه، واقدر لي الخير حيث كان، ثم ارضني به‏\"‏ قال‏:‏ ويسمي حاجته‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:39","bookId":"riyad","type":"hadith","num":39,"kitab":"كتاب الأدب","isnad":"","matn":"عن جابر رضي الله عنه ‏:‏ كان النبي صلى الله عليه وسلم الله عليه وسلم إذا كان يوم عيد خالف الطريق‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:40","bookId":"riyad","type":"hadith","num":40,"kitab":"كتاب الأدب","isnad":"","matn":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم كان يخرج من طريق الشجرة، ويدخل من طريق المعرس، وإذا دخل مكة دخل من الثنية العليا ويخرج من الثنية السفلى‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:41","bookId":"riyad","type":"hadith","num":41,"kitab":"كتاب الأدب","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يعجبه التيمن في شأنه كله‏:‏ في طهوره، وترجله، وتنعله‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:42","bookId":"riyad","type":"hadith","num":42,"kitab":"كتاب الأدب","isnad":"","matn":"وعنها قالت‏:‏ كانت يد رسول الله صلى الله عليه وسلم ، اليمنى لطهوره وطعامه، وكان اليسرى لخلائه وما كان من أذى‏.‏ حديث صحيح، ‏(‏‏(‏رواه أبو داود وغيره بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:43","bookId":"riyad","type":"hadith","num":43,"kitab":"كتاب الأدب","isnad":"وعن أم عطية رضي الله عنها أن النبي صلى الله عليه وسلمى الله عليه وسلم ، قال لهن في غسل ابنته زينب رضي الله عنها ‏:‏ ‏","matn":"\"‏ابدأن بميامنها ومواضع الوضوء منها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:44","bookId":"riyad","type":"hadith","num":44,"kitab":"كتاب الأدب","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “ إذا انتعل أحدكم فليبدأ باليمنى، وإذا نزع فليبدأ بالشمال‏.‏لتكن اليمنى أولهما تنعل، وآخرهما تنزع‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:45","bookId":"riyad","type":"hadith","num":45,"kitab":"كتاب الأدب","isnad":"","matn":"وعن حفصة رضي الله عنها أن رسول الله صلى الله عليه وسلم ، كان يجعل يمينه لطعامه وشرابه وثيابه، ويجعل يساره لما سوى ذلك‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وغيره‏)‏‏)‏‏.‏"},{"id":"riyad:46","bookId":"riyad","type":"hadith","num":46,"kitab":"كتاب الأدب","isnad":"","matn":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “ إذا لبستم،وإذا توضأتم، فابدؤا بأيمانكم” حديث صحيح، ‏(‏‏(‏رواه أبو داود والترمذي بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:47","bookId":"riyad","type":"hadith","num":47,"kitab":"كتاب الأدب","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم أتى منى‏:‏ فأتى الجمرة فرماها، ثم أتى منزله بمنى، ونحر، ثم قال للحلاق “خذ” وأشار إلى جانبه الأيمن، ثم الأيسر، ثم جعل يعطيه الناس‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏وفي رواية‏:‏ لما رمى الجمرة، ونحر نسكه وحلق‏:‏ ناول الحلاق شقه الأيمن فحلقه، ثم دعا أبا طلحة الأنصارى رضي الله عنه ، فأعطاه إياه،ثم ناوله الشق الأيسر فقال “احلق” فحلقه فأعطاه أبا طلحة فقال‏:‏ ‏","matn":"\"‏اقسمه بين الناس‏\"‏‏.‏"},{"id":"riyad:48","bookId":"riyad","type":"hadith","num":48,"kitab":"كتـــــاب أدب الطعام","isnad":"عن عمر بن أبى سلمة رضى الله عنهما قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏‏","matn":"\"‏سم الله وكل بيمينك، وكل مما يليك‏\"‏.‏ ((متفق عليه))"},{"id":"riyad:49","bookId":"riyad","type":"hadith","num":49,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن عائشة رضى الله عنها قالت ‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا أكل أحدكم فليذكر اسم الله تعالى، فإذا نسى أن يذكر اسم الله تعالى في أوله، فليقل، بسم الله أوله وآخره‏\"‏‏.‏ ((رواه أبو داود والترمذي))"},{"id":"riyad:50","bookId":"riyad","type":"hadith","num":50,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن جابر، رضى الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا دخل الرجل بيته، فذكر الله تعالى عند دخوله وعند طعامه، قال الشيطان لأصحابه‏:‏ لا مبيت لكم ولا عشاء، وإذا دخل ، فلم يذكر الله تعالى عند دخوله، قال الشيطان‏:‏ أدركتم المبيت؛ وإذا لم يذكر الله تعالى عند طعامه قال‏:‏ أدركتم المبيت والعشاء‏\"‏ ‏. ((رواه مسلم))"},{"id":"riyad:51","bookId":"riyad","type":"hadith","num":51,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن حذيفة رضى الله عنه قال‏:‏ كنا إذا حضرنا مع رسول الله صلى الله عليه وسلم طعاماً، لم نضع أيدينا حتى يبدأ رسول الله صلى الله عليه وسلم فيضع يده‏.‏ وإنا حضرنا معه مرةً طعاماً، فجاءت جارية كأنها تدفع، فذهبت لتضع يدها في الطعام، فأخذ رسول الله صلى الله عليه وسلم بيدها، ثم جاء أعرابي كأنما يدفع فأخذ بيده، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الشيطان يستحل الطعام أن لا يذكر اسم الله تعالى عليه، وإنه جاء بهذه الجارية ليستحل بها، فأخذت بيدها، فجاء بهذا الأعرابي ليستحل به، فأخذت بيده، والذي نفسي بيده إن يده في يدي مع يديهما‏\"‏ ثم ذكر اسم الله تعالى وأكل‏.‏ ‏‏((رواه مسلم))‏"},{"id":"riyad:52","bookId":"riyad","type":"hadith","num":52,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أمية بن مخشى الصحابي رضى الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم جالساً ، ورجل يأكل، فلم يسم الله حتى لم يبق من طعامه إلا لقمة، فلما رفعها إلى فيه، قال‏:‏ بسم الله أوله وآخره، فضحك النبي صلى الله عليه وسلم، ثم قال‏:‏‏","matn":"\"‏ما زال الشيطان يأكل معه، فلما ذكر اسم الله استقاء ما فيه بطنه‏\"‏ ‏.‏ ‏‏((رواه أبو داود والنسائي))"},{"id":"riyad:53","bookId":"riyad","type":"hadith","num":53,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن عائشة رضى الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يأكل طعاماً في ستة من أصحابه، فجاء أعرابى، فأكله بلقمتين‏.‏ فقال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أما إنه لو سمى لكفاكم‏\"‏‏.‏((رواه الترمذي))"},{"id":"riyad:54","bookId":"riyad","type":"hadith","num":54,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أبى أمامة رضى الله عنه أن النبي صلى الله عليه وسلم كان إذا رفع مائدته قال‏:‏ ‏","matn":"\"‏الحمد لله حمداً كثيراً طَيِّباً مباركاً فيه، غير مكفى ولامودع، ولا مستغنى عنه ربنا‏\"‏ ‏‏.‏(‏‏(‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:55","bookId":"riyad","type":"hadith","num":55,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن معاذ بن أنس رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من أكل طعاماً فقال‏:‏ الحمد الله الذي أطعمني هذا، ورزقنيه من غير حول منى ولا قوةٍ، غفر له ما تقدم من ذنبه‏\"‏ ‏‏.‏((رواه أبو داود والترمذي))"},{"id":"riyad:56","bookId":"riyad","type":"hadith","num":56,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أبى هريرة رضى الله عنه قال‏:‏ ‏","matn":"\"‏ما عاب رسول الله صلى الله عليه وسلم طعاماً قط، إن اشتهاه أكله، وإن كرهه تركه‏\"‏ ‏.‏ ((متفق عليه))"},{"id":"riyad:57","bookId":"riyad","type":"hadith","num":57,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن جابر رضى الله عنه أن النبي صلى الله عليه وسلم سأل أهله الأدم فقالوا‏:‏ ما عندنا إلا خل، فدعا به، فجعل يأكل ويقول‏:‏ ‏","matn":"\"‏نعم الأدم الخل، نعم الأدم الخل‏\"‏ ‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:58","bookId":"riyad","type":"hadith","num":58,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى هريرة رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا دعي أحدكم ، فليجب، فإن كان صائما فليصل، وإن كان مفطراً فليطعم‏\"‏ .‏‏‏((رواه مسلم))‏"},{"id":"riyad:59","bookId":"riyad","type":"hadith","num":59,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى مسعود البدرى رضى الله عنه قال‏:‏ دعا رجل النبي صلى الله عليه وسلم لطعام صنعه له خامس خمسة، فتبعهم رجل، فلما بلغ الباب، قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن هذا تبعنا؛ فإن شئت أن تأذن له، وإن شئت رجع‏\"‏ قال‏:‏ بل آذن له يا رسول الله ‏.‏((متفق عليه))"},{"id":"riyad:60","bookId":"riyad","type":"hadith","num":60,"kitab":"كتـــــاب أدب الطعام","isnad":"عن عمر بن أبى سلمة رضى الله عنهما قال‏:‏ كنت غلاماً في حجر رسول الله صلى الله عليه وسلم، وكانت يدي تطيش في الصحفة، فقال لي رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ يا غلام سم الله تعالى، وكل بيمينك،وكل مما يليك‏\"‏ .((متفق عليه))"},{"id":"riyad:61","bookId":"riyad","type":"hadith","num":61,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن سلمةَ بن الأَكْوَع أنَّ رَجُلاً أَكَلَ عِنْدَ رَسُولِ الله بِشِمَالِهِ ، فَقَالَ : « كُلْ بِيَمِينِكَ » قَالَ : لا أسْتَطِيعُ . قَالَ : « لا اسْتَطَعْتَ » ! مَا مَنَعَهُ إِلا الكِبْرُ ! فَمَا رَفَعَهَا إِلَى فِيهِ . ((رواه مسلم))"},{"id":"riyad:62","bookId":"riyad","type":"hadith","num":62,"kitab":"كتـــــاب أدب الطعام","isnad":"عن جبلة بن سحيم قال: أصابنا عام سنةٍ مع ابن الزبير، فرزقنا تمراً، وكان عبد الله بن عمر رضى الله عنهما يمر بنا ونحن نأكل، فيقول: لا تقارونوا، فإن النبى نهى عن الإقران، ثم يقول","matn":"\"إلا أن يستأذن الرجل أخاه\" ((متفق عليه))"},{"id":"riyad:63","bookId":"riyad","type":"hadith","num":63,"kitab":"كتـــــاب أدب الطعام","isnad":"عن وحشى بن حرب رضى الله عنه أن أصحاب رسول الله صلى الله عليه وسلم قالوا‏:‏ يا رسول الله ، إنا نأكل ولا نشبع قال‏:‏ ‏","matn":"\"‏فلعلكم تفترقون‏\"‏ قالوا‏:‏ نعم‏.‏ قال‏:‏ فاجتمعوا على طعامكم، واذكروا اسم الله ، يبارك لكم فيه‏\"‏ ((رواه أبو داود)) ‏‏‏"},{"id":"riyad:64","bookId":"riyad","type":"hadith","num":64,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن ابن عباس رضى الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏البركة تنزل وسط الطعام، فكلوا من حافتيه ولا تأكلوا من وسطه‏\"‏‏‏.((رواه أبو داود والترمذي))"},{"id":"riyad:65","bookId":"riyad","type":"hadith","num":65,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن عبد الله بن بشر رضى الله عنه قال‏:‏ كان للنبي صلى الله عليه وسلم قصعة يقال لها‏:‏ الغراء، يحملها أربعة رجال، فلما أضحوا وسجدوا الضحى أتى بتلك القصعة، يعنى وقد ثرد فيها، فالتقوا عليه ، فلما كثروا جثا رسول الله صلى الله عليه وسلم‏.‏فقال أعرابي ‏:‏ ما هذه الجلسة‏؟‏ قال رسول الله صلى الله عليه وسلم ‏:‏ إن الله جعلني عبداً كريماً، ولم يجعلني جباراً عنيداً، ثم قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏كلوا من حواليها، ودعوا ذروتها يبارك فيها‏\"‏ .‏((رواه أبو داود))"},{"id":"riyad:66","bookId":"riyad","type":"hadith","num":66,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى جحيفة وهب بن عبد الله رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ لا آكل متكئاً‏\"‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:67","bookId":"riyad","type":"hadith","num":67,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن أنس رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم جالساً مقعياً يأكل تمراً.‏ ‏‏((رواه مسلم))‏"},{"id":"riyad:68","bookId":"riyad","type":"hadith","num":68,"kitab":"كتـــــاب أدب الطعام","isnad":"عن ابن عباس رضى الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا أكل أحدكم طعاماً، فلا يمسح أصابعه حتى يلعقها أو يلعقها‏\"‏‏.‏ ‏((متفق عليه))"},{"id":"riyad:69","bookId":"riyad","type":"hadith","num":69,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن كعب بن مالك رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم يأكل بثلاث أصابع ، فإذا فرغ لعقها‏.‏‏‏((رواه مسلم))‏ ‏"},{"id":"riyad:70","bookId":"riyad","type":"hadith","num":70,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن جابر رضى الله عنه أن رسول الله صلى الله عليه وسلم أمر بلعق الأصابع والصحفة، وقال‏:‏ ‏","matn":"\"‏إنكم لا تدرون في أي طعامكم البركة‏\"‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:71","bookId":"riyad","type":"hadith","num":71,"kitab":"كتـــــاب أدب الطعام","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا وقعت لقمة أحدكم، فليأخذها فليمط ما كان بها من أذى وليأكلها، ولا يدعها للشيطان، ولا يمسح يده بالمنديل حتى يلعق أصابعه؛ فإنه لا يدرى في أي طعامه البركة‏\"‏ .‏‏((رواه مسلم))‏ ‏"},{"id":"riyad:72","bookId":"riyad","type":"hadith","num":72,"kitab":"كتـــــاب أدب الطعام","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الشيطان يحضر أحدكم عند كل شئ من شأنه، حتى يحضره عند طعامه؛ فإذا سقطت لقمة أحدكم فليأخذها فليمط ما كان بها من أذى، ثم ليأكلها ولا يدعها للشيطان، فإذا فرغ فليلعق أصابعه؛ فإنه لا يدرى في أي طعامه البركة‏\"‏‏‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:73","bookId":"riyad","type":"hadith","num":73,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أنس رضى الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا أكل طعاماً، لعق أصابعه الثلاث، وقال‏:‏‏","matn":"\"‏إذا سقطت لقمة أحدكم فليأخذها، وليمط عنها الأذى، وليأكلها،ولا يدعها للشيطان‏\"‏ وأمرنا أن نسلت القصعة وقال‏:‏ ‏\"‏إنكم لا تدرون في أي طعامكم البركة‏\"‏ ‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:74","bookId":"riyad","type":"hadith","num":74,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن سعيد بن الحارث أنه سأل جابراً رضى الله عنه عن الوضوء مما مست النار، فقال‏:‏ لا ، قد كنا زمن النبي صلى الله عليه وسلم لا نجد مثل ذلك الطعام إلا قليلاً، فإذا نحن وجدناه، لم يكن لنا مناديل إلا أكفنا وسواعدنا وأقدامنا، ثم نصلى ولا نتوضأ‏.‏ ‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:75","bookId":"riyad","type":"hadith","num":75,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى هريرة رضى الله عنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏طعام الاثنين كافي الثلاثة، وطعام الثلاثة كافي الأربعة‏","matn":"\"‏.‏ ((متفق عليه))"},{"id":"riyad:76","bookId":"riyad","type":"hadith","num":76,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن جابر رضى الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏طعام الواحد يكفى الاثنين، وطعام الاثنين يكفى الأربعة، وطعام الأربعة يكفى الثمانية‏\"‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:77","bookId":"riyad","type":"hadith","num":77,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"عن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم كان يتنفس في الشراب ثلاثاً‏.‏((متفق عليه))"},{"id":"riyad:78","bookId":"riyad","type":"hadith","num":78,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن ابن عباس رضى الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تشربوا واحداً كشرب البعير، ولكن اشربوا مثنى وثلاث، وسموا إذا أنتم شربتم،واحمدوا إذا أنتم رفعتم‏\"‏‏.‏((رواه الترمذي))"},{"id":"riyad:79","bookId":"riyad","type":"hadith","num":79,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن أبى قتادة رضى الله عنه أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء‏.‏‏((متفق عليه))"},{"id":"riyad:80","bookId":"riyad","type":"hadith","num":80,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم أتى بلبن قد شيب بماء، وعن يمينه أعرابي، وعن يساره أبو بكر رضى الله عنه ، فشرب، ثم أعطى الأعرابي وقال‏:‏ ‏","matn":"\"‏الأيمن فالأيمن‏\"‏.((متفق عليه))"},{"id":"riyad:81","bookId":"riyad","type":"hadith","num":81,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن سهل بن سعد رضى الله عنه أن رسول الله صلى الله عليه وسلم أتى بشراب، فشرب منه وعن يمينه غلام، وعن يساره أشياخ، فقال للغلام‏:‏ ‏","matn":"\"‏أتأذن لي أن أعطى هؤلاء‏.‏‏؟‏‏\"‏ فقال الغلام‏:‏ لا والله ، لا أوثر بنصيبي منك أحدا، فتله رسول الله صلى الله عليه وسلم في يده‏.‏((متفق عليه)) ‏"},{"id":"riyad:82","bookId":"riyad","type":"hadith","num":82,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"عن أبى سعيد الخدرى رضى الله عنه قال ‏:‏ نهى رسول الله عن اختناث الأسقية ‏:‏ يعنى‏:‏ أن تكسر أفواهها، ويشرب منها‏.‏((متفق عليه))"},{"id":"riyad:83","bookId":"riyad","type":"hadith","num":83,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن أبى هريرة رضى الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن يشرب من في السقاء أو القربة.‏((متفق عليه))"},{"id":"riyad:84","bookId":"riyad","type":"hadith","num":84,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن أم ثابت كبشة بنت ثابت أخت حسان بن ثابت رضى الله عنه وعنها قالت‏:‏ دخل عليَّ رسول الله صلى الله عليه وسلم، فشرب من فيّ قربة معلقة قائماً، فقمت إلى فيها فقطعته‏ ‏((رواه الترمذي وقال: حديث حسن صحيح)). وإنما قطعتها لتحفظ موضع فم رَسُول اللَّهِ ﷺ وتتبرك به وتصونه عن الابتذال. وهذا الحديث محمول على بيان الجواز، والحديثان السابقان لبيان الأفضل والأكمل، والله أعلم."},{"id":"riyad:85","bookId":"riyad","type":"hadith","num":85,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى سعيد الخدرى رضى الله عنه أن النبي صلى الله عليه وسلم نهى عن النفخ في الشراب، فقال رجل ‏:‏ القذاة أراها في الإناء‏؟‏ فقالب‏:‏ ‏","matn":"\"‏أهرقها‏\"‏ قال‏:‏ إني لا أروى من نفس واحد‏؟‏ قال‏:‏ ‏\"‏فأبن القدح إذاً عن فيك‏\"‏.‏((رواه الترمذي))"},{"id":"riyad:86","bookId":"riyad","type":"hadith","num":86,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن ابن عباس رضى الله عنهما أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء، أو ينفخ فيه‏.‏((رواه الترمذي))"},{"id":"riyad:87","bookId":"riyad","type":"hadith","num":87,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن ابن عباس رضى الله عنهما قال‏:‏ سقيت النبي صلى الله عليه وسلم من زمزم، فشرب وهو قائم ‏.‏((متفق عليه))"},{"id":"riyad:88","bookId":"riyad","type":"hadith","num":88,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن النزال بن سبرة رضى الله عنه قال‏:‏ أتى علي رضى الله عنه باب الرحبة فشرب قائماً، وقال‏:‏ إني رأيت رسول الله صلى الله عليه وسلم فعل كما رأيتموني فعلت‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:89","bookId":"riyad","type":"hadith","num":89,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن ابن عمر رضى الله عنهما قال‏:‏كنا نأكل على عهد رسول الله صلى الله عليه وسلم ونحن نمشى ، ونشرب ونحن قيام‏.‏((رواه الترمذي))"},{"id":"riyad:90","bookId":"riyad","type":"hadith","num":90,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم يشرب قائماً أو قاعداً‏.‏ ((رواه الترمذي))"},{"id":"riyad:91","bookId":"riyad","type":"hadith","num":91,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن أنس رضى الله عنه عن النبي صلى الله عليه وسلم أنه نهى أن يشرب الرجل قائماً‏.‏ قال قتادة‏:‏ فقلنا لأنس‏:‏ فالأكل‏؟‏ قال‏:‏ ذلك أشر -أو أخبث- ‏.‏ وفى رواية له أن النبي صلى الله عليه وسلم زجر عن الشرب قائما.‏‏((رواه مسلم))‏ وفى رواية له أن النبي صلى الله عليه وسلم زجر عن الشرب قائماً‏.‏"},{"id":"riyad:92","bookId":"riyad","type":"hadith","num":92,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أبى هريرة رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ لا يشربن أحد منكم قائماً، فمن نسى فليستقئ‏","matn":"\"‏‏‏‏. ((رواه مسلم))‏"},{"id":"riyad:93","bookId":"riyad","type":"hadith","num":93,"kitab":"كتـــــاب أدب الطعام","isnad":"عن أبى قتادة رضى الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ ساقي القوم آخرهم شرباً‏\"‏. ((رواه الترمذي))"},{"id":"riyad:94","bookId":"riyad","type":"hadith","num":94,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"عن أنس رضى الله عنه قال‏:‏ حضرت الصلاة، فقام من كان قريب الدار إلى أهله، وبقى قوم فأتى رسول الله صلى الله عليه وسلم بمخضب من حجارة، فصغر المخضب أن يبسط فيه كفه، فتوضأ القوم كلهم‏.‏ قالوا‏:‏ كم كنتم‏؟‏ قال‏:‏ ثمانين وزيادة‏.‏((متفق عليه))، هذه رواية البخاري. وفي رواية مسلم:‏ أن النبي صلى الله عليه وسلم دعا بإناء من ماء، فأتى بقدح رحراح فيه شئ من ماء، فوضع أصابعه فيه‏.‏ قال أنس ‏:‏ فجعلت أنظر إلى الماء ينبع من بين أصابعه ‎، فحزرت من توضأ ما بين السبعين إلى الثمانين‏.‏"},{"id":"riyad:95","bookId":"riyad","type":"hadith","num":95,"kitab":"كتـــــاب أدب الطعام","isnad":"","matn":"وعن عبد الله بن زيد رضى الله عنه قال‏:‏ أتانا النبي صلى الله عليه وسلم، فأخرجنا له ماء في نور من صفر فتوضأ‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:96","bookId":"riyad","type":"hadith","num":96,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن جابر رضى الله عنه أن رسول الله صلى الله عليه وسلم دخل على رجل من الأنصار، ومعه صاحب له، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن كان عندك ماء بات هذه الليلة في سنة وإلا كرعنا‏\"‏‏‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:97","bookId":"riyad","type":"hadith","num":97,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن حذيفة رضى الله عنه قال‏:‏ إن النبي صلى الله عليه وسلم نهانا عن الحرير والديباج والشرب في آنية الذهب والفضة، وقال‏:‏ ‏","matn":"\"‏هي لهم في الدنيا، وهى لكم في الآخرة‏\"‏‏.((متفق عليه)) ‏"},{"id":"riyad:98","bookId":"riyad","type":"hadith","num":98,"kitab":"كتـــــاب أدب الطعام","isnad":"وعن أم سلمة رضى الله عنها أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الذي يشرب في آنية الفضة إنما يجرجر في بطنه نار جهنم‏\"‏‏.((متفق عليه)) ‏ وفى ‏:‏ ‏\"‏إن الذي يأكل أو يشرب في آنية الفضة والذهب‏\"‏ وفى رواية له‏:‏ ‏\"‏ من شرب في إناءٍ من ذهب أو فضة فإنما يجرجر في بطنه ناراً من جهنم‏.‏"},{"id":"riyad:99","bookId":"riyad","type":"hadith","num":99,"kitab":"كتــــاب اللباس","isnad":"وعن ابن عباس رضى الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ إلبسوا من ثيابكم البياض؛ فإنها من خير ثيابكم، وكفنوا فيها موتاكم‏","matn":"\"‏.‏((رواه أبو داود والترمذي))"},{"id":"riyad:100","bookId":"riyad","type":"hadith","num":100,"kitab":"كتــــاب اللباس","isnad":"وعن سمرة رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏إلبسوا البياض؛ فإنها أطهر وأطيب، وكفنوا فيها موتاكم‏\"‏.‏ ((رواه النسائي والحاكم))"},{"id":"riyad:101","bookId":"riyad","type":"hadith","num":101,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن البراء رضى الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم مربوعاً، ولقد رأيته في حلةٍ حمراء ما رأيت شيئاً قط أحسن منه.((متفق عليه)) ‏‏"},{"id":"riyad:102","bookId":"riyad","type":"hadith","num":102,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن أبى جحيفة وهب بن عبد الله رضى الله عنه قال‏:‏ رأيت النبي صلى الله عليه وسلم بمكة وهو بالأبطح في قبة له حمراء من آدم، فخرج بلال بوضوئه، فمن ناضح ونائل، فخرج النبي صلى الله عليه وسلم وعليه حلة حمراء، كأني أنظر إلى بياض ساقيه، فتوضأ وأذن بلال، فجعلت أتتبع فاه ههنا وههنا، يقول يمينا وشمالاً‏:‏ حي على الصلاة، حي على الفلاح، ثم ركزت له عنزة، فتقدم فصلى يمر بين يديه الكلب والحمار لا يمنع‏.((متفق عليه))"},{"id":"riyad:103","bookId":"riyad","type":"hadith","num":103,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن أبى رمثة رفاعة التيمى رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم وعليه ثوبان أخضران‏.‏((رواه أبو داود والترمذي))"},{"id":"riyad:104","bookId":"riyad","type":"hadith","num":104,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن جابر رضى الله عنه ، أن رسول الله صلى الله عليه وسلم دخل يوم فتح مكة وعليه عمامة سوداء‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:105","bookId":"riyad","type":"hadith","num":105,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن أبى سعيد عمرو بن حريث رضى الله عنه قال‏:‏ كأني انظر إلى رسول الله صلى الله عليه وسلم وعليه عمامة سوداء، قد أرخى طرفيها بين كتفيه‏.‏‏‏((رواه مسلم))‏ ‏ وفى رواية له ‏:‏ أن رسول الله صلى الله عليه وسلم خطب الناس، وعليه عمامة سوداء‏."},{"id":"riyad:106","bookId":"riyad","type":"hadith","num":106,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن عائشة رضى الله عنها قالت‏:‏ كفن رسول الله صلى الله عليه وسلم في ثلاثة أثواب بيض سحولية من كرسف، ليس فيها قميص ولا عمامة‏.((متفق عليه)) ‏ ‏"},{"id":"riyad:107","bookId":"riyad","type":"hadith","num":107,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعنها قالت‏:‏ خرج رسول الله صلى الله عليه وسلم ذات غداة، وعليه مرط مرحل من شعر أسود‏.‏‏‏((رواه مسلم))‏"},{"id":"riyad:108","bookId":"riyad","type":"hadith","num":108,"kitab":"كتــــاب اللباس","isnad":"وعن المغيرة بن شعبة رضى الله عنه قال‏:‏ كنت مع رسول الله صلى الله عليه وسلم ذات ليلة في مسير، فقال لي‏:‏ ‏","matn":"\"‏أمعك ماء‏\"‏ ‏؟‏ قلت‏:‏ نعم، فنزل عن راحلته فمشى حتى توارى في سواد الليل ثم جاء فأفرغت علي من الإداواة، فغسل وجهه وعليه جبة من صوف،فلم يستطع أن يخرج ذراعيه منها حتى أخرجهما من أسفل الجبة، فغسل ذراعيه ومسح برأسه، ثم أهويت لأنزع خفيه فقال‏:‏‏\"‏دعهما فإني أدخلتهما طاهرتين‏\"‏ ومسح عليهما‏.‏((متفق عليه)) وفى رواية‏:‏وعليه جبة شامية ضيقة الكمين‏.‏ وفى رواية‏:‏ أن هذه القضية كانت في غزوة تبوك‏.‏"},{"id":"riyad:109","bookId":"riyad","type":"hadith","num":109,"kitab":"كتــــاب اللباس","isnad":"","matn":"عن أم سلمة رضى الله عنها قالت‏:‏ كان أحب الثياب إلى رسول الله صلى الله عليه وسلم القميص‏.‏((رواه أبو داود والترمذي))"},{"id":"riyad:110","bookId":"riyad","type":"hadith","num":110,"kitab":"كتــــاب اللباس","isnad":"","matn":"عن أسماء بنت يزيد الأنصارية رضى الله عنها قالت‏:‏ كان كم قميص رسول الله صلى الله عليه وسلم إلى الرسغ.‏((رواه أبو داود والترمذي))"},{"id":"riyad:111","bookId":"riyad","type":"hadith","num":111,"kitab":"كتــــاب اللباس","isnad":"وعن ابن عمر رضى الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة‏\"‏ فقال أبو بكر‏:‏ يا رسول الله إن إزاري يسترخي إلى أن أتعاهده، فقال له رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏إنك لست ممن يفعله خيلاء‏\"‏‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:112","bookId":"riyad","type":"hadith","num":112,"kitab":"كتــــاب اللباس","isnad":"وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا ينظر الله يوم القيامة إلى من جر إزاره بطراً‏\"‏.‏((متفق عليه))"},{"id":"riyad:113","bookId":"riyad","type":"hadith","num":113,"kitab":"كتــــاب اللباس","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما أسفل من الكعبين من الإزار ففي النار‏\"‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:114","bookId":"riyad","type":"hadith","num":114,"kitab":"كتــــاب اللباس","isnad":"وعن أبى ذر رضى الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ثلاثة لا يكلمهم الله يوم القيامة، ولا ينظر إليهم ، ولا يزكيهم، ولهم عذاب أليم‏\"‏ قال‏:‏ فقرأها رسول الله صلى الله عليه وسلم ثلاث مرار‏.‏ قال أبو ذر ‏:‏ خابوا وخسروا ‍ من هم يا رسول الله ‏؟‏ قال‏:‏ ‏\"‏المسبل، والمنان، والمنفق سلعته بالحلف الكاذب‏\"‏‏‏‏.‏ وفى رواية له‏:‏ ‏\"‏المسبل إزاره‏\"‏‏‏.((رواه مسلم))‏"},{"id":"riyad:115","bookId":"riyad","type":"hadith","num":115,"kitab":"كتــــاب اللباس","isnad":"وعن ابن عمر رضى الله عنهما ، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الإسبال من الإزار، والقميص، والعمامة؛ من جر شيئاً خيلاء لم ينظر الله إليه يوم القيامة‏\"‏‏‏‏.‏((رواه أبو داود والنسائي))"},{"id":"riyad:116","bookId":"riyad","type":"hadith","num":116,"kitab":"كتــــاب اللباس","isnad":"وعن أبى جرى جابر بن سليم رضى الله عنه قال‏:‏ رأيت رجلا يصدر الناس عن رأيه ؛ لا يقول شيئاً إلا صدروا عنه؛ قلت‏:‏ من هذا قالوا‏:‏ رسول الله صلى الله عليه وسلم‏.‏قلت‏:‏ عليك السلام يا رسول الله - مرتين- قال‏:‏ ‏","matn":"\"‏لا تقل عليك السلام، عليك السلام تحية الموتى -قلت ‏:‏ السلام عليك‏\"‏ قال‏:‏ قلت‏:‏ أنت رسول الله ‏؟‏ قال‏:‏ ‏\"‏أنا رسول الله إذا أصابك ضر فدعوته كشفه عنك،وإذا أصابك عام سنة فدعوته أنبتها لك، وإذا كنت بأرض قفر أو فلاة، فضلت راحلتك، فدعوته ردها عليك‏\"‏ قال‏:‏ قلت‏:‏ اعهد إلى‏.‏ قال‏:‏ ‏\"‏لا تسبن أحداً‏\"‏ قال‏:‏ فما سببت بعده حراً، ولا عبداً، ولا بعيراً، ولا شاة ‏\"‏ولا تحقرن من المعروف شيئاً، وأن تكلم أخاك وأنت منبسط إليه وجهك؛ إن ذلك من المعروف‏.‏ وارفع إزارك إلى نصف الساق، فإن أبيت فإلى الكعبين، وإياك وإسبال الإزار فإنها من المخيلة وإن الله لا يحب المخيلة، وإن امرؤا شتمك وعيرك، بما يعلم فيك فلا تعيره بما تعلم فيه، فإنما وبال ذلك عليه‏\"‏.‏((رواه أبو داود والترمذي))"},{"id":"riyad:117","bookId":"riyad","type":"hadith","num":117,"kitab":"كتــــاب اللباس","isnad":"وعن أبى هريرة رضى الله عنه قال‏:‏ بينما رجل يصلى مسبل إزاره، قال له رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اذهب فتوضأ‏\"‏ فذهب فتوضأ، ثم جاء فقال ‏:‏‏\"‏ اذهب فتوضأ‏\"‏ فقال رجل يا رسول الله ما لك أمرته أن يتوضأ ثم سكت عنه‏؟‏ قال‏:‏ ‏\"‏إنه كان يصلى وهو مسبل إزاره، وإن الله لا يقبل صلاة رجل مسبل‏\"‏‏.‏((رواه أبو داود))"},{"id":"riyad:118","bookId":"riyad","type":"hadith","num":118,"kitab":"كتــــاب اللباس","isnad":"وعن قيس بن بشر التغلبى قال‏:‏ أخبرني أبى - وكان جليساً لأبى الدرداء-قال‏:‏ كان بدمشق رجل من أصحاب النبي صلى الله عليه وسلم يقال له سهل بن الحنظلية، وكان رجلاً متوحداً قلما يجالس الناس، إنما هو في صلاة ، فإذا فرغ فإنما هو تسبيح وتكبير حتى يأتى أهله، فمر بنا ونحن عند أبى الدرداء فقال أبو الدرداء‏:‏ كلمةً تنفعنا ولا تضرك‏.‏ قال‏:‏ بعث رسول الله صلى الله عليه وسلم سرية فقدمت ، فجاء رجل منهم فجلس في المجلس الذي يجلس فيه رسول الله صلى الله عليه وسلم ، فقال لرجل إلى جنبه‏:‏ لو رأيتنا حين التقينا نحن والعدو،فحمل فلان وطعن، فقال‏:‏ خذها منى،وأنا الغلام الغفارى، كيف ترى في قوله‏؟‏ قال‏:‏ ما أراه إلا قد بطل أجره‏.‏ فسمع بذلك آخر فقال‏:‏ ما أرى بذلك بأساً ، فتنازعا حتى سمع رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏سبحان الله‏؟‏لا بأس أن يؤجر ويحمد‏\"‏ فرأيت أبا الدرداء سر بذلك، وجعل يرفع رأسه إليه ويقول‏:‏ أنت سمعت ذلك من رسول الله صلى الله عليه وسلم ‍‍‍‍‍‍‏؟‏ فيقول‏:‏ نعم‏.‏ فما زال يعيد عليه حتى إني لأقول ليبركن على ركبتيه‏.‏ قال‏:‏ فمر بنا يوماً آخر، فقال له الدرداء‏:‏ كلمة تنفعنا ولا تضرك، قال‏:‏ قال لنا رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏المنفق على الخير كالباسط يده بالصدقة ولا يقبضها‏\"‏‏.‏ثم مر بنا يوماً آخر، فقال له أبو الدرداء‏:‏ كلمة تنفعنا ولا تضرك، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏:‏‏\"‏نعم الرجل خريم الأسدى ‍‏!‏ لولا طول جمته وإسبال إزاره ‏!‏‏:‏ فبلغ خريما، فجعل، فأخذ شفرة فقطع بها جمته إلى أذنيه ، ورفع إزاره إلى أنصاف ساقية‏.‏ ثم مر بنا يوماً آخر فقال له أبو الدرداء‏:‏ كلمةً تنفعنا ولا تضرك، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏إنكم قادمون على إخوانكم، فأصلحوا رحالكم، وأصلحوا لباسكم حتى تكونوا كأنكم شامة في الناس، فإن الله لا يحب الفحش ولا التفحش‏\"‏‏.‏((رواه أبو داود))"},{"id":"riyad:119","bookId":"riyad","type":"hadith","num":119,"kitab":"كتــــاب اللباس","isnad":"وعن أبى سعيد الخدرى رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إزارة المسلم إلى نصف الساق، ولا حرج -أو لا جناح- فيما بينه وبين الكعبين، فما كان أسفل من الكعبين فهو في النار، ومن جر إزاره بطرا لم ينظر الله إليه‏\"‏‏.((رواه أبو داود))"},{"id":"riyad:120","bookId":"riyad","type":"hadith","num":120,"kitab":"كتــــاب اللباس","isnad":"وعن ابن عمر رضى الله عنهما قال‏:‏ مررت على رسول الله صلى الله عليه وسلم وفى إزاري استرخاء، فقال‏:‏ ‏","matn":"\"‏يا عبد الله، ارفع إزارك‏\"‏ فرفعت ثم قال‏:‏ ‏\"‏زد‏\"‏، فزدت، فما زلت أتحراها بعد‏.‏ فقال بعض القوم‏:‏ إلى أين ‏؟‏ فقال‏:‏ إلى أنصاف الساقين‏\"‏‏.‏‏((رواه مسلم))‏"},{"id":"riyad:121","bookId":"riyad","type":"hadith","num":121,"kitab":"كتــــاب اللباس","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة‏","matn":"\"‏ فقالت أم سلمة‏:‏ فكيف تصنع النساء بذيولهن، قال‏:‏ ‏\"‏يرخين شبراً‏\"‏ قالت‏:‏ ِإذاً تنكشف أقدامهن‏.‏ قال‏:‏ ‏\"‏فيرخينه ذراعاً لا يزدن‏\"‏‏.((رواه أبو داود والترمذي))"},{"id":"riyad:122","bookId":"riyad","type":"hadith","num":122,"kitab":"كتــــاب اللباس","isnad":"وعن معاذ بن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من ترك اللباس تواضعاً لله، وهو يقدر عليه، دعاه الله يوم القيامة على رؤوس الخلائق حتى يخيره من أي حلل الإيمان شاء يلبسها‏\"‏.((رواه الترمذي)) ‏"},{"id":"riyad:123","bookId":"riyad","type":"hadith","num":123,"kitab":"كتــــاب اللباس","isnad":"عن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله يحب أن يرى أثر نعمته على عبده‏\"‏.‏((رواه الترمذي))"},{"id":"riyad:124","bookId":"riyad","type":"hadith","num":124,"kitab":"كتــــاب اللباس","isnad":"عن عمر بن الخطاب رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لا تلبسوا الحرير؛ فإن من لبسه في الدنيا لم يلبسه في الآخرة‏\"‏ ‏.‏((متفق عليه))"},{"id":"riyad:125","bookId":"riyad","type":"hadith","num":125,"kitab":"كتــــاب اللباس","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إنما يلبس الحرير من لا خلاق له‏\"‏.((متفق عليه)) ‏ وفى رواية للبخاري‏:‏ ‏\"‏من لا خلاق له في الآخرة‏\"‏‏"},{"id":"riyad:126","bookId":"riyad","type":"hadith","num":126,"kitab":"كتــــاب اللباس","isnad":"وعن أنس رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من لبس الحرير في الدنيا لم يلبسه في الآخرة‏\"‏.((متفق عليه)) ‏"},{"id":"riyad:127","bookId":"riyad","type":"hadith","num":127,"kitab":"كتــــاب اللباس","isnad":"وعن على رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم أخذ حريراً، فجعله في يمينه، وذهباً فجعله في شماله، ثم قال‏:‏ ‏","matn":"\"‏إن هذين حرام على ذكور أمتي‏\"‏‏.‏((رواه أبو داود))"},{"id":"riyad:128","bookId":"riyad","type":"hadith","num":128,"kitab":"كتــــاب اللباس","isnad":"وعن أبى موسى الأشعرى رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏حرم لباس الحرير والذهب على ذكور أمتي ،وأحل لإناثهم‏\"‏.‏((رواه الترمذي))"},{"id":"riyad:129","bookId":"riyad","type":"hadith","num":129,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن حذيفة رضى الله عنه قال‏:‏ نهانا النبي صلى الله عليه وسلم أن نشرب في آنية الذهب والفضة، وأن نأكل فيها، وعن لبس الحرير والديباج،وأن نجلس عليه‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏"},{"id":"riyad:130","bookId":"riyad","type":"hadith","num":130,"kitab":"كتــــاب اللباس","isnad":"","matn":"عن أنس رضى الله عنه قال‏:‏ رخص رسول الله ، صلى الله عليه وسلم، للزبير وعبد الرحمن بن عوف رضى الله عنهما في لبس الحرير لحكة بهما‏.‏((متفق عليه))"},{"id":"riyad:131","bookId":"riyad","type":"hadith","num":131,"kitab":"كتــــاب اللباس","isnad":"عن معاوية رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تركبوا الخز ولا النمار‏\"‏‏.‏ ((رواه أبو داود))"},{"id":"riyad:132","bookId":"riyad","type":"hadith","num":132,"kitab":"كتــــاب اللباس","isnad":"","matn":"وعن أبى المليح عن أبيه ، رضى الله عنه ، أن رسول الله صلى الله عليه وسلم نهى عن جلود السباع‏.((رواه أبو داود والترمذي والنسائي)) و في رواية للترمذي: نهى عن جلود السباع أن تفترش. ‏"},{"id":"riyad:133","bookId":"riyad","type":"hadith","num":133,"kitab":"كتــــاب اللباس","isnad":"عن أبى سعيد الخدرى رضى الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا استجد ثوباً سماه باسمه -عمامة، أو قميصاً، أو رداء -يقول‏:‏ ‏","matn":"\"‏ اللهم لك الحمد أنت كسوتنيه، أسألك خيره وخير ما صنع له، وأعوذ بك من شره وشر ما صنع له‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذى وقال‏:‏حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:134","bookId":"riyad","type":"hadith","num":134,"kitab":"كتاب آداب النوم","isnad":"عن البراء بن عازب رضى الله عنهما قال‏:‏ كان رسول الله صلى الله عليه وسلم ِإذا أوى إلى فراشه نام على شقه الأيمن، ثم قال‏:‏ ‏","matn":"\"‏ اللهم أسلمت نفسي إليك، ووجهت وجهي إليك، وفوضت أمري إليك، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجى منك إلا إليك‏.‏ آمنت بكتابك الذي أنزلت ‏.‏ ونبيك الذي أرسلت‏\"‏‏.‏ ‏((رواه البخاري بهذا اللفظ في كتاب الأدب من صحيحه‏)‏‏)‏"},{"id":"riyad:135","bookId":"riyad","type":"hadith","num":135,"kitab":"كتاب آداب النوم","isnad":"وعنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا أتيت مضجعك فتوضأ وضوءك للصلاة، ثم اضطجع على شقك الأيمن ، وقل ‏.‏‏.‏‏.‏ ‏\"‏ وذكر نحوهن وفيه‏:‏ ‏\"‏ واجعلهن آخر ما تقول‏\" (‏‏(‏متفق عليه‏)‏‏)‏.‏‏"},{"id":"riyad:136","bookId":"riyad","type":"hadith","num":136,"kitab":"كتاب آداب النوم","isnad":"","matn":"وعن عائشة رضى الله عنها قالت‏:‏ كان النبي صلى الله عليه وسلم يصلى من الليل إحدى عشرا ركعة، فإذا طلع الفجر صلى ركعتين خفيفتين ، ثم اضطجع على شقه الأيمن حتى يجئ المؤذن فيؤذنه (‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏‏"},{"id":"riyad:137","bookId":"riyad","type":"hadith","num":137,"kitab":"كتاب آداب النوم","isnad":"وعن حذيفة رضى الله عنه قال‏:‏كان النبي صلى الله عليه وسلم إذا أخذ مضجعه من الليل وضع يده تحت خده، ثم يقول‏:‏ ‏","matn":"\"‏اللهم باسمك أموت وأحيا‏\"‏ وإذا استيقظ قال‏:‏ ‏\"‏الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏.‏"},{"id":"riyad:138","bookId":"riyad","type":"hadith","num":138,"kitab":"كتاب آداب النوم","isnad":"وعن يعيش بن طخفة الغفارى رضى الله عنه قال‏:‏ قال أبى‏:‏ بينما أنا مضطجع في المسجد على بطني إذا رجل يحركني برجله فقال‏:‏ ‏","matn":"\"‏إن هذه ضجعة يبغضها الله‏\"‏ قال‏:‏ فنظرت ، فإذا رسول الله صلى الله عليه وسلم‏. ((رواه أبو داود بإسناد صحيح))‏.‏"},{"id":"riyad:139","bookId":"riyad","type":"hadith","num":139,"kitab":"كتاب آداب النوم","isnad":"وعن أبى هريرة رضى الله عنه ، عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من قعد مقعداً لم يذكر الله تعالى فيه،كانت عليه من الله تعالى ترة، ومن اضطجع مضجعاً لا يذكر الله تعالى فيه، كانت عليه من الله ترة‏\"‏ ((رواه أبو داود بإسناد حسن)).‏ \"الترة\" بكسر التاء المثناة من فوق، وهي: النقص، وقيل: التبعة."},{"id":"riyad:140","bookId":"riyad","type":"hadith","num":140,"kitab":"كتاب آداب النوم","isnad":"","matn":"عن عبد الله بن زيد رضى الله عنه أنه رأى رسول الله صلى الله عليه وسلم مستلقياً في المسجد، واضعاً إحدى رجليه على الأخرى‏. (‏‏(‏متفق عليه‏)‏‏)‏‏‏."},{"id":"riyad:141","bookId":"riyad","type":"hadith","num":141,"kitab":"كتاب آداب النوم","isnad":"","matn":"وعن جابر بن سمرة رضى الله عنه قال‏:‏ كان النبي صلى الله عليه وسلم إذا صلى الفجر تربع في مجلسه حتى تطلع الشمس حسناء‏.‏ حديث صحيح، رواه أبو داود وغيره بأسانيد صحيحة‏.‏"},{"id":"riyad:142","bookId":"riyad","type":"hadith","num":142,"kitab":"كتاب آداب النوم","isnad":"","matn":"وعن ابن عمر رضى الله عنهما قال‏:‏ رأيت رسول الله صلى الله عليه وسلم بفناء الكعبة محتبياً بيديه هكذا‏.‏ ووصف بيديه الاحتباء، وهو القرفصاء‏.‏ ‏‏(‏‏(‏رواه البخاري‏)‏‏)‏.‏"},{"id":"riyad:143","bookId":"riyad","type":"hadith","num":143,"kitab":"كتاب آداب النوم","isnad":"","matn":"وعن قيلة بنت مخرمة رضى الله عنها قالت‏:‏ رأيت النبي صلى الله عليه وسلم وهو قاعد القرفصاء، فلما رأيت رسول الله صلى الله عليه وسلم المتخشع في الجلسة أرعدت من الفرق‏.‏ ((رواه أبو داود والترمذي))‏.‏"},{"id":"riyad:144","bookId":"riyad","type":"hadith","num":144,"kitab":"كتاب آداب النوم","isnad":"وعن الشريد بن سويد رضى الله عنه قال‏:‏ مر بي رسول الله صلى الله عليه وسلم وأنا جالس هكذا، وقد وضعت يدي اليسرى خلف ظهري، واتكأت على إلية يدي فقال‏:‏ ‏","matn":"\"‏أتقعد قعدة المغضوب عليهم‏؟‏‏!‏‏\"‏ ((رواه أبو داود بإسناد صحيح)).‏"},{"id":"riyad:145","bookId":"riyad","type":"hadith","num":145,"kitab":"كتاب آداب النوم","isnad":"عن ابن عمر رضى الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا يقمن أحدكم من مجلسه ثم يجلس فيه، ولكن توسعوا وتفسحوا‏\"‏ وكان ابن عمر إذا قام له رجل من مجلسه لم يجلس فيه‏.‏ (‏‏(‏متفق عليه‏)‏‏)‏."},{"id":"riyad:146","bookId":"riyad","type":"hadith","num":146,"kitab":"كتاب آداب النوم","isnad":"وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا قام أحدكم من مجلس، ثم رجع إليه، فهو أحق به‏\"‏. ((رواه مسلم))."},{"id":"riyad:147","bookId":"riyad","type":"hadith","num":147,"kitab":"كتاب آداب النوم","isnad":"وعن جابر بن سمرة رضى الله عنهما قال‏:‏ كنا إذا أتينا النبي صلى الله عليه وسلم جلس أحدنا حيث ينتهي‏.‏ ((رواه أبو داود والترمذي، وقال","matn":"\"حديث حسن\")). ‏"},{"id":"riyad:148","bookId":"riyad","type":"hadith","num":148,"kitab":"كتاب آداب النوم","isnad":"وعن أبى عبد الله سلمان الفارسي رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا يغتسل رجل يوم الجمعة، ويتطهر ما استطاع من طهر، ويدهن من دهنه، أو يمس من طيب بيته، ثم يخرج فلا يفرق بين اثنين، ثم يصلى ما كتب له، ثم ينصت إذا تكلم الإمام، إلا غفر له ما بينه وبين الجمعة الأخرى‏\"‏ ((رواه البخاري)).‏"},{"id":"riyad:149","bookId":"riyad","type":"hadith","num":149,"kitab":"كتاب آداب النوم","isnad":"وعن عمرو بن شعيب عن أبيه عن جده رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يحل لرجل أن يفرق بين اثنين إلا بإذنهما‏\"‏ رواه أبو داود والترمذي وقال \"حديث حسن\"‏‏.‏ ‏‏وفى رواية لأبى داود‏:‏ ‏\"‏لا يجلس بين رجلين إلا بإذنهما‏\"‏‏‏‏.‏"},{"id":"riyad:150","bookId":"riyad","type":"hadith","num":150,"kitab":"كتاب آداب النوم","isnad":"وعن حذيفة بن اليمان رضى الله عنه أن رسول الله صلى الله عليه وسلم لعن من جلس وسط الحلقة‏‏.‏ ‏‏رواه أبو داود بإسناد صحيح. وروى الترمذى عن أبى مجلز‏:‏ أن رجلا قعد وسط الحلقة، فقال حذيفة‏:‏ ملعون على لسان محمد صلى الله عليه وسلم -من جلس وسط الحلقة‏. قال الترمذى","matn":"\"حديث حسن صحيح\".‏"},{"id":"riyad:151","bookId":"riyad","type":"hadith","num":151,"kitab":"كتاب آداب النوم","isnad":"وعن أبى سعيد الخدرى رضى الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏خير المجالس أوسعها‏\"‏‏.‏ ((رواه أبو داود بإسناد صحيح على شرط البخاري.‏))"},{"id":"riyad:152","bookId":"riyad","type":"hadith","num":152,"kitab":"كتاب آداب النوم","isnad":"وعن أبى هريرة رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏من جلس في مجلس، فكثر فيه لغطه فقال قبل أن يقوم من مجلسه ذلك‏:‏ سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك، إلا غفر له ما كان في مجلسه ذلك‏\"‏ ((‏‏رَوَاهُ التِّرمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ صحيح)).‏"},{"id":"riyad:153","bookId":"riyad","type":"hadith","num":153,"kitab":"كتاب آداب النوم","isnad":"وعن أبى برزة رضى الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم يقول بآخرة إذا أراد أن يقوم من المجلس‏:‏ ‏","matn":"\"‏سبحانك الله وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك‏\"‏ فقال رجل‏:‏ يا رسول الله، إنك لتقول قولاً ما كنت تقوله فيما مضى‏؟‏ قال‏:‏ ‏\"‏ذلك كفارة لما يكون في المجلس‏. ‏‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏‏(‏‏(‏ورواه الحاكم أبو عبيد الله في ‏ ‏المستدرك‏ ‏ من رواية عائشة رضى الله عنها وقال‏:‏ صحيح بإسناد‏)‏‏)‏‏‏"},{"id":"riyad:154","bookId":"riyad","type":"hadith","num":154,"kitab":"كتاب آداب النوم","isnad":"وعن ابن عمر رَضِيَ اللَّهُ عَنهُ قال: قلما كان رَسُول اللَّهِ ﷺ يقوم من مجلس حتى يدعو بهؤلاء الدعوات","matn":"\"اللهم اقسم لنا من خشيتك ما تحول به بيننا وبين معاصيك، ومن طاعتك ما تبلغنا به جنتك، ومن اليقين ما تهون به علينا مصائب الدنيا، اللهم متعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همنا، ولا مبلغ علمنا، ولا تسلط علينا من لا يرحمنا\" ((رَوَاهُ التِّرمِذِيُّ وَقَالَ حَدِيثٌ حَسَنٌ))."},{"id":"riyad:155","bookId":"riyad","type":"hadith","num":155,"kitab":"كتاب آداب النوم","isnad":"وعن أبي هريرة رَضِيَ اللَّهُ عَنهُ قال، قال رَسُول اللَّهِ ﷺ","matn":"\"ما من قوم يقومون من مجلس ولا يذكرون اللَّه تعالى فيه إلا قاموا عن مثل جيفة حمار وكان لهم حسرة\" ((رَوَاهُ أبُو دَاوُدَ بإسناد صحيح))."},{"id":"riyad:156","bookId":"riyad","type":"hadith","num":156,"kitab":"كتاب آداب النوم","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما جلس قوم مجلساً لم يذكروا الله تعالى فيه، ولم يصلوا على نبيهم فيه، إلا كان عليهم ترة؛ فإن شاء عذبهم، وإن شاء غفر لهم‏\"‏ ((رَوَاهُ التِّرمِذِيُّ وَقَالَ: \"حَدِيثٌ حَسَنٌ\"))‏.‏"},{"id":"riyad:157","bookId":"riyad","type":"hadith","num":157,"kitab":"كتاب آداب النوم","isnad":"وعنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قعد مقعداً لم يذكر الله تعالى فيه كانت عليه من الله ترة، ومن اضطجع مضجعاً لم يذكر الله فيه كانت عليه من الله ترة‏\"‏ ((رَوَاهُ أبُو دَاوُدَ))‏‏‏.‏ ‏وقد سبق قريباً، وشرحنا \"‏الترة‏\"‏ فيه‏."},{"id":"riyad:158","bookId":"riyad","type":"hadith","num":158,"kitab":"كتاب آداب النوم","isnad":"وعن أبى هريرة رضى الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لم يبق من النبوة إلا المبشرات‏\"‏ قالوا‏:‏ وما المبشرات‏؟‏ قال‏:‏ ‏\"‏الرؤيا الصالحة‏\"‏ (( رَوَاهُ البُخَارِيُّ))‏.‏"},{"id":"riyad:159","bookId":"riyad","type":"hadith","num":159,"kitab":"كتاب آداب النوم","isnad":"وعنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا اقترب الزمان لم تكد رؤيا المؤمن تكذب، ورؤيا المؤمن جزء من ستة وأربعين جزءاً من النبوة‏\"‏ ((مُتَّفَقٌ عَلَيهِ))‏.‏ ‏ ‏وفى رواية‏:‏ ‏\"‏أصدقكم رؤيا أصدقكم حديثاً‏\"‏‏.‏"},{"id":"riyad:160","bookId":"riyad","type":"hadith","num":160,"kitab":"كتاب آداب النوم","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من رآني في المنام فسيراني في اليقظة -أو كأنما رآني في اليقظة- لا يتمثل الشيطان بي‏\"‏ ((مُتَّفَقٌ عَلَيهِ)).‏"},{"id":"riyad:161","bookId":"riyad","type":"hadith","num":161,"kitab":"كتاب آداب النوم","isnad":"وعن أبى سعيد الخدرى رضى الله عنه انه سمع النبي صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏إذا رأى أحدكم رؤيا يحبها، فإنما هي من الله تعالى، فليحمد الله عليها، وليحدث بها -وفى رواية، فلا يحدث بها إلا من يحب- وإذا رأى غير ذلك مما يكره، فإنما هي من الشيطان، فليستعذ من شرها، ولا يذكرها لأحد، فإنها لا تضره‏\"‏ (( مُتَّفَقٌ عَلَيهِ))."},{"id":"riyad:162","bookId":"riyad","type":"hadith","num":162,"kitab":"كتاب آداب النوم","isnad":"وعن أبى قتادة رضى الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏الرؤيا الصالحة -وفى رواية‏:‏ الرؤيا الحسنة- من الله، والحلم من الشيطان، فمن رأى شيئاً يكره فلينفث عن شماله ثلاثاً، وليتعوذ من الشيطان فإنها لا تضره‏\"‏ (( مُتَّفَقٌ عَلَيهِ)). ‏النفث‏ ‏ نفخ لطيف لا ريق معه‏.‏"},{"id":"riyad:163","bookId":"riyad","type":"hadith","num":163,"kitab":"كتاب آداب النوم","isnad":"وعن جابر رضى الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا رأى أحدكم الرؤيا يكرهها، فليبصق عن يساره ثلاثاً، وليستعذ بالله من الشيطان ثلاثاً، وليتحول عن جنبه الذي كان عليه‏\"‏ ((رَوَاهُ مُسلِمٌ))."},{"id":"riyad:164","bookId":"riyad","type":"hadith","num":164,"kitab":"كتاب آداب النوم","isnad":"وعن أبى الأسقع واثلة بن الأسقع رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن من أعظم الفرى أن يدعى الرجل إلى غير أبيه، أو يرى عينيه ما لم تر، أو يقول على رسول الله صلى الله عليه وسلم ما لم يقل‏\"‏ ‏((رَوَاهُ البُخَارِيُّ))."},{"id":"riyad:165","bookId":"riyad","type":"hadith","num":165,"kitab":"كتاب السلام","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن رجلا سأل رسول الله صلى الله عليه وسلم‏:‏ أي الإسلام خير‏؟‏ قال‏:‏ ‏","matn":"\"‏تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:166","bookId":"riyad","type":"hadith","num":166,"kitab":"كتاب السلام","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ لما خلق الله تعالى آدم عليه السلام قال‏:‏ اذهب فسلم على أولئك -نفر من الملائكة جلوس- فاستمع ما يحيونك، فإنه تحيتك وتحية ذريتك‏.‏ فقال‏:‏ السلام عليكم فقالوا‏:‏ السلام عليك ورحمة الله، فزادوه‏:‏ ورحمة الله‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:167","bookId":"riyad","type":"hadith","num":167,"kitab":"كتاب السلام","isnad":"","matn":"وعن أبي عمارة البراء بن عازب رضي الله عنهما قال‏:‏ أمرنا رسول الله صلى الله عليه وسلم بسبع‏:‏ بعيادة المريض، واتباع الجنائز، وتشميت العاطس، ونصر الضعيف، وعون المظلوم، وإفشاء السلام وإبرار المقسم‏.‏ ‏(‏‏(‏متفق عليه هذا لفظ إحدى روايات البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:168","bookId":"riyad","type":"hadith","num":168,"kitab":"كتاب السلام","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تدخلوا الجنة حتى تؤمنوا ولا تؤمنوا حتى تحابوا أولا أدلكم على شيء إذا فعلتموه تحاببتم‏؟‏ أفشوا السلام بينكم‏\"‏ ‏(‏‏(‏رواه مسلم ‏)‏‏)‏‏.‏"},{"id":"riyad:169","bookId":"riyad","type":"hadith","num":169,"kitab":"كتاب السلام","isnad":"وعن أبي يوسف عبد الله بن سلام رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏يا أيها الناس أفشوا السلام، وأطعموا الطعام، وصلوا الأرحام وصلوا والناس نيام، تدخلوا الجنة بسلام‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:170","bookId":"riyad","type":"hadith","num":170,"kitab":"كتاب السلام","isnad":"","matn":"وعن الطفيل بن أبي بن كعب أنه كان يأتي عبد الله بن عمر، فيغدو معه إلى السوق، قال‏:‏ فإذا غدونا إلى السوق، لم يمر عبد الله على سقاط ولا صاحب بيعة، ولا مسكين، ولا أحد إلا سلم عليه، قال الطفيل، فجئت عبد الله بن عمر يومًا، فاستتبعني إلى السوق فقلت له‏:‏ ما تصنع بالسوق، وأنت لا تقف على البيع ولا تسأل عن السلع، ولا تسوم بها، ولا تجلس في مجالس السوق‏؟‏ وأقول‏:‏ اجلس بنا هاهنا نتحدث، فقال يا أبا بطن- وكان الطفيل ذا بطن- إنما نغدو من أجل السلام فنسلم على من لقيناه‏.‏ ‏(‏‏(‏رواه مالك في الموطأ بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:171","bookId":"riyad","type":"hadith","num":171,"kitab":"كتاب السلام","isnad":"عن عمران بن الحصين رضي الله عنهما قال‏:‏ جاء رجل إلى النبي صلى الله عليه وسلم فقال‏:‏ السلام عليكم، فرد عليه ثم جلس، فقال النبي صلى الله عليه وسلم‏:‏ “عشر” ثم جاء آخر، فقال‏:‏ السلام عليكم ورحمة الله، فرد عليه فجلس، فقال‏:‏ ‏","matn":"\"‏عشرون‏\"‏ ثم جاء آخر، فقال‏:‏ السلام عليكم ورحمة الله وبركاته، فرد عليه فجلس، فقال‏:‏ “ثلاثون” ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:172","bookId":"riyad","type":"hadith","num":172,"kitab":"كتاب السلام","isnad":"وعن عائشة رضي الله عنه قالت‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ “هذا جبريل يقرأ عليك السلام‏","matn":"\"‏ قالت‏:‏ قلت‏:‏ ‏\"‏وعليه السلام ورحمة الله وبركاته‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وهكذا وقع في بعض روايات الصحيحين‏:‏ \"وبركاته\" وفي بعضها بحذفها وزيادة الثقة مقبولة"},{"id":"riyad:173","bookId":"riyad","type":"hadith","num":173,"kitab":"كتاب السلام","isnad":"","matn":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، كان إذا تكلم بكلمة أعادها ثلاثًا حتى تفهم عنه، وإذا أتى على قوم فسلم عليهم سلم عليهم ثلاثًا‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏ وهذا محمول على ما إذا كان الجمع كثيرًا‏.‏"},{"id":"riyad:174","bookId":"riyad","type":"hadith","num":174,"kitab":"كتاب السلام","isnad":"","matn":"وعن المقداد رضي الله عنه في حديثه الطويل قال‏:‏ كنا نرفع للنبي صلى الله عليه وسلم نصيبه من اللبن، فيجيء من الليل، فيسلم تسليمًا لا يوقظ نائمًا، ويسمع اليقظان، فجاء النبي صلى الله عليه وسلم فسلم كما كان يُسلم‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:175","bookId":"riyad","type":"hadith","num":175,"kitab":"كتاب السلام","isnad":"","matn":"وعن أسماء بنت يزيد رضي الله عنه عنها أن رسول الله صلى الله عليه وسلم، مر في المسجد يومًا، وعصبة من النساء قعود، فألوى بيده بالتسليم‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏"},{"id":"riyad:176","bookId":"riyad","type":"hadith","num":176,"kitab":"كتاب السلام","isnad":"وعن أبي أمامة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن أولى الناس بالله من بدأهم بالسلام‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد، ورواه الترمذي بنحوه وقال‏:‏ حديث حسن، وقد ذكر بعده‏)‏‏)‏‏.‏"},{"id":"riyad:177","bookId":"riyad","type":"hadith","num":177,"kitab":"كتاب السلام","isnad":"وعن أبي جري الهجيمي رضي الله عنه قال‏:‏ أتيت رسول الله صلى الله عليه وسلم فقلت‏:‏ عليك السلام يا رسول الله قال‏:‏ ‏","matn":"\"‏لا تقل عليك السلام؛ فإن عليك السلام تحية الموتى‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏.‏ وقد سبق بطوله‏)‏‏)‏‏.‏"},{"id":"riyad:178","bookId":"riyad","type":"hadith","num":178,"kitab":"كتاب السلام","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يسلم الراكب على الماشي، والماشي على القاعد، والقليل على الكثير” ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي رواية للبخاري‏:‏ ‏\"‏والصغير على الكبير‏\"‏"},{"id":"riyad:179","bookId":"riyad","type":"hadith","num":179,"kitab":"كتاب السلام","isnad":"وعن أبي أمامة صُدي بن عجلان الباهلي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “إن أولى الناس بالله من بدأهم بالسلام‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏ ورواه الترمذي عن أبي أمامة رضي الله عنه‏:‏ قيل‏:‏ يا رسول الله، الرجلان يلتقيان، أيهما يبدأ بالسلام‏؟‏ قال‏:‏ ‏\"‏أولاهما بالله تعالى‏\"‏ قال الترمذي ‏:‏ حديث حسن‏.‏"},{"id":"riyad:180","bookId":"riyad","type":"hadith","num":180,"kitab":"كتاب السلام","isnad":"عن أبي هريرة رضي الله عنه في حديث المسيء صلاته أنه جاء فصلى، ثم جاء النبي صلى الله عليه وسلم، فسلم عليه، فرد عليه السلام، فقال‏:‏ ‏","matn":"\"‏ارجع فصلِ، فإنك لم تصلِ‏\"‏ فرجع فصلى، ثم جاء فسلم على النبي صلى الله عليه وسلم، حتى فعل ذلك ثلاث مرات” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:181","bookId":"riyad","type":"hadith","num":181,"kitab":"كتاب السلام","isnad":"وعنه عن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏إذا لقي أحدكم أخاه، فليسلم عليه، فإن حالت بينهما شجرة، أو جدار، أو حجر، ثم لقيه، فليسلم عليه‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:182","bookId":"riyad","type":"hadith","num":182,"kitab":"كتاب السلام","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يا بُني، إذا دخلت على أهلك، فسلم، يكن بركة عليك، وعلى أهل بيتك‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:183","bookId":"riyad","type":"hadith","num":183,"kitab":"كتاب السلام","isnad":"","matn":"عن أنس رضي الله عنه أنه مر على صبيان، فسلم عليهم، وقال‏:‏ كان رسول الله صلى الله عليه وسلم يفعله” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:184","bookId":"riyad","type":"hadith","num":184,"kitab":"كتاب السلام","isnad":"عن سهل بن سعد رضي الله عنه قال‏:‏ كانت فينا امرأة -وفي رواية‏:‏ كانت لنا عجوز- تأخذ من أصول السلق فتطرحه في القدر، وتكركر حبات من شعير، فإذا صلينا الجمعة، وانصرفنا، نُسلم عليها، فتقدمه إلينا‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:185","bookId":"riyad","type":"hadith","num":185,"kitab":"كتاب السلام","isnad":"","matn":"وعن أم هانئ فاختة بنت أبي طالب رضي الله عنه قالت‏:‏ أتيت النبي صلى الله عليه وسلم يوم الفتح وهو يغتسل، وفاطمة تستره بثوب، فسلمت، وذكرت الحديث” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:186","bookId":"riyad","type":"hadith","num":186,"kitab":"كتاب السلام","isnad":"","matn":"وعن أسماء بنت يزيد رضي الله عنه قالت‏:‏ مر علينا النبي صلى الله عليه وسلم في نسوة فسلم علينا‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن، وهذا لفظ أبي داود)) ولفظ الترمذي‏:‏ أن رسول الله صلى الله عليه وسلم مر في المسجد يومًا، وعصبة من النساء قعود، فألوى بيده بالتسليم‏‏‏.‏"},{"id":"riyad:187","bookId":"riyad","type":"hadith","num":187,"kitab":"كتاب السلام","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا تبدءوا اليهود ولا النصارى بالسلام، فإذا لقيتم أحدهم في طريق فاضطروه إلى أضيقه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:188","bookId":"riyad","type":"hadith","num":188,"kitab":"كتاب السلام","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا سلم عليكم أهل الكتاب فقولوا‏:‏ وعليكم” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:189","bookId":"riyad","type":"hadith","num":189,"kitab":"كتاب السلام","isnad":"وعن أسامة رضي الله عنه أن النبي صلى الله عليه وسلم مر على مجلس فيه أخلاط من المسلمين والمشركين -عبدة الأوثان واليهود- فسلم عليهم النبي صلى الله عليه وسلم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:190","bookId":"riyad","type":"hadith","num":190,"kitab":"كتاب السلام","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا انتهى أحدكم إلى المجلس فليسلم، فإذا أراد أن يقوم فليسلم، فليست الأولى بأحق من الآخرة‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏\"‏‏)‏‏)‏‏.‏"},{"id":"riyad:191","bookId":"riyad","type":"hadith","num":191,"kitab":"كتاب السلام","isnad":"وعن أبي موسي الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “ الاستئذان ثلاث، فإن أذن لك وإلا فارجع‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:192","bookId":"riyad","type":"hadith","num":192,"kitab":"كتاب السلام","isnad":"وعن سهل بن سعد قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إنما جعل الاستئذان من أجل البصر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:193","bookId":"riyad","type":"hadith","num":193,"kitab":"كتاب السلام","isnad":"وعن ربعي بن حراش قال‏:‏ حدثنا رجل من بني عامر استأذن علي النبي صلى الله عليه وسلم وهو في بيت، فقال‏:‏ أألج‏؟‏ فقال رسول الله صلى الله عليه وسلم لخادمه‏:‏ ‏","matn":"\"‏أخرج إلي هذا وعلمه الاستئذان، فقل له‏:‏ قل‏:‏ السلام عليكم، أأدخل‏؟‏” فسمعه الرجل فقال‏:‏ السلام عليكم، أأدخل‏؟‏ فأذن له النبي صلى الله عليه وسلم ، فدخل‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:194","bookId":"riyad","type":"hadith","num":194,"kitab":"كتاب السلام","isnad":"عن كلدة بن الحنبل رضي الله عنه قال‏:‏ أتيت النبي صلى الله عليه وسلم ، فدخلت عليه ولم أسلم، فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ارجع فقل السلام عليكم أأدخل‏؟‏‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:195","bookId":"riyad","type":"hadith","num":195,"kitab":"كتاب السلام","isnad":"عن أنس رضي الله عنه في حديثه المشهور في الإسراء قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ثم صعد بي جبريل إلي السماء الدنيا فاستفتح، فقيل‏:‏ من هذا‏؟‏ قال‏:‏ جبريل، قيل‏:‏ومن معك‏؟‏ قال‏:‏ محمد‏.‏ ثم صعد إلي السماء الثانية والثالثة والرابعة وسائرهن، ويقال في باب كل سماء‏:‏ من هذا‏؟‏ فيقول‏:‏ جبريل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:196","bookId":"riyad","type":"hadith","num":196,"kitab":"كتاب السلام","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ خرجت ليلة من الليالي، فإذا رسول الله صلى الله عليه وسلم يمشي وحده، فجعلت أمشي في ظل القمر، فالتفت فرآني فقال‏:‏ ‏","matn":"\"‏من هذا‏؟‏‏\"‏ فقلت‏:‏ أبو ذر، ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:197","bookId":"riyad","type":"hadith","num":197,"kitab":"كتاب السلام","isnad":"وعن أم هانيء رضي الله عنها قالت‏:‏ أتيت النبي صلى الله عليه وسلم وهو يغتسل وفاطمة تستره فقال ‏","matn":"\"‏ من هذه‏؟‏‏\"‏ فقلت‏:‏ أنا أم هانيء‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:198","bookId":"riyad","type":"hadith","num":198,"kitab":"كتاب السلام","isnad":"وعن جابر رضي الله عنه قال‏:‏ أتيت النبي صلى الله عليه وسلم فدققت الباب، فقال ‏","matn":"\"‏من ذا‏؟‏‏\"‏ فقلت‏:‏ أنا، فقال‏:‏ ‏\"‏أنا أنا‏؟‏‏!‏‏\"‏ كـأنه كرهها ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:199","bookId":"riyad","type":"hadith","num":199,"kitab":"كتاب السلام","isnad":"عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله يحب العطاس، ويكره التثاؤب، فإذا عطس أحدكم وحمد الله تعالي كان حقاً علي كل مسلم سمعه أن يقول له‏:‏يرحمك الله، وأما التثاؤب فإنما هو من الشيطان، فإذا تثاءب أحدكم فليرده ما استطاع، فإن أحدكم إذا تثاءب ضحك منه الشيطان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:200","bookId":"riyad","type":"hadith","num":200,"kitab":"كتاب السلام","isnad":"وعنه عن النبي صلى الله عليه وسلم الله قال‏:‏ ‏","matn":"\"‏إذا عطس أحدكم فليقل‏:‏ الحمد لله؛ وليقل له أخوه أو أصحابه‏:‏ يرحمك الله، فإذا قال له‏:‏ يرحمك الله، فليقل‏:‏ يهديكم الله ويصلح بالكم‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:201","bookId":"riyad","type":"hadith","num":201,"kitab":"كتاب السلام","isnad":"وعن أبي موسي رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا عطس أحدكم فحمد الله فشمتوه، فإن لم يحمد الله فلا تشمتوه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:202","bookId":"riyad","type":"hadith","num":202,"kitab":"كتاب السلام","isnad":"وعن أنس رضي الله عنه قال‏:‏ عطس رجلان عند النبي صلى الله عليه وسلم ، فشمت أحدهما ولم يشمت الآخر، فقال الذي لم يشمته‏:‏ عطس فلان فشمته، وعطست فلم تشمتني‏؟‏ فقال‏:‏ ‏","matn":"\"‏هذا حمد الله، وإنك لم تحمد الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:203","bookId":"riyad","type":"hadith","num":203,"kitab":"كتاب السلام","isnad":"","matn":"وعن أبي هريرة رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا عطس وضع يده أو ثوبه علي فيه، وخفض -أو غض- بها صوته‏.‏ شك الراوي‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:204","bookId":"riyad","type":"hadith","num":204,"kitab":"كتاب السلام","isnad":"وعن أبي موسي رضي الله عنه قال‏:‏ كان اليهود يتعاطسون عند رسول الله صلى الله عليه وسلم يرجون أن يقول لهم‏:‏ يرحمكم الله، فيقول‏:‏ ‏","matn":"\"‏‏\"‏يهديكم الله ويصلح بالكم‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:205","bookId":"riyad","type":"hadith","num":205,"kitab":"كتاب السلام","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا تثاءب أحدكم فليمسك بيده علي فيه، فإن الشيطان يدخل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:206","bookId":"riyad","type":"hadith","num":206,"kitab":"كتاب السلام","isnad":"عن أبي الخطاب قتادة قال‏:‏ قلت لأنس‏:‏ أكانت المصافحة في أصحاب رسول الله صلى الله عليه وسلم ‏؟‏ قال‏:‏ نعم‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:207","bookId":"riyad","type":"hadith","num":207,"kitab":"كتاب السلام","isnad":"وعن أنس رضي الله عنه قال‏:‏ لما جاء أهل اليمن قال رسول الله صلى الله عليه وسلم ‏:‏ “قد جاءكم أهل اليمن، وهم أول من جاء بالمصافحة‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:208","bookId":"riyad","type":"hadith","num":208,"kitab":"كتاب السلام","isnad":"وعن البراء رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما من مسلمين يلتقيان فيتصافحان إلا غفر لهما قبل أن يفترقا‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:209","bookId":"riyad","type":"hadith","num":209,"kitab":"كتاب السلام","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رجل‏:‏ يا رسول الله، الرجل منا يلقي أخاه أو صديقه، أينحني له قال‏:‏ ‏","matn":"\"‏لا‏\"‏ قال‏:‏ أفيلتزمه ويقبله‏؟‏فال‏:‏ ‏\"‏لا‏\"‏ قال‏:‏ فيأخذ بيده ويصافحه‏؟‏ قال‏:‏‏\"‏نعم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:210","bookId":"riyad","type":"hadith","num":210,"kitab":"كتاب السلام","isnad":"","matn":"وعن صفوان بن عسال رضي الله عنه قال‏:‏ قال يهودي لصاحبه‏:‏ اذهب بنا إلي هذا النبي صلى الله عليه وسلم فأتيا رسول الله صلى الله عليه وسلم ، فسألاه عن تسع آيات بينات؛ فذكر الحديث إلي قوله‏:‏ فقبلا يده ورجله، وقالا‏:‏ نشهد أنك نبي‏.‏ ‏(‏‏(‏رواه الترمذي وغيره بأسانيد صحيحة‏)‏‏)‏‏.‏"},{"id":"riyad:211","bookId":"riyad","type":"hadith","num":211,"kitab":"كتاب السلام","isnad":"وعن ابن عمر، رضي الله عنهما، قصة قال فيها‏:‏ فدنونا من النبي صلى الله عليه وسلم فقبلنا يده‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:212","bookId":"riyad","type":"hadith","num":212,"kitab":"كتاب السلام","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قدم زيد بن حارثة المدينة ورسول الله صلى الله عليه وسلم في بيتي، فأتاه فقرع الباب، فقام إليه النبي صلى الله عليه وسلم يجر ثوبه، فاعتنقه وقبله‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:213","bookId":"riyad","type":"hadith","num":213,"kitab":"كتاب السلام","isnad":"وعن أبي ذر، رضي الله عنه، قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تحقرن من المعروف شيئاً، ولو أن تلقي أخاك بوجه طلق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:214","bookId":"riyad","type":"hadith","num":214,"kitab":"كتاب السلام","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قبل النبي،صلى الله عليه وسلم الحسن بن على، رضي الله عنهما، فقال الأقرع بن حابس‏:‏ إن لي عشرة من الولد ما قبلت منهم أحداً‏.‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من لا يرحم لا يرحم‏!‏‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:215","bookId":"riyad","type":"hadith","num":215,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"","matn":"عن البراء بن عازب رضي الله عنهما قال‏:‏ أمرنا رسول الله صلى الله عليه وسلم بعيادة المريض، واتباع الجنازة، وتشميت العاطس، وإبرار المقسم، ونصر المظلوم، وإجابة الداعى، وإفشاء السلام” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:216","bookId":"riyad","type":"hadith","num":216,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏حق المسلم علي المسلم خمس‏:‏ رد السلام، وعيادة المريض، واتباع الجنائز، وإجابة الدعوة، وتشميت العاطس” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:217","bookId":"riyad","type":"hadith","num":217,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنه قالك قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏عن الله عزو جل يقول يوم القيامة‏:‏ ‏\"‏يا ابن آدم مرضت فلم تعدني‏!‏ قال‏:‏ يا رب كيف أعودك وأنت رب العالمين‏؟‏‏!‏ قال‏:‏ أما علمت أن عبدي فلاناً مرض فلم تعده‏؟‏ أما علمت أنك لو عدته لوجدتني عنده‏؟‏ يا ابن آدم استطعمتك فلم تطعمني‏!‏ قال‏:‏ يا رب كيف أطعمك وأنت رب العالمين‏؟‏‏!‏ قال‏:‏ أما علمت أنه استطعمك عبدي فلان فلم تطعمه، أما علمت أنك لو أطعمته لوجدت ذلك عندي‏؟‏ يا ابن آدم استسقيتك فلم تسقني‏!‏ قال‏:‏ يارب كيف أسقيك وأنت رب العالمين‏؟‏‏!‏ قال‏:‏ استسقاك عبدي فلان فلم تسقه‏!‏ أما علمت أنك لو سقيته لوجدت ذلك عندي‏؟‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:218","bookId":"riyad","type":"hadith","num":218,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي موسي الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ، “ عودوا المريض، وأطعموا الجائع، وفكوا العاني‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:219","bookId":"riyad","type":"hadith","num":219,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن ثوبان، رضي الله عنه، عن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏إن المسلم إذا عاد أخاه المسلم لم يزل في خرفة الجنة حتي يرجع‏\"‏ قيل‏:‏ يا رسول الله وما خرفة الجنة‏؟‏ قال‏:‏ ‏\"‏جناها” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:220","bookId":"riyad","type":"hadith","num":220,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن علي رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما من مسلم يعود مسلماً غدوة إلا صلى عليه سبعون ألف ملك حتي يمسي، وإن عاده عشية إلا صلى عليه سبعون ألف ملك حتي يصبح، وكان له خريف في الجنة” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:221","bookId":"riyad","type":"hadith","num":221,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أنس رضي الله عنه قال‏:‏ كان غلام يهودي يخدم النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم فمرض فأتاه النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم يعوده، فقعد عند رأسه فقال له‏:‏ ‏","matn":"\"‏أسلم‏\"‏ فنظر إلي أبيه وهو عنده‏؟‏ فقال‏:‏ أطع أبا القاسم، فأسلم، فخرج النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم وهو يقول‏:‏ “الحمد لله الذي أنقذه من النار” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:222","bookId":"riyad","type":"hadith","num":222,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم كان إذا اشتكي الأنسان الشيء منه، أو كانت به قرحة أو جرح، قال النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم بأصبعه هكذا، ووضع سفيان بن عيينه الراوي سبابته بالأرض ثم رفعها وقال‏:‏ ‏","matn":"\"‏بسم الله، تربة أرضنا، بريقة بعضنا، يشفي سقيمنا، بإذن ربنا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:223","bookId":"riyad","type":"hadith","num":223,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنها أن النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم كان يعود بعض أهله يمسح بيده اليمني ويقول‏:‏ ‏","matn":"\"‏اللهم رب الناس، أذهب البأس، واشف، أنت الشافي لا شفاء إلا شفاؤك، شفاءً لا يغادر سقماً” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:224","bookId":"riyad","type":"hadith","num":224,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"","matn":"وعن أنس، رضي الله عنه أنه قال لثابت رحمه الله‏:‏ ألا أرقيك برقية رسول الله صلى الله عليه وسلم ‏؟‏ قال‏:‏ بلى، قال‏:‏ اللهم رب الناس، مذهب البأس، اشف أنت الشافي، لا شافي إلا أنت، شفاءً لا يغادر سقماً” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:225","bookId":"riyad","type":"hadith","num":225,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن سعد بن أبي وقاص، رضي الله عنه قال‏:‏ عادني رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏اللهم اشف سعداً، اللهم اشف سعداً، اللهم اشف سعداً‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:226","bookId":"riyad","type":"hadith","num":226,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي عبد الله عثمان بن أبي العاص رضي الله عنه أنه شكي إلي رسول الله صلى الله عليه وسلم وجعاً يجده في جسده فقال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ضع يدك علي الذي تألم من جسدك وقل‏:‏ بسم الله -ثلاثاً- وقل سبع مرات‏:‏ أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:227","bookId":"riyad","type":"hadith","num":227,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن ابن عباس، رضي الله عنهما، عن النبي،صلى الله عليه وسلمى الله عليه وسلم صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏من عاد مريضاً لم يحضره أجله، فقال عنده سبع مرات‏:‏ أسأل الله العظيم رب العرش العظيم أن يشفيك‏:‏ إلا عافاه الله من ذلك المرض‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن، وقال الحاكم‏:‏ حديث صحيح علي شرط البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:228","bookId":"riyad","type":"hadith","num":228,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنه أن النبي صلى الله عليه وسلم الله عليه وسلم صلى الله عليه وسلم ، دخل علي أعرأبي يعوده وكان إذا دخل علي من يعوده قال‏:‏ ‏","matn":"\"‏لا بأس، طهور إن شاء الله‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:229","bookId":"riyad","type":"hadith","num":229,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبيسعيد الخدري رضي الله عنه أن جبريل أتي النبي،صلى الله عليه وسلمى الله عليه وسلم صلى الله عليه وسلم ، فقال‏:‏ يا محمد اشتكيت‏؟‏ قال‏:‏ ‏","matn":"\"‏نعم‏\"‏ قال‏:‏ بسم الله أرقيك ، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، بسم الله أرقيك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:230","bookId":"riyad","type":"hadith","num":230,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي سعيد الخدري وأبي هريرة، رضي الله عنهما، أنهما شهدا علي رسول الله ، صلى الله عليه وسلم ، أنه قال‏:‏ ‏","matn":"\"‏من قال‏:‏ لا إله إلا الله والله اكبر، صدقه ربه، فقال‏:‏ لا إله إلا أنا وأنا أكبر‏.‏ وإذا قال‏:‏ لا إله إلا الله وحده لا شريك له، قال‏:‏ يقول‏:‏ لا إله إلا أنا وحدي لا شريك لي‏.‏ وإذا قال‏:‏ لا إله إلا الله له الملك وله الحمد، قال‏:‏ لا إله إلا أنا لي الملك ولي الحمد‏.‏ وإذا قال‏:‏ لا إله إلا الله ولا حول ولا قوة إلا بالله، قال‏:‏ لا إله إلا أنا ولا حول ولا قوة إلا بي‏\"‏ وكان يقول‏:‏ ‏\"‏من قالها في مرضه ثم مات لم تطعمه النار‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏"},{"id":"riyad:231","bookId":"riyad","type":"hadith","num":231,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن ابن عباس، رضي الله عنهما، أن علي بن أبي طالب، رضي الله عنه خرج من عند رسول الله صلى الله عليه وسلم ، في وجعه الذي توفي فيه فقال الناس‏:‏ يا أبا الحسن كيف أصبح رسول الله صلى الله عليه وسلم ‏؟‏ قال‏:‏ أصبح بحمد الله بارئاً‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:232","bookId":"riyad","type":"hadith","num":232,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن عائشة رضي الله عنها قالت‏:‏ سمعت النبي صلى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهو مستند إلي يقول‏:‏ اللهم اغفر لي وارحمني وألحقني بالرفيق الأعلى‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:233","bookId":"riyad","type":"hadith","num":233,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنها قالت‏:‏ رأيت رسول الله صلى الله عليه وسلم وهو بالموت عنده قدح فيه ماء وهو يدخل يده في القدح، ثم يمسح وجهه بالماء، ثم يقول‏:‏ ‏","matn":"\"‏اللهم أعني علي غمرات الموت وسكرات الموت‏\"‏ ‏(‏‏(‏رواه الترمذي‏)‏‏)‏‏.‏"},{"id":"riyad:234","bookId":"riyad","type":"hadith","num":234,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن عمران بن الحصين رضي الله عنهما أن امراة من جهينة أتت النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهي حبلي من الزنا، فقالت‏:‏ يا رسول الله، أصبت حداً فأقمه علي ، فدعا رسول الله صلى الله عليه وسلم وليها، فقال‏:‏ ‏","matn":"\"‏أحسن إليها فإذا وضعت فأتني بها” ففعل، فأمر بها النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم ، فشدت عليها ثيابها، ثم أمر بها فرجمت، ثم صلى عليها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:235","bookId":"riyad","type":"hadith","num":235,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن بن مسعود رضي الله عنه قال‏:‏ دخلت علي النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم وهو يوعك، فمسسته، فقلت‏:‏ إنك لتوعك وعكاً شديداً فقال‏:‏ ‏","matn":"\"‏إني أوعك كما يوعك رجلان منكم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:236","bookId":"riyad","type":"hadith","num":236,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن سعد بن أبي وقاص رضي الله عنه قال‏:‏ جاءني رسول الله صلى الله عليه وسلم يعودني من وجع اشتد بي، فقلت‏:‏ بلغ بي ما ترى، وأنا ذو مال، ولايرثني إلا ابنتي، وذكر الحديث‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:237","bookId":"riyad","type":"hadith","num":237,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن القاسم بن محمد قال‏:‏ قالت عائشة رضي الله عنها‏:‏ وا رأساه فقال النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم ‏:‏ ‏","matn":"\"‏بل أنا وا رأساه‏\"‏ وذكر الحديث‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:238","bookId":"riyad","type":"hadith","num":238,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن معاذ رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من كان آخر كلامه لا إله إلا الله دخل الجنة‏\"‏ ‏(‏‏(‏رواه أبو داود والحاكم وقال‏:‏ صحيح الإسناد‏)‏‏)‏‏.‏"},{"id":"riyad:239","bookId":"riyad","type":"hadith","num":239,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “لقنوا موتاكم لا إله إلا الله‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:240","bookId":"riyad","type":"hadith","num":240,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أم سلمة رضي الله عنها قالت‏:‏ دخل رسول الله صلى الله عليه وسلم علي أبي سلمه وقد شق بصره فأغمضه، ثم قال‏:‏ ‏","matn":"\"‏إن الروح إذا قبض، تبعه البصر‏\"‏ فضج ناس من أهله، فقال‏:‏ ‏\"‏لا تدعو علي أنفسكم إلا بخير فإن الملائكة يؤمنون علي ما تقولون” ثم قال‏:‏ “اللهم اغفر لأبي سلمه، وارفع درجته في المهديين،واخلفه في عقبه في الغابرين، واغفر لنا وله يا رب العالمين، وافسح له في قبره، ونور له فيه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:241","bookId":"riyad","type":"hadith","num":241,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"-عن أم سلمة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا حضرتم المريض، أو الميت، فقولوا خيرا، فإن الملائكة يؤمنون علي ما تقولون، قالت‏:‏ فلما مات أبو سلمة، أتيت النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم فقلت‏:‏ يا رسول الله، إن أبا سلمة قد مات، قال‏:‏ “قولي‏:‏ اللهم اغفر لي وله، واعقبني منه عقبة حسنة‏\"‏ فقلت‏:‏ فأعقبني الله من هو خير لي منه‏:‏ محمداً صلى الله عليه وسلم ‏.‏‏\"‏ ((رواه مسلم هكَذا:\"إِذا حَضَرْتُمُ المَرِيضَ\" أَو\"الميِّت\"عَلَى الشَّكِّ، رواه أبو داود وغيره:\"الميِّت\"بلا شَكٍّ))."},{"id":"riyad:242","bookId":"riyad","type":"hadith","num":242,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنها قالت‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏‏","matn":"\"‏ما من عبد تصيبه مصيبه، فيقول إن لله وإنا إليه راجعون‏:‏ اللهم آجرني في مصيبتي، واخلف لي خيرا منها، إلا آجره الله تعالي في مصيبته واخلف له خيراً منها‏.‏ قالت‏:‏ فلما توفي أبو سلمة، قلت كما أمرني رسول الله صلى الله عليه وسلم ، فاخلف الله خيراص منه رسول الله صلى الله عليه وسلم “ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:243","bookId":"riyad","type":"hadith","num":243,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي موسي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ إذا مات ولد العبد، قال الله تعالي لملائكته‏:‏ قبضتم ولد عبدي، فيقولون‏:‏ نعم، فيقول‏:‏ قبضتم ثمرة فؤاده، فيقولون‏:‏ نعم‏.‏ فيقول‏:‏ ماذا قال عبدي، فيقولون‏:‏ حمدك واسترجع، فيقول الله تعالى‏:‏ ابنوا لعبدي بيتاً في الجنة، وسموه بيت الحمد‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:244","bookId":"riyad","type":"hadith","num":244,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ يقول الله تعالى‏:‏ ما لعبدي المؤمن عندي جزاء إذا قبضت صفيه من أهل الدنيا، ثم احتسبه إلا الجنه‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:245","bookId":"riyad","type":"hadith","num":245,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أسامة بن زيد رضي الله عنهما قال‏:‏ أرسلت إحدي بنات النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم إليه تدعوه وتخبره أن صبياً لها -أو ابناً- في الموت فقال للرسول‏:‏ ارجع إليها فأخبرها أن لله تعالي ما أخذ وله ما أعطى، وكل شئ عنده بأجل مسمى، فمرها، فلتصبر ولتحتسب” وذكر تمام الحديث‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:246","bookId":"riyad","type":"hadith","num":246,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم عاد سعد بن عباده ومعه عبد الرحمن بن عوف، وسعد بن أبي وقاص، وعبد الله بن مسعود رضي الله عنهم، فبكي رسول الله صلى الله عليه وسلم ، فلما رأي القوم بكاء رسول الله صلى الله عليه وسلم ، بكوا ؛ فقال‏:‏ “ألا تسمعون‏؟‏ إن الله لا يعذب بدمع العين، ولا بحزن القلب، ولكن بهذا أو يرحم‏","matn":"\"‏ وأشار إلا لسانه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:247","bookId":"riyad","type":"hadith","num":247,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أسامة بن زيد رضي الله عنهما أن رسول الله صلى الله عليه وسلم رفع إليه ابن ابنته وهو في الموت، ففاض عينا رسول الله صلى الله عليه وسلم فقال له سعد‏:‏ ما هذا يا رسول الله‏؟‏‏!‏ قال‏:‏ ‏","matn":"\"‏هذه رحمة جعلها الله تعالي في قلوب عباده الرحماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:248","bookId":"riyad","type":"hadith","num":248,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم دخل علي ابنه إبراهيم رضي الله عنه وهو يجود بنفسه فجعلت عينا رسول الله صلى الله عليه وسلم تذرفان ‏.‏ فقال له عبد الرحمن بن عوف‏:‏ وأنت يا رسول الله ‏؟‏‏!‏ فقال‏:‏ “يا ابن عوف إنها رحمة” ثم أتبعها بأخرى، فقال‏:‏”إن العين تدمع والقلب يحزن ، ولا نقول إلا ما يرضي ربنا، وإنا بفراقك يا إبراهيم لمحزونون‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه البخاري، وروي مسلم بعضه‏)‏‏)‏‏.‏ والأحاديث في الباب كثيرة في الصحيح مشهورة والله أعلم‏.‏"},{"id":"riyad:249","bookId":"riyad","type":"hadith","num":249,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي رافع أسلم مولي رسول الله صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من غسل ميتاً فكتم عليه ، غفر الله له أربعين مرة‏\"‏ ‏(‏‏(‏رواه الحاكم وقال صحيح علي شرط مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:250","bookId":"riyad","type":"hadith","num":250,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “من شهد الجنازة حتي يصلى عليها، فله قيراط ، ومن شهدها حتي تدفن، فله قيراطان‏","matn":"\"‏ قيل‏:‏ وما القيراطان‏؟‏ قال‏:‏ “مثل الجبلين العظيمين” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:251","bookId":"riyad","type":"hadith","num":251,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من اتبع جنازة مسلم إيماناً واحتساباً، وكان معه حتي يصلى عليها ويفرغ من دفنها، فإنه يرجع من الأجر بقيراطين كل قيراط مثل أحدٍ، ومن صلى عليها، ثم رجع قبل أن تدفن ، فإنه يرجع بقيراط” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:252","bookId":"riyad","type":"hadith","num":252,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أم عطية رضي الله عنها قالت‏:‏ نهينا عن اتباع الجنائز، ولم يعزم علينا‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏\"‏ومعناه ‏\"‏ ولم يشدد في النهي كما يشدد في المحرمات‏.‏"},{"id":"riyad:253","bookId":"riyad","type":"hadith","num":253,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن عائشة رضي الله عنها، قالت: قال رسول الله صلى الله عليه وسلم","matn":"“ما من ميت يصلي عليه أمة من المسلمين يبلغون مائة كلهم يشفعون له إلا شفعوا فيه“ ((رواه مسلم)."},{"id":"riyad:254","bookId":"riyad","type":"hadith","num":254,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن ابن عباس رَضِيَ اللَّهُ عَنهُما قال سمعت رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيهِ وَسَلَّم يقول","matn":"\"ما من رجل مسلم يموت فيقوم على جنازته أربعون رجلاً لا يشركون بالله شيئاً إلا شفعهم اللَّه فيه.\" ((رَوَاهُ مُسلِمٌ))."},{"id":"riyad:255","bookId":"riyad","type":"hadith","num":255,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"","matn":"وعن مرثد بن عبد الله اليزني قال‏:‏ كان مالك بن هبيرة رضي الله عنه إذا صلى علي الجنازة ، فتقال الناس عليها، جزأهم عليها ثلاثة أجزاء، ثم قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “من صلى عليه ثلاثة صفوف، فقد أوجب “ ‏(‏‏(‏رواه أبو دواد، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:256","bookId":"riyad","type":"hadith","num":256,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي عبد الرحمن بن عوف بن مالك رضي الله عنه قال‏:‏ صلى رسول الله صلى الله عليه وسلم علي جنازة، فحفظت من دعائه وهو يقول‏:‏ ‏","matn":"\"‏اللهم اغفر له، وارحمه، وعافه، واعف عنه، وأكرم نزله، ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا، كما نقيت الثوب الأبيض من الدنس، وأبدله داراً خيراً من داره، وأهلاً خيراً من أهله، وزوجاً خيراً من زوجه، وأدخله الجنة، وأعذه من عذاب القبر، ومن عذاب النار” حتي تمنين أن أكون ذلك الميت‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:257","bookId":"riyad","type":"hadith","num":257,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة وأبي قتادة، وأبي إبراهيم الأشهلي عن أبيه -وأبوه صحابي- رضي الله عنهم، عن النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم أنه صلى علي جنازة فقال‏:‏‏","matn":"\"‏اللهم اغفر لحينا وميتنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، وشاهدنا وغائبنا‏.‏ اللهم من أحييته منا، فأحيه علي الإسلام، ومن توفيته منا، فتوفه علي الإيمان؛ اللهم لا تحرمنا أجره، ولا تفتنا بعده‏\"‏ ‏‏(‏‏(‏رواه الترمذي‏)‏‏)‏ من رواية أبي هريرة وأبو هريرة صحيح والأشهلي، ورواه أبو داود من رواية أبي هريرة وأبي قتادة‏.‏ قال الحاكم‏:‏ حديث أبي هريرة صحيح علي شرط البخاري ومسلم، قال الترمذي‏:‏ قال البخاري‏:‏ أصح روايات هذا الحديث رواية الأشهلي‏.‏ قال البخاري‏:‏ وأصح شيء في الباب حديث عوف بن مالك‏.‏"},{"id":"riyad:258","bookId":"riyad","type":"hadith","num":258,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “إذا صليتم علي الميت، فأخلصوا له الدعاء‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:259","bookId":"riyad","type":"hadith","num":259,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"","matn":"وعنه عن النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم في الصلاة علي الجنازة‏:‏ “اللهم أنت ربها، وأنت خلقتها، وأنت هديتها للإسلام، وأنت قبضت روحها، وأنت أعلم بسرها وعلانيتها، جئناك شفعاء له، فاغفر له” ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:260","bookId":"riyad","type":"hadith","num":260,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن واثلة بن الأسقع رضي الله عنه قال‏:‏ صلى بنا رسول الله صلى الله عليه وسلم علي رجل من المسلمين، فسمعته يقول‏:‏ ‏","matn":"\"‏اللهم إن فلان ابن فلان في ذمتك وحبل جوارك، فقه فتنة القبر، وعذاب النار، وأنت أهل الوفاء والحمد؛ اللهم اغفر له وارحمه، إنك أنت الغفور الرحيم‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:261","bookId":"riyad","type":"hadith","num":261,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"","matn":"وعن عبد الله بن أبي أوفي رضي الله عنهما أنه كبر علي جنازة ابنة له أربع تكبيرات، فقام بعد الرابعة كقدر ما بين التكبيرتين يستغفر لها ويدعو، ثم قال‏:‏ كان رسول الله صلى الله عليه وسلم يصنع هكذا‏.‏ وفي رواية‏:‏ ‏ ‏كبر أربعاً، فمكث ساعة حتي ظننت أنه سيكبر خمساً، ثم سلم عن يمينه وعن شماله‏.‏ فلما انصرف قلنا له‏:‏ ما هذا‏؟‏ فقال‏:‏ إني لا أزيدكم علي ما رأيت رسول الله صلى الله عليه وسلم يصنع، أو‏:‏ هكذا صنع رسول الله صلى الله عليه وسلم ‏ ‏ ‏(‏‏(‏رواه الحاكم وقال‏:‏ حديث صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:262","bookId":"riyad","type":"hadith","num":262,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أسرعوا بالجنازة، فإن تك صالحة، فخير تقدمونها إليه، وإن تك سوي ذلك، فشر تضعونه عن رقابكم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وفي رواية لمسلم‏:‏ ‏\"‏فخير تقدمونها عليه‏)‏‏)‏‏.‏"},{"id":"riyad:263","bookId":"riyad","type":"hadith","num":263,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ كان النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا وضعت الجنازة، فاحتملها الرجال علي أعناقهم، فإن كانت صالحة، قال‏:‏ قدموني، وإن كانت غير صالحة، قالت لأهلها‏:‏ يا ويلها أين تذهبون بها‏؟‏ يسمع صوتها كل شيء إلا الأنسان، ولو سمع الأنسان لصعق” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:264","bookId":"riyad","type":"hadith","num":264,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم قال‏:‏ ‏","matn":"\"‏نفس المؤمن معلقة بدينه حتي يقضي عنه‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:265","bookId":"riyad","type":"hadith","num":265,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن حصين بن وحوح رضي الله عنه أن طلحة بن البراء رضي الله عنه مرض، فأتاه النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم يعوده فقال‏:‏ إني لا أري طلحة إلا قد حدث فيه الموت فآذوني به وعجلوا به، فإنه لا ينبغي لجيفة مسلم أن تحبس بين ظهراني أهله‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:266","bookId":"riyad","type":"hadith","num":266,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن علي رضي الله عنه قال‏:‏ كنا في جنازة في بقيع الغرقد فأتانا رسول الله صلى الله عليه وسلم فقعد، وقعدنا حوله ومعه مخصرة فنكس وجعل ينكت بمخصرته، ثم قال‏:‏ ما منكم من أحد إلا وقد كتب مقعده من النار ومقعده من الجنة” فقالوا‏:‏ يا رسول الله أفلا نتكل علي كتابنا‏؟‏ فقال‏:‏ ‏","matn":"\"‏اعملوا فكل ميسر لما خلق له‏\"‏ وذكر تمام الحديث‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:267","bookId":"riyad","type":"hadith","num":267,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أبي عمرو -وقيل‏:‏ أبو عبد الله، وقيل‏:‏ أبو ليلى- عثمان بن عفان رضي الله عنه قال‏:‏ كان النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم إذا فرغ من دفن الميت وقف عليه، وقال‏:‏ ‏","matn":"\"‏استغفروا لأخيكم وسلوا له التثبيت، فإنه الآن يسأل‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:268","bookId":"riyad","type":"hadith","num":268,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن عمرو بن العاص رضي الله عنه قال‏:‏ إذا دفنتمونى، فأقيموا حول قبري قدر ما تنحر جذور، ويقسم لحمها حت أستأنس بكم، وأعلم ماذا أراجع به رسل ربي‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏.‏ وقد سبق بطوله‏)‏‏)‏‏.‏ وقال الشافعي رحمه الله‏:‏ ويستحب أن يقرأ عنده شيء من القرآن، وإن ختموا القرآن عنده كان حسناً‏.‏"},{"id":"riyad:269","bookId":"riyad","type":"hadith","num":269,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن عائشة رضي الله عنها أن رجلاً قال للنبي صلى الله عليه وسلم ‏:‏ إن أمي افتلتت نفسها وأراها لو تكلمت، تصدقت، فهل لها أجر إن تصدقت عنها‏؟‏ قال‏:‏ ‏","matn":"\"‏نعم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:270","bookId":"riyad","type":"hadith","num":270,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “إذا مات الأنسان انقطع عمله إلا من ثلاث‏:‏ صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:271","bookId":"riyad","type":"hadith","num":271,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أنس رضي الله عنه قال‏:‏ مروا بجنازة، فأثنوا عليها خيراً، فقال النبي صلى الله عليه وسلم الله عليه وسلمى الله عليه وسلم الله عليه وسلم ‏:‏ ‏","matn":"\"‏وجبت”، ثم مروا بأخرى، فأثنوا عليها شراً، فقال النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم الله عليه وسلم ‏:‏ ‏\"‏وجبت‏\"‏ فقال عمر بن الخطاب رضي الله عنه‏:‏ ما وجبت‏؟‏ قال‏:‏ ‏\"‏هذا أثنيتم عليه خيراً، فوجبت له الجنة، وهذا أثنيتم عليه شراً فوجبت عليه النار، أنتم شهداء الله في الأرض” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:272","bookId":"riyad","type":"hadith","num":272,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي الأسود قال‏:‏ قدمت المدينة، فجلست إلي عمر بن الخطاب رضي الله عنه فمرت بهم جنازة، فأثني علي صاحبها خيراً فقال عمر‏:‏ وجبت، ثم مر بأخرى، فأثني علي صاحبها خيراً، فقال عمر‏:‏ وجبت، ثم مر بالثالثة، فأثني علي صاحبها شراً، فقال عمر‏:‏ وجبت‏:‏ قال أبو الأسود‏:‏ فقلت‏:‏ وما وجبت يا أمير المؤمنين‏؟‏ قال‏:‏ قلت كما قال النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم ‏:‏ “أيما مسلم شهد له أربعة بخير، أدخله الله الجنة‏:‏ فقلنا‏:‏ وثلاثة‏؟‏ قال‏:‏ “وثلاثة‏","matn":"\"‏ فقلنا‏:‏ واثنان‏؟‏ قال‏:‏ ‏\"‏واثنان‏\"‏ ثم لم نسأله عن الواحد‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:273","bookId":"riyad","type":"hadith","num":273,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما من مسلم يموت له ثلاثة لم يبلغوا الحنث إلا ادخله الله الجنة بفضل رحمته إياهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:274","bookId":"riyad","type":"hadith","num":274,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “لا يموت لأحد من المسلمين ثلاثة من الولد لا تمسه النار إلا تحلة القسم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:275","bookId":"riyad","type":"hadith","num":275,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ جاءت امرأة إلي رسول الله صلى الله عليه وسلم ، فقالت‏:‏ يا رسول الله ذهب الرجال بحديثك، فاجعل لنا مننفسك يوماً ناتيك فيه تعلمنا مما علمك الله، قال‏:‏ “اجتمعن يوم كذا وكذا” فاجتمعن، فأتاهن النبي صلى الله عليه وسلم فعلمهن مما علمه الله، ثم قال‏:‏ ‏","matn":"\"‏ما منكن من امرأة تقدم ثلاثة من الولد إلا كانوا لها حجاباً من النار‏\"‏ فقالت امرأة‏:‏ واثنين‏؟‏ فقال رسول الله صلى الله عليه وسلم “واثنين” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:276","bookId":"riyad","type":"hadith","num":276,"kitab":"كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه","isnad":"عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال لأصحابه -يعني لما وصلوا الحجر‏:‏ ديار ثمود-‏:‏ ‏","matn":"\"‏لا تدخلوا علي هؤلاء المعذبين إلا أن تكونوا باكين، فإن لم تكونوا باكين، فلا تدخلوا عليهم، لا يصيبكم ما أصابهم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي رواية قال‏:‏ لما مر رسول الله صلى الله عليه وسلم بالحجر قال‏:‏ ‏\"‏لا تدخلوا مساكن الذين ظلموا أنفسهم أن يصيبكم ما أصابهم إلا ان تكونوا باكين‏\"‏ ثم قنع رسول الله صلى الله عليه وسلم رأسه وأسرع السير حتي أجاز الوادي‏.‏"},{"id":"riyad:277","bookId":"riyad","type":"hadith","num":277,"kitab":"كتاب آداب السفر","isnad":"عن كعب بن مالك، رضي الله عنه أن النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم خرج في غزوة تبوك يوم الخميس، وكان يحب أن يخرج يوم الخميس‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية في “الصحيحين” لقلما كان رسول الله صلى الله عليه وسلم يخرج إلا في يوم الخميس‏.‏"},{"id":"riyad:278","bookId":"riyad","type":"hadith","num":278,"kitab":"كتاب آداب السفر","isnad":"وعن صخر بن وداعة الغامدي الصحابي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “اللهم بارك لأمتي في بكورها‏","matn":"\"‏ وكان إذا بعث سرية أو جيشاً بعثهم من أول النهار‏.‏ وكان صخر تاجراً فكان يبعث تجارته أول النهار، فأثري وكثر ماله” ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:279","bookId":"riyad","type":"hadith","num":279,"kitab":"كتاب آداب السفر","isnad":"عن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لو أن الناس يعلمون من الوحدة ما أعلم ما سار راكب بليل وحده” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:280","bookId":"riyad","type":"hadith","num":280,"kitab":"كتاب آداب السفر","isnad":"وعن عمر بن شعيب عن أبيه عن جده رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “الراكب شيطان والراكبان شيطانان والثلاثة ركب‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود والترمذي والنسائي بأسانيد صحيحة، وقال الترمذي‏:‏ حديث حسن‏)‏‏)‏"},{"id":"riyad:281","bookId":"riyad","type":"hadith","num":281,"kitab":"كتاب آداب السفر","isnad":"وعن أبي سعيد وأبي هريرة رضي الله عنهما قالا‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “إذا خرج ثلاثة في سفر فليأمروا أحدهم‏","matn":"\"‏ حديث حسن، ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:282","bookId":"riyad","type":"hadith","num":282,"kitab":"كتاب آداب السفر","isnad":"وعن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ “خير الصحابة أربعة وخير السرايا أربعمائة وخير الجيوش أربعة آلاف ولن يغلب اثنا عشر ألفاً عن قلة‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏"},{"id":"riyad:283","bookId":"riyad","type":"hadith","num":283,"kitab":"كتاب آداب السفر","isnad":"","matn":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “إذا سافرتم في الخصب فأعطوا الإبل حظها من الأرض وإذا سافرتم في الجدب فأسرعوا عليها السير وبادروا بها نقيها، وإذا عرستم، فاجتنبوا الطريق، فإن طرق الدواب، ومأوي الهوام بالليل” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ معنى‏:‏ “أعطوا الإبل حظها من الأرض” أي‏:‏ ارفقوا بها في السير لترعي في حال سيرها وقوله‏:‏ ‏ ‏نقيها‏ ‏ وهو بكسر النون، وإسكان القاف، وبالياء المثناة من تحت وهو‏:‏ المخ، معناه‏:‏ أسرعوا بها حتي تصلوا المقصد قبل أن يذهب مخها من ضنك السير‏.‏ و‏ ‏التعريس‏ ‏ النزول في الليل‏.‏"},{"id":"riyad:284","bookId":"riyad","type":"hadith","num":284,"kitab":"كتاب آداب السفر","isnad":"وعن أبي قتادة، رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم ، إذا كان في سفر، فعرس بليل اضطجع علي يمينه وإذا عرس قبيل الصبح نصب ذراعه، ووضع رأسه علي كفه‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ قال العلماء‏:‏ إنما نصب ذراعه لئلا يستغرق في النوم، فتفوته صلاة الصبح عن وقتها أو عن أول وقتها‏.‏"},{"id":"riyad:285","bookId":"riyad","type":"hadith","num":285,"kitab":"كتاب آداب السفر","isnad":"عن أنس، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏عليكم بالدلجة، فإن الأرض تطوي بالليل‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏ الدلجة‏ ‏ ‏:‏ السير في الليل‏"},{"id":"riyad:286","bookId":"riyad","type":"hadith","num":286,"kitab":"كتاب آداب السفر","isnad":"وعن أبي ثعلبة الخشني، رضي الله عنه، قال‏:‏ كان الناس إذا نزلوا منزلاً تفرقوا في الشعاب والأودية‏.‏ فقال رسول الله، صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن تفرقكم في هذه الشعاب والأودية إنما ذلكم من الشيطان‏!‏‏\"‏ فلم ينزلوا بعد ذلك منزلا إلا انضم بعضهم إلي بعض‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:287","bookId":"riyad","type":"hadith","num":287,"kitab":"كتاب آداب السفر","isnad":"وعن سهل بن عمرو -وقيل سهل بن الربيع بن عمرو الأنصاري المعروف بابن الحنظلية، وهو من أهل بيعة الرضوان، رضي الله عنه، قال‏:‏ مر رسول الله صلى الله عليه وسلم ببعير قد لحق ظهره بطنه، فقال‏:‏ ‏","matn":"\"‏اتقوا الله في هذه البهائهم المعجمة، فاركبوها صالحة وكلوها صالحة‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:288","bookId":"riyad","type":"hadith","num":288,"kitab":"كتاب آداب السفر","isnad":"وعن أبي جعفر عبد الله بن جعفر، رضي الله عنهما، قال‏:‏ أردفني رسول الله صلى الله عليه وسلم ، ذات يوم خلفه، وأسر إلي حديثاً لا أحدث به أحداً من الناس وكان أحب ما أستتر به رسول الله صلى الله عليه وسلم لحاجته هدف أو حائش نخل‏.‏ يعنى‏:‏ حائط نخل‏","matn":"\"‏ ‏(‏‏(‏رواه هكذا مختصراً‏)‏‏)‏‏.‏ وزاد فيه البرقاني بإسناد مسلم بعد قوله‏:‏ حائش نخل‏:‏ فدخل حائطاً لرجل من الأنصار، فإذا فيه جمل، فلما رأي رسول الله صلى الله عليه وسلم جرجر وذرفت عيناه، فأتاه النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم ، فمسح سراته -أى‏:‏ سنامه- وذفراه فسكن؛ فقال‏:‏ ‏ ‏من رب هذا الجمل، لمن هذا الجمل‏؟‏‏ ‏ فجاء فتى من الأنصار، فقال‏:‏ هذا لي يا رسول الله، فقال‏:‏ ‏ ‏أفلا تتقي الله في هذه البهيمة التي ملكك الله إياها‏؟‏ فإنه يشكو إلي أنك تجيعه وتدئبه‏ ‏ ‏(‏‏(‏رواه أبو داود كرواية البرقاني‏)‏‏)‏‏.‏ قوله‏:‏ ‏ ‏ذفراه‏ ‏ وهو بكسر الذال المعجمة وإسكان الفاء، وهو لفظ مفرد مؤنث‏.‏ قال أهل اللغة‏:‏ الذفري‏:‏ الموضع الذي يعرق من البعير خلف الأذن، وقوله‏:‏ ‏ ‏تذئبه‏ ‏ أي‏:‏ تتعبه‏.‏"},{"id":"riyad:289","bookId":"riyad","type":"hadith","num":289,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعن أنس، رضي الله عنه، قال‏:‏ كنا إذا نزلنا منزلا لا نسبح حتي نحل الرحال‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد علي شرط مسلم‏)‏‏)‏‏.‏ وقوله‏:‏ ‏ ‏لا نسبح‏ ‏‏:‏ أي لا نصلي النافلة، ومعناه‏:‏ أنا -مع حرصنا علي الصلاة- لا نقدمها على حط الرحال وإراحة الدواب"},{"id":"riyad:290","bookId":"riyad","type":"hadith","num":290,"kitab":"كتاب آداب السفر","isnad":"وعن أبي سعيد الخدري، رضي الله عنه، قال‏:‏ بينما نحن في سفر إذ جاء رجل علي راحلة له، فجعل يصرف بصره يميناً وشمالاً، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من كان معه فضل ظهر؛ فليعد به علي من لا ظهر له، ومن كان له فضل زاد فليعد به علي من لا زاد له‏\"‏ فذكر من أصناف المال ما ذكره، حتي رأينا‏:‏ أنه لا حق لأحد منا في فضل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:291","bookId":"riyad","type":"hadith","num":291,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعن جابر رضي الله عنه، عن رسول الله صلى الله عليه وسلم ، أنه أراد أن يغزو، فقال‏:‏ يا معشر المهاجرين والأنصار‏!‏ إن من إخوانكم قوماً، ليس لهم مال، ولا عشيرة، فليضم أحدكم إليه الرجلين، أو الثلاثة، فما لأحدنا من ظهر يحمله إلا كعقبة، يعني أحدهم‏.‏ قال‏:‏ فضممت إلي اثنين أو ثلاثة مالي إلا عقبة كعقبة أحدهم من جملي‏.‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏"},{"id":"riyad:292","bookId":"riyad","type":"hadith","num":292,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعنه قال‏:‏ كان رسول الله صلى الله عليه وسلم يتخلف في المسير، فيزجي الضعيف ويردف ويدعو له، ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:293","bookId":"riyad","type":"hadith","num":293,"kitab":"كتاب آداب السفر","isnad":"وعن ابن عمر، رضي الله عنهما، أن رسول الله صلى الله عليه وسلم كان إذا استوى علي بعيره خارجاً إلى سفر، كبر ثلاثاً، ثم قال‏:‏ ‏","matn":"\"‏سبحان الذي سخر لنا هذا وما كنا له مقرنين، وإنا إلي ربنا لمنقلبون‏.‏ اللهم إنا نسألك في سفرنا هذا البر والتقوى، ومن العمل ما ترضي‏.‏ اللهم هون علينا سفرنا هذا واطو عنا بعده‏.‏ اللهم أنت الصاحب في السفر والخليفة في الأهل‏.‏ اللهم إني أعوذ بك من وعثاء السفر وكآبة المنظر وسوء المنقلب في الأهل والمال والولد‏\"‏ وإذا رجع قالهن وزاد فيهن‏:‏ ‏\"‏آيبون تائبون عابدون لربنا حامدون‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ معنى ‏ ‏مقرنين‏ ‏‏:‏ مطيقين‏.‏ ‏ ‏والوعثاء‏ ‏ بفتح الواو وإسكان العين المهملة وبالثاء المثلثة وبالمد، وهي‏:‏ الشدة‏.‏ و‏ ‏الكآبة‏ ‏ بالمد، وهي‏:‏ تغير النفس من حزن ونحوه‏.‏ ‏ ‏والمنقلب‏ ‏‏:‏ المرجع‏.‏"},{"id":"riyad:294","bookId":"riyad","type":"hadith","num":294,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعن عبد الله بن سرجس، رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا سافر يتعوذ من وعثاء السفر، وكآبة المنقلب، والحور بعد الكون، ودعوة المظلوم‏.‏ وسوء المنظر في الأهل والمال‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ هكذا هو في صحيح مسلم‏:‏ الحور بعد الكون، بالنون، وكذا رواه الترمذي والنسائي‏.‏ قال الترمذي‏:‏ يروي ‏:‏الكور‏ ‏ بالراء، وكلاهما له وجه‏.‏ قال العلماء‏:‏ ومعناه بالنون والراء جميعاً‏:‏ الرجوع من الاستقامة أو الزيادة إلي النقص‏.‏ قالوا‏:‏ ورواية الراء مأخوذة من تكوير العمامة، وهو لفها وجمعها، ورواية النون، من الكون، مصدراً ‏ ‏كان يكون كوناً‏ ‏ إذا وجد واستقر‏.‏"},{"id":"riyad:295","bookId":"riyad","type":"hadith","num":295,"kitab":"كتاب آداب السفر","isnad":"وعن علي بن ربيعة قال‏:‏ شهدت علي بن أبي طالب رضي الله عنه أتي بدابة ليركبها، فلما وضع رجله في الركاب قال‏:‏ بسم الله، فلما استوي علي ظهرها قال‏:‏ الحمد لله الذي سخر لنا هذا، وما كنا له مقرنين، وإنا إلي ربنا لمنقلبون، ثم قال‏:‏ الحمد الله، ثلاث مرات، ثم قال‏:‏ الله اكبر ثلاث مرات، ثم قال‏:‏ سبحانك إني ظلمت نفسي فاغفر لي فإنه لا يغفر الذنوب إلا أنت، ثم ضحك، فقيل‏:‏ يا أمير المؤمنين من أي شئ ضحكت‏؟‏ قال‏:‏ رأيت النبي صلى الله عليه وسلم فعل كما فعلت، ثم ضحك، فقلت‏:‏ يا رسول الله من أي شئ ضحكت‏؟‏ قال‏:‏ “إن ربك سبحانه يعجب من عبده إذا قال‏:‏ اغفر لي ذنوبي، يعلم أنه لا يغفر الذنوب غيره‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏ ‏وفي بعض النسخ‏:‏ حديث صحيح‏.‏ وهذا لفظ أبي داود"},{"id":"riyad:296","bookId":"riyad","type":"hadith","num":296,"kitab":"كتاب آداب السفر","isnad":"","matn":"عن جابر رضي الله عنه قال‏:‏ كنا إذا صعدنا كبرنا، وإذا نزلنا سبحنا‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:297","bookId":"riyad","type":"hadith","num":297,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعن ابن عمر رضي الله عنهما قال‏:‏ كان النبي صلى الله عليه وسلم وجيوشه إذا علو الثنايا كبروا، وإذا هبطوا سبحوا‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:298","bookId":"riyad","type":"hadith","num":298,"kitab":"كتاب آداب السفر","isnad":"وعنه قال كان النبي صلى الله عليه وسلم إذا قفل من الحج أو العمرة كلما أوفى علي ثنيه أو فدفد كبر ثلاثاً، ثم قال‏:‏ ‏","matn":"\"‏ لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو علي كل شئ قدير آيبون تائبون عابدون ساجدون لربنا حامدون‏.‏ صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏ وفي رواية لمسلم‏:‏ إذا قفل من الجيوش أو السرايا أو الحج أو العمرة قوله‏:‏ ‏ ‏أوفى‏ ‏ أي‏:‏ ارتفع، وقوله‏:‏ ‏ ‏فدفد‏ ‏ هو بفتح الفاءين بينهما دال مهملة ساكنة وآخره دال أخرى وهو ‏:‏ الغليظ المرتفع من الأرض‏.‏"},{"id":"riyad:299","bookId":"riyad","type":"hadith","num":299,"kitab":"كتاب آداب السفر","isnad":"وعن أبي هريرة رضي الله عنه أن رجلاً قال‏:‏ يا رسول الله ، إني أريد أن أسافر فأوصني، قال‏:‏ ‏","matn":"\"‏عليك بتقوى الله، والتكبيرعلي كل شرف‏\"‏ فلما ولى الرجل قال‏:‏ ‏\"‏ اللهم اطو له البعد، وهون عليه السفر” ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:300","bookId":"riyad","type":"hadith","num":300,"kitab":"كتاب آداب السفر","isnad":"وعن أبي موسي الأشعري رضي الله عنه قال‏:‏ كنا مع النبي صلى الله عليه وسلم في سفر، فكنا إذا أشرفنا على واد هللنا وكبرنا وارتفعت أصواتنا، فقال النبي صلى الله عليه وسلم ‏:‏”يا أيها الناس أربعوا عل أنفسكم فإنكم لا تدعون أصم ولا غائباً‏.‏ إنه معكم ، إنه سميع قريب‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ أربعوا” بفتح الباء الموحدة أي ‏:‏ أرفقوا بأنفسكم‏."},{"id":"riyad:301","bookId":"riyad","type":"hadith","num":301,"kitab":"كتاب آداب السفر","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال ‏:‏ رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ ثلاث دعوات مستجابات لا شك فيهن‏:‏ دعوة المظلوم، ودعوة المسافر، ودعوة الوالد على ولده‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏ وليس في رواية أبي داود‏:‏ “على ولده”"},{"id":"riyad:302","bookId":"riyad","type":"hadith","num":302,"kitab":"كتاب آداب السفر","isnad":"عن أبي موسي الأشعري رضي الله عنه أن رسول الله كان إذا خاف قوماً قال‏:‏ ‏","matn":"\"‏ اللهم إنا نجعلك في نحورهم ، ونعوذ بك من شرورهم‏\"‏ ‏(‏‏(‏رواه أبو داود، والنسائي بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:303","bookId":"riyad","type":"hadith","num":303,"kitab":"كتاب آداب السفر","isnad":"-عن خولة بنت حكيم رضي الله عنها قالت‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من نزل منزلاً ثم قال‏:‏ أعوذ بكلمات الله التامات من شر ما خلق‏:‏ لم يضره شيء حتي يرتحل من منزله ذلك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:304","bookId":"riyad","type":"hadith","num":304,"kitab":"كتاب آداب السفر","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا سافر فأقبل الليل قال‏:‏ ‏","matn":"\"‏ يا أرض ، ربي وربك الله، أعوذ بالله من شرك وشر ما فيك ، وشر ما خلق فيك، وشر ما يدب عليك أعوذ بالله من شر أسد وأسود، ومن الحية والعقرب، ومن ساكن البلد، ومن والد وما ولد‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏ والأسود‏ ‏‏:‏ الشخص، قال الخطابي‏:‏ و‏ ‏ساكن البلد‏ ‏‏:‏ هم الجن الذين هم سكان الأرض ‏.‏ قال‏:‏ والبلد من الأرض‏:‏ ما كان مأوى الحيوان، وإن لم يكن فيه بناء ومنازل ‏.‏ قال‏:‏ ويحتمل أن المراد ‏ ‏ بالوالد‏ ‏ ‏:‏ إبليس ‏ ‏وماولد‏ ‏ ‏:‏ الشياطين"},{"id":"riyad:305","bookId":"riyad","type":"hadith","num":305,"kitab":"كتاب آداب السفر","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏السفر قطعة من العذاب، يمنع أحدكم طعامه، وشرابه ونومه، فإذا قضى أحدكم نهمته من سفره، فليعجل إلى أهله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏نهمته‏ ‏ ‏:‏ مقصوده"},{"id":"riyad:306","bookId":"riyad","type":"hadith","num":306,"kitab":"كتاب آداب السفر","isnad":"عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أطال أحدكم الغيبة فلا يطرقن أهله ليلاً‏\"‏‏ وفي رواية أن رسول الله صلى الله عليه وسلم نهى أن يطرق الرجل أهله ليلاً‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:307","bookId":"riyad","type":"hadith","num":307,"kitab":"كتاب آداب السفر","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم لا يطرق أهله ليلاً، وكان يأتيهم غدوة أو عشية‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏الطروق‏ ‏ ‏:‏المجيء في الليل‏.‏"},{"id":"riyad:308","bookId":"riyad","type":"hadith","num":308,"kitab":"كتاب آداب السفر","isnad":"وعن أنس رضي الله عنه قال‏:‏ أقبلنا مع النبي صلى الله عليه وسلم ، حتي إذ كنا بظهر المدينة، قال‏:‏ ‏","matn":"\"‏آيبون، تائبون ، عابدون ، لربنا حامدون‏\"‏ فلم يزل يقول ذلك حتي قدمنا المدينة، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:309","bookId":"riyad","type":"hadith","num":309,"kitab":"كتاب آداب السفر","isnad":"","matn":"عن كعب بن مالك رضي الله عنه أن رسول الله صلى الله عليه وسلم كان إذا قدم من سفر بدأ بالمسجد فركع فيه ركعتين ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:310","bookId":"riyad","type":"hadith","num":310,"kitab":"كتاب آداب السفر","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يحل لامرأة تؤمن بالله واليوم الآخر تسافر مسيرة يوم وليلة إلا مع ذي محرم عليها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:311","bookId":"riyad","type":"hadith","num":311,"kitab":"كتاب آداب السفر","isnad":"وعن ابن عباس رضي الله عنهما أنه سمع النبي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لا يخلون رجل بامرأة إلا ومعها ذو محرم، ولا تسافر المرأة إلا مع ذي محرم‏\"‏ فقال له رجل‏:‏ يا رسول الله إن امرأتي خرجت حاجّة، وإني اكتتبت في غزوة كذا وكذا‏؟‏ قال‏:‏ ‏\"‏انطلق فحج مع امرأتك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:312","bookId":"riyad","type":"hadith","num":312,"kitab":"كتاب الفضائل","isnad":"عن أبي أمامة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ اقرءوا القرآن فإنه يأتي يوم القيامة شفيعًا لأصحابه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:313","bookId":"riyad","type":"hadith","num":313,"kitab":"كتاب الفضائل","isnad":"وعن النواس بن سمعان رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏يؤتى يوم القيامة بالقرآن وأهله الذين كانو يعملون به في الدنيا تقدمه سورة البقرة وآل عمران تحاجان عن صاحبهما ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:314","bookId":"riyad","type":"hadith","num":314,"kitab":"كتاب الفضائل","isnad":"- وعن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏خيركم من تعلم القرآن وعلمه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:315","bookId":"riyad","type":"hadith","num":315,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏الذي يقرأ القرآن وهو ماهر به مع السفرة الكرام البررة، والذي يقرأ القرآن ويتتعتع فيه وهو عليه شاق له أجران‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:316","bookId":"riyad","type":"hadith","num":316,"kitab":"كتاب الفضائل","isnad":"وعن أبي موسى الأشعري رضي الله عنه‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏مثل المؤمن الذي يقرأ القرآن مثل الأترجة‏:‏ ريحها طيب، وطعمها طيب، ومثل المؤمن الذي لا يقرأ القرآن كمثل التمرة‏:‏ لا ريح لها وطعمها حلو، ومثل المنافق الذي يقرأ القرآن كمثل الريحانة‏:‏ ريحها طيب وطعمها مر، ومثل المنافق الذي لايقرأ القرآن كمثل الحنظلة‏:‏ ليس له ريح وطعمها مر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:317","bookId":"riyad","type":"hadith","num":317,"kitab":"كتاب الفضائل","isnad":"وعن عمر بن الخطاب رضي الله عنه‏:‏ أن النبي صلى الله عليه وسلم قال ‏:‏ ‏","matn":"\"‏ إن الله يرفع بهذا الكتاب أقوامًا ويضع به آخرين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:318","bookId":"riyad","type":"hadith","num":318,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما‏:‏ عن النبي صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ لا حسد إلا في اثنتين‏:‏ رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالا، فهو ينفقه آناء الليل وآناء النهارِ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (1) ‏.‏"},{"id":"riyad:319","bookId":"riyad","type":"hadith","num":319,"kitab":"كتاب الفضائل","isnad":"وعن البراء بن عازب رضي الله عنهما قال‏:‏ كان رجل يقرأ سورة الكهف، وعنده فرس مربوط بشطنين فتغشته سحابة فجعلت تدنو، وجعل فرسه ينفر منها‏.‏ فلما أصبح أتى النبي صلى الله عليه وسلم ، فذكر له ذلك فقال ‏:‏‏","matn":"\"‏ تلك السكينة تنزلت للقرآن‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:320","bookId":"riyad","type":"hadith","num":320,"kitab":"كتاب الفضائل","isnad":"وعن ابن مسعود رضي الله عنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من قرأ حرفًا من كتاب الله فله حسنة، والحسنة بعشر أمثالها لا أقول‏:‏ ألم حرف، ولكن ألف حرف، ولام حرف، وميم حرف‏\"‏‏(‏‏(‏راوه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:321","bookId":"riyad","type":"hadith","num":321,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنهما قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن الذي ليس في جوفه شيء من القرآن كالبيت الخرب‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:322","bookId":"riyad","type":"hadith","num":322,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهماعن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يقال لصاحب القرآن‏:‏ اقرأ وارتقِ ورتل كما كنت ترتل في الدنيا، فإن منزلتك عند آخر آية تقرؤها‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:323","bookId":"riyad","type":"hadith","num":323,"kitab":"كتاب الفضائل","isnad":"عن أبي موسى رضي الله عنه عن النبي صلى الله عليه وسلم قال ‏","matn":"\"‏تعاهدوا هذا القرآن فوالذي نفس محمد بيده لهو أشد تفلتًا من الإبل في عقلها‏\"‏‏.‏ ‏(‏‏(‏متفق عله‏)‏‏)‏‏.‏"},{"id":"riyad:324","bookId":"riyad","type":"hadith","num":324,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إنما مثل صاحب القرآن كمثل الإبل المعقلة، إن عاهد عليها أمسكها، وإن أطلقها، ذهبت‏\"‏ متفق عليه‏.‏"},{"id":"riyad:325","bookId":"riyad","type":"hadith","num":325,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال ‏:‏سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما أذن الله لشيء ما أذن لنبي حسن الصوت يتغنى بالقرآن يجهر به ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:326","bookId":"riyad","type":"hadith","num":326,"kitab":"كتاب الفضائل","isnad":"وعن أبي موسى الأشعري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال له ‏:‏‏","matn":"\"‏ لقد أتيت مزمارا من مزامير آل داود ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي روايه لمسلم ‏:‏ أن رسول الله صلى الله عليه وسلم قال له ‏:‏ ‏\"‏ لو رأيتني وأنا أستمع لقراءتك البارحة‏\"‏‏.‏"},{"id":"riyad:327","bookId":"riyad","type":"hadith","num":327,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن البراء بن عازب رضي الله عنهما قال ‏:‏سمعت النبي صلى الله عليه وسلم قرأ في العشاء بالتين والزيتون، فما سمعت أحدًا أحسن صوتا منه ‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:328","bookId":"riyad","type":"hadith","num":328,"kitab":"كتاب الفضائل","isnad":"وعن أبي لبابة بشير بن عبد المنذر رضي الله عنه قال، أ‏ن النبي صلى الله عليه وسلم قال‏:‏ من لم يتغنَ بالقرآن فليس منا ‏","matn":"\"‏‏.‏‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏ ‏.‏"},{"id":"riyad:329","bookId":"riyad","type":"hadith","num":329,"kitab":"كتاب الفضائل","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال لي النبي صلى الله عليه وسلم ‏:‏‏","matn":"\"‏اقرأ علي القرآن ‏\"‏، فقلت ‏:‏ يا رسول الله، أقرأ عليك وعليك أنزل ‏؟‏‏!‏ قال ‏:‏ ‏\"‏إني أحب أن أسمعه من غيري‏\"‏ فقرأت عليه سورة النساء حتى جئت إلى هذه الآية ‏:‏ ‏{‏فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا‏}‏ قال‏:‏ ‏\"‏حسبك الآن‏\"‏ فالتفت إليه، فإذا عيناه تذرفان ‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:330","bookId":"riyad","type":"hadith","num":330,"kitab":"كتاب الفضائل","isnad":"عن أبي سعيد رافع بن المعلى رضي الله عنه قال ‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ألا أعلمك أعظم سورة في القرآن قبل أن تخرج من المسجد‏؟‏ فأخذ بيدي ، فلما أردنا أن نخرج قلت ‏:‏ يا رسول الله إنك قلت لأعلمنك أعظم سورة في القرآن ‏؟‏ قال‏:‏ ‏\"‏الحمد لله رب العالمين هي السبع المثاني، والقرآن العظيم الذي أوتيته ‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:331","bookId":"riyad","type":"hadith","num":331,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في‏:‏‏{‏ قل هو الله أحد‏}‏‏:‏‏","matn":"\"‏ والذي نفسي بيده، إنها لتعدل ثلث القرآن‏\"‏‏.‏ وفي رواية‏:‏ أن رسول الله صلى الله عليه وسلم قال لأصحابه‏:‏‏\"‏ أيعجز أحدكم أن يقرأ بثلث القرآن في ليلة‏\"‏ فشق ذلك عليهم، وقالوا‏:‏ أينا يطيق ذلك يارسول الله‏:‏ فقال ‏:‏‏\"‏ ‏{‏قل هو الله أحد‏}‏ ثلث القرآن‏.‏‏\"‏‏.‏ ‏(‏‏(‏ رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:332","bookId":"riyad","type":"hadith","num":332,"kitab":"كتاب الفضائل","isnad":"وعنه أن رجل سمع رجلاً يقرأ‏:‏‏{‏قل هو الله احد‏}‏ يرددها فلما أصبح جاء إلى رسول الله صلى الله عليه وسلم، فذكر ذلك له وكان الرجل يتقالها فقال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ والذي نفسي بيده، إنها لتعدل ثلث القرآن‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري ‏)‏‏)‏‏.‏"},{"id":"riyad:333","bookId":"riyad","type":"hadith","num":333,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في‏:‏‏{‏ قل هو الله أحد‏}‏ ‏","matn":"\"‏إنها تعدل ثلث القرآن‏\"‏‏.‏‏(‏‏(‏ رواه مسلم ‏)‏‏)‏‏.‏"},{"id":"riyad:334","bookId":"riyad","type":"hadith","num":334,"kitab":"كتاب الفضائل","isnad":"وعن أنس رضي الله عنه أن رجلا قال‏:‏ يارسول الله إني أحب هذه السورة ‏","matn":"\"‏قل هو الله أحد‏\"‏‏:‏‏\"‏إن حبها أدخلك الجنة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن- رواه البخاري في صحيحه تعليقًا‏)‏‏)‏‏.‏"},{"id":"riyad:335","bookId":"riyad","type":"hadith","num":335,"kitab":"كتاب الفضائل","isnad":"وعن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ ألم ترَ آيات أنزلت هذه الليلة لم يرَ مثلهن قط ‏؟‏ قل أعوذ برب الفلق، وقل أعوذ برب الناس ‏\"‏‏.‏‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:336","bookId":"riyad","type":"hadith","num":336,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أبي سعيد الخدري رضي الله عنه قال ‏:‏ كان رسول الله صلى الله عليه وسلم يتعوذ من الجان، وعين الإنسان، حتى نزلت المعوذتان، فلما نزلتا، أخذ بهما وترك ما سواهما ‏.‏ (‏‏(‏رواه الترمذي وقال ‏:‏حديث حسن ‏)‏‏)‏‏.‏"},{"id":"riyad:337","bookId":"riyad","type":"hadith","num":337,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ من القرآن سورة ثلاثون آية شفعت لرجل حتى غفرت له ،وهي‏:‏ تبارك الذي بيده الملك ‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال ‏:‏‏\"‏ حديث حسن ، وفي رواية أبي داود‏:‏ ‏\"‏تشفع ‏\"‏‏)‏‏)‏‏.‏"},{"id":"riyad:338","bookId":"riyad","type":"hadith","num":338,"kitab":"كتاب الفضائل","isnad":"وعن أبي مسعود البدري رضي الله عنه عن النبي صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:339","bookId":"riyad","type":"hadith","num":339,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ لا تجعلوا بيوتكم مقابر، إن الشيطان ينفر من البيت الذي تقرأ فيه سورة البقرة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:340","bookId":"riyad","type":"hadith","num":340,"kitab":"كتاب الفضائل","isnad":"وعن أبي بن كعب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ يا أبا المنذر أتدري أي آية من كتاب الله معك أعظم ‏؟‏ قلت‏:‏ الله لا إله إلا هو الحي القيوم، فضرب في صدري وقال ‏:‏‏\"‏ ليهنك العلم أبا المنذر‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم ‏)‏‏)‏‏.‏"},{"id":"riyad:341","bookId":"riyad","type":"hadith","num":341,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ وكلني رسول الله صلى الله عليه وسلم بحفظ زكاة رمضان، فأتاني آتٍ، فجعل يحثو من الطعام، فأخذته فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم قال‏:‏ إني محتاج، وعلي عيال، وبي حاجة شديدة، فخليت عنه، فأصبحت، فقال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ يا أبا هريرة، ما فعل أسيرك البارحة‏؟‏‏\"‏ قلت‏:‏ يا رسول الله شكا حاجة وعيالا، فرحمته، فخليت سبيله‏.‏ فقال‏:‏ ‏\"‏ أما إنه قد كذبك وسيعود‏\"‏ فعرفت أنه سيعود لقول رسول الله صلى الله عليه وسلم فرصدته، فجاء يحثو من الطعام، فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم، قال‏:‏ دعني فإني محتاج، وعلي عيال لا أعود، فرحمته فخليت سبيله، فأصبحت فقال لي رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏يا أبا هريرة، ما فعل أسيرك البارحة‏؟‏‏\"‏ قلت‏:‏ يا رسول الله شكا حاجة وعيالا فرحمته، فخليت سبيله، فقال‏:‏ ‏\"‏إنه قد كذبك وسيعود‏\"‏ فرصدته الثالثة‏.‏ فجاء يحثو من الطعام، فأخذته، فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم، وهذا آخر ثلاث أنك تزعم أنك لا تعود، ثم تعود‏!‏ فقال‏:‏ دعني فإني أعلمك كلمات ينفعك الله بها، قلت‏:‏ ما هن‏؟‏ قال‏:‏ إذا أويت إلى فراشك فاقرأ آية الكرسي، فإنه لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح، فخليت سبيله فأصبحت، فقال لي رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ما فعل أسيرك البارحة‏؟‏ ‏\"‏ قلت‏:‏ يا رسول الله زعم أنه يعلمني كلمات ينفعني الله بها، فخليت سبيله‏.‏ قال‏:‏ ‏\"‏ما هي‏؟‏‏\"‏ قلت‏:‏ قال لي‏:‏ إذا أويت إلى فراشك فاقرأ آية الكرسي من أولها حتى تختم الآية‏:‏ ‏{‏الله لا إله إلا هو الحي القيوم‏}‏ وقال لي‏:‏ لا يزال عليك من الله حافظ، ولن يقربك شيطان حتى تصبح، فقال النبي صلى الله عليه وسلم‏:‏ ‏\"‏أما إنه قد صدقك وهو كذوب، تعلم من تخاطب منذ ثلاث يا أبا هريرة ‏\"‏ ‏؟‏ قلت‏:‏ لا، قال‏:‏ ‏\"‏ذاك شيطان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:342","bookId":"riyad","type":"hadith","num":342,"kitab":"كتاب الفضائل","isnad":"وعن أبي الدرداء رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من حفظ عشر آيات من أول سورة الكهف، عصم من الدجال‏\"‏ وفي رواية‏:‏ ‏\"‏من آخر سورة الكهف‏\"‏ ‏(‏‏(‏رواهما مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:343","bookId":"riyad","type":"hadith","num":343,"kitab":"كتاب الفضائل","isnad":"-وعن ابن عباس رضي الله عنهما قال‏:‏ بينما جبريل عليه السلام قاعد عند النبي صلى الله عليه وسلم سمع نقيضًا من فوقه، فرفع رأسه فقال‏:‏ ‏","matn":"\"‏هذا باب من السماء فتح اليوم ولم يفتح قط إلا اليوم، فنزل منه ملك فقال‏:‏ هذا ملك نزل إلى الأرض لم ينزل قط إلا اليوم، فسلم وقال‏:‏ أبشر بنورين أوتيتهما، لم يؤتهما نبي قبلك‏:‏ فاتحة الكتاب، وخواتيم سورة البقرة، لن تقرأ بحرف منها إلا أعطيته‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏‏النقيض‏:‏ الصوت‏‏."},{"id":"riyad:344","bookId":"riyad","type":"hadith","num":344,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله، ويتدارسونه بينهم، إلا نزلت عليهم السكينة، وغشيتهم الرحمة، وحفتهم الملائكة، وذكرهم الله فيمن عنده‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:345","bookId":"riyad","type":"hadith","num":345,"kitab":"كتاب الفضائل","isnad":"-وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن أمتي يدعون يوم القيامة غرًا محجلين من آثار الوضوء فمن استطاع منكم أن يطيل غرته، فليفعل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:346","bookId":"riyad","type":"hadith","num":346,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ سمعت خليلي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏تبلغ الحلية من المؤمن حيث يبلغ الوضوء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:347","bookId":"riyad","type":"hadith","num":347,"kitab":"كتاب الفضائل","isnad":"وعن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من توضأ فأحسن الوضوء، خرجت خطاياه من جسده حتى تخرج من تحت أظفاره‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:348","bookId":"riyad","type":"hadith","num":348,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم يتوضأ مثل وضوئي هذا ثم قال‏:‏ ‏","matn":"\"‏من توضأ هكذا، غفر له ما تقدم من ذنبه، وكانت صلاته ومشيه إلى المسجد نافلة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:349","bookId":"riyad","type":"hadith","num":349,"kitab":"كتاب الفضائل","isnad":"-وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا توضأ العبد المسلم - أو المؤمن- فغسل وجهه، خرج من وجهه كل خطيئة نظر إليها بعينيه مع الماء، أو مع آخر قطر الماء، فإذا غسل يديه، خرج من يديه كل خطيئة كان بطشتها يداه مع الماء، أو مع آخر قطر الماء، فإذا غسل رجليه، خرجت كل خطيئة مشتها رجلاه مع الماء، أو مع آخر قطر الماء، حتى يخرج نقيًا من الذنوب‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:350","bookId":"riyad","type":"hadith","num":350,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم أتى المقبرة فقال‏:‏ ‏","matn":"\"‏السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، وددت أنا قد رأينا إخواننا‏\"‏ قالوا‏:‏ أولسنا إخوانك يا رسول الله‏؟‏ قال‏:‏ ‏\"‏أنتم أصحابي، وإخواننا الذين لم يأتوا بعد‏\"‏ قالوا‏:‏ كيف تعرف من لم يأتِ بعد من أمتك يا رسول الله‏؟‏ فقال‏:‏ ‏\"‏أرأيت لو أن رجلا له خيل غر محجلة بين ظهري خيل دهم بهم، ألا يعرف خيله ‏؟‏‏\"‏ قالوا بلى يا رسول الله، قال‏:‏ فإنهم يأتون غرًا محجلين من الوضوء وأنا فرطهم على الحوض ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:351","bookId":"riyad","type":"hadith","num":351,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال ألا أدلكم على ما يمحو الله به الخطايا ويرفع به الدرجات قالوا بلى يارسول الله قال‏:‏ ‏","matn":"\"‏إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط، فذلكم الرباط‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:352","bookId":"riyad","type":"hadith","num":352,"kitab":"كتاب الفضائل","isnad":"وعن أبي مالك الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏الطهور شطر الإيمان‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وقد سبق بطوله في باب الصبر‏.‏ وفي الباب حديث عمرو بن عبسة رضي الله عنه السابق في آخر باب الرجاء، وهو حديث عظيم، مشتمل على جمل من الخيرات‏.‏"},{"id":"riyad:353","bookId":"riyad","type":"hadith","num":353,"kitab":"كتاب الفضائل","isnad":"وعن عمر بن الخطاب رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏ما منكم من أحد يتوضا فيبلغ-أو فيسبغ الوضوء- ثم قال‏:‏ أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، إلا فتحت له أبواب الجنة الثمانية يدخل من أيها شاء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وزاد الترمذي‏:‏ ‏\"‏اللهم اجعلني من التوابين واجعلني من المتطهرين‏\""},{"id":"riyad:354","bookId":"riyad","type":"hadith","num":354,"kitab":"كتاب الفضائل","isnad":"- عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا عليه، ولو يعلمون ما في التهجير لاستبقوا إليه، ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏والاستهام‏:‏ الاقتراع‏.‏ والتهجير‏:‏ التبكير إلى الصلاة"},{"id":"riyad:355","bookId":"riyad","type":"hadith","num":355,"kitab":"كتاب الفضائل","isnad":"وعن معاوية رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏المؤذنون أطول الناس أعناقًا يوم القيامة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:356","bookId":"riyad","type":"hadith","num":356,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عبد الرحمن بن أبي صعصعة أن أبا سعيد الخدري رضي الله عنه قال له‏:‏ ‏","matn":"\"‏إني أراك تحب الغنم والبادية فإذا كنت في غنمك- أو باديتك- فأذنت للصلاة، فارفع صوتك بالنداء، فإنه لا يسمع مدى صوت المؤذن جن، ولا إنس، ولا شيء، إلا شهد له يوم القيامة‏\"‏ قال أبو سعيد‏:‏ سمعته من رسول الله صلى الله عليه وسلم ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:357","bookId":"riyad","type":"hadith","num":357,"kitab":"كتاب الفضائل","isnad":"- وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا نودي بالصلاة، أدبر الشيطان، له ضراط حتى لا يسمع التأذين، فإذا قضي النداء أقبل، حتى ثوب بالصلاة أدبر حتى إذا قضي التثويب أقبل حتى يخطر بين المرء ونفسه يقول‏:‏ اذكر كذا، واذكر كذا- لما لم يذكر من قبل- حتى يظل الرجل ما يدري كم صلى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:358","bookId":"riyad","type":"hadith","num":358,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا سمعتم النداء فقولوا مثل ما يقول، ثم صلوا علي، فإنه من صلى على صلاة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:359","bookId":"riyad","type":"hadith","num":359,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا سمعتم النداء، فقولوا كما يقول المؤذن‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:360","bookId":"riyad","type":"hadith","num":360,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قال حين يسمع النداء‏:‏ اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، حلت له شفاعتي يوم القيامة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:361","bookId":"riyad","type":"hadith","num":361,"kitab":"كتاب الفضائل","isnad":"وعن سعد بن أبي وقاص رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال‏:‏‏","matn":"\"‏من قال حين يسمع المؤذن‏:‏ أشهد أن لا إله إلا الله وحده لا شريك له، وأن محمدًا عبده ورسوله، رضيت بالله ربًا وبالإسلام دينًا، غفر له ذنبه‏\"‏‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:362","bookId":"riyad","type":"hadith","num":362,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أنس قال : قَالَ رسول الله : « الدُّعَاءُ لا يُرَدُّ بَيْنَ الأَذَانِ وَالإقَامَةِ » . رواه أَبُو داود والترمذي ، وقال : ( حَدِيثٌ حَسَنٌ )"},{"id":"riyad:363","bookId":"riyad","type":"hadith","num":363,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏أرأيتم لو أن نهرًا بباب أحدكم يغتسل منه كل يوم خمس مرات، هل يبقى من درنه شيء‏؟‏‏\"‏ قالوا‏:‏ لا يبقى من درنه شيء، قال‏:‏ ‏\"‏فذلك مثل الصلوات الخمس، يمحو الله بهن الخطايا‏\"‏‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:364","bookId":"riyad","type":"hadith","num":364,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏مثل الصلوات الخمس كمثل نهر غمر جار على باب أحدكم يغتسل منه كل يوم خمس مرات‏\"‏‏.‏‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:365","bookId":"riyad","type":"hadith","num":365,"kitab":"كتاب الفضائل","isnad":"وعن ابن مسعود رضي الله عنه أن رجلا أصاب من امرأة قُبلةً، فأتى النبي صلى الله عليه وسلم فأخبره فأنزل الله تعالى‏:‏ ‏{‏أقم الصلاة طرفي النهار وزلفًا من الليل، إن الحسنات يذهبن السيئات‏}‏ فقال الرجل‏:‏ ألي هذا‏؟‏ قال‏:‏ ‏","matn":"\"‏لجميع أمتي كلهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:366","bookId":"riyad","type":"hadith","num":366,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏الصلوات الخمس، والجمعة إلى الجمعة، كفارة لما بينهن، ما لم تغشَ الكبائر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:367","bookId":"riyad","type":"hadith","num":367,"kitab":"كتاب الفضائل","isnad":"وعن عثمان بن عفان رضي الله عنه قال‏:‏ سمعت النبي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما من امرئ مسلم تحضره صلاة مكتوبة فيحسن وضوءها وخشوعها وركوعها إلا كانت كفارة لما قبلها من الذنوب مالم تؤتَ كبيرة وذلك الدهر كله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:368","bookId":"riyad","type":"hadith","num":368,"kitab":"كتاب الفضائل","isnad":"عن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏من صلى البردين دخل الجنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:369","bookId":"riyad","type":"hadith","num":369,"kitab":"كتاب الفضائل","isnad":"وعن أبي زهير عمارة بن رؤيبة رضي الله عنه قال، سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لن يلج النار أحد صلى قبل طلوع الشمس وقبل غروبها‏\"‏ (11) ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:370","bookId":"riyad","type":"hadith","num":370,"kitab":"كتاب الفضائل","isnad":"وعن جندب بن سفيان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من صلى الصبح فهو في ذمة الله فانظر يابن آدم، لا يطلبنك الله من ذمته بشيء‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:371","bookId":"riyad","type":"hadith","num":371,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏يتعاقبون فيكم ملائكة بالليل، وملائكة بالنهار، ويجتمعون في صلاة الصبح وصلاة العصر، ثم يعرج الذين باتوا فيكم، فيسألهم الله -وهو أعلم بهم-‏:‏ كيف تركتم عبادي‏؟‏ فيقولون تركناهم وهم يصلون، وأتيناهم وهم يصلون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:372","bookId":"riyad","type":"hadith","num":372,"kitab":"كتاب الفضائل","isnad":"- وعن جرير بن عبد الله البجلي رضي الله عنه قال‏:‏ كنا عند النبي صلى الله عليه وسلم، فنظر إلى القمر ليلة البدر فقال‏:‏ ‏","matn":"\"‏إنكم سترون ربكم كما ترون هذا القمر، لاتضامون في رؤيته، فإن استطعتم أن لا تغلبو على صلاة قبل طلوع الشمس، وقبل غروبها فافعلوا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وفي رواية‏:‏ ‏\"‏فنظر إلى القمر ليلة أربع عشرة‏\"‏‏)‏‏)‏‏.‏"},{"id":"riyad:373","bookId":"riyad","type":"hadith","num":373,"kitab":"كتاب الفضائل","isnad":"وعن بريدة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏من ترك صلاة العصر فقد حبط عمله‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:374","bookId":"riyad","type":"hadith","num":374,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من غدا إلى المسجد أو راح، أعد الله له في الجنة نزلا كلما غدا أو راح‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:375","bookId":"riyad","type":"hadith","num":375,"kitab":"كتاب الفضائل","isnad":"وعنه أن النبي صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏من تطهر في بيته، ثم مضى إلى بيت من بيوت الله، ليقضي فريضة من فرائض الله كانت خطواته، إحداها تحط خطيئة، والأخرى ترفع درجة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:376","bookId":"riyad","type":"hadith","num":376,"kitab":"كتاب الفضائل","isnad":"-وعن أبي بن كعب رضي الله عنه قال‏:‏ كان رجل من الأنصار لا أعلم أحدًا أبعد من المسجد منه، وكانت لا تخطئه صلاة‏!‏ فقيل له‏:‏ لو اشتريت حمارًا تركبه في الظلماء وفي الرمضاء قال‏:‏ ما يسرني أن منزلي إلى جنب المسجد إني أريد أن يكتب لي ممشاي إلى المسجد، ورجوعي إذا رجعت إلى أهلي، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏قد جمع الله لك ذلك كله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:377","bookId":"riyad","type":"hadith","num":377,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال‏:‏ خلت البقاع حول المسجد فأراد بنو سلمة أن ينتقلوا قرب المسجد، فبلغ ذلك النبي صلى الله عليه وسلم فقال لهم‏:‏ ‏","matn":"\"‏بلغني أنكم تريدون أن تنتقلوا قرب المسجد‏؟‏ قالوا‏:‏ نعم يا رسول الله قد أردنا ذلك، فقال‏:‏ ‏\"‏ بني سلمة دياركم تكتب آثاركم، دياركم تكتب آثاركم‏\"‏ فقالوا‏:‏ ما يسرنا أنا كنا تحولنا‏\"‏ ‏(‏‏(‏رواه مسلم، وروى البخاري معناه من رواية أنس‏)‏‏)‏‏.‏"},{"id":"riyad:378","bookId":"riyad","type":"hadith","num":378,"kitab":"كتاب الفضائل","isnad":"وعن أبي موسى الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن أعظم الناس أجرًا في الصلاة أبعدهم إليها ممشى، فأبعدهم، والذي ينتظر الصلاة حتى يصليها مع الإمام أعظم أجرًا من الذي يصليها ثم ينام‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:379","bookId":"riyad","type":"hadith","num":379,"kitab":"كتاب الفضائل","isnad":"وعن بريدة رضي الله عنه عن النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏بشروا المشائين في الظلم إلى المساجد بالنور التام يوم القيامة‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي‏)‏‏)‏‏.‏"},{"id":"riyad:380","bookId":"riyad","type":"hadith","num":380,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ألا أدلكم على ما يمحو الله به الخطايا، ويرفع به الدرجات‏؟‏ ‏\"‏ قالوا بلى يا رسول الله‏.‏ قال‏:‏ ‏\"‏إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط، فذلكم الرباط‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:381","bookId":"riyad","type":"hadith","num":381,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا رأيتم الرجل يعتاد المساجد فاشهدوا له بالإيمان، قال الله عز وجل ‏{‏إنما يعمر مساجد الله من آمن بالله واليوم الآخر‏}‏ ‏(‏‏(‏الآية‏.‏ رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:382","bookId":"riyad","type":"hadith","num":382,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يزال أحدكم في صلاة مادامت الصلاة تحبسه لا يمنعه أن ينقلب إلى أهله إلا الصلاة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:383","bookId":"riyad","type":"hadith","num":383,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ الملائكة تصلي على أحدكم ما دام في مصلاه الذي صلى فيه ما لم يحدث تقول اللهم اغفر له اللهم ارحمه‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:384","bookId":"riyad","type":"hadith","num":384,"kitab":"كتاب الفضائل","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم أخر ليلة صلاة العشاء إلى شطر الليل ثم أقبل علينا بوجهه بعدما صلى فقال‏:‏ ‏","matn":"\"‏صلى الناس ورقدوا ولم تزالوا في صلاة منذ انتظرتموها‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:385","bookId":"riyad","type":"hadith","num":385,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة‏)‏‏)‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:386","bookId":"riyad","type":"hadith","num":386,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏صلاة الرجل في جماعة تُضعَّف على صلاته في بيته وفي سوقه خمسًا وعشرين ضعفًا، وذلك أنه إذا توضأ فأحسن الوضوء، ثم خرج إلى المسجد، لا يخرجه إلا الصلاة، لم يخطُ خطوة إلا رفعت له بها درجة، وحطت عنه بها خطيئة، فإذا صلى لم تزل الملائكة تصلي عليه ما دام في مصلاه، ما لم يحدث، تقول اللهم صلِّ عليه، اللهم ارحمه‏.‏ ولا يزال في صلاة ما انتظر الصلاة‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ وهذا لفظ البخاري‏)‏‏)‏"},{"id":"riyad:387","bookId":"riyad","type":"hadith","num":387,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ أتى النبي صلى الله عليه وسلم رجل أعمي، فقال‏:‏ يا رسول الله، ليس لي قائد يقودني إلى المسجد، فسأل رسول الله صلى الله عليه وسلم أن يرخص له فيصلي في بيته، فرخص له، فلما ولى دعاه فقال له‏:‏ ‏","matn":"\"‏هل تسمع النداء بالصلاة‏؟‏ ‏\"‏ قال نعم، قال‏:‏ ‏\"‏فأجب‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:388","bookId":"riyad","type":"hadith","num":388,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله- وقيل‏:‏ عمرو بن قيس المعروف بابن أم مكتوم المؤذن رضي الله عنه أنه قال‏:‏ يا رسول الله إن المدينة كثيرة الهوام والسباع‏.‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏تسمع حي على الصلاة، حي على الفلاح، فحيهلا‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏.‏ (12)"},{"id":"riyad:389","bookId":"riyad","type":"hadith","num":389,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏والذي نفسي بيده، لقد هممت أن آمر بحطب فيحتطب، ثم آمر بالصلاة فيؤذن لها، ثم آمر رجلا فيؤم الناس، ثم أخالف إلى رجال فأحرق عليهم بيوتهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:390","bookId":"riyad","type":"hadith","num":390,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن مسعود رضي الله عنه قال‏:‏ من سره أن يلقى الله تعالى غدًا مسلمًا، فليحافظ على هؤلاء الصلوات، حيث ينادى بهن، فإن الله شرع لنبيكم صلى الله عليه وسلم سنن الهدى، وإنهن من سنن الهدى، ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم، ولو تركتم سنة نبيكم لضللتم، ولقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق، ولقد كان الرجل يؤتى به، يهادى بين الرجلين حتى يقام في الصف‏.‏ ‏(‏‏(‏رواه مسلم وفي رواية له قال‏:‏ إن رسول الله صلى الله عليه وسلم علمنا سنن الهدى، وإن من الهدى الصلاة في المسجد الذي يؤذن فيه‏)‏‏)‏‏.‏"},{"id":"riyad:391","bookId":"riyad","type":"hadith","num":391,"kitab":"كتاب الفضائل","isnad":"وعن أبي الدرداء رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما من ثلاثة في قرية ولا بدو لا تقام فيهم الصلاة إلا قد استحوذ عليهم الشيطان‏.‏ فعليكم بالجماعة، فإنما يأكل الذئب من الغنم القاصية‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:392","bookId":"riyad","type":"hadith","num":392,"kitab":"كتاب الفضائل","isnad":"عن عثمان بن عفان رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من صلى العشاء في جماعة، فكأنما قام نصف الليل ومن صلى الصبح في جماعة، فكانما صلى الليل كله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية الترمذي عن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏من شهد العشاء في جماعة كان له قيام نصف ليلة، ومن شهد العشاء والفجر في جماعة، كان له كقيام ليلة‏\"‏ ‏(‏‏(‏قال الترمذي حديث حسن صحيح‏)‏‏)‏"},{"id":"riyad:393","bookId":"riyad","type":"hadith","num":393,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وقد سبق بطوله‏.‏"},{"id":"riyad:394","bookId":"riyad","type":"hadith","num":394,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ليس صلاة أثقل على المنافقين من صلاة الفجر والعشاء ولو يعلمون ما فيهما لأتوهما ولو حبوًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:395","bookId":"riyad","type":"hadith","num":395,"kitab":"كتاب الفضائل","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ سألت رسول الله صلى الله عليه وسلم ‏:‏ أي الأعمال أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏الصلاة على أوقتها‏\"‏ قلت‏:‏ ثم أي‏؟‏ قال‏:‏ ‏\"‏بر الوالدين‏\"‏ قلت ثم أي‏؟‏ قال‏:‏ ‏\"‏ الجهاد في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:396","bookId":"riyad","type":"hadith","num":396,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ بني الإسلام على خمس‏:‏ شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:397","bookId":"riyad","type":"hadith","num":397,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك، عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:398","bookId":"riyad","type":"hadith","num":398,"kitab":"كتاب الفضائل","isnad":"وعن معاذ رضي الله عنه قال‏:‏ بعثني رسول الله صلى الله عليه وسلم إلى اليمن فقال‏:‏ ‏","matn":"\"‏إنك تأتي قومًا من أهل الكتاب، فادعهم إلى شهادة أن لا إله إلا الله وأني رسول الله، فإن هم أطاعوا لذلك، فأعلمهم أن الله تعالى افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك، فأعلمهم أن الله تعالى افترض عليهم صدقة تؤخذ من أغنيائهم فترد على فقرائهم، فإن هم اطاعوا لذلك، فإياك وكرائم أموالهم واتقِ دعوة المظلوم فإنه ليس بينها وبين الله حجاب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:399","bookId":"riyad","type":"hadith","num":399,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن بين الرجل وبين الشرك والكفر ترك الصلاة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:400","bookId":"riyad","type":"hadith","num":400,"kitab":"كتاب الفضائل","isnad":"وعن بريدة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:401","bookId":"riyad","type":"hadith","num":401,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن شقيق بن عبد الله التابعي المتفق على جلالته رحمه الله قال‏:‏ كان أصحاب محمد صلى الله عليه وسلم لا يرون شيئًا من الأعمال تركه كفر غير الصلاة‏.‏ ‏(‏‏(‏رواه الترمذي في كتاب الإيمان بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:402","bookId":"riyad","type":"hadith","num":402,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن أول ما يحاسب به العبد يوم القيامة من عمله صلاته، فإن صلحت، فقد أفلح وأنجح، وإن فسدت، فقد خاب وخسر، فإن انتقص من فريضته شيئًا، قال الرب، عز وجل‏:‏ انظروا هل لعبدي من تطوع، فيكمل منها ما انتقص من الفريضة‏؟‏ ثم يكون سائر أعماله على هذا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:403","bookId":"riyad","type":"hadith","num":403,"kitab":"كتاب الفضائل","isnad":"عن جابر بن سمرة، رضي الله عنهما، قال‏:‏ خرج علينا رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏ألا تصفون كما تصف الملائكة عند ربها‏؟‏‏\"‏ فقلنا‏:‏ يا رسول الله وكيف تصف الملائكة عند ربها‏؟‏ قال‏:‏ ‏\"‏يتمون الصفوف الأُول، ويتراصون في الصف‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:404","bookId":"riyad","type":"hadith","num":404,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لو يعلم الناس ما في النداء والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:405","bookId":"riyad","type":"hadith","num":405,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏خير صفوف الرجال أولها، وشرها آخرها، وخير صفوف النساء آخرها، وشرها أولها‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:406","bookId":"riyad","type":"hadith","num":406,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري، رضي الله عنه أن رسول الله صلى الله عليه وسلم رأي في أصحابه تأخرًا، فقال لهم‏:‏ ‏","matn":"\"‏تقدموا فَأتموا بي وليأتم بكم مَن بعدكم، لا يزال قوم يتأخرون حتى يؤخرهم الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:407","bookId":"riyad","type":"hadith","num":407,"kitab":"كتاب الفضائل","isnad":"وعن أبي مسعود رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم يمسح مناكبنا في الصلاة، ويقول‏:‏ ‏","matn":"\"‏استووا ولا تختلفوا فتختلف قلوبكم، ليلني منكم أولو الأحلام والنهى، ثم الذين يلونهم ثم الذين يلونهم‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:408","bookId":"riyad","type":"hadith","num":408,"kitab":"كتاب الفضائل","isnad":"وعن أنس، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏سووا صفوفكم، فإن تسوية الصف من تمام الصلاة‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي رواية البخاري‏:‏ ‏\"‏فإن تسوية الصفوف من إقامة الصلاة‏\"‏‏.‏"},{"id":"riyad:409","bookId":"riyad","type":"hadith","num":409,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ أقيمت الصلاة، فأقبل علينا رسول الله صلى الله عليه وسلم بوجهه فقال‏:‏ ‏","matn":"\"‏أقيموا صفوفكم وتراصوا، فإني أراكم من وراء ظهري‏\"‏ ‏(‏‏(‏رواه البخاري بلفظه، ومسلم بمعناه‏)‏‏)‏‏.‏ وفي رواية للبخاري‏:‏ وكان أحدنا يلزق منكبه بمنكب صاحبه وقدمه بقدمه‏\"‏‏.‏"},{"id":"riyad:410","bookId":"riyad","type":"hadith","num":410,"kitab":"كتاب الفضائل","isnad":"وعن النعمان بن بشير رضي الله عنهما، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لتسون صفوفكم، أو ليخالفن الله بين وجوهكم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي رواية لمسلم‏:‏ أن رسول الله صلى الله عليه وسلم كان يسوي صفوفنا حتى كأنما يسوي بها القداح، حتى رأى أنا قد عقلنا عنه‏.‏ ثم خرج يومًا فقام حتى كاد يكبر، فرأى رجلا باديا صدره من الصف، فقال ‏\"‏عباد الله لتسون صفوفكم، أو ليخالفن الله بين وجوهكم‏\"‏‏.‏"},{"id":"riyad:411","bookId":"riyad","type":"hadith","num":411,"kitab":"كتاب الفضائل","isnad":"وعن البراء بن عازب رضي الله عنهما، قال كان رسول الله صلى الله عليه وسلم يتخلل من ناحية إلى ناحية، يمسح صدورنا ومناكبنا ويقول،‏:‏ ‏","matn":"\"‏لا تختلفوا فتختلف قلوبكم‏\"‏ وكان يقول‏:‏ ‏\"‏إن الله وملائكته يصلون على الصفوف الأُول‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:412","bookId":"riyad","type":"hadith","num":412,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أقيموا الصفوف، وحاذوا المناكب، وسدوا الخلل، ولينوا بأيدي إخوانكم، ولا تذروا فرجات للشيطان، ومن وصل صفًا وصله الله، ومن قطع صفًا قطعه الله‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:413","bookId":"riyad","type":"hadith","num":413,"kitab":"كتاب الفضائل","isnad":"وعن أنس، رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏رصوا صفوفكم، وقاربوا بينها وحاذوا الأعناق فوالذي نفسي بيده إني لأرى الشيطان يدخل من خلل الصف، كأنها الحذف‏\"‏ ‏(‏‏(‏حديث صحيح رواه أبو داود بإسناد على شرط مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:414","bookId":"riyad","type":"hadith","num":414,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أتموا الصف المقدم، ثم الذي يليه، فما كان من نقص فليكن في الصف المؤخر‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:415","bookId":"riyad","type":"hadith","num":415,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها، قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله وملائكته يصلون على ميامن الصفوف‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد على شرط مسلم، وفيه رجل مختلف في توثيقه‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:416","bookId":"riyad","type":"hadith","num":416,"kitab":"كتاب الفضائل","isnad":"وعن البراء، رضي الله عنه قال‏:‏ ‏","matn":"\"‏كنا إذا صلينا خلف رسول الله صلى الله عليه وسلم ، أحببنا أن نكون عن يمينه، يقبل علينا بوجهه، فسمعته يقول‏:‏ ‏\"‏رب قني عذابك يوم تبعث - أو تجمع- عبادك‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:417","bookId":"riyad","type":"hadith","num":417,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏وسطوا الإمام، وسدوا الخلل‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:418","bookId":"riyad","type":"hadith","num":418,"kitab":"كتاب الفضائل","isnad":"عن أم المؤمنين أم حبيبة رملة بنت أبي سفيان، رضي الله عنهما، قالت سمعت رسول الله صلى الله عليه وسلم، يقول‏:‏ ما من عبد مسلم يصلي لله تعالى كل يوم ثنتي عشرة ركعة تطوعًا غير الفريضة، إلا بنى الله له بيتًا في الجنة أو‏:‏ إلا بني له بيت في الجنة‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:419","bookId":"riyad","type":"hadith","num":419,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، قال‏:‏ صليت مع رسول الله صلى الله عليه وسلم، ركعتين قبل الظهر وركعتين بعدها، وركعتين بعد الجمعة، وركعتين بعد المغرب، وركعتين بعد العشاء‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:420","bookId":"riyad","type":"hadith","num":420,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن مغفل، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة‏\"‏ وقال في الثالثة‏:‏ ‏\"‏لمن شاء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:421","bookId":"riyad","type":"hadith","num":421,"kitab":"كتاب الفضائل","isnad":"","matn":"عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر، وركعتين قبل الغداة ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:422","bookId":"riyad","type":"hadith","num":422,"kitab":"كتاب الفضائل","isnad":"وعنها قالت‏:‏ لم يكن النبي، صلى الله عليه وسلم على شيء من النوافل أشد تعاهدًا منه على ركعتي الفجر‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:423","bookId":"riyad","type":"hadith","num":423,"kitab":"كتاب الفضائل","isnad":"وعنها عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ركعتا الفجر خير من الدنيا وما فيها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية لهما لأحب إلي من الدنيا جميعًا‏.‏"},{"id":"riyad:424","bookId":"riyad","type":"hadith","num":424,"kitab":"كتاب الفضائل","isnad":"وعن أبي عبد الله بلال بن رباح، رضي الله عنه مؤذن رسول الله صلى الله عليه وسلم أنه أتى رسول الله صلى الله عليه وسلم ليؤذنه بصلاة الغداة، فشغلت عائشة بلالا بأمر سألته عنه، حتى أصبح جدا فقام بلال فآذنه بالصلاة، وتابع أذانه، فلم يخرج رسول الله صلى الله عليه وسلم فلما خرج صلى بالناس، فأخبره أن عائشة شغلته بأمر سألته عنه حتى أصبح جدا، وأنه أبطأ عليه بالخروج، فقال -يعني النبي صلى الله عليه وسلم -‏:‏ ‏","matn":"\"‏إني كنت ركعت ركعتي الفجر‏\"‏ فقال‏:‏ يا رسول الله إنك أصبحت جدا‏؟‏ فقال‏:‏ ‏\"‏لو أصبحت أكثر مما أصبحت، لركعتهما وأحسنتهما، وأجملتهما‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:425","bookId":"riyad","type":"hadith","num":425,"kitab":"كتاب الفضائل","isnad":"عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم، كان يصلي ركعتين خفيفتين بين النداء والإقامة من صلاة الصبح‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي رواية لهما‏:‏ يصلي ركعتي الفجر، إذا سمع الأذان فيخففهما حتى أقول هل قرأ فيهمابأم القرآن‏!‏‏.‏ وفي رواية لمسلم‏:‏ كان يصلى ركعتيي الفجر إذا سمع الأذان ويخففهما‏.‏ وفي رواية‏:‏ إذا طلع الفجر‏.‏"},{"id":"riyad:426","bookId":"riyad","type":"hadith","num":426,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن حفصة رضي الله عنها أن رسول الله صلى الله عليه وسلم كان إذا أذن المؤذن للصبح، وبدا الصبح صلى ركعتين خفيفتين‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ كان رسول الله صلى الله عليه وسلم إذا طلع الفجر لا يصلى إلا ركعتين خفيفتين‏.‏"},{"id":"riyad:427","bookId":"riyad","type":"hadith","num":427,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كان رسول الله صلى الله عليه وسلم يصلي من الليل مثنى مثنى، ويوتر بركعة من آخر الليل، ويصلي الركعتين قبل صلاة الغداة، وكأن الأذان بأذنيه‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:428","bookId":"riyad","type":"hadith","num":428,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم، كان يقرأ في ركعتي الفجر في الأولى منهما‏:‏ ‏{‏قولوا آمنا بالله وما أنزل إلينا‏}‏ الآية التي في البقرة، وفي الآخرة منهما‏:‏ ‏{‏آمنا بالله واشهد بأنا مسلمون‏}.‏ وفي رواية‏:‏ في الآخرة التي في آل عمران‏:‏ ‏{‏تعالوا إلى كلمة سواء بيننا وبينكم‏}‏‏.‏ ‏(‏‏(‏رواهما مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:429","bookId":"riyad","type":"hadith","num":429,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم، قرأ في ركعتي الفجر‏:‏ ‏{‏قل يا أيها الكافرون‏}‏ و‏{‏قل هو الله أحد‏}‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:430","bookId":"riyad","type":"hadith","num":430,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن عمر رضي الله عنهما، قال رمقت النبي صلى الله عليه وسلم شهرًا يقرأ في الركعتين قبل الفجر‏:‏ ‏{‏قل يا أيها الكافرون‏}‏، و‏:‏ ‏{‏قل هو الله أحد‏}‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:431","bookId":"riyad","type":"hadith","num":431,"kitab":"كتاب الفضائل","isnad":"","matn":"عن عائشة رضي الله عنها قالت‏:‏ كان النبي صلى الله عليه وسلم إذا صلى ركعتي الفجر، اضطجع على شقه الأيمن‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:432","bookId":"riyad","type":"hadith","num":432,"kitab":"كتاب الفضائل","isnad":"وعنها قالت‏:‏ كان النبي صلى الله عليه وسلم يصلي فيما بين أن يفرغ من صلاة العشاء إلى الفجر إحدى عشرة ركعة يسلم بين كل ركعتين، ويوتر بواحدة، فإذا سكت المؤذن من صلاة الفجر، وتبين له الفجر وجاء المؤذن، قام فركع ركعتين خفيفتين، ثم اضطجع على شقه الأيمن هكذا حتى يأتيه المؤذن للإقامة‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ (15)"},{"id":"riyad:433","bookId":"riyad","type":"hadith","num":433,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا صلى أحدكم ركعتي الفجر، فليضطجع على يمينه‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي بأسانيد صحيحة‏.‏ قال الترمذي‏:‏ حديث حسن صحيح‏.‏"},{"id":"riyad:434","bookId":"riyad","type":"hadith","num":434,"kitab":"كتاب الفضائل","isnad":"","matn":"عن ابن عمر رضي الله عنهما قال‏:‏ صليت مع رسول الله صلى الله عليه وسلم ركعتين قبل الظهر، وركعتين بعدها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:435","bookId":"riyad","type":"hadith","num":435,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:436","bookId":"riyad","type":"hadith","num":436,"kitab":"كتاب الفضائل","isnad":"","matn":"وعنها قالت‏:‏ كان النبي صلى الله عليه وسلم يصلي في بيتي قبل الظهر أربعًا، ثم يخرج فيصلي بالناس، ثم يدخل فيصلي ركعتين، وكان يصلي بالناس المغرب ثم يدخل بيتي فيصلي ركعتين، ويصلي بالناس العشاء، ويدخل بيتي، فيصلي ركعتين‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:437","bookId":"riyad","type":"hadith","num":437,"kitab":"كتاب الفضائل","isnad":"وعن أم حبيبة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من حافظ على أربع ركعات قبل الظهر وأربع بعدها، حرمه الله على النار‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي‏)‏‏)‏‏.‏ وقال حديث حسن صحيح‏.‏"},{"id":"riyad:438","bookId":"riyad","type":"hadith","num":438,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن السائب، رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يصلى أربعًا بعد أن تزول الشمس قبل الظهر، وقال ‏","matn":"\"‏إنها ساعة تفتح فيها أبواب السماء، فأحب أن يصعد لي فيها عمل صالح‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:439","bookId":"riyad","type":"hadith","num":439,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا لم يصلِ أربعًا قبل الظهر، صلاهن بعدها‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:440","bookId":"riyad","type":"hadith","num":440,"kitab":"كتاب الفضائل","isnad":"","matn":"عن علي بن أبي طالب، رضي الله عنه قال كان النبي صلى الله عليه وسلم يصلي قلب العصر أربع ركعات يفصل بينهن بالتسليم على الملائكة المقربين ومن تبعهم من المسلمين والمؤمنين‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:441","bookId":"riyad","type":"hadith","num":441,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر، رضي الله عنهما، عن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏رحم الله امرءًا صلى قبل العصر أربعًا‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:442","bookId":"riyad","type":"hadith","num":442,"kitab":"كتاب الفضائل","isnad":"وعن علي بن أبي طالب رضي الله عنه أن النبي صلى الله عليه وسلم كان يصلي قبل العصر ركعتين‏.‏‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:443","bookId":"riyad","type":"hadith","num":443,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن مغفل، رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏صلوا قبل المغرب‏\"‏ قال في الثالثة‏:‏ ‏\"‏لمن شاء‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:444","bookId":"riyad","type":"hadith","num":444,"kitab":"كتاب الفضائل","isnad":"","matn":"- وعن أنس، رضي الله عنه قال‏:‏ لقد رأيت كبار أصحاب رسول الله صلى الله عليه وسلم يبتدرون السواري عند المغرب‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:445","bookId":"riyad","type":"hadith","num":445,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ كنا نصلي على عهد رسول الله صلى الله عليه وسلم ركعتين بعد غروب الشمس قبل المغرب، فقيل‏:‏ أكان رسول الله صلى الله عليه وسلم صلاها‏؟‏ قال‏:‏ كان يرانا نصليهما فلم يأمرنا ولم ينهنا‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:446","bookId":"riyad","type":"hadith","num":446,"kitab":"كتاب الفضائل","isnad":"","matn":"وعنه قال‏:‏ كنا بالمدينة فإذا أذن المؤذن لصلاة المغرب ابتدروا السواري، فركعوا ركعتين، حتى إن الرجل الغريب ليدخل المسجد فيحسب أن الصلاة قد صليت من كثرة من يصليهما‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:447","bookId":"riyad","type":"hadith","num":447,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا صلى أحدكم الجمعة، فليصلِ بعدها أربعًا‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:448","bookId":"riyad","type":"hadith","num":448,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم كان لا يصلي بعد الجمعة حتى ينصرف، فيصلي ركعتين في بيته‏. (‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:449","bookId":"riyad","type":"hadith","num":449,"kitab":"كتاب الفضائل","isnad":"عن زيد بن ثابت رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏صلوا أيها الناس في بيوتكم، فإن الصلاة صلاة المرء في بيته إلا المكتوبة‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:450","bookId":"riyad","type":"hadith","num":450,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ اجلعوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:451","bookId":"riyad","type":"hadith","num":451,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا قضى أحدكم صلاته في مسجده، فليجعل لبيته نصيبًا من صلاته، فإن الله جاعل في بيته صلاته خيرًا‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:452","bookId":"riyad","type":"hadith","num":452,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عمر بن عطاء أن نافع بن جبير أرسله إلى السائب ابن أخت نمر يسأله عن شيء رآه منه معاوية في الصلاة فقال‏:‏ نعم صليت معه الجمعة في المقصورة، فلما سلم الإمام، قمت في مقامي، فصليت فلما دخل أرسل إلي فقال‏:‏ لا تعد لما فعلت‏:‏ إذا صليت الجمعة فلا تصلها بصلاة حتى تتكلم أو تخرج، فإن رسول الله صلى الله عليه وسلم أمرنا بذلك أن لا نوصل صلاة بصلاة حتى نتكلم أو نخرج‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:453","bookId":"riyad","type":"hadith","num":453,"kitab":"كتاب الفضائل","isnad":"عن علي رضي الله عنه قال‏:‏ الوتر ليس بختم كصلاة المكتوبة ولكن سن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله وتر يحب الوتر، فأوتروا يا أهل القرآن‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي‏)‏‏)‏‏.‏ وقال‏:‏ حديث حسن‏.‏"},{"id":"riyad:454","bookId":"riyad","type":"hadith","num":454,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ من كل الليل قد أوتر رسول الله صلى الله عليه وسلم‏:‏ من أول الليل ومن أوسطه، ومن آخره‏.‏ وانتهى وتره إلى السحر‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:455","bookId":"riyad","type":"hadith","num":455,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ اجعلوا آخر صلاتكم بالليل وترًا‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:456","bookId":"riyad","type":"hadith","num":456,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أوتروا قبل أن تصبحوا‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:457","bookId":"riyad","type":"hadith","num":457,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يصلي بالليل، وهي معترضة بين يديه، فإذا بقي الوتر، أيقظها فأوترت‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ فإذا بقي الوتر قال‏:‏ ‏","matn":"\"‏قومي فأوتري يا عائشة‏\"‏"},{"id":"riyad:458","bookId":"riyad","type":"hadith","num":458,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏بادروا الصبح بالوتر‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي‏)‏‏)‏‏.‏ وقال‏:‏ حديث حسن صحيح‏.‏"},{"id":"riyad:459","bookId":"riyad","type":"hadith","num":459,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من خاف أن لا يقوم الليل فليوتر أوله، ومن طمع أن يقوم آخره، فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:460","bookId":"riyad","type":"hadith","num":460,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ أوصاني خليلي صلى الله عليه وسلم بصيام ثلاثة أيام من كل شهر، وركعتي الضحى، وأن أوتر قبل أن أرقد‏","matn":"\"‏ ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ والإيتار قبل النوم إنما يستحب لمن لا يثق باستيقاظ آخر الليل، فإن وثق فآخر الليل أفضل‏.‏"},{"id":"riyad:461","bookId":"riyad","type":"hadith","num":461,"kitab":"كتاب الفضائل","isnad":"وعن أبي ذر رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يصبح على كل سلامى من أحدكم صدقة‏:‏ فكل تسبيحة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويجزئ من ذلك ركعتان يركعهما من الضحى‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:462","bookId":"riyad","type":"hadith","num":462,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يصلي الضحى أربعًا ويزيد ما شاء الله ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:463","bookId":"riyad","type":"hadith","num":463,"kitab":"كتاب الفضائل","isnad":"وعن أم هانئ فاختة بنت أبي طالب رضي الله عنها قالت‏:‏ ذهبت إلى رسول الله صلى الله عليه وسلم عام الفتح فوجدته يغتسل فلما فرغ من غسله صلى ثمان ركعات، وذلك ضحى‏","matn":"\"‏ ‏(‏‏(‏متفق عليه وهذا مختصر لفظ إحدى روايات مسلم‏)‏‏)‏"},{"id":"riyad:464","bookId":"riyad","type":"hadith","num":464,"kitab":"كتاب الفضائل","isnad":"عن زيد بن أرقم رضي الله عنه أنه رأى قومًا يصلون من الضحى، فقال‏:‏ أما لقد علموا أن الصلاة في غير هذه الساعة أفضل، إن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏صلاة الأوابين حين ترمض الفصال‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:465","bookId":"riyad","type":"hadith","num":465,"kitab":"كتاب الفضائل","isnad":"وعن أبي قتادة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:466","bookId":"riyad","type":"hadith","num":466,"kitab":"كتاب الفضائل","isnad":"وعن جابر، رضي الله عنه قال‏:‏ أتيت النبي صلى الله عليه وسلم وهو في المسجد فقال‏:‏ ‏","matn":"\"‏صلِ ركعتين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:467","bookId":"riyad","type":"hadith","num":467,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال","matn":"لبلال‏:‏ يا بلال حدثني بأرجى عمل عملته في الإسلام، فإني سمعت دف نعليك بين يدي في الجنة، قال‏:‏ ما عملت عملا أرجى عندي من أني لم أتطهر طهورًا في ساعة من ليل أو نهار إلا صليت بذلك الطهور ما كتب لي أن أصلي‏.‏ ‏(‏‏(‏متفق عليه وهذا لفظ البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:468","bookId":"riyad","type":"hadith","num":468,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ خير يوم طلعت عليه الشمس يوم الجمعة‏:‏ فيه خلق آدم، وفيه أدخل الجنة، وفيه أخرج منها‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:469","bookId":"riyad","type":"hadith","num":469,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من توضأ فأحسن الوضوء ثم أتي الجمعة، فاستمع وأنصت، غفر له ما بينه وبين الجمعة وزيادة ثلاثة أيام، ومن مس الحصى، فقد لغا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:470","bookId":"riyad","type":"hadith","num":470,"kitab":"كتاب الفضائل","isnad":"وعنه عن النبي، صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الصلوات الخمس والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات ما بينهن إذا اجتنبت الكبائر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:471","bookId":"riyad","type":"hadith","num":471,"kitab":"كتاب الفضائل","isnad":"وعنه وعن ابن عمر، رضي الله عنهم، أنهما سمعا رسول الله صلى الله عليه وسلم ، يقول على أعواد منبره‏:‏ ‏","matn":"\"‏لينتهين أقوام عن وَدعهم الجمعات، أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:472","bookId":"riyad","type":"hadith","num":472,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏إذا جاء أحدكم الجمعة، فليغتسل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:473","bookId":"riyad","type":"hadith","num":473,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري، رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏غسل الجمعة واجب على كل محتلم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:474","bookId":"riyad","type":"hadith","num":474,"kitab":"كتاب الفضائل","isnad":"وعن سمرة، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من توضأ يوم الجمعة، فبها ونعمت، ومن اغتسل فالغسل أفضل‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:475","bookId":"riyad","type":"hadith","num":475,"kitab":"كتاب الفضائل","isnad":"- وعن سلمان، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يغتسل رجل يوم الجمعة، ويتطهر ما استطاع من طهر، ويدهن من دهنه، أو يمس من طيب بيته، ثم يخرج فلا يفرق بين اثنين، ثم يصلي ما كتب له، ثم ينصت إذا تكلم الإمام، إلا غفر له ما بينه وبين الجمعة الأخرى‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:476","bookId":"riyad","type":"hadith","num":476,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏من اغتسل يوم الجمعة غسل الجنابة، ثم راح في الساعة الأولى فكأنما قرب بدنة، ومن راح في الساعة الثانية، فكأنما قرب بقرة، ومن راح في الساعة الثالثة، فكأنما قرب كبشًا أقرن، ومن راح في الساعة الرابعة، فكأنما قرب دجاجة، ومن راح في الساعة الخامسة، فكأنما قرب بيضة، فإذا خرج الإمام، حضرت الملائكة يستمعون الذكر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:477","bookId":"riyad","type":"hadith","num":477,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم ، ذكر يوم الجمعة، فقال‏:‏ ‏","matn":"\"‏فيها ساعة لا يوافقها عبد مسلم، وهو قائم يصلي يسأل الله شيئًا، إلا أعطاه إياه‏\"‏ وأشار بيده يقللها، ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:478","bookId":"riyad","type":"hadith","num":478,"kitab":"كتاب الفضائل","isnad":"وعن أبي بردة بن أبي موسى الأشعري، رضي الله عنه، قال‏:‏ قال عبد الله بن عمر رضي الله عنهما‏:‏ أسمعت أباك يحدث عن رسول الله صلى الله عليه وسلم ، في شأن ساعة الجمعة‏؟‏ قال‏:‏ قلت‏:‏ نعم، سمعته يقول‏:‏ سمعت رسول الله صلى الله عليه وسلم ، يقول‏:‏ ‏","matn":"\"‏هي ما بين أن يجلس الإمام إلى أن تقضى الصلاة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:479","bookId":"riyad","type":"hadith","num":479,"kitab":"كتاب الفضائل","isnad":"وعن أوس بن أوس، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن من أفضل أيامكم يوم الجمعة، فأكثروا علي من الصلاة فيه، فإن صلاتكم معروضة علي‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:480","bookId":"riyad","type":"hadith","num":480,"kitab":"كتاب الفضائل","isnad":"عن سعد بن أبي وقاص، رضي الله عنه، قال‏:‏ خرجنا مع رسول الله صلى الله عليه وسلم من مكة نريد المدينة، فلما كنا قريبًا من عزوراء نزل ثم رفع يديه، فدعا الله ساعة، ثم خر ساجدًا، فمكث طويلا، ثم قام فرفع يديه ساعة، ثم خر ساجدًا- فعله- ثلاثًا- وقال‏:‏ ‏","matn":"\"‏إني سألت ربي، وشفعت لأمتي، فأعطاني ثلث أمتي، فخررت ساجدًا لربي شكرًا، ثم رفعت رأسي، فسألت ربي لأمتي، فأعطاني ثلث أمتي، فخررت ساجدًا لربي شكرًا، ثم رفعت رأسي، فسألت ربي لأمتي، فأعطاني الثلث الآخر، فخررت ساجدًا لربي‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:481","bookId":"riyad","type":"hadith","num":481,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها، قالت‏:‏ كان النبي صلى الله عليه وسلم ، يقوم من الليل حتى تتفطر قدماه، فقلت له‏:‏ لم تصنع هذا يا رسول الله، وقد غفر لك ما تقدم من ذنبك وما تأخر‏؟‏ قال‏:‏ ‏","matn":"\"‏أفلا أكون عبدًا شكورًا‏\"‏‏.‏ ‏(‏‏(‏متفق عليه وعن المغيرة بن شعبة نحوه، متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:482","bookId":"riyad","type":"hadith","num":482,"kitab":"كتاب الفضائل","isnad":"وعن علي رضي الله عنه، أن النبي صلى الله عليه وسلم، طرقه وفاطمة ليلا، فقال‏:‏ ‏","matn":"\"‏ألا تصليان‏؟‏‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (20)"},{"id":"riyad:483","bookId":"riyad","type":"hadith","num":483,"kitab":"كتاب الفضائل","isnad":"وعن سالم بن عبد الله بن عمر بن الخطاب، رضي الله عنهم، عن أبيه‏:‏ أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏نعم الرجل عبد الله لو كان يصلي من الليل‏\"‏ قال سالم‏:‏ فكان عبد الله بعد ذلك لا ينام إلا قليلا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:484","bookId":"riyad","type":"hadith","num":484,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يا عبد الله لا تكن مثل فلان‏:‏ كان يقوم الليل فترك قيام الليل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:485","bookId":"riyad","type":"hadith","num":485,"kitab":"كتاب الفضائل","isnad":"وعن ابن مسعود رضي الله عنه ، قال‏:‏ ذكر عند النبي، صلى الله عليه وسلم رجل نام ليلة حتى أصبح‏!‏ قال‏:‏ ‏","matn":"\"‏ذاك رجل بال الشيطان في أذنيه- أو قال‏:‏ في أذنه-‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:486","bookId":"riyad","type":"hadith","num":486,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏يعقد الشيطان على قافية، رأس أحدكم، إذا هو نام، ثلاث عقد، يضرب على كل عقدة‏:‏ عليك ليل طويل فارقد، فإن استيقظ أحدكم، فذكر الله تعالى انحلت عقدة، فإن توضأ انحلت عقدة، فإن صلى انحلت عقدة، فأصبح نشيطًا طيب النفس، وإلا أصبح خبيث النفس كسلان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:487","bookId":"riyad","type":"hadith","num":487,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن سلام، رضي الله عنه ، أن النبي، صلى الله عليه وسلم ،قال‏:‏ ‏","matn":"\"‏أيها الناس أفشوا السلام، وأطعموا الطعام، وصلوا بالليل والناس نيام، تدخلوا الجنة بسلام‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:488","bookId":"riyad","type":"hadith","num":488,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أفضل الصيام بعد رمضان شهر الله المحرم، وأفضل الصلاة بعد الفريضة صلاة الليل‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:489","bookId":"riyad","type":"hadith","num":489,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏صلاة الليل مثنى مثنى، فإذا خفت الصبح فأوتر بواحدة‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:490","bookId":"riyad","type":"hadith","num":490,"kitab":"كتاب الفضائل","isnad":"","matn":"وعنه قال‏:‏ كان النبي صلى الله عليه وسلم ، يصلي من الليل مثنى مثنى، ويوتر بركعة‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:491","bookId":"riyad","type":"hadith","num":491,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أنس رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم ، يفطر من الشهر حتى نظن أن لا يصوم منه، ويصوم حتى نظن أن لا يفطر منه شيئًا، وكان لا تشاء أن تراه من الليل مصليا إلا رأيته، ولا نائمًا إلا رأيته‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:492","bookId":"riyad","type":"hadith","num":492,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها، أن رسول الله صلى الله عليه وسلم، كان يصلي إحدى عشرة ركعة- تعني في الليل- يسجد السجدة من ذلك قدر ما يقرأ أحدكم خمسين آية قبل أن يرفع رأسه، ويركع ركعتين قبل صلاة الفجر، ثم يضطجع على شقه الأيمن حتى يأتيه المنادي للصلاة، ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:493","bookId":"riyad","type":"hadith","num":493,"kitab":"كتاب الفضائل","isnad":"وعنها قالت‏:‏ ما كان رسول الله صلى الله عليه وسلم ، يزيد- في رمضان ولا في غيره- على إحدي عشرة ركعة‏:‏ يصلي أربعًا فلا تسأل عن حسنهن وطولهن‏!‏ ثم يصلي أربعًا فلا تسأل عن حسنهن وطولهن‏!‏ ثم يصلي ثلاثًا‏.‏ فقلت‏:‏ يا رسول الله أتنام قبل أن توتر‏!‏‏؟‏ فقال‏:‏ ‏","matn":"\"‏يا عائشة إن عيني تنامان ولا ينام قلبي‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:494","bookId":"riyad","type":"hadith","num":494,"kitab":"كتاب الفضائل","isnad":"","matn":"وعنها أن النبي صلى الله عليه وسلم، كان ينام أول الليل، ويقوم آخره فيصلي‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:495","bookId":"riyad","type":"hadith","num":495,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن مسعود رضي الله عنه، قال‏:‏ صليت مع النبي صلى الله عليه وسلم ، ليلة، فلم يزل قائمًا حتى هممت بأمر سوء‏.‏ قيل‏:‏ ما هممت‏؟‏ قال‏:‏ هممت أن أجلس وأدعه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:496","bookId":"riyad","type":"hadith","num":496,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن حذيفة رضي الله عنه، قال‏:‏ صليت مع النبي صلى الله عليه وسلم ، ذات ليلة فافتتح البقرة، فقلت‏:‏ يركع عند المائة، ثم مضى، فقلت‏:‏ يصلي بها في ركعة، فمضي، فقلت‏:‏ يركع بها، ثم افتتح النساء فقرأها، ثم افتتح آل عمران، فقرأها، يقرأ مترسلا‏.‏ إذا مر بآية فيها تسبيح سبح، وإذا بسؤال سأل، وإذا مر بتعوذ تعوذ، ثم ركع، فجعل يقول‏:‏ سبحان ربي العظيم، فكان ركوعه نحوًا من قيامه، ثم قال‏:‏ سمع الله لمن حمده، ربنا لك الحمد، ثم قام طويلا قريبًا مما ركع، ثم سجد فقال‏:‏ سبحان ربي الأعلى، فكان سجوده قريبًا من قيامه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:497","bookId":"riyad","type":"hadith","num":497,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم ‏:‏ أي الصلاة أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏طول القنوت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:498","bookId":"riyad","type":"hadith","num":498,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏أحب الصلاة إلى الله صلاة داود، وأحب الصيام إلى الله صيام داود، كان ينام نصف الليل ويقوم ثلثه وينام سدسه ويصوم يومًا ويفطر يومًا‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:499","bookId":"riyad","type":"hadith","num":499,"kitab":"كتاب الفضائل","isnad":"وعن جابر رضي اللله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم ، يقول‏:‏ ‏","matn":"\"‏إن في الليل لساعة، لا يوافقها رجل مسلم يسأل الله تعالى خيرًا من أمر الدنيا والآخرة، إلا أعطاه إياه، وذلك كل ليلة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:500","bookId":"riyad","type":"hadith","num":500,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، أن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏إذا قام أحدكم من الليل فليفتتح الصلاة بركعتين خفيفتين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:501","bookId":"riyad","type":"hadith","num":501,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت كان رسول الله صلى الله عليه وسلم إذا قام من الليل افتتح صلاته بركعتين خفيفتين ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:502","bookId":"riyad","type":"hadith","num":502,"kitab":"كتاب الفضائل","isnad":"","matn":"وعنها رضي الله عنها، قالت‏:‏ كان رسول الله صلى الله عليه وسلم ، إذا فاتته الصلاة من الليل من وجع أو غيره، صلى من النهار ثنتي عشر ركعة‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:503","bookId":"riyad","type":"hadith","num":503,"kitab":"كتاب الفضائل","isnad":"وعن عمر بن الخطاب، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من نام عن حزبه، أو عن شيء منه، فقرأه فيما بين صلاة الفجر وصلاة الظهر، كتب له كأنما قرأه من الليل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:504","bookId":"riyad","type":"hadith","num":504,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏رحم الله رجلا قام من الليل، فصلى وأيقظ امرأته، فإن أبت نضح في وجهها الماء، ورحم الله امرأة قامت من الليل فصلت، وأيقظت زوجها فإن أبي نضحت في وجهه الماء‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:505","bookId":"riyad","type":"hadith","num":505,"kitab":"كتاب الفضائل","isnad":"وعنه وعن أبي سعيد رضي الله عنهما، قالا‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا أيقظ الرجل أهله من الليل فصليا أو صلى ركعتين جميعًا كتب في الذاكرين والذاكرات‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:506","bookId":"riyad","type":"hadith","num":506,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا نعس أحدكم في الصلاة، فليرقد حتى يذهب عنه النوم، فإن أحدكم إذا صلى وهو ناعس، لعله يذهب يستغفر فيسب نفسه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:507","bookId":"riyad","type":"hadith","num":507,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا قام أحدكم، من الليل فاستعجم القرآن على لسانه، فلم يدرِ ما يقول، فليضطجع‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:508","bookId":"riyad","type":"hadith","num":508,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:509","bookId":"riyad","type":"hadith","num":509,"kitab":"كتاب الفضائل","isnad":"وعنه، رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم، يرغب في قيام رمضان من غير أن يأمرهم فيه بعزيمة، فيقول‏:‏ ‏","matn":"\"‏من قام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه‏\"‏ ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:510","bookId":"riyad","type":"hadith","num":510,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قام ليلة القدر إيمانا واحتسابًا غفر له ما تقدم من ذنبه‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:511","bookId":"riyad","type":"hadith","num":511,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما أن رجالا من أصحاب النبي صلى الله عليه وسلم، أروا ليلة القدر في المنام في السبع الأواخر، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أرى رؤياكم قد تواطأت في السبع الأواخر، فمن كان متحريها، فليتحرها في السبع الأواخر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:512","bookId":"riyad","type":"hadith","num":512,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها، قالت‏:‏ كان رسول الله صلى الله عليه وسلم يجاور في العشر الأواخر من رمضان، ويقول‏:‏ ‏","matn":"\"‏تحروا ليلة القدر في العشر الأواخر من رمضان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:513","bookId":"riyad","type":"hadith","num":513,"kitab":"كتاب الفضائل","isnad":"وعنها، رضي الله عنها، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏تحروا ليلة القدر في الوتر من العشر الأواخر من رمضان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:514","bookId":"riyad","type":"hadith","num":514,"kitab":"كتاب الفضائل","isnad":"وعنها رضي الله عنها، قالت‏:‏ كان رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا دخل العشر الأواخر من رمضان، أحيا الليلة، وأيقظ أهله، وجد وشد المئزر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:515","bookId":"riyad","type":"hadith","num":515,"kitab":"كتاب الفضائل","isnad":"وعنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم ، يجتهد في رمضان ما لا يجتهد في غيره، وفي العشر الأواخر منه، ما لا يجتهد في غيره‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:516","bookId":"riyad","type":"hadith","num":516,"kitab":"كتاب الفضائل","isnad":"وعنها قالت‏:‏ قلت‏:‏ يا رسول الله أرأيت إن علمت أي ليلة القدر ما أقول فيها‏؟‏ قال‏:‏ ‏","matn":"\"‏قولي‏:‏ اللهم إنك عفو تحب العفو فاعفُ عني‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏"},{"id":"riyad:517","bookId":"riyad","type":"hadith","num":517,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لولا أن أشق على أمتي - أو على الناس- لأمرتهم بالسواك مع كل صلاة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:518","bookId":"riyad","type":"hadith","num":518,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن حذيفة رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم، إذا قام من النوم يشوص فاه بالسواك‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:519","bookId":"riyad","type":"hadith","num":519,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها، قالت‏:‏ كنا نعد لرسول الله، سواكه وطهوره، فيبعثه الله ما شاء أن يبعثه من الليل، فيتسوك ويتوضأ ويصلي‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:520","bookId":"riyad","type":"hadith","num":520,"kitab":"كتاب الفضائل","isnad":"وعن أنس رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أكثرت عليكم في السواك‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:521","bookId":"riyad","type":"hadith","num":521,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن شريح بن هانئ قال‏:‏ قلت لعائشة، رضي الله عنها‏:‏ بأي شيء كان يبدأ النبي صلى الله عليه وسلم إذا دخل بيته‏.‏ قالت‏:‏ بالسواك‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:522","bookId":"riyad","type":"hadith","num":522,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أبي موسى الأشعري، رضي الله عنه، قال‏:‏ دخلت على النبي صلى الله عليه وسلم، وطرف السواك على لسانه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وهذا لفظ مسلم‏.‏"},{"id":"riyad:523","bookId":"riyad","type":"hadith","num":523,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها ان النبي صلى الله عليه وسلم ‏:‏ قال‏:‏ ‏","matn":"\"‏السواك مطهرة للفم مرضاة للرب‏\"‏ ‏(‏‏(‏رواه النسائي، وابن خذيمة في صحيحه بأسانيد صحيحة‏)‏‏)‏‏.‏"},{"id":"riyad:524","bookId":"riyad","type":"hadith","num":524,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الفطرة خمس، أو خمس من الفطرة‏:‏ الختان، والاستحداد، وتقليم الأظفار، ونتف الإبط، وقص الشارب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ (24)"},{"id":"riyad:525","bookId":"riyad","type":"hadith","num":525,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏عشر من الفطرة‏:‏ قص الشارب، وإعفاء اللحية، والسواك، واستنشاق الماء، وقص الأظفار، وغسل البراجم، ونتف الإبط، وحلق العانة، وانتقاص الماء‏\"‏ ‏(‏‏(‏قال الراوي‏:‏ ونسيت العاشرة إلا أن تكون المضمضة، قال‏:‏ وكيع- وهو أحد رواته-‏)‏‏)‏ ‏.‏ (25) ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏‏(‏‏(‏ (26)"},{"id":"riyad:526","bookId":"riyad","type":"hadith","num":526,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أحفوا الشوارب وأعفوا اللحى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:527","bookId":"riyad","type":"hadith","num":527,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏بني الإسلام على خمس‏:‏ شهادة أن لا إله إلا الله وأن محمدًا عبده ورسوله، إقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:528","bookId":"riyad","type":"hadith","num":528,"kitab":"كتاب الفضائل","isnad":"وعن طلحة بن عبيد الله، رضي الله عنه قال‏:‏ جاء رجل إلى رسول الله صلى الله عليه وسلم، من أهل نجد، ثائر الرأس نسمع دوي صوته، ولا نفقه ما يقول، حتى دنا من رسول الله صلى الله عليه وسلم فإذا هو يسأل عن الإسلام، فقال الرسول صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏خمس صلوات في اليوم والليلة‏\"‏ قال‏:‏ هل علي غيرهن‏؟‏ قال‏:‏ ‏\"‏لا، إلا أن تطوع‏\"‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏وصيام شهر رمضان‏\"‏ قال هل على غيره‏؟‏ قال‏:‏ ‏\"‏لا إلا أن تطوع‏\"‏ قال‏:‏ وذكر له رسول الله صلى الله عليه وسلم، الزكاه فقال‏:‏ هل علي غيرها‏؟‏ قال‏:‏ ‏\"‏لا، إلا أن تطوع‏\"‏ فأدبر الرجل وهو يقول‏:‏ والله لا أزيد على هذا ولا أنقص منه، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏أفلح إن صدق‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:529","bookId":"riyad","type":"hadith","num":529,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنه، أن النبي صلى الله عليه وسلم بعث معاذًا رضي الله عنه إلى اليمن فقال‏:‏ ‏","matn":"\"‏ادعهم إلى شهادة أن لا إله إلا الله وأني رسول الله، فإن هم أطاعوا لذلك فأعلمهم أن الله تعالى افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك فأعلمهم أن الله افترض عليهم صدقة تؤخذ من أغنيائهم، وترد على فقرائهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:530","bookId":"riyad","type":"hadith","num":530,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك، عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:531","bookId":"riyad","type":"hadith","num":531,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه، قال‏:‏ لما توفي رسول الله، وكان أبو بكر، رضي الله عنه، وكفر من كفر من العرب، فقال عمر رضي الله عنه‏:‏ كيف يقاتل الناس وقد قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فمن قالها، فقد عصم مني ماله ونفسه إلا بحقه وحسابه على الله‏\"‏ ‏؟‏‏!‏ فقال أبو بكر‏:‏ والله لأقاتلن من فرق بين الصلاة والزكاة، فإن الزكاة حق المال‏.‏ والله لو منعوني عقال كانوا يؤدونه إلى رسول الله صلى الله عليه وسلم، لقاتلتهم على منعه، قال‏:‏ عمر رضي الله عنه‏:‏ فوالله ما هو إلا أن رأيت الله قد شرح صدر أبي بكر للقتال، فعرفت أنه الحق‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:532","bookId":"riyad","type":"hadith","num":532,"kitab":"كتاب الفضائل","isnad":"وعن أبي أيوب رضي الله عنه، أن رجلا قال للنبي صلى الله عليه وسلم ‏:‏ أخبرني بعمل يدخلني الجنة قال‏:‏ ‏","matn":"\"‏تعبد الله لا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصل الرحم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:533","bookId":"riyad","type":"hadith","num":533,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، أن أعرابيًا أتي النبي صلى الله عليه وسلم فقال‏:‏ يا رسول الله دلني على عمل إذا عملته، دخلت الجنة‏.‏ قال‏:‏ ‏","matn":"\"‏تعبد الله ولا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة المفروضة، وتصوم رمضان‏\"‏ قال‏:‏ والذي نفسي بيده، لا أزيد على هذا‏.‏ فلما ولى قال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏من سره أن ينظر إلى رجل من أهل الجنة فلينظر إلى هذا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:534","bookId":"riyad","type":"hadith","num":534,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن جرير بن عبد الله، رضي الله عنه، قال‏:‏ بايعت النبي، صلى الله عليه وسلم، على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:535","bookId":"riyad","type":"hadith","num":535,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما من صاحب ذهب، ولا فضة، لا يؤدي منها حقها إلا إذا كان يوم القيامة صفحت له صفائح من نار، فأحمي عليها في نار جهنم فيكوى بها جنبه، وجبينه، وظهره، كلما بردت أعيدت له في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين العباد فيرى سبيله، إما إلى الجنة، وإما إلى النار‏\"‏ قيل‏:‏ يا رسول الله فالإبل‏؟‏ قال‏:‏ ‏\"‏ولا صاحب إبل لا يؤدي منها حقها، ومن حقها حلبها يوم وردها، إلا إذ كان يوم القيامة بطح لها بقاع قرقر أوفر ما كانت، لا يفقد منها فصيلا واحدًا، تطؤه بأخفافها، وتعضه بأفواهها كلما مر عليه أُولاها، رد عليه أُخراها، في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين العباد، فيرى سبيله، إما إلى الجنة، وإما إلى النار‏\"‏ قيل‏:‏ يا رسول الله فالبقر والغنم‏؟‏ قال‏:‏ ‏\"‏ولا صاحب بقر ولا غنم لا يؤدي منها حقها إلا إذا كان يوم القيامة، بطح لها بقاع قرقر، لا يفقد منها شيئًا ليس فيها عقصاء، ولا جلحاء، ولا عضباء، تنطحه بقرونها، وتطؤه بأظلافها، كلما مر عليه أُولاها، رد عليه أُخراها، في يوم كان مقداره خمسين ألف سنة حتى يقضى بين العباد، فيرى سبيله، إما إلى الجنة، وإما إلى النار‏\"‏ ‏.‏ قيل‏:‏ يا رسول الله فالخيل‏؟‏ قال‏:‏ ‏\"‏الخيل ثلاثة‏:‏ هي لرجل وزر، وهي لرجل ستر، وهي لرجل أجر، فأما التي هي له وزر فرجل ربطها رياء وفخرًا ونواء على أهل الإسلام، فهي له وزر، وأما التي هي له ستر، فرجل ربطها في سبيل الله، ثم لم ينسَ حق الله في ظهورها، ولا رقابها فهي له ستر، وأما التي هي له أجر، فرجل ربطها في سبيل الله لأهل الإسلام في مرج، أو روضة، فما أكلت من ذلك المرج أو الروضة من شيء إلا كتب له عدد ما أكلت حسنات، وكتب له عدد أرواثها وأبوالها حسنات، ولا تقطع طولها فاستنت شرفًا أو شرفين إلا كتب الله له عدد آثارها، وأرواثها حسنات، ولا مر بها صاحبها على نهر فشربت منه، ولا يريد أن يسقيها إلا كتب الله له عدد ما شربت حسنات‏\"‏ والإيتار قبل النوم إنما يستحب لمن لا يثق باستيقاظ آخر الليل، فإن وثق فآخر الليل أفضل‏.‏"},{"id":"riyad:536","bookId":"riyad","type":"hadith","num":536,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏قال الله عز وجل‏:‏ كل عمل ابن آدم له إلا الصيام، فإنه لي وأنا أجزي به‏.‏ والصيام جُنة فإذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابه أحد أو قاتله، فليقل‏:‏ إني صائم‏.‏ والذي نفس محمد بيده لخُلوف فم الصائم أطيب عند الله من ريح المسك‏.‏ ‏\"‏للصائم فرحتان يفرحهما‏:‏ إذا أفطر فرح بفطره، وإذا لقي ربه فرح بصومه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏‏(‏‏(‏وهذا لفظ رواية البخاري‏.‏ وفي رواية له‏:‏ يترك طعامه، وشرابه، وشهوته، من أجلي، الصيام لي وأنا أجزي به، والحسنة بعشر أمثالها‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏كل عمل ابن آدم يضاعف‏:‏ الحسنة بعشر أمثالها إلى سبعمائة ضعف‏.‏ قال الله تعالى‏:‏ ‏(إلا الصوم فإنه لي وأنا أجزي به‏:‏ يدع شهوته وطعامه من أجلي‏.‏ للصائم فرحتان‏:‏ فرحة عند فطره، وفرحة عند لقاء ربه‏.‏ ولخلوف فيه أطيب عند الله من ريح المسك‏)‏‏.‏"},{"id":"riyad:537","bookId":"riyad","type":"hadith","num":537,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏ من أنفق زوجين في سبيل الله نودي من أبواب الجنة ‏:‏يا عبد الله هذا خير، فمن كان من أهل الصلاة دعي من باب الصلاة، ومن كان من أهل الجهاد دعي من باب الجهاد، ومن كان من أهل الصيام دعي من باب الريان، ومن كان من أهل الصدقة دعي من باب الصدقة ‏\"‏ قال أبو بكر، رضي الله عنه ‏:‏بأبي أنت وأمي يا رسول الله ما على من دعي من تلك الأبواب من ضرورة، فهل يدعى أحد من تلك الأبواب كلها‏؟‏ قال‏:‏ ‏\"‏ نعم وأرجو أن تكون منهم ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:538","bookId":"riyad","type":"hadith","num":538,"kitab":"كتاب الفضائل","isnad":"وعن سهل بن سعد رضي الله عنه عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن في الجنة بابًا يقال له‏:‏ الريان، يدخل منه الصائمون يوم القيامة لا يدخل منه أحد غيرهم يقال‏:‏ أين الصائمون‏؟‏ فيقومون لا يدخل منه أحد غيرهم، فإذا دخلوا أغلق فلم يدخل منه أحد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:539","bookId":"riyad","type":"hadith","num":539,"kitab":"كتاب الفضائل","isnad":"وعن أبي سعيد الخدري، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ ما من عبد يصوم يومًا في سبيل الله إلا باعد الله بذلك اليوم وجهه عن النار سبعين خريفًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:540","bookId":"riyad","type":"hadith","num":540,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ من صام رمضان إيمانًا واحتسابًا، غفر له ما تقدم من ذنبه ‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:541","bookId":"riyad","type":"hadith","num":541,"kitab":"كتاب الفضائل","isnad":"وعنه رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا جاء رمضان فتحت أبواب الجنة، وغلقت أبواب النار، وصفدت الشياطين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:542","bookId":"riyad","type":"hadith","num":542,"kitab":"كتاب الفضائل","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏صوموا لرؤيته، وأفطروا لرؤيته، فإن غَبِيَ عليكم فأكملوا عدة شعبان ثلاثين‏\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ البخاري‏)‏‏)‏‏.‏ وفي رواية مسلم‏:‏ ‏\"‏فإن غم عليكم فصوموا ثلاثين يومًا‏\"‏‏.‏"},{"id":"riyad:543","bookId":"riyad","type":"hadith","num":543,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنهما‏:‏ قال‏:‏ كان رسول الله صلى الله عليه وسلم أجود الناس، وكان أجود ما يكون في رمضان حين يلقاه جبريل وكان جبريل يلقاه في كل ليلة من رمضان فيدارسه القرآن فَلَرَسول الله صلى الله عليه وسلم حين يلقاه جبريل أجود بالخير من الريح المرسلة‏","matn":"\"‏ ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:544","bookId":"riyad","type":"hadith","num":544,"kitab":"كتاب الفضائل","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم إذا دخل العشر أحيا الليل وأيقظ أهله، وشد المئزر‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:545","bookId":"riyad","type":"hadith","num":545,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يتقدمن أحدكم رمضان بصوم يوم أو يومين، إلا أن يكون رجل كان يصوم صومه، فليصم ذلك اليوم‏\"‏ ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:546","bookId":"riyad","type":"hadith","num":546,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ لا تصوموا قبل رمضان صوموا لرؤيته وأفطروا لرؤيته، فإن حالت دونه فأكملوا ثلاثين يومًا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏.‏"},{"id":"riyad:547","bookId":"riyad","type":"hadith","num":547,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏إذا بقي نصف من شعبان فلا تصوموا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:548","bookId":"riyad","type":"hadith","num":548,"kitab":"كتاب الفضائل","isnad":"وعن أبي اليقظان عمار بن ياسر، رضي الله عنهما قال‏:‏ ‏","matn":"\"‏من صام اليوم الذي يشك فيه فقد عصي أبا القاسم، صلى الله عليه وسلم‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:549","bookId":"riyad","type":"hadith","num":549,"kitab":"كتاب الفضائل","isnad":"عن طلحة بن عبيد الله رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا رأى الهلال قال‏:‏ ‏","matn":"\"‏اللهم أهله علينا بالأمن والإيمان والسلامة والإسلام، ربي وربك الله، هلال رشد وخير‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:550","bookId":"riyad","type":"hadith","num":550,"kitab":"كتاب الفضائل","isnad":"عن أنس، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏تسحروا فإن في السحور بركة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:551","bookId":"riyad","type":"hadith","num":551,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن زيد بن ثابت رضي الله عنه قال‏:‏ تسحرنا مع رسول الله صلى الله عليه وسلم ثم قمنا إلى الصلاة قيل كم كان بينهما‏؟‏ قال‏:‏ خمسون آية ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:552","bookId":"riyad","type":"hadith","num":552,"kitab":"كتاب الفضائل","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كان لرسول الله صلى الله عليه وسلم مؤذنان‏:‏ بلال وابن أم مكتوم‏.‏ فقال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ إن بلالا يؤذن بليل فكلوا واشربوا حتى يؤذن ابن أم مكتوم‏\"‏ قال ولم يكن بينهما إلا أن ينزل هذا ويرقى هذا، ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:553","bookId":"riyad","type":"hadith","num":553,"kitab":"كتاب الفضائل","isnad":"وعن عمرو بن العاص رضي الله عنه أن رسول الله قال‏:‏ ‏","matn":"\"‏فصل ما بين صيامنا وصيام أهل الكتاب أكلة السحر‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:554","bookId":"riyad","type":"hadith","num":554,"kitab":"كتاب الفضائل","isnad":"عن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يزال الناس بخير ما عجلوا الفطر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:555","bookId":"riyad","type":"hadith","num":555,"kitab":"كتاب الفضائل","isnad":"وعن أبي عطية قال‏:‏ دخلت أنا ومسروق على عائشة رضي الله عنها فقال لها مسروق‏:‏ رجلان من أصحاب محمد صلى الله عليه وسلم كلاهما لا يألو عن الخير‏:‏ أحدهما يعجل المغرب والإفطار، والآخر يؤخر المغرب والإفطار‏؟‏ فقالت‏:‏ من يعجل المغرب والإفطار‏؟‏ قال‏:‏ عبد الله - يعني ابن مسعود- فقالت‏:‏ هكذا كان رسول الله صلى الله عليه وسلم يصنع‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:556","bookId":"riyad","type":"hadith","num":556,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم قال الله عز وجل‏:‏ ‏","matn":"\"‏أحب عبادي إلي أعجلهم فطرًا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:557","bookId":"riyad","type":"hadith","num":557,"kitab":"كتاب الفضائل","isnad":"وعن عمر بن الخطاب، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا أقبل الليل من ههنا وأدبر النهار من ههنا، وغربت الشمس، فقد أفطر الصائم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:558","bookId":"riyad","type":"hadith","num":558,"kitab":"كتاب الفضائل","isnad":"وعن أبي إبراهيم عبد الله بن أبي أوفى، رضي الله عنهما قال‏:‏ سرنا مع رسول الله صلى الله عليه وسلم وهو صائم فلما غربت الشمس قال لبعض القوم‏:‏ ‏","matn":"\"‏يا فلان انزل فاجدح لنا، فقال‏:‏ يا رسول الله لو أمسيت‏؟‏ قال‏:‏ ‏\"‏انزل فاجدح لنا‏\"‏ قال‏:‏ إن عليك نهارًا، قال‏:‏ ‏\"‏انزل فاجدح لنا‏\"‏ قال‏:‏ فنزل فجدح لهم فشرب رسول الله صلى الله عليه وسلم ثم قال‏:‏ ‏\"‏إذا رأيتم الليل قد أقبل من ههنا، فقد أفطر الصائم‏\"‏ وأشار بيده قبل المشرق‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:559","bookId":"riyad","type":"hadith","num":559,"kitab":"كتاب الفضائل","isnad":"وعن سلمان بن عامر الضبي الصحابي، رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أفطر أحدكم، فليفطر على تمر فإن لم يجد فليفطر على ماء فإنه طهور‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:560","bookId":"riyad","type":"hadith","num":560,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أنس رضي الله عنه قال كان رسول الله صلى الله عليه وسلم يفطر قبل أن يصلي على رطبات، فإن لم تكن رطبات فتميرات فإن لم تكن تميرات حسا حسوات من ماء‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:561","bookId":"riyad","type":"hadith","num":561,"kitab":"كتاب الفضائل","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابه أحد أو قاتله، فليقل‏:‏ إني صائم‏\"‏"},{"id":"riyad:562","bookId":"riyad","type":"hadith","num":562,"kitab":"كتاب الفضائل","isnad":"وعنه قال‏:‏ قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من لم يدع قول الزور والعمل به فليس لله حاجة في أن يدع طعامه وشرابه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:563","bookId":"riyad","type":"hadith","num":563,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا نسي أحدكم فأكل أو شرب فليتم صومه فإنما أطعمه الله وسقاه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:564","bookId":"riyad","type":"hadith","num":564,"kitab":"كتاب الفضائل","isnad":"وعن لقيط بن صبرة رضي الله عنه قال قلت يا رسول الله أخبرني عن الوضوء‏؟‏ قال‏","matn":"\"‏ ‏\"‏أسبغ الوضوء، وخلل بين الأصابع، وبالغ في الاستنشاق، إلا أن تكون صائمًا‏\"‏ ‏(‏‏(‏رواه أبوداود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:565","bookId":"riyad","type":"hadith","num":565,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يدركه الفجر وهو جنب من أهله ثم يغتسل ويصوم ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:566","bookId":"riyad","type":"hadith","num":566,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة وأم سلمة رضي الله عنهما قالتا‏:‏ كان رسول الله صلى الله عليه وسلم يصبح جنبًا من غير حلم ثم يصوم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:567","bookId":"riyad","type":"hadith","num":567,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أفضل الصيام بعد رمضان‏:‏ شهر الله المحرم، وأفضل الصلاة بعد الفريضة‏:‏ صلاة الليل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:568","bookId":"riyad","type":"hadith","num":568,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت لم يكن النبي صلى الله عليه وسلم يصوم من شهر أكثر من شعبان فإنه كان يصوم شعبان كله وفي رواية‏:‏ كان يصوم شعبان إلا قليلا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:569","bookId":"riyad","type":"hadith","num":569,"kitab":"كتاب الفضائل","isnad":"وعن مجيبة الباهلية عن أبيها أو عمها، أنه أتى رسول الله صلى الله عليه وسلم ثم انطلق فأتاه بعد سنة وقد تغيرت حاله وهيئته، فقال‏:‏ يا رسول الله أما تعرفني‏؟‏ قال‏:‏ ‏","matn":"\"‏ومن أنت‏؟‏‏\"‏ قال‏:‏ أنا الباهلي الذي جئتك عام الأول‏.‏ قال‏:‏ ‏\"‏فما غيرك، وقد كنت حسن الهيئة‏؟‏‏\"‏ قال‏:‏ ما أكلت طعامًا منذ فارقتك إلا بليل‏.‏ فقال رسول الله صلى الله عليه وسلم ‏\"‏عذبت نفسك‏!‏‏\"‏ ثم قال‏:‏ ‏\"‏صم شهر الصبر، ويومًا من كل شهر‏\"‏ قال‏:‏ زدني، فإن بي قوة، قال‏:‏ ‏\"‏ صم يومين‏\"‏ قال‏:‏ زذني، قال‏:‏ ‏\"‏صم ثلاثة أيام‏\"‏ قال‏:‏ زدني‏.‏ قال‏:‏ ‏\"‏صم من الحرم واترك، صم من الحرم واترك، صم من الحرم واترك‏\"‏ وقال بأصابعه الثلاث فضمها، ثم أرسلها‏.‏ ‏(‏‏(‏رواه أبو داود‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:570","bookId":"riyad","type":"hadith","num":570,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ ما من أيام العمل الصالح فيها أحب إلى الله من هذه الأيام‏\"‏ يعني أيام العشر، قالوا‏:‏ يا رسول الله ولا الجهاد في سبيل الله‏؟‏ قال‏:‏ ‏\"‏ولا الجهاد في سبيل الله، إلا رجل خرج بنفسه، وماله فلم يرجع من ذلك بشيء‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:571","bookId":"riyad","type":"hadith","num":571,"kitab":"كتاب الفضائل","isnad":"وعن أبي قتادة رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم‏:‏ عن صوم يوم عرفة‏؟‏ قال‏:‏ ‏","matn":"\"‏يكفر السنة الماضية والباقية‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:572","bookId":"riyad","type":"hadith","num":572,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم صام يوم عاشوراء، وأمر بصيامه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:573","bookId":"riyad","type":"hadith","num":573,"kitab":"كتاب الفضائل","isnad":"وعن أبي قتادة رضي الله عنه أن رسول الله صلى الله عليه وسلم سئل عن صيام يوم عاشوراء فقال‏:‏ ‏","matn":"\"‏يكفر السنة الماضية‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:574","bookId":"riyad","type":"hadith","num":574,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لئن بقيت إلى قابل لأصومن التاسع‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:575","bookId":"riyad","type":"hadith","num":575,"kitab":"كتاب الفضائل","isnad":"عن أبي أيوب رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من صام رمضان ثم أتبعه بست من شوال كان كصيام الدهر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:576","bookId":"riyad","type":"hadith","num":576,"kitab":"كتاب الفضائل","isnad":"عن أبي قتادة رضي الله عنه أن رسول الله صلى الله عليه وسلم‏:‏ سئل عن صوم يوم الاثنين فقال‏:‏ ‏","matn":"\"‏ذلك يوم ولدت فيه، ويوم بعثت أو أنزل علي فيه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:577","bookId":"riyad","type":"hadith","num":577,"kitab":"كتاب الفضائل","isnad":"وعن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ تعرض الأعمال يوم الاثنين والخميس، فأحب أن يعرض عملي وأنا صائم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن، ورواه مسلم بغير ذكر الصوم‏)‏‏)‏‏.‏"},{"id":"riyad:578","bookId":"riyad","type":"hadith","num":578,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يتحرى صوم الاثنين والخميس‏.‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:579","bookId":"riyad","type":"hadith","num":579,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أبي هريرة رضي الله عنه قال‏:‏ أوصاني خليلي صلى الله عليه وسلم بثلاث‏:‏ صيام ثلاثة أيام من كل شهر، وركعتي الضحى وأن أوتر قبل أن أنام‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:580","bookId":"riyad","type":"hadith","num":580,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن أبي الدرداء رضي الله عنه قال‏:‏ أوصاني حبيبي، صلى الله عليه وسلم بثلاث لن أدعهن ما عشت‏:‏ بصيام ثلاثة أيام من كل شهر، وصلاة الضحى، وبأن لا أنام حتى أوتر‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:581","bookId":"riyad","type":"hadith","num":581,"kitab":"كتاب الفضائل","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال‏:‏ قال رسول الله‏:‏ ‏","matn":"\"‏صوم ثلاثة أيام من كل شهر صوم الدهر كله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:582","bookId":"riyad","type":"hadith","num":582,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن معاذة العدوية أنها سألت عائشة رضي الله عنها‏:‏ أكان رسول الله صلى الله عليه وسلم يصوم من كل شهر ثلاثة أيام، فقالت‏:‏ نعم‏.‏ فقلت‏:‏ من أي الشهر كان يصوم‏؟‏ قالت‏:‏ لم يكن يبالي من أي الشهر يصوم‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:583","bookId":"riyad","type":"hadith","num":583,"kitab":"كتاب الفضائل","isnad":"وعن أبي ذر رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا صمت من الشهر ثلاثًا، فصم ثلاث عشرة، وأربع عشرة وخمس عشرة‏\"‏ رواه الترمذي وقال‏:‏ حديث حسن‏.‏"},{"id":"riyad:584","bookId":"riyad","type":"hadith","num":584,"kitab":"كتاب الفضائل","isnad":"","matn":"وعن قتادة بن ملحان، رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم يأمرنا بصيام أيام البيض‏:‏ ثلاث عشرة، وأربع شعرة وخمس عشرة‏.‏ ‏(‏‏(‏رواه أبو داود‏.‏"},{"id":"riyad:585","bookId":"riyad","type":"hadith","num":585,"kitab":"كتاب الفضائل","isnad":"وعن ابن عباس، رضي الله عنهما، قال‏:‏ كان رسول الله صلى الله عليه وسلم ‏","matn":"\"‏لا يفطر أيام البيض في حضر ولا سفر‏\"‏ ‏(‏‏(‏رواه النسائي بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:586","bookId":"riyad","type":"hadith","num":586,"kitab":"كتاب الفضائل","isnad":"عن زيد بن خالد الجهني، رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من فطر صائمًا، كان له مثل أجره غير أنه لا ينقص من أجر الصائم شيء‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:587","bookId":"riyad","type":"hadith","num":587,"kitab":"كتاب الفضائل","isnad":"وعن أم عمارة الأنصارية، رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها فقدمت إليه طعامًا فقال ‏","matn":"\"‏ كلي‏\"‏ فقالت‏:‏ إني صائمة، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏إن الصائم تصلي عليه الملائكة إذا أكل عنده حتى يفرغوا‏\"‏ وربما قال‏:‏ ‏\"‏حتى يشبعوا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:588","bookId":"riyad","type":"hadith","num":588,"kitab":"كتاب الفضائل","isnad":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم جاء إلى سعد بن عبادة رضي الله عنه فجاء بخبز وزيت، فأكل ثم قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أفطر عندكم الصائمون وأكل طعامكم الأبرار وصلت عليكم الملائكة‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:589","bookId":"riyad","type":"hadith","num":589,"kitab":"كتاب الاعتكاف","isnad":"","matn":"عن ابن عمر رضي الله عنهما، قال‏:‏ كان رسول الله صلى الله عليه وسلم يعتكف العشر الأواخر من رمضان‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:590","bookId":"riyad","type":"hadith","num":590,"kitab":"كتاب الاعتكاف","isnad":"","matn":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يعتكف العشر الأواخر من رمضان، حتى توفاه الله، تعالى ثم اعتكف أزواجه من بعده‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:591","bookId":"riyad","type":"hadith","num":591,"kitab":"كتاب الاعتكاف","isnad":"","matn":"وعن أبي هريرة رضي الله عنه قال‏:‏ كان النبي صلى الله عليه وسلم يعتكف في كل رمضان عشرة أيام، فلما كان العام الذي قبض فيه اعتكف عشرين يومًا ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:592","bookId":"riyad","type":"hadith","num":592,"kitab":"كتاب الحج","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ بني الإسلام على خمس‏:‏ شهادة أن لا إله إلى الله وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:593","bookId":"riyad","type":"hadith","num":593,"kitab":"كتاب الحج","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ خطبنا رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏يا أيها الناس إن الله قد فرض عليكم الحج فحجوا‏\"‏ فقال رجل‏:‏ أكل عام يا رسول الله‏؟‏ فسكت، حتى قالها ثلاثًا فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏لو قلت نعم لوجبت، ولما استطعتم‏\"‏ ثم قال‏:‏ ‏\"‏ذروني ما تركتكم، فإنما هلك من كان قبلكم بكثرة سؤالهم، واختلافهم على أنبيائهم، فإذا أمرتكم بشيء فأتوا منه ما استطعتم، وإذا نهيتكم عن شيء فدعوه‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:594","bookId":"riyad","type":"hadith","num":594,"kitab":"كتاب الحج","isnad":"وعنه قال‏:‏ سئل النبي صلى الله عليه وسلم أي العمل أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏إيمان بالله ورسوله‏\"‏ قيل‏:‏ ثم ماذا‏؟‏ قال‏:‏ ‏\"‏الجهاد في سبيل الله‏\"‏ قيل ثم ماذا‏؟‏ قال‏:‏ ‏\"‏حج مبرور‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏\"‏المبرور‏\"‏ هو الذي لا يرتكب صاحبه فيه معصية‏.‏"},{"id":"riyad:595","bookId":"riyad","type":"hadith","num":595,"kitab":"كتاب الحج","isnad":"وعنه قال سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من حج، فلم يرفث ولم يفسق، رجع كيوم ولدته أمه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:596","bookId":"riyad","type":"hadith","num":596,"kitab":"كتاب الحج","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:597","bookId":"riyad","type":"hadith","num":597,"kitab":"كتاب الحج","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قلت يا رسول الله نرى الجهاد أفضل العمل، أفلا نجاهد‏؟‏ فقال‏:‏ ‏:‏ ‏","matn":"\"‏لَكُنّ أفضل الجهاد حج مبرور‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:598","bookId":"riyad","type":"hadith","num":598,"kitab":"كتاب الحج","isnad":"وعنها أن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏ما من يوم أكثر من أن يعتق الله فيه عبدًا من النار من يوم عرفة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:599","bookId":"riyad","type":"hadith","num":599,"kitab":"كتاب الحج","isnad":"وعن ابن عباس رضي الله عنهما، أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏عمرة في رمضان تعدل عمرة أو حجة معي‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:600","bookId":"riyad","type":"hadith","num":600,"kitab":"كتاب الحج","isnad":"وعنه أن امرأة قالت‏:‏ يا رسول الله إن فريضة الله على عباده في الحج، أدركت أبي شيخًا كبيرًا، لا يثبت على الراحلة، أفأحج عنه‏؟‏ قال‏:‏ ‏","matn":"\"‏نعم‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:601","bookId":"riyad","type":"hadith","num":601,"kitab":"كتاب الحج","isnad":"وعن لقيط بن عامر رضي الله عنه أنه أتى النبي صلى الله عليه وسلم فقال‏:‏ إن أبي شيخ كبير لا يستطيع الحج ولا العمرة، ولا الظعن قال‏:‏ ‏","matn":"\"‏حج عن أبيك واعتمر‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:602","bookId":"riyad","type":"hadith","num":602,"kitab":"كتاب الحج","isnad":"","matn":"وعن السائب بن يزيد رضي الله عنه، قال‏:‏ حج بي مع رسول الله صلى الله عليه وسلم في حجة الوداع وأنا ابن سبع سنين‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:603","bookId":"riyad","type":"hadith","num":603,"kitab":"كتاب الحج","isnad":"وعن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم لقي ركبا بالروحاء فقال‏:‏ ‏","matn":"\"‏من القوم‏؟‏‏\"‏ قالوا‏:‏ المسلمون‏.‏ قالوا من أنت‏؟‏ قال‏:‏ ‏\"‏رسول الله‏\"‏ فرفعت امرأة صبيًا فقالت‏:‏ ألهذا حج‏؟‏ قال ‏\"‏نعم ولك أجر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:604","bookId":"riyad","type":"hadith","num":604,"kitab":"كتاب الحج","isnad":"","matn":"وعن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم حج على رحل وكانت زاملته‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:605","bookId":"riyad","type":"hadith","num":605,"kitab":"كتاب الحج","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال‏:‏ كانت عكاظ ومجنة، وذو المجاز أسواقًا في الجاهلية، فتأثموا أن يتجروا في المواسم، فنزلت‏:‏ ‏{‏ليس عليكم جناح أن تبتغوا فضلا من ربكم‏}‏ ‏(‏‏(‏البقرة‏:‏ 198‏)‏‏)‏ في مواسم الحج‏.‏‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:606","bookId":"riyad","type":"hadith","num":606,"kitab":"كتاب الجهاد","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم أي العمل أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏إيمان بالله ورسوله‏\"‏ قيل‏:‏ ثم ماذا‏؟‏ قال‏:‏ ‏\"‏الجهاد في سبيل الله‏\"‏ قيل‏:‏ ثم ماذا‏؟‏ قال‏:‏ ‏\"‏حج مبرور‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:607","bookId":"riyad","type":"hadith","num":607,"kitab":"كتاب الجهاد","isnad":"وعن ابن مسعود، رضي الله عنه قال‏:‏ قلت يا رسول الله أي العمل أحب إلى الله تعالى‏؟‏ قال‏:‏ ‏","matn":"\"‏الصلاة على وقتها‏\"‏ قلت‏:‏ ثم أي‏؟‏ قال‏:‏ ‏\"‏بر الوالدين‏\"‏ قلت ثم أي‏:‏ قال‏:‏ ‏\"‏الجهاد في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:608","bookId":"riyad","type":"hadith","num":608,"kitab":"كتاب الجهاد","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قلت يا رسول الله أي العمل أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏الإيمان بالله والجهاد في سبيله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:609","bookId":"riyad","type":"hadith","num":609,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لغدوة في سبيل الله أو روحة خير من الدنيا وما فيها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:610","bookId":"riyad","type":"hadith","num":610,"kitab":"كتاب الجهاد","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ أتى رجل رسول الله صلى الله عليه وسلم فقال‏:‏ أي الناس أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏مؤمن يجاهد بنفسه وماله في سبيل الله‏\"‏ قال‏:‏ ثم من‏؟‏ قال‏:‏ ‏\"‏مؤمن في شعب من الشعاب يعبد الله ويدع الناس من شره‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:611","bookId":"riyad","type":"hadith","num":611,"kitab":"كتاب الجهاد","isnad":"وعن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏رباط يوم في سبيل الله خير من الدنيا وما عليها، وموضع سوط أحدكم من الجنة خير من الدنيا وما عليها، والروحة يروحها العبد في سبيل الله تعالى، أو الغدوة خير من الدنيا وما عليها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:612","bookId":"riyad","type":"hadith","num":612,"kitab":"كتاب الجهاد","isnad":"وعن سلمان رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏رباط يوم وليلة خير من صيام شهر وقيامه، وإن مات فيه أجري عليه عمله الذي كان يعمل، وأجري عليه رزقه، وأمن الفتان‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:613","bookId":"riyad","type":"hadith","num":613,"kitab":"كتاب الجهاد","isnad":"وعن فضالة بن عبيد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كل ميت يختم على عمله إلا المرابط في سبيل الله فإنه ينمى له عمله إلى يوم القيامة، ويؤمن فتنة القبر” ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:614","bookId":"riyad","type":"hadith","num":614,"kitab":"كتاب الجهاد","isnad":"وعن عثمان رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏رباط يوم في سبيل الله خير من ألف يوم فيما سواه من المنازل‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:615","bookId":"riyad","type":"hadith","num":615,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏تضمن الله لمن خرج في سبيله لا يخرجه إلا جهاد في سبيلي، وإيمان بي وتصديق برسلي فهو علي ضامن أن أدخله الجنة، أو أرجعه إلى منزله الذي خرج منه بما نال من أجر، أو غنيمة، والذي نفس محمد بيده ما من كلم يكلم في سبيل الله إلا جاء يوم القيامة كهيئته يوم كلم، لونه لون دم، وريحه ريح مسك، والذي نفس محمد بيده لولا أن يشق على المسلمين ما قعدت خلاف سرية تغزو في سبيل الله أبدا، ولكن لا أجد سعة فأحملهم ولا يجدون سعة عليهم أن يتخلفوا عني، والذي نفس محمد بيده لوددت أن أغزو في سبيل الله فأقتل، ثم أغزو فأقتل ثم أغزو فأقتل‏\"‏ ‏(‏‏(‏رواه مسلم وروى البخاري بعضه‏)‏‏)‏‏.‏ ‏(‏‏(‏‏\"‏الكلم‏\"‏ الجرح‏.‏‏)‏‏)‏"},{"id":"riyad:616","bookId":"riyad","type":"hadith","num":616,"kitab":"كتاب الجهاد","isnad":"وعنه قال‏:‏ قال‏:‏ رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ما من مكلوم يكلم في سبيل الله إلا جاء يوم القيامة، وكلمه يدمي اللون لون دم، والريح ريح مسك‏:‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:617","bookId":"riyad","type":"hadith","num":617,"kitab":"كتاب الجهاد","isnad":"وعن معاذ رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قاتل في سبييل الله من رجل مسلم فواق ناقة وجبت له الجنة، ومن جرح جرحًا في سبيل الله أو نكب نكبة فإنها تجيء يوم القيامة كأغزر ما كانت‏:‏ لونها الزعفران، وريحها كالمسك‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:618","bookId":"riyad","type":"hadith","num":618,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ مر رجل من أصحاب رسول الله صلى الله عليه وسلم بشعب فيه عيينة من ماء عذبة فأعجبته، فقال‏:‏ لو اعتزلت الناس فأقمت في هذا الشعب، ولن أفعل حتى استأذن رسول الله صلى الله عليه وسلم فذكر ذلك لرسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏لا تفعل فإن مقام أحدكم في سبيل الله أفضل من صلاته في بيته سبعين عامًا، ألا تحبون أن يغفر الله لكم ويدخلكم الجنة‏؟‏ اغزو في سبيل الله من قاتل في سبيل الله فواق ناقة وجبت له الجنة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ ‏(‏‏(‏‏\"‏والفواق‏\"‏‏:‏ ما بين الحلبتين‏)‏‏)‏‏.‏"},{"id":"riyad:619","bookId":"riyad","type":"hadith","num":619,"kitab":"كتاب الجهاد","isnad":"وعنه قال قيل يا رسول الله‏:‏ ما يعدل الجهاد في سبيل الله‏؟‏ قال‏:‏ ‏","matn":"\"‏لاتستطيعونه‏\"‏ فأعادوا عليه مرتين أو ثلاثًا كل ذلك يقول‏:‏ ‏\"‏لاتستطيعونه‏!‏‏\"‏ ثم قال‏:‏ ‏\"‏مثل المجاهد في سبيل الله كمثل الصائم القائم القانت بآيات الله لا يفتر‏:‏ من صلاة ولا صيام، حتى يرجع المجاهد في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه، وهذا لفظ مسلم‏)‏‏)‏ ‏.‏ وفي رواية البخاري، أن رجلا قال‏:‏ يا رسول الله دلني على عمل يعدل الجهاد‏؟‏ قال‏:‏ ‏\"‏لا أجده‏\"‏ ثم قال‏:‏ ‏\"‏هل تستطيع إذا خرج المجاهد أن تدخل مسجدك فتقوم ولا تفتر وتصوم ولا تفطر‏؟‏ فقال‏:‏ ومن يستطيع ذلك‏؟‏‏!‏‏.‏"},{"id":"riyad:620","bookId":"riyad","type":"hadith","num":620,"kitab":"كتاب الجهاد","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من خير معاش الناس لهم رجل ممسك بعنان فرسه في سبيل الله، يطير على متنه كلما سمع هيعة، أو فزعة طار على متنه، يبتغي القتل أو الموت مظانه، أو رجل في غنيمة أو شعفة من هذه الشعف أو بطن واد من هذه الأودية يقيم الصلاة ويؤتي الزكاة، ويعبد ربه حتى يأتيه اليقين ليس من الناس إلا في خير‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:621","bookId":"riyad","type":"hadith","num":621,"kitab":"كتاب الجهاد","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن في الجنة مائة درجة أعدها للمجاهدين في سبيل الله ما بين الدرجتين كما بين السماء والأرض‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:622","bookId":"riyad","type":"hadith","num":622,"kitab":"كتاب الجهاد","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من رضي بالله ربًا وبالإسلام دينًا، وبمحمد رسولا وجبت له الجنة‏\"‏ فعجب لها أبو سعيد فقال أعدها علي يا رسول الله فأعادها عليه ثم قال‏:‏ ‏\"‏وأخرى يرفع الله بها العبد مائة درجة في الجنة، ما بين كل درجتين، كما بين السماء والأرض‏\"‏ قال‏:‏ وما هي يا رسول الله‏؟‏ قال‏:‏ ‏\"‏الجهاد في سبيل الله، الجهاد في سبيل الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:623","bookId":"riyad","type":"hadith","num":623,"kitab":"كتاب الجهاد","isnad":"وعن أبي بكر بن أبي موسى الأشعري، قال‏:‏ سمعت أبي رضي الله عنه وهو بحضرة العدو، يقول قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏إن أبواب الجنة تحت ظلال السيوف‏\"‏ فقام رجل رث الهيئة فقال يا أبا موسى أأنت سمعت رسول الله صلى الله عليه وسلم يقول هذا‏؟‏ قال‏:‏ نعم، فرجع إلى أصحابه، فقال‏:‏ ‏\"‏اقرأ عليكم السلام‏\"‏ ثم كسر جفن سيفه فألقاه، ثم مشى بسيفه إلى العدو فضرب به حتى قتل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:624","bookId":"riyad","type":"hadith","num":624,"kitab":"كتاب الجهاد","isnad":"وعن أبي عبس عبد الرحمن بن جبير، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما اغبرت قدما عبد في سبيل الله فتمسه النار‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:625","bookId":"riyad","type":"hadith","num":625,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا يلج النار رجل بكي من خشية الله حتى يعود اللبن في الضرع، ولا يجتمع على عبد غبار في سبيل الله ودخان جهنم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:626","bookId":"riyad","type":"hadith","num":626,"kitab":"كتاب الجهاد","isnad":"وعن ابن عباس، رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “عينان لا تمسهما النار عين بكت من خشية الله، وعين باتت تحرس في سبيل الله‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:627","bookId":"riyad","type":"hadith","num":627,"kitab":"كتاب الجهاد","isnad":"وعن زيد بن خالد، رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من جهز غازيًا في سبيل الله فقد غزا ومن خلف غازيا في أهله بخير فقد غزا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:628","bookId":"riyad","type":"hadith","num":628,"kitab":"كتاب الجهاد","isnad":"وعن أبي أمامة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أفضل الصدقات ظل فسطاط في سبيل الله، ومنيحة خادم في سبيل الله، أو طروقة فحل في سبيل الله‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:629","bookId":"riyad","type":"hadith","num":629,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه أن فتى من أسلم قال‏:‏ يا رسول الله إني أريد الغزو وليس معي ما أتجهز به، قال‏:‏ ‏","matn":"\"‏ائت فلانًا، قد كان تجهز فمرض فأتاه فقال‏:‏ إن رسول الله صلى الله عليه وسلم يقرئك السلام ويقول‏:‏ أعطني الذي تجهزت به قال‏:‏ يا فلانة أعطيه، الذي كنت تجهزت به ولاتحبسي منه شيئًا فوالله لا تحبسي منه شيئًا فيبارك لك فيه ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:630","bookId":"riyad","type":"hadith","num":630,"kitab":"كتاب الجهاد","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم بعث إلى بني لحيان، فقال‏:‏ ‏","matn":"\"‏لا ينبعث من كل رجلين أحدهما، والأجر بينهما‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:631","bookId":"riyad","type":"hadith","num":631,"kitab":"كتاب الجهاد","isnad":"وعن البراء رضي الله عنه قال أتى النبي صلى الله عليه وسلم رجل مقنع بالحديد، فقال يا رسول الله أقاتل أو أسلم‏؟‏ قال‏:‏ ‏","matn":"\"‏أسلم، ثم قاتل‏\"‏ فأسلم، ثم قاتل فقتل، فقال رسول الله صلى الله عليه وسلم ‏:‏ عمل قليلا وأُجر كثيرًا‏\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ البخاري‏)‏‏)‏ ‏.‏"},{"id":"riyad:632","bookId":"riyad","type":"hadith","num":632,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما أحد يدخل الجنة يحب أن يرجع إلى الدنيا وله ما على الأرض من شيء إلا الشهيد، يتمنى أن يرجع إلى الدنيا فيقتل عشر مرات لما يرى من الكرامة”"},{"id":"riyad:633","bookId":"riyad","type":"hadith","num":633,"kitab":"كتاب الجهاد","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يغفر الله للشهيد كل شيء إلا الدين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:634","bookId":"riyad","type":"hadith","num":634,"kitab":"كتاب الجهاد","isnad":"وعن أبي قتادة رضي الله عنه أن رسول الله صلى الله عليه وسلم قام فيهم فذكر أن الجهاد في سبيل الله والإيمان بالله أفضل الأعمال فقام رجل فقال يا رسول الله أرأيت إن قتلت في سبيل الله أتكفر عني خطاياي‏؟‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏نعم إن قتلت في سبيل الله وأنت صابر محتسب مقبل غير مدبر‏\"‏ ثم قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏كيف قلت‏؟‏‏\"‏ قال‏:‏ أرأيت إن قتلت في سبيل الله أتكفر عني خطاياي‏؟‏ فقال رسول الله صلى الله عليه وسلم ‏\"‏نعم وأنت صابر محتسب مقبل غير مدبر إلا الدين فإن جبريل عليه السلام قال لي ذلك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:635","bookId":"riyad","type":"hadith","num":635,"kitab":"كتاب الجهاد","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال رجل‏:‏ أين أنا يا رسول الله إن قتلت‏؟‏ قال‏:‏ “في الجنة‏","matn":"\"‏ فألقى تمرات كن في يده ثم قاتل حتى قتل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:636","bookId":"riyad","type":"hadith","num":636,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه قال انطلق رسول الله صلى الله عليه وسلم وأصحابه حتى سبقوا المشركين إلى بدر وجاء المشركون، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يقدمن أحد منكم إلى شيء حتى أكون أنا دونه‏\"‏ فدنا المشركون، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏قوموا إلى جنة عرضها السماوات والأرض‏\"‏ قال‏:‏ يقول عمير بن الحمام الأنصاري رضي الله عنه‏:‏ يا رسول الله جنة عرضها السماوات والأرض‏؟‏ قال‏:‏ ‏\"‏نعم‏\"‏ قال‏:‏ بخ بخ‏!‏ فقال رسول الله صلى الله عليه وسلم‏:‏ “ما يحملك على قولك بخ بخ‏\"‏ قال فإنك من أهلها فأخرج تمرات من قرنه فجعل يأكل منهن، ثم قال لئن أنا حييت حتى آكل تمراتي هذه إنها لحياة طويلة‏!‏ فرمى بما كان معه من التمر، ثم قاتلهم حتى قتل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ (4)"},{"id":"riyad:637","bookId":"riyad","type":"hadith","num":637,"kitab":"كتاب الجهاد","isnad":"وعنه قال‏:‏ جاء ناس إلى النبي صلى الله عليه وسلم أن ابعث معنا رجالا يعلمونا القرآن والسنة فبعث إليهم سبعين رجلا من الأنصار يقال لهم‏:‏ القراء، فيهم خالي حرام، يقرءون القرآن ويتدارسونه بالليل يتعلمون، وكانوا بالنهار يجيئون بالماء فيضعونه في المسجد، ويحتطبون فيبيعونه، ويشترون به الطعام لأهل الصفة، وللفقراء فبعثهم صلى الله عليه وسلم فعرضوا لهم فقتلوهم قبل أن يبلغوا المكان، فقالوا‏:‏ اللهم بلغ عنا نبينا أن قد لقيناك فرضينا عنك ورضيت عنا، وأتى رجل حراما خال أنس من خلف فطعنه برمح حتى أنفذه، فقال حرام‏:‏ فزت ورب الكعبة، فقال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏إن إخوانكم قد قتلوا وإنهم قالوا‏:‏ اللهم بلغ عنا نبينا أنا قد لقيناك فرضينا عنك ورضيت عنا‏\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:638","bookId":"riyad","type":"hadith","num":638,"kitab":"كتاب الجهاد","isnad":"","matn":"وعنه قال‏:‏ غاب عمي أنس بن النضر رضي الله عنه عن قتال بدر، فقال‏:‏ يا رسول الله غبت عن أول قتال قاتلت الشركين لئن الله أشهدني قتال المشركين ليرين الله ما أصنع‏.‏ فلما كان يوم أحد انكشف المسلمون، فقال اللهم إني اعتذر إليك مما صنع هؤلاء - يعني الصحابة- وأبرأ إليك مما صنع هؤلاء يعني المشركين- ثم تقدم فاستقبله سعد بن معاذ فقال‏:‏ يا سعد بن معاذ الجنة ورب النضر، إني أجد ريحها من دون أحد‏!‏ قال سعد‏:‏ فما استطعت يا رسول الله ما صنع‏!‏ قال أنس‏:‏ فوجدنا به بضعًا وثمانين ضربة بالسيف، أو طعنة برمح أو رمية بسهم، ووجدناه قد قتل ومثل به المشركون، فما عرفه أحد إلا أخته ببنانه، قال أنس‏:‏ كنا نرى -أو نظن- أن هذه الآية نزلت فيه وفي أشباهه‏:‏ ‏{‏من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه‏}‏ إلى آخره ‏(‏‏(‏الأحزاب 23‏)‏‏)‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وقد سبق في باب المجاهدة‏.‏"},{"id":"riyad:639","bookId":"riyad","type":"hadith","num":639,"kitab":"كتاب الجهاد","isnad":"وعن سمرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “رأيت الليلة رجلين أتياني فصعدا بي الشجرة وأدخلاني دارًا هي أحسن وأفضل، لم أر قط أحسن منها، قال أما هذه الدار فدار الشهداء‏","matn":"\"‏ (5)"},{"id":"riyad:640","bookId":"riyad","type":"hadith","num":640,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه أن أم الربيع بنت البراء وهي أم حارثة بن سراقة أتت النبي صلى الله عليه وسلم فقالت‏:‏ يا رسول الله ألا تحدثني عن حارثة‏.‏ وكان قتل يوم بدر، فإن كان في الجنة صبرت، وإن كان غير ذلك اجتهدت عليه في البكاء، فقال‏:‏ ‏","matn":"\"‏يا أم حارثة إنها جنان في الجنة، وإن ابنك أصاب الفردوس الأعلى‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:641","bookId":"riyad","type":"hadith","num":641,"kitab":"كتاب الجهاد","isnad":"وعن جابر بن عبد الله رضي الله عنهما قال‏:‏ جيء بأبي إلى النبي صلى الله عليه وسلم قد مثل به فوضع بين يديه، فذهبت أكشف عن وجهه فنهاني قوم فقال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما زالت الملائكة تظله بأجنحتها” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:642","bookId":"riyad","type":"hadith","num":642,"kitab":"كتاب الجهاد","isnad":"وعن سهل بن حنيف رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من سأل الله تعالى الشهادة بصدق بلغه الله منازل الشهداء وإن مات على فراشه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:643","bookId":"riyad","type":"hadith","num":643,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من طلب الشهادة صادقًا أعطيها ولو لم تصبه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:644","bookId":"riyad","type":"hadith","num":644,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما يجد الشهيد من مس القتل إلا كما يجد أحدكم من مس القرصة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:645","bookId":"riyad","type":"hadith","num":645,"kitab":"كتاب الجهاد","isnad":"وعن عبد الله بن أبي أوفى رضي الله عنهما أن رسول الله صلى الله عليه وسلم في بعض أيامه التي لقي فيها العدو انتظر حتى مالت الشمس، ثم قام في الناس فقال‏:‏ ‏","matn":"\"‏ أيها الناس، لا تتمنوا لقاء العدو، وسلو الله العافية، فإذا لقيتموه فاصبروا، واعلموا أن الجنة تحت ظلال السيوف‏\"‏ ثم قال‏:‏ ‏\"‏اللهم منزل الكتاب ومجري السحاب، وهازم الأحزاب اهزمهم وانصرنا عليهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:646","bookId":"riyad","type":"hadith","num":646,"kitab":"كتاب الجهاد","isnad":"وعن سهل بن سعد رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ثنتان لا تردان، أو قلما تردان‏:‏ الدعاء عند النداء وعند البأس حين يلحم بعضهم بعضًا‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:647","bookId":"riyad","type":"hadith","num":647,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا غزا قال‏:‏ ‏","matn":"\"‏اللهم أنت عضدي ونصيري، بك أحول وبك أجول وبك أصول، وبك أقاتل‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:648","bookId":"riyad","type":"hadith","num":648,"kitab":"كتاب الجهاد","isnad":"وعن أبي موسى، رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا خاف قومًا قال‏:‏ اللهم إنا نجعلك في نحورهم، ونعوذ بك من شرورهم‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:649","bookId":"riyad","type":"hadith","num":649,"kitab":"كتاب الجهاد","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الخيل معقود في نواصيها الخير إلى يوم القيامة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:650","bookId":"riyad","type":"hadith","num":650,"kitab":"كتاب الجهاد","isnad":"وعن عروة البارقي رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ الخيل معقود في نواصيها الخير إلى يوم القيامة‏:‏ الأجر والمغنم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:651","bookId":"riyad","type":"hadith","num":651,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من احتبس فرسًا في سبيل الله إيمانًا بالله وتصديقًا بوعده، فإن شبعه، وروثه، وبوله في ميزانه يوم القيامة” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:652","bookId":"riyad","type":"hadith","num":652,"kitab":"كتاب الجهاد","isnad":"وعن أبي مسعود رضي الله عنه قال‏:‏ جار رجل إلى النبي صلى الله عليه وسلم بناقة مخطومة فقال‏:‏ هذه في سبيل الله، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لك بها يوم القيامة سبعمائة ناقة كلها مخطومة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:653","bookId":"riyad","type":"hadith","num":653,"kitab":"كتاب الجهاد","isnad":"وعن أبي حماد- ويقال‏:‏ أبو سعاد، ويقال‏:‏ أبو أسد، ويقال‏:‏ أبو عامر، ويقال‏:‏ أبو عمرو، ويقال‏:‏ أبو الأسود، ويقال‏:‏ أبو عبس- عقبة بن عامر الجهني، رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم وهو على المنبر يقول‏:‏ “وأعدوا لهم ما استطعتم من قوة ألا إن القوة الرمي، ألا إن القوة الرمي، ألا إن القوة الرمي‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏ستفتح عليكم أرضون ويكفيكم الله فلا يعجز أحدكم أن يلهو بأسهمه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:654","bookId":"riyad","type":"hadith","num":654,"kitab":"كتاب الجهاد","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ستفتح عليكم أرضون ويكفيكم الله فلا يعجز أحدكم أن يلهو بأسهمه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:655","bookId":"riyad","type":"hadith","num":655,"kitab":"كتاب الجهاد","isnad":"وعنه أنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من عُلم الرمي ثم تركه فليس منا أو فقد عصى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:656","bookId":"riyad","type":"hadith","num":656,"kitab":"كتاب الجهاد","isnad":"وعنه، رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن الله يدخل بالسهم الواحد ثلاثة نفر الجنة‏:‏ صانعه يحتسب في صنعته الخير، والرامي به ومنبله‏.‏ وارموا واركبوا، وأن ترموا أحب إلي من أن تركبوا‏.‏ ومن ترك الرمي بعد ما علمه رغبة عنه فإنها نعمة تركها‏\"‏ أو قال‏:‏ ‏\"‏كفرها‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:657","bookId":"riyad","type":"hadith","num":657,"kitab":"كتاب الجهاد","isnad":"وعن سلمه بن الأكوع، رضي الله عنه قال‏:‏ مر النبي صلى الله عليه وسلم على نفر ينتضلون، فقال‏:‏ ‏","matn":"\"‏ارموا بني إسماعيل فإن أباكم كان راميًا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:658","bookId":"riyad","type":"hadith","num":658,"kitab":"كتاب الجهاد","isnad":"وعن عمرو بن عبسة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ من رمى بسهم في سبيل الله فهو له عدل محررة‏:‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:659","bookId":"riyad","type":"hadith","num":659,"kitab":"كتاب الجهاد","isnad":"وعن أبي يحيي خريم بن فاتك رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أنفق نفقة في سبيل الله كتب له سبعمائة ضعف‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:660","bookId":"riyad","type":"hadith","num":660,"kitab":"كتاب الجهاد","isnad":"وعن أبي سعيد رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما من عبد يصوم يومًا في سبيل الله إلا باعد الله بذلك اليوم وجهه عن النار سبعين خريفًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:661","bookId":"riyad","type":"hadith","num":661,"kitab":"كتاب الجهاد","isnad":"وعن أبي أمامة، رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من صام يومًا في سبيل الله جعل الله بينه وبين النار خندقًا كما بين السماء والأرض‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:662","bookId":"riyad","type":"hadith","num":662,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من مات ولم يغزُ، ولم يحدث نفسه بالغزو، مات على شعبة من النفاق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:663","bookId":"riyad","type":"hadith","num":663,"kitab":"كتاب الجهاد","isnad":"وعن جابر رضي الله عنه قال‏:‏ كنا مع النبي صلى الله عليه وسلم في غزاة فقال‏:‏ ‏","matn":"\"‏إن بالمدينة لرجالا ما سرتم مسيرًا، ولا قطعتم واديًا إلا كانوا معكم حبسهم المرض‏\"‏"},{"id":"riyad:664","bookId":"riyad","type":"hadith","num":664,"kitab":"كتاب الجهاد","isnad":"وعن أبي موسى، رضي الله عنه أن أعرابيا أتى النبي صلى الله عليه وسلم فقال‏:‏ يا رسول الله الرجل يقاتل للمغنم، والرجل يقاتل ليذكر، والرجل يقاتل ليرى مكانه‏؟‏ وفي رواية‏:‏ يقاتل شجاعة، ويقاتل حَمِيّة‏.‏ وفي رواية‏:‏ ويقاتل غضبًا، فمن في سبيل الله‏؟‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من قاتل لتكون كلمة الله هي العليا، فهو في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:665","bookId":"riyad","type":"hadith","num":665,"kitab":"كتاب الجهاد","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما من غازية أو سرية تغزو، فتغنم وتسلم، إلا كانوا قد تعجلوا ثلثي أجورهم، وما من غازية أو سرية تخفق وتصاب إلا تم لهم أجورهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:666","bookId":"riyad","type":"hadith","num":666,"kitab":"كتاب الجهاد","isnad":"وعن أبي أمامة، رضي الله عنه أن رجلا قال‏:‏ يا رسول الله ائذن لي في السياحة‏.‏ فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن سياحة أمتي الجهاد في سبيل الله، عز وجل‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏"},{"id":"riyad:667","bookId":"riyad","type":"hadith","num":667,"kitab":"كتاب الجهاد","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏قفلة كغزوة‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏"},{"id":"riyad:668","bookId":"riyad","type":"hadith","num":668,"kitab":"كتاب الجهاد","isnad":"","matn":"وعن السائب بن يزيد، رضي الله عنه قال‏:‏ لما قدم النبي صلى الله عليه وسلم من غزوة تبوك تلقاه الناس، فلقيته مع الصبيان على ثنية الوداع‏.‏ ‏‏(‏رواه أبو داود بإسناد صحيح بهذا اللفظ‏)‏‏‏ ورواه البخاري قال‏:‏ ذهبنا نتلقى رسول الله صلى الله عليه وسلم مع الصبيان إلى ثنية الوداع‏"},{"id":"riyad:669","bookId":"riyad","type":"hadith","num":669,"kitab":"كتاب الجهاد","isnad":"وعن أبي أمامة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏","matn":"‏ من لم يغزُ أو يجهز غازيًا، أو يخلف غازيًا في أهله بخير أصابه الله بقارعة قبل يوم القيامة‏:‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:670","bookId":"riyad","type":"hadith","num":670,"kitab":"كتاب الجهاد","isnad":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏جاهدوا المشركين بأموالكم وأنفسكم وألسنتكم‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:671","bookId":"riyad","type":"hadith","num":671,"kitab":"كتاب الجهاد","isnad":"","matn":"وعن أبي عمرو ويقال‏:‏ أبو حكيم النعمان بن مقرن رضي الله عنه قال‏:‏ شهدت رسول الله صلى الله عليه وسلم إذا لم يقاتل من أول النهار أخر القتال حتى تزول الشمس وتهب الريح وينزل النصر‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي، وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:672","bookId":"riyad","type":"hadith","num":672,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تتمنوا لقاء العدو، فإذا لقيتموه فاصبروا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:673","bookId":"riyad","type":"hadith","num":673,"kitab":"كتاب الجهاد","isnad":"وعنه وعن جابر، رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الحرب خُدعة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:674","bookId":"riyad","type":"hadith","num":674,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏الشهداء خمسة‏:‏ المطعون والمبطون، والغريق، وصاحب الهدم والشهيد في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:675","bookId":"riyad","type":"hadith","num":675,"kitab":"كتاب الجهاد","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما تعدون الشهداء فيكم‏؟‏ قالوا‏:‏ يا رسول الله من قتل في سبيل الله فهو شهيد‏.‏ قال‏:‏ ‏\"‏إن شهداء أمتي إذًا لقليل‏!‏‏\"‏ قالوا‏:‏ فمن يا رسول الله ‏؟‏ قال‏:‏ ‏\"‏من قتل في سبيل الله فهو شهيد، ومن مات في سبيل الله فهو شهيد، ومن مات في الطاعون فهو شهيد، ومن مات في البطن فهو شهيد، والغريق شهيد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:676","bookId":"riyad","type":"hadith","num":676,"kitab":"كتاب الجهاد","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “من قتل دون ماله فهو شهيد‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:677","bookId":"riyad","type":"hadith","num":677,"kitab":"كتاب الجهاد","isnad":"وعن أبي الأعور سعيد بن زيد بن عمرو بن نفيل، أحد العشرة المشهود لهم بالجنة، رضي الله عنهم، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من قتل دون ماله فهو شهيد، ومن قتل دون دمه فهو شهيد، ومن قتل دون دينه فهو شهيد، ومن قتل دون عرضه فهو شهيد‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:678","bookId":"riyad","type":"hadith","num":678,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ جاء رجل إلى رسول الله صلى الله عليه وسلم فقال‏:‏ يا رسول الله أرأيت إن جاء رجل يريد أخذ مالي‏؟‏ قال‏:‏ ‏","matn":"\"‏فلا تعطه مالك‏\"‏ قال‏:‏ أرأيت إن قاتلني‏؟‏ قال‏:‏ ‏\"‏قاتله‏\"‏ قال‏:‏ أرأيت إن قتلني قال‏:‏ ‏\"‏فأنت شهيد‏\"‏ قال‏:‏ أرأيت إن قتلته‏؟‏ قال‏:‏ ‏\"‏هو في النار‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:679","bookId":"riyad","type":"hadith","num":679,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أعتق رقبة مسلمة أعتق الله بكل عضو منه عضوًا منه من النار حتى فرجه بفرجه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:680","bookId":"riyad","type":"hadith","num":680,"kitab":"كتاب الجهاد","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قلت يا رسول الله أي الأعمال أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏الإيمان بالله، والجهاد في سبيل الله‏\"‏ قلت‏:‏ أي الرقاب أفضل‏؟‏ قال‏:‏ ‏\"‏أنفسها عند أهلها وأكثرها ثمنًا” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:681","bookId":"riyad","type":"hadith","num":681,"kitab":"كتاب الجهاد","isnad":"وعن المعرور بن سويد قال‏:‏ رأيت أبا ذر رضي الله عنه وعليه حلة وعلى غلامه مثلها، فسألته عن ذلك فذكر أنه ساب رجلا على عهد رسول الله صلى الله عليه وسلم فعيره بأمه فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إنك امرؤ فيك جاهلية‏\"‏ ‏:‏ هم إخوانكم، وخولكم جعلهم الله تحت أيديكم فمن كان أخوه تحت يده فليطعمه مما يأكل ويلبسه مما يلبس ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:682","bookId":"riyad","type":"hadith","num":682,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أتى أحدكم خادمه بطعامه، فإن لم يجلسه معه فليناوله لقمة أو لقمتين أو أُكلة أو أُكلتين فإنه ولي علاجه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ (9)"},{"id":"riyad:683","bookId":"riyad","type":"hadith","num":683,"kitab":"كتاب الجهاد","isnad":"عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن العبد إذا نصح لسيده، وأحسن عبادة الله، فله أجره مرتين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:684","bookId":"riyad","type":"hadith","num":684,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏للعبد المملوك المصلح أجران، والذي نفس أبي هريرة بيده لولا الجهاد في سبيل الله والحج، وبر أمي لأحببت أن أموت وأنا مملوك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:685","bookId":"riyad","type":"hadith","num":685,"kitab":"كتاب الجهاد","isnad":"وعن أبي موسى الأشعري قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏المملوك الذي يحسن عبادة ربه ويؤدي إلى سيده الذي عليه من الحق، والنصيحة والطاعة له أجران‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:686","bookId":"riyad","type":"hadith","num":686,"kitab":"كتاب الجهاد","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ثلاثة لهم أجران‏:‏ رجل من أهل الكتاب آمن بنبيه، وآمن بمحمد، والعبد المملوك إذا أدى حق الله، وحق مواليه، ورجل كانت له أمة فأدبها فأحسن تأديبها وعلمها فأحسن تعليمها، ثم أعتقها فتزوجها فله أجران‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:687","bookId":"riyad","type":"hadith","num":687,"kitab":"كتاب الجهاد","isnad":"عن معقل بن يسار رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏العبادة في الهرج كهجرة إلي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:688","bookId":"riyad","type":"hadith","num":688,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه أن رجلا أتى النبي صلى الله عليه وسلم يتقاضاه فأغلظ له فهم به أصحابه، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏دعوه فإن لصاحب الحق مقالا‏\"‏ ثم قال‏:‏ ‏\"‏أعطوه سنا مثل سنه‏\"‏ قالوا‏:‏ يا رسول الله لا نجد إلا أمثل من سنه، قال‏:‏ ‏\"‏أعطوه فإن خيركم أحسنكم قضاء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:689","bookId":"riyad","type":"hadith","num":689,"kitab":"كتاب الجهاد","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏رحم الله رجلا سمحًا إذا باع وإذا اشترى وإذا اقتضى‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:690","bookId":"riyad","type":"hadith","num":690,"kitab":"كتاب الجهاد","isnad":"وعن أبي قتادة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من سره أن ينجيه الله من كرب يوم القيامة، فلينفس عن معسر أو يضع عنه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:691","bookId":"riyad","type":"hadith","num":691,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كان رجل يداين الناس، وكان يقول لفتاه‏:‏ إذا أتيت معسرا فتجاوز عنه، لعل الله أن يتجاوز عنا فلقي الله فتجاوز عنه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:692","bookId":"riyad","type":"hadith","num":692,"kitab":"كتاب الجهاد","isnad":"وعن أبي مسعود البدري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏حوسب رجل ممن كان قبلكم فلم يوجد له من الخير شيء إلا أنه كان يخالط الناس، وكان موسرًا وكان يأمر غلمانه أن يتجاوزوا عن المعسر قال الله عز وجل‏:‏ ‏\"‏نحن أحق بذلك منه، تجاوزوا عنه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:693","bookId":"riyad","type":"hadith","num":693,"kitab":"كتاب الجهاد","isnad":"وعن حذيفة رضي الله عنه قال‏:‏ أتي الله تعالى بعبد من عباده آتاه الله مالا فقال له ماذا عملت في الدنيا‏؟‏ قال‏:‏ ولا يكتمون الله حديثا- قال‏:‏ يا رب آتيتني مالك فكنت أبايع الناس، وكان من خلقي الجواز فكنت أتيسر على الموسر وأنظر المعسر فقال الله تعالى‏:‏ “‏","matn":"\"‏أنا أحق بذا منك، تجاوزوا عن عبدي‏\"‏ فقال عقبة بن عامر، وأبو مسعود الأنصاري رضي الله عنهما هكذا سمعناه من في رسول الله صلى الله عليه وسلم‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:694","bookId":"riyad","type":"hadith","num":694,"kitab":"كتاب الجهاد","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أنظر معسرًا أو وضع له، أظله الله يوم القيامة تحت ظل عرشه يوم لا ظل إلا ظله‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:695","bookId":"riyad","type":"hadith","num":695,"kitab":"كتاب الجهاد","isnad":"","matn":"وعن جابر، رضي الله عنه أن النبي صلى الله عليه وسلم اشترى منه بعيرًا فوزن له فأرجح‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:696","bookId":"riyad","type":"hadith","num":696,"kitab":"كتاب الجهاد","isnad":"وعن أبي صفوان سويد بن قيس، رضي الله عنه قال‏:‏ جلبت أنا ومخرمة العبدي بزًا من هجر، فجاءنا النبي صلى الله عليه وسلم فساومنا سراويل، وعندي وزان يزن بالأجر، فقال النبي صلى الله عليه وسلم للوزان ‏","matn":"\"‏زن وأرجح‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:697","bookId":"riyad","type":"hadith","num":697,"kitab":"كتاب العلم","isnad":"وعن معاوية رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من يرد الله به خيرًا يفقه في الدين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:698","bookId":"riyad","type":"hadith","num":698,"kitab":"كتاب العلم","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا حسد إلا في اثنتين‏:‏ رجل آتاه الله مالا فسلطه على هلكته في الحق، ورجل آتاه الله الحكمة فهو يقضي بها ويعلمها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:699","bookId":"riyad","type":"hadith","num":699,"kitab":"كتاب العلم","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏مثل ما بعثني الله به من الهدى والعلم كمثل غيث أصاب أرضًا، فكانت منها طائفة طيبة قبلت الماء فأنبتت الكلأ، والعشب الكثير وكان منها أجادب أمسكت الماء، فنفع الله بها الناس، فشربوا منها وسقوا وزرعوا، وأصاب طائفة منها أخرى إنما هي قيعان لا تمسك ماء ولا تنبت كلأ فذلك مثل من فقه في دين الله ونفعه ما بعثني الله به وعلم، ومثل من لم يرفع بذلك رأسًا ولم يقبل هدى الله الذي أرسلت به‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:700","bookId":"riyad","type":"hadith","num":700,"kitab":"كتاب العلم","isnad":"وعن سهل بن سعد رضي الله عنه أن النبي صلى الله عليه وسلم قال لعلي رضي الله عنه ‏:‏ ‏","matn":"\"‏فوالله لأن يهدي الله بك رجلا واحدا خير من حمر النعم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:701","bookId":"riyad","type":"hadith","num":701,"kitab":"كتاب العلم","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏بلغوا عني ولو آية وحدثوا عن بني إسرائيل ولا حرج، ومن كذب علي متعمدًا فليتبوأ مقعده من النار‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:702","bookId":"riyad","type":"hadith","num":702,"kitab":"كتاب العلم","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ومن سلك طريقًا يلتمس فيه علما سهل الله له به طريقًا إلى الجنة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:703","bookId":"riyad","type":"hadith","num":703,"kitab":"كتاب العلم","isnad":"وعنه أيضًا رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئًا ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:704","bookId":"riyad","type":"hadith","num":704,"kitab":"كتاب العلم","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا مات ابن آدم انقطع عمله إلا من ثلاث‏:‏ صدقة جارية ،أو علم ينتفع به، أو ولد صالح يدعو له‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:705","bookId":"riyad","type":"hadith","num":705,"kitab":"كتاب العلم","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏الدنيا ملعونة ملعون ما فيها إلا ذكر الله تعالى، وما والاه، وعالمًا أو متعلمًا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏.‏ ‏)‏‏)‏‏.‏ (2)"},{"id":"riyad:706","bookId":"riyad","type":"hadith","num":706,"kitab":"كتاب العلم","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من خرج في طلب العلم، فهو في سبيل الله حتى يرجع‏\"‏ رواه الترمذي وقال‏:‏ حديث حسن‏.‏"},{"id":"riyad:707","bookId":"riyad","type":"hadith","num":707,"kitab":"كتاب العلم","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لن يشبع مؤمن من خير حتى يكون منتهاه الجنة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:708","bookId":"riyad","type":"hadith","num":708,"kitab":"كتاب العلم","isnad":"وعن أبي أمامة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏فضل العالم على العابد كفضلي على أدناكم‏\"‏ ثم قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏إن الله وملائكته وأهل السماوات والأرض حتى النملة في جحرها وحتى الحوت ليصلون على معلمي الناس الخير‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:709","bookId":"riyad","type":"hadith","num":709,"kitab":"كتاب العلم","isnad":"وعن أبي الدرداء رضي الله عنه قال سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من سلك طريقًا يبتغي فيه علمًا سهل الله له طريقًا إلى الجنة، وإن الملائكة لتضع أجنحتها لطالب العلم رضا بما صنع، وإن العالم ليستغفر له من في السماوات والأرض حتى الحيتان في الماء، وفضل العالم على العابد كفضل القمر على سائر الكواكب، وإن العلماء ورثة الأنبياء وإن الأنبياء لم يورثوا دينارًا ولا درهما وإنما ورثوا العلم‏.‏ فمن أخذه أخذ بحظ وافر‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي‏)‏‏)‏‏.‏"},{"id":"riyad:710","bookId":"riyad","type":"hadith","num":710,"kitab":"كتاب العلم","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏نضر الله امرءًا سمع منا شيئًا فبلغه كما سمعه فرب مبلغ أوعي من سامع‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:711","bookId":"riyad","type":"hadith","num":711,"kitab":"كتاب العلم","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من سئل عن علم فكتمه ألجم يوم القيامة بلجام من نار‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي، وقال‏:‏ حديث حسن‏.‏"},{"id":"riyad:712","bookId":"riyad","type":"hadith","num":712,"kitab":"كتاب العلم","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من تعلم علمًا مما يبتغى به وجه الله عز وجل لا يتعلمه إلا ليصيب به غرضًا من الدنيا لم يجد عرف الجنة يوم القيامة‏\"‏ ‏(‏‏(‏يعني ريحها‏)‏‏)‏، ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏.‏ ‏)‏‏)‏‏.‏"},{"id":"riyad:713","bookId":"riyad","type":"hadith","num":713,"kitab":"كتاب العلم","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن الله لا يقبض العلم انتزاعًا ينتزعه من الناس ولكن يقبض العلم بقبض العلماء حتى إذا لم يبقِ عالمًا، اتخذ الناس رءوسًا جهالا، فسئلوا فأفتوا بغير علم، فضلوا وأضلوا‏:‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:714","bookId":"riyad","type":"hadith","num":714,"kitab":"كتاب حمد الله تعالى وشكره","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم أتي ليلة أسري به بقدحين من خمر ولبن، فنظر إليهما فأخذ اللبن، فقال جبريل صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏الحمد لله الذي هداك للفطرة لو أخذت الخمر غوت أمتك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:715","bookId":"riyad","type":"hadith","num":715,"kitab":"كتاب حمد الله تعالى وشكره","isnad":"وعنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كل أمر ذي بال لا يبدأ فيه‏:‏ بالحمد لله فهو أقطع‏\"‏ حديث حسن، ‏(‏‏(‏رواه أبو داود وغيره‏)‏‏)‏‏.‏"},{"id":"riyad:716","bookId":"riyad","type":"hadith","num":716,"kitab":"كتاب حمد الله تعالى وشكره","isnad":"وعن أبي موسى الأشعري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا مات ولد العبد قال الله تعالى لملائكته‏:‏ قبضتم ولد عبدي‏؟‏ فَيقولون : نَعَمْ ، فيقول : قَبَضْتُمْ ثَمَرَةَ فُؤادِهِ ؟ فيقولون : نَعَمْ ، فيقول : فماذا قال عبدي‏؟‏ فيقولون‏:‏ حمدك واسترجع، فيقول الله تعالى‏:‏ ابنوا لعبدي بيتًا في الجنة، وسموه بيت الحمد‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:717","bookId":"riyad","type":"hadith","num":717,"kitab":"كتاب حمد الله تعالى وشكره","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله ليرضى عن العبد يأكل الأكلة فيحمده عليها، ويشرب الشربة، فيحمده عليها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:718","bookId":"riyad","type":"hadith","num":718,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من صلى علي صلاة، صلى الله عليه بها عشرًا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:719","bookId":"riyad","type":"hadith","num":719,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “أولى الناس بي يوم القيامة أكثرهم علي صلاة‏","matn":"\"‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:720","bookId":"riyad","type":"hadith","num":720,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن أوس بن أوس، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن من أفضل أيامكم يوم الجمعة، فأكثروا على من الصلاة فيه، فإن صلاتكم معروضة علي‏\"‏ فقالوا‏:‏ يا رسول الله، كيف تعرض صلاتنا عليك وقد أرمت‏؟‏ قال‏:‏ يقول‏:‏ بلىت، قال‏:‏ ‏\"‏إن الله عز وجل حرم على الأرض أجساد الأنبياء‏\"‏ رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:721","bookId":"riyad","type":"hadith","num":721,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏رغم أنف رجل ذكرت عنده فلم يصلِ علي‏\"‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:722","bookId":"riyad","type":"hadith","num":722,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تجعلوا قبري عيدًا وصلوا علي، فإن صلاتكم تبلغني حيث كنتم‏\"‏ رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:723","bookId":"riyad","type":"hadith","num":723,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما من أحد يسلم علي إلا رد الله علي روحي حتى أرد عليه السلام‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:724","bookId":"riyad","type":"hadith","num":724,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن علي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ البخيل من ذكرت عنده، فلم يصلِ علي‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:725","bookId":"riyad","type":"hadith","num":725,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن فضالة بن عبيد رضي الله عنه قال‏:‏ سمع رسول الله صلى الله عليه وسلم رجلا يدعو في صلاته لم يمجد الله تعالى، ولم يصلِ على النبي صلى الله عليه وسلم، فقال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏عجل هذا‏\"‏ ثم دعاه فقال له -أو لغيره‏:‏ إذا صلى أحدكم فليبدأ بتحميد ربه سبحانه، والثناء عليه، ثم يصلي على النبي صلى الله عليه وسلم ثم يدعو بعد ما شاء‏\"‏ رواه أبو داود والترمذي وقال حديث صحيح‏.‏"},{"id":"riyad:726","bookId":"riyad","type":"hadith","num":726,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن أبي محمد كعب بن عجرة رضي الله عنه قال‏:‏ خرج علينا النبي صلى الله عليه وسلم فقلنا‏:‏ يا رسول الله، قد علمنا كيف نسلم عليك، فكيف نصلي عليك‏؟‏ قال‏:‏ ‏","matn":"\"‏قولوا‏:‏ اللهم صلِ على محمد، وعلى آل محمد، كما صليت على آل إبراهيم، إنك حميد مجيد‏.‏ اللهم بارك على محمد وعلى آل محمد، كما باركت على آل إبراهيم، إنك حميد مجيد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:727","bookId":"riyad","type":"hadith","num":727,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن أبي مسعود بن عبادة البدري، رضي الله عنه، قال‏:‏ أتانا رسول الله صلى الله عليه وسلم، ونحن في مجلس سعد بن عبادة رضي الله عنه، فقال له بشير بن سعد‏:‏ أمرنا الله تعالى أن نصلي عليك يا رسول الله، فكيف نصلي عليك‏؟‏ فسكت رسول الله صلى الله عليه وسلم، حتى تمنينا أنه لم يسأله، ثم قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏قولوا اللهم صلِ على محمد وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم إنك حميد مجيد، والسلام كما قد علمتم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:728","bookId":"riyad","type":"hadith","num":728,"kitab":"كتاب الصلاة على رسول الله صلى الله عليه وسلم","isnad":"وعن أبي حميد الساعدي رضي الله عنه قال‏:‏ قالوا‏:‏ يا رسول الله كيف نصلي عليك‏؟‏ قال‏:‏ ‏","matn":"\"‏قولوا‏:‏ اللهم صلِ على محمد، وعلى أزواجه وذريته، كما صليت على آل إبراهيم، وبارك على محمد، وعلى أزواجه وذريته، كما باركت على إبراهيم، إنك حميد مجيد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:729","bookId":"riyad","type":"hadith","num":729,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن‏:‏ سبحان الله وبحمده، سبحان الله العظيم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:730","bookId":"riyad","type":"hadith","num":730,"kitab":"كتاب الأذكار","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ لأن أقول‏:‏ سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، أحب إلي مما طلعت عليه الشمس” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:731","bookId":"riyad","type":"hadith","num":731,"kitab":"كتاب الأذكار","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قال لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، في يوم مائة مرة كانت له عدل عشر رقاب وكتبت له مائة حسنة، ومحيت عنه مائة سيئة، وكانت له حرزًا من الشيطان يومه ذلك حتى يمسي، ولم يأتِ أحد بأفضل مما جاء به إلا رجل عمل أكثر منه‏\"‏ وقال‏:‏ ‏\"‏من قال سبحان الله وبحمده، في يوم مائة مرة حطت عنه خطاياه وإن كانت مثل زبد البحر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:732","bookId":"riyad","type":"hadith","num":732,"kitab":"كتاب الأذكار","isnad":"وعن أبي أيوب الأنصاري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قال لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، عشر مرات، كان كمن أعتق أربعة أنفس من ولد إسماعيل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:733","bookId":"riyad","type":"hadith","num":733,"kitab":"كتاب الأذكار","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قال لي رسول صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ألا أخبرك بأحب الكلام إلى الله‏؟‏ إن أحب الكلام إلى الله‏:‏ سبحان الله وبحمده‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:734","bookId":"riyad","type":"hadith","num":734,"kitab":"كتاب الأذكار","isnad":"وعن أبي مالك الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله، والحمد لله تملآن -أو تملأ- ما بين السماوات والأرض‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:735","bookId":"riyad","type":"hadith","num":735,"kitab":"كتاب الأذكار","isnad":"وعن سعد بن أبي وقاص رضي الله عنه قال‏:‏ جاء أعرابي إلى رسول الله صلى الله عليه وسلم فقال‏:‏ علمني كلامًا أقوله‏.‏ قال‏:‏ ‏","matn":"\"‏قل لا إله إلا الله وحده لا شريك له، الله أكبر كبيرا والحمد لله كثيرا وسبحان الله رب العالمين، ولا حول ولا قوة إلا بالله العزيز الحكيم” قال فهؤلاء لربي، فما لي‏؟‏ قال‏:‏ ‏\"‏قل اللهم اغفر لي، وارحمني، واهدني، وارزقني‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:736","bookId":"riyad","type":"hadith","num":736,"kitab":"كتاب الأذكار","isnad":"وعن ثوبان رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم‏:‏ إذا انصرف من صلاته استغفر ثلاثا ، وقال ‏:‏ ‏","matn":"\"‏ اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام “ قيل للأوزاعي ، وهو أحد رواة الحديث ‏:‏ كيف الاستغفار ‏؟‏ قال ‏:‏ يقول ‏:‏ أستغفر الله أستغفر الله ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:737","bookId":"riyad","type":"hadith","num":737,"kitab":"كتاب الأذكار","isnad":"وعن المغيرة بن شعبة رضي الله عنه أن رسول الله صلى الله عليه وسلم، كان إذا فرغ من الصلاة وسلم قال ‏:‏ ‏","matn":"\"‏لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير‏.‏ اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:738","bookId":"riyad","type":"hadith","num":738,"kitab":"كتاب الأذكار","isnad":"","matn":"وعن عبد الله ابن الزبير رضي الله عنهما أنه كان يقول دبر كل صلاة، حين يسلم‏:‏ لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد ، وهو على كل شيء قدير ‏.‏ لا حول ولا قوة إلا بالله ،لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل وله الثناء الحسن‏.‏ لا إله إلا الله مخلصين له الدين ولو كره الكافرون ‏.‏ قال ابن الزبير‏:‏ وكان رسول الله صلى الله عليه وسلم، يهلل بهن دبر كل صلاة‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:739","bookId":"riyad","type":"hadith","num":739,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه أن فقراء المهاجرين أتوا رسول الله صلى الله عليه وسلم فقالوا‏:‏ ‏","matn":"\"‏ذهب أهل الدثور بالدرجات العلى، والنعيم المقيم‏:‏ يصلون كما نصلي، ويصومون كما نصوم، ولهم فضل من أموال‏:‏ يحجون، ويعتمرون، ويجاهدون، ويتصدقون‏.‏ فقال‏:‏ ‏\"‏ألا أعلمكم شيئًا تدركون به من سبقكم، وتسبقون به من بعدكم، ولا يكون أحد أفضل منكم إلا من صنع مثل ما صنعتم‏؟‏ قالوا‏:‏ بلى يا رسول الله، قال‏:‏ ‏\"‏تسبحون، وتحمدون، وتكبرون، خلف كل صلاة ثلاثًا وثلاثين قال أبو صالح الراوي عن أبي هريرة، لما سئل عن كيفية ذكرهن، قال‏:‏ يقول‏:‏ سبحان الله، والحمد لله، والله أكبر، حتى يكون منهن كلهن ثلاثًا وثلاثين‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وزاد مسلم في روايته‏:‏ فرجع فقراء المهاجرين إلى رسول الله صلى الله عليه وسلم، فقالوا‏:‏ سمع إخواننا أهل الأموال بما فعلنا، وفعلوا مثله‏؟‏ فقال رسول الله‏:‏ ‏\"‏ذلك فضل الله يؤتيه من يشاء‏\"‏‏.‏ ((الدثور))جمع دثر- بفتح الدال و اسكان الثاء المثلثة- و هو: المال الكثير."},{"id":"riyad:740","bookId":"riyad","type":"hadith","num":740,"kitab":"كتاب الأذكار","isnad":"وعنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من سبح الله في دبر كل صلاة ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين، وكبر الله ثلاثًا وثلاثين، وقال تمام المائة‏:‏ لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، غفرت خطاياه وإن كانت مثل زبد البحر” ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:741","bookId":"riyad","type":"hadith","num":741,"kitab":"كتاب الأذكار","isnad":"وعن كعب بن عجرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏معقبات لا يخيب قائلهن -أو فاعلهن- دبر كل صلاة مكتوبة‏:‏ ثلاثًا وثلاثين تسبيحة وثلاثًا وثلاثين تحميدة، وأربعًا وثلاثين تكبيرة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:742","bookId":"riyad","type":"hadith","num":742,"kitab":"كتاب الأذكار","isnad":"وعن سعد بن أبي وقاص رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يتعوذ دبر الصلوات بهؤلاء الكلمات‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من الجبن والبخل، وأعوذ بك من أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا، وأعوذ بك من فتنة القبر” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:743","bookId":"riyad","type":"hadith","num":743,"kitab":"كتاب الأذكار","isnad":"وعن معاذ رضي الله عنه أن رسول الله صلى الله عليه وسلم أخذ بيده وقال‏:‏ ‏","matn":"\"‏يا معاذ والله إني لأحبك‏\"‏ فقال‏:‏ ‏\"‏أوصيك يا معاذ لا تدعن في دبر كل صلاة تقول‏:‏ اللهم أعني على ذكرك، وشكرك، وحسن عبادتك‏\"‏‏.‏ رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:744","bookId":"riyad","type":"hadith","num":744,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا تشهد أحدكم فليستعذ بالله من أربع، يقول‏:‏ اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر ومن فتنة المحيا والممات، ومن شر فتنة المسيح الدجال‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:745","bookId":"riyad","type":"hadith","num":745,"kitab":"كتاب الأذكار","isnad":"وعن علي رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا قام إلى الصلاة يكون من آخر ما يقول بين التشهد والتسليم‏:‏ ‏","matn":"\"‏اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، لا إله إلا أنت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:746","bookId":"riyad","type":"hadith","num":746,"kitab":"كتاب الأذكار","isnad":"وعن عائشة رضي الله عنه قالت‏:‏ كان النبي صلى الله عليه وسلم يكثر أن يقول في ركوعه وسجوده‏:‏ سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:747","bookId":"riyad","type":"hadith","num":747,"kitab":"كتاب الأذكار","isnad":"وعنها أن رسول الله صلى الله عليه وسلم كان يقول في ركوعه وسجوده‏:‏ ‏","matn":"\"‏سبوح قدوس رب الملائكة والروح‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:748","bookId":"riyad","type":"hadith","num":748,"kitab":"كتاب الأذكار","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ فأما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:749","bookId":"riyad","type":"hadith","num":749,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:750","bookId":"riyad","type":"hadith","num":750,"kitab":"كتاب الأذكار","isnad":"وعنه أن رسول الله صلى الله عليه وسلم كان يقول في سجوده‏:‏ “اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:751","bookId":"riyad","type":"hadith","num":751,"kitab":"كتاب الأذكار","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ افتقدت النبي صلى الله عليه وسلم ذات ليلة فتحسست، فإذا هو راكع‏.‏-أو ساجد- يقول‏:‏ ‏","matn":"\"‏سبحانك وبحمدك لا إله إلا أنت‏\"‏ ، وفي رواية‏:‏ فوقعت يدي على بطن قدميه، وهو في المسجد، وهما منصوبتان، وهو يقول‏:‏ ‏\"‏اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وأعوذ بك منك، لا أحصي ثناء عليك أنت كما أثنيت على نفسك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:752","bookId":"riyad","type":"hadith","num":752,"kitab":"كتاب الأذكار","isnad":"وعن سعد بن أبي وقاص رضي الله عنه قال‏:‏ كنا عند رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏أيعجز أحدكم أن يكسب في كل يوم ألف حسنة‏!‏‏\"‏ فسأله سائل من جلسائه‏:‏ كيف يكسب ألف حسنة‏؟‏ قال‏:‏ ‏\"‏يسبح مائة تسبيحة، فيكتب له ألف حسنة، أو يحط عنه ألف خطيئة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏. قال الحميدي: كذا هو في كتاب مسلم : ((او يحط)) قال البرقاني: ورواه شعبة و ابو عوانة, و يحيى القطان, عن موسى الذي رواه مسلم من جهته فقالوا:((و يحط)) بغير الف."},{"id":"riyad:753","bookId":"riyad","type":"hadith","num":753,"kitab":"كتاب الأذكار","isnad":"وعن أبي ذر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “يصبح على كل سلامى من أحدكم صدقة‏:‏ فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويجزي من ذلك ركعتان يركعهما من الضحى‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:754","bookId":"riyad","type":"hadith","num":754,"kitab":"كتاب الأذكار","isnad":"وعن أم المؤمنيين جويرية بنت الحارث رضي الله عنها أن النبي صلى الله عليه وسلم خرج من عندها بكرة حين صلى الصبح وهي في مسجدها، ثم رجع بعد أن أضحي وهي جالسة، فقال‏:‏ ‏","matn":"\"‏مازلت على الحالة التي فارقت عليها‏؟‏‏\"‏ قالت‏:‏ نعم، فقال النبي صلى الله عليه وسلم‏:‏ ‏\"‏لقد كنت بعدك أربع كلمات ثلاث مرات، لو وزنت بما قلت منذ اليوم لوزنتهن‏:‏ سبحان الله وبحمده عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ سبحان الله عدد خلقه، سبحان الله رضا نفسه، سبحان الله زنة عرشه، سبحان الله مداد كلماته‏\"‏‏.‏ وفي رواية الترمذي‏:‏ ألا أعلمك كلمات تقولينها‏؟‏ سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله مداد كلماته، سبحان الله مداد كلماته، سبحان الله مداد كلماته‏\"‏‏.‏"},{"id":"riyad:755","bookId":"riyad","type":"hadith","num":755,"kitab":"كتاب الأذكار","isnad":"وعن أبي موسى الأشعري رضي الله عنه عن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏مثل الذي يذكر ربه والذي لا يذكره، مثل الحي والميت‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ ورواه مسلم فقال‏:‏ ‏\"‏مثل البيت الذي يذكر الله فيه، والبيت الذي لا يذكر الله فيه، مثل الحي والميت‏\"‏‏.‏"},{"id":"riyad:756","bookId":"riyad","type":"hadith","num":756,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة، رضي الله عنه، أن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏يقول الله تعالى‏:‏ أنا عند ظن عبدي بي، وأنا معه إذا ذكرني، فإن ذكرني في نفسه، ذكرته في نفسي وإن ذكرني في ملإٍ ذكرته في ملإٍ خير منهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:757","bookId":"riyad","type":"hadith","num":757,"kitab":"كتاب الأذكار","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏سبق المفردون‏\"‏ قالوا‏:‏ وما المفردون يا رسول الله‏؟‏ قال‏:‏ ‏\"‏الذاكرون الله كثيرًا والذكرات‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وروي : (( المفردون )) بتشديد الراء وتخفيفها والمشهور الذي قاله الجمهور : التشديد."},{"id":"riyad:758","bookId":"riyad","type":"hadith","num":758,"kitab":"كتاب الأذكار","isnad":"وعن جابر رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏أفضل الذكر‏:‏ لا إله إلا الله‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:759","bookId":"riyad","type":"hadith","num":759,"kitab":"كتاب الأذكار","isnad":"وعن عبد الله بن بشر رضي الله عنه أن رجلا قال‏:‏ يا رسول الله، إن شرائع الإسلام قد كثرت علي، فأخبرني بشيء أتشبث به قال‏:‏ ‏","matn":"\"‏لا يزال لسانك رطبًا من ذكر الله‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:760","bookId":"riyad","type":"hadith","num":760,"kitab":"كتاب الأذكار","isnad":"وعن جابر رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من قال‏:‏ سبحان الله وبحمده، غرست له نخلة في الجنة‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:761","bookId":"riyad","type":"hadith","num":761,"kitab":"كتاب الأذكار","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لقيت إبراهيم صلى الله عليه وسلم ليلة أسري بي، فقال‏:‏ يا محمد أقرئ أمتك مني السلام، وأخبرهم أن الجنة طيبة التربة، عذبة الماء، وأنها قيعان، وأن غراسها‏:‏ سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:762","bookId":"riyad","type":"hadith","num":762,"kitab":"كتاب الأذكار","isnad":"وعن أبي الدرداء، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ألا أنبئكم بخير أعمالكم، وأزكاها عند مليككم، وأرفعها في درجاتكم، وخير لكم من إنفاق الذهب والفضة وخير لكم من أن تلقوا عدوكم فتضربوا أعناقهم، ويضربوا أعناقكم‏؟‏‏\"‏ قالوا‏:‏ بلى، قال‏:‏ ‏\"‏ذكر الله تعالى‏\"‏‏.‏ رواه الترمذي وقال الحاكم أبو عبد الله إسناده صحيح‏.‏"},{"id":"riyad:763","bookId":"riyad","type":"hadith","num":763,"kitab":"كتاب الأذكار","isnad":"وعن سعد بن أبي وقاص رضي الله عنه أنه دخل مع رسول الله صلى الله عليه وسلم على امرأة وبين يديها نوى -أو حصى- تسبح به فقال‏:‏ ‏","matn":"\"‏أخبرك بما هو أيسر عليك من هذا - أو أفضل‏\"‏ فقال‏:‏ ‏\"‏سبحان الله عدد ما خلق في السماء، وسبحان الله عدد ما خلق في الأرض، وسبحان الله عدد ما بين ذلك، وسبحان الله عدد ما هو خالق، والله أكبر مثل ذلك، والحمد لله مثل ذلك، ولا إله إلا الله مثل ذلك، ولا حول ولا قوة إلا بالله مثل ذلك‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:764","bookId":"riyad","type":"hadith","num":764,"kitab":"كتاب الأذكار","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ألا أدلك على كنز من كنوز الجنة ‏؟‏‏\"‏ فقلت‏:‏ بلى يا رسول الله قال‏:‏ ‏\"‏لا حول ولا قوة إلا بالله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:765","bookId":"riyad","type":"hadith","num":765,"kitab":"كتاب الأذكار","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يذكر الله تعالى على كل أحيانه‏.‏ رواه مسلم‏.‏"},{"id":"riyad:766","bookId":"riyad","type":"hadith","num":766,"kitab":"كتاب الأذكار","isnad":"وعن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لو أن أحدكم إذا أتى أهله قال‏:‏ بسم الله، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا، فقضى بينهما ولد لم يضره ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:767","bookId":"riyad","type":"hadith","num":767,"kitab":"كتاب الأذكار","isnad":"عن حذيفة، وأبي ذر رضي الله عنهما قالا‏:‏ كان رسول الله صلى الله عليه وسلم إذا أوى إلى فراشه قال‏:‏ ‏","matn":"\"‏باسمك اللهم أموت وأحيا‏\"‏ وإذا استيقظ قال‏:‏ ‏\"‏الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:768","bookId":"riyad","type":"hadith","num":768,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏إن لله تعالى ملائكة يطوفون في الطرق يلتمسون أهل الذكر، فإذا وجدوا قومًا يذكرون الله عز وجل، تنادوا‏:‏ هلموا إلى حاجتكم، فيحفونهم بأجنحتهم إلى السماء الدنيا، فيسألهم ربهم - وهو أعلم‏:‏ ما يقول عبادي‏؟‏ قال‏:‏ يقولون‏:‏ يسبحونك، ويكبرونك، ويحمدونك، ويمجدونك، فيقول‏:‏ هل رأوني‏؟‏ فيقولون‏:‏ لا لا والله ما رأوك، فيقول‏:‏ كيف لو رأوني‏؟‏‏!‏ قال‏:‏ يقولون‏:‏ لو رأوك كانوا أشد لك عبادة، وأشد لك تمجيدًا، وأكثر لك تسبيحًا فيقول‏:‏ فماذا يسألون‏؟‏ قال‏:‏ يقولون‏:‏ يسألونك الجنة‏.‏ قال‏:‏ يقول‏:‏ وهل رأوها‏؟‏ قال‏:‏ يقولون‏:‏ لا والله يا رب ما رأوها‏.‏ قال‏:‏ يقول‏:‏ فكيف لو رأوها‏؟‏‏!‏ قال‏:‏ يقولون‏:‏ لو أنهم رأوها كانوا أشد عليها حرصًا، وأشد لها طلبًا، وأعظم فيها رغبة‏.‏ قال‏:‏ فمم يتعوذون‏؟‏ قال يقولون‏:‏ يتعوذون من النار، قال‏:‏ فيقول‏:‏ وهل رأوها‏؟‏ قال‏:‏ يقولون‏:‏ ولا والله ما رأوها‏.‏ فيقول‏:‏ كيف لو رأوها‏؟‏‏!‏ قال‏:‏ يقولون‏:‏ لو رأوها كانوا أشد فرارًا، وأشد لها مخافة‏.‏ قال‏:‏ يقول‏:‏ فأشهدكم أني قد غفرت لهم، قال‏:‏ يقول ملك من الملائكة‏:‏ فيهم فلان ليس منهم، إنما جاء لحاجة، قال‏:‏ هم الجلساء لا يشقى بهم جليسهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏\"‏إن لله ملائكة سيارة فضلا يتتبعون مجالس الذكر، فإذا وجدوا مجلسًا فيه ذكر، قعدوا معهم، وحف بعضهم بعضًا بأجنحتهم حتى يملئوا ما بينهم وما بين السماء الدنيا، فإذا تفرقوا عرجوا وصعدوا إلى السماء، فيسألهم الله عز وجل - وهو أعلم‏:‏ من أين جئتم‏؟‏ فيقولون‏:‏ جئنا من عند عباد لك في الأرض‏:‏ يسبحونك، ويكبرونك، ويهللونك، ويحمدونك، ويسألونك‏.‏ قال‏:‏ وماذا يسألوني‏؟‏ قالوا‏:‏ يسألونك جنتك‏.‏ قال‏:‏ وهل رأوا جنتي‏؟‏ قالوا‏:‏ لا، أي رب‏.‏ قال‏:‏ فكيف لو رأوا جنتي‏؟‏‏!‏ قالوا‏:‏ ويستجيرونك‏.‏ قال‏:‏ ومم يستجيروني‏؟‏ قالوا‏:‏ من نارك يا رب‏.‏ قال‏:‏ وهل رأوا ناري‏؟‏ قالوا‏:‏ لا، قال‏:‏ فكيف لو رأوا ناري‏؟‏ قالوا‏:‏ ويستغفرونك، فيقول‏:‏ قد غفرت لهم، وأعطيتهم ما سألوا، وأجرتهم ما استجاروا‏.‏ قال‏:‏ فيقولون‏:‏ رب فيهم فلان عبد خطاء إنما مر، فجلس معهم، فيقول‏:‏ وله غفرت، هم القوم لا يشقى بهم جليسهم‏\"‏‏.‏"},{"id":"riyad:769","bookId":"riyad","type":"hadith","num":769,"kitab":"كتاب الأذكار","isnad":"وعنه وعن أبي سعيد رضي الله عنهما قالا‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا يقعد قوم يذكرون الله عز وجل إلا حفتهم الملائكة، وغشيتهم الرحمة ونزلت عليهم السكينة، وذكرهم الله فيمن عنده‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:770","bookId":"riyad","type":"hadith","num":770,"kitab":"كتاب الأذكار","isnad":"وعن أبي واقد الحارث بن عوف رضي الله عنه أن رسول الله صلى الله عليه وسلم، بينما هو جالس في المسجد، والناس معه، إذ أقبل اثنان إلى رسول الله صلى الله عليه وسلم، وذهب واحد، فوقفا على رسول الله صلى الله عليه وسلم، فأما أحدهما فرأى فرجة في الحلقة، فجلس فيها وأما الآخر، فجلس خلفهم، وأما الثالث فأدبر ذاهبًا‏.‏ فلما فرغ رسول الله صلى الله عليه وسلم، قال‏:‏ ألا أخبركم عن النفر الثلاثة‏:‏ أما أحدهم، فأوى إلى الله، فآواه الله ، وأما الآخر فاستحيى فاستحيى الله منه، وأما الآخر، فأعرض، فأعرض الله عنه‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:771","bookId":"riyad","type":"hadith","num":771,"kitab":"كتاب الأذكار","isnad":"وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ خرج معاوية رضي الله عنه على حلقة في المسجد، فقال‏:‏ ما أجلسكم‏؟‏ قالوا‏:‏ جلسنا نذكر الله‏.‏ قال‏:‏ آلله ما أجلسكم إلا ذاك‏؟‏ قالوا‏:‏ ما أجلسنا إلا ذاك، قال‏:‏ أما إني لم أستحلفكم تهمة لكم، وما كان أحد بمنزلتي من رسول الله صلى الله عليه وسلم أقل حديثًا مني‏:‏ إن رسول الله صلى الله عليه وسلم خرج على حلقة من أصحابه فقال‏:‏ ‏","matn":"\"‏ما أجلسكم‏؟‏‏\"‏ قالوا‏:‏ جلسنا نذكر الله، ونحمده على ما هدانا للإسلام، ومنَّ به علينا‏.‏ قال‏:‏ ‏\"‏آلله ما أجلسكم إلا ذاك‏؟‏‏\"‏ قالوا‏:‏ والله ما أجلسنا إلا ذلك‏\"‏‏.‏ قال‏:‏ ‏\"‏أما إني لم أستحلفكم تهمة لكم، ولكنه أتاني جبريل فأخبرني أن الله يباهي بكم الملائكة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:772","bookId":"riyad","type":"hadith","num":772,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من قال حين يصبح وحين يمسي‏:‏ سبحان الله وبحمده مائة مرة، لم يأتِ أحد يوم القيامة بأفضل مما جاء به، إلا أحد قال مثل ما قال أو زاد‏\"‏ ‏(‏‏(‏ رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:773","bookId":"riyad","type":"hadith","num":773,"kitab":"كتاب الأذكار","isnad":"وعنه قال‏:‏ جاء رجل إلى النبي صلى الله عليه وسلم، فقال‏:‏ يا رسول الله ما لقيت من عقرب لدغتني البارحة‏!‏ قال‏:‏ ‏","matn":"\"‏أما لو قلت حين أمسيت‏:‏ أعوذ بكلمات الله التامات من شر ما خلق لم تضرك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:774","bookId":"riyad","type":"hadith","num":774,"kitab":"كتاب الأذكار","isnad":"وعنه عنه النبي، صلى الله عليه وسلم، أنه كان يقول إذا أصبح‏:‏ ‏","matn":"\"‏اللهم بك أصبحنا، وبك أمسينا، وبك نحيا، وبك نموت، وإليك النشور‏\"‏‏.‏ وإذا أمسى قال‏:‏ ‏\"‏اللهم بك أمسينا، وبك نحيا، وبك نموت، وإليك المصير‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن‏.‏"},{"id":"riyad:775","bookId":"riyad","type":"hadith","num":775,"kitab":"كتاب الأذكار","isnad":"وعنه أن أبا بكر الصديق رضي الله عنه قال‏:‏ يا رسول الله مرني بكلمات أقولهن إذا أصبحت وإذا أمسيت، قال‏:‏ قل‏:‏ ‏","matn":"\"‏اللهم فاطر السماوات والأرض عالم الغيب والشهادة، رب كل شيء ومليكه أشهد أن لا إله إلا أنت، أعوذ بك من شر نفسي وشر الشيطان وشركه‏\"‏ قال‏:‏ ‏\"‏قلها إذا أصبحت، وإذا أمسيت، وإذا أخذت مضجعك‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن صحيح‏.‏"},{"id":"riyad:776","bookId":"riyad","type":"hadith","num":776,"kitab":"كتاب الأذكار","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ كان نبي الله صلى الله عليه وسلم، إذا أمسى قال‏:‏ أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له‏","matn":"\"‏ قال الراوي‏:‏ أراه قال فيهن‏:‏ ‏\"‏له الملك وله الحمد وهو على كل شيء قدير، رب أسألك خير ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها، رب أعوذ بك من الكسل، وسوء الكبر، رب أعوذ بك من شر ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها، رب أعوذ بك من الكسل، وسوء الكبر، رب أعوذ بك من عذاب النار، وعذاب في القبر‏\"‏ وإذا أصبح قال ذلك أيضًا‏:‏ ‏\"‏أصبحنا وأصبح الملك لله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:777","bookId":"riyad","type":"hadith","num":777,"kitab":"كتاب الأذكار","isnad":"وعن عبد الله بن خُبيب -بضم الخاء المعجمة- رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اقرأ‏:‏ قل هو الله أحد، والمعوذتين حين تمسي وحين تصبح، ثلاث مرات، تكفيك من كل شيء‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن صحيح ‏.‏"},{"id":"riyad:778","bookId":"riyad","type":"hadith","num":778,"kitab":"كتاب الأذكار","isnad":"وعن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما من عبد يقول في صباح كل يوم ومساء كل ليلة‏:‏ بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات، إلا لم يضره شيء‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن صحيح ‏.‏"},{"id":"riyad:779","bookId":"riyad","type":"hadith","num":779,"kitab":"كتاب الأذكار","isnad":"وعن حذيفة وأبي ذر رضي الله عنهما أن رسول الله صلى الله عليه وسلم كان إذا أوى إلى فراشه قال‏:‏ ‏","matn":"\"‏باسمك اللهم أحيا وأموت‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:780","bookId":"riyad","type":"hadith","num":780,"kitab":"كتاب الأذكار","isnad":"وعن علي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال له ولفاطمة، رضي الله عنهما‏:‏ ‏","matn":"\"‏إذا أويتما إلى فراشكما، أو‏:‏ إذا أخذتما مضجعكما - فكبرا ثلاثًا وثلاثين، وسبحا ثلاثًا وثلاثين، واحمدا ثلاثًا وثلاثين‏\"‏ وفي رواية‏:‏ التسبيح أربعًا وثلاثين‏\"‏ وفي رواية‏:‏ ‏\"‏التكبير أربعًا وثلاثين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:781","bookId":"riyad","type":"hadith","num":781,"kitab":"كتاب الأذكار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا أوى أحدكم إلى فراشه، فلينفض فراشه بداخلة إزاره فإنه لا يدري ما خلفه عليه، ثم يقول‏:‏ باسمك ربي وضعت جنبي، وبك أرفعه؛ إن أمسكت نفسي فارحمها، وإن أرسلتها، فاحفظها بما تحفظ به عبادك الصالحين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:782","bookId":"riyad","type":"hadith","num":782,"kitab":"كتاب الأذكار","isnad":"وعن عائشة، رضي الله عنه، أن رسول الله صلى الله عليه وسلم، كان إذا أخذ مضجعه نفث في يديه، وقرأ بالمعوذات ومسح بهما جسده‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لهما‏:‏ ‏","matn":"\"‏أن النبي صلى الله عليه وسلم، كان إذا أوى إلى فراشه كل ليلة جمع كفيه، ثم نفث فيهما فقرأ فيهما‏:‏ قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، ثم مسح بهما ما استطاع من جسده، يبدأ بهما على رأسه ووجهه، وما أقبل من جسده، يفعل ذلك ثلاث مرات‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏. قال أهل اللغة : (( النفث )) نفخ لطيف بلا ريق‏"},{"id":"riyad:783","bookId":"riyad","type":"hadith","num":783,"kitab":"كتاب الأذكار","isnad":"وعن البراء بن عازب رضي الله عنهما، قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إذا أتيت مضجعك فتوضأ وضوءك للصلاة، ثم اضطجع على شقك الأيمن، وقل‏:‏ اللهم أسلمت نفسي إليك، ووجهت وجهي إليك وفوضت أمري إليك، وألجأت ظهري إليك رغبة ورهبة إليك لا ملجأ ولا منجا منك إلا إليك آمنت بكتابك الذي أنزلت، وبنبيك الذي أرسلت، فإن مت، مت على الفطرة، واجعلهن آخر ما تقول‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:784","bookId":"riyad","type":"hadith","num":784,"kitab":"كتاب الأذكار","isnad":"وعن أنس رضي الله عنه، أن النبي صلى الله عليه وسلم، كان إذا أوى فراشه قال‏:‏ ‏","matn":"\"‏الحمد لله الذي أطعمنا وسقانا، وكفانا وآوانا، فكم ممن لا كافي له ولا مئوي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:785","bookId":"riyad","type":"hadith","num":785,"kitab":"كتاب الأذكار","isnad":"وعن حذيفة رضي الله عنه أن رسول الله صلى الله عليه وسلم، كان إذا أراد أن يرقد وضع يده اليمنى تحت خده، ثم يقول‏:‏ ‏","matn":"\"‏اللهم قني عذابك يوم تبعث عبادك‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن ورواه أبو داود من رواية حفصة رضي الله عنه وفيه أنه كان يقوله ثلاث مرات‏)‏‏)‏‏.‏"},{"id":"riyad:786","bookId":"riyad","type":"hadith","num":786,"kitab":"كتاب الدعوات","isnad":"وعن النعمان بن بشير رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الدعاء هو العبادة‏\"‏‏.‏"},{"id":"riyad:787","bookId":"riyad","type":"hadith","num":787,"kitab":"كتاب الدعوات","isnad":"","matn":"وعن عائشة، رضي الله عنها، قالت‏:‏ كان رسول الله صلى الله عليه وسلم، يستحب الجوامع من الدعاء، ويدع ما سوى ذلك‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏"},{"id":"riyad:788","bookId":"riyad","type":"hadith","num":788,"kitab":"كتاب الدعوات","isnad":"وعن أنس رضي الله عنه، قال‏:‏ كان أكثر دعاء النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اللهم آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ زاد مسلم في روايته قال‏:‏ وكان أنس إذا أراد أن يدعو بدعوة دعا بها، وإذا أراد أن يدعو بدعاء دعا بها فيه‏.‏"},{"id":"riyad:789","bookId":"riyad","type":"hadith","num":789,"kitab":"كتاب الدعوات","isnad":"وعن ابن مسعود، رضي الله عنه، أن النبي، صلى الله عليه وسلم، كان يقول‏:‏ ‏","matn":"\"‏اللهم إني أسألك الهدى، والتقى، والعفاف، والغنى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:790","bookId":"riyad","type":"hadith","num":790,"kitab":"كتاب الدعوات","isnad":"وعن طارق بن أشيم، رضي الله عنه، قال‏:‏ كان الرجل إذا أسلم علمه النبي صلى الله عليه وسلم، الصلاة، ثم أمره أن يدعو بهؤلاء الكلمات‏:‏ ‏","matn":"\"‏اللهم اغفر لي، وارحمني، واهدني، وعافني، وارزقني‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له عن طارق أنه سمع النبي صلى الله عليه وسلم، وأتاه رجل، فقال‏:‏ يا رسول الله، كيف أقول حين أسأل ربي‏؟‏ قال‏:‏ ‏\"‏قل‏:‏ اللهم اغفر لي، وارحمني، وعافني، وارزقني، فإن هؤلاء تجمع لك دنياك وآخرتك‏\"‏‏.‏"},{"id":"riyad:791","bookId":"riyad","type":"hadith","num":791,"kitab":"كتاب الدعوات","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اللهم مصرف القلوب صرف قلوبنا على طاعتك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:792","bookId":"riyad","type":"hadith","num":792,"kitab":"كتاب الدعوات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏تعوذوا بالله من جهد البلاء، ودرك الشقاء، وسوء القضاء، وشماته الأعداء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ قال سفيان‏:‏ أشك أني زدت واحدة منها‏.‏"},{"id":"riyad:793","bookId":"riyad","type":"hadith","num":793,"kitab":"كتاب الدعوات","isnad":"وعنه قال‏:‏ كان رسول الله صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:794","bookId":"riyad","type":"hadith","num":794,"kitab":"كتاب الدعوات","isnad":"وعن علي رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏قل‏:‏ اللهم اهدني، وسددني‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏اللهم إني أسألك الهدى، والسداد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:795","bookId":"riyad","type":"hadith","num":795,"kitab":"كتاب الدعوات","isnad":"وعن أنس رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم‏:‏ يقول‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من العجز والكسل والجبن والهرم، والبخل، وأعوذ بك من عذاب القبر، وأعوذ بك من فتنة المحيا والممات‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏وضلع الدين وغلبة الرجال‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:796","bookId":"riyad","type":"hadith","num":796,"kitab":"كتاب الدعوات","isnad":"وعن أبي بكر الصديق رضي الله عنه أنه قال لرسول الله صلى الله عليه وسلم‏:‏ علمني دعاء أدعو به في صلاتي، قال‏:‏ ‏","matn":"\"‏قل‏:‏ اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ ‏\"‏وفي بيتي‏\"‏ وروي‏:‏ ‏\"‏ظلمًا كثيرًا‏\"‏ وروي ‏\"‏كبيرًا‏\"‏ بالثاء المثلثة وبالباء الموحدة، فينبغي أن يجمع بينهما، فقال‏:‏ كثيرًا كبيرًا‏.‏"},{"id":"riyad:797","bookId":"riyad","type":"hadith","num":797,"kitab":"كتاب الدعوات","isnad":"وعن أبي موسى، رضي الله عنه، عن النبي صلى الله عليه وسلم، أنه كان يدعو بهذا الدعاء‏:‏ ‏","matn":"\"‏اللهم اغفر لي خطيئتي وجهلي، وإسرافي في أمري، وما أنت أعلم به مني، اللهم اغفر لي جدي وهزلي، وخطئي وعمدي، وكل ذلك عندي، اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، وأنت على كل شيء قدير‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:798","bookId":"riyad","type":"hadith","num":798,"kitab":"كتاب الدعوات","isnad":"وعن عائشة، رضي الله عنها، أن النبي صلى الله عليه وسلم، كان يقول في دعائه‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:799","bookId":"riyad","type":"hadith","num":799,"kitab":"كتاب الدعوات","isnad":"وعن ابن عمر رضي الله عنه الله عنهما قال‏:‏ كان من دعاء رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:800","bookId":"riyad","type":"hadith","num":800,"kitab":"كتاب الدعوات","isnad":"وعن زيد بن أرقم رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من العجز والكسل، والبخل والهرم، وعذاب القبر، اللهم آت نفسي تقواها، وزكها أنت خير من زكاها، أنت وليها ومولاها، اللهم إني أعوذ بك من علم لا ينفع ومن قلب لا يخشع، ومن نفس لا تشبع، ومن دعوة لا يستجاب لها‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:801","bookId":"riyad","type":"hadith","num":801,"kitab":"كتاب الدعوات","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم، كان يقول‏:‏ ‏","matn":"\"‏اللهم لك أسلمت، وبك آمنت، وعليك توكلت، وإليك أنبت وبك خاصمت، وإليك حاكمت، فاغفر لي ما قدمت، وما أخرت وما أسررت وما أعلنت، أنت المقدم، وأنت المؤخر، لا إله إلا أنت‏\"‏ زاد بعض الرواة‏:‏ ‏\"‏ولا حول ولا قوة إلا بالله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:802","bookId":"riyad","type":"hadith","num":802,"kitab":"كتاب الدعوات","isnad":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم، كان يدعو بهؤلاء الكلمات‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من فتنة النار، وعذاب النار، ومن شر الغنى والفقر‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن صحيح وهذا لفظ أبي داود‏.‏"},{"id":"riyad:803","bookId":"riyad","type":"hadith","num":803,"kitab":"كتاب الدعوات","isnad":"وعن زياد بن علاقة عن عمه، وهو قطبة بن مالك، رضي الله عنه، قال‏:‏ كان النبي صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من منكرات الأخلاق، والأعمال، والأهواء‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:804","bookId":"riyad","type":"hadith","num":804,"kitab":"كتاب الدعوات","isnad":"وعن شكل بن حميد، رضي الله عنه قال‏:‏ قلت يا رسول الله‏:‏ علمني دعاء‏.‏ قال‏:‏ ‏","matn":"\"‏قل‏:‏ اللهم إني أعوذ بك من شر سمعي، ومن شر بصري، ومن شر لساني، ومن شر قلبي، ومن شر مني‏\"‏‏.‏ رواه أبو داود والترمذي وقال حديث حسن‏.‏"},{"id":"riyad:805","bookId":"riyad","type":"hadith","num":805,"kitab":"كتاب الدعوات","isnad":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، كان يقول‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من البرص والجنون، والجذام، وسيئ الأسقام‏\"‏‏.‏ رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:806","bookId":"riyad","type":"hadith","num":806,"kitab":"كتاب الدعوات","isnad":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم ، يقول‏:‏ ‏","matn":"\"‏اللهم إني أعوذ بك من الجوع، فإنه بئس الضجيع، وأعوذ بك من الخيانة، فإنها بئست البطانة‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:807","bookId":"riyad","type":"hadith","num":807,"kitab":"كتاب الدعوات","isnad":"وعن علي، رضي الله عنه، أن مكاتبًا جاءه، فقال‏:‏ إني عجزت عن كتابتي‏.‏ فأعني‏.‏ قال‏:‏ ألا أعلمك كلمات علمنيهن رسول الله صلى الله عليه وسلم، لو كان عليك مثل جبل دينا أداه الله عنك‏؟‏ قل‏:‏ ‏","matn":"\"‏اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:808","bookId":"riyad","type":"hadith","num":808,"kitab":"كتاب الدعوات","isnad":"وعن عمران بن الحصين، رضي الله عنهما، أن النبي صلى الله عليه وسلم علم أباه حصينًا كلمتين يدعو بهما‏:‏ ‏","matn":"\"‏اللهم ألهمني رشدي، وأعذني من شر نفسي‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:809","bookId":"riyad","type":"hadith","num":809,"kitab":"كتاب الدعوات","isnad":"وعن أبي الفضل العباس بن عبد المطلب رضي الله عنه قال‏:‏ قلت يا رسول الله‏:‏ علمني شيئًا أسأله الله تعالى، قال‏:‏ ‏","matn":"\"‏سلوا الله العافية‏\"‏ فمكثت أيامًا، ثم جئت فقلت‏:‏ يا رسول الله‏:‏ علمني شيئًا أسأله الله تعالى، قال لي‏:‏ ‏\"‏يا عباس ‏يا عم رسول الله سلوا الله العافية في الدنيا والآخرة‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:810","bookId":"riyad","type":"hadith","num":810,"kitab":"كتاب الدعوات","isnad":"وعن شهر بن حوشب قال‏:‏ قلت لأم سلمة، رضي الله عنها، يا أم المؤمنين ما كان أكثر دعاء رسول الله صلى الله عليه وسلم، إذا كان عندك‏؟‏ قالت‏:‏ كان أكثر دعائه‏:‏ ‏","matn":"\"‏يا مقلب القلوب ثبت قلبي على دينك‏\"‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:811","bookId":"riyad","type":"hadith","num":811,"kitab":"كتاب الدعوات","isnad":"وعن أبي الدرداء، رضي الله عنه، قال‏:‏ رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏كان من دعاء داود عليه السلام‏:‏ ‏\"‏اللهم إني أسألك حبك، وحب من يحبك، والعمل الذي يبلغني حبك، اللهم اجعل حبك أحب إلى من نفسي، وأهلي، ومن الماء البارد‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:812","bookId":"riyad","type":"hadith","num":812,"kitab":"كتاب الدعوات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ألظوا بيا ذا الجلال والإكرام‏\"‏‏.‏ رواه الترمذي ورواه النسائي من رواية ربيعة بن عامر الصحابي قال الحاكم حديث صحيح الإسناد‏.‏"},{"id":"riyad:813","bookId":"riyad","type":"hadith","num":813,"kitab":"كتاب الدعوات","isnad":"وعن أبي أمامة، رضي الله عنه قال‏:‏ دعا رسول الله صلى الله عليه وسلم، بدعاء كثير لم نحفظ منه شيئًا، قلنا","matn":"\"يا رسول الله دعوت بدعاء كثير لم نحفظ منه شيئا،\" فقال‏:‏ ‏\"‏ألا أدلكم على ما يجمع ذلك كله‏؟‏ تقول‏:‏ ‏\"‏اللهم إني أسألك من خير ما سألك منه نبيك محمد صلى الله عليه وسلم، وأعوذ بك من شر ما استعاذ منه نبيك محمد صلى الله عليه وسلم، وأنت المستعان، وعليك البلاغ، ولا حول ولا قوة إلا بالله‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:814","bookId":"riyad","type":"hadith","num":814,"kitab":"كتاب الدعوات","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ كان من دعاء رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏اللهم إني أسألك موجبات رحمتك، وعزائم مغفرتك، والسلامة من كل إثم، والغنيمة من كل بر، والفوز بالجنة، والنجاة من النار‏\"‏‏.‏ ‏(‏‏(‏رواه الحاكم أبو عبد الله، وقال‏:‏ حديث صحيح على شرط مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:815","bookId":"riyad","type":"hadith","num":815,"kitab":"كتاب الدعوات","isnad":"وعن أبي الدرداء رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما من عبد مسلم يدعو لأخيه بظهر الغيب إلا قال الملك ولك بمثل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:816","bookId":"riyad","type":"hadith","num":816,"kitab":"كتاب الدعوات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم كان يقول‏:‏ ‏","matn":"\"‏دعوة المرء المسلم لأخيه بظهر الغيب مستجابة، عند رأسه ملك موكل كلما دعا لأخيه بخير قال الملك الموكل به‏:‏ آمين، ولك بمثل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:817","bookId":"riyad","type":"hadith","num":817,"kitab":"كتاب الدعوات","isnad":"وعن أسامة بن زيد رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من صنع إليه معروف، فقال لفاعله‏:‏ جزاك الله خيرًا، فقد أبلغ في الثناء‏\"‏‏.‏ رواه الترمذي وقال حديث حسن صحيح ‏.‏"},{"id":"riyad:818","bookId":"riyad","type":"hadith","num":818,"kitab":"كتاب الدعوات","isnad":"وعن جابر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تدعوا على أنفسكم، ولا تدعوا على أولادكم، ولا تدعو على أموالكم، لا توافقوا من الله ساعة يسأل فيها عطاء، فيستجيب لكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:819","bookId":"riyad","type":"hadith","num":819,"kitab":"كتاب الدعوات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:820","bookId":"riyad","type":"hadith","num":820,"kitab":"كتاب الدعوات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يستجاب لأحدكم ما لم يعجل‏:‏ يقول‏:‏ قد دعوت ربي، فلم يستجب لي‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم لا يزال يستجاب للعبد ما لم يدعُ بإثم أو قطيعة رحم ما لم يستعجل‏.‏ قيل يا رسول الله ما الاستعجال‏؟‏ قال يقول قد دعوت وقد دعوت فلم أرَ من يستجب لي فيستحسر عند ذلك ويدع الدعاء‏.‏"},{"id":"riyad:821","bookId":"riyad","type":"hadith","num":821,"kitab":"كتاب الدعوات","isnad":"وعن أبي أمامة رضي الله عنه قال‏:‏ قيل لرسول الله صلى الله عليه وسلم‏:‏ أي الدعاء أسمع‏؟‏ قال‏:‏ ‏","matn":"\"‏جوف الليل الآخر ودبر الصلوات المكتوبات‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏"},{"id":"riyad:822","bookId":"riyad","type":"hadith","num":822,"kitab":"كتاب الدعوات","isnad":"وعن عبادة بن الصامت رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما على الأرض مسلم يدعو الله تعالى بدعوة إلا آتاه الله إياها، أو صرف عنه من السوء مثلها‏.‏ ما لم يدع بإثم، أو قطيعة رحم‏\"‏ فقال رجل من القوم‏:‏ إذًا نكثر قال‏:‏ ‏\"‏الله أكثر‏\"‏‏.‏ رواه الترمذي وقال حديث حسن صحيح‏.‏"},{"id":"riyad:823","bookId":"riyad","type":"hadith","num":823,"kitab":"كتاب الدعوات","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم كان يقول عند الكرب‏:‏ ‏","matn":"\"‏لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:824","bookId":"riyad","type":"hadith","num":824,"kitab":"كتاب الدعوات","isnad":"وعن أبي محمد عبد الرحمن بن أبي بكر الصديق رضي الله عنهما أن أصحاب الصُّفة كانوا أناسًا فقراء، وأن النبي صلى الله عليه وسلم قال مرة‏:‏ ‏","matn":"\"‏من كان عنده طعام اثنين، فليذهب بثالث، ومن كان عنده طعام أربعة، فليذهب بخامس بسادس‏\"‏ أو كما قال‏:‏ وأن أبا بكر رضي الله عنه جاء بثلاثة، وانطلق النبي صلى الله عليه وسلم بعشرة، وأن أبا بكر تعشى عند النبي صلى الله عليه وسلم ثم لبث حتى صلى العشاء، ثم رجع، فجاء بعد ما مضى من الليل ما شاء الله‏.‏ قالت له امرأته‏:‏ ما حبسك عن أضيافك‏؟‏ قال‏:‏ أو ما عشيتهم‏؟‏ قالت‏:‏ أبوا حتى تجيء وقد عرضوا عليهم قال‏:‏ فذهبت أنا، فاختبأت، فقال‏:‏ يا غُنثر، فجدع وسب، وقال‏:‏ كلوا لا هنيئًا، والله لا أطعمه أبدًا، قال‏:‏ وايم الله ما كنا نأخذ من لقمة إلا ربا من أسفلها أكثر منها حتى شبعوا، وصارت أكثر مما كانت قبل ذلك، فنظر إليها أبو بكر فقال لامرأته‏:‏ يا أخت بني فراس ما هذا‏؟‏ قالت‏:‏ لا وقرة عيني لهي الآن أكثر منها قبل ذلك بثلاث مرات‏!‏ فأكل منها أبو بكر وقال‏:‏ إنما كان ذلك من الشيطان، يعني يمينه‏.‏ ثم أكل منها لقمة، ثم حملها إلى النبي صلى الله عليه وسلم فأصبحت عنده، وكان بيننا وبين قوم عهد، فمضى الأجل، فتفرقنا اثني عشر رجلا، مع كل رجل منهم أناس، الله أعلم كم مع كل رجل، فأكلوا منها أجمعون‏.‏ وفي رواية‏:‏ فحلف أبو بكر لا يطعمه، فحلفت المرأة لا تطعمه، فحلف الضيف -أو الأضياف- أن لا يطعمه، أو يطعموه حتى يطعمه، فقال أبو بكر‏:‏ هذه من الشيطان‏!‏ فدعا بالطعام، فأكل وأكلوا، فجعلوا لا يرفعون لقمة إلا ربت من أسفلها أكثر منها، فقال‏:‏ يا أخت بني فراس، ما هذا‏؟‏ فقالت‏:‏ وقرة عيني إنها الآن لأكثر منها قبل أن نأكل، فأكلوا، وبعث بها إلى النبي صلى الله عليه وسلم فذكر أنه أكل منها‏.‏ وفي رواية‏:‏ إن أبا بكر قال لعبد الرحمن‏:‏ دونك أضيافك، فإني منطلق إلى النبي صلى الله عليه وسلم، فافرغ من قراهم قبل أن أجيء، فانطلق عبد الرحمن، فأتاهم بما عنده، فقال‏:‏ اطعموا، فقالوا‏:‏ أين رب منزلنا‏؟‏ قال اطعموا، قالوا‏:‏ ما نحن بآكلين حتى يجيء رب منزلنا، قال‏:‏ اقبلوا عنا قراكم، فإنه إن جاء ولم تطعموا، لنلقين منه، فأبوا، فعرفت أنه يجد علي، فلما جاء تنحيت عنه، فقال‏:‏ ما صنعتم‏؟‏ فأخبروه، فقال‏:‏ يا عبد الرحمن فسكت، ثم قال‏:‏ يا عبد الرحمن، فسكت، فقال‏:‏ يا غُنثر أقسمت عليك إن كنت تسمع صوتي لما جئت‏!‏ فخرجت، فقلت‏:‏ سل أضيافك، فقالوا‏:‏ صدق، أتانا به‏.‏ فقال‏:‏ إنما انتظرتموني والله لا أطعمه الليلة، فقال الآخرون‏:‏ والله لا نطعمه حتى تطعمه، فقال‏:‏ ويلكم ما لكم لا تقبلون عنا قراكم‏؟‏ هات طعامك، فجاء به، فوضع يده، فقال‏:‏ بسم الله‏.‏ الأولى من الشيطان، فأكل وأكلوا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:825","bookId":"riyad","type":"hadith","num":825,"kitab":"كتاب الدعوات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لقد كان فيما قبلكم من الأمم ناس محدثون، فإن يك في أمتي أحد، فإنه عمر‏\"‏ ‏(‏‏(‏رواه البخاري، ورواه مسلم من رواية عائشة، وفي روايتهما قال ابن وهب‏:‏ ‏\"‏محدثون‏\"‏ أي‏:‏ ملهمون‏)‏‏)‏‏.‏"},{"id":"riyad:826","bookId":"riyad","type":"hadith","num":826,"kitab":"كتاب الدعوات","isnad":"","matn":"وعن جابر بن سَمُرة، رضي الله عنهما، قال‏:‏ شكا أهل الكوفة سعدًا، يعني‏:‏ ابن أبي وقاص، رضي الله عنه الله عنه، إلى عمر بن الخطاب، رضي الله عنه، فعزله واستعمل عليهم عمارًا، فشكوا حتى ذكروا أنه لا يحسن يصلي، فأرسل إليه، فقال‏:‏ يا أبا إسحاق، إن هؤلاء يزعمون أنك لا تحسن تصلي، فقال‏:‏ أما أنا والله فإني كنت أصلي بهم رسول الله صلى الله عليه وسلم، لا أخرم عنها أصلي صلاة العشاء فأركد في الأوليين، وأخف في الأخريين، قال‏:‏ ذلك الظن بك يا أبا إسحاق، وأرسل معه رجلا -أو رجالا- إلى الكوفة يسأل عنه أهل الكوفة، فلم يدع مسجدًا إلا سأل عنه، ويثنون معروفًا، حتى دخل مسجدًا لبني عبس، فقام رجل منهم، يقال له أسامة بن قتادة، يكنى أبا سعدة‏.‏ فقال‏:‏ أما إذ نشدتنا فإن سعدًا كان لا يسير بالسرية ولا يقسم بالسوية، ولا يعدل في القضية، قال سعد‏:‏ أم والله لأدعون بثلاث‏:‏ اللهم إن كان عبدك هذا كاذبًا، قام رياء، وسمعة، فأطل عمره، وأطل فقره، وعرضه للفتن‏.‏ وكان بعد ذلك إذا سئل يقول‏:‏ شيخ كبير مفتون، أصابتني دعوة سعد‏.‏ قال عبد الملك بن عمير الرواي عن جابر بن سمرة‏:‏ فأنا رأيته بعد قد سقط حاجباه على عينيه من الكبر، وإنه ليتعرض للجواري في الطرق فيغمزهن‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:827","bookId":"riyad","type":"hadith","num":827,"kitab":"كتاب الدعوات","isnad":"وعن عروة بن الزبير أن سعيد بن زيد بن عمرو بن نفيل، رضي الله عنه الله عنه خاصمته أروى بنت أوس إلى مروْان بن الحكم، وادعت أنه أخذ شيئًا من أرضها، فقال سعيد‏:‏ أنا كنت آخذ من أرضها شيئًا بعد الذي سمعت من رسول الله صلى الله عليه وسلم‏!‏‏؟‏ قال‏:‏ ماذا سمعت من رسول الله صلى الله عليه وسلم‏؟‏ قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من أخذ شبرًا من الأرض ظلمًا، طوقه إلى سبعين أرضين‏\"‏ فقال له مروْان‏:‏ لا أسألك بينة بعد هذا، فقال سعيد‏:‏ اللهم إن كانت كاذبة، فأعمِ بصرها، واقتلها في أرضها، فقال‏:‏ فما ماتت حتى ذهب بصرها وبينما هي تمشي في أرضها إذ وقعت في حفرة فماتت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم عن محمد بن زيد بن عبد الله بن عمر بمعناه وأنه رآها عمياء تلتمس الجدر تقول‏:‏ أصابتني دعوة سعيد، وأنها مرت على بئر في الدار التي خاصمته فيها، فوقعت فيها فكانت قبرها‏.‏"},{"id":"riyad:828","bookId":"riyad","type":"hadith","num":828,"kitab":"كتاب الدعوات","isnad":"وعن جابر بن عبد الله رضي الله عنه الله عنهما قال‏:‏ لما حضرت أحد دعاني أبي من الليل فقال‏:‏ ما رآني إلا مقتولا في أول من يقتل من أصحاب النبي صلى الله عليه وسلم، وإني لا أترك بعدي أعز علي منك غير نفس رسول الله صلى الله عليه وسلم، وإن علي دينا فاقضِ، واستوصِ بأخواتك خيرًا، فأصبحنا، فكان أول قتيل، ودفنت معه آخر في قبره، ثم لم تطب نفسي أن أتركه مع آخر، فاستخرجته بعد ستة أشهر، فإذا هو كيوم وضعته غير أذنه، فجعلته في قبر على حدة‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:829","bookId":"riyad","type":"hadith","num":829,"kitab":"كتاب الدعوات","isnad":"","matn":"وعن أنس رضي الله عنه أن رجلين من أصحاب النبي صلى الله عليه وسلم خرجا من عند النبي صلى الله عليه وسلم، في ليلة مظلمة ومعهما مثل المصباحين بين أيديهما، فلما افترقا، صار مع كل واحد منهما واحد حتى أتى أهله‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ من طرق، وفي بعضها أن الرجلين أسيد بن حضير، وعباد بن بشر رضي الله عنهما‏.‏"},{"id":"riyad:830","bookId":"riyad","type":"hadith","num":830,"kitab":"كتاب الدعوات","isnad":"وعن أبي هريرة، رضي الله عنه ، قال‏:‏ بعث رسول الله صلى الله عليه وسلم عشرة رهط عينًا سرية، وأمَّر عليهم عاصم بن ثابت الأنصاري، رضي الله عنه، فانطلقوا حتى إذا كانوا بالهدأة، بين عسفان ومكة، ذكروا لحي من هذيل يقال لهم‏:‏ بنو لحيان، فنفروا لهم بقريب من مائة رجل رام، فاقتصوا آثارهم، فلما أحس بهم عاصم وأصحابه، لجئوا إلى موضع فأحاط بهم القوم، فقالوا‏:‏ انزلوا، فأعطوا بأيديكم ولكم العهد والميثاق أن لا نقتل منكم أحدًا، فقال عاصم بن ثابت‏:‏ أيها القوم أما أنا، فلا أنزل على ذمة كافر‏:‏ اللهم أخبر عنا نبيك صلى الله عليه وسلم، فرموهم بالنبل فقتلوا عاصمًا، ونزل إليهم ثلاثة نفر على العهد والميثاق، منهم خُبيب، وزيد بن الدِّثِنَّة ورجل آخر‏.‏ فلما استمكنوا منهم أطلقوا أوتار قسيهم، فربطوهم بها، قال الرجل الثالث‏:‏ هذا أول الغدر والله لا أصحبكم إن لي بهؤلاء أسوة، يريد القتلى، فجروه وعالجوه، فأبى أن يصحبهم، فقتلوه، وانطلقوا بخُبيب، وزيد بن الدِّثِنَّة، حتى باعوهما بمكة بعد وقعة بدر، فابتاع بنو الحارث بن عامر بن نوفل بن عبد مناف خُبيبًا، وكان خُبيب هو قتل الحارث يوم بدر، فلبث خُبيب عندهم أسيرًا حتى أجمعوا على قتله، فاستعار من بعض بنات الحارث موسى يستحد بها فأعارته، فدرج بُنيٌّ لها وهي غافلة حتى أتاه، فوجدته مجلسه على فخذه الموسى بيده، ففزعت فزعة عرفها خُبيب، فقال أتخشين أن أقتله ماكنت لأفعل ذلك قالت‏:‏ والله ما رأيت أسيرا خيرا من خُبيب فوالله لقد وجدته يومًا يأكل قطفًا من عنب في يده وإنه لموثق بالحديد وما بمكة من ثمرة، وكانت تقول‏:‏ إنه لرزق رزقه الله خُبيبًا، فلما خرجوا به من الحرم ليقتلوه في الحل، قال لهم خبيب‏:‏ دعوني أصلي ركعتين، فتركوه، فركع ركعتين، فقال‏:‏ والله لولا أن تحسبوا أن ما بي جزع لزدت‏.‏ اللهم أحصهم عددًا، واقتلهم بددًا، ولا تُبقِ منهم أحدًا، وقال‏:‏ فلست أبالي حين أُقتل مســــلمًا**على أي جنب كان لله مصرعــي وذلك في ذات الإله وإن يشأ**يبارك على أوصـــال شلو ممزع وكان خُبيب هو سَنَّ لكل مسلم قُتل صبرًا الصلاة، وأخبر -يعني النبي صلى الله عليه وسلم - أصحابه يوم أصيبوا خبرهم، وبعث ناسٌ من قريش إلى عاصم بن ثابت حين حدثوا أنه قُتل أن يؤتوا بشيء منه يُعرف، وكان قتل رجلا من عظمائهم، فبعث الله لعاصم مثل الظلة من الدبر فحمته من رسلهم، فلم يقدروا أن يقطعوا منه شيئًا‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ قوله‏:‏ الهدأة‏:‏ موضع، والظلة‏:‏ السحاب، الدبر‏:‏ النحل‏.‏ وقوله‏:‏ ‏","matn":"\"‏اقتلهم بَِددًا‏\"‏ بكسر الباء وفتحها، فمن كسر، قال‏:‏ هو جمع بدة بكسر الباء، وهو النصيب، ومعناه‏:‏ اقتلهم حصصًا منقسمة لكل واحد منهم نصيب، ومن فتح ، قال معناه‏:‏ متفرقين في القتل واحدًا بعد واحد من التبديد‏.‏ وفي الباب أحاديثُ كثيرة صحيحة سبقت في مواضعها من هذا الكتاب، منها حديث الغلام الذي كان يأتي الراهب والساحر، ومنها حديث جُريج، وحديث أصحاب الغار الذين أطبقت عليهم الصخرة، وحديث الرجل الذي سمع صوتًا في السحاب يقول‏:‏ اسقِ حديقة فلان، وغير ذلك‏.‏ والدلائل في الباب كثيرة مشهورة، وبالله التوفيق‏.‏"},{"id":"riyad:831","bookId":"riyad","type":"hadith","num":831,"kitab":"كتاب الدعوات","isnad":"","matn":"وعن ابن عمر رضي الله عنهما قال‏:‏ ما سمعت عمر رضي الله عنه يقول لشيء قط‏:‏ إني لأظنه كذا إلا كان كما يظن‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:832","bookId":"riyad","type":"hadith","num":832,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من كان يؤمن بالله واليوم الآخر، فليقل خيرًا، أو ليصمت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وهذا صريح أنه ينبغي أن لا يتكلم إلا إذا كان الكلام خيرًا، وهو الذي ظهرت مصلحته، ومتى شك في ظهور المصلحة، فلا يتكلم‏.‏"},{"id":"riyad:833","bookId":"riyad","type":"hadith","num":833,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قلت‏:‏ يا رسول الله أي المسلمين أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏من سلم المسلمون من لسانه ويده‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:834","bookId":"riyad","type":"hadith","num":834,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن سهل بن سعد قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من يضمن لي ما بين لحييه، وما بين رجليه أضمن له الجنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:835","bookId":"riyad","type":"hadith","num":835,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أنه سمع النبي صلى الله عليه وسلم يقول‏:‏ “إن العبد ليتكلم بالكلمة ما يتبين فيها يزل بها إلى النار أبعد مما بين المشرق والمغرب‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏ ‏ومعني‏:‏ ‏ ‏يتبين‏ ‏ يتفكر أنها خير أم لا.‏"},{"id":"riyad:836","bookId":"riyad","type":"hadith","num":836,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن العبد ليتكلم بالكلمة من رضوان الله تعالى ما يُلقي لها بالا يرفعه الله بها درجات، وإن العبد ليتكلم بالكلمة من سخط الله تعالى لا يُلقي لها بالا يَهوي بها في جهنم‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:837","bookId":"riyad","type":"hadith","num":837,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي عبد الرحمن بلال بن الحارث المزني رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الرجل ليتكلم بالكلمة من رضوان الله تعالى ما كان يظن أن تبلغ ما بلغت يكتب الله له بها رضوانه إلى يوم يلقاه، وإن الرجل ليتكلم بالكلمة من سخط الله ما كان يظن أن تبلغ ما بلغت يكتب الله له بها سخطه إلى يوم يلقاه”‏.‏ رواه مالك في الموطأ والترمذي وقال حديث حسن صحيح‏.‏"},{"id":"riyad:838","bookId":"riyad","type":"hadith","num":838,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن سفيان بن عبد الله رضي الله عنه قال‏:‏ قلت يا رسول الله حدثني بأمر أعتصم به قال‏:‏ ‏","matn":"\"‏ قل ربي الله ثم استقم‏\"‏ قلت‏:‏ يا رسول الله ما أخوف ما تخاف علي‏؟‏ فأخذ بلسان نفسه، ثم قال‏:‏ “هذا”‏.‏ رواه الترمذي وقال حديث حسن صحيح‏.‏"},{"id":"riyad:839","bookId":"riyad","type":"hadith","num":839,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تكثروا الكلام بغير ذكر الله، فإن كثرة الكلام بغير ذكر الله تعالى قسوة للقلب‏!‏ وإن أبعد الناس من الله القلب القاسي‏\"‏‏.‏ رواه الترمذي‏.‏"},{"id":"riyad:840","bookId":"riyad","type":"hadith","num":840,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ومن وقاه الله شر ما بين لحييه، وشر ما بين رجليه دخل الجنة‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:841","bookId":"riyad","type":"hadith","num":841,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عقبة بن عامر رضي الله عنه قال‏:‏ قلت يا رسول الله ما النجاة‏؟‏ قال‏:‏ ‏","matn":"\"‏أمسك عليك لسانك، وليسعك بيتك، وابكِ على خطيئتك‏\"‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:842","bookId":"riyad","type":"hadith","num":842,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏","matn":"‏ “إذا أصبح ابن آدم، فإن الأعضاء كلها تكفر اللسان، تقول‏:‏ اتقِ الله فينا، فإنما نحن بك‏:‏ فإن استقمت استقمنا وإن اعوججت اعوججنا”‏.‏ ‏(‏‏(‏رواه الترمذي‏)‏‏)‏‏.‏ ‏ '‏معني “تكفر اللسان” أي تذل وتخضع ل‏ه.‏"},{"id":"riyad:843","bookId":"riyad","type":"hadith","num":843,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن معاذ رضي الله عنه قال‏:‏ قلت يا رسول الله‏:‏ أخبرني بعمل يدخلني الجنة، ويباعدني من النار‏؟‏ قال‏:‏ ‏","matn":"\"‏لقد سألت عن عظيم، وإنه ليسير على من يسره الله تعالى عليه‏:‏ تعبد الله لا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان وتحج البيت إن استطعت إليه سبيلا ثم قال‏:‏ ألا أدلك على أبواب الخير‏؟‏ الصوم جُنة، والصدقة تطفئ الخطيئة كما يطفئ الماء النار، وصلاة الرجل من جوف الليل” ثم تلا‏:‏ ‏{‏تتجافى جنوبهم عن المضاجع‏}‏ حتى بلغ‏:‏ ‏{‏يعملون‏}‏ ‏(‏‏(‏السجدة‏:‏ 16-17‏)‏‏)‏‏.‏ ثم قال‏:‏ ‏\"‏ألا أخبرك برأس الأمر وعموده وذِروة سنامه‏\"‏ قلت‏\"‏ بلى يا رسول الله، قال‏:‏ رأس الأمر الإسلام، وعموده الصلاة، وذِروة سنامه الجهاد” ثم قال‏:‏ “ألا أخبرك بملاك ذلك كله‏؟‏‏\"‏ قلت‏:‏ بلى يا رسول الله، فأخذ بلسانه قال‏:‏ ‏\"‏كف عليك هذا‏\"‏ قلت‏:‏ يا رسول الله وإنا لمؤاخذون بما نتكلم به‏؟‏ فقال‏:‏ ثكلتك أمك‏!‏ وهل يُكب الناس في النار على وجوههم إلا حصائد ألسنتهم‏؟‏‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح، وقد سبق شرحه في باب قبل هذا‏)‏‏)‏‏.‏"},{"id":"riyad:844","bookId":"riyad","type":"hadith","num":844,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “أتدرون ما الغيبة‏؟‏” قالوا‏:‏ الله ورسوله أعلم قال‏:‏ ‏","matn":"\"‏ذكرك أخاك بما يكره‏\"‏ قيل‏:‏ أفرأيت إن كان في أخي ما أقول‏؟‏ قال‏:‏ ‏\"‏إن كان فيه ما تقول، فقد اغتبته، وإن لم يكن فيه ما تقول فقد بهته”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:845","bookId":"riyad","type":"hadith","num":845,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي بكر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في خطبته يوم النحر بمنًى في حجة الوداع‏:‏ ‏","matn":"\"‏إن دماءكم، وأموالكم، وأعراضكم حرام عليكم كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا، ألا هل بلغت” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:846","bookId":"riyad","type":"hadith","num":846,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها‏:‏ قالت قلت للنبي صلى الله عليه وسلم حسبك من صفية كذا وكذا‏.‏ قال بعض الرواة‏:‏ تعني قصيرة، فقال‏:‏ ‏","matn":"\"‏لقد قلت كلمة لو مُزجت بماء البحر لمزجته‏!‏‏\"‏ قالت‏:‏ وحكيت له إنسانًا فقال‏:‏ “ما أحب أني حكيت إنسانًا وإن لي كذا وكذا”‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال حديث حسن صحيح‏.‏‏)‏‏)‏ ومعني‏:‏ ‏\"‏مزجته‏\"‏ خالطته مخالطة يتغير بها طعمه، أو ريحه لشدة نتنها وقبحها، وهذا الحديث من أبلغ الزواجر عن الغيبة، قال الله تعالى‏:‏ ‏{‏وما ينطق عن الهوى، إن هو إلا وحي يوحى‏}‏‏.‏"},{"id":"riyad:847","bookId":"riyad","type":"hadith","num":847,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “لما عُرج بي مررت بقوم لهم أظفار من نُحاس يخمشون وجوههم وصدورهم، فقلت‏:‏ من هؤلاء يا جبريل‏؟‏ قال‏:‏ هؤلاء الذين يأكلون لحوم الناس، ويقعون في أعراضهم‏!‏”‏.‏ ‏(‏‏(‏رواه أبو داود‏.‏‏)‏‏)‏"},{"id":"riyad:848","bookId":"riyad","type":"hadith","num":848,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كل المسلم على المسلم حرام‏:‏ دمه وعرضه وماله‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:849","bookId":"riyad","type":"hadith","num":849,"kitab":"كتاب الأمور المنهي عنها","isnad":"- وعن أبي الدرداء رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من رد عن عِرض أخيه، رد الله عن وجهه النار يوم القيامة‏\"‏‏.‏‏(‏‏(‏رواه الترمذي وقال حديث حسن‏.‏‏)‏‏)‏"},{"id":"riyad:850","bookId":"riyad","type":"hadith","num":850,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عتبان بن مالك رضي الله عنه في حديثه الطويل المشهور الذي تقدم في باب الرجاء قال‏:‏ قام النبي صلى الله عليه وسلم يصلي فقال‏:‏ ‏","matn":"\"‏أين مالك بن الدخشم‏؟‏ فقال رجل‏:‏ ذلك منافق لا يحب الله ورسوله، فقال النبي صلى الله عليه وسلم‏:‏ “لا تقل ذلك ألا تراه قد قال‏:‏ لا إله إلا الله يريد بذلك وجه الله‏!‏ وإن الله قد حرم على النار من قال لا إله إلا الله يبتغي بذلك وجه الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ \"وعِتبانُ\"بكسر العين عَلَى المشهور، وحُكِي ضمُّها، وبعدها تاءٌ مثناةٌ مِنْ فوق، ثُمَّ باءٌ موحدةٌ. و\"الدُّخْشُمُ\"بضم الدال وإسكان الخاءِ وضمِّ الشين المعجمتين"},{"id":"riyad:851","bookId":"riyad","type":"hadith","num":851,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن كعب بن مالك رضي الله عنه في حديثه الطويل في قصة توبته وقد سبق في بابه التوبة‏.‏ قال‏:‏ قال النبي صلى الله عليه وسلم وهو جالس في القوم بتبوك‏:‏ ‏","matn":"\"‏ما فعل كعب مالك‏؟‏ فقال رجل من بني سلمة‏:‏ يا رسول الله حبسه برداه، والنظر في عطفيه فقال معاذ بن جبل رضي الله عنه بئس ما قلت والله يا رسول الله ما علمنا عليه إلا خيرًا، فسكت رسول الله صلى الله عليه وسلم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ \"عِطْفَاهُ\"جانِباهُ، وهو إشارةٌ إلى إعجابِهِ بنفسهِ."},{"id":"riyad:852","bookId":"riyad","type":"hadith","num":852,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عائشة رضي الله عنها أن رجلا استأذن على النبي صلى الله عليه وسلم فقال‏:‏ “ائذنوا له، بئس أخو العشيرة‏؟‏ ‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ احتج به البخاري في جواز غيبة أهل الفساد وأهل الريب‏.‏"},{"id":"riyad:853","bookId":"riyad","type":"hadith","num":853,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ما أظن فلانًا وفلانًا يعرفان من ديننا شيئًا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ قال الليث بن سعد أحد رواة هذا الحديث‏:‏ هذان الرجلان كانا من المنافقين‏.‏"},{"id":"riyad:854","bookId":"riyad","type":"hadith","num":854,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن فاطمة بنت قيس رضي الله عنها قالت‏:‏ أتيت النبي صلى الله عليه وسلم، فقلت‏:‏ إن أبا الجهم ومعاوية خطباني‏؟‏ فقال رسول الله صلى الله عليه وسلم‏:‏‏","matn":"\"‏أما معاوية، فصعلوك لا مال له ، وأما أبوالجهم، فلا يضع العصا عن عاتقه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لمسلم ‏:‏ ‏\"‏وأما أبو الجهم فضراب للنساء‏\"‏ وهو تفسير لرواية‏:‏ ‏\"‏ لا يضع العصا عن عاتقه‏\"‏ وقيل‏:‏ معناه‏:‏ كثير الأسفار‏.‏"},{"id":"riyad:855","bookId":"riyad","type":"hadith","num":855,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن زيد بن أرقم رضي الله عنه قال‏:‏ خرجنا مع رسول الله صلى الله عليه وسلم في سفر أصاب الناس فيه شدة، فقال عبد الله بن أبي‏:‏ لا تنفقوا على من عند رسول الله حتى ينفضوا وقال‏:‏ لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل فأتيت رسول الله صلى الله عليه وسلم، فأخبرته بذلك، فأرسل إلى عبد الله بن أبي ، فاجتهد يمينه‏:‏ ما فعل، فقالوا‏:‏ كذب زيد رسول الله صلى الله عليه وسلم فوقع في نفسي مما قالوا شدة حتى أنزل الله تعالى تصديقي ‏{‏إذا جاءك المنافقون‏}‏ ثم دعاهم النبي صلى الله عليه وسلم، ليستغفر لهم فلووا رءوسهم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:856","bookId":"riyad","type":"hadith","num":856,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قالت هند امرأة أبي سفيان للنبي صلى الله عليه وسلم ‏:‏ إن أبا سفيان رجل شحيح وليس يعطيني ما يكفيني وولدي إلا ما أخذت منه، وهو لا يعلم‏؟‏ قال‏:‏ ‏","matn":"\"‏خذي ما يكفيك وولدك بالمعروف‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:857","bookId":"riyad","type":"hadith","num":857,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن حذيفة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يدخل الجنة نمام‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:858","bookId":"riyad","type":"hadith","num":858,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم مر بقبرين فقال‏:‏ “إنهما يعذابان ، وما يعذبان في كبير‏!‏ بلى إنه كبير‏:‏ أما أحدهما ، فكان يمشي بالنميمة، وأما الآخر فكان لا يستتر من بوله ‏(‏‏(‏متفق عليه وهذا لفظ إحدى روايات البخاري‏)‏‏)‏‏.‏ قال العلماء‏:‏ معنى ‏","matn":"\"‏وما يعذبان في كبير‏\"‏ أي كبير في زعمهما وقيل‏:‏ كبير تركه عليهما‏.‏"},{"id":"riyad:859","bookId":"riyad","type":"hadith","num":859,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ “ ألا أنبئكم ما العِضَه‏؟‏ هي النميمة، القالة بين الناس‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ العضه: بفتح العين المهملة، وإسكان الضاد المعجمة، وبالهاء على وزن الوجه، وروي: العضة بكسر العين وفتح الضاد المعجمة على وزن العدة، وهي: الكذب والبهتان، وعلى الرواية الأولى: العضه مصدر، يقال: عضهه عضها، أي: رماه بالعضه ."},{"id":"riyad:860","bookId":"riyad","type":"hadith","num":860,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “لا يُبلغني أحد من أصحابي عن أحد شيءا، فإني أحب أن أخرج إلىكم وأنا سليم الصدر‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه أبوداود والترمذي‏)‏‏)‏"},{"id":"riyad:861","bookId":"riyad","type":"hadith","num":861,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “تجدون الناس معادن‏:‏ خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا، وتجدون خيار الناس في هذا الشأن أشدهم له كراهية، وتجدون شر الناس ذا الوجهين، الذي يأتي هؤلاء بوجه، وهؤلاء بوجه‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:862","bookId":"riyad","type":"hadith","num":862,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن محمد بن زيد أن ناسًا قالوا لجده عبد الله بن عمر رضي الله عنهما‏:‏ إنا ندخل على سلاطيننا فنقول لهم بخلاف ما نتكلم إذا خرجنا من عندهم‏.‏ قال‏:‏ كنا نعد هذا نفاقًا على عهد رسول الله صلى الله عليه وسلم ‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:863","bookId":"riyad","type":"hadith","num":863,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ إن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة، وإن الرجل ليصدق حتى يكتب عند الله صديقًا، وإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار، وإن الرجل ليكذب حتى يكتب عند الله كذابًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:864","bookId":"riyad","type":"hadith","num":864,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما، أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أربع من كن فيه كان منافقًا خالصًا، ومن كانت فيه خصلة منهن كانت فيه خصلة من نفاق حتى يدعها‏:‏ إذا أؤتمن خان، وإذا حدث كذب، وإذا عاهد غدر، وإذا خاصم فجر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وقد سبق بيانه مع حديث أبي هريرة بنحوه في باب الوفاء بالعهد‏.‏"},{"id":"riyad:865","bookId":"riyad","type":"hadith","num":865,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏ من تحلم بحلم لم يره، كُلف أن يعقد بين شعيرتين ولن يفعل، ومن استمع إلى حديث قوم وهم له كارهون، صب في أذنيه الآنُك يوم القيامة، ومن صور صورة، عذب وكلف أن ينفخ فيها الروح وليس بنافخ‏\"‏‏.‏رواه البخاري . تحلم أي: قال أنه حلم في نومه ورأى كذا وكذا، وهو كاذب و الآنك بالمد وضم النون وتخفيف الكاف: وهو الرصاص المذاب ."},{"id":"riyad:866","bookId":"riyad","type":"hadith","num":866,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أفرى الفرى أن يري الرجل عينيه ما لم تريا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ ‏ ومعناه يقول‏:‏ رأيت فيما لم يره‏‏.‏"},{"id":"riyad:867","bookId":"riyad","type":"hadith","num":867,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن سمرة بن جندب رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم مما يكثر أن يقول لأصحابه‏:‏‏(‏‏(‏هل رأى أحد منكم رؤيا‏؟‏‏)‏‏)‏ فيقص عليه من شاء الله أن يقص، وإنه قال لنا ذات غداة‏:‏‏(‏‏(‏إنه أتاني الليلة آتيان، وإنهما قالا لي‏:‏ انطلق، وإني انطلقت معهما، وإنا أتينا على رجل مضطجع، وإذا آخر قائم عليه بصخرة، وإذا هو يهوي بالصخرة لرأسه، فيثلغ رأسه، فيتدهده الحجر ها هنا، فيتبع الحجر فليأخذه، فلا يرجع إليه حتى يصح رأسه كما كان، ثم يعود عليه، فيفعل به مثل ما فعل المرة الأولى‏!‏‏","matn":"\"‏ قال‏:‏ ‏\"‏قلت لهما‏:‏ سبحان الله‏!‏ ما هذان‏؟‏ قالا لي‏:‏ انطلق انطلق، فانطلقنا، فأتينا على رجل مستلق لقفاه، وإذا آخر قائم عليه بكلوب من حديد، وإذا هو يأتي أحد شقي وجهه فيشرشر شدقه إلى قفاه، ومنخره إلى قفاه، وعينه إلى قفاه، ثم يتحول إلى الجانب الآخر، فيفعل به مثل ما فعل بالجانب الأول، فما يفرغ من ذلك الجانب حتى يصح ذلك الجانب كما كان، ثم يعود عليه، فيفعل مثل ما فعل في المرة الأولى‏\"‏ قال‏:‏ قلت‏:‏ سبحان الله‏؟‏ ما هذان‏؟‏ قال‏:‏ قالا لي‏:‏ انطلق انطلق، فانطلقنا، فأتينا على مثل التنور‏\"‏ فأحسب أنه قال‏:‏ ‏\"‏فإذا فيه‏:‏ لغط وأصوات، فاطلعنا فيه فإذا فيه رجال ونساء عراة، وإذا هم يأتيهم لهب من أسفل منهم فإذا أتاهم ذلك اللهب ضوضئوا‏.‏ قلت‏:‏ ما هؤلاء‏؟‏ قالا لي‏:‏ انطلق انطلق، فانطلقنا فأتينا على نهر‏\"‏ حسبت أنه كان يقول‏:‏ ‏\"‏أحمر مثل الدم، وإذا في النهر رجل سابح يسبح، وإذا على شط النهر رجل قد جمع عنده حجارة كثيرة، وإذا ذلك السابح يسب ما يسبح، ثم يأتي ذلك الذي قد جمع عنده الحجارة، فيفغر له فاه، فيلقمه حجرًا، فينطلق فيسبح، ثم يرجع إليه، كلما رجع إليه، فغر له فاه، فألقمه حجرًا، قلت لهما‏:‏ ما هذان‏؟‏ قالا لي‏:‏ انطلق انطلق، فانطلقنا، فأتينا على رجل كريه المرآة، أو كأكره ما أنت راء رجلا مرأى فإذا هو عنده نارٌ يحشها ويسعى حولها‏.‏ قلت لهما‏:‏ ما هذا‏؟‏ قال لي‏:‏ انطلق انطلق، فانطلقنا فأتينا على روضة معتمة فيها من كل نور الربيع، وإذا بين ظهري الروضة رجل طويل لا أكاد أرى رأسه طولا في السماء، وإذا حول الرجل من أكثر ولدان رأيتهم قط، قلت‏:‏ ما هذا‏!‏ وما هؤلاء‏؟‏ قالا لي‏:‏ انطلق انطلق، فانطلقنا، فأتينا إلى دوحة عظيمة لم أرَ دوحة قط أعظم منها، ولا أحسن‏!‏ قالا لي‏:‏ ارقَ لي‏:‏ ارقَ فيها، فارتقينا فيها إلى مدينة مبنية بلبن ذهب ولبن فضة، فأتينا باب المدينة فاستفتحنا، ففتح لنا، فدخلناها، فتلقانا رجال شطر من خلقهم كأحسن ما أنت راء‏!‏ وشطر منهم كأقبح ما أنت راء‏!‏ قالا لهم‏:‏ اذهبوا فقعوا في ذلك النهر، وإذا هو نهر معترض يجري كأن ماءه المحض في البياض، فذهبوا فوقعوا فيه‏.‏ ثم رجعوا إلينا قد ذهب ذلك السوء عنهم، فصاروا في أحسن صورة‏.‏ قال‏:‏ قالا لي‏:‏ هذه جنة عدن، وهذاك منزلك، فسما بصري صعدًا، فإذا قصر مثل الربابة البيضاء‏.‏ قالا لي‏:‏ هذاك منزلك‏؟‏ قلت لهما‏:‏ بارك الله فيكما، فذراني فأدخله‏.‏ قالا‏:‏ أما الآن فلا، وأنت داخله‏.‏ قلت لهما‏:‏ فإني رأيت منذ الليلة عجبًا‏؟‏ فما هذا الذي رأيت‏؟‏ قالا لي‏:‏ أما إنا سنخبرك‏:‏ أما الرجل الأول الذي أتيت عليه يثلغ رأسه بالحجر، فإنه الرجل يأخذ القرآن فيرفضه وينام عن الصلاة المكتوبة، وأما الرجل الذي أتيت عليه يشرشر شدقه إلى قفاه، ومنخره إلى قفاه، وعينه إلى قفاه، فإنه الرجل يغدو من بيته فيكذب الكذبة تبلغ الآفاق‏.‏ وأما الرجال والنساء العراة الذين هم في مثل بناء التنور، فإنهم الزناة والزواني، وأما الرجل الذي أتيت عليه يسبح في النهر، ويلقم الحجارة، فإنه آكل الربا، وأما الرجل الكرية المرآة الذي عند النار يحشها ويسعى حولها، فإنه مالك خازن جهنم، وأما الرجل الطويل الذي في الروضة، فإنه إبراهيم، وأما الولدان الذين حوله، فكل مولود مات على الفطرة‏\"‏ وفي رواية البرقاني‏:‏ ‏\"‏ولد على الفطرة‏\"‏ فقال بعض المسلمين‏:‏ يا رسول الله، وأولاد المشركين‏؟‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏وأولاد المشركين، وأما القوم الذين كانوا شطر منهم حسن، وشطر منهم قبيح، فإنهم قوم خلطوا عملا صالحًا وآخر سيئًا، تجاوز الله عنهم‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ وفي رواية له‏:‏ ‏\"‏رأيت الليلة رجلين أتياني فأخرجاني إلى أرض مقدسة‏\"‏ ثم ذكره وقال‏:‏ ‏\"‏فانطلقنا إلى نقب مثل التنور، أعلاه ضيق وأسفله واسع؛ يتوقد تحته نارًا، فإذا ارتفعت ارتفعوا حتى كادوا أن يخرجوا، وإذا خمدت، رجعوا فيها، وفيها رجال ونساء عراة‏\"‏‏.‏ وفيها‏:‏ ‏\"‏حتى أتينا على نهر من دم‏\"‏ ولم يشك ‏\"‏فيه رجل قائم على وسط النهر، وعلى شط النهر رجل، وبين يديه حجارة، فأقبل الرجل الذي في النهر، فإذا أراد أن يخرج، رمى الرجل بحجر في فيه، فرده حيث كان، فجعل كلما جاء ليخرج جعل يرمي في فيه بحجر، فيرجع كما كان‏\"‏‏.‏ وفيها‏:‏ ‏\"‏فصعدا بي الشجرة، فأدخلاني دارًا لم أرَ قط أحسن منها، فيها رجال شيوخ وشباب‏\"‏‏.‏ وفيها‏:‏ ‏\"‏الذي رأيته يشق شدقه فكذاب، يحدث بالكذبة فتحمل عنه حتى تبلغ الآفاق، فيصنع به ما رأيت إلى يوم القيامة‏\"‏ وفيها‏:‏ ‏\"‏الذي رأيته يشدخ رأسه فرجل علمه الله القرآن، فنام عنه بالليل، ولم يعمل فيه بالنهار، فيفعل به إلى يوم القيامة، والدار الأولى التي دخلت دار عامة المؤمنين، وأما هذه الدار فدار الشهداء، وأنا جبريل، وهذا ميكائيل، فارفع رأسك، فرفعت رأسي، فإذا فوقي مثل السحاب، قالا‏:‏ ذاك منزلك، قلت‏:‏ دعاني أدخل منزلي، قالا‏:‏ إنه بقي لك عمر لم تستكمله، فلو استكملته، أتيت منزلك‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏قوله: «يثلغ رأسه» هو بالثاء المثلثة والغين المعجمة، أي: يشدخه ويشقه. قوله: «يتدهده» أي: يتدحرج. و «الكلوب» بفتح الكاف وضم اللام المشددة، وهو معروف. قوله: «فيشرشر» : أي: يقطع. قوله: «ضوضوا» وهو بضادين معجمتين: أي صاحوا. قوله: «فيفغر» هو بالفاء والغين المعجمة، أي: يفتح. قوله «المرآة» هو بفتح الميم، أي: المنظر. قوله: «يحشها» هو بفتح الياء وضم الحاء المهملة والشين المعجمة، أي: يوقدها. قوله: «روضة معتمة» هو بضم الميم وإسكان العين وفتح التاء وتشديد الميم، أي: وافية النبات طويلته. قوله: «دوحة» وهي بفتح الدال وإسكان الواو وبالحاء المهملة: وهي الشجرة الكبيرة. قوله: «المحض» هو بفتح الميم وإسكان الحاء المهملة وبالضاد المعجمة، وهو: اللبن. قوله «فسما بصري» أي: ارتفع. و «صعدا» بضم الصاد والعي، أي: مرتفعا. و «الربابة» بفتح الراء وبالباء الموحدة مكررة، وهي: السحابة"},{"id":"riyad:868","bookId":"riyad","type":"hadith","num":868,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كفى بالمرء كذبًا أن يحدث بكل ما سمع‏\"‏‏.‏ (‏‏(‏رواه مسلم‏)‏‏)‏‏"},{"id":"riyad:869","bookId":"riyad","type":"hadith","num":869,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن سمرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من حدث عني بحديث يرى أنه كذب، فهو أحد الكاذبين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:870","bookId":"riyad","type":"hadith","num":870,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أسماء رضي الله عنها أن امرأة قالت‏:‏ يا رسول الله إن لي ضَّرة فهل علي جناح إن تشبعت من زوجي غير الذي يعطيني‏؟‏ فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏المتشبع بما لم يعطَ كلابس ثوبي زور‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ المتشبع: هو الذي يظهر الشبع وليس بشبعان، ومعناها هنا أنه يظهر أنه حصل له فضيلة وليست حاصلة ولابس ثوبي زور أي: ذي زور وهو الذي يزور على الناس بأن يتزي بزي أهل الزهد أو العلم أو الثروة ليغتر به الناس وليس هو بتلك الصفة وقيل غير ذلك والله أعلم"},{"id":"riyad:871","bookId":"riyad","type":"hadith","num":871,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي بكر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ألا أنبئكم بأكبر الكبائر‏؟‏‏\"‏ قلنا‏:‏ بلى يا رسول الله‏.‏ قال‏:‏ ‏\"‏الإشراك بالله، وعقوق الوالدين‏\"‏ وكان متكئا فجلس، فقال‏:‏ ‏\"‏ألا وقول الزور‏!‏‏\"‏ فما زال يكررها حتى قلنا‏:‏ ليته سكت‏.‏ متفق عليه‏"},{"id":"riyad:872","bookId":"riyad","type":"hadith","num":872,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي زيد ثابت بن الضحاك الأنصاري رضي الله عنه، وهو من أهل بيعة الرضوان قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من حلف على يمين بملة غير الإسلام كاذبًا متعمدًا، فهو كما قال، ومن قتل نفسه بشيء، عُذب به يوم القيامة، وليس على رجل نذر فيما لا يملكه، ولعن المؤمن كقتله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:873","bookId":"riyad","type":"hadith","num":873,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا ينبغي لصدِّيق أن يكون لعانًا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:874","bookId":"riyad","type":"hadith","num":874,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي الدرداء رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يكون اللعانون شفعاء، ولا شهداء يوم القيامة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:875","bookId":"riyad","type":"hadith","num":875,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن سَمُرَة بن جُندب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تلاعنوا بلعنة الله، ولا بغضبه، ولا بالنار‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:876","bookId":"riyad","type":"hadith","num":876,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذي‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:877","bookId":"riyad","type":"hadith","num":877,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي الدرداء رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن العبد إذا لعن شيئًا، صعدت اللعنة إلى السماء، فتغلق أبواب السماء دونها، ثم تهبط إلى الأرض، فتغلق أبوابها دونها، ثم تأخذ يمينًا وشمالا، فإذا لم تجد مساغًا رجعت إلى الذي لُعن، فإن كان أهلا لذلك، وإلا رجعت إلى قائلها‏\"‏‏.‏ رواه أبو داود."},{"id":"riyad:878","bookId":"riyad","type":"hadith","num":878,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عمران بن الحصين رضي الله عنه الله عنهما قال‏:‏ بينما رسول الله صلى الله عليه وسلم في بعض أسفاره، وامرأة من الأنصار على ناقة، فضجرت، فلعنتها، فسمع ذلك رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏خذوا ما عليها ودعوها، فإنها ملعونة‏\"‏ قال عمران‏:‏ فكأني أراها الآن تمشي في الناس ما يَعرض لها أحد‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:879","bookId":"riyad","type":"hadith","num":879,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي برزة نضلة بن عبيد الأسلمي رضي الله عنه قال بينما جارية على ناقة عليها بعض متاع القوم، إذ بصرت بالنبي صلى الله عليه وسلم، وتضايق بهم الجبل، فقالت‏:‏ حل، اللهم العنها‏.‏ فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تصاحبنا ناقة عليها لعنة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏. ‏قوله: حل بفتح الحاء المهملة، وإسكان اللام وهي كلمة لزجر الإبل واعلم أن هذا الحديث قد يستشكل معناه ولا إشكال فيه بل المراد النهي أن تصاحبهم تلك الناقة وليس فيه نهي عن بيعها وذبحها وركوبها في غير صحبة النبي صلى الله عليه وسلم بل كل ذلك وما سواه من التصرفات جائز لا منع منه إلا من مصاحبته صلى الله عليه وسلم بها لأن هذه التصرفات كلها كانت جائزة فمنع بعض منها فبقي الباقي على ما كان والله أعلم"},{"id":"riyad:880","bookId":"riyad","type":"hadith","num":880,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏سباب المسلم فسوق، وقتاله كفر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:881","bookId":"riyad","type":"hadith","num":881,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي ذر رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لا يرمي رجل رجلا بالفسق أو الكفر، إلا ارتدت عليه، إن لم يكن صاحبه كذلك‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:882","bookId":"riyad","type":"hadith","num":882,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏المتسابان ما قالا فعلى البادي منهما حتى يعتدي المظلوم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:883","bookId":"riyad","type":"hadith","num":883,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ أتي النبي صلى الله عليه وسلم برجل قد شرب قال‏:‏ ‏","matn":"\"‏اضربوه‏\"‏ قال أبو هريرة‏:‏ فمنا الضارب بيده، والضارب بنعله، والضارب بثوبه‏.‏ فلما انصرف، قال بعض القوم‏:‏ أخزاك الله، قال‏:‏ ‏\"‏لا تقولوا هذا، لا تُعينوا عليه الشيطان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:884","bookId":"riyad","type":"hadith","num":884,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من قذف مملوكه بالزنا يقام عليه الحد يوم القيامة، إلا أن يكون كما قال‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:885","bookId":"riyad","type":"hadith","num":885,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:886","bookId":"riyad","type":"hadith","num":886,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:887","bookId":"riyad","type":"hadith","num":887,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أحب أن يزحزح عن النار، ويدخل الجنة، فلتأته منيته وهو يؤمن بالله واليوم الآخر، وليأتِ إلى الناس الذي يحب أن يؤتى إليه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وهو بعض حديث طويل سبق في باب طاعة ولاة الأمور‏.‏"},{"id":"riyad:888","bookId":"riyad","type":"hadith","num":888,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تباغضوا، ولا تحاسدوا ولا تدابروا، ولا تقاطعوا، وكونوا عباد الله إخوانًا، ولا يحل لمسلم أن يهجر أخاه فوق ثلاث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:889","bookId":"riyad","type":"hadith","num":889,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏تُفتح أبواب الجنة يوم الاثنين ويوم الخميس، فيغفر لكل عبد لا يشرك بالله شيئًا، إلا رجلا كانت بينه وبين أخيه شحناء فيقال‏:‏ أنظروا هذين حتى يصطلحا‏!‏ أنظروا هذين حتى يصطلحا‏!‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له ‏\"‏تعرض الأعمال في كل يوم خميس واثنين‏\"‏ وذكر نحوه‏.‏"},{"id":"riyad:890","bookId":"riyad","type":"hadith","num":890,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والحسد، فإن الحسد يأكل الحسنات كما تأكل النار الحطب، أو قال‏:‏ العشب‏\"‏‏.‏ رواه أَبُو دَاوُدَ"},{"id":"riyad:891","bookId":"riyad","type":"hadith","num":891,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والظن، فإن الظن أكذب الحديث، ولا تحسسوا، ولا تجسسوا ولا تنافسوا، ولا تحاسدوا، ولا تباغضوا، ولا تدابروا، وكونوا عباد الله إخوانًا كما أمركم‏.‏ المسلم أخو المسلم، لا يظلمه، ولا يخذله ولا يحقره‏.‏ التقوى ههنا، ‏\"‏ ويشير إلى صدره ‏\"‏بحسب امرئ من الشر أن يحقر أخاه المسلم، كل المسلم على المسلم حرام‏:‏ دمه، وعرضه، وماله، إن الله لا ينظر إلى أجسادكم، ولا إلى صوركم، ولكن ينظر إلى قلوبكم وأعمالكم‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏لا تحاسدوا، ولا تباغضوا، ولا تجسسوا، ولا تحسسوا ولا تناجشوا وكونوا عباد الله إخوانًا‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏لا تقاطعوا، ولا تدابروا، ولا تباغضوا ولا تحاسدوا، وكونوا عباد الله إخوانًا‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏لا تهاجروا ولا يبع بعضكم على بيع بعض‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم بكل هذه الروايات، وروى البخاري أكثرها‏)‏‏)‏‏.‏"},{"id":"riyad:892","bookId":"riyad","type":"hadith","num":892,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن معاوية رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إنك إن اتبعت عورات المسلمين أفسدتهم، أو كدت تفسدهم‏\"‏‏.‏ حديث صحيح رواه أبو داود بإسناد صحيح‏.‏"},{"id":"riyad:893","bookId":"riyad","type":"hadith","num":893,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه أنه أتي برجل فقيل له، هذا فلان تقطر لحيته خمرًا، فقال‏:‏ إنَّا قد نهينا عن التجسس، ولكن إن يظهر لنا شئ، نأخذ به‏","matn":"\"‏‏.‏ حديث حسن صحيح رواه أبو داود بإسناد على شرط البخاري ومسلم‏.‏"},{"id":"riyad:894","bookId":"riyad","type":"hadith","num":894,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والظن، فإن الظن أكذب الحديث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:895","bookId":"riyad","type":"hadith","num":895,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏بحسب امرئ من الشر أن يحقر المسلم‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم، وقد سبق قريبًا بطوله‏)‏‏)‏‏.‏"},{"id":"riyad:896","bookId":"riyad","type":"hadith","num":896,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر‏\"‏ فقال رجل‏:‏ إن الرجل يحب أن يكون ثوبه حسنًا، ونعله حسنة، فقال‏:‏ ‏\"‏إن الله جميل يحب الجمال، الكبر بَطَر الحق، وغمط الناس‏\"‏‏.‏‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ومعنى ‏\"‏بَطَر الحق‏\"‏‏:‏ دفعه، ‏\"‏وغمطهم‏\"‏‏:‏ احتقارهم، وقد سبق بيانه أوضح من هذا في باب الكبر‏.‏"},{"id":"riyad:897","bookId":"riyad","type":"hadith","num":897,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جُندب بن عبد الله رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏قال رجل‏:‏ والله لا يغفر الله لفلان، فقال الله عز وجل‏:‏ من ذا الذي يتألى علي أن لا أغفر لفلان‏!‏ فإني قد غفرت له، وأحبطت عملك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:898","bookId":"riyad","type":"hadith","num":898,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن واثلة بن الأسقع رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لا تظهر الشماتة لأخيك، فيرحمه الله ويبتليك‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏ وفي الباب حديث أبي هريرة السابق في باب التجسس‏:‏ ‏\"‏ كل المسلم على المسلم حرام‏\"‏ الحديث‏.‏"},{"id":"riyad:899","bookId":"riyad","type":"hadith","num":899,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ اثنتان في الناس هما بهم كفر‏:‏ الطعن في النسب، والنياحة على الميت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:900","bookId":"riyad","type":"hadith","num":900,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من حمل علينا السلاح، فليس منا، ومن غشنا، فليس منا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له أن رسول الله صلى الله عليه وسلم مر على صبرة طعام، فأدخل يده فيها، فنالت أصابعه بللا، فقال‏:‏ ‏\"‏ ما هذا ياصاحب الطعام‏؟‏‏\"‏ قال أصابته السماء يارسول الله، قال‏:‏ ‏\"‏ أفلا جعلته فوق الطعام حتى يراه الناس‏!‏ من غشنا فليس منا‏\"‏‏.‏"},{"id":"riyad:901","bookId":"riyad","type":"hadith","num":901,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏ لا تناجشوا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:902","bookId":"riyad","type":"hadith","num":902,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم نهى عن النَجَش، ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:903","bookId":"riyad","type":"hadith","num":903,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ ذكر رجل لرسول الله صلى الله عليه وسلم أنه يُخدع في البيوع فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من بايعت‏؟‏ فقل ‏:‏ لا خلابة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏\"‏الخِلابة‏\"‏ بخاء معجمة مكسورة، وباء موحدة‏:‏ وهي الخديعة‏.‏"},{"id":"riyad:904","bookId":"riyad","type":"hadith","num":904,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من خبب زوجة امرئ، أو مملوكه، فليس منا‏\"‏‏.‏ ‏\"‏خَبَب‏\"‏ بخاء معجمة، ثم باء موحدة مكررة‏:‏ أي‏:‏ أفسده وخدعه‏.‏"},{"id":"riyad:905","bookId":"riyad","type":"hadith","num":905,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ أربع من كن فيه، كان منافقًا خالصًا، ومن كانت فيه خصلة منهن، كان فيه خصلة من النفاق حتى يدعها‏:‏ إذا اؤتمن خان، وإذا حدث كذب، وإذا عاهد غدر، وإذا خاصم فجر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:906","bookId":"riyad","type":"hadith","num":906,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود، وابن عمر، وأنس رضي الله عنهم قالوا‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لكل غادر لواء يوم القيامة، يقال‏:‏ هذه غدرة فلان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:907","bookId":"riyad","type":"hadith","num":907,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال ‏:‏ ‏","matn":"\"‏ لكل غادر لواء عند استه يوم القيامة يرفع له بقدر غدره، ألا لا غادر أعظم غدرًا من أمير عامة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:908","bookId":"riyad","type":"hadith","num":908,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ قال الله تعالى‏:‏ ثلاثة أنا خصمهم يوم القيامة ‏:‏ رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا، فاستوفى منه، ولم يعطه أجره‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:909","bookId":"riyad","type":"hadith","num":909,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي ذر رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ ثلاثة لا يكلمهم الله يوم القيامة ولا ينظر إليهم، ولا يزكيهم ولهم عذاب أليم‏\"‏ قال‏:‏ فقرأها رسول الله صلى الله عليه وسلم ثلاث مرار‏.‏ قال أبو ذر‏:‏ خابوا وخسروا من هم يا رسول الله‏؟‏ قال‏:‏ المسبل، والمنان، والمنفق سلعته بالحلف الكاذب‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له ‏:‏ ‏\"‏ المسبل إزاره‏\"‏ يعني‏:‏ المسبل إزاره وثوبه أسفل من الكعبين للخُيلاء‏.‏"},{"id":"riyad:910","bookId":"riyad","type":"hadith","num":910,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عياض بن حمار رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن الله تعالى أوحى إلي أن تواضعوا حتى لا يبغي أحد على أحد، ولا يفخر أحد على أحد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ قال أهل اللغة‏:‏ البغي‏:‏ التعدي والاستطالة‏.‏"},{"id":"riyad:911","bookId":"riyad","type":"hadith","num":911,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا قال الرجل‏:‏ هلك الناس، فهو أهلكهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏الرواية المشهورة‏:‏ ‏ ‏أهلكَُهم‏ ‏ برفع الكاف، وروي بنصبها، وهذا هو الحرام، وأما من قاله ذلك عجبًا بنفسه، وتصاغرا للناس، وارتفاعًا عليهم، فهذا هو الحرام، وأما من قاله لما يرى في الناس من نقص في أمر دينهم، وقاله تحزنًا عليهم، وعلى الدين فلا بأس به‏.‏ هكذا فسره العلماء وفصلوه، ومن قاله من الأئمة الأعلام‏:‏ مالك بن أنس، والخطابي، والحميدي وآخرون، وقد أوضحته في كتاب ‏ ‏الأذكار‏ ‏‏."},{"id":"riyad:912","bookId":"riyad","type":"hadith","num":912,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تقاطعوا ولا تدابروا، ولا تباغضوا، ولا تحاسدوا، وكونوا عباد الله إخوانًا، ولا يحل لمسلم أن يهجر أخاه فوق ثلاث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:913","bookId":"riyad","type":"hadith","num":913,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي أيوب رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليال‏:‏ يلتقيان، فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:914","bookId":"riyad","type":"hadith","num":914,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏تعرض الأعمال في كل اثنين وخميس، فيغفر الله لكل امرئ لا يشرك بالله شيئا، إلا امرءا كانت بينه وبين أخيه شحناء، فيقول‏:‏ اتركوا هذين حتى يصطلحا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:915","bookId":"riyad","type":"hadith","num":915,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن الشيطان قد يئس أن يعبده المصلون في جزيرة العرب، ولكن في والتحريش بينهم ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ التحريش‏:‏ الإفساد وتغيير قلوبهم وتقاطعهم‏.‏"},{"id":"riyad:916","bookId":"riyad","type":"hadith","num":916,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يحل لمسلم أن يهجر أخاه فوق ثلاث، فمن هجر فوق ثلاث، فمات دخل النار‏\"‏‏.‏‏(‏‏(‏رواه أبو داود بإسناد على شرط البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:917","bookId":"riyad","type":"hadith","num":917,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي خراش حدرد بن أبي حدرد الأسلمي، ويقال السلمي الصحابي رضي الله عنه أنه سمع النبي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من هجر أخاه سنة فهو كسفك دمه‏\"‏‏.‏‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:918","bookId":"riyad","type":"hadith","num":918,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يحل لمؤمن أن يهجر مؤمنًا فوق ثلاث، فإن مرت به ثلاث، فليلقه، وليسلم عليه، فإن رد عليه السلام، فقد اشتركا في الأجر، وإن لم يرد عليه، فقد باء بالإثم، وخرج المسلم من الهجرة‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد حسن قال أبو داود‏:‏ إذا كانت الهجرة لله تعالى، فليس من هذا في شيء‏)‏‏)‏‏.‏"},{"id":"riyad:919","bookId":"riyad","type":"hadith","num":919,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا كانوا ثلاثة فلا يتناجى اثنان دون الثالث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏ورواه أبو دواد وزاد‏:‏ قال أبو صالح‏:‏ قلت لابن عمر‏:‏ فأربعة‏؟‏ قال‏:‏ لا يضرك‏.‏ ورواه مالك في الموطأ‏:‏ عن عبد الله بن دينار قال‏:‏ كنت أنا وابن عمر عند دار خالد بن عقبة التي في السوق، فجاء رجل يريد أن يناجيه، وليس مع ابن عمر أحد غيري، فدعا ابن عمر رجلا آخر حتى كنا أربعة فقال لي وللرجل الثالث الذي دعا‏:‏ استأخرا شيئًا، فإني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏لا يتناجى اثنان دون واحد‏\"‏‏.‏"},{"id":"riyad:920","bookId":"riyad","type":"hadith","num":920,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا كنتم ثلاثة، فلا يتناجى اثنان دون الآخر حتى تختلطوا بالناس، من أجل أن ذلك يحزنه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:921","bookId":"riyad","type":"hadith","num":921,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏عذبت امرأة في هِرة حبستها حتى ماتت، فدخلت فيها النار، لا هي أطعمتها وسقتها، إذ هي حبستها، ولا هي تركتها تأكل من خشاش الأرض‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ((خشاش الأرض)) يفتح الخاء المعجمة وبالشين المعجمة المكررة، وهي: هوامها وحشراتها."},{"id":"riyad:922","bookId":"riyad","type":"hadith","num":922,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه أنه مر بفتيان من قريش قد نصبوا طيرًا وهم يرمونه، وقد جعلوا لصاحب الطير كل خاطئة من نبلهم، فلما رأوا ابن عمر تفرقوا، فقال ابن عمر‏:‏ من فعل هذا‏؟‏ لعن الله من فعل هذا، إن رسول الله صلى الله عليه وسلم لعن من اتخذ شيئًا فيه روح غرضًا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏","matn":"\"‏الغَرَض‏\"‏ ‏:‏ بفتح الغين المعجمة والراء، وهو الهدف، والشيء الذي يرمى إليه‏.‏"},{"id":"riyad:923","bookId":"riyad","type":"hadith","num":923,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن تُصبر البهائم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ومعناه‏:‏ تحبس للقتل‏.‏"},{"id":"riyad:924","bookId":"riyad","type":"hadith","num":924,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي علي سويد بن مقرن رضي الله عنه قال‏:‏ لقد رأيتني سابع سبعة من بني مقرن ما لنا خادم إلا واحدة لطمها أصغرنا فأمرنا رسول الله صلى الله عليه وسلم أن نعتقها‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ورواية‏:‏ ‏","matn":"\"‏سابع إخوة لي‏\"‏‏.‏"},{"id":"riyad:925","bookId":"riyad","type":"hadith","num":925,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي مسعود البدري رضي الله عنه قال‏:‏ ‏","matn":"\"‏كنتُ أضرب غلامًا لي بالوسط، فسمعت صوتًا من خلفي‏:‏ ‏\"‏اعلم أبا مسعود‏\"‏ فلم أفهم الصوت من الغضب، فلما دنا مني إذا هو رسول الله صلى الله عليه وسلم فإذا هو يقول‏:‏ ‏\"‏اعلم أبا مسعود أن الله أقدرُ عليك منك على هذا الغلام‏\"‏ فقلت‏:‏ لا أضرب مملوكًا بعده أبدًا‏.‏ ‏(‏‏(‏وفي رواية‏:‏ فسقط السوط من يدي من هيبته‏)‏‏)‏ ‏(‏‏(‏وفي رواية‏:‏ فقلت‏:‏ يارسول الله هو حر لوجه الله تعالى، فقال‏:‏ ‏\"‏أما لو لم تفعل، للفحتك النار، أو لمستك النار‏\"‏ ‏(‏‏(‏رواه مسلم بهذه الروايات‏)‏‏)‏‏.‏"},{"id":"riyad:926","bookId":"riyad","type":"hadith","num":926,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من ضرب غلامًا له حدًا لم يأتهِ، أو لطمه، فإن كفارته أن يعتقه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:927","bookId":"riyad","type":"hadith","num":927,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن هشام بن حكيم بن حزام رضي الله عنه أنه مر بالشام على أناس من الأنباط، وقد أقيموا في الشمس، وصُب على رءوسهم الزيت فقال‏:‏ ما هذا‏؟‏ يُعذبون في الخراج وفي رواية‏:‏ حُبسوا في الجزية‏.‏ فقال هشام‏:‏ أشهد لسمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن الله يعذب الذين يعذبون الناس في الدنيا‏\"‏ فدخل على الأمير، فحدثه، فأمر بهم فخلوا‏\"‏ ‏(‏‏(‏رواه مسلم‏.‏ ‏\"‏الأنباط‏\"‏ الفلاحون من العجم‏)‏‏)‏‏.‏"},{"id":"riyad:928","bookId":"riyad","type":"hadith","num":928,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال‏:‏ رأى رسول الله صلى الله عليه وسلم حمارًا موسوم الوجه، فأنكر ذلك‏؟‏ فقال‏:‏ والله لا أسمه إلا أقصى شيء من الوجه، وأمر بحماره، فكوي في جاعرتيه، فهو أول من كوى الجاعرتين‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏((الجاعرتان)): ناحية الوركين حول الدبر."},{"id":"riyad:929","bookId":"riyad","type":"hadith","num":929,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه أن النبي صلى الله عليه وسلم ‏:‏ مر عليه حمار قد وُسم في وجهه، فقال‏:‏ ‏","matn":"\"‏لعن الله الذي وسمه‏\"‏ ‏(‏‏(‏رواه مسلم‏.‏ وفي رواية لمسلم أيضًا‏:‏ نهى رسول الله صلى الله عليه وسلم عن الضرب في الوجه، وعن الوسم في الوجه‏)‏‏)‏‏.‏"},{"id":"riyad:930","bookId":"riyad","type":"hadith","num":930,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ بعثنا رسول الله صلى الله عليه وسلم في بعث فقال‏:‏ ‏","matn":"\"‏إن وجدتم فلانًا وفلانًا‏\"‏ لرجلين من قريش سماهما ‏\"‏فأحرقوهما بالنار‏\"‏ ثم قال رسول الله صلى الله عليه وسلم حين أردنا الخروج‏:‏ ‏\"‏إني كنت أمرتكم أن تحرقوا فلانًا وفلانًا، وإن النار لا يعذب بها إلا الله، فإن وجدتموهما فاقتلوهما‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:931","bookId":"riyad","type":"hadith","num":931,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ كنا مع رسول الله صلى الله عليه وسلم في سفر، فانطلق لحاجته، فرأينا حمرة معها فرخان، فأخذنا فرخيها، فجاءت الحمرة فجعلت تعرش فجاء النبي صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏من فجع هذه بولدها‏؟‏ ردوا ولدها إليها‏\"‏ ورأى قرية نمل قد حرقناها، فقال‏:‏ ‏\"‏من حرق هذه‏؟‏‏\"‏ قلنا‏:‏ نحن‏.‏ قال‏:‏ ‏\"‏إنه لا ينبغي أن يعذِّب بالنار إلا رب النار‏\"‏‏.‏ قوله‏:‏ ‏ ‏قرية نمل‏ ‏ معناه‏:‏ موضع النمل مع النمل.‏"},{"id":"riyad:932","bookId":"riyad","type":"hadith","num":932,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏مطل الغني ظلم وإذا أُتبع أحدكم على مليء فليتبع‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ معنى ‏\"‏أتبع‏\"‏‏:‏ أحيل‏)‏‏)‏‏.‏"},{"id":"riyad:933","bookId":"riyad","type":"hadith","num":933,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الذي يعود في هبته كالكلب يرجع في قيئه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وفي رواية‏:‏ ‏\"‏مثل الذي يرجع في صدقته، كمثل الكلب يقيء، ثم يعود في قيئه فيأكله‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏العائد في هبته كالعائد في قيئه‏)‏‏)‏‏.‏"},{"id":"riyad:934","bookId":"riyad","type":"hadith","num":934,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عمر بن الخطاب رضي الله عنه قال‏:‏ حملت على فرس في سبيل الله فأضاعه الذي كان عنده، فأردت أن أشتريه، وظننت أنه يبيعه برخص، فسألت النبي صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏لا تشتره ولا تعد في صدقتك وإن أعطاكه بدرهم، فإن العائد في صدقته كالعائد في قيئه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ قوله‏:‏ ‏\"‏حملت على فرس في سبيل الله‏\"‏ معناه‏:‏ تصدقت به على بعض المجاهدين‏.‏"},{"id":"riyad:935","bookId":"riyad","type":"hadith","num":935,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏اجتنبوا السبع الموبقات‏\"‏ قالوا‏:‏ يا رسول الله وما هن‏؟‏ قال‏:‏ ‏\"‏الشرك بالله، والسحر وقتل النفس التي حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات المؤمنات الغافلات‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ ‏\"‏الموبقات‏\"‏ المهلكات‏)‏‏)‏‏.‏"},{"id":"riyad:936","bookId":"riyad","type":"hadith","num":936,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ ‏","matn":"\"‏ لعن رسول الله صلى الله عليه وسلم آكل الربا وموكله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏زاد الترمذي وغيره‏:‏ ‏ ‏ وشاهديه، وكاتبه"},{"id":"riyad:937","bookId":"riyad","type":"hadith","num":937,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ قال الله تعالى‏:‏ أنا أغنى الشركاء عن الشرك، من عمل عملا أشرك فيه معي غيري، تركته وشركه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:938","bookId":"riyad","type":"hadith","num":938,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ إن أول الناس يقضى يوم القيامة عليه رجل اسُتشهد، فأتي به، فعرفه نعمته، فعرفها، قال‏:‏ فما عملت فيها‏؟‏ قال‏:‏ قاتلت فيك حتى اسُتشهدت، قال‏:‏ كذبت، ولكنك قاتلت لأن يقال‏:‏ جريء، فقد قيل، ثم أمر به، فسحب على وجهه حتى ألقي في النار‏.‏ ورجل تعلم العلم وعلمه، وقرأ القرآن، فأتي به، فعرفه نعمه فعرفها‏.‏ قال فما عملت فيها‏؟‏ قال تعلمت العلم وعلمته وقرأت فيك القرآن‏.‏ قال كذبت، ولكنك تعلمت ليقال‏:‏ عالم‏.‏ وقرأت القرآن ليقال‏:‏ هو قارئ، فقد قيل‏:‏ ثم أُمر به، فسُحب على وجهه حتى ألقي في النار، ورجل وسع الله عليه، وأعطاه من أصناف المال، فأتي به فعرفه نعمه، فعرفها‏.‏ قال‏:‏ فما عملت فيها ‏؟‏ قال‏:‏ ما تركت من سبيل تحب أن ينفق فيها إلا أنفقت فيها لك، قال‏:‏ كذبت، ولكنك فعلت ليقال‏:‏ جواد، فقد قيل، ثم أُمر به فسُحب على وجهه ثم ألقي في النار‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏جَريء‏ ‏ بفتح الجيم وكسر الراء وبالمد، أي‏:‏ شجاع حاذق"},{"id":"riyad:939","bookId":"riyad","type":"hadith","num":939,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن عمر رضي الله عنهما أن ناسًا قالوا له‏:‏ إنا ندخل على سلاطيننا فنقول لهم بخلاف ما نتكلم إذا خرجنا من عندهم‏؟‏ قال ابن عمر رضي الله عنهما‏:‏ كنا نعد هذا نفاقًا على عهد رسول الله صلى الله عليه وسلم ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:940","bookId":"riyad","type":"hadith","num":940,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جُندب بن عبد الله بن سفيان رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من سمَّع سمَّع الله به، ومن يرائي الله يرائي به‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏رواه مسلم أيضًا من رواية ابن عباس رضي الله عنه‏)‏‏)‏‏.‏ ‏\"‏سمَّع‏\"‏ بتشديد الميم، ومعناه‏:‏ أظهر عمله للناس رياء ‏\"‏ سمَّع الله به‏\"‏ أي فضحه يوم القيامة، ومعنى‏:‏ ‏\"‏ من راءى‏\"‏ أي‏:‏ من أظهر للناس العمل الصالح ليعظم عندهم ‏\"‏راءى الله به‏\"‏ أي‏:‏ أظهر سريرته على رءوس الخلائق‏.‏"},{"id":"riyad:941","bookId":"riyad","type":"hadith","num":941,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ من تعلم علمًا مما يبتغى به وجه الله عز وجل لا يتعلمه إلا ليصيب به عرضًا من الدنيا، لم يجد عَرف الجنة يوم القيامة‏\"‏ يعني ريحها‏.‏ رواه أبو داود بإسناد صحيح‏ والأحاديث في الباب كثير مشهورة.‏"},{"id":"riyad:942","bookId":"riyad","type":"hadith","num":942,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قيل لرسول الله صلى الله عليه وسلم ‏:‏ أرأيت الرجل يعمل العمل من الخير، ويحمده الناس عليه‏؟‏ قال‏:‏ ‏","matn":"\"‏ تلك عاجل بشرى المؤمن‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:943","bookId":"riyad","type":"hadith","num":943,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كُتب على ابن آدم نصيبه من الزنا مدرك ذلك لا محالة‏:‏ العينان زناهما النظر، والأذنان زناهما الاستماع، واللسان زناه الكلام، واليد زناها البطش، والرجل زناها الخطا، والقلب يهوى ويتمنى، ويصدق ذلك الفرج أو يكذبه‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏.‏ وهذا لفظ مسلم، ورواية البخاري مختصرة‏)‏‏)‏‏.‏"},{"id":"riyad:944","bookId":"riyad","type":"hadith","num":944,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي سعيد الخُدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والجلوس في الطرقات‏\"‏‏.‏ قالوا‏:‏ يا رسول الله ما لنا من مجالسنا بُد نتحدث فيها‏.‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏فإذا أبيتم إلا المجلس، فأعطوا الطريق حقه‏\"‏ قالوا‏:‏ وما حق الطريق يا رسول الله‏؟‏ قال‏:‏ ‏\"‏غض البصر، وكف الأذى، ورد السلام، والأمر المعروف والنهي عن المنكر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:945","bookId":"riyad","type":"hadith","num":945,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي طلحة زيد بن سهل رضي الله عنه قال‏:‏ كنا قعودًا بالأفنية نتحدث فيها فجاء رسول الله صلى الله عليه وسلم فقالم علينا فقال‏:‏ ‏","matn":"\"‏ما لكم ولمجالس الصعدات‏؟‏ فقلنا‏:‏ إنما قعدنا لغير ما بأس، قعدنا نتذاكر، ونتحدث‏.‏ قال‏:‏ ‏\"‏إما لا فأدوا حقها‏:‏ غض البصر، ورد السلام، وحسن الكلام‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏\"‏الصُّعُدات‏\"‏ بضم الصاد والعين، أي‏:‏ الطرقات‏.‏"},{"id":"riyad:946","bookId":"riyad","type":"hadith","num":946,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جرير رضي الله عنه قال‏:‏ سألت رسول الله صلى الله عليه وسلم عن نظر الفجأة فقال‏:‏ ‏","matn":"\"‏اصرف بصرك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:947","bookId":"riyad","type":"hadith","num":947,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أم سلمة رضي الله عنها قالت‏:‏ كنت عند رسول الله صلى الله عليه وسلم وعنده ميمونة، فأقبل ابن أم مكتوم، وذلك بعد أن أُمرنا بالحجاب فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏احتجبا منه‏\"‏ فقلنا‏:‏ يا رسول الله إلىس هو أعمى لا يبصرنا، ولا يعرفنا‏؟‏ فقال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏أفعمياوان أنتما ألستما تبصرانه‏؟‏‏!‏‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي‏:‏ وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:948","bookId":"riyad","type":"hadith","num":948,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي سعيد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا ينظر الرجل إلى عورة الرجل، ولا المرأة إلى عورة المرأة، ولا يفضي الرجل إلى الرجل في ثوب واحد، ولا تفضي المرأة إلى المرأة في ثوب واحد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:949","bookId":"riyad","type":"hadith","num":949,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والدخول على النساء‏\"‏، فقال رجل من الأنصار‏:‏ أفرأيت الحمو‏؟‏ قال‏:‏ ‏\"‏الحمو الموت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏ ‏الحمو‏ ‏ قريب الزوج كأخيه، وابن أخيه، وابن عمه‏.‏"},{"id":"riyad:950","bookId":"riyad","type":"hadith","num":950,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يخلون أحدكم بامرأة إلا مع ذي محرم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:951","bookId":"riyad","type":"hadith","num":951,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن بريدة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏حرمة نساء المجاهدين على القاعدين كحرمة أمهاتهم، ما من رجل من القاعدين يخلف رجلا من المجاهدين في أهله، فيخونه فيهم إلا وقف له يوم القيامة، فيأخذ من حسناته ما شاء حتى يرضى‏\"‏ ثم التفت إلينا رسول الله صلى الله عليه وسلم وقال‏:‏ ‏\"‏ما ظنكم‏؟‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:952","bookId":"riyad","type":"hadith","num":952,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال‏:‏ لعن رسول الله صلى الله عليه وسلم المخنثين من الرجال، والمترجلات من النساء‏.‏ وفي رواية‏:‏ لعن رسول الله صلى الله عليه وسلم المتشبهين من الرجال بالنساء، والمتشبهات من النساء بالرجال‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:953","bookId":"riyad","type":"hadith","num":953,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أبي هريرة رضي الله عنه قال‏:‏ لعن رسول الله صلى الله عليه وسلم الرجل يلبس لبسة المرأة، والمرأة تلبس لبسة الرجل‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:954","bookId":"riyad","type":"hadith","num":954,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏صِنفان من أهل النار لم أرهما‏:‏ قوم معهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مميلات مائلات، رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة، ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ معنى ((كاسيات)) اي من نعمة الله ((عاريات)) من شكرها ، وقيل معناه: تستر بعض بدنها ، وتكشف بعضه إظهارا بحالها ونحوه ، وقيل : معناه تلبس ثوبا رقيقا يصف لون بدنها . وأما ( مائلات ) فقيل : معناه عن طاعة الله ، وما يلزمهن حفظه . ( مميلات ) أي يعلمن غيرهن فعلهن المذموم ، وقيل : مائلات يمشين متبخترات ، مميلات لأكتافهن . وقيل : مائلات يمشطن المشطة المائلة ، وهي مشطة البغايا . مميلات يمشطن غيرهن تلك المشطة . ومعنى ( رءوسهن كأسنمة البخت ) أن يكبرنها ويعظمنها بلف عمامة أو عصابة أو نحوهما ."},{"id":"riyad:955","bookId":"riyad","type":"hadith","num":955,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تأكلوا بالشمال، فإن الشيطان يأكل ويشرب بشماله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:956","bookId":"riyad","type":"hadith","num":956,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله قال‏:‏ ‏","matn":"\"‏لا يأكلن أحدكم بشماله، ولا يشربن بها‏.‏ فإن الشيطان يأكل بشماله ويشرب بها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:957","bookId":"riyad","type":"hadith","num":957,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن اليهود والنصارى لا يصبغون، فخالفوهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ المُرَادُ: خِضَابُ شَعْرِ اللِّحْيةِ والرَّأسِ الأبْيضِ بِصُفْرةٍ أوْ حُمْرةٍ، وأمَّا السَّوادُ، فَمنْهيُّ عَنْهُ كَما سَنَذْكُرُ في الْباب بعْدَهُ، إنْ شَاءَ اللَّه تَعَالَى."},{"id":"riyad:958","bookId":"riyad","type":"hadith","num":958,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن جابر رضي الله عنه قال‏:‏ أتي بأبي قحافة والد أبي بكر الصديق رضي الله عنهما يوم فتح مكة ورأسه ولحيته كالثغامة بياضًا، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏غيروا هذا واجتنبوا السواد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:959","bookId":"riyad","type":"hadith","num":959,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن ابن عمر رضي الله عنهما قال‏:‏ نهى رسول الله صلى الله عليه وسلم عن القزع‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:960","bookId":"riyad","type":"hadith","num":960,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ رأى رسول الله صلى الله عليه وسلم صبيًا قد حلق بعض شعر رأسه وترك بعضه فنهاهم عن ذلك وقال‏:‏ ‏","matn":"\"‏احلقوه كله، أو اتركوه كله‏\"‏‏.‏ رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم‏.‏"},{"id":"riyad:961","bookId":"riyad","type":"hadith","num":961,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن جعفر رضي الله عنهما أن النبي صلى الله عليه وسلم أمهل آل جعفر رضي الله عنه ثلاثًا، ثم أتاهم فقال‏:‏ ‏","matn":"\"‏لا تبكوا على أخي بعد اليوم‏\"‏‏.‏ ثم قال‏:‏ ‏\"‏ادعوا لي بني أخي‏\"‏ فجيء بنا كأننا أفرخ فقال‏:‏ ‏\"‏ادعوا لي الحلاق‏\"‏ فأمره، فحلق رءوسنا‏\"‏‏.‏ رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم‏.‏"},{"id":"riyad:962","bookId":"riyad","type":"hadith","num":962,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن علي قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن تحلق المرأة رأسها‏.‏ ‏(‏‏(‏رواه النسائي‏)‏‏)‏‏.‏"},{"id":"riyad:963","bookId":"riyad","type":"hadith","num":963,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعَنْ أسْمَاءَ رَضِيَ اللَّه عنْهَا: أنَّ امْرأَةً سألتِ النبيَّ ﷺ فَقَالتْ: يا رَسُولَ اللَّه، إنَّ ابْنَتِي أصَابَتْهَا الْحَصْبةُ، فتَمَرَّقَ شَعْرُهَا، وإنِّي زَوَّجْتُها، أفَأَصِلُ فِيهِ؟ فقالَ: لَعَنَ اللَّه الْواصِلةَ والْمَوصولة متفقٌ عليه. وفي روايةٍ: الواصِلَةَ والمُسْتوصِلَةَ. قَوْلَهَا","matn":"\"فَتَمرَّقَ\"هو بالرَّاءِ، ومعناهُ: انْتثر وَسَقَطَ،\"والْوَاصِلة\": التي تَصِلُ شَعْرهَا، أو شَعْر غَيْرِهَا بشَعْرٍ آخَرَ.\"والمَوْصُولة\": التي يُوصَلُ شَعْرُهَا. \"والمُستَوصِلَةُ\": التي تَسْأَلُ منْ يَفْعَلُ ذلكَ لَهَا."},{"id":"riyad:964","bookId":"riyad","type":"hadith","num":964,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعَنْ عائشة رضي اللَّه عنْهَا نَحْوُهُ، متفقٌ عليه."},{"id":"riyad:965","bookId":"riyad","type":"hadith","num":965,"kitab":"كتاب الأمور المنهي عنها","isnad":"وَعَنْ حميْدِ بن عبْدِ الرَّحْمن أنَّهُ سَمِعَ مُعاويَةَ رضي اللَّه عنْهُ عامَ حجَّ علَى المِنْبَر وَتَنَاول قُصَّةً مِنْ شَعْرٍ كَانَتْ في يَدِ حَرِسيٍّ فَقَالَ: يَا أهْل المَدِينَةِ أيْنَ عُلَمَاؤكُمْ؟، سمِعْتُ النبيَّ صَلّى اللهُ عَلَيْهِ وسَلَّم يَنْهَى عنْ مِثْلِ هَذِهِ ويقُولُ","matn":"\"إنًَّمَا هَلَكَتْ بنُو إسْرَائِيل حِينَ اتخذ هذه نِسَاؤُهُمْ\" متفقٌ عليه."},{"id":"riyad:966","bookId":"riyad","type":"hadith","num":966,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن عمر رضي الله عنه أن رسول الله صلى الله عليه وسلم لعن الواصلة والمستوصلة والواشمة والمستوشمة ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:967","bookId":"riyad","type":"hadith","num":967,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن ابن مسعود رضي الله عنه قال‏:‏ لعن الله الواشمات والمستوشمات والمتنمصات والمتفلجات بالحسن، المغيرات خلق الله‏!‏ فقالت له امرأة في ذلك فقال‏:‏ وما لي لا ألعن من لعنه رسول الله صلى الله عليه وسلم وهو في كتاب الله‏؟‏‏!‏ قال الله تعالى‏:‏ ‏{‏وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا‏}‏ ‏(‏‏(‏الحشر‏:‏7‏)‏‏)‏‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ المتفلجة هي: التي تبرد من أسنانها ليتباعد بعضها من بعض قليلا، وتحسنها وهو الوشر. والنامصة: التي تأخذ من شعر حاجب غيرها، وترققه ليصير حسنا. والمتنمصة: التي تأمر من يفعل بها ذلك."},{"id":"riyad:968","bookId":"riyad","type":"hadith","num":968,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من عمل عملا ليس عليه أمرنا فهو رد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:969","bookId":"riyad","type":"hadith","num":969,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي قتادة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا بال أحدكم، فلا يؤخذن ذكره بيمينه، ولا يستنجي بيمينه، ولا يتنفس في الإناء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وفي الباب أحاديث كثيرة صحيحة‏.‏"},{"id":"riyad:970","bookId":"riyad","type":"hadith","num":970,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يمشي أحدكم في نعل واحدة لينعلهما جميعًا او ليخلعهما جميعًا‏\"‏‏.‏ وفي رواية ‏\"‏ أو ليحفهما جميعًا ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:971","bookId":"riyad","type":"hadith","num":971,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا انقطع شسع نعل أحدكم، فلا يمشِ في الأخرى حتى يصلحها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:972","bookId":"riyad","type":"hadith","num":972,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم نهى أن ينتعل الرجل قائمًا‏","matn":"\"‏‏.‏ ((رواه أبو داود بإسناد حسن ))"},{"id":"riyad:973","bookId":"riyad","type":"hadith","num":973,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تتركوا النار في بيوتكم حين تنامون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:974","bookId":"riyad","type":"hadith","num":974,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي موسى الأشعري رضي الله عنه قال‏:‏ احترق بيت بالمدينة على أهله من الليل، فلما حدث رسول الله صلى الله عليه وسلم بشأنهم قال‏:‏ ‏","matn":"\"‏إن هذه النار عدو لكم، فإذا نمتم فأطفئوها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:975","bookId":"riyad","type":"hadith","num":975,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏غطوا الإناء، وأوكئوا السقاء، وأغلقوا الأبواب، وأطفئوا السراج، فإن الشيطان لا يحل سقاء، ولايفتح بابًا ولايكشف إناءً، إن لم يجد أحدكم إلا أن يعرض على إنائه عودا، ويذكر اسم الله، فليفعل، فإن الفويسقة تضرم على أهل البيت بيتهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ ‏\"‏الفويسقة‏:‏ الفأرة، و‏\"‏تضرم‏\"‏‏:‏ تحرق‏.‏"},{"id":"riyad:976","bookId":"riyad","type":"hadith","num":976,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال ‏:‏‏","matn":"\"‏نهينا عن التكلف‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:977","bookId":"riyad","type":"hadith","num":977,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن مسروق قال ‏:‏ دخلنا على عبدالله بن مسعود رضي الله عنه فقال ‏:‏ يا أيها الناس من علم شيئا فليقل به، ومن لم يعلم، فليقل ‏:‏الله أعلم، فإن من العلم أن يقول الرجل لما لا يعلم‏:‏ الله أعلم ‏.‏ قال الله تعالى لنبيه صلى الله عليه وسلم ‏:‏‏{‏قل ما أسألكم عليه من أجر وما أنا من المتكلفين‏}‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:978","bookId":"riyad","type":"hadith","num":978,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عمر بن الخطاب رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏‏","matn":"\"‏الميت يُعذب في قبره بما نِيح عليه ‏\"‏‏. وَفِي روايةٍ:\"مَا نِيحَ علَيْهِ\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:979","bookId":"riyad","type":"hadith","num":979,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ليس منا من ضرب الخدود، وشق الجيوب، ودعا بدعوى الجاهليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:980","bookId":"riyad","type":"hadith","num":980,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي بردة قال‏:‏ وجع أبو موسى، فغشي عليه، ورأسه في حجر امرأة من أهله، فأقبلت تصيح برنة فلم يستطع أن يرد عليها شيئًا، فلما أفاق ،قال ‏:‏ أنا بريء ممن برئ منه رسول الله صلى الله عليه وسلم ، إن رسول الله صلى الله عليه وسلم برئ من الصالقة، والحالقة، والشاقة‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏","matn":"\"‏الصالقة‏\"‏‏:‏ التي ترفع صوتها بالنياحة والندب‏.‏ ‏ والحالقة‏ ‏‏:‏ التي تحلق رأسها عند المصيبة‏ ‏ الشاقة ‏ ‏‏:‏التي تشق ثوبها‏‏.‏"},{"id":"riyad:981","bookId":"riyad","type":"hadith","num":981,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن المغيرة بن شعبة رضي الله عنه قال ‏:‏سمعت رسول الله صلى الله عليه وسلم يقول ‏","matn":"\"‏من نِيح عليه، فإنه يُعذب بما نِيح عليه يوم القيامة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:982","bookId":"riyad","type":"hadith","num":982,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أم عطية نَُسيبة -بضم النون وفتحها- رضي الله عنها قالت ‏:‏ أخذ علينا رسول الله صلى الله عليه وسلم عند البيعة أن لا ننوح‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:983","bookId":"riyad","type":"hadith","num":983,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن النعمان بن بشير رضي الله عنه قال‏:‏ أغمي على عبد الله بن رواحة رضي الله عنه فجعلت أخته تبكي، وتقول‏:‏ واجبلاه، وا كذا وا كذا‏:‏ تعدد عليه فقال حين أفاق‏:‏ ما قلت شيئًا ألا قيل لي ‏:‏أنت كذلك‏؟‏‏!‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:984","bookId":"riyad","type":"hadith","num":984,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ اشتكى سعد بن عبادة رضي الله عنه شكوى فأتاه رسول الله صلى الله عليه وسلم يعوده مع عبد الرحمن بن عوف، وسعد بن أبي وقاص، وعبد الله بن مسعود رضي الله عنهم، فلما دخل عليه، وجده في غشية فقال‏:‏ ‏","matn":"\"‏أقضي‏؟‏‏\"‏ قالوا‏:‏ لا يا رسول الله فبكى رسول الله صلى الله عليه وسلم فلما رأى القوم بكاء النبي صلى الله عليه وسلم بكوا، قال‏:‏ ‏\"‏ألا تسمعون‏؟‏ إن الله لا يُعذب بدمع العين، ولا بحزن القلب، ولكن يعذب بهذا‏\"‏ وأشار إلى لسانه ‏\"‏أو يرحم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:985","bookId":"riyad","type":"hadith","num":985,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي مالك الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏النائحة إذا لم تتب قبل موتها تقام يوم القيامة وعليها سربال من قطران، ودرع من جرب‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:986","bookId":"riyad","type":"hadith","num":986,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أسيد بن أبي أسيد التابعي عن امرأة من المبايعات قالت‏:‏ كان فيما أخذ علينا رسول الله صلى الله عليه وسلم، في المعروف الذي أخذ علينا أن لا نعصيه فيه‏:‏ أن لا نخمش وجهًا، ولا ندعو ويلا، ولا نشق جيبًا، وأن لا ننشر شعرًا‏","matn":"\"‏‏. ((رواه أبو داود بإسناد حسن ))‏"},{"id":"riyad:987","bookId":"riyad","type":"hadith","num":987,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما من ميت يموت، فيقوم باكيهم، فيقول‏:‏ واجبلاه، وأسيداه، أو نحو ذلك إلا وكل به ملكان يلهزانه‏:‏ أهكذا كنت‏؟‏‏!‏‏\"‏‏.‏ رواه الترمذي وقال حديث حسن‏.‏ «اللَّهْزُ»: الدَّفْعُ بِجُمْعِ اليَدِ فِي الصَّدْرِ."},{"id":"riyad:988","bookId":"riyad","type":"hadith","num":988,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏اثنان في الناس هما بهم كفر‏:‏ الطعن في النسب، والنياحة على الميت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:989","bookId":"riyad","type":"hadith","num":989,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عائشة رضي الله عنها قالت‏:‏ سأل رسول الله صلى الله عليه وسلم أناس عن الكهان، فقال‏:‏ ‏","matn":"\"‏ليسوا بشيء‏\"‏ فقالوا‏:‏ يا رسول الله إنهم يحدثونا أحيانًا بشيء، فيكون حقًا‏؟‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏تلك الكلمة من الحق يخطفها الجني‏.‏ فيقرها في أذن وليه، فيخلطون معها مائة كذبة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية للبخاري عن عائشة رضي الله عنها أنها سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏إن الملائكة تنزل في العَنان -وهو السحاب-‏.‏ فتذكر الأمر قضي في السماء، فيسترق الشيطان السمع، فيسمعه، فيوحيه إلى الكهان، فيكذبون معها مائة كذبة من عند أنفسهم‏\"‏‏ قَولُهُ: «فَيَقُرُّهَا» هو بفتح الياء وضم القاف والراء، أي: يُلْقِيها، «والعَنانِ» بفتح العين."},{"id":"riyad:990","bookId":"riyad","type":"hadith","num":990,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن قبيصة بنت أبي عبيد، عن بعض أزواج النبي صلى الله عليه وسلم، ورضي الله عنها، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من أتي عرافًا فسأله عن شيء، فصدقه، لم تقبل له صلاة أربعين يومًا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:991","bookId":"riyad","type":"hadith","num":991,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن قبيصة بن المخارق رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏العِيافة، والطِّيَرة، والطرق، من الجبت‏\"‏‏.‏ ((رواه أبو داود بإسناد حسن)). وقال: «الطَّرْقُ» هُوَ الزَّجْرُ: أيْ زَجْرُ الطَّيْرِ وَهُوَ أنْ يَتَيَمَّنَ أو يَتَشَاءمَ بِطَيَرَانِهِ، فإنْ طَارَ إلَى جِهَةِ اليَمِين، تَيَمَّنَ، وإنْ طَارَ إلَى جِهَةِ اليَسَارِ، تَشَاءمَ. قال أبو داود: «والعِيَافَةُ»: الخَطُّ. قالَ الجَوْهَريُّ في الصِّحَاحِ: الجِبْتُ كَلِمَةٌ تَقَعُ عَلَى الصَّنَمِ وَالكاهِنِ والسَّاحِرِ وَنَحْوِ ذلِكَ."},{"id":"riyad:992","bookId":"riyad","type":"hadith","num":992,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من اقتبس علمًا من النجوم، اقتبس شعبة من السحر زاد ما زاد‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:993","bookId":"riyad","type":"hadith","num":993,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن معاوية بن الحكم رضي الله عنه قال‏:‏ قلت يا رسول الله إني حديث عهد بجاهلية، وقد جاء الله تعالى بالإسلام، وإن منا رجالا يأتون الكهان‏؟‏ قال‏:‏ ‏","matn":"\"‏فلا تأتهم‏\"‏ قلت‏:‏ ومنا رجال يتطيرون‏؟‏ قال‏:‏ ‏\"‏ذلك شيء يجدونه في صدورهم، فلا يصدهم‏\"‏ قلت‏:‏ ومنا رجال يخطون‏؟‏ قال‏:‏ ‏\"‏كان نبي من الأنبياء يخط، فمن وافق خطه، فذاك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:994","bookId":"riyad","type":"hadith","num":994,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي مسعود البدري رضي الله عنه قال‏:‏ إن رسول الله صلى الله عليه وسلم ‏","matn":"\"‏نهى عن ثمن الكلب، ومهر البغي وحُلوان الكاهن‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:995","bookId":"riyad","type":"hadith","num":995,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا عدوى ولا طِيَرة ويعجبني الفأل‏\"‏ قالوا‏:‏ وما الفأل‏؟‏ قال‏:‏ ‏\"‏كلمة طيبة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:996","bookId":"riyad","type":"hadith","num":996,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا عدوى ولا طِيَرة، وإن كان الشؤم في شيء ففي الدار والمرأة، والفرس‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:997","bookId":"riyad","type":"hadith","num":997,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن بريدة رضي الله عنه أن النبي صلى الله عليه وسلم كان لا يتطير‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:998","bookId":"riyad","type":"hadith","num":998,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عروة بن عامر رضي الله عنه قال‏:‏ ذكرت الطِيَرة عند رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏أحسنها الفأل، ولا ترد مسلمًا فإذا رأى أحدكم ما يكره، فليقل‏:‏ اللهم لا يأتي بالحسنات إلا أنت، ولا يدفع السيئات إلا أنت، ولا حول ولا قوة إلا بك‏\"‏‏.‏‏(‏‏(‏حديث صحيح رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:999","bookId":"riyad","type":"hadith","num":999,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الذين يصنعون هذه الصور يعذبون يوم القيامة، يقال لهم‏:‏ أحيوا ما خلقتم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1000","bookId":"riyad","type":"hadith","num":1000,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قدم رسول الله صلى الله عليه وسلم من سفر وقد سترت سهوة لي بقرام فيه تماثيل فلما رآه رسول الله صلى الله عليه وسلم، تلون وجهه، وقال‏:‏ ‏","matn":"\"‏يا عائشة، أشد الناس عذابًا عن الله يوم القيامة الذين يضاهون بخلق الله‏\"‏ قالت‏:‏ فقطعناه، فجعلنا منه وسادة أو وسادتين‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ «القِرامُ» بكسرِ القاف هو: السِّتْرُ. «وَالسَّهْوَةُ» بفتح السينِ المهملة وهي: الصُّفَّةُ تَكُونُ بَيْنَ يَدَيِ البَيْتِ، وقيلَ: هِيَ الطَّاقُ النَّافِذُ في الحائِطِ."},{"id":"riyad:1001","bookId":"riyad","type":"hadith","num":1001,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏كل مصور في النار يجعل له بكل صورة صورها نفس فيعذبه في جهنم‏\"‏ قال ابن عباس‏:‏ فإن كنت لابد فاعلا، فاصنع الشجر وما لا ورح فيه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1002","bookId":"riyad","type":"hadith","num":1002,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من صور في الدنيا، كُلف أن يَنفخ فيها الروح يوم القيامة وليس بنافخ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1003","bookId":"riyad","type":"hadith","num":1003,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن أشد الناس عذابًا يوم القيامة المصورون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1004","bookId":"riyad","type":"hadith","num":1004,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏قال الله تعالى‏:‏ ‏{‏ومن أظلم ممن ذهب يخلق كخلقي‏!‏ فليخلقوا ذرة أو ليخلقوا حبة، أو ليخلقوا شعيرة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1005","bookId":"riyad","type":"hadith","num":1005,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي طلحة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تدخل الملائكة بيتًا فيه كلب ولا صورة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1006","bookId":"riyad","type":"hadith","num":1006,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ وعد رسول الله صلى الله عليه وسلم جبريل أن يأتيه فراث عليه حتى اشتد على رسول الله صلى الله عليه وسلم، فخرج فلقيه جبريل فشكا إليه، فقال‏:‏ إنا لا ندخل بيتًا فيه كلب ولا صورة‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ ‏(‏‏(‏‏","matn":"\"‏راث‏\"‏‏:‏ أبطأ، وهو بالثاء المثلثة‏)‏‏)‏‏.‏"},{"id":"riyad:1007","bookId":"riyad","type":"hadith","num":1007,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ واعد رسول الله صلى الله عليه وسلم جبريل عليه السلام في ساعة أن يأتيه، فجاءت تلك الساعة ولم يأته‏!‏ قالت‏:‏ وكان بيده عصًا، فطرحها من يده وهو يقول‏:‏ ‏","matn":"\"‏ما يخلف الله وعده ولا رسله‏\"‏ ثم التفت، فإذا جرو كلب تحت سريره‏.‏ فقال‏:‏ ‏\"‏متى دخل هذا الكلب‏؟‏‏\"‏ فقلت‏:‏ والله ما دريت به، فأمر به فأخرج، فجاءه جبريل عليه السلام‏:‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏وعدتني، فجلست لك ولم تأتني‏\"‏ فقال‏:‏ منعني الكلب الذي كان في بيتك، إنا لا ندخل بيتًا فيه كلب ولا صورة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1008","bookId":"riyad","type":"hadith","num":1008,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أبي الهياج حيان بن حصين قال‏:‏ قال لي علي بن أبي طالب رضي الله عنه‏:‏ ألا أبعثك على ما بعثني عليه رسول الله صلى الله عليه وسلم ‏؟‏ أن لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1009","bookId":"riyad","type":"hadith","num":1009,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنهما قال سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من اقتنى كلبًا إلا كلب صيد أو ماشية فإنه ينقص فإنه ينقص من أجره كل يوم قيراطان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ ‏ ‏قيراط‏‏‏.‏"},{"id":"riyad:1010","bookId":"riyad","type":"hadith","num":1010,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أمسك كلبًا فإنه ينقص كل يوم من عمله قيراط إلا كلب حرث أو ماشية‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏من اقتنى كلبًا ليس بكلب صيد، ولا ماشية ولا أرض، فإنه ينقص من أجره قيراطان كل يوم‏\"‏‏.‏"},{"id":"riyad:1011","bookId":"riyad","type":"hadith","num":1011,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تصحب الملائكة رفقة كلب أو جرس‏\"‏‏.‏ ((رواه مسلم))"},{"id":"riyad:1012","bookId":"riyad","type":"hadith","num":1012,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الجرس مزامير الشيطان‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:1013","bookId":"riyad","type":"hadith","num":1013,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن ابن عمر رضي الله عنهما قال‏:‏ نهى رسول الله صلى الله عليه وسلم عن الجلالة في الإبل أن يركب عليها‏.‏ ((رواه أبو داود بإسناد صحيح ))"},{"id":"riyad:1014","bookId":"riyad","type":"hadith","num":1014,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏البصاق في المسجد خطيئة، وكفارتها دفنها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ والمرادُ بِدَفْنِهَا إذَا كَانَ المَسْجِدُ تُرَابًا أوْ رَمْلًا ونَحْوَهُ فَيُوَارِيهَا تَحْتَ تُرَابِهِ. قالَ أبُو المحاسِنِ الرُّويَانِي مِنْ أصحابِنا في كِتَابِهِ (البحر) وقِيلَ: المُرَادُ بِدَفْنِهَا إخْراجُهَا مِنَ المَسْجِدِ، أمَّا إِذَا كَانَ المَسْجِدُ مُبَلَّطًا أَوْ مُجَصَّصًا، فَدَلَكَهَا عَلَيْهِ بِمَدَاسِهِ أَوْ بِغَيْرِهِ كَمَا يَفْعَلُهُ كَثيرٌ مِنَ الجُهَّالِ، فَلَيْسَ ذَلِكَ بِدَفْنٍ، بَلْ زِيَادَةٌ فِي الخَطِيئَةِ وَتَكْثِيرٌ لِلقَذَرِ في المَسْجِدِ، وَعَلَى مَنْ فَعَلَ ذَلِكَ أنْ يَمْسَحَهُ بَعْدَ ذَلِكَ بِثَوْبِهِ أَوْ بِيَدِهِ أَوْ غَيرِهِ أَوْ يَغْسِلَهُ."},{"id":"riyad:1015","bookId":"riyad","type":"hadith","num":1015,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم رأى في جدار القبلة مخاطا أو بزاقا أو نخامة فحكه ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1016","bookId":"riyad","type":"hadith","num":1016,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن هذه المساجد لا تصلح لشيء من البول ولا القذر، إنما هي لذكر الله تعالى، وقراءة القرآن‏\"‏ أو كما قال رسول الله صلى الله عليه وسلم ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1017","bookId":"riyad","type":"hadith","num":1017,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من سمع رجلا ينشد ضالة في المسجد فليقل‏:‏ لا ردها الله عليك، فإن المساجد لم تبنَ لهذا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1018","bookId":"riyad","type":"hadith","num":1018,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا رأيتم من يبيع أو يبتاع في المسجد، فقولوا‏:‏ لا أربح الله تجارتك، وإذا رأيتم من ينشد ضالة فقولوا‏:‏ لا ردها الله عليك‏\"‏‏.‏ رواه الترمذي، وقال: (حَدِيثٌ حَسَنٌ)."},{"id":"riyad:1019","bookId":"riyad","type":"hadith","num":1019,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن بريدة رضي الله عنه أن رجلا نشد في المسجد فقال‏:‏ من دعا إلى الجمل الأحمر، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا وجدت، إنما بنيت المساجد لم بنيت له‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1020","bookId":"riyad","type":"hadith","num":1020,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه أن رسول الله صلى الله عليه وسلم نهى عن الشراء والبيع في المسجد، وأن تنشد فيه ضالة، أو ينشد فيه شعر‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال حديث حسن‏)‏‏)‏"},{"id":"riyad:1021","bookId":"riyad","type":"hadith","num":1021,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن السائب بن زيد الصحابي رضي الله عنه قال‏:‏ كنت في المسجد فحصبني رجل، فنظرت فإذا عمر بن الخطاب رضي الله عنه فقال‏:‏ اذهب فائتني بهذين، فجئته بهما، فقال‏:‏ من أين أنتما‏؟‏ فقالا‏:‏ من أهل الطائف، فقال‏:‏ لو كنتما من أهل البلد، لأوجعتكما، ترفعان أصواتكما في مسجد رسول الله صلى الله عليه وسلم ‏!‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1022","bookId":"riyad","type":"hadith","num":1022,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من أكل من هذه الشجرة -يعني الثوم- فلا يقربن مسجدنا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏مساجدنا‏\"‏‏.‏"},{"id":"riyad:1023","bookId":"riyad","type":"hadith","num":1023,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أكل من هذه الشجرة، فلا يقربنا، ولا يصلين معنا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1024","bookId":"riyad","type":"hadith","num":1024,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أكل ثومًا أو بصلا فليعتزلنا، أو فليعتزل مسجدنا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏من أكل البصل، والثوم، الكراث، فلا يقربن مسجدنا، فإن الملائكة تتأذى مما يتأذى منه بنو آدم‏\"‏‏.‏"},{"id":"riyad:1025","bookId":"riyad","type":"hadith","num":1025,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن عمر بن الخطاب رضي الله عنه أنه خطب يوم الجمعة فقال في خطبته‏:‏ ثم إنكم أيها الناس تأكلون شجرتين ما أراهما إلا خبيثتين‏:‏ البصل، والثوم -لقد رأيت رسول الله صلى الله عليه وسلم إذا وجد ريحهما من الرجل في المسجد أمر به، فأخرج إلى البقيع، فمن أكلهما، فليمتهما طبخًا‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1026","bookId":"riyad","type":"hadith","num":1026,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن معاذ بن أنس الجهني، رضي الله عنه، أن النبي صلى الله عليه وسلم نهى عن الحبوة يوم الجمعة والإمام يخطب ‏(‏‏(‏رواه أبو داود والترمذي وقالا‏:‏ حديث حسن‏)‏‏)‏"},{"id":"riyad:1027","bookId":"riyad","type":"hadith","num":1027,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أم سلمة رضي الله عنها قالت قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من كان له ذبح يذبحه، فإذا أهل هلال ذي الحجة، فلا يأخذن من شعره ولا من أظفاره شيئًا حتى يضحي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1028","bookId":"riyad","type":"hadith","num":1028,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر، رضي الله عنهما، عن النبي صلى الله عليه وسلم ، قال‏:‏ ‏","matn":"\"‏إن الله تعالى ينهاكم أن تحلفوا بآبائكم، فمن كان حالفًا، فليحلف بالله، أو ليصمت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية في الصحيح ‏\"‏فمن كان حالفًا فلا يحلف إلا بالله أو ليسكت‏\"‏‏.‏"},{"id":"riyad:1029","bookId":"riyad","type":"hadith","num":1029,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الرحمن بن سَمُرَة، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تحلفوا بالطواغي، ولا بآبائكم‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏\"‏الطواغي‏\"‏‏:‏ جمع طاغية، وهي الأصنام، ومنه الحديث‏:‏ ‏\"‏هذه طاغية دوس‏\"‏‏:‏ أي‏:‏ صنمهم ومعبودهم، وروي في غير مسلم‏:‏ ‏\"‏بالطواغيت‏\"‏ جمع طاغوت، وهو الشيطان والصنم‏.‏"},{"id":"riyad:1030","bookId":"riyad","type":"hadith","num":1030,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن بريدة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من حلف بالأمانة، فليس منا‏\"‏‏.‏ ‏(‏‏(‏حديث صحيح رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:1031","bookId":"riyad","type":"hadith","num":1031,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من حلف فقال‏:‏ إني بريء من الإسلام، فإن كان كاذبًا، فهو كما قال، وإن كان صادقًا، فلن يرجع إلى الإسلام سالمًا‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏"},{"id":"riyad:1032","bookId":"riyad","type":"hadith","num":1032,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أنه سمع رجلا يقول‏:‏ لا والكعبة، قال ابن عمر‏:‏ لا تحلف بغير الله، فإني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من حلف بغير الله، فقد كفر أو أشرك‏\"‏‏.‏‏(‏‏(‏ رواه الترمذي وقال حديث حسن‏)‏‏)‏ وفسر بعض العلماء قوله‏:‏ ‏\"‏كفر أو أشرك‏\"‏ على التغليظ، كما روي أن النبي صلى الله عليه وسلم قال‏:‏ ‏\"‏الرياء شرك‏\"‏‏.‏"},{"id":"riyad:1033","bookId":"riyad","type":"hadith","num":1033,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من خلف على مال امرئ مسلم بغير حقه، لقي الله وهو عليه غضبان‏\"‏ قال‏:‏ ثم قرأ علينا رسول الله صلى الله عليه وسلم مصداقه من كتاب الله عز وجل‏:‏ ‏{‏إن الذين يشترون بعهد الله وأيمانهم ثمنًا قليلا‏}‏ ‏(‏‏(‏آل عمران‏:‏ 77‏)‏‏)‏ إلى آخر الآية‏:‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1034","bookId":"riyad","type":"hadith","num":1034,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي أُمامة إياس بن ثعلبة الحارثي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من اقتطع حق امرئ مسلم بيمينه، فقد أوجب الله له النار‏.‏ -وحرم عليه الجنة‏\"‏ فقال له رجل‏:‏ وإن كان شيئًا يسيرًا يا رسول الله‏؟‏ قال‏:‏ ‏\"‏وإن كان قضيبًا من أراك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1035","bookId":"riyad","type":"hadith","num":1035,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الكبائر‏:‏ الإشراك بالله، وعقوق الوالدين، وقتل النفس، واليمين الغموس‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ وفي رواية‏:‏ أن أعرابيًا جاء إلى النبي صلى الله عليه وسلم فقال‏:‏ يا رسول الله ما الكبائر‏؟‏ قال‏:‏ ‏ ‏الإشراك بالله‏ ‏ قال‏:‏ ثم ماذا‏؟‏ قال‏:‏ ‏ ‏اليمين الغموس‏ ‏ قلت‏:‏ وما اليمين الغموس‏؟‏ قال‏:‏ ‏ ‏الذي يقتطع مال امرئ مسلم‏ ‏ يعني بيمين هو فيها كاذب"},{"id":"riyad:1036","bookId":"riyad","type":"hadith","num":1036,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عبد الرحمن بن سَمُرَة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏وإذا حلفت على يمين، فرأيت غيرها خيرًا منها، فائت الذي هو خير، وكفر عن يمينك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1037","bookId":"riyad","type":"hadith","num":1037,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من حلف على يمين، فرأى غيرها خيرًا منها، فليكفر عن يمينه، وليفعل الذي هو خير‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1038","bookId":"riyad","type":"hadith","num":1038,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إني والله إن شاء الله لا أحلف على يمين، ثم أرى خيرًا منها إلا كفرت عن يميني، وأتيت الذي هو خير‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1039","bookId":"riyad","type":"hadith","num":1039,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لأن يلج أحدكم في يمينه في أهله آثم له عند الله تعالى من أن يعطي كفارته التي فرض الله عليه‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ قوله‏:‏ ‏\"‏يلَجّ‏\"‏ بفتح اللام، وتشديد الجيم‏:‏ أي يتمادى فيها، ولا يكفر، قوله‏:‏ ‏\"‏آثم‏\"‏ هو بالثاء المثلثة، أي‏:‏ أكثر إثمًا‏.‏"},{"id":"riyad:1040","bookId":"riyad","type":"hadith","num":1040,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ أنزلت هذه الآية‏:‏ ‏{‏لا يؤاخذكم الله باللغو في أيمانكم‏}‏ في قول الرجل‏:‏ لا والله، وبلى والله‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1041","bookId":"riyad","type":"hadith","num":1041,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏الحلف منفقة للسلعة، ممحقة للكسب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1042","bookId":"riyad","type":"hadith","num":1042,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي قتادة رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إياكم وكثرة الحلف في البيع، فإنه ينفق ثم يمحق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1043","bookId":"riyad","type":"hadith","num":1043,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يسأل بوجه الله إلا الجنة‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:1044","bookId":"riyad","type":"hadith","num":1044,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من استعاذ بالله فأعيذوه، ومن سأل بالله، فأعطوه، ومن دعاكم فأجيبوه، ومن صنع إليكم معروفًا فكافئوه، فإن لم تجدوا ما تكافئونه به، فادعوا له حتى تروا أنكم قد كافأتموه‏\"‏‏.‏ ‏(‏‏(‏حديث صحيح رواه أبو داود والنسائي بأسانيد الصحيحين‏)‏‏)‏"},{"id":"riyad:1045","bookId":"riyad","type":"hadith","num":1045,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن أخنع اسم عند الله عز وجل رجل تسمى ملك الأملاك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ قال سُفيانُ بن عُيَيْنَةَ: «مَلِكُ الأَمْلاَكِ» مِثْلُ: شَاهِن شَاهِ."},{"id":"riyad:1046","bookId":"riyad","type":"hadith","num":1046,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن بريدة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تقولوا للمنافق سيد، فإنه إن يكن سيدًا، فقد أسخطتم ربكم عز وجل‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:1047","bookId":"riyad","type":"hadith","num":1047,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم دخل على أم السائب، أو أم المسيب فقال‏:‏ ‏","matn":"\"‏مالك يا أم السائب -أو يا أم المسيب- تزفزفين‏؟‏ ‏\"‏ قالت‏:‏ الحمى لا بارك الله فيها، فقال‏:‏ ‏\"‏لا تسبي الحمى، فإنها تذهب خطايا بني آدم، كما يذهب الكير خبث الحديد‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ «تُزَفْزِفِينَ» أيْ تَتَحَرَّكِينَ حَرَكَةً سَريعَةً، وَمَعْنَاهُ: تَرْتَعِدِين. وَهُوَ بِضَمِّ التاء وبالزاي المكررة والفاء المكررة، وَرُوِيَ أيضًا بالراء المكررة والقافينِ."},{"id":"riyad:1048","bookId":"riyad","type":"hadith","num":1048,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي المنذر أبي بن كعب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تسبوا الريح، فإذا رأيتم ما تكرهون، فقولوا‏:‏ اللهم إنا نسألك من خير هذه الريح وخير ما فيها وخير ما أُمرت به، ونعوذ بك من شر هذه الريح وشر ما فيها وشر ما أُمرت به‏\"‏‏.‏‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏"},{"id":"riyad:1049","bookId":"riyad","type":"hadith","num":1049,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏الريح من روح الله، تأتي بالرحمة، وتأتي بالعذاب، فإذا رأيتموها فلا تسبوها، وسلوا الله خيرها، واستعيذوا بالله من شرها‏\"‏‏.‏‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏) قوله صلى الله عليه وسلم من روح الله هو بفتح الراء أي رحمته بعباده‏"},{"id":"riyad:1050","bookId":"riyad","type":"hadith","num":1050,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ كان النبي صلى الله عليه وسلم إذا عصفت الريح قال‏:‏ اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أُرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أُرسلت به‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1051","bookId":"riyad","type":"hadith","num":1051,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن زيد بن خادل الجهني رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تسبوا الديك، فإنه يوقظ للصلاة‏\"‏‏.‏‏(‏‏(‏ رواه أبو داود بإسناد صحيح‏)‏‏)‏"},{"id":"riyad:1052","bookId":"riyad","type":"hadith","num":1052,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن زيد بن خالد رضي الله عنه قال‏:‏ صلى بنا رسول الله صلى الله عليه وسلم صلاة الصبح بالحديبية في أثر سماء كانت من الليل، فلما انصرف أقبل على الناس، فقال‏:‏ ‏","matn":"\"‏هل تدرون ماذا قال ربكم‏؟‏ ‏\"‏ قالوا‏:‏ الله ورسوله أعلم‏.‏ قال‏:‏ قال‏:‏ ‏\"‏أصبح من عبادي مؤمن بي وكافر بي ، فأما من قال‏:‏ مُطِرْنَا بفضل الله ورحمته، فذلك مؤمن بي كافر بالكواكب، وأما من قال‏:‏ مُطِرْنَا بنوء كذا وكذا، فذلك كافر بي مؤمن بالكواكب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ والسماء هنا‏:‏ المطر‏‏‏.‏"},{"id":"riyad:1053","bookId":"riyad","type":"hadith","num":1053,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا قال رجل لأخيه‏:‏ يا كافر، فقد باء بها أحدهما، فإن كان كما قال وإلا رجعت عليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1054","bookId":"riyad","type":"hadith","num":1054,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي ذر رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من دعا رجلا بالكفر، أو قال‏:‏ عدو الله، وليس كذلك إلا حار عليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ حار‏ ‏ رجع‏‏.‏"},{"id":"riyad:1055","bookId":"riyad","type":"hadith","num":1055,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذي‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1056","bookId":"riyad","type":"hadith","num":1056,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما كان الفحش في شيء إلا شانه، وما كان الحياء في شيء إلا زانه‏\"‏‏.‏‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1057","bookId":"riyad","type":"hadith","num":1057,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏هلك المتنطعون‏\"‏، قالها ثلاثًا‏.‏ ‏(‏‏(‏رواه مسلم‏.‏‏\"‏المتنطعون‏\"‏‏:‏ المبالغون في الأمور‏)‏‏)‏‏.‏"},{"id":"riyad:1058","bookId":"riyad","type":"hadith","num":1058,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله يبغض البليغ من الرجال الذي يتخلل بلسانه كما تتخلل البقرة‏\"‏‏.‏‏(‏‏(‏رواه أبو داود والترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1059","bookId":"riyad","type":"hadith","num":1059,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر بن عبد الله رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن من أحبكم إلي، وأقربكم مني مجلسًا يوم القيامة، أحاسنكم أخلاقًا، وإن أبغضكم إلي وأبعدكم مني يوم القيامة، والثرثارون، والمتشدقون، والمتفيهقون‏\"‏‏.‏‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏ وقد سبق شرحه في باب حسن الخلق‏.‏"},{"id":"riyad:1060","bookId":"riyad","type":"hadith","num":1060,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عائشة رضي الله عنها عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يقولن أحدكم خبثت نفسي، ولكن ليقل‏:‏ لقست نفسي‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ قال العلماء معنى خبثت أي غثيت وهو معنى لقست ولكن كره لفظ الخبث"},{"id":"riyad:1061","bookId":"riyad","type":"hadith","num":1061,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تسموا العنب الكَرْم، فإن الكَرْم المسلم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وهذا لفظ مسلم‏)‏‏)‏‏.‏ وفي رواية‏:‏ ‏\"‏فإنما الكرم قلب المؤمن‏\"‏ وفي رواية للبخاري ومسلم‏:‏ ‏\"‏يقولون الكرم، إنما الكرم قلب المؤمن‏\"‏‏.‏"},{"id":"riyad:1062","bookId":"riyad","type":"hadith","num":1062,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن وائل بن حجر رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تقولوا‏:‏ الكَرْم، ولكن قولوا‏:‏ العنب، والحَبَْلة‏\"‏ رواه مسلم الحبلة بفتح الحاء والباء ويقال أيضا بإسكان الباء"},{"id":"riyad:1063","bookId":"riyad","type":"hadith","num":1063,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تباشر المرأة المرأة، فتصفها لزوجها كأنه ينظر إليها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1064","bookId":"riyad","type":"hadith","num":1064,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يقولن أحدكم‏:‏ اللهم اغفر لي إن شئت‏:‏ اللهم ارحمني إن شئت، ليعزم المسألة، فإنه لا مكره له‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وفي رواية لمسلم‏:‏ ‏\"‏ولكن ليعزم، وليعظم الرغبة، فإن الله تعالى، لا يتعاظمه شيء أعطاه‏\"‏‏)‏‏)‏‏.‏"},{"id":"riyad:1065","bookId":"riyad","type":"hadith","num":1065,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا دعا أحدكم، فليعزم المسألة، ولا يقولن‏:‏ اللهم إن شئت، فأعطني، فإنه لا مستكره له‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1066","bookId":"riyad","type":"hadith","num":1066,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن حذيفة بن اليمان رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تقولوا‏:‏ ما شاء الله وشاء فلان، ولكن قولوا‏:‏ ما شاء الله، ثم شاء فلان‏\"‏‏.‏ رواه أبو داود بإسناد صحيح"},{"id":"riyad:1067","bookId":"riyad","type":"hadith","num":1067,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أبي برزة رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يكره النوم قبل العشاء والحديث بعدها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1068","bookId":"riyad","type":"hadith","num":1068,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم صلى العشاء في آخر حياته، فلما سلم، قال‏:‏ ‏","matn":"\"‏أرأيتكم ليلتكم هذه‏؟‏ فإن على رأس مائة سنة لا يبقي ممن هو على ظهر الأرض اليوم أحد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1069","bookId":"riyad","type":"hadith","num":1069,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه أنهم انتظروا النبي صلى الله عليه وسلم ، فجاءهم قريبًا من شطر الليل فصلى بهم، يعني العشاء، قال‏:‏ ثم خطبنا فقال‏:‏ ‏","matn":"\"‏ألا إن الناس قد صلوا‏.‏ ثم رقدوا، وإنكم لن تزالوا في صلاة ما انتظرتم الصلاة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1070","bookId":"riyad","type":"hadith","num":1070,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا دعا الرجل امرأته إلى فراشه فأبت، فبات غضبان عليها، لعنتها الملائكة حتى تصبح‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏ وفي رواية‏:‏ حتى‏:‏ ‏ ‏ترجع‏‏‏.‏"},{"id":"riyad:1071","bookId":"riyad","type":"hadith","num":1071,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يحل للمرأة أن تصوم وزوجها شاهد إلا بإذنه، ولا تأذن في بيته إلا بإذنه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1072","bookId":"riyad","type":"hadith","num":1072,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أما يخشى أحدكم إذا رفع رأسه قبل الإمام أن يجعل الله رأسه رأس حمار‏!‏ أو يجعل الله صورته صورة حمار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1073","bookId":"riyad","type":"hadith","num":1073,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم‏:‏ نهى عن الخصر في الصلاة‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1074","bookId":"riyad","type":"hadith","num":1074,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عائشة رَضِيَ اللهُ عنها، قالت: سَمِعْتُ رسولَ الله - صلى الله عليه وسلم - يقولُ","matn":"\"لا صَلاَةَ بِحَضْرَةِ طَعَامٍ، وَلاَ وَهُوَ يُدَافِعُهُ الأَخْبَثَانِ\". ((رواه مسلم‏)) ‏"},{"id":"riyad:1075","bookId":"riyad","type":"hadith","num":1075,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أنس بن مالك قَالَ : قَالَ رسولُ اللهِ : « مَا بَالُ أقْوامٍ يَرْفَعُونَ أبْصَارَهُمْ إِلَى السَّمَاءِ في صَلاَتِهِمْ » ! فَاشْتَدَّ قَولُهُ في ذَلِكَ حَتَّى قَالَ : « لَيَنْتَهُنَّ عَنْ ذَلِكَ ، أَوْ لَتُخطفَنَّ أَبْصَارُهُمْ » ! . رواه البخاري"},{"id":"riyad:1076","bookId":"riyad","type":"hadith","num":1076,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عائشة رضي الله عنها قالت‏:‏ سألت رسول الله صلى الله عليه وسلم عن الالتفات في الصلاة فقال‏:‏ ‏","matn":"\"‏هو اختلاس يختلسه الشيطان من صلاة العبد‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1077","bookId":"riyad","type":"hadith","num":1077,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إياك والالتفات في الصلاة، فإن الالتفات في الصلاة هلكة، فإن كان لابد، ففي التطوع لا في الفريضة‏\"‏‏.‏‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1078","bookId":"riyad","type":"hadith","num":1078,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي مرثد كناز بن الحصين رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لا تصلوا إلى القبور، ولا تجلسوا عليها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1079","bookId":"riyad","type":"hadith","num":1079,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي الجهيم عبد الله بن الحارث بن الصمة الأنصاري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لو يعلم المار بين المصلي ماذا عليه لكان أن يقف أربعين خيرًا له من أن يمر بين يديه‏\"‏ ‏(‏‏(‏قال الراوي‏:‏ لا أدري قال أربعين يومًا، أو أربعين شهرًا، أو أربعين سنة‏)‏‏)‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1080","bookId":"riyad","type":"hadith","num":1080,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أقيمت الصلاة، فلا صلاة إلا المكتوبة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1081","bookId":"riyad","type":"hadith","num":1081,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا تخصوا ليلة الجمعة بقيام من بين الليالي، ولا تخصوا يوم الجمعة بصيام من بين الأيام إلا أن يكون في صوم يصومه أحدكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1082","bookId":"riyad","type":"hadith","num":1082,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لا يصومن أحدكم يوم الجمعة إلا يومًا قبله أو بعده‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1083","bookId":"riyad","type":"hadith","num":1083,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن محمد بن عباد قال‏:‏ سألت جابرًا رضي الله عنه‏:‏ أنهى النبي صلى الله عليه وسلم عن صوم يوم الجمعة‏؟‏ قال‏:‏ نعم ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1084","bookId":"riyad","type":"hadith","num":1084,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أم المؤمنين جويرة بنت الحارس رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها يوم الجمعة وهي صائمة، فقال‏:‏ ‏","matn":"\"‏ أصمت أمس‏؟‏‏\"‏ قالت‏:‏ لا، قال‏:‏ ‏\"‏ تريدين أن تصومي غدا ‏\"‏ قالت‏:‏ لا، قال ‏:‏ ‏\"‏فأفطري‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:1085","bookId":"riyad","type":"hadith","num":1085,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أبي هريرة وعائشة رضي الله عنهما أن النبي صلى الله عليه وسلم نهى عن الوصال‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1086","bookId":"riyad","type":"hadith","num":1086,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ نهى رسول الله صلى الله عليه وسلم عن الوصال‏.‏ قالوا ‏:‏إنك تواصل‏؟‏ قال‏:‏ ‏","matn":"\"‏إني لست مثلكم، إني أُطعم وأُسقى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ، وهذا لفظ البخاري‏.‏"},{"id":"riyad:1087","bookId":"riyad","type":"hadith","num":1087,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ لأن يجلس أحدكم على جمرة، فتحرق ثيابه، فتخلص على جلده خير له من أن يجلس على قبر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:1088","bookId":"riyad","type":"hadith","num":1088,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن جابر رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:1089","bookId":"riyad","type":"hadith","num":1089,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن جرير بن عبد الله رضي الله عنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏أيما عبد أبق، فقد برئت منه الذمة ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:1090","bookId":"riyad","type":"hadith","num":1090,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعنه عن النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا أبق العبد، لم تقبل له صلاة ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ ‏.‏ وفي رواية‏:‏ ‏\"‏فقد كفر ‏\"‏ ‏.‏"},{"id":"riyad:1091","bookId":"riyad","type":"hadith","num":1091,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عائشة رضي الله عنها، أن قريشًا أهمهم شأن المرأة المخزومية التي سرقت فقالوا‏:‏ من يكلم فيها رسول الله صلى الله عليه وسلم ‏؟‏ فقالوا‏:‏ ومن يجترئ عليه إلا أسامة بن زيد، حب رسول الله صلى الله عليه وسلم ‏:‏، فكلمه أسامة فقال صلى الله عليه وسلم ‏:‏“أتشفع في حد من حدود الله تعالى‏؟‏ “ثم قام فاختطب، ثم قال‏:‏ “إنما أهلك الذين قبلكم أنهم كانوا إذا سرق فيهم الشريف تركوه، وإذا سرق فيهم الضعيف، أقاموا عليه الحد، وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية فتلون وجه رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ فقال‏:‏ ‏\"‏أتشفع في حد من حدود الله‏؟‏‏\"‏ قال أسامة‏:‏ استغفر لي يا رسول الله قال‏:‏ ثم أمر بتلك المرأة فقطعت يدها‏.‏"},{"id":"riyad:1092","bookId":"riyad","type":"hadith","num":1092,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “اتقوا اللاعنين” قالوا‏:‏ وما اللاعنان‏؟‏ قال‏:‏ ‏","matn":"\"‏الذي يتخلى في طريق الناس أو في ظلهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1093","bookId":"riyad","type":"hadith","num":1093,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن جابر رضي الله عنه ‏:‏ أن رسول الله صلى الله عليه وسلم نهى أن يبال في الماء الراكد‏.‏‏ رواه مسلم‏"},{"id":"riyad:1094","bookId":"riyad","type":"hadith","num":1094,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن النعمان بن بشير رضي الله عنهما أن أبًا له أتي به رسول الله صلى الله عليه وسلم فقال‏:‏ إني نحلت ابني هذا غلامًا كان لي، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أكل ولدك نحلته مثل هذا‏؟‏‏\"‏ فقال‏:‏ لا، فقال رسول الله صلى الله عليه وسلم فأرجعه‏\"‏‏.‏ وفي رواية‏:‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏أفعلت هذا بولدك كلهم‏؟‏‏\"‏ قال‏:‏ لا، قال‏:‏ ‏\"‏اتقوا الله واعدلوا بين أولادكم‏\"‏ فرجع أبي، فرد تلك الصدقة‏.‏ وفي رواية‏:‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ “يا بشير ألك ولد سوى هذا‏؟‏” قال‏:‏ نعم، قال‏:‏ “أكلهم وهبت له مثل هذا‏؟‏‏\"‏ قال‏:‏ لا، قال‏:‏ ‏\"‏فلا تشهدني إذًا فإني لا أشهد على جور‏\"‏ وفي رواية ‏\"‏لا تشهدني على جور‏\"‏ وفي رواية‏:‏ ‏\"‏أشهد على هذا غيري‏\"‏ ثم قال‏:‏ ‏\"‏أيسرك أن يكونوا إليك في البر سواء‏؟‏‏\"‏ قال‏\"‏ بلى، قال‏:‏ ‏\"‏فلا إذًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1095","bookId":"riyad","type":"hadith","num":1095,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن زينب بنت أبي سلمة رضي الله عنهما قالت‏:‏ دخلت على أم حبيبة رضي الله عنه زوج النبي صلى الله عليه وسلم حين توفي أبوها أبو سفيان بن حرب رضي الله عنه، فدعت بطيب فيه صفرة خلوق أو غيره، فدهنت منه جارية، ثم مست بعارضيها‏.‏ ثم قالت‏:‏ والله مالي بالطيب من حاجة، غير أني سمعت رسول الله صلى الله عليه وسلم يقول على المنبر‏:‏ ‏","matn":"\"‏لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث ليال، إلا على زوج أربعة أشهر وعشرا‏\"‏ قالت زينب‏:‏ ثم دخلت على زينب بنت جحش رضي الله عنها حين توفي أخوها، فدعت بطيب، فمست منه، ثم قالت‏:‏ أما والله مالي بالطيب من حاجة، غير أني سمعت رسول الله صلى الله عليه وسلم يقول على المنبر‏:‏ “لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث إلا على زوج أربعة أشهر وعشرًا” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1096","bookId":"riyad","type":"hadith","num":1096,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أنس رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن يبيع حاضر لباد وإن كان أخاه لأبيه وأمه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1097","bookId":"riyad","type":"hadith","num":1097,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏”لا تتلقوا السلع حتى يهبط بها إلى الأسواق‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1098","bookId":"riyad","type":"hadith","num":1098,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “لا تتلقوا الركبان، ولا يبع حاضر لباد‏","matn":"\"‏ فقال له طاوس‏:‏ ما قوله‏:‏ لا بيع حاضر لباد‏؟‏ قال‏:‏ لا يكون له سمسارًا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1099","bookId":"riyad","type":"hadith","num":1099,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن يبيع حاضر لباد، ولا تناجشوا ولا يبيع الرجل على بيع أخيه، ولا يخطب على خطبة أخيه، ولا تسأل المرأة طلاق أختها لتكفأ ما في إنائها‏.‏ وفي رواية قال‏:‏ نهى رسول الله صلى الله عليه وسلم عن التلقي وأن يبتاع المهاجر للأعرابي، وأن تشترط المرأة طلاق أختها، وأن يستام الرجل على سوم أخيه، ونهى عن النجش والتصرية‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1100","bookId":"riyad","type":"hadith","num":1100,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يبع بعضكم على بيع بعض، ولا يخطب على خطبة أخيه إلا أن يأذن له‏\"‏ ‏(‏‏(‏متفق عليه، وهذا لفظ مسلم‏)‏‏)‏"},{"id":"riyad:1101","bookId":"riyad","type":"hadith","num":1101,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عقبة بن عامر أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏المؤمن أخو المؤمن، فلا يحل لمؤمن أن يبتاع على بيع أخيه ولا يخطب على خطبة أخيه حتى يذر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1102","bookId":"riyad","type":"hadith","num":1102,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن الله تعالى يرضى لكم ثلاثا، ويكره لكم ثلاثًا‏:‏ فيرضى لكم أن تعبدوه، ولا تشركوا به شيئًا، وأن تعتصموا بحبل الله جميعًا ولا تفرقوا، ويكره لكم‏:‏ قيل وقال، وكثرة السؤال، وإضاعة المال‏\"‏ ‏(‏‏(‏رواه مسلم، وتقدم شرحه‏)‏‏)‏‏.‏"},{"id":"riyad:1103","bookId":"riyad","type":"hadith","num":1103,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن وراد كاتب المغيرة شعبة قال‏:‏ أملى على المغيرة بن شعبة في كتاب إلى معاوية رضي الله عنه ، أن النبي صلى الله عليه وسلم أن يقول في دبر كل صلاة مكتوبة‏:‏ ‏","matn":"\"‏لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد‏\"‏ وكتب إليه أنه ‏\"‏كان ينهى عن قيل وقال، وإضاعة المال، وكثرة السؤال، وكان ينهى عن عقوق الأمهات، ووأد البنات، ومنع وهات” ‏(‏‏(‏متفق عليه وسبق شرحه‏)‏‏)‏‏.‏"},{"id":"riyad:1104","bookId":"riyad","type":"hadith","num":1104,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ “لا يُشر أحدكم إلى أخيه بالسلاح، فإنه لا يدري لعل الشيطان ينزع في يده، فيقع في حفرة من النار‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم قال‏:‏ قال أبو القاسم صلى الله عليه وسلم ‏:‏ “من أشار إلى أخيه بحديدة، فإن الملائكة تلعنه، حتى ينزع وإن كان أخاه لأبيه وأمه‏\"‏‏.‏ قوله صلى الله عليه وسلم ‏:‏ ‏\"‏ينزِع‏\"‏ ضبط بالعين المهملة مع كسر الزاي، وبالغين المعجمة مع فتحها، ومعناهما متقارب، ومعناه بالمهملة يرمي، وبالمعجمة أيضًا يرمي ويفسد، وأصل النزع الطعن والفساد‏.‏"},{"id":"riyad:1105","bookId":"riyad","type":"hadith","num":1105,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن جابر رضي الله عنه قال‏:‏ ‏","matn":"\"‏نهى رسول الله صلى الله عليه وسلم أن يتعاطى السيف مسلولا‏\"‏‏.‏‏(‏‏(‏رواه أبو داود والترمذي وقال حديث حسن‏)‏‏)‏"},{"id":"riyad:1106","bookId":"riyad","type":"hadith","num":1106,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي الشعثاء قال‏:‏ كنا قعودًا مع أبي هريرة رضي الله عنه في المسجد فأذن المؤذن، فقام رجل من المسجد يمشي، فأتبعه أبو هريرة بصره حتى خرج من المسجد فقال أبو هريرة‏:‏ أما هذا فقد عصى أبا القاسم صلى الله عليه وسلم ‏","matn":"\"‏ ‏(‏‏(‏‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1107","bookId":"riyad","type":"hadith","num":1107,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “من عرض عليه ريحان، فلا يرده، فإنه خفيف المحمل طيب الريح‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1108","bookId":"riyad","type":"hadith","num":1108,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أنس بن مالك رضي الله عنه أن النبي صلى الله عليه وسلم كان لا يرد الطيب” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1109","bookId":"riyad","type":"hadith","num":1109,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي موسى الأشعري رضي الله عنه قال‏:‏ سمع رسول الله صلى الله عليه وسلم رجلا يُثني على رجل ويُطريه في المدحة، فقال‏:‏ ‏","matn":"\"‏أهلكتم، أو قطعتم ظهر الرجل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (23).‏"},{"id":"riyad:1110","bookId":"riyad","type":"hadith","num":1110,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي بكر رضي الله عنه أن رجلا ذُكر عند النبي صلى الله عليه وسلم ، فأثنى عليه رجل خيرًا، فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ويحك‏!‏ قطعت عنق صاحبك‏\"‏ يقوله مرارًا ‏\"‏وإن كان أحدكم مادحًا لا محالة، فليقل‏:‏ أحسب كذا وكذا إن كان يرى أنه كذلك وحسيبه الله، ولا يزكي على الله أحدًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1111","bookId":"riyad","type":"hadith","num":1111,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن همام بن الحارث، عن المقداد، رضي الله عنه أم رجلا جعل يمدح عثمان رضي الله عنه ، فعمد المقداد، فجثا على ركبتيه، فجعل يحثو في وجهه الحصباء، فقال له عثمان‏:‏ ما شأنك‏؟‏ فقال‏:‏ إن رسول الله صلى الله عليه وسلم قال‏:‏ “إذا رأيتم المادحين، فاحثوا في وجوههم التراب‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ فهذه الأحاديث في النهي، وجاء في الإباحة أحاديث كثيرة صحيحة‏.‏ قال العلماء‏:‏ وطريق الجمع بين الأحاديث أن يقال‏:‏ إن كان الممدوح عنده كمال إيمان ويقين، ورياضة نفس، ومعرفة تامة بحيث لا يفتن، ولا يغتر بذلك، ولا تلعب به نفسه، فليس بحرام ولا مكروه، وإن خيف عليه شيء من هذه الأمور، كره مدحه في وجهه كراهة شديدة، وعلى هذا التفصيل تنزل الأحاديث المختلفة في ذلك‏.‏ ومما جاء في الإباحة قوله صلى الله عليه وسلم لأبي بكر رضي الله عنه‏:‏ “أرجو أن تكون منهم‏\"‏ أي من الذين يُدعون من جميع أبواب الجنة لدخولها، وفي الحديث الآخر‏:‏ ‏\"‏لست منهم‏\"‏ أي‏:‏ لست من الذين يُسبلون أُزرهم خيلاء‏.‏ وقال صلى الله عليه وسلم لعمر رضي الله عنه‏:‏ “ما رآك الشيطان سالكًا فجًا إلا سلك فجًا غير فجك” والأحاديث في الإباحة كثيرة، وقد ذكرت جملة من أطرافها في كتاب‏:‏ ‏\"‏الأذكار‏\"‏‏.‏"},{"id":"riyad:1112","bookId":"riyad","type":"hadith","num":1112,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن ابن عباس رضي الله عنه أن عمر بن الخطاب رضي الله عنه خرج إلى الشام حتى إذا كان بسرغ لقيه أمراء الأجناد -أبو عبيدة بن الجراح وأصحابه- فأخبروه أن الوباء قد وقع بالشام، قال بن عباس‏:‏ فقال عمر‏:‏ ادع لي المهاجرين الأولين، فدعوتهم، فاستشارهم، وأخبرهم أن الوباء قد وقع بالشام، فاختلفوا، فقال بعضهم‏:‏ خرجت لأمر، ولا نرى أن ترجع عنه‏.‏ وقال بعضهم‏:‏ معك بقية الناس وأصحاب رسول الله صلى الله عليه وسلم ، ولا نرى أن تقدمهم على هذا الوباء‏.‏ فقال‏:‏ ارتفعوا عني، ثم قال‏:‏ ادع لي الأنصار، فدعوتهم، فاستشارهم، فسلكوا سبيل المهاجرين، واختلفوا كاختلافهم، فقال‏:‏ ارتفعوا عني، ثم قال‏:‏ ادع لي من كان ها هنا من مشيخة قريش من مهاجرة الفتح، فدعوتهم، فلم يختلف عليه منهم رجلان، فقالوا‏:‏ نرى أن ترجع بالناس، ولا تقدمهم على هذا الوباء، فنادى عمر رضي الله عنه في الناس‏:‏ إني مصبح على ظهر، فأصبحوا عليه فقال أبو عبيدة بن الجراح رضي الله عنه ‏:‏ أفرار من قدر الله‏؟‏ فقال عمر رضي الله عنه ‏:‏ لو غيرك قالها يا أبا عبيدة‏!‏ -وكان عمر يكره خلافه- نعم نفر من قدر الله إلى قدر الله، أرأيت لو كان لك إبل، فهبطت وادياً له عدوتان، إحداهما خصبة، والأخرى جدبة، أليس إن رعيت الخصبة رعيتها بقدر الله، وإن رعيت الجدبة رعيتها بقدر الله‏؟‏ قال‏:‏ فجاء عبد الرحمن بن عوف رضي الله عنه ، وكان متغيباً في بعض حاجته، فقال‏:‏ إن عندي من هذا علما، سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “إذا سمعتم به بأرض، فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها، فلا تخرجوا فرارا منه‏","matn":"\"‏ فحمد الله تعالى عمر رضي الله عنه وانصرف‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ والعدوة‏:‏ جانب الوادي‏‏‏.‏"},{"id":"riyad:1113","bookId":"riyad","type":"hadith","num":1113,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أسامة بن زيد رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا سمعتم الطاعون بأرض، فلا تدخلوها، وإذا وقع بأرض، وأنتم فيها، فلا تخرجوا منها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1114","bookId":"riyad","type":"hadith","num":1114,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “أجتنبوا السبع الموبقات” قالوا‏:‏ يا رسول الله وما هن‏؟‏ قال‏:‏ ‏","matn":"\"‏الشرك بالله، والسحر، وقتل النفس التى حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1115","bookId":"riyad","type":"hadith","num":1115,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن ابن عمر رضي الله عنهما قال‏:‏ ‏","matn":"\"‏نهى رسول الله صلى الله عليه وسلم أن يسافر بالقرآن إلى أرض العدو‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1116","bookId":"riyad","type":"hadith","num":1116,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن أم سلمة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الذي يشرب في آنية الفضة إنما يجرجر في بطنه نار جهنم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏أن الذي يأكل أو يشرب في آنية الفضة والذهب‏\"‏"},{"id":"riyad:1117","bookId":"riyad","type":"hadith","num":1117,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن حذيفة رضي الله عنه، قال‏:‏ إن النبي صلى الله عليه وسلم نهانا عن الحرير، والديباج والشرب في آنية الذهب والفضة، وقال‏:‏ ‏","matn":"\"‏هن لهم في الدنيا وهم لكم في الاخرة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية في الصحيحين عن حذيفة رضي الله عنه، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏لا تلبسوا الحرير ولا الديباج، ولا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها‏\"‏‏.‏"},{"id":"riyad:1118","bookId":"riyad","type":"hadith","num":1118,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أنس بن سيرين قال‏:‏ كنت مع أنس بن مالك رضي الله عنه عند نفر من المجوس، فجيء بفالوذج على إناء من فضة، فلم يأكله، فقيل له‏:‏ حوله، فحوله على إناء من خلنج، وجيء به فأكله‏.‏ ‏(‏‏(‏رواه البيهقي بإسناد حسن‏)‏‏)‏‏.الخلنج الجفنة ‏"},{"id":"riyad:1119","bookId":"riyad","type":"hadith","num":1119,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"عن أنس رضي الله عنه قال‏:‏ نهى النبي صلى الله عليه وسلم أن يتزعفر الرجل‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1120","bookId":"riyad","type":"hadith","num":1120,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنه قال‏:‏ رأى النبي صلى الله عليه وسلم علي ثوبين معصفرين فقال‏:‏ ‏","matn":"\"‏أمك أمرتك بهذا‏؟‏‏\"‏ قلت‏:‏ أغسلهما‏؟‏ قال‏:‏ ‏\"‏بل احرقهما‏\"‏‏.‏ وفي رواية فقال‏:‏ ‏\"‏إن هذا من ثياب الكفار فلا تلبسها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1121","bookId":"riyad","type":"hadith","num":1121,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن عليّ رضي الله عنه قال‏:‏ حفظت عن رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يتم بعد احتلام، ولا صمات يوم إلى الليل‏\"‏‏.‏ قال الخطابي في تفسير هذا الحديث‏:‏ كان من نسك الجاهلية الصمات، فنهوا في الإسلام عن ذلك، وأمروا بالذكر والحديث بالخير‏.‏"},{"id":"riyad:1122","bookId":"riyad","type":"hadith","num":1122,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن قيس بن أبي حازم قال‏:‏ دخل أبو بكر الصديق رضي الله عنه على امرأة من أحمس يقال لها‏:‏ زينب، فرأها لا تتكلم‏.‏ فقال‏:‏ ما لها لا تتكلم‏؟‏ فقالوا‏:‏ حجت مصمته، فقال لها‏:‏ تكلمي فإن هذا لا يحل، هذا من عمل الجاهلية‏!‏ فتكلمت‏.‏ رواه البخاري"},{"id":"riyad:1123","bookId":"riyad","type":"hadith","num":1123,"kitab":"كتاب الأمور المنهي عنها","isnad":"عن سعد بن أبي وقاص رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من ادعى إلى غير أبيه وهو يعلم أنه غير أبيه، فالجنة عليه حرام‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1124","bookId":"riyad","type":"hadith","num":1124,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا ترغبوا عن آبائكم، فمن رغب عن أبيه، فهو كافر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1125","bookId":"riyad","type":"hadith","num":1125,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن يزيد بن شريك بن طارق قال‏:‏ رأيت عليا رضي الله عنه على المنبر يخطب، فسمعته يقول‏:‏ لا والله ما عندنا من كتاب نقرؤه إلا كتاب الله، وما في هذه الصحيفة، فنشرها فإذا فيها أسنان الإبل، وأشياء من الجراحات، وفيها‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏المدينة حرم ما بين عير إلى ثور، فمن أحدث فيها حدثاً، أو آوى محدثاً، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً، ذمة المسلمين واحدة، يسعى بها أدناهم، فمن أخفر مسلماً، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً، ومن ادعى إلى غير أبيه، أو انتمى إلى غير مواليه، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ \"ذِمَّةُ المُسْلِمِينَ\"أيْ: عَهْدُهُمْ وأمانتُهُم.\"وَأخْفَرَهُ\": نَقَضَ عَهْدَهُ.\"والصَّرفُ\": التَّوْبَةُ، وَقِيلَ: الحِيلَةُ.\"وَالْعَدْلُ\": الفِدَاءُ."},{"id":"riyad:1126","bookId":"riyad","type":"hadith","num":1126,"kitab":"كتاب الأمور المنهي عنها","isnad":"","matn":"وعن أبي ذر رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ “ليس من رجل ادعى لغير أبيه وهو يعلمه إلا كفر، ومن ادعى ما ليس له، فليس منا، وليتبوأ مقعده من النار، ومن دعا رجلاً بالكفر، أو قال‏:‏ عدو الله، وليس كذلك إلا حار عليه” ‏(‏‏(‏متفق عليه وهذا لفظ رواية مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1127","bookId":"riyad","type":"hadith","num":1127,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله تعالى يغار، وغيرة الله أن يأتي المرء ما حرم الله عليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1128","bookId":"riyad","type":"hadith","num":1128,"kitab":"كتاب الأمور المنهي عنها","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “من حلف فقال في حلفه‏:‏ باللات والعزى، فليقل‏:‏ لا إله إلا الله، ومن قال لصاحبه‏:‏ تعالى أقامرك فليتصدق‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1129","bookId":"riyad","type":"hadith","num":1129,"kitab":"كتاب المنثورات والملح","isnad":"عن النواس بن سمعان رضي الله عنه قال‏:‏ ذكر رسول الله صلى الله عليه وسلم الدجال ذات غداة، فخفض فيه، ورفع حتى ظنناه في طائفة النخل‏.‏ فلما رحنا إليه، عرف ذلك فينا، فقال‏:‏ ‏","matn":"\"‏ما شأنكم‏؟‏” قلنا‏:‏ يا رسول الله ذكرت الدجال الغداة، فخفضت فيه حتى ظنناه في طائفة النخل فقال‏:‏ ‏\"‏غير الدجال أخوفنى عليكم؛ إن يخرج وأنا فيكم، فأنا حجيجه دونكم؛ وإن يخرج ولست فيكم، فامرؤ حجيج نفسه، والله خليفتي على كل مسلم، إنه شاب قطط، عينه طافية، كأني أشبهه بعبد العزى بن قطن، فمن أدركه منكم فليقرأ عليه فواتح سورة الكهف، إنه خارج خلة بين الشام والعراق، فعاث يمينا وعاث شمالاً، يا عباد الله فاثبتوا” قلنا‏:‏ يا رسول الله وما لبثه في الأرض‏؟‏ قال‏:‏ ‏\"‏أربعون يوماً‏:‏ يوم كسنة، ويوم كشهر، ويوم كجمعة، وسائر أيامه كأيامكم‏\"‏ قلنا ‏:‏ يا رسول الله ، فذلك اليوم الذي كسنة أتكفينا فيه صلاة يوم‏؟‏ قال‏:‏ لا، اقدروا له قدره” فقلنا‏:‏ يا رسول الله وما إسراعه في الأرض‏؟‏ قال‏:‏ ‏\"‏كالغيث استدبرته الريح، فيأتي على القوم، فيدعوهم، فيؤمنون به، ويستجيبون له فيأمر السماء فتمطر، والأرض فتنبت، فتروح عليهم سارحتهم، أطول ما كانت ذرى، وأسبغه ضروعاً، وأمده خواصر، ثم يأتي القوم فيدعوهم، فيردون عليه قوله، فيصرف عنهم، فيصبحون ممحلين ليس بأيديهم شيء من أموالهم، ويمر بالخربة فيقول لها‏:‏ أخرجي كنوزك، فتتبعه كنوزها كيعاسيب النحل، ثم يدعو رجلاً ممتلئاً شبابا فيضربه بالسيف، فيقطعه جزلتين رمية الغرض، ثم يدعوه، فيقبل، ويتهلل وجهه يضحك، فبينما هو كذلك إذ بعث الله تعالى المسيح ابن مريم،صلى الله عليه وسلم ، فينزل عند المنارة البيضاء شرقي دمشق بين مهرودتين، واضعاً كفيه على أجنحة ملكين، إذا طأطأ رأسه، قطر، وإذا رفعه تحدر منه جمان كاللؤلؤ، فلا يحل لكافر يجد نفسه إلا مات، ونفسه ينتهي إلى حيث ينتهي طرفه، فيطلبه حتى يدركه بباب لد فيقتله، ثم يأتي عيسى ، صلى الله عليه وسلم ، قوم قد عصمهم الله منه، فيمسح عن وجوههم، ويحدثهم بدرجاتهم في الجنة، فبينما هو كذلك إذ أوحى الله تعالى إلى عيسى صلى الله عليه وسلم إني قد أخرجت عباداً لي لا يدان لأحد بقتالهم، فحرز عبادي إلى الطور، ويبعث الله يأجوج ومأجوج وهم من كل حدب ينسلون، فيمر أوائلهم على بحيرة طبرية فيشربون ما فيها، ويمر آخرهم فيقول‏:‏ لقد كان بهذه مرة ماء، ويحصر نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه حتى يكون رأس الثور لأحدهم خيراً من مائة دينار لأحدكم اليوم، فيرغب نبي الله عيسى، صلى الله عليه وسلم وأصحابه، رضي الله عنهم، إلى الله تعالى، فيرسل الله تعالى عليهم النغف في رقابهم، فيصبحون فرسى كموت نفس واحدة ثم يهبط نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه رضي الله عنهم، إلى الله تعالى، فيرسل الله تعالى عليهم النغف في رقابهم فيصبحون فرسى كموت نفس واحدة ثم يهبط نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه رضي الله عنهم، إلى الأرض، فلا يجدون في الأرض موضع شبر إلا ملأه زهمهم ونتنهم، فيرغب، نبي الله عيسىصلى الله عليه وسلم ، وأصحابه رضي الله عنهم إلى الله تعالى، فيرسل الله تعالى طيراً كأعناق البخت، فتحملهم، فتطرحهم حيث شاء الله، ثم يرسل الله عز وجل مطراً لا يكن منه بيت مدر ولا وبر، فيغسل الأرض حتى يتركها كالزلقة، ثم يقال للأرض‏:‏ أنبتي ثمرتك، وردي بركتك، فيومئذ تأكل العصابة من الرمانة، ويستظلون بقحفها، ويبارك في الرسل حتى إن اللقحة من الإبل لتكفي الفئام من الناس، واللقحة من البقر لتكفي القبيلة من الناس، واللقحة من الغنم لتكفي الفخذ من الناس، فبينما هم كذلك إذ بعث الله تعالى ريحاً طيبة، فتأخذهم تحت آباطهم، فتقبض روح كل مؤمن وكل مسلم؛ ويبقى شرار الناس يتهارجون فيها تهارج الحمر فعليهم تقوم الساعة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ قوله: «خلة بين الشام والعراق» : أي طريقا بينهما. وقوله: «عاث» بالعين المهملة والثاء المثلثة، والعيث: أشد الفساد. «والذرى» : بضم الذال المعجمة وهو أعالي الأسنمة وهو جمع ذروة بضم الذال وكسرها « واليعاسيب» : ذكور النحل. «وجزلتين» : أي قطعتين، «والغرض» : الهدف الذي يرمى إليه بالنشاب، أي: يرميه رمية كرمية النشاب إلى الهدف. «والمهرودة» بالدال المهملة والمعجمة، وهي: الثوب المصبوغ. قوله: «لا يدان» : أي لا طاقة. «والنغف» : دود. «وفرسى» : جمع فريس، وهو القتيل. و «الزلقة» : بفتح الزاي واللام وبالقاف، ... وروي: الزلفة بضم الزاي وإسكان اللام وبالفاء وهي المرآة. ... «والعصابة» : الجماعة. «والرسل» بكسر الراء: اللبن. «واللقحة» : اللبون. «والفئام» بكسر الفاء وبعدها همزة ممدودة: الجماعة. ... «والفخذ» من الناس: دون القبيلة."},{"id":"riyad:1130","bookId":"riyad","type":"hadith","num":1130,"kitab":"كتاب المنثورات والملح","isnad":"وعن ربعي بن حراش قال‏:‏ انطلقت مع أبي مسعود الأنصاري إلى حذيفة بن اليمان رضي الله عنهم فقال له أبو مسعود، حدثني ما سمعت من رسول الله صلى الله عليه وسلم ، في الدجال قال‏:‏ ‏","matn":"\"‏إن الدجال يخرج ، وإن معه ماء وناراً ، فأما الذي يراه الناس ماء فنار تحرق، وأما الذي يراه الناس نارأً، فماء بارد عذب، فمن أدركه منكم، فليقع في الذي يراه ناراً، فإنه ماء عذب طيب‏\"‏ فقال أبو مسعود‏:‏ وأنا قد سمعته‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1131","bookId":"riyad","type":"hadith","num":1131,"kitab":"كتاب المنثورات والملح","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يخرج الدجال في أمتى فيمكث أربعين لا أدري يوماً أو أربعين شهراً، أو أربعين عاماً، فيبعث الله تعالى عيسى بن مريم‏.‏ صلى الله عليه وسلم ، فيطلبه فيهلكه، ثم يمكث الناس سبع سنين ليس بين اثنين عداوة، ثم يرسل الله عز وجل،ريحاً باردة من قبل الشام، فلا يبقى على وجه الأرض أحد في قلبه مثقال ذرة من خير أو إيمان إلا قبضته، حتى لو أن أحدكم دخل في كبد جبل، لدخلته عليه حتى تقبضه، فيبقى شرار الناس في خفة الطير، وأحلام السباع لا يعرفون معروفاً ، ولا ينكرون منكراً، فيتمثل لهم الشيطان، فيقول‏:‏ ألا تستجيبون‏؟‏ فيقولون ‏:‏ فما تأمرنا‏؟‏ فيأمرهم بعبادة الأوثان، وهم في ذلك دار رزقهم، حسن عيشهم ، ثم ينفخ في الصور، فلا يسمعه أحد إلا أصغى ليتا ورفع ليتا، وأول من يسمعه رجل يلوط حوض إبله فيصعق ويصعق الناس، ثم يرسل الله -أو قال‏:‏ ينزل الله - مطرا كأنه الطل أو الظل، فتنبت منه أجساد الناس، ثم ينفخ فيه أخرى فإذا هم قيام ينظرون ، ثم يقال‏:‏ يا أيها الناس هلم إلى ربكم ، وقفوهم إنهم مسؤولون ‎، ثم يقال‏:‏ أخرجوا بعث النار فيقال‏:‏ من كم‏؟‏ فيقال‏:‏ من كل ألف تسعمائة وتسعة وتسعين، فذلك يوم يجعل الولدان شيباً، وذلك يوم يكشف عن ساق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ «الليت» : صفحة العنق. ومعناه يضع صفحة عنقه ويرفع صفحته الأخرى."},{"id":"riyad:1132","bookId":"riyad","type":"hadith","num":1132,"kitab":"كتاب المنثورات والملح","isnad":"-وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ليس من بلد إلى سيطؤه الدجال، إلا مكة والمدينة، وليس نقب من أنقابها إلا عليه الملائكة صافين تحرسهما، فينزل بالسبخة، فترجف المدينة ثلاث رجفات، يخرج الله منها كل كافر ومنافق‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1133","bookId":"riyad","type":"hadith","num":1133,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يتبع الدجال من يهود أصبهان سبعون ألفا عليهم الطيالسة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1134","bookId":"riyad","type":"hadith","num":1134,"kitab":"كتاب المنثورات والملح","isnad":"وعن أم شريك رضي الله عنها أنها سمعت النبي صلى الله عليه وسلم يقول‏:‏ لينفرن الناس من الدجال في الجبال‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1135","bookId":"riyad","type":"hadith","num":1135,"kitab":"كتاب المنثورات والملح","isnad":"وعن عمران بن حصين رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ما بين خلق آدم إلى قيام الساعة أمر أكبر من الدجال‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1136","bookId":"riyad","type":"hadith","num":1136,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “يخرج الدجال فيتوجه قبله رجل من المؤمنين فيتلقاه المسالح‏:‏ مسالح الدجال، فيقولون له‏:‏ إلى أين تعمد‏؟‏ فيقول‏:‏ أعمد إلى هذا الذي خرج فيقولون له أوَ ما تؤمن بربنا‏؟‏ فيقول‏:‏ ما بربنا خفاء‏!‏ فيقولون‏:‏ اقتلوه، فيقول بعضهم لبعض‏:‏ أليس قد نهاكم ربكم أن تقتلوا أحداً دونه، فينطلقون به إلى الدجال، فإذا رآه المؤمن قال‏:‏ يا أيها الناس إن هذا الدجال الذي ذكر رسول الله صلى الله عليه وسلم ؛ فيأمر الدجال به فيشبّح؛ فيقول‏:‏ خذوه وشجوه، فيوسع ظهره وبطنه ضرباً، فيقول‏:‏ أوَ ما تؤمن بي‏؟‏ فيقول‏:‏ أنت المسيح الكذاب‏!‏ فيؤمر به ، فيؤشر بالمنشار من مفرقه حتى يفرق بين رجليه، ثم يمشي الدجال بين القطعتين ، ثم يقول له‏:‏ قم ، فيستوي قائماً، ثم يقول له‏:‏ أتؤمن بي‏؟‏ فيقول‏:‏ ما ازددت فيك إلا بصيرة، ثم يقول‏:‏ يا أيها الناس إنه لا يفعل بعدي بأحد من الناس، فيأخذه الدجال ليذبحه، فيجعل الله ما بين رقبته إلى ترقوته نحاساً، فلا يستطيع إليه سبيلا، فيأخذ بيديه ورجليه فيقذف به، فيحسب الناس أنما قذفه إلى النار، وإنما ألقي في الجنة‏","matn":"\"‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏هذا أعظم الناس شهادة عند رب العالمين‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وروى البخاري بعضه بمعناه “المسالح” ‏:‏هم الخفراء والطلائع‏.‏"},{"id":"riyad:1137","bookId":"riyad","type":"hadith","num":1137,"kitab":"كتاب المنثورات والملح","isnad":"وعن المغيرة بن شعبة رضي الله عنه قال‏:‏ ما سأل أحد رسول الله صلى الله عليه وسلم عن الدجال أكثر مما سألته؛ وإنه قال لي‏:‏ ‏","matn":"\"‏مايضرك‏؟‏ ‏\"‏قلت‏:‏ إنهم يقولون‏:‏ إن معه جبل خبز ونهر ماء‏!‏ قال‏:‏ ‏\"‏هو أهون على الله من ذلك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1138","bookId":"riyad","type":"hadith","num":1138,"kitab":"كتاب المنثورات والملح","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما من نبي إلا وقد أنذر أمته الأعور الكذاب، ألا إنه أعور، وإن ربكم عز وجل ليس بأعور، مكتوب بين عينيه ك ف ر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1139","bookId":"riyad","type":"hadith","num":1139,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ألا أحدثكم حديثاً عن الدجال ما حدث به نبي قومه‏!‏ إنه أعور، وإنه يجيء معه بمثال الجنة والنار، فالتي يقول إنها الجنة هي النار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1140","bookId":"riyad","type":"hadith","num":1140,"kitab":"كتاب المنثورات والملح","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم ذكر الدجال بين ظهراني الناس فقال‏:‏ ‏","matn":"\"‏ إن الله ليس بأعور، ألا إن المسيح الدجال أعور العين اليمنى، كأن عينه عنبة طافية‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1141","bookId":"riyad","type":"hadith","num":1141,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا تقوم الساعة حتى يقاتل المسلمون اليهود، حتى يختبيء اليهودي من وراء الحجر والشجر، فيقول الحجر والشجر‏:‏ يا مسلم هذا يهودي خلفى تعالى فاقتله، إلا الغرقد فإنه من شجر اليهود‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1142","bookId":"riyad","type":"hadith","num":1142,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ والذي نفسي بيده لا تذهب الدنيا حتى يمر الرجل بالقبر، فيتمرغ عليه، ويقول‏:‏ ياليتني مكان صاحب هذا القبر، وليس به الدين، ما به إلا البلاء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1143","bookId":"riyad","type":"hadith","num":1143,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لا تقوم الساعة حتى يحسر الفرات عن جبل من ذهب يقتتل عليه، فيقتل من كل مائة تسعة وتسعون، فيقول كل رجل منه‏:‏ لعلي أن أكون أنا أنجو‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏يوشك أن يحسر الفرات عن كنز من ذهب، فمن حضره فلا يأخذ منه شيئاً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1144","bookId":"riyad","type":"hadith","num":1144,"kitab":"كتاب المنثورات والملح","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏يتركون المدينة على خير ما كانت، لا يغشاها إلا العوافي -يريد‏:‏ عوافي السباع والطير، وآخر من يحشر راعيان من مزينة يريدان المدينة ينعقان بغنمهما فيجدانها وحوشاً، حتى إذا بلغا ثنية الوداع خراً على وجوههما‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1145","bookId":"riyad","type":"hadith","num":1145,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يكون خليفة ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ خلفائكم في آخر الزمان يحثو المال ولا يعده‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1146","bookId":"riyad","type":"hadith","num":1146,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي موسى الأشعري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليأتين على الناس زمان يطوف الرجل فيه بالصدقة من الذهب، فلا يجد أحداً يأخذها منه، ويرى الرجل الواحد يتبعه أربعون امرأة يلذن به من قلة الرجال وكثرة النساء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1147","bookId":"riyad","type":"hadith","num":1147,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ اشترى رجل من رجل عقاراً، فوجد الذي اشترى العقار في عقاره جرة فيها ذهب، فقال له الذي اشترى العقار خذ ذهبك‏:‏ إنما اشتريت منك الأرض، ولم أشتر الذهب، وقال الذي له الأرض‏:‏ إنما بعتك الأرض وما فيها، فتحاكما إلى رجل، فقال الذي تحاكما إليه‏:‏ ألكما ولد‏؟‏ قال أحدهما ‏:‏ لي غلام، وقال الآخر‏:‏ لي جارية، قال‏:‏ أنكحا الغلام الجارية وأنفقوا على أنفسهما منه وتصدقا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1148","bookId":"riyad","type":"hadith","num":1148,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏كانت امرأتان معهما ابناهما، جاء الذئب فذهب بابن إحداهما، فقالت لصاحبتها‏:‏ إنما ذهب بابنك، وقالت الأخرى إنما ذهب بابنك فتحاكما إلى داود صلى الله عليه وسلم فقضى به للكبرى، فخرجتا على سليمان بن داود، صلى الله عليه وسلم فأخبرتاه، فقال‏:‏ ائتوني بالسكين أشقه بينهما‏.‏ فقالت الصغرى‏:‏ لا تفعل رحمك الله، هو ابنها، فقضى به للصغرى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1149","bookId":"riyad","type":"hadith","num":1149,"kitab":"كتاب المنثورات والملح","isnad":"وعن مرادس الأسلمي رضي الله عنه قال‏:‏ قال للنبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يذهب الصالحون الأول فالأول، وتبقى حثالة كحثالة الشعير أو التمر، لا يباليهم الله باله‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1150","bookId":"riyad","type":"hadith","num":1150,"kitab":"كتاب المنثورات والملح","isnad":"وعن رفاعة بن رافع الزرقي رضي الله عنه قال‏:‏ جاء جبريل إلى النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إذا أنزل الله تعالى بقوم عذاباً‏‏.‏ وعن رفاعة بن رافع الزُّرَقِيِّ - رضي الله عنه - قال: جاء جبريل إلى النبيّ - صلى الله عليه وسلم - قال: مَا تَعُدُّونَ أهْلَ بَدْرٍ فِيكُمْ؟ قال: «مِنْ أفْضَلِ المُسْلِمِينَ» أوْ كَلِمَةً نَحْوَهَا. قال: وَكَذلِكَ مَنْ شَهِدَ بَدْرًا مِنَ المَلائِكَةِ. (‏رواه البخاري)"},{"id":"riyad:1151","bookId":"riyad","type":"hadith","num":1151,"kitab":"كتاب المنثورات والملح","isnad":"","matn":"وعن ابن عمر رضي الله عنهما قال : قال رسولُ اللهِ : « إذَا أنْزَلَ اللهُ تَعَالَى بِقَومٍ عَذَاباً ، أصَابَ العَذَابُ مَنْ كَانَ فِيهِمْ ، ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ » . متفق عليه ."},{"id":"riyad:1152","bookId":"riyad","type":"hadith","num":1152,"kitab":"كتاب المنثورات والملح","isnad":"وعن جابر رضي الله عنه قال‏:‏ كان جذع يقوم إليه النبي صلى الله عليه وسلم ، يعني في الخطبة‏.‏ فلما وضع المنبر، سمعنا للجذع مثل صوت العشار حتى نزل النبي، صلى الله عليه وسلم ، فوضع يده عليه فسكن‏","matn":"\"‏‏.‏ وفي رواية‏:‏ فلما كان يوم الجمعة قعد النبي، صلى الله عليه وسلم على المنبر، فصاحت النخلة التى كان يخطب عندها حتى كادت أن تنشق‏.‏ وفي رواية ‏:‏ فصاحت صياح الصبي، فنزل النبي صلى الله عليه وسلم ، حتى أخذها فضمها إليه، فجعلت تئن أنين الصبي الذي يسكت حتى استقرت ، قال‏:‏ ‏\"‏بكت على ما كانت تسمع من الذكر‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1153","bookId":"riyad","type":"hadith","num":1153,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي ثعلبة الخشني جرثوم بن ناشر رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله تعالى فرض فرائض فلا تضيعوها، وحد حدوداً فلا تعتدوها، وحرم أشياء فلا تنتهكوها، وسكت عن أشياء رحمة لكم غير نسيان فلا تبحثوا عنها‏\"‏‏.‏ حديث حسن. رواه الدارقطني وغيره."},{"id":"riyad:1154","bookId":"riyad","type":"hadith","num":1154,"kitab":"كتاب المنثورات والملح","isnad":"وعن عبد الله بن أبي أوفى رضي الله عنهما قال‏:‏ غزونا مع رسول الله صلى الله عليه وسلم سبع غزوات نأكل الجراد، وفي رواية‏:‏ نأكل معه الجراد‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1155","bookId":"riyad","type":"hadith","num":1155,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يلدغ المؤمن من جحر مرتين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1156","bookId":"riyad","type":"hadith","num":1156,"kitab":"كتاب المنثورات والملح","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ، ‏:‏ ‏","matn":"\"‏ثلاثة لا يكلمهم الله يوم القيامة ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم‏:‏ رجل على فضل ماء بالفلاة يمنعه من ابن السبيل، ورجل بايع رجلاً، سلعة، بعد العصر، فحلف بالله لأخذها بكذا وكذا، فصدقه وهو على غير ذلك، ورجل بايع إماماً لا يبايعه إلا لدنيا، فإن أعطاه منها وفى ، وإن لم يعطه منها لم يف‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1157","bookId":"riyad","type":"hadith","num":1157,"kitab":"كتاب المنثورات والملح","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ بين النفختين أربعون‏\"‏ قالوا‏:‏ يا أبا هريرة أربعون يوماً‏؟‏ قال‏:‏ أبيت، قالوا‏:‏ أربعون سنة‏؟‏ قال‏:‏ أبيت، قالوا‏:‏ أربعون شهراً‏؟‏ قال‏:‏ أبيت‏\"‏ ويبلى كل شئ من الإنسان إلا عجب ذنبه، فيه يركب الخلق، ثم ينزل الله من السماء ماء، فينبتون كما ينبت البقل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1158","bookId":"riyad","type":"hadith","num":1158,"kitab":"كتاب المنثورات والملح","isnad":"وعنه قال‏:‏ بينما النبي صلى الله عليه وسلم في مجلس يحدث القوم، جاءه أعرابي فقال‏:‏ متى الساعة‏؟‏ فمضى رسول الله صلى الله عليه وسلم ، يحدث، فقال بعض القوم‏:‏ سمع ما قال‏:‏ فكره ما قال، وقال بعضهم‏:‏ بل لم يسمع، حتى إذا قضى حديثه قال‏:‏ ‏","matn":"\"‏أين السائل عن الساعة‏؟‏ ‏\"‏قال‏:‏ ها أنا يا رسول الله ‏.‏ قال‏:‏ ‏\"‏إذا ضيعت الأمانة ، فانتظر الساعة‏\"‏ قال‏:‏ كيف إضاعتها‏؟‏ قالك ‏\"‏إذا وسد الأمر إلى غير أهله فانتظر الساعة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1159","bookId":"riyad","type":"hadith","num":1159,"kitab":"كتاب المنثورات والملح","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يصلون لكم، فإن أصابوا فلكم، وإن أخطؤوا فلكم وعليهم‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1160","bookId":"riyad","type":"hadith","num":1160,"kitab":"كتاب المنثورات والملح","isnad":"","matn":"وعنه رضي الله عنه ‏:‏ ‏{‏كنتم خير أمة أخرجت للناس‏}‏ قال‏:‏ خير الناس للناس يأتون بهم في السلاسل في أعناقهم حتى يدخلوا في الإسلام‏.‏ أخرجه: البخاري."},{"id":"riyad:1161","bookId":"riyad","type":"hadith","num":1161,"kitab":"كتاب المنثورات والملح","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏عجب الله عز وجل من قوم يدخلون الجنة في السلاسل‏\"‏ ‏(‏‏(‏رواهما البخاري‏)‏‏)‏‏.‏ معناه: يؤسرون ويقيدون ثم يسلمون فيدخلون الجنة."},{"id":"riyad:1162","bookId":"riyad","type":"hadith","num":1162,"kitab":"كتاب المنثورات والملح","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أحب البلاد إلى الله مساجدها ، وأبغض البلاد إلى الله أسواقها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1163","bookId":"riyad","type":"hadith","num":1163,"kitab":"كتاب المنثورات والملح","isnad":"وعن سلمان الفارسي رضي الله عنه من قوله قال‏:‏ لا تكونن إن استطعت أول من يدخل السوق، ولا آخر من يخرج منها، فإنها معركة الشيطان، وبها ينصب رايته‏.‏ ‏(‏‏(‏رواه مسلم هكذا‏)‏‏)‏‏.‏ ورواه البرقاني في صحيحه عن سلمان قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا تكن أول من يدخل السوق، ولا آخر من يخرج منها، فيها باض الشيطان وفرخ‏\"‏‏.‏"},{"id":"riyad:1164","bookId":"riyad","type":"hadith","num":1164,"kitab":"كتاب المنثورات والملح","isnad":"وعن عاصم الأحول عن عبد الله بن سرجس رضي الله عنه قال‏:‏ قلت لرسول الله صلى الله عليه وسلم ‏:‏ يا رسول الله غفر الله لك، قال‏:‏ ‏","matn":"\"‏ولك‏\"‏ قال عاصم‏:‏ فقلت له‏:‏ استغفر لك رضي الله عنه صلى الله عليه وسلم ‏؟‏ قال‏:‏ نعم ولك، ثم تلا هذه الآية‏:‏ ‏{‏واستغفر لذنبك، وللمؤمنين والمؤمنات‏}‏ ‏(‏‏(‏محمد‏:‏19‏)‏‏)‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1165","bookId":"riyad","type":"hadith","num":1165,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي مسعود الأنصاري رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن مما أدرك الناس من كلام النبوة الأولى‏:‏ إذا لم تستحي فاصنع ما شئت‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1166","bookId":"riyad","type":"hadith","num":1166,"kitab":"كتاب المنثورات والملح","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏أول ما يقضى بين الناس يوم القيامة في الدماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1167","bookId":"riyad","type":"hadith","num":1167,"kitab":"كتاب المنثورات والملح","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏خلقت الملائكة من نور، وخلق الجان من مارج من نار، وخلق آدم مما وصف لكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1168","bookId":"riyad","type":"hadith","num":1168,"kitab":"كتاب المنثورات والملح","isnad":"وعنها رضي الله عنها قالت‏:‏ ‏","matn":"\"‏كان خلق نبي الله صلى الله عليه وسلم القرآن‏\"‏ ‏(‏‏(‏رواه مسلم في جملة حديث طويل‏)‏‏)‏‏.‏"},{"id":"riyad:1169","bookId":"riyad","type":"hadith","num":1169,"kitab":"كتاب المنثورات والملح","isnad":"وعنها قالت ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه‏\"‏ فقلت‏:‏ يا رسول الله ، أكراهية الموت‏؟‏ فكلنا نكره الموت‏!‏ قال‏:‏‏\"‏ليس كذلك، ولكن المؤمن إذا بشر برحمة الله ورضوانه وجنته أحب لقاء الله ، فأحب الله لقاءه، وإن الكافر إذا بشر بعذاب الله وسخطه، كره لقاء الله وكره الله لقاءه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1170","bookId":"riyad","type":"hadith","num":1170,"kitab":"كتاب المنثورات والملح","isnad":"وعن أم المؤمنين صفية بن حيي رضي الله عنها قالت‏:‏ كان النبي صلى الله عليه وسلم معتكفاً، فأتيته أزوره ليلاً، فحدثته ثم قمت لأنقلب، فقام معي ليقلبني، فمر رجلان من الأنصار رضي الله عنهما ، فلما رأيا النبي صلى الله عليه وسلم أسرعا، فقال صلى الله عليه وسلم ‏:‏ على رسلكما إنها صفية بنت حيي فقالا‏:‏ سبحان الله يا رسول الله‏!‏ ‏:‏‏","matn":"\"‏إن الشيطان يجري من ابن آدم مجرى الدم، وإني خشيت أن يقذف في قلوبكما شراً أو قال‏:‏ شيئاً” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1171","bookId":"riyad","type":"hadith","num":1171,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي الفضل العباس بن عبد المطلب رضي الله عنه قال‏:‏ شهدت مع رسول الله صلى الله عليه وسلم يوم حنين فلزمت أنا وأبو سفيان بن الحارث بن عبد المطلب رسول الله صلى الله عليه وسلم فلم نفارقه ورسول الله صلى الله عليه وسلم على بغلة له بيضاء، فلما التقى المسلمون والمشركون ولى المسلمون مدبرين ، فطفق رسول الله صلى الله عليه وسلم ، يركض بغلته قبل الكفار، وأنا آخذ بلجام بغلة رسول الله صلى الله عليه وسلم ،أكفها إرادة أن لا تسرع وأبو سفيان آخذ بركاب رسول الله صلى الله عليه وسلم فقال‏:‏ رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أي عباس ناد أصحاب السمرة” قال العباس، وكان رجلاً صيتا فقلت بأعلى صوتي‏:‏ أين أصحاب السمرة، فوالله لكأن عطفتهم حين سمعوا صوتى عطفة البقر على أولادها، فقالوا‏:‏ يا لبيك يا لبيك، فاقتتلوا هم والكفار، والدعوة في الأنصار يقولون‏:‏ يا معشر الأنصار، يا معشر الأنصار، ثم قصرت الدعوة على بني الحارث بن الخزرج، فنظر رسول الله صلى الله عليه وسلم وهو على بغلته كالمتطاول عليها إلى قتالهم فقال‏:‏ ‏\"‏هذا حين حمي الوطيس‏\"‏ ثم أخذ رسول الله صلى الله عليه وسلم حصيات، فرمى بهن وجوه الكفار، ثم قال‏:‏ ‏\"‏انهزموا ورب محمد‏\"‏، فذهبت أنظر فإذا القتال على هيئته فيما أرى، فوالله ما هو إلا أن رماهم بحصياته، فما زلت أرى حدهم كيلاً، وأمرهم مدبراً، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏«الوطيس» التنور، ومعناه: اشتدت الحرب. وقوله: «حدهم» هو بالحاء المهملة: أي بأسهم."},{"id":"riyad:1172","bookId":"riyad","type":"hadith","num":1172,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يا أيها الناس إن الله طيب لا يقبل إلا طيباً، وإن الله أمر المؤمنين بما أمر به المرسلين، فقال تعالى‏:‏ ‏{‏يا أيها الرسل كلوا من الطيباب واعلموا صالحاً‏}‏، وقال تعالى‏:‏ ‏{‏يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم‏}‏ ثم ذكر الرجل يطيل السفر أشعث أغبر يمد يديه إلى السماء ‏:‏ يا رب يارب، ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام فأنى يستجاب لذلك‏!‏‏؟‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1173","bookId":"riyad","type":"hadith","num":1173,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ثلاثة لا يكلمهم الله يوم القيامة، ولا يزكيهم، ولا ينظر إليهم ، ولهم عذاب أليم‏:‏ شيخ زان، وملك كذاب، وعائل مستكبر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ (4)"},{"id":"riyad:1174","bookId":"riyad","type":"hadith","num":1174,"kitab":"كتاب المنثورات والملح","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏سيحان وجيحان والفرات والنيل كل من أنهار الجنة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1175","bookId":"riyad","type":"hadith","num":1175,"kitab":"كتاب المنثورات والملح","isnad":"وعنه قال‏:‏ أخذ رسول الله صلى الله عليه وسلم بيدي فقال‏:‏ ‏","matn":"\"‏خلق الله التربة يوم السبت، وخلق فيها الجبال يوم الأحد، وخلق الشجر يوم الأثنين وخلق المكروه يوم الثلاثاء، وخلق النور يوم الأربعاء، وبث فيها الدواب يوم الخميس، وخلق آدم صلى الله عليه وسلم بعد العصر من يوم الجمعة في آخر الخلق في آخر ساعة من النهار فيما بين العصر إلى الليل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1176","bookId":"riyad","type":"hadith","num":1176,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي سليمان خالد بن الوليد رضي الله عنه قال‏:‏ “لقد انقطعت في يدي يوم مؤته تسعة أسياف، فما بقي في يدي إلا صفيحة يمانية‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1177","bookId":"riyad","type":"hadith","num":1177,"kitab":"كتاب المنثورات والملح","isnad":"وعن عمرو بن العاص رضي الله عنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إذا حكم الحاكم، فاجتهد، ثم أصاب، فله أجران، وإن حكم واجتهد، فأخطأ، فله أجر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1178","bookId":"riyad","type":"hadith","num":1178,"kitab":"كتاب المنثورات والملح","isnad":"وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الحمى فيح جهنم فأبردوها بالماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1179","bookId":"riyad","type":"hadith","num":1179,"kitab":"كتاب المنثورات والملح","isnad":"وعنها رضي الله عنها عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من مات وعليه صوم، صام عنه وليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1180","bookId":"riyad","type":"hadith","num":1180,"kitab":"كتاب المنثورات والملح","isnad":"","matn":"وعن عوف بن مالك بن الطفيل أن عائشة رضي الله عنها حدثت أن عبد الله بن الزبير رضي الله عنهما قال في بيع أو عطاء أعطته عائشة رضي الله عنها‏:‏ والله لتنتهين عائشة، أو لأحجرن عليها، قالت أهو قال هذا ‏؟‏ قالو‏:‏ نعم، قالت‏:‏ هو لله علي نذر أن لا أكلم ابن الزبير أبدا، فاستشفع بن الزبير إليها حين طالت الهجرة، فقالت‏:‏ لا والله لا أشفع فيه أبداً، ولا أتحنث إلى نذري فلما طال ذلك على ابن الزبير كلم المسور ابن مخرمة، وعبد الرحمن بن الأسود بن عبد يغوث وقال لهما‏:‏ أنشدكما الله لما أدخلتماني على عائشة رضي الله عنها، فإنها لا يحل لها أن تنذر قطيعتى، فأقبل به المسور، وعبد الرحمن حتى استأذنا على عائشة، فقالا‏:‏ السلام عليك ورحمة الله وبركاته، أندخل‏؟‏ قالت عائشة‏:‏ ادخلوا، قالوا‏:‏ كلنا‏؟‏ قالت‏:‏ نعم ادخلوا كلكم، ولا تعلم أن معهما ابن الزبير، فلما دخلوا ، دخل ابن الزبير الحجاب، فاعتنق عائشة رضي الله عنها، وطفق يناشدها ويبكي، وطفق المسور، وعبد الرحمن يناشدانها إلا كلمته وقبلت منه، ويقولان ‏:‏ إن النبي صلى الله عليه وسلم نها عما قد علمت من الهجرة، ولا يحل لمسلم أن يهجر أخاه فوق ثلاث ليال، فلما أكثروا على عائشة من التذكرة والتحريج، طفقت تذكرهما وتبكي ، وتقول‏:‏ إني نذرت والنذر شديد ، فلم يزالا بها حتى كلمت ابن الزبير، وأعتقت في نذرها ذلك أربعين رقبة، وكانت تذكر نذرها بعد ذلك فتبكي حتى تبل دموعها خمارها‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1181","bookId":"riyad","type":"hadith","num":1181,"kitab":"كتاب المنثورات والملح","isnad":"وعن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم خرج إلى قتلى أحد، فصلى عليهم بعد ثمان سنين كالمودع للأحياء والأموات، ثم طلع إلى المنبر ، فقال‏:‏ إني بين أيديكم فرط وأنا شهيد عليكم، وإن موعدكم الحوض ، وإني لأنظر إليه من مقامي هذا، وإني لست أخشى عليكم أن تشركوا، ولكن أخشى عليكم الدنيا أن تنافسوها‏","matn":"\"‏ قال‏:‏ فكانت آخر نظرة نظرتها إلى رسول الله صلى الله عليه وسلم ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية ‏:‏ ‏\"‏ولكني أخشى عليكم الدنيا أن تنافسوا فيها ، وتقتتلوا فتهلكوا كملا هلك من كان قبلكم‏\"‏ قال عقبة‏:‏ فكان آخر ما رأيت رسول الله صلى الله عليه وسلم على المنبر‏. وفي رواية قال: «إني فرط لكم وأنا شهيد عليكم وإني والله لأنظر إلى حوضي الآن، وإني أعطيت مفاتيح خزائن الأرض، أو مفاتيح الأرض، وإني والله ما أخاف عليكم أن تشركوا بعدي، ولكن أخاف عليكم أن تنافسوا فيها» . والمراد بالصلاة على قتلى أحد: الدعاء لهم، لا الصلاة المعروفة.‏"},{"id":"riyad:1182","bookId":"riyad","type":"hadith","num":1182,"kitab":"كتاب المنثورات والملح","isnad":"","matn":"وعن أبي زيد عمرو بن أخطب الأنصاري رضي الله عنه قال‏:‏ صلى بنا رسول الله صلى الله عليه وسلم الفجر، وصعد المنبر، فخطبنا حتى حضرت الظهر، فنزل فصلى، ثم صعد المنبر حتى حضرت العصر، ثم نزل فصلى، ثم صعد المنبر حتى غربت الشمس، فأخبرنا ما كان هو كائن، فأعلمنا أحفظنا‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1183","bookId":"riyad","type":"hadith","num":1183,"kitab":"كتاب المنثورات والملح","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ من نذر أن يطيع الله فليطعه ومن نذر أن يعصي الله فلا يعصه‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1184","bookId":"riyad","type":"hadith","num":1184,"kitab":"كتاب المنثورات والملح","isnad":"-وعن أم شريك رضي الله عنها أن رسول الله صلى الله عليه وسلم أمرها بقتل الأوزاغ وقال‏:‏ “كان ينفخ على إبراهيم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1185","bookId":"riyad","type":"hadith","num":1185,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “من قتل وزغة في أول ضربة فله كذا وكذا حسنة،ومن قتلها في الضربة الثانية، فله كذا وكذا حسنة، ودون الأول وإن قتلها في الضربة الثالثة، فله كذا وكذا حسنة” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية‏:‏ ‏","matn":"\"‏من قتل وزغاً في أول ضربة، كتب له مائة حسنة، وفى الثانية دون ذلك، وفى الثالثة دون ذلك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ قال أهل اللغة: «الوزغ» العظام من سام أبرص."},{"id":"riyad:1186","bookId":"riyad","type":"hadith","num":1186,"kitab":"كتاب المنثورات والملح","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ قال رجل لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد سارق، فأصبحوا يتحدثون‏:‏ تصدق على سارق‏!‏ فقال‏:‏ اللهم لك الحمد لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد زانية‏؟‏‏!‏ فأصبحوا يتحدثون‏:‏ تصدق على زانية فقال‏:‏ اللهم لك الحمد على زانية، لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد غني‏,‏ فأصبحوا يتحدثون‏!‏ تصدق الليلة على غني‏,‏ فقال‏:‏ اللهم لك الحمد على سارق ، وعلى زانية، وعلى غني‏!‏ فأتى فقيل له‏:‏ أما صدقتك على سارق، فلعله أن يستعف عن سرقته، وأما الزانية فلعلها تستعف عن زناها، وأما الغني فلعله أن يعتبر، فينفق مما آتاه الله‏\"‏ ‏(‏‏(‏رواه البخاري بلفظه، ومسلم بمعناه‏)‏‏)‏‏.‏"},{"id":"riyad:1187","bookId":"riyad","type":"hadith","num":1187,"kitab":"كتاب المنثورات والملح","isnad":"وعنه قال‏:‏ كنا مع رسول الله صلى الله عليه وسلم في دعوة، فرفع إليه الذراع، وكانت تعجبه، فنهس منها نهسة وقال‏:‏ أنا سيد الناس يوم القيامة، هل تدرون مم ذاك‏؟‏ يجمع الله الأولين والآخرين في صعيد واحد، فيبصرهم الناظر، ويسمعهم الداعي، وتدنوا منهم الشمس، فيبلغ الناس من الغم والكرب ما لا يطيقون ولا يحتملون ، فيقول الناس‏:‏ ألا ترون إلى ما أنتم فيه إلى ما بلغكم، ألا تنظرون من يشفع لكم إلى ربكم‏؟‏ فيقول بعض الناس لبعض‏:‏ أبوكم آدم، ويأتونه فيقولون‏:‏ يا آدم أنت أبو البشر، خلقك الله بيده، ونفخ فيك من روحه، وأمر الملائكة، فسجدوا لك وأسكنك الجنة، ألا تشفع لنا إلى ربك‏؟‏ ألا ترى ما نحن فيه، وما بلغنا‏؟‏ فقال‏:‏ إن ربي غضب غضباً لم يغضب قبله مثله، ولا يغضب بعده مثله، وإنه نهاني عن الشجرة، فعصيت، نفسي نفسي نفسي، اذهبوا إلى غيري، إذهبوا إلى نوح، فيأتون نوحا فيقولون‏:‏ يا نوح ، أنت أول الرسل إلى أهل الأرض، وقد سماك الله عبداً شكوراً، ألا ترى ما نحن فيه، ألا ترى ما بلغنا ألا تشفع لنا إلى ربك‏؟‏ فيقول‏:‏ إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإنه قد كانت لي دعوة دعوت بها على قومي، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى إبراهيم فيأتون إبراهيم فيقولون‏:‏ يا إبراهيم أنت نبي الله وخليله من أهل الأرض اشفع لنا إلى ربك، ألا ترى ما نحن فيه‏؟‏ فيقول لهم‏:‏ إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإني كنت كذبت ثلاث كذبات، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى موسى، فيأتون موسى، فيقولون‏:‏ يا موسى أنت رسول الله فضلك الله برسالاته وبكلامه على الناس، اشفع لنا إلى ربك ألا ترى ما نحن فيه‏؟‏ فيقول‏:‏ إن ربي قد غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإني قد قتلت نفساً لم أومر بقتلها، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى عيسى، فيأتون عيسى، فيقولون‏:‏ يا عيسى أنت رسول الله وكلمته ألقاها إلى مريم وروح منه ، وكلمت الناس في المهد ‎، اشفع لنا إلى ربك، ألا ترى ما نحن فيه‏؟‏ فيقول عيسى‏:‏ إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله ولم يذكر ذنباً، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى محمد صلى الله عليه وسلم ‏","matn":"\"‏‏.‏ وفي رواية‏:‏ ‏\"‏فيأتوني فيقولون‏:‏ يا محمد أنت رسول الله وخاتم الأنبياء، وقد غفر لك ما تقدم من ذنبك وما تأخر، اشفع لنا إلى ربك، ألا ترى ما نحن فيه‏؟‏ فأنطلق، فأتي تحت العرش، فأقع ساجداً لربي، ثم يفتح الله علي من محامده، وحسن الثناء عليه شيئاً لم يفتح على أحد قبلي ثم يقال‏:‏ يا محمد ارفع رأسك، سل تعطه، واشفع تشفع، فأرفع رأسي، فأقول أمتي يارب، أمتي يا رب، فيقال‏:‏ يا محمد أدخل من أمتك من لا حساب عليهم من الباب الأيمن من أبواب الجنة وهم شركاء الناس فيما سوى ذلك من الأبواب‏\"‏ ثم قال‏:‏‏\"‏ والذي نفسي بيده إن ما بين المصراعين من مصاريع الجنة كما بين مكة وهجر، أو كما بين مكة وبصرى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1188","bookId":"riyad","type":"hadith","num":1188,"kitab":"كتاب المنثورات والملح","isnad":"وعن بن عباس رضي الله عنهما قال‏:‏ جاء إبراهيم صلى الله عليه وسلم بأم إسماعيل وبابنها إسماعيل وهي ترضعه حتى وضعها عند البيت عند دوحة فوق زمزم في أعلى المسجد وليس بمكة يومئذ أحد وليس بها ماء، فوضعهما هناك، ووضع عندهما جراباً فيه تمر، وسقاء فيه ماء، ثم قفى إبراهيم منطلقاً، فتبعته أم إسماعيل فقالت‏:‏ يا إبراهيم أين تذهب وتتركنا بهذا الوادي الذي ليس فيه أنيس ولا شيء‏؟‏ فقالت له ذلك مراراً، وجعل لا يلتفت إليها، قالت له‏:‏ آلله أمرك بهذا‏؟‏ قال‏:‏ نعم ، قالت‏:‏ إذا لا يضيعنا، ثم رجعت، فانطلق إبراهيم صلى الله عليه وسلم ، حتى إذا كان عند الثنية حيث يرونه استقبل بوجهه البيت ، ثم دعا بهؤلاء الدعوات ، فرفع يديه فقال‏:‏ ‏{‏ربنا إني أسكنت من ذريتي بواد غير ذي زرع‏}‏ حتى بلغ ‏{‏يشكرون‏}‏ وجعلت أم إسماعيل ترضع إسماعيل، وتشرب من ذلك الماء، حتى إذا نفد ما في السقاء عطشت، وعطش ابنها، وجعلت تنظر إليه يتلوى -أوقال‏:‏ يتلبط- فانطلقت كراهية أن تنظر إليه ، فوجدت الصفا أقرب جبل في الأرض يليها، فقامت عليه، ثم استقبلت الوادي تنظر هل ترى أحداً‏؟‏ فلم تر أحداً، فهبطت من الصفا حتى إذا بلغت الوادي، رفعت طرف درعها، ثم سعت سعي الإنسان المجهود حتى جاوزت الوادي، ثم أتت المروة، فقامت عليها، فنظرت هل ترى أحداً‏؟‏ فلم تر أحداً، ففعلت ذلك سبع مرات، قال ابن عباس رضي الله عنهما‏:‏ قال النبي صلى الله عليه وسلم ‏","matn":"\"‏فذلك سعي الناس بينها‏\"‏ فلما أشرفت على المروة سمعت صوتاً، فقالت‏:‏ صه-تريد نفسها- ثم تسمّعت ، فسمعت أيضاً فقالت‏:‏ قد أسمعت إن كان عندك غواث فأغث، فإذا هى بالملك عند موضع زمزم، فبحث بعقبه -أو قال بجناحه- حتى ظهر الماء، فجعلت تحوضه وتقول بيدها هكذا، وجعلت تغرف الماء في سقائها وهو يفور بعدما تغرف، وفي رواية ‏:‏ بقدر ما تغرف، قال ابن عباس رضي الله عنهما ‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏رحم الله أم إسماعيل لو تركت زمزم -أو قال‏:‏ لو لم تغرف من الماء، لكان زمزم عينا معينا” قال‏:‏ فشربت ، وأرضعت ولدها، فقال لها الملك‏:‏ لا تخافوا الضيعة فإن ههنا بيتا لله يبنيه هذا الغلام وأبوه، وإن الله لا يضيع أهله، وكان البيت مرتفعاً من الأرض كالرابية تأتيه السيول، فتأخذ عن يمينه وعن شماله، فكانت كذلك حتى مرت بهم رفقة من جرهم، أو أهل بيت من جرهم مقبلين من طريق كداء، فنزلوا في أسفل مكة، فرأوا طائراً عائفاً فقالوا‏:‏ إن هذا الطائر ليدور على ماء لعهدنا بهذا الوادي وما فيه ماء، فأرسلوا جرياً أو جريين، فإذا هم بالماء، فرجعوا، فأخبروهم، فأقبلوا وأم إسماعيل عند الماء، فقالوا‏:‏ أتأذنين لنا أن ننزل عندك‏؟‏ قالت‏:‏ نعم، ولكن لا حق لكم في الماء، قالوا‏:‏ نعم، قال ابن عباس‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏فألفى ذلك أم إسماعيل، وهي تحب الأنس، فنزلوا، فأرسلوا إلى أهليهم فنزلوا معهم، حتى إذا كانوا بها أهل أبيات، وشب الغلام وتعلم العربيه منهم وأنفسهم وأعجبهم حين شب ، فلما أدرك، زوجوه امرأة منهم، وماتت أم إسماعيل، فجاء إبراهيم بعد ما تزوج إسماعيل يطالع تركته فلم يجد إسماعيل، فسأل امرأته عنه فقالت‏:‏ خرج يبتغي لنا- وفي رواية‏:‏ يصيد لنا - ثم سألها عن عيشهم وهيئتهم فقالت‏:‏ نحن بشر ، نحن في ضيق وشدة، وشكت إليه ، قال‏:‏ فإذا جاء زوجك، أقرئي عليه السلام وقولي‏:‏ غير عتبة بابك، قال‏:‏ ذاك أبي وقد أمرني أن أفارقك، الحقي بأهلك‏.‏ فطلقها ، وتزوج منهم أخرى، فلبث عنهم إبراهيم ما شاء الله ثم أتاهم بعد، فلم يجده ، فدخل على امرأته، فسأله عنه، قالت‏:‏ خرج يبتغي لنا، قال‏:‏ كيف أنتم‏؟‏ وسألها عن عيشهم وهيئتهم، فقالت‏:‏ نحن بخير وسعة وأثنت على الله تعالى، فقال‏:‏ ما طعامكم‏؟‏ قالت‏:‏ اللحم قال‏:‏ فما شرابكم‏؟‏ قالت الماء‏.‏ قال‏:‏ اللهم بارك لهم في اللحم والماء، قال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏ولم يكن لهم يؤمئذ حب ولو كان لهم دعا لهم فيه” قال‏:‏ فهما لا يخلو عليهما أحد بغير مكة إلا لم يوافقاه‏.‏ وفي رواية فجاء فقال‏:‏ أين إسماعيل‏؟‏ فقالت امرأته‏:‏ ذهب يصيد، فقالت امرأته‏:‏ ألا تنزل، فتطعم وتشرب‏؟‏ قال‏:‏ وما طعامكم وما شرابكم‏؟‏ قالت‏:‏ طعامنا اللحم، وشرابنا الماء، قال‏:‏ اللهم بارك لهم في طعامهم وشرابهم- قال، فقال أبوالقاسم صلى الله عليه وسلم ‏:‏ “بركة دعوة إبراهيم صلى الله عليه وسلم ‏\"‏ قال‏:‏ فإذا جاء زوجك ، فاقرئي عليه السلام ومريه يثبت عتبة بابه، فلما جاء إسماعيل، قال‏:‏ هل أتاكم من أحد‏؟‏ قالت‏:‏ نعم، أتانا شيخ حسن الهيئة، وأثنت عليه فسألني عنك، فأخبرته ،فسألني كيف عيشنا، فأخبرته، أنّا بخير، قال‏:‏ فأوصاك بشيء‏؟‏ قالت‏:‏ نعم، يقرأ عليك السلام، ويأمرك أن تثبت عبتة بابك، قال‏:‏ ذاك أبي وأنت العتبة أمرني أن أمسكك، ثم لبث عنهم ما شاء الله، ثم جاء بعد ذلك وإسماعيل يبري نبلاً له تحت دوحة قريباً من زمزم، فلما رآه، قام إليه ، فصنع كما يصنع الوالد بالولد، والولد بالوالد قال يا إسماعيل إن الله أمرني بأمر ، قال‏:‏ فاصنع ما أراك ربك‏؟‏ قال‏:‏ وتعينني، قال‏:‏ وأعينك، قال‏:‏ فإن الله أمرني أن أبني بيتا ههنا، وأشار إلى أكمة مرتفعة على ما حولها، فعند ذلك رفع القواعد من البيت، فجعل إسماعيل يأتي بالحجارة وإبراهيم يبني حتى إذا ارتفع البناء، جاء بهذا الحجر فوضعه له فقام عليه، وهو يبني وإسماعيل يناوله الحجارة وهما يقولان ‏:‏ ربنا تقبل منا إنك أنت السميع العليم‏.‏ وفي رواية‏:‏ إن إبراهيم خرج بإسماعيل وأم إسماعيل، معهم شنة فيها ماء، فجعلت أم إسماعيل تشرب من الشنة، فيدر لبنها على صبيها حتى قدم مكة، فوضعها تحت دوحة، ثم رجع إبراهيم إلى أهله، فاتبعته أم إسماعيل حتى لما بلغوا كداء، نادته من ورائه‏:‏ يا إبراهيم إلى من تتركنا‏؟‏ قال‏:‏ إلى الله ، قالت‏:‏ رضيت بالله، فرجعت، وجعلت تشرب من الشنة، ويدر لبنها على صبيها حتى لما فني الماء قالت‏:‏ لو ذهبت ، فنظرت لعلي أحس أحداً، قال‏:‏ فذهبت فصعدت الصفا، فنظرت ونظرت هل تحس أحداً، فلما بلغت الوادي، سمعت، وأتت المروة، وفعلت ذلك أشواطا، ثم قالت‏:‏ لو ذهبت فنظرت ما فعل الصبي، فذهبت ونظرت، فإذا هو على حاله كأنه ينشغ للموت، فلم تقرها نفسها ، فقالت‏:‏ لو ذهبت ، فنظرت لعلي أحس أحداً، فذهبت فصعدت الصفا، فنظرت ونظرت، فلم تحس أحداً حتى أتمت سبعاً، ثم قالت‏:‏ لو ذهبت ، فنظرت ما فعل، فإذا هي بصوت فقال‏:‏ أغث إن كان عندك خير، فإذا جبريل صلى الله عليه وسلم فقال بعقبه هكذا، وغمز بعقبه على الأرض فانبثق الماء فدهشت أم إسماعيل، فجعلت تحفن، وذكر الحديث بطوله‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ بهذه الروايات كلها‏.‏ «الدوحة» الشجرة الكبيرة. قوله: «قفى» : أي: ولى. ... «والجري» : الرسول. «وألفى» : معناه وجد. قوله: «ينشغ» : أي: يشهق."},{"id":"riyad:1189","bookId":"riyad","type":"hadith","num":1189,"kitab":"كتاب المنثورات والملح","isnad":"وعن سعيد بن زيد رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏الكمأة من المن، وماؤها شفاء للعين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1190","bookId":"riyad","type":"hadith","num":1190,"kitab":"كتاب الاستغفار","isnad":"وعن الأغر المزني رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إنه ليغان على قلبي، وإني لأستغفر الله في اليوم مائة مرة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1191","bookId":"riyad","type":"hadith","num":1191,"kitab":"كتاب الاستغفار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول “والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1192","bookId":"riyad","type":"hadith","num":1192,"kitab":"كتاب الاستغفار","isnad":"وعنه رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏والذي نفسي بيده لو لم تذنبوا، لذهب الله تعالى بكم، ولجاء بقوم يذنبون فيستغفرون الله تعالى فيغفر لهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1193","bookId":"riyad","type":"hadith","num":1193,"kitab":"كتاب الاستغفار","isnad":"وعن بن عمر رضي الله عنه قال‏:‏ كنا نعد لرسول الله صلى الله عليه وسلم في المجلس الواحد مائة مرة‏:‏ ‏","matn":"\"‏رب اغفر لي، وتب على إنك أنت التواب الرحيم‏\"‏ ‏(‏‏(‏رواه أبوداود والترمذي‏)‏‏)‏‏.‏ وقال : (( حديث حسن صحيح غريب )) ."},{"id":"riyad:1194","bookId":"riyad","type":"hadith","num":1194,"kitab":"كتاب الاستغفار","isnad":"وعن ابن عباس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “من لزم الاستغفار ، جعل الله له من كل ضيق مخرجاً ومن كل هم فرجاً، ورزقه من حيث لا يحتسب‏","matn":"\"‏ رواه أبو داود‏‏.‏"},{"id":"riyad:1195","bookId":"riyad","type":"hadith","num":1195,"kitab":"كتاب الاستغفار","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من قال‏:‏ أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه ، غفرت ذنوبه ، وإن كان قد فر من الزحف‏\"‏ ‏(‏‏(‏رواه أبو داود والترمذي والحاكم، وقال‏:‏ حديث صحيح على شرط البخاري ومسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1196","bookId":"riyad","type":"hadith","num":1196,"kitab":"كتاب الاستغفار","isnad":"وعن شداد بن أوس رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏سيد الإستغفار أن يقول العبد ‏:‏ اللهم أنت ربي، لا إله إلا أنت ، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي، وأبوء بذنبي، فاغفر لي فإنه لا يغفر الذنوب إلا أنت، من قالها من النهار موقنا بها، فمات من يومه قبل أن يمسي، فهو من أهل الجنة، ومن قالها من الليل وهو موقن بها فمات قبل أن يصبح، فهو من أهل الجنة” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ (1)"},{"id":"riyad:1197","bookId":"riyad","type":"hadith","num":1197,"kitab":"كتاب الاستغفار","isnad":"- وعن ثوبان رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم إذا انصرف من صلاته ، استغفر الله ثلاثاً وقال‏:‏ ‏","matn":"\"‏اللهم أنت السلام، ومنك السلام، تباركت يا ياذا الجلال والإكرام‏\"‏ قيل للأوزاعي- وهو أحد رواته‏:‏ كيف الإستغفار‏؟‏ قال‏:‏ يقول‏:‏ ‏\"‏أستغفر الله ، أستغفر الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1198","bookId":"riyad","type":"hadith","num":1198,"kitab":"كتاب الاستغفار","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يكثر أن يقول قبل موته ‏","matn":"\"‏سبحان الله وبحمده، أستغفر الله، وأتوب إليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1199","bookId":"riyad","type":"hadith","num":1199,"kitab":"كتاب الاستغفار","isnad":"وعن أنس رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “قال الله تعالى‏:‏ يا ابن آدم إنك ما دعوتني ورجوتني غفرت لك ما كان منك ولا أبالي، يا ابن آدم لو بلغت ذنوبك عنان السماء، ثم استغفرتني ، غفرت لك ولا أبالي، يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا، ثم لقيتني لا تشرك بي شيئاً، لأتيتك بقرابها مغفرة‏","matn":"\"‏ ‏.‏ (2)"},{"id":"riyad:1200","bookId":"riyad","type":"hadith","num":1200,"kitab":"كتاب الاستغفار","isnad":"وعن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يا معشر النساء تصدقن، وأكثرن من الاستغفار، فإني رأيتكن أكثر أهل النار‏\"‏ قالت امرأة منهن‏:‏ مالنا أكثر أهل النار‏؟‏ قال‏:‏ ‏\"‏تكثرن اللعن، وتكفرن العشير مارأيت من ناقصات عقل ودين أغلب لذي لب منكن‏\"‏ قالت‏:‏ ما نقصان العقل والدين‏؟‏ قال‏\"‏ ‏\"‏شهادة امرأتين بشهادة رجل، وتمكث الأيام لا تصلي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1201","bookId":"riyad","type":"hadith","num":1201,"kitab":"كتاب الاستغفار","isnad":"وعن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “يأكل أهل الجنة فيها ، ويشربون ، ولا يتغوطون، ولا يتمخطون، ولا يبولون، ولكن طعامهم ذلك جشاء كرشح المسك، يلهمون التسبيح والتكبير، كما يلهمون النفس‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1202","bookId":"riyad","type":"hadith","num":1202,"kitab":"كتاب الاستغفار","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏قال الله تعالى أعددت لعبادي الصالحين ما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر، واقرؤوا إن شئتم‏:‏ ‏{‏فلا تعلم نفس ما أخفي لهم من قرة أعين جزاء بما كانوا يعملون‏}‏ ‏(‏‏(‏السجدة‏:‏17‏)‏‏)‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1203","bookId":"riyad","type":"hadith","num":1203,"kitab":"كتاب الاستغفار","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أول زمرة يدخلون الجنة على صورة القمر ليلة البدر، ثم الذين يلونهم على أشد كوكب دري في السماء إضاءة، لا يبولون ولا يتغوطون، ولا يتفلون، ولا يتمخطون، أمشاطهم الذهب، وريحهم المسك، ومجامرهم الألوة -عود الطيب- أزواجهم الحورالعين، على خلق رجل واحد، على صورة أبيهم آدم ستون ذراعاً في السماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية للبخاري ومسلم‏:‏ آنيتهم فيها الذهب، ورشحهم المسك، ولكل واحد منهم زوجتان يرى مخ ساقهما من وراء اللحم من الحسن، لا اختلاف بينهم ، ولا تباغض‏:‏ قلوبهم قلب رجل واحد، يسبحون الله بكرة وعشياً‏. قوله: (على خلق رجل واحد). رواه بعضهم بفتح الخاء واسكان اللام وبعضهم بضمهما وكلاهما صحيح."},{"id":"riyad:1204","bookId":"riyad","type":"hadith","num":1204,"kitab":"كتاب الاستغفار","isnad":"وعن المغيرة بن شعبة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏سأل موسى صلى الله عليه وسلم ربه، ما أدنى أهل الجنة منزلة ‏؟‏ قال‏:‏ هو رجل يجيء بعد ما أدخل أهل الجنة-الجنة، فيقال له ‏:‏ ادخل الجنة، فيقول‏:‏ أي رب كيف وقد نزل الناس منازلهم، وأخذوا أخذاتهم‏؟‏ فيقول له‏:‏ أترضى أن يكون لك مثل ملك ملك من ملوك الدنيا‏؟‏ فيقول‏:‏ رضيت رب فيقول‏:‏ لك ذلك ومثله ومثله ومثله ومثله، فيقول في الخامسة‏:‏ رضيت يا رب فيقول‏:‏ هذا لك وعشرة أمثاله، ولك ما اشتهيت نفسك، ولذت عينك، فيقول‏:‏ رضيت رب، قال رب فأعلاهم منزلة‏؟‏ قال‏:‏ أولئك الذين أردت؛ غرست كرامتهم بيدي، وختمت عليها، فلم تر عين، ولم تسمع أذن، ولم يخطر على قلب بشر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1205","bookId":"riyad","type":"hadith","num":1205,"kitab":"كتاب الاستغفار","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إني لأعلم آخر النار خروجاً منها، وآخر أهل الجنة دخولاً الجنة، رجل يخرج من النار حبوا؛ فيقول الله عز وجل له‏:‏ اذهب فادخل الجنة، فيأتيها، فيخيل إليه أنها ملأى، فيرجع فيقول‏:‏ يا رب وجدتها ملأى، فيقول الله عز وجل له‏:‏ اذهب فادخل الجنة، فيرجع ، فيقول‏:‏ يا رب وجدتها ملأى، في سورة يقول الله عز وجل له ‏:‏ اذهب فادخل الجنة ، فيأتيها، فيخيل إليه أنها ملأى، فيرجع، فيقول‏:‏ يا رب وجدتها ملأى‏!‏ فيقول الله عز وجل له‏:‏ اذهب فادخل الجنة، فإن لك مثل الدنيا وعشرة أمثالها أو إن لك مثل عشرة أمثال الدنيا، فيقول‏:‏ أتسخر بي، أو تضحك بي وأنت الملك” قال‏:‏ فلقد رأيت رسول الله صلى الله عليه وسلم ضحك حتى بدت نواجذه فكان يقول‏:‏ ‏\"‏ذلك أدنى أهل الجنة منزلة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1206","bookId":"riyad","type":"hadith","num":1206,"kitab":"كتاب الاستغفار","isnad":"وعن أبي موسى رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن للمؤمن في الجنة لخيمة من لؤلؤة واحدة مجوفة طولها في السماء ستون ميلاً، للمؤمن فيها أهلون، يطوف عليهم المؤمن فلا يرى بعضهم بعضاً، ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏«الميل» : ستة آلاف ذراع"},{"id":"riyad:1207","bookId":"riyad","type":"hadith","num":1207,"kitab":"كتاب الاستغفار","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن في الجنة لشجرة يسير الراكب الجواد المضمر السريع مائة سنة ما يقطعها ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وروياه في ‏\"‏الصحيحين‏\"‏ أيضاً من رواية أبي هريرة رضي الله عنه قال‏:‏ ‏\"‏يسير الراكب في سورة في ظلها سنة ما يقطعها‏\"‏‏.‏"},{"id":"riyad:1208","bookId":"riyad","type":"hadith","num":1208,"kitab":"كتاب الاستغفار","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن أهل الجنة ليتراءون أهل الغرف من فوقهم كما تراءون الكوكب الدري الغابر في الأفق من المشرق أو المغرب لتفاضل ملا بينهم‏\"‏ قالوا‏:‏ يا رسول الله، تلك منازل الأنبياء لا يبلغها غيرهم‏؟‏ قال‏:‏ “بلى والذي نفسي بيده رجال آمنوا بالله وصدقوا المرسلين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1209","bookId":"riyad","type":"hadith","num":1209,"kitab":"كتاب الاستغفار","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لقاب قوس في الجنة خير مما تطلع عليه الشمس أو تغرب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1210","bookId":"riyad","type":"hadith","num":1210,"kitab":"كتاب الاستغفار","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن في الجنة سوقاً يأتونها كل جمعة‏.‏ فتهب ريح الشمال، فتحثوا في وجوههم وثيابهم، فيزدادون حسناً وجمالاً فيرجعون إلى أهليهم، وقد ازدادوا حسناً وجمالاً، فيقول لهم أهلوهم‏:‏ والله لقد ازددتم حسناً وجمالاً‏!‏ فيقولون‏:‏ وأنتم والله لقد ازددتم بعدنا حسناً وجمالاً‏!‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1211","bookId":"riyad","type":"hadith","num":1211,"kitab":"كتاب الاستغفار","isnad":"وعن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن أهل الجنة ليتراءون الغرف في الجنة كما تتراءون الكوكب في السماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1212","bookId":"riyad","type":"hadith","num":1212,"kitab":"كتاب الاستغفار","isnad":"وعنه رضي الله عنه قال‏:‏ شهدت من النبي صلى الله عليه وسلم مجلساً وصف فيه الجنة حتى انتهى، ثم قال في آخر حديثه‏:‏ ‏","matn":"\"‏فيها مالا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر‏\"‏ ثم قرأ ‏{‏تتجافى جنوبهم عن المضاجع‏}‏ إلى قوله تعالى‏:‏ ‏{‏فلا تعلم نفس ما أخفي لهم من قرة أعين‏}‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1213","bookId":"riyad","type":"hadith","num":1213,"kitab":"كتاب الاستغفار","isnad":"وعن أبي سعيد وأبي هريرة رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ “إذا دخل أهل الجنة - الجنة- ينادي مناد‏:‏ إن لكم أن تحيوا، فلا تموتوا أبداً، وإن لكم أن تصحوا، فلا تسقموا أبداً، وإن لكم أن تشبوا فلا تهرموا أبداً، وإن لكم أن تنعموا، فلا تبأسوا أبداً‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1214","bookId":"riyad","type":"hadith","num":1214,"kitab":"كتاب الاستغفار","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن أدنى مقعد أحدكم من الجنة أن يقول له‏:‏ تمن فيتمنى ويتمنى، فيقول له‏:‏ هل تمنيت‏؟‏ فيقول‏:‏ نعم، فيقول له‏:‏ فإن لك ما تمنيت ومثله معه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1215","bookId":"riyad","type":"hadith","num":1215,"kitab":"كتاب الاستغفار","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله عز وجل يقول لأهل الجنة‏:‏ يا أهل الجنة، فيقولون ‏:‏ لبيك ربنا وسعديك، والخير في يديك فيقول‏:‏ هل رضيتم‏؟‏ فيقولون‏:‏ وما لنا لا نرضى يا ربنا وقد أعطيتنا مالم تعط أحداً من خلقك‏!‏ فيقول‏:‏ ألا أعطيكم أفضل من ذلك فيقولون‏:‏ وأي شيء أفضل من ذلك‏؟‏ فيقول‏:‏ أحل عليكم رضواني، فلا أسخط عليكم بعده أبداً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1216","bookId":"riyad","type":"hadith","num":1216,"kitab":"كتاب الاستغفار","isnad":"وعن جرير بن عبد الله رضي الله عنه قال‏:‏ كنا عند رسول الله صلى الله عليه وسلم فنظر إلى القمر ليلة البدر، وقال‏:‏ ‏","matn":"\"‏إنكم سترون ربكم عياناً كما ترون هذا القمر، لا تضامون في رؤيته‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏.‏"},{"id":"riyad:1217","bookId":"riyad","type":"hadith","num":1217,"kitab":"كتاب الاستغفار","isnad":"وعن صهيب رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا دخل أهل الجنة -الجنة- يقول الله تبارك وتعالى‏:‏ تريدون شيئاً أزيدكم‏؟‏ فيقولون‏:‏ ألم تبيض وجوهنا‏؟‏ ألم تدخلنا الجنة وتنجنا من النار‏؟‏ فيكشف الحجاب، فما أعطو شيئاً أحب إليهم من النظر إلى ربهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ قال الله تعالى‏:‏ ‏{‏إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم تجري من تحتهم الأنهار في جنات النعيم* دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام وآخر دعواهم أن الحمد لله رب العالمين‏}‏ ‏(‏‏(‏يونس‏:‏9،10‏)‏‏)‏‏.‏ الحمد لله الذي هدانا لهذا وما كنا لنهتدى لولا أن هدانا الله‏.‏ اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم ، وبارك على محمد، وعلى آل محمد، كما باركت على إبراهيم وعلى آل إبراهيم ، إنك حميد مجيد‏.‏ قال مؤلفه رضي الله عنه ‏:‏ ‏\"‏ فرغت منه يوم الاثنين رابع شهر رمضان سنة سبعين وستمائة‏\"‏‏.‏"},{"id":"riyad:1218","bookId":"riyad","type":"hadith","num":1218,"kitab":"كتاب المقدمات","isnad":"وعن أمير المؤمنين أبي حفص عمر بن الخطاب بن نفيل بن عبد العزى بن رياح بن قرط بن رزاح بن عدى بن لؤى ابن غالب القرشى العدوى‏.‏ رضي الله عنه، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ إنما الأعمال بالنيات، وإنما لكل امرىء ما نوى فمن كانت هجرته إلى الله ورسوله فهجرته إلى الله ورسوله، ومن كانت هجرته لدنيا يصيبها، أو امرأة ينكحها فهجرته إلى ما هاجر إليه‏\"‏ ‏(‏‏(‏متفق على صحته‏.‏ رواه إماما المحدثين‏: أبو عبدالله محمد بن إسماعيل بن إبراهيم بن المغيرة بن بَرْدِزْبَهْ الجعفي البخاري، أبو الحسين مسلم بن الحجاج بن مسلم القشيرى النيسابورى رضي الله عنهما في صحيحهما اللذين هما أصح الكتب المصنفة‏)‏‏)‏‏.‏"},{"id":"riyad:1219","bookId":"riyad","type":"hadith","num":1219,"kitab":"كتاب المقدمات","isnad":"وعن أم المؤمنين أم عبد الله عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يغزو جيش الكعبة فإذا كانوا ببيداء من الأرض يخسف بأولهم وآخرهم‏\"‏‏.‏ قالت‏:‏ قلت‏:‏ يارسول الله، كيف يخسف بأولهم وآخرهم وفيهم أسواقهم ومن ليس منهم‏!‏‏؟‏ قال‏:‏ ‏\"‏يخسف بأولهم وآخرهم، ثم يبعثون على نياتهم‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ هذا لفظ البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1220","bookId":"riyad","type":"hadith","num":1220,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ لا هجرة بعد الفتح، ولكن جهاد ونية، وإذا استنفرتم فانفروا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1221","bookId":"riyad","type":"hadith","num":1221,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله جابر بن عبد الله الأنصارى رضي الله عنهما قال‏:‏ كنا مع النبي صلى الله عليه وسلم في غزاةٍ فقال‏:‏ ‏","matn":"\"‏إن بالمدينة لرجالاً ماسرتم مسيراً، ولا قطعتم وادياً إلا كانوا معكم حبسهم المرض‏\"‏ وفى رواية‏:‏ ‏\"‏إلا شاركوكم في الأجر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏(‏‏(‏ورواه البخاري‏)‏‏)‏ عن أنس رضي الله عنه قال‏:‏ رجعنا من غزوة تبوك مع النبي صلى الله عليه وسلم فقال‏:‏ ‏\"‏ إن أقواماً خلفنا بالمدينة ما سلكنا شعباً ولا وادياً إلا وهم معنا، حبسهم العذر‏\"‏‏.‏"},{"id":"riyad:1222","bookId":"riyad","type":"hadith","num":1222,"kitab":"كتاب المقدمات","isnad":"وعن أبي يزيد معن بن يزيد بن الأخنس رضي الله عنهم، وهو وأبوه وجده صحابيون، قال‏:‏ كان أبي يزيد أخرج دنانير يتصدق بها فوضعها عند رجل في المسجد فجئت فأخذتها فأتيته بها، فقال‏:‏ والله ما إياك أردت، فخاصمته إلى رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏ لك ما نويت يا يزيد، ولك ما أخذت يامعن‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1223","bookId":"riyad","type":"hadith","num":1223,"kitab":"كتاب المقدمات","isnad":"وعن أبي إسحاق سعد بن أبي وقاص مالك بن أهيب بن عبد مناف بن زهرة بن كلاب بن مرة بن كعب بن لؤى القرش الزهرى رضي الله عنه، أحد العشرة المشهود لهم بالجنة، رضي الله عنهم، قال‏:‏ ‏","matn":"\"‏ جاءنى رسول الله صلى الله عليه وسلم يعودنى عام حجة الوداع من وجع اشتد بى فقلت‏:‏ يارسول الله إني قد بلغ بى من الوجع ما ترى، وأنا ذو مال ولا يرثنى إلا ابنة لي، أفاتصدق بثلثى ما لي‏؟‏ قال‏:‏ لا، قلت‏:‏ فالشطر يارسول الله‏؟‏ فقال‏:‏ لا، قلت‏:‏ فالثلث يا رسول الله‏؟‏ قال الثلث والثلث كثير- أو كبير- إنك أن تذر ورثتك أغنياء خير من أن تذرهم عالة يتكففون الناس، وإنك لن تنفق نفقة تبتغى بها وجه الله إلا أجرت عليها حتى ما تجعل في فيّ امرأتك قال‏:‏ فقلت‏:‏ يارسول الله أخلف بعد أصحابي‏؟‏ قال‏:‏ إنك لن تخلف فتعمل عملا تبتغي بهوجه الله إلا ازددت به درجة ورفعةً، ولعلك أن تخلف حتى ينتفع بك أقوام ويضرّ بك آخرون‏.‏ اللهم امض لآصحابى هجرتهم، ولا تردهم على أعقابهم، لكن البائس سعد بن خولة‏\"‏ يرثى له رسول الله صلى الله عليه وسلم أن مات بمكة‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1224","bookId":"riyad","type":"hadith","num":1224,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة عبد الرحمن بن صخر رضي الله عنه قال قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ إن الله لا ينظر إلى أجسامكم ، ولا إلى صوركم، ولكن ينظر إلى قلوبكم وأعمالكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1225","bookId":"riyad","type":"hadith","num":1225,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم عن الرجل يقاتل شجاعة، ويقاتل حميةً، ويقاتل رياء، أى ذلك في سبيل الله‏؟‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من قاتل لتكون كلمة الله هى العليا فهو في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1226","bookId":"riyad","type":"hadith","num":1226,"kitab":"كتاب المقدمات","isnad":"وعن أبي بكرة نفيع بن الحارث الثقفى رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذ التقى المسلمان بسيفيهما فالقاتل والمقتول في النار‏\"‏ قلت يارسول الله، هذا القاتل فما بال المقتول‏؟‏ قال‏:‏ ‏\"‏إنه كان حريصاً على قتل صاحبه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1227","bookId":"riyad","type":"hadith","num":1227,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏صلاة الرجل في جماعة تزيد على صلاته في سوقه وبيته بضعاً وعشرين درجه وذلك أن أحدهم إذا توضأ فأحسن الوضوء ثم أتى المسجد لا يريد إلا الصلاة، لا ينهزه إلا الصلاة، لم يخط خطوة إلا رفع له بها درجة، وحط عنه بها خطيئة حتى يدخل المسجد، فإذا دخل المسجد كان في الصلاة ما كانت الصلاة هى تحبسه، والملائكة يصلون على أحدكم ما دام في مجلسه الذى صلى فيه، ما لم يحدث فيه‏\"‏ ‏(‏‏(‏متفق عليه، وهذا لفظ مسلم‏)‏‏)‏‏.‏ وقوله صلى الله عليه وسلم‏:‏ '‏‏ ‏ينهزه‏ ‏ هو بفتح الياء والهاء وبالزاى‏:‏ أى يخرجه وينهضه ‏'"},{"id":"riyad:1228","bookId":"riyad","type":"hadith","num":1228,"kitab":"كتاب المقدمات","isnad":"وعن أبي العباس عبد الله بن عباس بن عبد المطلب رضي الله عنهما، عن رسول الله، صلى الله عليه وسلم، فيما يروى عن ربه، تبارك وتعالى قال‏:‏ ‏","matn":"\"‏ إن الله كتب الحسنات والسيئات ثم بين ذلك‏:‏ فمن همّ بحسنة فلم يعملها كتبها الله تبارك وتعالى عنده حسنة كاملة، وإن هم بها فعملها كتبها الله عشر حسنات إلى سبعمائه ضعف إلى أضعاف كثيرة، وإن هم بسيئة فلم يعملها كتبها الله عنده حسنة كاملة، وإن همّ بها فعملها كتبها الله سيئة واحدة ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1229","bookId":"riyad","type":"hadith","num":1229,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الرحمن عبد الله بن عمر بن الخطاب، رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ انطلق ثلاثة نفر ممن كان قبلكم حتى آواهم المبيت إلى غار فدخلوه، فانحدرت صخرة من الجبل فسدت عليهم الغار، فقالوا‏:‏ إنه لا ينجيكم من هذه الصخرة إلا أن تدعوا الله بصالح أعمالكم‏.‏ قال رجل منهم‏:‏ اللهم كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلاً ولا مالاً‏.‏ فنأى بى طلب الشجر يوماً فلم أرح عليهما حتى ناما فحلبت لهما غبوقهما فوجدتهما نائمين فكرهت أن أوقظهما وأن أغبق قبلهما أهلاً أو مالاً، فلبثت- والقدح على يدى- أنتظر استيقاظهما حتى برق الفجر والصبية يتضاغون عند قدمى- فاستيقظا فشربا غبوقهما‏.‏ اللهم إن كنت فعلت ذلك ابتغاء وجهك ففرج عنا ما نحن فيه من هذه الصخرة، فانفرجت شيئاً لا يستطيعون الخروج منه‏.‏ قال الآخر‏:‏ اللهم إنه كانت لي ابنة عم كانت أحب الناس إلىّ ‏\"‏ وفى رواية‏:‏ ‏\"‏كنت أحبها كأشد ما يحب الرجال النساء، فأردتها على نفسها فامتنعت منى حتى ألمّت بها سنة من السنين فجاءتنى فأعطيتها عشرين ومائة دينار على أن تخلى بينى وبين نفسها ففعلت، حتى إذا قدرت عليها‏\"‏ وفى رواية‏:‏ ‏\"‏فلما قعدت بين رجليها، قالت‏:‏ اتق الله ولا تفض الخاتم إلا بحقه، فانصرفت عنها وهى أحب الناس إلى وتركت الذهب الذى أعطيتها، اللهم إن كنت فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة غير أنهم لا يستطيعون الخروج منها‏.‏ وقال الثالث‏:‏ اللهم استأجرت أجراء وأعطيتهم أجرهم غير رجل واحد ترك الذى له وذهب، فثمرت أجره حتى كثرت منه الأموال، فجاءنى بعد حين فقال‏:‏ يا عبد الله أدّ إلى أجرى، فقلت‏:‏ كل ما ترى من أجرك‏:‏ من الإبل والبقر والغنم والرقيق‏.‏ فقال‏:‏ يا عبد الله لا تستهزئ بى‏!‏ فقلت‏:‏ لا أستهزئ بك، فأخذه كله فاستاقه فلم يترك منه شيئاً، اللهم إن كنتُ فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة فخرجوا يمشون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1230","bookId":"riyad","type":"hadith","num":1230,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة ‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1231","bookId":"riyad","type":"hadith","num":1231,"kitab":"كتاب المقدمات","isnad":"وعن الأغر بن يسار المزنى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ ياأيها الناس توبوا إلى الله واستغفروه فإنى أتوب في اليوم مائه مرة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1232","bookId":"riyad","type":"hadith","num":1232,"kitab":"كتاب المقدمات","isnad":"وعن أبي حمزة أنس بن مالك الأنصارى خادم رسول الله صلى الله عليه وسلم، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لله أفرح بتوبة عبده من أحدكم سقط على بعيره وقد أضله في أرض فلاة ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفى رواية لمسلم‏:‏ لله أشد فرحا بتوبة عبده حين يتوب إليه من أحدكم كان على راحلته بأرض فلاة، فانفلتت منه وعليها طعامه وشرابه فأيس منها، فأتى شجرة فاضطجع في ظلها، وقد أيس من راحلته، فبينما هو كذلك إذا هو بها، قائمة عنده ، فأخذ بخطامها ثم قال من شدة الفرح‏:‏ اللهم أنت عبدي وأنا ربك، أخطأ من شدة الفرح‏\"‏‏.‏"},{"id":"riyad:1233","bookId":"riyad","type":"hadith","num":1233,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى عبد الله بن قيس الأشعرى رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إن الله تعالى يبسط يده بالليل ليتوب مسيء النهار، ويبسط يده بالنهار ليتوب مسيء الليل حتى تطلع الشمس من مغربها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1234","bookId":"riyad","type":"hadith","num":1234,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ من تاب قبل أن تطلع الشمس من مغربها تاب الله عليه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1235","bookId":"riyad","type":"hadith","num":1235,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الرحمن عبد الله بن عمر بن الخطاب رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إن الله عز وجل يقبل توبة العبد ما لم يغرغر‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1236","bookId":"riyad","type":"hadith","num":1236,"kitab":"كتاب المقدمات","isnad":"وعن زر بن حبيش قال‏:‏ أتيت صفوان بن عسال رضي الله عنه أسأله عن المسح على الخفين فقال‏:‏ ما جاء بك يازر‏؟‏ فقلت‏:‏ ابتغاء العلم، فقال‏:‏ إن الملائكة تضع أجنحتها لطالب العلم رضي بما يطلب، فقلت‏:‏ من أصحاب النبي صلى الله عليه وسلم ، فجئت أسألك‏:‏ هل سمعته يذكر في ذلك شيئاً‏؟‏ قال‏:‏ نعم، كان يأمرنا إذا كنا سفراً- أو مسافرين- أن لا ننزع خفافناً ثلاثة أيام ولياليهن إلا من جنابة، ولكن من غائط وبول ونوم‏.‏ فقلت‏:‏ سفر، فبينا نحن عنده إذ ناداه أعرابى بصوت له جهورى‏:‏ يا محمد، فأجابه رسول الله صلى الله عليه وسلم نحواً من صوته‏:‏ ‏","matn":"\"‏هاؤم‏\"‏ فقلت له‏:‏ ويحك اغضض من صوتك فإنك عند النبي صلى الله عليه وسلم ، وقد نهيت عن هذا‏!‏ فقال‏:‏ والله لا أغضض‏.‏ قال الأعرابى‏:‏ المرء يحب القوم ولما يلحق بهم‏؟‏ قال النبي صلى الله عليه وسلم‏:‏ ‏\"‏ المرء مع من أحب يوم القيامة‏\"‏ فما زال يحدثنا حتى ذكر باباً من المغرب مسيرة عرضه أو يسير الراكب في عرضه أربعين أو سبعين عاماً‏.‏ قال سفيان أحد الرواة قبل الشام خلقه الله تعالى يوم خلق السماوات والأرض مفتوحاً للتوبة لا يغلق حتى تطلع الشمس منه‏\"‏ ‏(‏‏(‏رواه الترمذي وغيره وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1237","bookId":"riyad","type":"hadith","num":1237,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنه أن نبي الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ كان فيمن كان قبلكم رجل قتل تسعة وتسعين نفساً، فسأل عن أعلم أهل الأرض، فدل على راهب، فأتاه فقال‏:‏ إنه قتل تسعه وتسعين نفساً، فهل له من توبة‏؟‏ فقال‏:‏ لا، فقتله فكمل به مائةً، ثم سأل عن أعلم أهل الأرض، فدل على رجل عالم فقال‏:‏ إنه قتل مائة نفس فهل له من توبة‏؟‏ فقال‏:‏ نعم، ومن يحول بينه وبين التوبة‏؟‏ انطلق إلى أرض كذا وكذا، فإن بها أناساً يعبدون الله تعالى فاعبد الله معهم، ولا ترجع إلى أرضك فإنها أرض سوءٍ، فانطلق حتى إذا نصف الطريق أتاه الموت، فاختصمت فيه ملائكة الرحمة وملائكة العذاب‏.‏ فقالت ملائكة الرحمة‏:‏ جاء تائبا مقبلا بقلبه إلى الله تعالى، وقالت ملائكة العذاب‏:‏ إنه لم يعمل خيرا قط، فأتاهم ملك في صورة آدمي فجعلوه بينهم- أي حكماً- فقال‏:‏ قيسوا ما بين الأرضين فإلى أيتهما كان أدنى فهو له، فقاسوا فوجدوه أدنى إلى الأرض التي أراد، فقبضته ملائكة الرحمة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1238","bookId":"riyad","type":"hadith","num":1238,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن كعب بن مالك، وكان قائد كعب رضي الله عنه من بنيه حين عمي قال‏:‏ سمعت كعب بن مالك رضي الله عنه يحدث بحديثه حين تخلف عن رسول الله صلى الله عليه وسلم في غزوة تبوك‏.‏ قال كعب‏:‏ لم اتخلف عن رسول الله، صلى الله عليه وسلم ، في غزوة غزاها قط إلا في غزوة تبوك، غير أني قد تخلفت في غزوة بدر، ولم يعاتب أحد تخلف عنه، إنما خرج رسول الله صلى الله عليه وسلم والمسلمون يريدون عير قريش حتى جمع الله تعالى بينهم وبين عدوهم على غير ميعاد‏.‏ ولقد شهدت مع رسول الله صلى الله عليه وسلم ليلة العقبة حين تواثقنا على الإسلام، وما أحب أن لي بها مشهد بدرٍ، وإن كانت بدر أذكر في الناس منها‏.‏ وكان من خبري حين تخلف عن رسول الله، صلى الله عليه وسلم، في غزوة تبوك أني لم أكن قط أقوى ولا أيسر مني حين تخلفت عنه في تلك الغزوة، والله ما جمعت قبلها راحلتين قط حتى جمعتهما في تلك الغزوة، ولم يكن رسول الله صلى الله عليه وسلم يريد غزوة إلا ورى بغيرها حتى كانت تلك الغزوة، فغزاها رسول الله صلى الله عليه وسلم في حر شديد، واستقبل سفراً بعيداً ومفازاً، واستقبل عدداً كثيراً، فجلى للمسلمين أمرهم ليتأهبوا أهبة غزوهم فأخبرهم بوجههم الذي يريد، والمسلمون مع رسول الله كثير ولا يجمعهم كتاب حافظ ‏","matn":"\"‏يريد بذلك الديوان‏\"‏ قال كعب‏:‏ فقل رجل يريد أن يتغيب إلا ظن أن ذلك سيخفى به مالم ينزل فيه وحي من الله، وغزا رسول الله صلى الله عليه وسلم تلك الغزوة حين طابت الثمار والظلال فأنا إليها أصعر فتجهز رسول الله صلى الله عليه وسلم والمسلمون معه، وطفقت أغدو لكي أتجهز معه، فأرجع ولم أقض شيئاً، وأقول في نفسي‏:‏ أنا قادر على ذلك إذا أردت، فلم يزل يتمادى بي حتى استمر بالناس الجد، فأصبح رسول الله صلى الله عليه وسلم غادياً والمسلمون معه، ولم أقض من جهازي شيئاً، ثم غدوت فرجعت ولم أقض شيئاً، فلم يزل يتمادى بي حتى أسرعوا وتفارط الغرو، فهممت أن أرتحل فأدركهم، فياليتني فعلت، ثم لم يقدر ذلك لي، فطفقت إذا خرجت في الناس بعد خروج رسول الله صلى الله عليه وسلم يحزنني أني أرى لي أسوة، إلا رجلاً مغموصاً عليه في النفاق، أو رجلاً ممن عذر الله تعالى من أسوة، إلا رجلاً مغموصاً عليه في النفاق، أو رجلاً ممن عذر الله تعالى من الضعفاء، ولم يذكرني رسول الله صلى الله عليه وسلم حتى بلغ تبوك، فقال وهو جالس في القوم بتبوك‏:‏ ما فعل كعب بن مالك‏؟‏ قَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ يَا رَسُولَ اللَّهِ حَبَسَهُ بُرْدَاهُ وَالنَّظَرُ فِي عِطْفَيْهِ.فقال له معاذ بن جبل رضي الله عنه بئس ما قلت‏!‏ والله يارسول الله ما علمنا عليه إلا خيراً ، فسكت رسول الله صلى الله عليه وسلم فبينا هو على ذلك رأى رجلا مبيضا يزول به السراب فقال رسول الله صلى الله عليه وسلم‏:‏ كن أبا خيثمة، فإذا أبو خيثمة الأنصاري وهو الذي تصدق بصاع التمر حين لمزه المنافقون، قال كعب‏:‏ فلما بلغني أن رسول الله صلى الله عليه وسلم قد توجه قافلاً من تبوك حضرني بثي، فطفقت أتذكر الكذب وأقول‏:‏ بم أخرج من سخطه غداً وأستعين على ذلك بكل ذي رأى من أهلي، فلما قيل‏:‏ إن رسول الله صلى الله عليه وسلم قد أظل قادماً زاح عني الباطل حتى عرفت أني لم أنج منه بشيء أبداً، فأجمعت صدقه، وأصبح رسول الله صلى الله عليه وسلم قادماً، وكان إذا قدم من سفر بدأ بالمسجد فركع فيه ركعتين ثم جلس للناس، فلما فعل فعل ذلك جاءه المخلفون يعتذرون إليه ويحلفون له، وكانوا بضعا وثمانين رجلاً فقبل منهم علانيتهم وبايعهم واستغفر لهم ووكل سرائرهم إلى الله تعالى حتى جئت‏.‏ فلما سلمت تبسم تبسم المغضب ثم قال‏:‏ تعال، فجئت أمشي حتى جلست بين يديه، فقال لي‏:‏ ما خلفك‏؟‏ ألم تكن قد ابتعت ظهرك‏!‏ قال قلت‏:‏ يارسول الله إني والله لو جلست عند غيرك من أهل الدنيا لرأيت أني سأخرج من سخطه بعذر، لقد أعطيت جدلاً، ولكنني والله لقد علمت لئن حدثتك اليوم حديث كذب ترضي به ليوشكن الله يسخطك علي، وإن حدثتك حديث صدق تجد علي فيه إني لأرجو فيه عقبى الله عز وجل، والله ما كان لي من عذر، والله ما كنت قط أقوى ولا أيسر مني حين تخلفت عنك‏.‏ قال‏:‏ فقال رسول الله صلى الله عليه وسلم ‏\"‏ أما هذا فقد صدق، فقم حتى يقضي الله فيك‏\"‏ وسار رجال من بني سلمة فاتبعوني، فقالوا لي‏:‏ والله ما علمناك أذنبت ذنبا قبل هذا، لقد عجزت في أن لا يكون اعتذرت إلى رسول الله صلى الله عليه وسلم بما اعتذر إليه المخلفون فقد كان كافيك ذنبك استغفار رسول الله صلى الله عليه وسلم لك‏.‏ قال‏:‏ فوالله ما زالوا يؤنبونني حتى أردت أن أرجع إلى رسول الله صلى الله عليه وسلم فأكذب نفسي، ثم قلت لهم‏:‏ هل لقي هذا معي من أحد‏؟‏ قالوا‏:‏ نعم لقيه معك رجلان قالا مثل ما قلت، وقيل لهما مثل ما قيل لك، قال قلت‏:‏ من هما‏؟‏ قالوا‏:‏ مرارة بن الربيع العمري، وهلال بن أمية الواقفي‏؟‏ قال‏:‏ فذكروا لي رجلين صالحين قد شهدا بدراً فيهما أسوة‏.‏ قال‏:‏ فمضيت حين ذكروهما لي‏.‏ ونهى رسول صلى الله عليه وسلم عن كلامنا أيها الثلاثة من بين من تخلف عنه، قال‏:‏ فاجتنبنا الناس- أو قال‏:‏ تغيروا لنا- حتى تنكرت لي في نفس الأرض، فما هي بالأرض التي أعرف، فلبثنا على ذلك خمسين ليلة‏.‏ فأما صاحباي فاستكانا وقعدا في بيوتهما يبكيان، وأما أنا فكنت أشب القوم وأجلدهم، فكنت أخرج فأشهد الصلاة مع المسلمين، وأطوف في الأسواق ولا يكلمني أحد، وآتي رسول الله صلى الله عليه وسلم فأسلم عليه، وهو في مجلسه بعد الصلاة، فأقول في نفسي ‏:‏ هل حرك شفتيه برد السلام أم ‏؟‏ ثم أصلي قريباً منه وأسارقه النظر، فإذا أقبلت على صلاتي نظر إلي، وإذا التفت نحوه أعرض عني، حتى إذا طال ذلك علي من جفوة المسلمين مشيت حتى تسورت جدار حائط أبي قتادة وهو ابن عمي وأحب الناس إلي، فسلمت عليه فوالله ما ردّ علي السلام، فقلت له‏:‏ يا أبا قتادة أنشدك بالله هل تعلمني أُحب الله ورسوله صلى الله عليه وسلم ‏؟‏ فسكت، فعدت فناشدته فسكت، فعدت فناشدته فقال‏:‏ الله ورسوله أعلم‏.‏ ففاضت عيناي، وتوليت حتى تسورت الجدار، فبينما أنا أمشى في سوق المدينة إذا نبطى من نبط أهل الشام ممن قدم بالطعام ببيعه بالمدينة يقول‏:‏ من يدل على كعب بن مالك‏؟‏ فطفق الناس يشيرون له إلي حتى جاءنى فدفع إلي كتاب من ملك غسان، وكنت كاتباً‏.‏ فقرأته فإذا فيه‏:‏ أما بعد فإنه قد بلغنا أن صاحبك قد جفاك، ولم يجعلك الله بدار هوان ولا مضيعة، فالحق بنا نواسك، فقلت حين قرأتها، وهذه أيضاً من البلاء فتيممت بها التنور فسجرتها، حتى إذا مضت أربعون من الخمسين واستلبث الوحى إذا رسول رسول الله صلى الله عليه وسلم يأتينى، فقال‏:‏ إن رسول الله صلى الله عليه وسلم يأمرك أن تعتزل امرأتك، فقلت‏:‏ أطلقها، أم ماذا أفعل‏؟‏ قال‏:‏ لا، بل اعتزلها فلا تقربنها، وأرسل إلى صاحبي بمثل ذلك‏.‏ فقلت لامرأتي‏:‏ ألحقي بأهلك فكوني عندهم حتى يقضي الله في هذا الأمر، فجاءت امرأة هلال بن أمية رسول الله صلى الله عليه وسلم فقالت له ‏:‏ يا رسول الله إن هلال بن أمية شيخ ضائع ليس له خادم، فهل تكره أن أخدمه‏؟‏ قال ‏:‏ لا، ولكن لا يقربنك‏.‏ فقالت‏:‏ إنه والله ما به من حركة إلى شيء، ووالله ما زال يبكي منذ كان من أمره ما كان إلى يومه هذا‏.‏ فقال لي بعض أهلي‏:‏ لو استأذنت رسول الله صلى الله عليه وسلم في امرأتك، فقد أذن لامرأة هلال بن أمية أن تخدمه‏؟‏ فقلت‏:‏ لا أستأذن فيها رسول الله صلى الله عليه وسلم، وما يدريني ماذا يقول رسول الله صلى الله عليه وسلم، إذا استأذنته فيها وأنا رجل شاب‏!‏ فلبثت بذلك عشر ليالٍ، فكمل لنا خمسون ليلة من حين نهى عن كلامنا‏.‏ ثم صليت صلاة الفجر صباح خمسين ليلة على ظهر بيت من بيوتنا، فبينما أنا جالس على الحال التى ذكر الله تعالى منا، قد ضافت علي نفسي وضاقت علي الأرض بما رحبت، سمعت صوت صارخ أوفى على سلع يقول بأعلى صوته‏:‏ يا كعب بن مالك أبشر فخررت ساجداً، وعرفت أنه قد جاء فرج‏.‏ فآذن رسول الله صلى الله عليه وسلم الناس بتوبة الله عز وجل علينا حين صلى صلاة الفجر فذهب الناس يبشروننا، فذهب قبل صاحبي مبشرون، وركض رجل إلي فرساً وسعى ساع من أسلم قبلي وأوفى على الجبل، فكان الصوت أسرع من الفرس، فلما جاءني الذى سمعت صوته يبشرني نزعت له ثوبي فكسوتهما إياه ببشراه، والله ما أملك غيرهما يومئذ، واستعرت ثوبين فلبستهما وانطلقت أتأمم رسول الله صلى الله عليه وسلم يتلقانى الناس فوجاً فوجاً يهنئوني بالتوبة ويقولون لي‏:‏ لتهنك توبة الله عليك، حتى دخلت المسجد فإذا رسول الله صلى الله عليه وسلم جالس حوله الناس، فقام طلحة بن عبيد الله رضي الله عنه يهرول حتى صافحني وهنأني، والله ما قام رجل من المهاجرين غيره، فكان كعب لا ينساها لطلحة‏.‏ قال كعب‏:‏ فلما سلمت على رسول الله صلى الله عليه وسلم قال‏:‏ وهو يبرق وجهه من السرور ‏:‏ أبشر بخير يوم مرّ عليك مذ ولدتك أمك، فقلت‏:‏ أمن عندك يا رسول الله أم من عند الله‏؟‏ قال ‏:‏ لا ، بل من عند الله عز وجل، وكان رسول الله صلى الله عليه وسلم إذا سر استنار وجهه حتى كأن وجهه قطعة قمر، وكنا نعرف ذلك منه، فلما جلست بين يديه قلت‏:‏ يا رسول الله إن من توبتي أن أنخلع من مالي صدقة‎ إلى الله وإلى رسوله‏.‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ أمسك عليك بعض مالك فهو خير لك، فقلت‏:‏ إني أمسك سهمي الذى بخيبر‏.‏ وقلت‏:‏ يا رسول الله إن الله تعالى إنما أنجاني بالصدق، وإن من توبتي أن لا أحدثَ إلا صدقاً ما بقيت ، فو الله ما علمت أحداً من المسلمين أبلاه الله في صدق الحديث منذ ذكرت ذلك لرسول الله صلى الله عليه وسلم أحسن مما أبلاني الله تعالى ، والله ما تعمدت كذبة منذ قلت ذلك لرسول الله صلى الله عليه وسلم إلى يومي هذا، وإني لأرجو أن يحفظني الله تعالى فيما بقي، قال‏:‏ فأنزل الله تعالى‏:‏ ‏{‏لقد تاب الله على النبي والمهاجرين والأنصار الذين اتبعوه في ساعة العسرة‏)‏ حتى بلغ‏:‏ ‏{‏إنه بهم رؤوف رحيم ‏.‏ وعلى الثلاثة الذين خلفوا حتى إذا ضاقت عليهم الأرض بما رحبت‏}‏ حتى بلغ ‏:‏ ‏{‏اتقوا الله وكونوا مع الصادقين‏}‏ ‏(‏‏(‏التوبة 117، 119‏)‏‏)‏ قال كعب ‏:‏ والله ما أنعم الله علي من نعمة قط بعد إذ هداني الله للإسلام أعظم في نفسي من صدقي رسول الله صلى الله عليه وسلم أن لا أكون كذبته، فأهلك كما هلك الذين كذبوا، إن الله تعالى قال للذين كذبوا حين أنزل الوحي شر ما قال لأحد، فقال الله تعالى ‏:‏ ‏{‏سيحلفون بالله لكم إذا انقلبتم إليهم لتعرضوا عنهم فأعرضوا عنهم إنهم رجس ومأواهم جهنم جزاء بما كانوا يكسبون يحلفون لكم لترضوا عنهم فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفاسقين‏}‏ ‏(‏‏(‏التوبة‏:‏ 95،96‏)‏‏)‏ ‏.‏ قال كعب ‏:‏ كنا خلفنا أيها الثلاثة عن أمر أولئك الذين قبل منهم رسول الله صلى الله عليه وسلم حين حلفوا له ، فبايعهم واستغفر لهم، وأرجأ رسول الله صلى الله عليه وسلم أمرنا حتى قضى الله تعالى فيه بذلك، قال الله تعالى ‏:‏ ‏{‏وعلى الثلاثة الذين خلفوا‏}‏ وليس الذي ذكر مما خلفنا تخلفنا عن الغزو، وإنما هو تخليفه إيانا وإرجاؤه أمرنا عمن حلف له واعتذر إليه فقبل منه‏.‏ متفق عليه‏.‏ وفى رواية ‏\"‏أن النبي صلى الله عليه وسلم خرج في غزوة تبوك يوم الخميس، وكان يحب أن يخرج يوم الخميس‏\"‏ وفى رواية‏:‏ ‏\"‏وكان لا يقدم من سفر إلا نهاراً في الضحى، فإذا قدم بدأ بالمسجد فصلى فيه ركعتين ثم جلس فيه‏\"‏ ‏.‏"},{"id":"riyad:1239","bookId":"riyad","type":"hadith","num":1239,"kitab":"كتاب المقدمات","isnad":"وعن أبي نجيد- ضم النون وفتح الجيم - عمران بن الحصين الخزاعى رضي الله عنهما أن امرأة من جهينة أتت رسول الله صلى الله عليه وسلم وهى حبلى من الزنى، فقالت‏:‏ يا رسول الله أصبت حداً فأقمه علي، فدعا نبي الله صلى الله عليه وسلم وليها فقال‏:‏ أحسن إليها، فإذا وضعت فأتني، ففعل فأمر بها نبي الله صلى الله عليه وسلم، فشدت عليها ثيابها، ثم أمر بها فرجمت، ثم صلى الله عليه وآله وسلم عليها‏.‏ فقال له عمر‏:‏ تصلى عليها يا رسول الله وقد زنت، قال‏:‏ لقد تابت توبة لو قمست بين سبعين من أهل المدينة لوستعتهم، وهل وجدت أفضل من أن جادت بنفسها لله عز وجل ‏؟‏‏!‏ ‏","matn":"\"‏ رواه مسلم‏.‏"},{"id":"riyad:1240","bookId":"riyad","type":"hadith","num":1240,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لو أن لابن آدم وادياً من ذهب أحب أن يكون له واديان، ولن يملأ فاه إلا التراب، ويتوب الله على من تاب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1241","bookId":"riyad","type":"hadith","num":1241,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يضحك الله سبحانه وتعالى إلى رجلين يقتل أحدهما الآخر يدخلان الجنة، يقاتل هذا في سبيل الله فيقتل، ثم يتوب الله على القاتل فيسلم فيستشهد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1242","bookId":"riyad","type":"hadith","num":1242,"kitab":"كتاب المقدمات","isnad":"وعن أبي مالك الحارث بن عاصم الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن -أو تملأ- ما بين السماوات والأرض، والصلاة نور، والصدقة برهان، والصبر ضياء، والقرآن حجة لك أو عليك‏.‏ كل الناس يغدو، فبائع نفسه فمعتقها، أو موبقها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1243","bookId":"riyad","type":"hadith","num":1243,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد سعد بن مالك بن سنان الخدري رضي الله عنهما‏:‏ ‏","matn":"\"‏أن ناساً من الأنصار سألوا رسول الله صلى الله عليه وسلم فأعطاهم، ثم سألوه فأعطاهم ، حتى نفد ما عنده، فقال لهم حين أنفق كل شيء بيده ‏:‏ ‏\"‏ما يكن عندي من خير فلن أدخره عنكم ، ومن يستعفف يعفه الله، ومن يستغن يغنه الله، ومن يتصبر يصبره الله‏.‏ وما أعطي أحد عطاءً خيراً وأوسع من الصبر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1244","bookId":"riyad","type":"hadith","num":1244,"kitab":"كتاب المقدمات","isnad":"وعن أبي يحيى صهيب بن سنان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏عجبا لأمر المؤمن إن أمره كله له خير، وليس ذلك لأحد إلا للمؤمن ‏:‏ إن أصابته سراء شكر فكان خيراً له، وإن أصابته ضراء صبر فكان خيراً له‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1245","bookId":"riyad","type":"hadith","num":1245,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ لما ثقل النبي صلى الله عليه وسلم جعل يتغشاه الكرب فقالت فاطمة رضي الله عنها‏:‏ واكرب أبتاه‏.‏ فقال ‏:‏ ‏","matn":"\"‏ليس على أبيك كرب بعد اليوم‏\"‏ فلما مات قالت ‏:‏ يا أبتاه أجاب رباً دعاه، يا أبتاه جنة الفردوس مأواه، يا أبتاه إلى جبريل ننعاه، فلما دفن قالت ‏:‏ فاطمة رضي الله عنها‏:‏ أطابت أنفسكم أن تحثوا على رسول الله صلى الله عليه وسلم التراب‏؟‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1246","bookId":"riyad","type":"hadith","num":1246,"kitab":"كتاب المقدمات","isnad":"وعن أبي زيد أسامة بن زيد بن حارثة مولى رسول الله صلى الله عليه وسلم وحبه وابن حبه، رضي الله عنهما، قال‏:‏ أرسلت بنت النبي صلى الله عليه وسلم ‏:‏ إن ابني قد احتضر فاشهدنا، فأرسل يقرئ السلام ويقول‏:‏ ‏","matn":"\"‏إن لله ما أخذ، وله ما أعطى، وكل شيء عنده بأجل مسمى، فلتصبر ولتحتسب‏\"‏ فأرسلت إليه تقسم عليه ليأتينها‏.‏ فقام ومعه سعد بن عبادة، ومعاذ بن جبل، وأبي بن كعب، وزيد بن ثابت، ورجال رضي الله عنهم، فرفع إلى رسول الله صلى الله عليه وسلم الصبي فأقعده في حجره ونفسه تقعقع، ففاضت عيناه، فقال سعد‏:‏ يا رسول الله ماهذا‏؟‏ فقال‏:‏ ‏\"‏هذه رحمة جعلها الله تعالى في قلوب عباده‏\"‏ وفى رواية ‏:‏ ‏\"‏في قلوب من شاء من عباده وإنما يرحم الله من عباده الرحماء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1247","bookId":"riyad","type":"hadith","num":1247,"kitab":"كتاب المقدمات","isnad":"وعن صهيب رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ كان ملك فيمن كان قبلكم، وكان له ساحرٌ، فلما كبر قال للملك ‏:‏ إني قد كبرت فابعث إلى غلاماً أعلمه السحر؛ فبعث إليه غلاماً يعلمه، وكان في طريقه إذا سلك راهبٌ، فقعد إليه وسمع كلامه فأعجبه، وكان إذا أتى الساحر مر بالراهب وقعد إليه، فإذا أتى الساحر ضربه، فشكا ذلك إلى الراهب فقال‏:‏ إذا خشيت الساحر فقال‏:‏ حبسني أهلي، وإذا خشيت أهلك فقل‏:‏ حبسني الساحر‏.‏ فبينما هو على ذلك إذ أتى على دابةٍ عظيمةٍ قد حبست الناس فقال‏:‏ اليوم أعلم آلساحر أفضل أم الراهب أفضل‏؟‏ فآخذ حجراً فقال‏:‏ اللهم إن كان أمر الراهب أحب إليك من أمر الساحر فاقتل هذه الدابة حتى يمضي الناس، فرماها فقتلها ومضى الناس، فأتى الراهب فأخبره‏.‏ فقال له الراهب‏:‏ أي بني أنت اليوم أفضل مني، قد بلغ أمرك ما أرى، وإنك ستبتلى، فإن ابتليت فلا تدل علي؛ وكان الغلام يبرئ الأكمه والأبرص، ويداوي الناس من سائر الأدواء‏.‏ فسمع جليس للملك كان قد عمي، فأتاه بهدايا كثيرةٍ فقال‏:‏ ما هاهُنا لك أجمع إن أنت شفيتنى، فقال‏:‏ إني لا أشفي أحداً إنما يشفى الله تعالى، فإن آمنت بالله دعوت الله فشفاك، فآمن بالله تعالى فشفاه الله تعالى، فأتى الملك فجلس إليه كما كان يجلس فقال له الملك‏:‏ من ردّ عليك بصرك‏؟‏ فقال‏:‏ ربي قال‏:‏ ولك رب غيري ‏؟‏‏(‏ قال‏:‏ ربي وربك الله، فأخذه فلم يزل يعذبه حتى دل على الغلام، فجئ بالغلام فقال له الملك‏:‏ أى بني قد بلغ من سحرك ما تبرئ الأكمه والأبرص وتفعل وتفعل فقال‏:‏ إني لا أشفي أحداً، إنما يشفي الله تعالى، فأخذه فلم يزل يعذبه حتى دل على الراهب؛ فجيء بالراهب فقيل له‏:‏ ارجع عن دينك، فأبى ، فدعا بالمنشار فوضع المنشار في مفرق رأسه، فشقه حتى وقع شقاه، ثم جيء بجليس الملك فقيل له‏:‏ ارجع عن دينك فأبى، فوضع المنشار في مفرق رأسه، فشقه به حتى وقع شقاه، ثم جيء بالغلام فقيل له ارجع عن دينك فأبى، فدفعه إلى نفر من أصحابه فقال‏:‏ اذهبوا به إلى جبل كذا وكذا فاصعدوا به الجبل فقال‏:‏ اللهم اكفنيهم بما شئت، فرجف بهم الجبل فسقطوا، وجاء يمشي إلى الملك، فقال له الملك‏:‏ ما فعل أصحابك‏؟‏ فقال‏:‏ كفانيهم الله تعالى، فدفعه إلى نفر من أصحابه فقال ‏:‏ اذهبوا به فاحملوه في قرقور وتوسطوا به البحر، فإن رجع عن دينه وإلا فاقذفوه، فذهبوا به فقال‏:‏ اللهم اكفنيهم بما شئت، فانكفأت بهم السفينة فغرقوا، وجاء يمشي إلى الملك‏.‏ فقال له الملك ‏:‏ ما فعل أصحابك‏؟‏ فقال‏:‏ كفانيهم الله تعالى‏.‏ فقال الملك إنك لست بقاتلي حتى تفعل ما آمرك به‏.‏ قال ‏:‏ ما هو‏؟‏ قال ‏:‏ تجمع الناس في صعيد واحد، وتصلبني على جذع ، ثم خذ سهماً من كنانتي، ثم ضع السهم في كبد القوس ثم قل‏:‏ بسم الله رب الغلام ثم ارمني، فإنك إن فعلت ذلك قتلتني ‏.‏ فجمع الناس في صعيد واحد، وصلبه على جذع، ثم أخذ سهما من كنانته، ثم وضع السهم في كبد القوس، ثم قال‏:‏ بسم الله رب الغلام، ثم رماه فوقع السهم في صدغه، فوضع يده في صدغه فمات‏.‏ فقال الناس آمنا برب الغلام، فأتى الملك فقيل له‏:‏ أرأيت ما كنت تحذر قد والله نزل بك حذرك‏.‏ قد آمن الناس‏.‏ فأمر بالأخدود بأفواه السكك فخدت وأضرم فيها النيران وقال‏:‏ من لم يرجع عن دينه فأقحموه فيها أو قيل له ‏:‏ اقتحم ، ففعلوا حتى جاءت امرأة ومعها صبى لها، فتقاعست ان تقع فيها، فقال لها الغلام‏:‏ يا أماه اصبري فإنك على الحق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1248","bookId":"riyad","type":"hadith","num":1248,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ مر النبي صلى الله عليه وسلم بامرأة تبكي عند قبر فقال ‏:‏ ‏","matn":"\"‏اتقي الله واصبري‏\"‏ فقالت ‏:‏ إليك عني ، فإنك لم تصب بمصيبتي ‍‍‍‏(‏ ولم تعرفه، فقيل لها ‏:‏ إنه النبي صلى الله عليه وسلم ، فأتت باب النبي صلى الله عليه وسلم، فلم تجد عنده بوابين، فقالت‏:‏ لم أعرفك، فقال‏:‏ ‏\"‏إنما الصبر عند الصدمة الأولى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1249","bookId":"riyad","type":"hadith","num":1249,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال ‏:‏ ‏","matn":"\"‏ يقول الله تعالى ‏:‏ ما لعبدي المؤمن عندي جزاء إذا قبضت صفيه من أهل الدنيا ثم احتسبه إلا الجنة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1250","bookId":"riyad","type":"hadith","num":1250,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها أنها سألت رسول الله صلى الله عليه وسلم عن الطاعون، فأخبرها أنه كان عذاباً يبعثه الله تعالى على من يشاء، فجعله الله تعالى رحمة للمؤمنين، فليس من عبد يقع في الطاعون فيمكث في بلده صابراً محتسباً يعلم أنه لا يصيبه إلا ما كتب الله له إلا كان له مثل أجر الشهيد‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1251","bookId":"riyad","type":"hadith","num":1251,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول ‏:‏ ‏","matn":"\"‏إن لله عزوجل قال‏:‏ إذا ابتليت عبدي بحبيبتيه فصبر عوضته منهما الجنة‏\"‏ (‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1252","bookId":"riyad","type":"hadith","num":1252,"kitab":"كتاب المقدمات","isnad":"وعن عطاء بن أبي رباح قال‏:‏ قال لي ابن عباس رضي الله عنهما‏:‏ ألا أريك امرأة من أهل الجنة ‏","matn":"\"‏ فقلت‏:‏ بلى، قال‏:‏ هذه المرأة السوداء أتتت النبي صلى الله عليه وسلم فقالت ‏:‏ إني أصرع، و إني أتكشف، فادع الله تعالى لي قال‏:‏ ‏\"‏إن شئت صبرت ولك الجنة، وإن شئت دعوت الله تعالى أن يعافيك‏\"‏ فقالت‏:‏ أصبر، فقالت‏:‏ إني أتكشف ، فادع الله أن لا أتشكف ، فدعا لها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1253","bookId":"riyad","type":"hadith","num":1253,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه قال‏:‏ كأني انظر إلى رسول الله صلى الله عليه وسلم يحكي نبياً من الأنبياء، صلوات الله وسلامه عليهم، ضربه قومه فأدموه وهو يمسح الدم عن وجهه، يقول ‏:‏ ‏","matn":"\"‏اللهم اغفر لقومى فإنهم لا يعلمون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1254","bookId":"riyad","type":"hadith","num":1254,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد وأبي هريرة رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما يصيب المسلم من نصب ولا وصب ولا هم ولا حزن ولا أذى ولا غم، حتى الشوكة يشاكها إلا كفر الله بها من خطاياه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ '‏و‏ ‏الوصب‏ ‏':‏ المرض .‏"},{"id":"riyad:1255","bookId":"riyad","type":"hadith","num":1255,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ دخلت على النبي صلى الله عليه وسلم وهو يوعك فقلت‏:‏ يارسول الله إنك توعك وعكاً شديداً قال‏:‏ ‏","matn":"\"‏أجل إني أوعك كما يوعك رجلان منكم‏\"‏ قلت‏:‏ ذلك أن لك أجرين ‏؟‏ قال‏:‏ ‏\"‏أجل ذلك كذلك ما من مسلم يصيبه أذى؛ شوكة فما فوقها إلا كفر الله بها سيئاته ، وحطت عنه ذنوبه كما تحط الشجرة ورقها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1256","bookId":"riyad","type":"hadith","num":1256,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ من يرد الله به خيراً يصب منه‏\"‏ ‏:‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1257","bookId":"riyad","type":"hadith","num":1257,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لا يتمنين أحدكم الموت لضر أصابه، فإن كان لابد فاعلاً فليقل‏:‏ اللهم أحيني ما كانت الحياة خيراً لي وتوفني إذا كانت الوفاة خيراً لي‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1258","bookId":"riyad","type":"hadith","num":1258,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله خباب بن الأرت رضي الله عنه قال‏:‏ شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد بردة له في ظل الكعبة، فقلنا ‏:‏ ألا تستنصر لنا ألا تدعو لنا‏؟‏ فقال‏:‏ قد كان من قبلكم يؤخذ الرجل فيحفر له في الأرض فيجعل فيها ثم يؤتى بالمنشار فيوضع على رأسه فيجعل نصفين، ويمشط بأمشاط من الحديد ما دون لحمه وعظمه، ما يصده ذلك عن دينه، والله ليتمن الله هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله والذئب على غنمه، ولكنكم تستعجلون‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1259","bookId":"riyad","type":"hadith","num":1259,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه قال ‏:‏ لما كان يوم حنين آثر رسول الله صلى الله عليه وسلم ناساً في القسمة، فأعطى الأقرع بن حابس مائة من الإبل، وأعطى عيينة بن حصن مثل ذلك، وأعطى ناساً من أشراف العرب وآثرهم يومئذ في القسمة‏.‏ فقال رجل‏:‏ والله إن هذه قسمة ما عدل فيها، وما أريد فيها وجه الله، فقلت ‏:‏ والله لأخبرن رسول الله صلى الله عليه وسلم ، فأتيته فأخبرته بما قال‏:‏ فتغير وجههه حتى كان كالصرف ‏.‏ ثم قال ‏","matn":"\"‏ فمن يعدل إذا لم يعدل الله ورسوله‏؟‏ ثم قال‏:‏ يرحم الله موسى قد أوذي بأكثر من هذا فصبر‏\"‏‏.‏ فقلت‏:‏ لا جرم لا أرفع إليه بعدها حديثاً‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1260","bookId":"riyad","type":"hadith","num":1260,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏إذا أراد الله بعبده خيراً عجل له العقوبة في الدنيا، وإذا أراد الله بعبده الشر أمسك عنه بذنبه حتى يوافي به يوم القيامة‏\"‏‏.‏ وقال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏إن عظم الجزاء مع عظم البلاء، وإن الله تعالى إذا أحب قوماً ابتلاهم، فمن رضي فله الرضى، ومن سخط فله السخط‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1261","bookId":"riyad","type":"hadith","num":1261,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ كان ابن لأبي طلحة رضي الله عنه يشتكي، فخرج أبو طلحة، فقبض الصبي، فلما رجع أبو طلحة قال‏:‏ ما فعل ابني‏؟‏ قالت أم سليم وهى أم الصبي ‏:‏ هو أسكن ما كان، فقربت إليه العشاء فتعشى، ثم أصاب منها، فلما فرغ قالت‏:‏ واروا الصبي، فلما أصبح أبو طلحة أتى رسول الله صلى الله عليه وسلم فأخبره، فقال‏:‏ ‏","matn":"\"‏أعرستم الليلة ‏؟‏‏\"‏ قال‏:‏ نعم ، قال‏:‏ ‏\"‏اللهم بارك لهما، فولدت غلاماً، فقال لي أبو طلحة‏:‏ احمله حتى تأتى به النبي صلى الله عليه وسلم، وبعث معه بتمرات، فقال‏:‏ ‏\"‏أمعه شيء‏؟‏‏\"‏ قال‏:‏ نعم، تمرات فأخذها النبي صلى الله عليه وسلم فمضغها ، ثم أخذها من فيه فجعلها في فيّ الصبي ، ثم حنكه وسماه عبد الله‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفى رواية لمسلم‏:‏ مات ابن لأبي طلحة بن أم سليم ، فقالت لأهلها لا تحدثوا أبا طلحة بابنه حتى أكون أنا أحدثه، فجاء فقربت إليه عشاءً فأكل وشرب، ثم تصنعت له أحسن ما كانت تصنع قبل ذلك، فوقع بها، فلما أن رأت أنه قد شبع وأصاب منها قالت‏:‏ يا أبا طلحة، أرأيت لو أن قوماً أعاروا عاريتهم أهل بيت فطلبوا عاريتهم، ألهم أن يمنعوهم‏؟‏ قال‏:‏ لا، فقالت ‏:‏ فاحتسب ابنك‏.‏ قال‏:‏ فغضب، ثم قال‏:‏ تركتني حتى إذا تلطخت أخبرتني بابني‏؟‏‏!‏ فانطلق حتى أتى رسول الله صلى الله عليه وسلم فأخبره بما كان ، فقال رسول الله صلى الله عليه وسلم‏.‏ ‏\"‏بارك الله في ليلتكما‏\"‏ قال‏:‏ فحملت، قال وكان رسول الله صلى الله عليه وسلم في سفر وهي معه، وكان رسول الله صلى الله عليه وسلم إذا أتى المدينة من سفر لا يطرقها طروقاً فدنوا من المدينة، فضربها المخاض، فاحتبس عليها أبو طلحة، وانطلق رسول الله صلى الله عليه وسلم قال‏:‏ يقول أبو طلحة‏:‏ إنك لتعلم يارب أنه يعجبني أن أخرج مع رسول الله صلى الله عليه وسلم إذا خرج، وأدخل معه إذا دخل، وقد احتبست بما ترى، تقول أم سليم‏:‏ يا أبا طلحة ما أجد الذى كنت أجد، انطلق، فانطلقنا، وضربها المخاض حين قدما فولدت غلاماً‏.‏ فقالت لي أمي ‏:‏ يا أنس لا يرضعه أحد حتى تغدو به على رسول الله صلى الله عليه وسلم، فلما أصبح احتملته فانطلقت به إلى رسول الله صلى الله عليه وسلم‏.‏ وذكر تمام الحديث‏.‏"},{"id":"riyad:1262","bookId":"riyad","type":"hadith","num":1262,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس الشديد بالصرعة، إنما الشديد الذى يملك نفسه عند الغضب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1263","bookId":"riyad","type":"hadith","num":1263,"kitab":"كتاب المقدمات","isnad":"وعن سليمان بن صرد رضي الله عنه قال‏:‏ كنت جالساً مع النبي صلى الله عليه وسلم، ورجلان يستبان، وأحدهما قد احمر وجهه، وانتفخت أوداجه‏.‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ إني لأعلم كلمة لو قالها لذهب عنه ما يجد، لو قال‏:‏ أعوذ بالله من الشيطان الرجيم ذهب منه ما يجد‏\"‏‏.‏ فقال له‏:‏ إن النبي صلى الله عليه وسلم قال‏:‏ ‏\"‏ تعوذ بالله من الشيطان الرجيم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1264","bookId":"riyad","type":"hadith","num":1264,"kitab":"كتاب المقدمات","isnad":"وعن معاذ بن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من كظم غيظاً ، وهو قادر على أن ينفذه، دعاه الله سبحانه وتعالى على رؤوس الخلائق يوم القيامة حتى يخيره من الحور العين ما شاء‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1265","bookId":"riyad","type":"hadith","num":1265,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه ، أن رجلاً قال للنبي صلى الله عليه وسلم‏:‏ أوصني، قال‏:‏ ‏","matn":"\"‏لا تغضب‏\"‏ فردد مراراً، قال‏:‏ ‏\"‏ لاتغضب‏\"‏ رواه البخاري‏.‏"},{"id":"riyad:1266","bookId":"riyad","type":"hadith","num":1266,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ ما يزال البلاء بالمؤمن والمؤمنة في نفسه وولده ة وماله حتى يلقى الله تعالى وما عليه خطيئة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏ ‏.‏"},{"id":"riyad:1267","bookId":"riyad","type":"hadith","num":1267,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال‏:‏ قدم عيينة بن حصن فنزل على ابن أخيه الحر بن قيس، وكان من النفر الذين يدنيهم عمر رضي الله عنه، وكان القراء أصحاب مجلس عمر رضي الله عنه ومشاورته كهولاً كانوا أو شباناً، فقال عيينة لابن أخيه ‏:‏ يا ابن أخي لك وجه عند هذا الأمير فاستأذن لي عليه، فاستأذن فأذن عمر‏.‏ فلما دخل قال‏:‏ هِىَ يا ابن الخطاب، فوالله ما تعطينا الجزل ولا تحكم فينا بالعدل، فغضب عمر رضي الله عنه حتى همّ أن يوقع به، فقال له الحر‏:‏ يا أمير المؤمنين إن الله تعالى قال لنبيه صلى الله عليه وسلم‏:‏ ‏{‏خذ العفو وأمر بالعرف وأعرض عن الجاهلين‏}‏ ‏(‏‏(‏الأعراف: 199‏)‏‏)‏‏.‏ وإن هذا من الجاهلين، والله ما جاوزها عمر حين تلاها، وكان وقافاً عند كتاب الله تعالى‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ ‏.‏"},{"id":"riyad:1268","bookId":"riyad","type":"hadith","num":1268,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إنها ستكون بعدي أثرة وأمور تنكرونها ‏!‏ قالوا‏:‏ يا رسول الله فما تأمرنا‏؟‏ قال‏:‏ تؤدون الحق الذى عليكم ، وتسألون الله الذى لكم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1269","bookId":"riyad","type":"hadith","num":1269,"kitab":"كتاب المقدمات","isnad":"وعن أبي يحيى أسيد بن حضير رضي الله عنه أن رجلاً من الأنصار قال‏:‏ يا رسول الله ألا تستعملني كما استعملت فلاناً فقال‏:‏ ‏","matn":"\"‏إنكم ستلقون بعدي أثرة، فاصبروا حتى تلقوني على الحوض‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1270","bookId":"riyad","type":"hadith","num":1270,"kitab":"كتاب المقدمات","isnad":"وعن أبي إبراهيم عبد الله بن أبي أوفى رضي الله عنهما أن رسول الله صلى الله عليه وسلم في بعض أيامه التي لقي فيها العدو، انتظر حتى إذا مالت الشمس قام فيهم فقال‏:‏ ‏","matn":"\"‏ يا أيها الناس لا تتمنوا لقاء العدو، واسألوا الله العافية، فإذا لقيتموهم فاصبروا، واعلموا أن الجنة تحت ظلال السيوف‏\"‏ ثم قال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏ اللهم منزل الكتاب ومجري السحاب ، وهازم الأحزاب، اهزمهم وانصرنا عليهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وبالله التوفيق‏.‏"},{"id":"riyad:1271","bookId":"riyad","type":"hadith","num":1271,"kitab":"كتاب المقدمات","isnad":"فالأول عن ابن مسعود رضي الله عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الصدق يهدي إلى البر وإن البر يهدي إلى الجنة، وإن الرجل ليصدق حتى يكتب عند الله صديقاً، وإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار، وإن الرجل ليكذب حتى يكتب عند الله كذاباً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1272","bookId":"riyad","type":"hadith","num":1272,"kitab":"كتاب المقدمات","isnad":"الثانى‏:‏ عن أبي محمد الحسن بن علي بن أبي طالب، رضي الله عنهما ، قال ‏:‏ حفظت من رسول الله، صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏دع ما يريبك إلى ما لا يريبك؛ فإن الصدق طمأنينة، والكذب ريبةٌ‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏ ‏.‏"},{"id":"riyad:1273","bookId":"riyad","type":"hadith","num":1273,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن أبي سفيان صخر بن حرب ، رضي الله عنه، في حديثه الطويل في قصة هرقل، قال هرقل‏:‏ فماذا يأمركم -يعنى النبي صلى الله عليه وسلم- قال أبو سفيان‏:‏ قلت ‏:‏يقول ‏:‏ ‏","matn":"\"‏ اعبدوا الله وحده لا تشركوا به شيئاً، واتركوا ما يقول آباؤكم ، ويأمرنا بالصلاة، والصدق، والعفاف، والصلة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1274","bookId":"riyad","type":"hadith","num":1274,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن أبي ثابت، وقيل أبي سعيد، وقيل أبي الوليد، سهل بن حنيف ، وهو بدري، رضي الله عنه، أن النبي ، صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏من سأل الله، تعالى، الشهادة بصدق بلغه الله منازل الشهداء، وإن مات على فراشه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ ‏.‏"},{"id":"riyad:1275","bookId":"riyad","type":"hadith","num":1275,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن أبي هريرة ، رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏غزا نبي من الأنبياء صلوات الله وسلامه عليهم فقال لقومه‏:‏ لا يتبعني رجل ملك بضع امرأة‏.‏ وهو يريد أن يبني بها ولما يبن بها، ولا أحد بنى بيوتا لم يرفع سقوفها، ولا أحد اشترى غنما أو خلفات وهو ينتظر أولادها‏.‏ فغزا فدنا من القرية صلاة العصر أو قريباً من ذلك، فقال للشمس‏:‏ إنك مأمورة وأنا مأمور، اللهم احبسها علينا، فحبست حتى فتح الله عليه، فجمع الغنائم، فجائت -يعني النار- لتأكلها فلم تطعمها، فقال ‏:‏ إن فيكم غلولاً، فليبايعني من كل قبيلةٍ رجل، فلزقت يد رجل بيده فقال‏:‏ فيكم الغلول، فلتبايعني قبيلتك، فلزقت يد رجلين أو ثلاثة بيده فقال‏:‏ فيكم الغلول‏:‏ فجاؤوا برأس مثل رأس بقرة من الذهب، فوضعها فجاءت النار فأكلتها، فلم تحل الغنائم لأحد قبلنا، ثم أحل الله لنا الغنائم لما رأى ضعفنا وعجزنا فأحلها لنا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1276","bookId":"riyad","type":"hadith","num":1276,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن أبي خالد حكيم بن حزام‏.‏ رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ البيعان بالخيار مالم يتفرقا، فإن صدقاً وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1277","bookId":"riyad","type":"hadith","num":1277,"kitab":"كتاب المقدمات","isnad":"وأما الأحاديث ؛ فالأول‏:‏ عن عمر بن الخطاب، رضي الله عنه ، قال ‏","matn":"\"‏ بينما نحن جلوس عند رسول الله، صلى الله عليه وسلم ذات يوم إذ طلع عينا رجل شديد بياض الثياب ، شديد سواد الشعر، لا يرى عليه أثر السفر، ولا يعرفه منا أحد، حتى جلس إلى النبي ،صلى الله عليه وسلم ، فأسند ركبتيه إلى ركبتيه، ووضع كفيه على فخذيه وقال‏:‏ يا محمد أخبرني عن الإسلام، فقال‏:‏ رسول الله صلى الله عليه وسلم‏:‏ الإسلام أن تشهد أن لا إله إلا الله ، وأن محمداً رسول الله وتقيم الصلاة، وتؤتي الزكاة ، وتصوم رمضان ، وتحج البيت إن استطعت إليه سبيلاً‏.‏ قال صدقت‏.‏ فعجبنا له يسأله ويصدقه‏!‏ قال ‏:‏ فأخبرني عن الإيمان‏.‏ قال أن تؤمن بالله، وملائكته، وكتبه ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره‏.‏ قال صدقت‏.‏ قال فأخبرني عن الإحسان ‏.‏ قال أن تعبد الله كأنك تراه؛ فإن لم تكن تراه فإنه يراك‏.‏ قال‏:‏ فأخبرني عن الساعة‏.‏ قال‏:‏ ما المسؤول عنها بأعلم من السائل‏.‏ قال ‏:‏ فأخبرني عن أماراتها قال‏:‏ أن تلد الأمة ربتها، وأن ترى الحفاة العراة العالة رعاء الشاء يتطالون في البنيان‏.‏ ثم انطلق، فلبثت ملياً، ثم قال‏:‏ يا عمر أتدري من السائل‏؟‏ قلت‏:‏ الله ورسوله أعلم‏.‏ قال‏:‏ فإنه جبريل أتاكم يعلمكم أمر دينكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ ‏.‏"},{"id":"riyad:1278","bookId":"riyad","type":"hadith","num":1278,"kitab":"كتاب المقدمات","isnad":"الثانى‏:‏ عن أبي ذر جندب بن جنادة، وأبي عبد الرحمن معاذ بن جبل، رضي الله عنهما، عن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏ اتق الله حيثما كنت واتبع السيئة الحسنة تمحها، وخالق الناس بخلق حسن‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن ‏)‏‏)‏‏.‏"},{"id":"riyad:1279","bookId":"riyad","type":"hadith","num":1279,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن ابن عباس، رضي الله عنهما، قال‏:‏ ‏","matn":"\"‏ كنت خلف النبي، صلى الله عليه وسلم، يوماً فقال‏:‏ ‏\"‏ يا غلام إني أعلمك كلمات‏:‏ ‏\"‏احفظ الله يحفظك، احفظ الله تجده تجاهك، إذا سألت فاسأل الله ، وإذا استعنت فاستعن بالله، واعلم‏:‏ أن الأمة لو اجتمعت على أن ينفعوك بشيء، لم ينفعوك إلا بشيء قد كتبه الله لك، وإن اجتمعوا على أن يضروك بشيء، لم يضروك بشيء إلا بشيء قد كتبه الله عليك؛ رفعت الأقلام، وجفت الصحف‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن صحيح‏)‏‏)‏ ‏.‏"},{"id":"riyad:1280","bookId":"riyad","type":"hadith","num":1280,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن أنس رضي الله عنه قال‏:‏ ‏","matn":"\"‏إنكم لتعملون أعمالاً هي أدق في أعينكم من الشعر، كنا نعدها على عهد رسول الله صلى الله عليه وسلم من الموبقات‏\"‏ ‏(‏‏(‏رواه البخاري ‏)‏‏)‏ '‏وقال ‏:‏ ‏ ‏الموبقات‏ ‏ المهلكات ‏'.‏"},{"id":"riyad:1281","bookId":"riyad","type":"hadith","num":1281,"kitab":"كتاب المقدمات","isnad":"الخامس ‏:‏ عن أبي هريرة، رضي الله عنه ، عن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏ إن الله تعالى يغار، وغيرة الله ، تعالى، أن يأتي المرء ما حرم الله عليه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1282","bookId":"riyad","type":"hadith","num":1282,"kitab":"كتاب المقدمات","isnad":"السادس ‏:‏ عن أبي هريرة رضي الله عنه أنه سمع النبي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ إن ثلاثة من بنى إسرائيل ‏:‏ أبرص ، وأقرع، وأعمى، أراد الله أن يبتليهم فبعث إليهم ملكاً، فأتى الأبرص فقال‏:‏ أي شيء أحب إليك‏؟‏ قال ‏:‏ لون حسن، وجلد حسن ، ويذهب عني الذى قد قذرني الناس؛ فمسحه فذهب عنه قذره وأعطي لونا حسناً‏.‏ قال‏:‏ فأي المال أحب إليك‏؟‏ قال‏:‏ الإبل-أو قال البقر-شك الرواي- فأعطي ناقة عشراء، فقال‏:‏ بارك الله لك فيها‏.‏ فأتى الأقرع فقال‏:‏ أي شيء أحب إليك‏؟‏ قال‏:‏ شعر حسن، ويذهب عني هذا الذى قذرني الناس ، فمسحه فذهب عنه وأعطي شعراً حسناً‏.‏ قال‏:‏ فأي المال أحب إليك‏؟‏ قال‏:‏ البقر، فأعطي بقرة حاملاً،وقال بارك الله لك فيها‏.‏ فأتي الأعمى فقال‏:‏ أي شيء أحب إليك‏؟‏ قال‏:‏ أن يرد الله إلي بصري فأبصر الناس، فمسحه فرد الله إليه بصره‏.‏ قال‏:‏ فأي المال أحب إليك‏؟‏ قال‏:‏ الغنم، فأعطي شاة والداً‏.‏ فأنتج هذان وولد هذا، فكان لهذا واد من الإبل، ولهذا واد من البقر، ولهذا واد من الغنم‏.‏ ثم إنه أتى الأبرص في صورته وهيئته، فقال له‏:‏ رجل مسكين وابن سبيل قد انقطعت بي الحبال في سفري، فلا بلاغ لي اليوم إلا بالله ثم بك، أسألك بالذي أعطاك اللون الحسن، والجلد الحسن، والمال، بعيراً أتبلغ به في سفري، فقال‏:‏ الحقوق كثيرة‏.‏ فقال ‏:‏ كأني أعرفك، ألم تكن أبرص يقذرك الناس فقيراً، فأعطاك الله ‏؟‏‏!‏ فقال ‏:‏ إنما ورثت هذا المال كابراً عن كابر، فقال‏:‏ إن كنت كاذباً فصيرك الله إلى ما كنت‏.‏ وأتى الأقرع، فقال له مثل ما قال لهذا، ورد عليه مثل ما ردّ هذا، فقال إن كنت كاذبا فصيرك الله إلى ما كنت ‏.‏ وأتى الأعمى في صورته وهيئته، فقال‏:‏ رجل مسكين وابن سبيل انقطعت بي الحبال في سفري، فلا بلاغ لي اليوم إلا بالله ثم بك، أسألك بالذي رد عليك بصرك شاة أتبلغ بها في سفري‏؟‏ فقال‏:‏ قد كنت أعمى فرد الله بصري، فخذ ما شئت ودع ما شئت، فوالله ما أجهدك اليوم بشيء أخذته لله عز وجل فقال‏:‏ أمسك عليك مالك فإنما ابتليتم، فقد رضي الله عنك، وسخط على صاحبيك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1283","bookId":"riyad","type":"hadith","num":1283,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عن أبي يعلى شداد بن أوس رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ الكيس من دان نفسه، وعمل لما بعد الموت ، والعاجز من أتبع نفسه هواها، وتمنى على الله‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1284","bookId":"riyad","type":"hadith","num":1284,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ من حسن إسلام المرء تركه ما لا يعنيه‏\"‏ ‏(‏‏(‏حديث حسن رواه الترمذي وغيره‏)‏‏)‏"},{"id":"riyad:1285","bookId":"riyad","type":"hadith","num":1285,"kitab":"كتاب المقدمات","isnad":"التاسع‏:‏ عن عمر رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يسأل الرجل فيم ضرب امرأته‏\"‏ ‏(‏‏(‏رواه أبو دواد وغيره‏)‏‏)‏ ‏.‏"},{"id":"riyad:1286","bookId":"riyad","type":"hadith","num":1286,"kitab":"كتاب المقدمات","isnad":"وأما الأحاديث فالأول‏:‏ عن أبي هريرة رضي الله عنه قال‏:‏ قيل ‏:‏ يا رسول الله من أكرم الناس‏؟‏ قال‏:‏ ‏","matn":"\"‏أتقاهم‏\"‏‏.‏ فقالوا‏:‏ ليس عن هذا نسألك، قال‏:‏ ‏\"‏ فيوسف نبي الله بن نبي الله بن نبي الله بن خليل الله‏\"‏ قالوا‏:‏ ليس عن هذا نسألك، قال‏:‏ ‏\"‏فعن معادن العرب تسألوني‏؟‏ خيارهم في الجاهلية خيارهم في الإسلام إذا فقهواً ‏:‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1287","bookId":"riyad","type":"hadith","num":1287,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إن الدنيا حلوة خضرة، وإن الله مستخلفكم فيها فينظر كيف تعملون، فاتقوا الدنيا واتقوا النساء؛ فإن أول فتنة بني إسرائيل كانت في النساء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1288","bookId":"riyad","type":"hadith","num":1288,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم كان يقول‏:‏ ‏","matn":"\"‏اللهم إني أسألك الهدى والتقى والعفاف والغنى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1289","bookId":"riyad","type":"hadith","num":1289,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن أبي ظريف عدي بن حاتم الطائي رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من حلف على يمين ثم رأى أتقى لله منها فليأت التقوى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1290","bookId":"riyad","type":"hadith","num":1290,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن أبي أمامة صدي بن عجلان الباهلي رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يخطب في حجة الوداع فقال ‏:‏ اتقوا الله ، وصلوا خمسكم، وصوموا شهركم، وأدوا زكاة أموالكم، وأطيعوا أمراءكم، تدخلوا جنة ربكم‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي، في آخر كتاب الصلاة وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1291","bookId":"riyad","type":"hadith","num":1291,"kitab":"كتاب المقدمات","isnad":"فالأول عن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ عرضت علي الأمم، فرأيت النبي ومعه الرهيط، والنبي ومعه الرجل والرجلان، والنبي وليس معه أحد إذ رفع لي سواد عظيم فظننت أنهم أمتي، فقيل لى ‏:‏ هذا موسى وقومه، ولكن انظر إلى الأفق، فنظرت فإذا سواد عظيم، فقيل لى، انظر إلى الأفق الآخر، فإذا سواد عظيم، فقيل لي‏:‏ هذه أمتك، ومعهم سبعون ألفاً يدخلون الجنة بغير حساب ولا عذاب‏","matn":"\"‏ ثم نهض فدخل منزله، فخاض الناس في أولئك الذين يدخلون الجنة بغير حساب ولا عذاب، فقال بعضهم‏:‏ فلعلهم الذين صحبوا رسول الله صلى الله عليه وسلم ، وقال بعضهم‏:‏ فلعلهم الذين ولدوا في الإسلام، فلم يشركوا بالله شيئاً- وذكروا أشياء- فخرج عليهم رسول الله صلى الله عليه وسلم فقال‏:‏ ‏\"‏ما الذي تخوضون فيه‏؟‏‏\"‏ فأخبروه فقال‏:‏ ‏\"‏هم الذين لا يرقون ، ولا يسترقون ولا يتطيرون، وعلى ربهم يتوكلون‏\"‏ فقام عكاشة بن محصن فقال‏:‏ ادع الله أن يجعلني منهم، فقال‏:‏ ‏\"‏أنت منهم‏\"‏ ثم قام رجل آخر فقال‏:‏ ادع الله أن يجعلني منهم فقال‏:‏ ‏\"‏سبقك بها عكاشة‏\"‏ ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1292","bookId":"riyad","type":"hadith","num":1292,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن ابن عباس رضي الله عنهما أيضاً أن رسول الله صلى الله عليه وسلم كان يقول‏:‏ ‏","matn":"\"‏اللهم لك أسلمت وبك آمنت، وعليك توكلت، وإليك أنبت ، وبك خاصمت‏.‏ اللهم أعوذ بعزتك، لا إله إلا أنت أن تضلني، أنت الحي الذي لا تموت، والجن والإنس يموتون‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏(‏‏(‏وهذا لفظ مسلم، واختصره البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1293","bookId":"riyad","type":"hadith","num":1293,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن ابن عباس رضي الله عنهما أيضاً قال‏:‏ ‏","matn":"\"‏حسبنا الله ونعم الوكيل، قالها إبراهيم صلى الله عليه وسلم حين ألقي في النار، وقالها محمد صلى الله عليه وسلم حين قالوا‏:‏ إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمانا وقالوا‏:‏ حسبنا الله ونعم الوكيل‏:‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1294","bookId":"riyad","type":"hadith","num":1294,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏يدخل الجنة أقوام أفئدتهم مثل أفئدة الطير‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1295","bookId":"riyad","type":"hadith","num":1295,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن جابر رضي الله عنه أنه غزا مع النبي صلى الله عليه وسلم قبل نجد، فلما قفل رسول الله صلى الله عليه وسلم قفل معهم، فأدركتهم القائلة في واد كثير العضاه، فنزل رسول الله صلى الله عليه وسلم، وتفرق الناس يستظلون بالشجر، ونزل رسول الله صلى الله عليه وسلم تحت سمرة، فعلق بها سيفه، ونمنا نومة، فإذا رسول الله صلى الله عليه وسلم يدعونا، وإذا عنده أعرابي فقال‏:‏ ‏","matn":"\"‏إن هذا اختراط علي سيفي وأنا نائم، فاسيقظت وهو في يده صلتا، قال‏:‏ من يمنعك منى‏؟‏ قلت‏:‏ الله-ثلاثا‏\"‏ ولم يعاقبه وجلس‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية ‏:‏ قال جابر‏:‏ كنا مع رسول الله صلى الله عليه وسلم بذات الرقاع‏:‏ فإذا أتينا على شجرة ظليلة تركناها لرسول الله صلى الله عليه وسلم، فجاء رجل من المشركين، وسيف رسول الله صلى الله عليه وسلم معلق بالشجرة، فاخترطه فقال ‏:‏ تخافني‏؟‏ قال‏:‏ ‏ ‏لا‏ ‏ قال ‏:‏ فمن يمنعك مني ‏؟‏ قال‏:‏ ‏ ‏الله‏ ‏‏.‏ وفي رواية أبي بكر الإسماعيلى في صحيحه‏:‏ قال‏:‏ من يمنعك مني‏؟‏ قال ‏:‏ ‏ ‏الله‏ ‏ قال‏:‏ فسقط السيف من يده، فأخذ رسول الله صلى الله عليه وسلم السيف فقال‏:‏ ‏ ‏من يمنعك مني‏؟‏‏ ‏ فقال كن خير آخذ، فقال ‏ ‏تشهد أن لا إله إلا الله ، وأني رسول الله‏؟‏ ‏ ‏ قال‏:‏ لا، ولكني أعاهدك أن لا أقاتلك ولا أكون مع قوم يقاتلونك، فخلى سبيله، فأتى أصحابه فقال‏:‏ جئتكم من عند خير الناس‏.‏"},{"id":"riyad:1296","bookId":"riyad","type":"hadith","num":1296,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن عمر رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول ‏:‏ ‏","matn":"\"‏لو أنكم تتوكلون على الله حق توكله لرزقكم كما يرزق الطير ، تغدو خماصاً وتروح بطاناً‏\"‏ ‏(‏‏(‏رواه الترمذي ، وقال حديث حسن ‏)‏‏)‏‏.‏"},{"id":"riyad:1297","bookId":"riyad","type":"hadith","num":1297,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عن أبي عمارة البراء بن عازب رضي الله عنهما قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ يا فلان إذا أويت إلى فراشك فقل‏:‏ اللهم أسلمت نفسي إليك، ووجهت وجهي إليك‏:‏ وفوضت أمري إليك ، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجى منك إلا إليك ، آمنت بكتابك الذي أنزلت، ونبيك الذي أرسلت؛ فإنك إن مت من ليلتك مت على الفطرة، وإن أصبحت أصبت خيراً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1298","bookId":"riyad","type":"hadith","num":1298,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عن أبي بكر الصديق رضي الله عنه عن عبد الله بن عثمان بن عامر بن عمر بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب القرشي التيمي رضي الله عنه - وهو وأبوه وأمه صحابة، رضي الله عنهم- قال‏:‏ نظرت إلى أقدام المشركين ونحن في الغار وهم على رؤوسنا فقلت يارسول الله لو أن أحدهم نظر تحت قدمية لأبصرنا‏.‏ فقال‏:‏ ‏","matn":"\"‏ ما ظنك يا أبا بكر باثنين الله ثالثهما‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1299","bookId":"riyad","type":"hadith","num":1299,"kitab":"كتاب المقدمات","isnad":"التاسع‏:‏ عن أم المؤمنين أم سلمة، واسمها هند بنت أبي أمية حذيفة المخزومية، رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا خرج من بيته قال‏:‏ ‏","matn":"\"‏بسم الله، توكلت على الله ، اللهم إني أعوذ بك أن أضل أو أضل، أو أذل أو أذل، أو أظلم أو أظلم ، أو أجهل أو يجهل علي‏\"‏ ‏(‏‏(‏حديث صحيح رواه أبو داود، والترمذي وغيرهما بأسانيد صحيحة‏)‏‏)‏ ‏.‏ ‏(‏‏(‏قال الترمذي‏:‏ حديث حسن صحيح، وهذا لفظ أبي داود‏)‏‏)‏‏.‏"},{"id":"riyad:1300","bookId":"riyad","type":"hadith","num":1300,"kitab":"كتاب المقدمات","isnad":"العاشر‏:‏ عن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من قال-يعني إذا خرج من بيته-‏:‏ بسم الله توكلت على الله، ولا حول ولا قوة إلا بالله ، يقال له‏:‏ هديت وكفيت ووقيت، وتنحى عنه الشيطان‏\"‏‏.‏ رواه أبو داود والترمذي، والنسائي وغيرهم‏.‏ وقال الترمذي‏:‏ حديث حسن، زاد أبو داود‏:‏ ‏\"‏فيقول ‏:‏-يعني الشيطان-لشيطان آخر‏:‏ كيف لك برجل قد هدي وكفي ووقيّ ‏؟‏"},{"id":"riyad:1301","bookId":"riyad","type":"hadith","num":1301,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ كان أخوان على عهد النبي صلى الله عليه وسلم، وكان أحدهما يأتي النبي صلى الله عليه وسلم ، والآخر يحترف، فشكا المحترف آخاه للنبي صلى الله عليه وسلم فقال ‏:‏ ‏","matn":"\"‏لعلك ترزق به‏\"‏ ‏(‏‏(‏رواه الترمذي بإسناد صحيح على شرط مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1302","bookId":"riyad","type":"hadith","num":1302,"kitab":"كتاب المقدمات","isnad":"وعن أبي عمرو، وقيل‏:‏ أبي عمرة سفيان بن عبد الله رضي الله عنه قال‏:‏ قلت‏:‏ يا رسول الله قل لي في الإسلام قولاً لا أسأل عنه أحداً غيرك‏.‏ قال‏:‏ ‏","matn":"\"‏قل آمنت بالله‏:‏ ثم استقم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1303","bookId":"riyad","type":"hadith","num":1303,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه ‏:‏ قال‏:‏ قال رسول الله صلى الله عليه وسلم قاربوا وسددوا، واعلموا أنه لن ينجو أحد منكم بعمله‏","matn":"\"‏ قالوا‏:‏ ولا أنت يا رسول الله ‏؟‏ قال‏:‏ ‏\"‏ولا أنا إلا أن يتغمدنى الله برحمة منه وفضل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1304","bookId":"riyad","type":"hadith","num":1304,"kitab":"كتاب المقدمات","isnad":"فالأول‏:‏ عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ بادروا بالأعمال فتناً كقطع الليل المظلم يصبح الرجل مؤمنا ويمسي كافراً ويمسي مؤمنا ويصبح كافراً، يبيع دينه بعرض من الدنيا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1305","bookId":"riyad","type":"hadith","num":1305,"kitab":"كتاب المقدمات","isnad":"الثاني عن أبي سروعة -بكسر السين المهملة وفتحها- عقبة ابن الحارث رضي الله عنه قال‏:‏ صليت وراء النبي صلى الله عليه وسلم بالمدينة العصر، فسلم ثم قام مسرعاً فتخطى رقاب الناس إلى بعض حجر نسائه، ففزع الناس من سرعته، فخرج عليهم، فرأى أنهم قد عجبوا من سرعته، قال ‏","matn":"\"‏ذكرت شيئاً من تبر عندنا فكرهت أن يحبسنى، فأمرت بقسمته‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ وفي رواية للبخاري ‏:‏ ‏ ‏كنت خلفت في البيت تبراً من الصدقة، فكرهت أن أبيته‏ ‏‏.‏ ‏(‏‏(‏التبر‏)‏‏)‏ قطع ذهب أو فضة"},{"id":"riyad:1306","bookId":"riyad","type":"hadith","num":1306,"kitab":"كتاب المقدمات","isnad":"","matn":"الثالث‏:‏ عن جابر رضي الله عنه قال‏:‏ قال رجل للنبي صلى الله عليه وسلم يوم أحد‏: : رَأيتَ إنْ قُتِلتُ فَأَيْنَ أَنَا ؟ قَالَ : « في الجنَّةِ » فَأَلْقَى تَمَرَاتٍ كُنَّ في يَدِهِ ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ . مُتَّفَقٌ عَلَيهِ ."},{"id":"riyad:1307","bookId":"riyad","type":"hadith","num":1307,"kitab":"كتاب المقدمات","isnad":"","matn":"عن أبي هريرة ، قَالَ : جاءَ رَجُلٌ إِلَى النَّبيِّ فَقَالَ : يَا رسولَ الله ، أيُّ الصَّدَقَةِ أعْظَمُ أجْرَاً ؟ قَالَ : « أنْ تَصَدَّقَ وَأنتَ صَحيحٌ شَحيحٌ ، تَخشَى الفَقرَ وتَأمُلُ الغِنَى ، وَلا تُمهِلْ حَتَّى إِذَا بَلَغتِ الحُلقُومَ قُلْتَ لِفُلان كذا ولِفُلانٍ كَذا ، وقَدْ كَانَ لِفُلانٍ » . مُتَّفَقٌ عَلَيهِ ."},{"id":"riyad:1308","bookId":"riyad","type":"hadith","num":1308,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم أخذ سيفاً يوم أحد فقال‏:‏ ‏","matn":"\"‏ من يأخذ مني هذا‏؟‏ فبسطوا أيديهم، كل إنسان منهم يقول‏:‏ أنا أنا‏.‏ قال‏:‏ ‏\"‏فمن يأخذه بحقه‏؟‏‏\"‏ فأحجم القوم، فقال أبو دجانة رضي الله عنه‏:‏ أنا آخذه بحقه، فأخذه ففلق به هام المشركين‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1309","bookId":"riyad","type":"hadith","num":1309,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن الزبير بن عدي قال‏:‏ أتينا أنس بن مالك رضي الله عنه فشكونا إليه ما نلقى من الحجاج‏.‏ فقال‏:‏ ‏","matn":"\"‏اصبروا فإنه لا يأتي زمان إلا والذي بعده شر منه حتى تلقوا ربكم‏\"‏ سمعته من نبيكم صلى الله عليه وسلم‏.‏‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1310","bookId":"riyad","type":"hadith","num":1310,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ بادروا بالأعمال سبعاً‏.‏ هل تنتظرون إلا فقراً منسياً، أو غنى مطغياً، أو مرضاً مفسداً، أو هرماً مفنداً أو موتاً مجهزاً أو الدجال فشر غائب ينتظر، أو الساعة فالساعة أدهى وأمر‏!‏‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1311","bookId":"riyad","type":"hadith","num":1311,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عنه أن رسول الله صلى الله عليه وسلم قال يوم خيبر‏:‏ ‏","matn":"\"‏لأعطين هذه الراية رجلا يحب الله ورسوله، يفتح الله على يديه‏\"‏ قال عمر رضي الله عنه‏:‏ ما أحببت الإمارة إلا يؤمئذ، فتساورت لها رجاء أن أدعى لها، فدعا رسول الله صلى الله عليه وسلم عليّ بن أبي طالب رضي الله عنه فأعطاه إياها وقال‏:‏ ‏\"‏ أمش ولا تلتفت حتى يفتح الله عليك‏\"‏ فسار علي شيئاً، ثم وقف ولم يلتفت، فصرخ‏:‏ يا رسول الله، على ماذا أقاتل الناس‏؟‏ قال‏:‏ ‏\"‏ قاتلهم حتى يشهدوا أن لا إله إلا الله، وأن محمداً رسول الله، فإذا فعلوا ذلك فقد منعوا منك دماءهم وأموالهم إلا بحقها، وحسابهم على الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏:‏ (14)"},{"id":"riyad:1312","bookId":"riyad","type":"hadith","num":1312,"kitab":"كتاب المقدمات","isnad":"فالأول‏:‏ عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله تعالى قال‏:‏ من عادى لي وليا فقد آذنته بالحرب‏.‏ وما تقرب إلي عبدي بشيء أحب إلي مما افترضت عليه، وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه، فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به، ويده التي يبطش بها، ورجله التي يمشي بها، وإن سألني أعطيته؛ ولئن استعاذني لأعيذنه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1313","bookId":"riyad","type":"hadith","num":1313,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن أنس رضي الله عنه عن النبي صلى الله عليه وسلم فيما يرويه عن ربه عز وجل قال‏:‏ ‏","matn":"\"‏ إذا تقرب العبد إلي شبراً تقربت إليه ذراعاً، وإذا تقرب إلي ذراعاً تقربت منه باعاً، وإذا أتاني يمشي أتيته هرولة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1314","bookId":"riyad","type":"hadith","num":1314,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ نعمتان مغبون فيهما كثير من الناس‏:‏ الصحة، والفراغ‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1315","bookId":"riyad","type":"hadith","num":1315,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يقوم من الليل حتى تنفطر قدماه، فقلت له‏:‏ لم تصنع هذا يا رسول الله، وقد غفر الله لك ما تقدم من ذنبك وما تأخر‏؟‏‏!‏ قال‏:‏ ‏","matn":"\"‏ أفلا أحب أن أكون عبداً شكوراً‏؟‏‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ هذا لفظ البخاري، ونحوه في الصحيحين من رواية المغيرة بن شعبة‏)‏‏)‏‏.‏"},{"id":"riyad:1316","bookId":"riyad","type":"hadith","num":1316,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن عائشة رضي الله عنها أنها قالت‏:‏ ‏","matn":"\"‏ كان رسول الله صلى الله عليه وسلم إذا دخل العشر أحيا الليل، وأيقظ أهله، وجد وشد المئزر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1317","bookId":"riyad","type":"hadith","num":1317,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كل خير‏.‏ احرص على ما ينفعك، واستعن بالله ولا تعجز‏.‏ وإن أصابك شيء فلا تقل‏:‏ لو أني فعلت كان كذا وكذا، ولكن قل‏:‏ قدر الله، وما شاء فعل؛ فإن لو تفتح عمل الشيطان‏\"‏ ‏(‏‏(‏ رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1318","bookId":"riyad","type":"hadith","num":1318,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ حجبت النار بالشهوات، وحجبت الجنة بالمكاره‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1319","bookId":"riyad","type":"hadith","num":1319,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عن أبي عبد الله حذيفة بن اليمان، رضي الله عنهما، قال‏:‏ صليت مع النبي صلى الله عليه وسلم ذات ليلة، فافتتح البقرة، فقلت يركع عند المائة، ثم مضى؛ فقلت يصلي بها في ركعة، فمضى؛ فقلت يركع بها، ثم افتتح النساء؛ فقرأها، ثم افتتح آل عمران فقرأها، يقرأ مترسلاً إذا مر بآية فيها تسبيح سبح، وإذا مر بسؤال سأل، وإذا مر بتعوذ تعوذ، ثم ركع فجعل يقول‏:‏ ‏","matn":"\"‏ سبحان ربي العظيم‏\"‏ فكان ركوعه نحواً من قيامه ثم قال‏:‏ ‏\"‏ سمع الله لمن حمده، ربنا لك الحمد‏\"‏ ثم قام قياماً طويلاً قريباً مما ركع، ثم سجد فقال‏:‏ ‏\"‏ سبحان ربي الأعلى‏\"‏ فكان سجوده قريباً من قيامه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏.‏"},{"id":"riyad:1320","bookId":"riyad","type":"hadith","num":1320,"kitab":"كتاب المقدمات","isnad":"","matn":"التاسع‏:‏ عن ابن مسعود رضي الله عنه قال‏:‏ صليت مع النبي صلى الله عليه وسلم ليلة، فأطال القيام حتى هممت بأمر سوء‏!‏ قيل‏:‏ وما هممت به‏؟‏ قال‏:‏ هممت أن أجلس وأدعه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1321","bookId":"riyad","type":"hadith","num":1321,"kitab":"كتاب المقدمات","isnad":"العاشر عن أنس رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ يتبع الميت ثلاثة‏:‏ أهله وماله وعمله؛ فيرجع اثنان ويبقى واحد‏:‏ يرجع أهله وماله، ويبقى عمله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1322","bookId":"riyad","type":"hadith","num":1322,"kitab":"كتاب المقدمات","isnad":"الحادي عشر‏:‏ عن ابن مسعود رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ الجنة أقرب إلى أحدكم من شراك نعله، والنار مثل ذلك‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1323","bookId":"riyad","type":"hadith","num":1323,"kitab":"كتاب المقدمات","isnad":"الثاني عشر‏:‏ عن أبي فراس ربيعة بن كعب الأسلمى خادم رسول الله صلى الله عليه وسلم، ومن أهل الصفة رضي الله عنه قال‏:‏ ‏","matn":"\"‏ كنت أبيت مع رسول الله صلى الله عليه وسلم، فآتيه بوضوئه، وحاجته فقال‏:‏ ‏\"‏سلني‏\"‏ فقلت‏:‏ أسألك مرافقتك في الجنة‏.‏ فقال‏:‏ ‏{‏ أوغير ذلك‏؟‏‏\"‏ قلت‏:‏ هو ذاك قال‏:‏ ‏\"‏ فأعني على نفسك بكثرة السجود‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1324","bookId":"riyad","type":"hadith","num":1324,"kitab":"كتاب المقدمات","isnad":"الثالث عشر‏:‏ عن أبي عبد الله- ويقال‏:‏ أبو عبد الرحمن- ثوبان مولى رسول الله صلى الله عليه وسلم قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ عليك بكثرة السجود، فإنك لن تسجد لله سجدة إلا رفعك الله بها درجة، وحط عنك بها خطيئة‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1325","bookId":"riyad","type":"hadith","num":1325,"kitab":"كتاب المقدمات","isnad":"الرابع عشر‏:‏ عن أبي صفوان عبد الله بن بسر الأسلمي، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ خير الناس من طال عمره وحسن عمله‏\"‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن‏.‏ ‏\"‏بسر‏\"‏‏:‏ بضم الياء وبالسين المهملة‏)‏‏)‏‏.‏"},{"id":"riyad:1326","bookId":"riyad","type":"hadith","num":1326,"kitab":"كتاب المقدمات","isnad":"","matn":"الخامس عشر‏:‏ عن أنس رضي الله عنه، قال‏:‏ غاب عمي أنس ابن النضر رضي الله عنه، عن قتال بدر، فقال‏:‏ يارسول الله غبت عن أول قتال قاتلت المشركين، لئن الله أشهدني قتال المشركين ليرين الله ما أصنع‏.‏ فلما كان يوم أحد انكشف المسلمون، فقال اللهم أعتذر إليك مما صنع هؤلاء - يعني أصحابه- وأبرأ إليك مما صنع هؤلاء- يعني المشركين- ثم تقدم فاستقبله سعد بن معاذ، فقال‏:‏ ياسعد بن معاذ الجنة ورب الكعبة، إني أجد ريحها من دون أحد‏.‏ قال سعد‏:‏ فما استطعت يا رسول الله ما صنع‏!‏ قال أنس‏:‏ فوجدنا به بضعاً وثمانين ضربة بالسيف، أو طعنة برمح ، أو رمية بسهم، ووجدناه قد قتل ومثل به المشركون فما عرفه أحد إلا أخته ببنانه‏.‏ قال أنس‏:‏ كنا نرى أو نظن أن هذه الآيه نزلت فيه وفي أشباهه‏:‏ ‏{‏من المؤمنين رجال صدقوا ما عهدوا الله عليه‏}‏ ‏(‏‏(‏ الأحزاب‏:‏ 23‏)‏‏)‏ إلى آخرها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1327","bookId":"riyad","type":"hadith","num":1327,"kitab":"كتاب المقدمات","isnad":"","matn":"السادس عشر‏:‏ عن أبي مسعود عقبة بن عمرو الأنصاري البدري رضي الله عنه قال‏:‏ لما نزلت آيه الصدقة كنا نحامل على ظهورنا‏.‏ فجاء رجل فتصدق بشيء كثير فقالوا‏:‏ مراءٍ، وجاء رجل آخر فتصدق بصاع فقالوا‏:‏ إن الله لغني عن صاع هذا‏!‏ فنزلت ‏{‏ الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون إلا جهدهم‏}‏ الآية ‏(‏‏(‏التوبة‏:‏79‏)‏‏)‏‏.‏ ‏(‏‏(‏متفق عليه ‏)‏‏)‏‏.‏"},{"id":"riyad:1328","bookId":"riyad","type":"hadith","num":1328,"kitab":"كتاب المقدمات","isnad":"السابع عشر‏:‏ عن سعيد بن عبد العزيز، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي ذر جندب بن جنادة، رضي الله عنه، عن النبي صلى الله عليه وسلم فيما يروى عن الله تبارك وتعالى أنه قال‏:‏ ‏","matn":"\"‏ ياعبادي إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا، يا عبادي كلكم ضال إلا من هديته؛ فاستهدوني أهدكم، يا عبادي كلكم جائع إلا من أطعمته؛ فاستطعموني أطعمكم،يا عبادي كلكم عارٍ إلا من كسوته، فاستكسوني أكسكم، يا عبادي إنكم تخطئون بالليل والنهار وأنا أغفر الذنوب جميعا، فاستغفروني أغفرلكم، ياعبادي إنكم لن تبلغوا ضري فتضروني، ولن تبلغوا نفعي فتنفعوني، يَا عِبَادي ، لَوْ أنَّ أوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجنَّكُمْ كَانُوا عَلَى أتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا زَادَ ذلِكَ في مُلكي شيئاً . يَا عِبَادي ، لَوْ أنَّ أوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجنَّكُمْ كَانُوا عَلَى أفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مَا نَقَصَ ذلِكَ من مُلكي شيئاً، يا عبادي لو أن أولكم وآخركم، وإنسكم وجنكم قاموا في صعيد واحد، فسألوني فأعطيت كل إنسان مسألته، ما نقص ذلك مما عندي إلا كما ينقص المخيط إذا أدخل البحر، يا عبادي إنما هي أعمالكم أحصيها لكم، ثم أوفيكم إياها، فمن وجد خيراً فليحمد الله، ومن وجد غير ذلك فلا يلومن إلا نفسه‏\"‏‏.‏ قال سعيد‏:‏ كان أبو إدريس إذا حدث بهذا الحديث جثا على ركبتيه‏.‏ رواه مسلم‏.‏ (20)‏.‏"},{"id":"riyad:1329","bookId":"riyad","type":"hadith","num":1329,"kitab":"كتاب المقدمات","isnad":"وأما الأحاديث فالأول‏:‏ عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ أعذر الله إلى امرئ أخر أجله حتى بلغ ستين سنة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1330","bookId":"riyad","type":"hadith","num":1330,"kitab":"كتاب المقدمات","isnad":"","matn":"الثاني‏:‏ عن ابن عباس، رضي الله عنهما، قال‏:‏ كان عمر رضي الله عنه يدخلني مع أشياخ بدر، فكأن بعضهم وجد في نفسه فقال‏:‏ لم يدخل هذا معنا ولنا أبناء مثله‏!‏‏؟‏ فقال عمر‏:‏ إنه من حيث علمتم‏!‏ فدعاني ذات يوم فأدخلني معهم، فما رأيت أنه دعانى يومئذ إلا ليريهم قال‏:‏ ما تقولون في قول الله تعالى‏:‏ ‏{‏إذا جاء نصر الله والفتح‏؟‏‏)‏ ‏(‏‏(‏النصر‏:‏1‏)‏‏)‏ فقال بعضهم‏:‏ أمرنا نحمد الله ونستغفره إذا نصرنا وفتح علينا‏.‏ وسكت بعضهم فلم يقل شيئاً‏.‏ فقال لي‏:‏ أكذلك تقول يا ابن عباس‏؟‏ فقلت‏:‏ لا‏.‏ قال فما تقول‏؟‏ قلت‏:‏ هو أجل رسول الله صلى الله عليه وسلم، أعلمه له قال‏:‏ ‏{‏إذاجاء نصر الله والفتح‏}‏ وذلك علامة أجلك ‏{‏فسبح بحمد ربك واستغفره إنه كان تواباً‏}‏ ‏(‏‏(‏الفتح‏:‏ 3‏)‏‏)‏ فقال عمر رضي الله عنه‏:‏ ما أعلم منها إلا ما تقول‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1331","bookId":"riyad","type":"hadith","num":1331,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن عائشة رضي الله عنها قالت‏:‏ ما صلى رسول الله صلى الله عليه وسلم صلاة بعد أن نزلت عليه ‏{‏ إذا جاء نصر الله والفتح‏}‏ إلا يقول فيها‏:‏ ‏","matn":"\"‏ سبحانك ربنا وبحمدك، اللهم اغفر لي‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية في الصحيحين‏\"‏ عنها‏:‏ كان رسول الله صلى الله عليه وسلم يكثر أن يقول في ركوعه وسجوده‏:‏ ‏\"‏سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي‏\"‏ يتأول القرآن‏.‏ وفي رواية لمسلم‏:‏ كان رسول الله صلى الله عليه وسلم يكثر أن يقول قبل أن يموت‏:‏ ‏\"‏سبحانك اللهم وبحمدك، أستغفرك وأتوب إليك‏\"‏‏.‏ قالت عائشة‏:‏ قلت‏:‏ يا رسول الله ما هذه الكلمات التي أراك أحدثتها تقولها‏؟‏ قال‏:‏ ‏\"‏جعلت لي علامة في أمتي إذا رأيتها قلتها ‏{‏إذا جاء نصر الله والفتح‏}‏ إلى آخر السورة‏\"‏‏.‏ وفي رواية له‏:‏ كان رسول الله صلى الله عليه وسلم يكثر من قول‏:‏ ‏\"‏سبحان الله وبحمده، أستغفر الله وأتوب إليه‏\"‏‏.‏ قالت‏:‏ قلت‏:‏ يا رسول الله‏!‏ أراك تكثر من قول‏:‏ سبحان الله وبحمده، أستغفر الله وأتوب إليه‏؟‏ فقال‏:‏ ‏\"‏أخبرني ربي أني سأرى علامة في أمتي فإذا رأيتها أكثرت من قول‏:‏ سبحان الله وبحمده، أستغفر الله وأتوب إليه، فقد رأيتها‏:‏ ‏{‏إذا جاء نصر الله والفتح‏}‏ فتح مكة، ‏{‏ورأيت الناس يدخلون في دين الله أفواجاً، فسبح بحمد ربك واستغفره إنه كان تواباً‏}‏‏.‏"},{"id":"riyad:1332","bookId":"riyad","type":"hadith","num":1332,"kitab":"كتاب المقدمات","isnad":"الرابع؛‏:‏ عن أنس رضي الله عنه قال‏:‏ إن الله عز وجل تابع الوحي على رسول الله صلى الله عليه وسلم قبل وفاته، حتى توفي أكثر ما كان الوحي‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1333","bookId":"riyad","type":"hadith","num":1333,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏يبعث كل عبد على ما مات عليه‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1334","bookId":"riyad","type":"hadith","num":1334,"kitab":"كتاب المقدمات","isnad":"الأول‏:‏ عن أبي ذر جندب بن جنادة رضي الله عنها قال‏:‏ قلت يا رسول الله، أي الأعمال أفضل‏؟‏ قال‏:‏ ‏","matn":"\"‏الإيمان بالله، والجهاد في سبيله‏\"‏‏.‏ قلت‏:‏ أي الرقاب أفضل‏؟‏ قال‏:‏ ‏\"‏أنفسها عند أهلها، وأكثرها ثمناً‏\"‏ قلت‏:‏ فإن لم أفعل‏؟‏ قال‏:‏ ‏\"‏تعين صانعاً أو تصنع لأخرق‏\"‏ قلت‏:‏ يا رسول الله أرأيت إن ضعفت عن بعض العمل‏؟‏ قال‏:‏ تكف شرك عن الناس فإنها صدقة منك على نفسك‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1335","bookId":"riyad","type":"hadith","num":1335,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن أبي ذر أيضاً رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ يصبح على كل سلامى من أحدكم صدقة، فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهى عن المنكر صدقة، ويجزيء من ذلك ركعتان يركعهما من الضحى‏\"‏ ‏(‏‏(‏رواه مسلم)) ‏‏‏ ‏ السلامى‏ ‏ بضم السين المهملة وتخفيف اللام وفتح الميم‏:‏ المفصل.‏"},{"id":"riyad:1336","bookId":"riyad","type":"hadith","num":1336,"kitab":"كتاب المقدمات","isnad":"الثالث عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ عرضت علي أعمال أمتي حسنها وسيئها، فوجدت في محاسن أعمالها الأذى يماط عن الطريق، ووجدت في مساوىء أعمالها النخاعة تكون في المسجد لا تدفن‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1337","bookId":"riyad","type":"hadith","num":1337,"kitab":"كتاب المقدمات","isnad":"الرابع عنه‏:‏ أن ناساً قالوا‏:‏ يارسول الله، ذهب أهل الدثور بالأجور، يصلون كما نصلي، ويصومون كما نصوم، ويتصدقون بفضول أموالهم قال‏:‏ ‏","matn":"\"‏ أو ليس قد جعل الله لكم ما تصدقون به‏:‏ إن بكل تسبيحة صدقة، وكل تكبيرة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة وفي بضع أحدكم صدقة قالوا‏:‏ يارسول الله أيأتى أحدنا شهوته، ويكون له فيها أجر‏؟‏‏!‏ قال‏:‏ ‏\"‏ أرأيتم لو وضعها في حرام أكان عليه وزر‏؟‏ فكذلك إذا وضعها في الحلال كان له أجر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1338","bookId":"riyad","type":"hadith","num":1338,"kitab":"كتاب المقدمات","isnad":"-الخامس‏:‏ عنه قال لي النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ لا تحقرن من المعروف شيئاً ولو أن تلقى أخاك بوجهٍ طليق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1339","bookId":"riyad","type":"hadith","num":1339,"kitab":"كتاب المقدمات","isnad":"السادس ‏:‏ عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ كل سلامى من الناس عليه صدقة كل يوم تطلع فيه الشمس‏:‏ تعدل بين الأثنين صدقة، وتعين الرجل في دابته، فتحمله عليها، أو ترفع له عليها متاعه صدقة، والكلمة الطيبة صدقة، وبكل خطوة تمشيها إلى الصلاة صدقة، وتميط الأذى عن الطريق صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ورواه مسلم أيضاً من رواية عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ إنه خلق كل إنسان من بني آدم على ستين وثلاثمائه مفصل، فمن كبر الله، وحمد الله، وهلل الله، وسبح الله واستغفر الله، وعزل حجراً عن طريق الناس أو شوكة أو عظماً عن طريق الناس، أو أمر بمعروف أو نهى عن المنكر، عدد الستين والثلاثمائة، فإنه يمسي يومئذ وقد زحزح نفسه عن النار‏\"‏‏.‏"},{"id":"riyad:1340","bookId":"riyad","type":"hadith","num":1340,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من غدا إلى المسجد أو راح، أعد الله له في الجنة نزلا كلما غدا أو راح‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1341","bookId":"riyad","type":"hadith","num":1341,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عنه قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ يا نساء المسلمات لا تحقرن جارة لجارتها ولو فرسن شاة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1342","bookId":"riyad","type":"hadith","num":1342,"kitab":"كتاب المقدمات","isnad":"التاسع‏:‏ عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ الإيمان بضع وسبعون، أو بضع وستون شعبة‏:‏ فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1343","bookId":"riyad","type":"hadith","num":1343,"kitab":"كتاب المقدمات","isnad":"العاشر‏:‏ عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ بينما رجل يمشى بطريق اشتد عليه العطش، فوجد بئراً فنزل فيها فشرب، ثم خرج فإذا كلب يلهث يأكل الثرى من العطش، فقال الرجل‏:‏ لقد بلغ هذا الكلب من العطش مثل الذي كان قد بلغ منى، فنزل البئر فملأ خفه ماء ثم أمسكه بفيه، حتى رقي فسقى الكلب، فشكر الله له فغفر له‏\"‏ قالوا ‏:‏ يارسول الله إن لنا في البهائم أجراً‏؟‏ فقال‏:‏ في كل كبدٍ رطبة أجر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1344","bookId":"riyad","type":"hadith","num":1344,"kitab":"كتاب المقدمات","isnad":"الحادي عشر‏:‏ عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لقد رأيت رجلا يتقلب في الجنة في شجرة قطعها من ظهر الطريق كانت تؤذى المسلمين‏\"‏‏.‏‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية‏:‏ ‏ ‏ مر رجل بغصن شجرة على ظهر طريق فقال‏:‏ والله لأنحين هذا عن المسلمين لا يؤذيهم، فأدخل الجنة‏ ‏‏.‏ وفي رواية لهما‏:‏ ‏ ‏ بينما رجل يمشى بطريق وجد غصن شوك على الطريق، فأخره فشكره الله له، فغفر له‏ .‏"},{"id":"riyad:1345","bookId":"riyad","type":"hadith","num":1345,"kitab":"كتاب المقدمات","isnad":"الثاني عشر‏:‏ عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من توضأ فأحسن الوضوء، ثم أتى الجمعة، فاستمع وأنصت، غفر له ما بينه وبين الجمعة وزيادة ثلاثة أيام، ومن مس الحصا فقد لغا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1346","bookId":"riyad","type":"hadith","num":1346,"kitab":"كتاب المقدمات","isnad":"الثالث عشر‏:‏ عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا توضأ العبد المسلم، أو المؤمن فغسل وجهه خرج من وجهه كل خطيئة نظر إليها بعينيه مع الماء، أو آخر قطر الماء، فإذا غسل رجليه خرجت كل خطيئة مشتها رجلاه مع الماء أو مع آخر قطر الماء حتى يخرج نقياً من الذنوب‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1347","bookId":"riyad","type":"hadith","num":1347,"kitab":"كتاب المقدمات","isnad":"الرابع عشر‏:‏ عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان مكفرات لما بينهن إذا اجتنبت الكبائر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1348","bookId":"riyad","type":"hadith","num":1348,"kitab":"كتاب المقدمات","isnad":"الخامس عشر‏:‏ عنه قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ ألا أدلكم على ما يمحو الله به الخطايا، ويرفع به الدرجات‏؟‏‏\"‏ قالوا‏:‏ بلى يا رسول الله، قال‏:‏ ‏\"‏ إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1349","bookId":"riyad","type":"hadith","num":1349,"kitab":"كتاب المقدمات","isnad":"السادس عشر‏:‏ عن أبي موسى الأشعري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من صلى البردين دخل الجنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1350","bookId":"riyad","type":"hadith","num":1350,"kitab":"كتاب المقدمات","isnad":"السابع عشر‏:‏ عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ إذا مرض العبد أو سافر كتب له مثل ما كان يعمل مقيماً صحيحاً‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1351","bookId":"riyad","type":"hadith","num":1351,"kitab":"كتاب المقدمات","isnad":"الثامن عشر‏:‏ عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ كل معروف صدقة‏\"‏ ‏(‏‏(‏رواه البخاري، ورواه مسلم من رواية حذيفة رضي الله عنه‏)‏‏)‏‏.‏"},{"id":"riyad:1352","bookId":"riyad","type":"hadith","num":1352,"kitab":"كتاب المقدمات","isnad":"التاسع عشر‏:‏ عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ ما من مسلم يغرس غرساً إلا كان ما أكل منه له صدقة، وما سرق منه له صدقة، ولا يرزؤه أحد إلا كان له صدقة‏\"‏ ‏(‏‏(‏رواه مسلم‏.‏ ‏)‏‏)‏ وفي رواية له‏:‏ ‏\"‏ فلا يغرس المسلم غرساً، فيأكل منه إنسان ولا دابة ولا طير إلا كان له صدقة إلى يوم القيامة‏\"‏‏.‏ وفي رواية له‏:‏ ‏\"‏ لا يغرس مسلم غرساً، ولا يزرع زرعاً، فيأكل منه إنسان ولا دابة ولا شىء إلا كانت له صدقة‏\"‏ وروياه جميعاً من رواية أنس رضي الله عنه‏.‏"},{"id":"riyad:1353","bookId":"riyad","type":"hadith","num":1353,"kitab":"كتاب المقدمات","isnad":"العشرون‏:‏ عنه قال‏:‏ أراد بنو سلمة أن ينقلوا قرب المسجد فبلغ ذلك رسول الله صلى الله عليه وسلم، فقال لهم‏:‏ ‏","matn":"\"‏ إنه قد بلغني أنكم تريدون أن تنتقلوا قرب المسجد‏؟‏‏\"‏ فقالوا‏:‏ نعم يارسول الله قد أردنا ذلك، فقال‏:‏‏\"‏بني سلمة دياركم؛ تكتب آثاركم ‎، دياركم، تكتب آثاركم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1354","bookId":"riyad","type":"hadith","num":1354,"kitab":"كتاب المقدمات","isnad":"الحادي والعشرون‏:‏ عن أبي المنذر أبي بن كعب رضي الله عنه قال‏:‏ كان رجل لا أعلم رجلاً أبعد من المسجد منه، وكان لا تخطئه صلاة فقيل له، أو فقلت له‏:‏ لو اشتريت حماراً تركبه في الظلماء، وفي الرمضاء، فقال‏:‏ ما يسرني أن منزلي إلى جنب المسجد، إني أريد أن يكتب لي ممشاي إلى المسجد، ورجوعي إذا رجعت إلى أهلي، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏قد جمع الله لك ذلك كله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1355","bookId":"riyad","type":"hadith","num":1355,"kitab":"كتاب المقدمات","isnad":"الثاني والعشرون‏:‏ عن أبي محمد عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أربعون خصلة أعلاها منيحة العنز، ما من عامل يعمل بخصلة منها رجاء ثوابها وتصديق موعودها إلا أدخله الله بها الجنة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1356","bookId":"riyad","type":"hadith","num":1356,"kitab":"كتاب المقدمات","isnad":"الثالث والعشرون‏:‏ عن عدي بن حاتم رضي الله عنه قال‏:‏ سمعت النبي صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ اتقوا النار ولو بشق تمرةٍ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لهما عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ ما منكم من أحد إلا سيكلمه ربه ليس بينه وبينه ترجمان فينظر أيمن منه فلا يرى إلا ما قدم، وينظر أشأم منه فلا يرى إلا ما قدم، ينظر بين يديه فلا يرى إلا النار تلقاء وجهه، فاتقوا النار ولو بشق تمرة، فمن لم يجد فبكلمة طيبةٍ‏\"‏‏.‏"},{"id":"riyad:1357","bookId":"riyad","type":"hadith","num":1357,"kitab":"كتاب المقدمات","isnad":"الرابع والعشرون‏:‏ عن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها ، أو يشرب الشربة فيحمده عليها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1358","bookId":"riyad","type":"hadith","num":1358,"kitab":"كتاب المقدمات","isnad":"الخامس والعشرون‏:‏ عن أبي موس رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏على كل مسلم صدقة‏\"‏ قال ‏:‏ أرأيت إن لم يجد‏؟‏ قال‏:‏ أرأيت إن لم يستطع‏؟‏ قال‏:‏ ‏\"‏يعين ذا الحاجة الملهوف‏\"‏ قال‏:‏ أرأيت إن لم يستطع‏؟‏ قال‏:‏ ‏\"‏يأمر بالمعروف أو الخير‏\"‏ قال ‏:‏ أرأيت إن لم يفعل‏؟‏ قال‏:‏ يمسك عن الشر فإنها صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1359","bookId":"riyad","type":"hadith","num":1359,"kitab":"كتاب المقدمات","isnad":"- وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها وعندها امرأة قال‏:‏ من هذه‏؟‏ قالت‏:‏ هذه فلانة تذكر من صلاتها قال‏:‏ ‏","matn":"\"‏ مه عليكم بما تطيقون، فوالله لا يمل الله حتى تملوا‏\"‏ وكان أحب الدين إليه ما داوم صاحبه عليه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1360","bookId":"riyad","type":"hadith","num":1360,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ جاء ثلاثة رهط إلى بيوت أزواج النبي صلى الله عليه وسلم، يسألون عن عبادة النبي صلى الله عليه وسلم، فلما أخبروا كأنهم تقالوها وقالوا‏:‏ أين نحن من النبي صلى الله عليه وسلم قد غفر الله له تقدم من ذنبه وما تأخر‏.‏ قال أحدهم‏:‏ أما أنا فأصلي الليل أبداً وقال الآخر‏:‏ وأنا أصوم الدهر أبداً ولا أفطر، وقال الآخر‏:‏ وأنا أعتزل النساء فلا أتزوج أبداً، فجاء رسول الله صلى الله عليه وسلم إليهم فقال‏:‏ ‏","matn":"\"‏أنتم الذين قلتم كذا وكذا‏؟‏‏!‏ أما والله إني لأخشاكم لله وأتقاكم له لكني أصوم وأفطر، وأصلي وأرقد، وأتزوج النساء، فمن رغب عن سنتي فليس مني‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1361","bookId":"riyad","type":"hadith","num":1361,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏هلك المتنطعون‏\"‏ قالها ثلاثاً ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏"},{"id":"riyad:1362","bookId":"riyad","type":"hadith","num":1362,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إن الدين يسر، ولن يشاد الدين إلا غلبه، فسددوا وقاربوا وأبشروا، واستعينوا بالغدوة والروحة وشيء من الدلجة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ وفي رواية له ‏:‏ ‏ ‏سددوا وقاربوا واغدوا وروحوا، وشيء من الدلجة، القصد القصد تبلغوا‏ ‏‏.‏"},{"id":"riyad:1363","bookId":"riyad","type":"hadith","num":1363,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ دخل النبي صلى الله عليه وسلم المسجد فإذا حبل ممدود بين الساريتين فقال‏:‏ ‏","matn":"\"‏ما هذا الحبل‏\"‏ قالوا ‏:‏ هذا حبل لزينب، فإذا فترت تعلقت به‏.‏ فقال النبي صلى الله عليه وسلم ‏\"‏ حلوه، ليصل أحدكم نشاطه فإذا فتر فليرقد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1364","bookId":"riyad","type":"hadith","num":1364,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا نعس أحدكم وهو يصلي، فليرقد حتى يذهب عنه النوم، فإن أحدكم إذا صلى وهو ناعس لا يدري لعله يذهب ويستغفر فيسب نفسه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1365","bookId":"riyad","type":"hadith","num":1365,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله جابر بن سمرة رضي الله عنهما قال‏:‏ ‏","matn":"\"‏كنت أصلى مع النبي صلى الله عليه وسلم الصلوات، فكانت صلاته قصداً وخطبته قصداً‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1366","bookId":"riyad","type":"hadith","num":1366,"kitab":"كتاب المقدمات","isnad":"وعن أبي جحيفة وهب بن عبد الله رضي الله عنه قال‏:‏ آخى النبي صلى الله عليه وسلم بين سلمان وأبى الدرداء ، فزار سلمان أبا الدرداء، فرأى أم الدرداء متبذلة فقال‏:‏ ما شأنك قالت‏:‏ أخوك أبو الدرداء ليس له حاجة في الدنيا، فجاء أبو الدراداء فصنع له طعاماً، فقال له‏:‏ كل فإنى صائم، قال‏:‏ ما أنا بآكل حتى تأكل، فأكل، فلما كان الليل ذهب أبو الدرداء يقوم فقال له‏:‏ نم، فنام، ثم ذهب يقوم فقال له ‏:‏ نم، فلما كان من آخر الليل قال سلمان‏:‏ قم الآن‏:‏ فصليا جميعاً، فقال له سلمان‏:‏ إن لربك عليك حقاً، وإن لنفسك عليك حقاً، ولأهلك عليك حقاً، فأعط كل ذى حق حقه، فأتى النبي صلى الله عليه وسلم فذكر ذلك له، فقال النبي صلى الله عليه وسلم ‏","matn":"\"‏صدق سلمان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1367","bookId":"riyad","type":"hadith","num":1367,"kitab":"كتاب المقدمات","isnad":"وعن أبي محمد عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ أخبر النبي صلى الله عليه وسلم أني أقول‏:‏ والله لأصومن النهار، ولأقومن الليل ماعشت، فقال رسول الله صلى الله عليه وسلم ‏:‏ أنت الذي تقول ذلك‏؟‏ فقلت له‏:‏ قد قلته بأبى أنت وأمى يا رسول الله‏.‏ قال‏:‏‏","matn":"\"‏فإنك لا تستطيع ذلك؛ فصم وأفطر، ونم وقم، وصم من الشهر ثلاثة أيام فإن الحسنة بعشر أمثالها، وذلك مثل صيام الدهر‏\"‏ قلت‏:‏ فإنى أطيق أفضل من ذلك قال‏:‏ فصم يوما وأفطر يومين، قلت‏:‏ فإنى أطيق أفضل من ذلك، قال‏:‏ ‏\"‏فصم يوماً وأفطر يوماً، فذلك صيام داود صلى الله عليه وسلم، وهو أعدل الصيام‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏وهو أفضل الصيام‏\"‏ فقلت ‏:‏ فإني أطيق أفضل من ذلك‏.‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ لا أفضل من ذلك‏\"‏ ولأن أكون قبلت الثلاثة الأيام التي قال رسول الله صلى الله عليه وسلم أحب إلي من أهلي وما لي‏.‏ وفي رواية‏:‏ ‏\"‏ألم أخبر أنك تصوم النهار وتقوم الليل‏؟‏‏\"‏ قلت ‏:‏ بلى يا رسول الله قال‏:‏ ‏\"‏فلا تفعل‏:‏ صم وأفطر ، ونم وقم فإن لجسدك عليك حقاً، وإن لعينيك عليك حقاً، وإن لزوجك عليك حقاً، وإن لزورك عليك حقاً، وإن بحسبك أن تصوم في كل شهر ثلاثة أيام ، فإن لك بكل حسنة عشر أمثالها، فإن ذلك صيام الدهر‏\"‏ فشددت فشدد علي، قلت‏:‏ يا رسول الله إني أجد قوة، قال‏:‏ ‏\"‏صم صيام نبي الله داود ولا تزد عليه‏\"‏ قلت‏:‏ وما كان صيام داود‏؟‏ قال‏:‏ ‏\"‏نصف الدهر‏\"‏ فكان عبد الله يقول بعدما كبر‏:‏ يا ليتني قبلت رخصة رسول الله صلى الله عليه وسلم‏.‏ وفي رواية‏:‏ ‏\"‏ ألم أخبر أنك تصوم الدهر، وتقرأ القرآن كل ليلةٍ‏؟‏‍‍‍‍‍‍‏\"‏ فقلت‏:‏ بلى يا رسول الله، ولم أرد بذلك إلا الخير قال‏:‏ ‏\"‏فصم صوم نبي الله داود، فإنه كان أعبد الناس، واقرأِ القرآن كل شهرٍ‏\"‏ قلت‏:‏ يا نبي الله إني أطيق أفضل من ذلك‏؟‏ قال‏:‏ ‏\"‏فاقرأه في كل عشرين‏\"‏ قلت‏:‏ يا نبي الله إني أطيق أفضل من ذلك‏؟‏ قال‏:‏ ‏\"‏فاقرأه في كل عشر‏\"‏ قلت يا نبي الله إني أطيق أفضل من ذلك‏؟‏ قال‏:‏ ‏\"‏فاقرأه في كل سبع ولا تزد على ذلك‏\"‏‏.‏ فشددت فشدد علي ، وقال لي النبي صلى الله عليه وسلم‏:‏ ‏\"‏إنك لا تدري لعلك يطول بك عمر‏\"‏ قال‏:‏ فصرت إلى الذي قال لي النبي صلى الله عليه وسلم، فلما كبرت وددت أني كنت قبلت رخصة نبي الله صلى الله عليه وسلم‏.‏ وفي رواية‏:‏ ‏\"‏ وإن لولدك عليك حقاً‏\"‏ وفي رواية‏:‏ ‏\"‏ لا صام من صام الأبد‏\"‏ ثلاثاً‏.‏ وفي رواية‏:‏ ‏\"‏أحب الصيام إلى الله تعالى صيام داود، وأحب الصلاة إلى الله تعالى صلاة داود‏:‏ كان ينام نصف الليل، ويقوم ثلثه، وينام سدسه، وكان يصوم يوما ويفطر يوماً، ولا يفر إذا لاقى‏\"‏‏.‏ وفي رواية‏:‏ أنكحني أبي امرأة ذات حسب، وكان يتعاهد كنته-أي ‏:‏ امرأة ولده- فيسألها عن بعلها، فتقول له ‏:‏ نعم الرجل من رجل لم ييطأ لنا فراشاً ولم يفتش لنا كنفاً منذ أتيناه‏.‏ فلما طال ذلك عليه ذكر ذلك للنبي صلى الله عليه وسلم‏.‏ فقال‏:‏ ‏\"‏القنى به‏\"‏ فلقيته بعد ذلك فقال‏:‏ ‏\"‏كيف تصوم‏؟‏‏\"‏ قلت كل يوم، قال‏:‏ ‏\"‏وكيف تختم‏؟‏‏\"‏ قلت‏:‏ كل ليلةٍ، وذكر نحون ما سبق ، وكان يقرأ على بعض أهله السبع الذي يقرؤه، يعرضه من النهار ليكون أخف عليه بالليل، وإذا أراد أن يتقوى أفطر أياماً وأحصى وصام مثلهن كراهية أن يترك شيئاً فارق عليه النبي صلى الله عليه وسلم‏.‏ كل هذه الروايات صحيحة معظمها في الصحيحين وقليل منها في أحدهما‏.‏ ‏.‏"},{"id":"riyad:1368","bookId":"riyad","type":"hadith","num":1368,"kitab":"كتاب المقدمات","isnad":"وعن أبي ربعي حنظلة بن الربيع الأسيدى الكاتب أحد كتاب رسول الله صلى الله عليه وسلم قال‏:‏ لقيني أبو بكر رضي الله عنه فقال‏:‏ كيف أنت يا حنظلة‏؟‏ قلت‏:‏ نافق حنظلة‏؟‏ قلت‏:‏ نافق حنظلة ‍‍‏(‏ قال‏:‏ سبحان الله ما تقول‏؟‏ ‏(‏ قلت‏:‏ نكون عند رسول الله صلى الله عليه وسلم يذكرنا بالجنة والنار كأنا رأي عين، فإذا خرجنا من عند رسول الله صلى الله عليه وسلم عافسنا الأزواج والأولاد والضيعات نسينا كثيراً‏.‏ قال أبو بكر رضي الله عنه ‏:‏ فوالله إنا لنلقى مثل هذا، فانطلقت أنا وأبو بكر حتى دخلنا على رسول الله صلى الله عليه وسلم‏.‏ فقلت‏:‏ نافق حنظلة يا رسول الله ‏(‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏وما ذاك‏؟‏‏\"‏ قلت‏:‏ يا رسول الله نكون عندك تذكرنا بالنار والجنة كأنا رأي العين، فإذا خرجنا من عندك عافسنا الأزواج والأولاد والضيعات نسينا كثيراً‏.‏ فقال رسول الله 0‏:‏ ‏\"‏والذي نفسي بيده لو تدومون على ما تكونون عندي وفي الذكر لصافحتكم الملائكة على فرشكم وفي طرقكم، ولكن يا حنظلة ساعة وساعة‏\"‏ ثلاث مرات، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1369","bookId":"riyad","type":"hadith","num":1369,"kitab":"كتاب المقدمات","isnad":"- وعن ابن عباس رضي الله عنهما قال‏:‏ بينما النبي صلى الله عليه وسلم يخطب إذا هو برجل قائم، فسأل عنه فقالوا‏:‏ أبو إسرائيل نذر أن يقوم في الشمس ولا يقعد، ولا يستظل ولا يتكلم، ويصوم، فقال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏مروه فليتكلم وليستظل وليقعد وليتم صومه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1370","bookId":"riyad","type":"hadith","num":1370,"kitab":"كتاب المقدمات","isnad":"وعن عمر بن الخطاب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من نام عن حزبه من الليل، أو عن شيء منه فقرأه ما بين صلاة الفجر وصلاة الظهر، كتب له كأنما قرأه من الليل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1371","bookId":"riyad","type":"hadith","num":1371,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏ يا عبد الله لا تكن مثل فلان، كان يقوم الليل فترك قيام الليل‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1372","bookId":"riyad","type":"hadith","num":1372,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم إذا فاتته الصلاة من الليل من وجع أو غيره، صلى من النهار ثنتي عشرة ركعة‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1373","bookId":"riyad","type":"hadith","num":1373,"kitab":"كتاب المقدمات","isnad":"فالأول ‏:‏ عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏دعوني ماتركتكم‏:‏ إنما أهلك من كان قبلكم كثرة سؤالهم ، واختلافهم على أنبيائهم، فإذا نهيتكم عن شيء فاجتنبوه، وإذا أمرتكم بأمر فأتوا منه ما استطعتم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1374","bookId":"riyad","type":"hadith","num":1374,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن أبي نجيح العرباض بن سارية رضي الله عنه قال‏:‏ ‏","matn":"\"‏وعظنا رسول الله صلى الله عليه وسلم موعظة بليغة وجلت منها القلوب وذرفت منها العيون، فقلنا‏:‏ يا رسول الله كأنها موعظة مودع فأوصنا‏.‏ قال‏:‏ ‏\"‏أوصيكم بتقوى الله ، والسمع والطاعة وإن تأمر عليكم عبد حبشي، وإنه من يعش منكم فسيرى اختلافاً كثيراً‏.‏ فعليكم بسنتي وسنة الخلفاء الراشدين المهديين، عضوا عليها بالنواجذ، وإياكم ومحدثات الأمور فإن كل بدعة ضلالة‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1375","bookId":"riyad","type":"hadith","num":1375,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كل أمتي يدخلون الجنة إلا من أبى ‏\"‏ ‏.‏ قيل‏:‏ ومن يأبى يا رسول الله قال‏:‏ ‏\"‏ من أطاعني دخل الجنة، ومن عصاني فقد أبى‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1376","bookId":"riyad","type":"hadith","num":1376,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن أبي مسلم، وقيل ‏:‏ أبي إياس سلمة بن عمرو بن الأكوع رضي الله عنه ، أن رجلاً أكل عند رسول الله صلى الله عليه وسلم بشماله فقال‏:‏ ‏","matn":"\"‏كل بيمينك‏\"‏ قال‏:‏ لا أستطيع‏.‏ قال‏:‏ ‏\"‏ لا استطعت‏\"‏ ما منعه إلا الكبر، فما رفعها إلى فيه ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1377","bookId":"riyad","type":"hadith","num":1377,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن أبي عبد الله النعمان بن بشير رضي الله عنهما، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏لتسون صفوفكم أو ليخالفن الله بين وجوهكم ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لمسلم‏:‏ كان رسول الله صلى الله عليه وسلم يسوي صفوفنا حتى كأنما يسوي بها القداح ،حتى إذا رأى أنا قد عقلنا عنه ثم خرج يوما، فقام حتى كاد أن يكبر، فرأى رجلاً بادياً صدره فقال‏:‏ ‏\"‏ عباد الله لتسون صفوفكم أو ليخالفن الله بين وجوهكم‏\"‏‏.‏"},{"id":"riyad:1378","bookId":"riyad","type":"hadith","num":1378,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن أبي موسى رضي الله عنه قال‏:‏ احترق بيت بالمدينة على أهله من الليل، فلما حدث رسول الله صلى الله عليه وسلم بشأنهم قال ‏","matn":"\"‏إن هذه النار عدو لكم، فإذا نمتم فاطفئوها عنكم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1379","bookId":"riyad","type":"hadith","num":1379,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن مثل ما بعثني الله به من الهدى والعلم كمثل غيث أصاب أرضاً فكانت منها طائفة طيبة، قبلت الماء فأنبتت الكلأ والعشب الكثير، وكان منها أجادب أمسكت الماء، فنفع الله بها الناس فشربوا منها وسقوا وزرعوا‏.‏ وأصاب طائفة منها أخرى ، إنما هي قيعان لا تمسك ماء ولا تنبت كلأ‏.‏ فذلك مثل من فقه في دين الله، ونفعه بما بعثنى الله به، فعلم وعلم، ومثل من لم يرفع بذلك رأساً، ولم يقبل هدى الله الذي أرسلت به‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏ ‏فقه‏ ‏ بضم القاف على المشهور، وقيل‏:‏ بكسرها، أي‏:‏ صار فقيهاً‏."},{"id":"riyad:1380","bookId":"riyad","type":"hadith","num":1380,"kitab":"كتاب المقدمات","isnad":"الثامن‏:‏ عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏مثلي ومثلكم كمثل رجل أوقد ناراً فجعل الجنادب والفراش يقعن فيها وهو يذبهن عنها وأنا آخذ بحجزكم عن النار، وأنتم تفلتون من يدي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1381","bookId":"riyad","type":"hadith","num":1381,"kitab":"كتاب المقدمات","isnad":"التاسع‏:‏ عنه أن رسول الله صلى الله عليه وسلم، أمر بلعق الأصابع والصحفة وقال‏:‏ ‏","matn":"\"‏إنكم لا تدرون في أيها البركة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ ‏\"‏ إذا وقعت لقمة أحدكم ‏.‏ فليأخذها فليمط ماكان بها من أذى، وليأكلها، ولا يدعها للشيطان، ولا يمسح يده بالمنديل حتى يلعق أصابعه، فإنه لا يدري في أي طعامه البركة‏\"‏‏.‏ وفي رواية له‏:‏ ‏\"‏إن الشيطان يحضر أحدكم عند كل شيء من شأنه حتى يحضره عند طعامه، فإذا سقطت من أحدكم اللقمة فليمط ما كان بها من أذى ، فليأكلها، ولا يدعها للشيطان‏\"‏‏.‏"},{"id":"riyad:1382","bookId":"riyad","type":"hadith","num":1382,"kitab":"كتاب المقدمات","isnad":"العاشر‏:‏ عن ابن عباس، رضي الله عنهما، قال‏:‏ قام فينا رسول الله صلى الله عليه وسلم بموعظة فقال‏:‏ ‏","matn":"\"‏يا أيها الناس إنكم محشورون إلى الله تعالى حفاة عراة غرلاً ‏{‏كما بدأنا أول خلق نعيده وعداً علينا إنا كنا فاعلين‏}‏ ‏(‏‏(‏الأنبياء‏:‏ 103‏)‏‏)‏ ألا وإن أول الخلائق يكسى يوم القيامة إبراهيم ، صلى الله عليه وسلم، ألا وإنه سيجاء برجال من أمتي ، فيؤخذ بهم ذات الشمال؛ فأقول‏:‏ يارب أصحابي؛ فيقال‏:‏ إنك لا تدري ما أحدثوا بعدك، فأقول كما قال العبد الصالح‏:‏ ‏{‏وكنت عليهم شهيداً ما دمت فيهم‏}‏ إلى قوله‏:‏ ‏{‏ العزيز الحكيم‏}‏ ‏)‏ ‏(‏‏(‏المائدة ‏:‏ 117،118‏)‏‏)‏ فيقال لي ‏:‏ إنهم لم يزالوا مرتدين على أعقابهم منذ فارقتهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (46)"},{"id":"riyad:1383","bookId":"riyad","type":"hadith","num":1383,"kitab":"كتاب المقدمات","isnad":"الحادي عشر‏:‏ عن أبي سعيد عبد الله بن مغفل، رضي الله عنه ، قال‏:‏ نهى رسول الله، صلى الله عليه وسلم عن الخذف وقال‏:‏ ‏","matn":"\"‏إنه لا يقتل الصيد، ولا ينكأ العدو، وإنه يفقأ العين، ويكسر السن‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1384","bookId":"riyad","type":"hadith","num":1384,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عابس بن ربيعة قال‏:‏ رأيت عمر بن الخطاب ، رضي الله عنه ، يقبل الحجر -يعنى الأسود- ويقول‏:‏إني أعلم أنك حجر ما تنفع ولا تضر، ولولا أني رأيت رسول الله، صلى الله عليه وسلم، يقبلك ما قبلتك‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1385","bookId":"riyad","type":"hadith","num":1385,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة، رضي الله عنه ، قال‏:‏ لما نزلت على رسول الله، صلى الله عليه وسلم ‏:‏ ‏{‏ لله ما في السموات وما في الأرض وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله‏}‏ الآية ‏(‏‏(‏البقرة‏:‏283‏)‏‏)‏ أشتد ذلك على أصحاب رسول الله، صلى الله عليه وسلم، فأتوا رسول الله ، صلى الله عليه وسلم، ثم بركوا على الركب فقالوا‏:‏ أي رسول الله كلفنا من الأعمال مانطيق‏:‏ الصلاة والجهاد والصيام والصدقة، وقد أنزلت عليك هذه الآية ولا نطيقها‏.‏ قال رسول الله، صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أتريدون أن تقولوا كما قال‏:‏ أهل الكتابين من قبلكم‏:‏ سمعنا وعصينا‏؟‏ بل قولوا‏:‏ سمعنا وأطعنا غفرانك ربنا وإليك المصير‏\"‏ فلما اقترأها القوم، وذلت بها ألسنتهم؛ أنزل الله تعالى في إثرها‏:‏ ‏{‏آمن الرسول بما أنزل إليه من ربه والمؤمنون كل آمن بالله وملائكته وكتبه ورسله لا نفرق بين أحد من رسله وقالوا سمعنا وأطعنا غفرانك ربنا وإليك المصير‏}‏ فلما فعلوا ذلك نسخها الله تعالى؛ فأنزل الله عز وجل‏:‏ ‏{‏لايكلف الله نفسا إلا وسعها لها ما كسبت وعليها ما اكتسبت ، ربنا لا تؤاخذنا إن نسينا أو أخطأنا‏}‏ قال‏:‏ نعم ‏{‏ ربنا ولا تحمل علينا إصراً كما حملته على الذين من قبلنا ‏}‏ قال‏:‏ نعم ‏{‏ ربنا ولا تحملنا ما لا طاقة لنا به‏}‏ قال ‏:‏ نعم ‏{‏واعف عنا واغفر لنا وارحمنا أنت مولانا فانصرنا على القوم الكافرين ‏}‏ قال‏:‏ نعم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1386","bookId":"riyad","type":"hadith","num":1386,"kitab":"كتاب المقدمات","isnad":"عن عائشة، رضي الله عنها، قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من أحدث في أمرنا هذا ما ليس منه فهو رد‏\"‏ ‏(‏‏(‏ متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم ‏:‏ ‏\"‏من عمل عملاً ليس عليه أمرنا فهو رد‏\"‏‏.‏"},{"id":"riyad:1387","bookId":"riyad","type":"hadith","num":1387,"kitab":"كتاب المقدمات","isnad":"وعن جابر، رضي الله عنه ، كان رسول الله، صلى الله عليه وسلم، إذا خطب احمرت عيناه، وعلا صوته، واشتد غضبه، حتى كأنه منذر جيش يقول‏:‏ ‏","matn":"\"‏صبحكم ومساكم‏\"‏ ويقول‏:‏ ‏\"‏بعثت أنا والساعة كهاتين‏\"‏ ويقرن بين أصبعيه؛ السبابة والوسطى، ويقول‏:‏ ‏\"‏أما بعد؛ فإن خير الحديث كتاب الله وخير الهدى هدى محمد، صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلالة‏\"‏ ثم يقول‏:‏ ‏\"‏أنا أولى بكل مؤمن من نفسه‏.‏ من ترك مالاً فلأهله، ومن ترك ديناً أو ضياعاً فإلي وعلى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وعن العرباض بن سارية، رضي الله عنه ، حديثة السابق في باب المحافظة على السنة‏.‏"},{"id":"riyad:1388","bookId":"riyad","type":"hadith","num":1388,"kitab":"كتاب المقدمات","isnad":"عن أبي عمرو، جرير بن عبد الله، رضي الله عنه ، قال‏:‏ كنا في صدر النهار عند رسول الله، صلى الله عليه وسلم، فجاءه قوم عراة مجتابي النمار، أو العباء، متقلدي السيوف، عامتهم من مضر، بل كلهم من مضر؛ فتمعر وجه رسول الله، صلى الله عليه وسلم، لما رأى بهم من الفاقة؛ فدخل ثم خرج، فأمر بلالاً فأذن وأقام، فصلى ثم خطب؛ فقال‏:‏ ‏{‏يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة‏}‏ إلى آخر الآية‏:‏ ‏{‏إن الله كان عليكم رقيبا‏}‏، والآية الأخرى التي في آخر الحشر‏:‏ ‏{‏يا أيها الذين آمنوا اتقوا الله ولتنظر نفس ما قدمت لغد‏}‏ تصدق رجل من ديناره من درهمه من ثوبه من صاع بره من صاع تمره _حتى قال _ ولو بشق تمرة ‏,‏فجاء رجل من الأنصار بصرة كادت كفه تعجز عنها، بل قد عجزت، ثم تتابع الناس حتى رأيت كومين من طعام وثياب، حتى رأيت وجه رسول الله، صلى الله عليه وسلم، يتهلل كأنه مذهبة، فقال رسول الله، صلى الله عليه وسلم، ‏","matn":"\"‏ من سن في الإسلام سنة حسنة فله أجرها، وأجر من عمل بها من بعده من غير أن يقنص من أجورهم شيء، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعده من غير أن ينقص من أوزارهم شيء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1389","bookId":"riyad","type":"hadith","num":1389,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس من نفس تقتل ظلماً إلا كان على ابن آدم الأول كفل من دمها لأنه كان أول من سن القتل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1390","bookId":"riyad","type":"hadith","num":1390,"kitab":"كتاب المقدمات","isnad":"وعن أبي مسعود عقبة بن عمرو الأنصاري البدي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من دل على خير فله مثل أجر فاعله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1391","bookId":"riyad","type":"hadith","num":1391,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئاً، ومن دعا إلى ضلالة كان عليه من الإثم مثل آثام من تبعه لا ينقص ذلك من آثامهم شيئاً‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1392","bookId":"riyad","type":"hadith","num":1392,"kitab":"كتاب المقدمات","isnad":"وعن العباس سهل بن سعد الساعدي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال يوم خيبر‏:‏ ‏","matn":"\"‏لأعطين الراية غداً رجلا يفتح الله على يديه، يحب الله ورسوله، ويحبه الله ورسوله‏\"‏ فبات الناس يدوكون ليلتهم أيهم يعطاها‏.‏ فلما أصبح الناس غدوا على رسول الله صلى الله عليه وسلم‏:‏ كلهم يرجو أن يعطاها، فقال‏:‏ ‏\"‏أين علي بن أبى طالب‏؟‏‏\"‏ فقيل‏:‏ يا رسول الله هو يشتكي عينيه قال‏:‏ ‏\"‏فأرسلوا إليه‏\"‏ فأتي به ، فبصق رسول الله صلى الله عليه وسلم في عينيه، ودعا له، فبرأ حتى كأن لم يكن به وجع، فأعطاه الراية‏.‏ فقال علي رضي الله عنه ‏:‏ يا رسول الله أقاتلهم حتى يكونوا مثلنا‏؟‏ فقال‏:‏ ‏\"‏انفذ على رسلك حتى تنزل بساحتهم، ثم ادعهم إلى الإسلام، وأخبرهم بما يجب عليهم من حق الله تعالى فيه، فوالله لأن يهدي الله بك رجلاً واحداً خير لك من حمر النعم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1393","bookId":"riyad","type":"hadith","num":1393,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه أن فتى من أسلم قال‏:‏ يا رسول الله إني أريد الغزو وليس معي ما أتجهز به‏؟‏ قال‏:‏ ‏","matn":"\"‏ائت فلانا فإنه قد كان تجهز فمرض‏\"‏ فأتاه فقال‏:‏ إن رسول الله صلى الله عليه وسلم يقرئك السلام ويقول‏:‏ أعطني الذي تجهزت به، فقال‏:‏ يا فلانة أعطيه الذي تجهزت به، ولا تحبسي منه شيئاً ، فوالله لا تحبسين منه شيئاً فيبارك لك فيه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1394","bookId":"riyad","type":"hadith","num":1394,"kitab":"كتاب المقدمات","isnad":"عن أبي عبد الرحمن زيد بن خالد الجهني رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من جهز غازياً في سبيل الله فقد غزا ومن خلف غازيا في أهله بخير فقد غزا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1395","bookId":"riyad","type":"hadith","num":1395,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم، بعث بعثاً إلى بني لحيان من هذيل فقال‏:‏ ‏","matn":"\"‏ لينبعث من كل رجلين أحدهما والأجر بينهما‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1396","bookId":"riyad","type":"hadith","num":1396,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم لقي ركبا بالروحاء فقال ‏:‏ ‏","matn":"\"‏من القوم‏؟‏‏\"‏ قالوا‏:‏ المسلمون، فقالوا‏:‏ من أنت‏؟‏ قال‏:‏ ‏\"‏رسول الله‏\"‏ فرفعت إليه امرأة صبياً فقالت ‏:‏ ألهذا حج‏؟‏ قال‏:‏ ‏\"‏نعم ولك أجر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1397","bookId":"riyad","type":"hadith","num":1397,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري رضي الله عنه ، عن النبي صلى الله عليه وسلم أنه قال‏:‏ ‏","matn":"\"‏ الخازن المسلم الأمين الذي ينفذ ما أمر به، فيعطيه كاملاً موفراً، طيبة به نفسه فيدفعه إلى الذي أمر له به أحد المتصدقين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1398","bookId":"riyad","type":"hadith","num":1398,"kitab":"كتاب المقدمات","isnad":"فالأول‏:‏ عن أبي رقية تميم بن أوس الداري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ الدين النصيحة‏\"‏ قلنا‏:‏ لمن‏؟‏ قال‏:‏ لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1399","bookId":"riyad","type":"hadith","num":1399,"kitab":"كتاب المقدمات","isnad":"","matn":"الثاني‏:‏ عن جرير بن عبد الله رضي الله عنه قال‏:‏ بايعت رسول الله صلى الله عليه وسلم على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1400","bookId":"riyad","type":"hadith","num":1400,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن أنس رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1401","bookId":"riyad","type":"hadith","num":1401,"kitab":"كتاب المقدمات","isnad":"فالأول‏:‏ عن أبي سعيد الخدري رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏من رأى منكم منكرًا فليغيره بيده ، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1402","bookId":"riyad","type":"hadith","num":1402,"kitab":"كتاب المقدمات","isnad":"الثاني‏:‏ عن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما من نبي بعثه الله في أمة قبلي إلا كان له من أمته حواريون وأصحاب يأخذون بسنته ويقتدون بأمره، ثم إنها تختلف من بعدهم خلوف يقولون مالا يفعلون ويفعلون ما لا يؤمرون، فمن جاهدهم بيده فهو مؤمن، ومن جاهدهم بقلبه فهو مؤمن، ومن جاهدهم بلسانه فهو مؤمن ، وليس وراء ذلك الإيمان حبة خردل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1403","bookId":"riyad","type":"hadith","num":1403,"kitab":"كتاب المقدمات","isnad":"الثالث‏:‏ عن أبي الوليد عبادة بن الصامت رضي الله عنه قال‏:‏ “بايعنا رسول الله صلى الله عليه وسلم على السمع والطاعة في العسر واليسر والمنشط والمكره، وعلى أثرةٍ علينا، وعلى أن لا ننازع الأمر أهله إلا أن تروا كفرًا بواحًا عندكم من الله تعالى فيه برهان ، وعلى أن نقول بالحق أينما كنا لا نخاف في الله لومة لائم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏ ‏المنشط والمكره‏ ‏ بفتح ميميهما‏:‏ أي‏:‏ في السهل والصعب‏.‏ ‏ ‏والأثرة‏ ‏ ‏:‏ الاختصاص بالمشترك، وقد سبق بيانها‏.‏ ‏ ‏بواحًا‏ ‏ بفتح الباء الموحدة بعدها واو ثم ألف ثم حاء مهملة‏:‏ أي ظاهر لا يحتمل تأويلا."},{"id":"riyad:1404","bookId":"riyad","type":"hadith","num":1404,"kitab":"كتاب المقدمات","isnad":"الرابع‏:‏ عن النعمان بن بشير رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏مثل القائم على حدود الله والواقع فيها كمثل قوم استهموا على سفينة، فصار بعضهم أعلاها وبعضهم أسفلها، وكان الذين في أسفلها إذا استقوا من الماء مروا على من فوقهم فقالوا‏:‏ لو أنا خرقنا في نصيبنا خرقًا ولم نؤذ من فوقنا ‎، فإن تركوهم وما أرادوا هلكوا وهلكوا جميعًا، وإن أخذوا على أيديهم نجوا ونجوا جميعا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1405","bookId":"riyad","type":"hadith","num":1405,"kitab":"كتاب المقدمات","isnad":"الخامس‏:‏ عن أم المؤمنين أم سلمة هند بنت أبي أمية حذيفة رضي الله عنها، عن النبي صلى الله عليه وسلم أنه قال‏:‏ ‏","matn":"\"‏ إنه يستعمل عليكم أمراءُ فتعرفون وتنكرون فمن كره فقد برئ، ومن أنكر فقد سلم، ولكن من رضي وتابع” قالوا‏:‏ يا رسول الله ألا نقاتلهم‏؟‏ قال‏:‏ ‏\"‏لا ، الإمام أقاموا فيكم الصلاة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1406","bookId":"riyad","type":"hadith","num":1406,"kitab":"كتاب المقدمات","isnad":"السادس‏:‏ عن أم المؤمنين أم الحكم زينب بنت جحش رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها فزعا يقول‏:‏ ‏","matn":"\"‏لا إله إلا الله، ويل للعرب من شر قد اقترب، فتح اليوم من ردم يأجوج ومأجوج مثل هذه” وحلق بأصبعيه الإبهام والتي تليها‏.‏ فقلت‏:‏ يا رسول الله أنهلك وفينا الصالحون‏؟‏ قال‏:‏ ‏\"‏نعم إذا كثر الخبث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1407","bookId":"riyad","type":"hadith","num":1407,"kitab":"كتاب المقدمات","isnad":"السابع‏:‏ عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إياكم والجلوس في الطرقات‏\"‏ فقالوا ‏:‏ يا رسول الله ما لنا من مجالسنا بد؛ نتحدث فيها‏!‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏فإذا أبيتم إلا المجلس فأعطوا الطريق حقه‏\"‏ قالوا‏:‏ وما حق الطريق يا رسول الله‏؟‏ قال‏:‏ ‏\"‏غض البصر وكف الأذى ورد السلام، والأمر بالمعروف ، والنهي عن المنكر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1408","bookId":"riyad","type":"hadith","num":1408,"kitab":"كتاب المقدمات","isnad":"الثامن ‏:‏ عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم رأى خاتمًا من ذهب في يد رجل، فنزعه فطرحه وقال‏:‏ ‏","matn":"\"‏ يعمد أحدكم إلى جمرة من نار فيجعلها في يده ‏!‏‏\"‏ فقيل للرجل بعد ما ذهب رسول الله صلى الله عليه وسلم ‏:‏ خذ خاتمك؛ انتفع به‏.‏ قال‏:‏ لا والله لا آخذه أبدًا وقد طرحه رسول الله صلى الله عليه وسلم‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1409","bookId":"riyad","type":"hadith","num":1409,"kitab":"كتاب المقدمات","isnad":"التاسع‏:‏ عن أبي سعيد الحسن البصري أن عائذ بن عمرو رضي الله عنه دخل على عبيد الله بن زياد فقال‏:‏ أي بني، إني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن شر الرعاء الحطمة” فإياك أن تكون منهم‏.‏ فقال له ‏:‏ اجلس فإنما أنت من نخالة أصحاب محمد صلى الله عليه وسلم ، فقال‏:‏ وهل كانت لهم نخالة، إنما كانت النخالة بعدهم وفي غيرهم ‏!‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1410","bookId":"riyad","type":"hadith","num":1410,"kitab":"كتاب المقدمات","isnad":"العاشر‏:‏ عن حذيفة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ والذي نفسي بيده لتأمرن بالمعروف، ولتنهون عن المنكر، أو ليوشكن الله أن يبعث عليكم عقابًا منه، ثم تدعونه فلا يستجاب لكم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1411","bookId":"riyad","type":"hadith","num":1411,"kitab":"كتاب المقدمات","isnad":"الحادي عشر‏:‏ عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أفضل الجهاد كلمة عدل عند سلطان جائر‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1412","bookId":"riyad","type":"hadith","num":1412,"kitab":"كتاب المقدمات","isnad":"الثاني عشر‏:‏ عن أبي عبد الله طارق بن شهاب البجلي الأحمسي رضي الله عنه أن رجلاً سأل النبي صلى الله عليه وسلم، وقد وضع رجله في الغرز‏:‏ أي الجهاد أفضل‏؟‏ قال‏:‏ “كلمة حق عند سلطان جائر‏","matn":"\"‏ ‏(‏‏(‏رواه النسائي بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1413","bookId":"riyad","type":"hadith","num":1413,"kitab":"كتاب المقدمات","isnad":"الثالث عشر‏:‏ عن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏إن أول ما دخل النقص على بني إسرائيل أنه كان الرجل يلقى الرجل فيقول‏:‏ يا هذا اتق الله ودع ما تصنع فإنه لا يحل لك، ثم يلقاه من الغد وهو على حاله، فلا يمنعه ذلك أن يكون أكيله وشريبه وقعيده، فلما فعلوا ذلك ضرب الله قلوب بعضهم ببعض‏\"‏ ثم قال‏:‏ ‏{‏لعن الذين كفروا من بني إسرائيل على لسان داود وعيسى ابن مريم ذلك بما عصوا وكانوا يعتدون‏.‏ كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون‏.‏ ترى كثيرًا منهم يتولون الذين كفروا لبئس ما قدمت لهم أنفسهم ‏}‏ إلى قوله‏:‏ ‏{‏فاسقون‏}‏ ‏(‏‏(‏المائد‏:‏ 78،81‏)‏‏)‏ ثم قال‏:‏ ‏\"‏ كلا، والله لتأمرن بالمعروف ولتنهون عن المنكر، ولتأخذن على يد الظالم ولتأطرنه على الحق أطرا، ولتقصرنه على الحق قصرا، أو ليضربن الله بقلوب بعضكم على بعض، ثم ليلعننكم كما لعنهم‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ هذا لفظ أبي داود، ولفظ الترمذي‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏ ‏لما وقعت بنو إسرائيل في المعاصي نهتهم علماؤهم فلم ينتهوا، فجالسوهم في مجالسهم وواكلوهم وشاربوهم، فضرب الله قلوب بعضهم ببعض، ولعنهم على لسان داود وعيسى ابن مريم ذلك بما عصوا وكانوا يعتدون‏ ‏ فجلس رسول الله صلى الله عليه وسلم، وكان متكئًا فقال‏:‏ ‏ ‏لا والذي نفسي بيده حتى تأطروهم على الحق أطرا‏ ‏‏.‏ قوله‏:‏ ‏ ‏تأطروهم‏ ‏ أي تعطفوهم‏.‏ ‏ ‏ ولتقصرنه‏ ‏ أي لتحبسنه‏.‏"},{"id":"riyad:1414","bookId":"riyad","type":"hadith","num":1414,"kitab":"كتاب المقدمات","isnad":"الرابع عشر‏:‏ عن أبي بكر الصديق، رضي الله عنه ، قال‏:‏ يا أيها الناس إنكم لتقرءون هذه الآية‏:‏ ‏{‏يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم‏}‏ ‏(‏‏(‏المائدة ‏:‏ 105‏)‏‏)‏ وإني سمعت رسول الله، صلى الله عليه وسلم، يقول‏:‏ “إن الناس إذا رأو الظالم فلم يأخذوا على يديه أوشك أن يعمهم الله بعقاب منه‏","matn":"\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي، والنسائي بأسانيد صحيحة‏)‏‏)‏‏.‏"},{"id":"riyad:1415","bookId":"riyad","type":"hadith","num":1415,"kitab":"كتاب المقدمات","isnad":"وعن أبي زيد أسامة بن زيد بن حارثة، رضي الله عنهما، قال‏:‏ سمعت رسول الله، صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏يؤتى بالرجل يوم القيامة فيلقى في النار فتندلق أقتاب بطنه فيدور بها كما يدور الحمار في الرحى فيجتمع إليه أهل النار فيقولون‏:‏ يا فلان ما لك ‏؟‏ ألم تك تأمر بالمعروف وتنهى عن المنكر‏؟‏ فيقول‏:‏ بلى، كنت آمر بالمعروف ولا آتيه، وأنهى عن المنكر وآتيه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏قوله‏:‏ ‏ ‏تندلق‏ ‏ هو بالدال المهملة، ومعناه تخرج‏.‏ و”الأقتاب”‏:‏ الأمعاء، واحدها قتب‏."},{"id":"riyad:1416","bookId":"riyad","type":"hadith","num":1416,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة ، رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال‏:‏ “آية المنافق ثلاث‏:‏ إذا حدث كذب، وإذا وعد أخلف، وإذا أؤتمن خان‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1417","bookId":"riyad","type":"hadith","num":1417,"kitab":"كتاب المقدمات","isnad":"وعن حذيفة بن اليمان‏.‏ رضي الله عنه ، قال‏:‏ حدثنا رسول الله، صلى الله عليه وسلم، حديثين قد رأيت أحدهما، وأنا أنتظر الآخر‏:‏ حدثنا أن الأمانة نزلت في جذر قلوب الرجال، ثم نزل القرآن فعلموا من القرآن، وعلموا من السنة، ثم حدثنا عن رفع الأمانة فقال‏:‏ ‏","matn":"\"‏ينام الرجل النومة فتقبض الأمانة من قلبه، فيظل أثرها مثل الوكت، ثم ينام النومة فتبض الأمانة من قلبه، فيظل أثرها مثل أثر المجل، كجمر دحرجته على رجلك، فنفط فتراه منتبرًا وليس فيه شيء ‏\"‏ ثم أخذ حصاة فدحرجه على رجله ‏\"‏فيصبح الناس يتبايعون، فلا يكاد أحد يؤدي الأمانة حتى يقال‏:‏” إن في بني فلان رجلاً أمينًا، حتى يقال للرجل، ما أجلده ما أظرفه، ما أعقله‏!‏ وما في قلبه مثقال حبة من خردل من إيمان ‏.‏ ولقد أتى علي زمان وما أبالي أيكم بايعت؛ لئن كان مسلمًا ليردنه علي دينه، ولئن كان نصرانيا أو يهودياً ليردنه علي ساعيه، وأما اليوم فما كنت أبايع منكم إلا فلانًا و فلانًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1418","bookId":"riyad","type":"hadith","num":1418,"kitab":"كتاب المقدمات","isnad":"وعن حذيفة، وأبي هريرة، رضي الله عنهما ، قالا‏:‏ قال رسول الله، صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏يجمع الله، تبارك وتعالى الناس، فيقوم المؤمنون حتى تزلف لهم الجنة، فيأتون آدم، صلوات الله عليه، فيقولون‏:‏ يا أبانا استفتح لنا الجنة، فيقول‏:‏ وهل أخرجكم من الجنة إلا خطيئة أبيكم ‏!‏ لست بصاحب ذلك، اذهبوا إلى ابني إبراهيم خليل الله، قال‏:‏ فيأتون إبراهيم، فيقول إبراهيم‏:‏ لست بصاحب ذلك ، اذهبوا إلى موسى الذي كلمه الله تكليمًا، فيأتون موسى، فيقول‏:‏ لست بصاحب ذلك؛ اذهبوا إلى عيسى كلمة الله وروحه‏.‏ فيقول عيسى‏:‏ لست بصاحب ذلك‏.‏ فيأتون محمدًا صلى الله عليه وسلم، فيقوم فيؤذن له، وترسل الأمانة والرحم فتقومان جنبتي الصراط يمينًا وشمالاً، فيمر أولكم كبالبرق‏\"‏ قلت‏:‏ بأبي وأمي، أي شيء كمر البرق‏؟‏ قال‏:‏ “ألم تروا كيف يمر ويرجع في طرفة عين‏؟‏ ثم كمر الريح، ثم كمر الطير، وأشد الرجال تجري بهم أعمالهم، ونبيكم قائم على الصراط يقول‏:‏‏\"‏ رب سلم سلم، حتى تعدز أعمال العباد، حتى يجيء الرجل لا يستطيع السير إلا زحفاً، وفي حافتي الصراط كلاليب معلقة مأمورة بأخذ من أمرت به، فمخدوش ناج، ومكردس في النار‏\"‏ والذي نفس أبي هريرة بيده إن قعر جهنم لسبعون خريفًا‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1419","bookId":"riyad","type":"hadith","num":1419,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي خُبيب -بضم الخاء المعجمة- عبد الله بن الزبير، رضي الله عنهما، قال‏:‏ لما وقف الزبير يوم الجمل دعاني فقمت إلى جنبه، فقال‏:‏ يا بني إنه لا يقتل اليوم إلا ظالم أو مظلوم ،وإني لا أرانى إلا سأقتل اليوم مظلوما، وإن من أكبر همي لديني، أفترى ديننا يبقي من مالنا شيئًا‏؟‏ ثم قال‏:‏ يا بني بع مالنا واقض ديني، وأوصى بالثلث وثلثه لبنيه، يعني لبني عبد الله بن الزبير ثلث الثلث‏.‏ قال فإن فضل من مالنا بعد قضاء الدين شيء فثلثه لبنيك ، قال هشام ‏:‏ وكان بعض ولد عبد الله قد وازى بعض بني الزبير خبيب وعباد، وله يومئذ تسعة بنين وتسع بنات‏.‏ قال عبد الله ‏:‏ فجعل يوصيني بدينه ويقول‏:‏ يا بنى إن عجزت عن شيء منه فاستعن عليه بمولاي‏.‏ قال فوالله ما دريت ما أراد حتى قلت‏:‏ يا أبت من مولاك‏؟‏ قال‏:‏ الله‏.‏ قال‏:‏ فوالله ما وقعت في كربةٍ من دينه إلا قلت‏:‏ يا مولى الزبير اقض عنه دينه، فيقضيه‏.‏ قال‏:‏ فقتل الزبير ولم يدع دينارًا ولا درهمًا إلا أرضين، منهما الغابة وإحدى عشرة دارًا بالمدينة، ودارين بالبصرة، ودارًا بالكوفة ودارًا بمصر‏.‏ قال‏:‏ وإنما كان دينه الذي كان عليه أن الرجل كان يأتيه بالمال، فيستودعه إياه، فيقول الزبير‏:‏ لا ولكن هو سلف إني أخشى عليه الضيعة‏.‏ وما ولي إمارة قط ولا جباية ولا خراجًا ولا شيئًا إلا أن يكون في غزو مع رسول الله صلى الله عليه وسلم، أو مع أبي بكر وعمر وعثمان رضي الله عنهم، قال عبد الله‏:‏ فحسبت ما كان عليه من الدين فوجدته ألفي ألف ومائتي ألف‏!‏ فلقى حكيم بن حزام عبد الله بن الزبير فقال‏:‏ يا ابن أخي كم على أخي من الدين‏؟‏ فكتمته وقلت ‏:‏ مائة ألف‏.‏ فقال حكيم‏:‏ والله ما أرى أموالكم تسع هذه ‏!‏ فقال عبد الله‏:‏ أرأيتك إن كانت ألف ألف‏؟‏ ومائتي ألف‏؟‏ قال‏:‏ ما أراكم تطيقون هذا، فإن عجزتم عن شيء منه فاستعينوا بي‏.‏ قال‏:‏ وكان الزبير قد اشترى الغابة بسبعين ومائة ألف، فباعها عبد الله بألف ألف وستمائة ألف ، ثم قام فقال‏:‏ من كان له على الزبير شيء فليوافنا بالغابة، فأتاه عبد الله بن جعفر، وكان له على الزبير أربعمائة ألف، فقال لعبد الله‏:‏ إن شئتم تركتها لكم‏؟‏ قال عبد الله‏:‏ لا، قال‏:‏ فإن شئتم جعلتموها فيما تؤخرون إن أخرتم، فقال عبد الله‏:‏ لا قال‏:‏ فاقطعوا لي قطعة، قال عبد الله‏:‏ لك من ههنا إلى ههنا‏.‏ فباع عبد الله منها، فقضى عنه دينه، وأوفاه وبقي منها أربعة أسهم ونصف، فقدم على معاوية وعنده عمرو بن عثمان، والمنذر بن الزبير، وابن زمعة فقال له معاوية‏:‏ كم قومت الغابة‏؟‏ قال ‏:‏ كل سهم بمائة ألف قال‏:‏ كم بقي منها‏؟‏ قال‏:‏ أربعة أسهم ونصف، فقال المنذر ابن الزبير‏:‏ قد أخذت منها سهمًا بمائة ألف، قال عمرو بن عثمان‏:‏ قد أخذت منها سهمًا بمائة ألف‏.‏ وقال ابن زمعة‏:‏ قد أخذت سهمًا بمائة ألف، فقال معاوية‏:‏ كم بقي منها‏؟‏ قال‏:‏ سهم ونصف سهم، قال‏:‏ قد أخذته بخمسين ومائة ألف ‏.‏ قال‏:‏ وباع عبد الله بن جعفر نصيبه من معاوية بستمائة ألف‏.‏ فلما فرغ ابن الزبير من قضاء دينه قال بنو الزبير ‏:‏ اقسم بيننا ميراثنا‏.‏ قال‏:‏ ‏:‏ والله لا أقسم بينكم حتى أنادي بالموسم أربع سنين ‏:‏ ألا من كان له على الزبير دين فليأتنا فلنقضه‏.‏ فجعل كل سنة ينادي في الموسم، فلما مضى أربع سنين قسم بينهم ودفع الثلث‏.‏ وكان للزبير أربع نسوة، فأصاب كل امراةٍ ألف ألف ومائتا ألف، فجميع ماله خمسون ألف ألف ومائتا ألف، رواه البخاري‏.‏"},{"id":"riyad:1420","bookId":"riyad","type":"hadith","num":1420,"kitab":"كتاب المقدمات","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏اتقوا الظلم، فإن الظلم ظلمات يوم القيامة، واتقوا الشح فإن الشح أهلك من كان قبلكم، حملهم على أن سفكوا دماءهم واستحلوا محارمهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1421","bookId":"riyad","type":"hadith","num":1421,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لتؤدن الحقوق إلى أهلها يوم القيامة حتى يقاد للشاة الجلحاء من الشاة القرناء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1422","bookId":"riyad","type":"hadith","num":1422,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كنا نتحدث عن حجة الوداع، والنبي صلى الله عليه وسلم بين أظهرنا، ولا ندري ما حجة الوداع، حتى حمد الله رسول الله صلى الله عليه وسلم، وأثنى عليه، ثم ذكر المسيح الدجال فأطنب في ذكره، وقال‏:‏ “ ما بعث الله من نبي إلا أنذره أمته‏:‏ أنذره نوح والنبيون من بعده، وإنه إن يخرج فيكم فما خفي عليكم من شأنه فليس يخفى عليكم، إن ربكم ليس بأعور، وإنه أعور عين اليمنى، كأن عينه عنبة طافية‏.‏ ألا إن الله حرم عليكم دماءكم وأموالكم ، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلغت‏؟‏” قالوا‏:‏ نعم، قال‏:‏ “اللهم اشهد -ثلاثًا- ويلكم، أو ويحكم، انظروا، لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري ، وروي مسلم بعضه‏)‏‏)‏‏.‏"},{"id":"riyad:1423","bookId":"riyad","type":"hadith","num":1423,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “من ظلم قيد شبر من الأرض طوقه من سبع أرضين” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1424","bookId":"riyad","type":"hadith","num":1424,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ “إن الله ليملي للظالم فإذا أخذه لم يفلته ثم قرأ‏:‏ ‏{‏وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة إن أخذه أليم شديد‏}‏ ‏(‏‏(‏هود ‏:‏ 102‏)‏‏)‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1425","bookId":"riyad","type":"hadith","num":1425,"kitab":"كتاب المقدمات","isnad":"وعن معاذ رضي الله عنه قال ‏:‏ بعثني رسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏إنك تأتي قومًا من أهل الكتاب، فادعهم إلى شهادة أن لا إله إلا الله، وأني رسول الله ، فإن هم أطاعوا لذلك، فأعلمهم أن الله قد افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك، فإياك وكرائم أموالهم‏.‏ واتق دعوة المظلوم فإنه ليس بينها وبين الله حجاب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1426","bookId":"riyad","type":"hadith","num":1426,"kitab":"كتاب المقدمات","isnad":"وعن أبي حميد عبد الرحمن بن سعد الساعدي رضي الله عنه قال‏:‏ استعمل النبي رجلاً من الأزد يقال له‏:‏ ابن اللتبية على الصدقة، فلما قدم قال ‏:‏ هذا لكم، وهذا أهدي إلي، فقام رسول الله صلى الله عليه وسلم على المنبر، فحمد الله وأثنى عليه، ثم قال‏:‏ “أما بعد فإني أستعمل الرجل منكم على العمل مما ولاني الله، فيأتي فيقول‏:‏ هذا لكم، وهذا هدية أهديت إلي، أفلا جلس في بيت أبيه وأمه حتى تأتيه هديته إن كان صادقًا، والله لا يأخذ أحد منكم شيئًا بغير حقه إلا لقى الله تعالى، يحمله يوم القيامة، فلا أعرفن أحدًا منكم لقي الله يحمل بعيرًا له رغاء، أو بقرة لها خوار، أو شاة تيعر” ثم رفع يديه حتى رؤي بياض إبطيه فقال ‏:‏ ‏","matn":"\"‏اللهم هل بلغت‏\"‏ ثلاثا ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1427","bookId":"riyad","type":"hadith","num":1427,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من كانت عنده مظلمة لأخيه، من عرضه أو من شيء، فليتحلله منه اليوم قبل أن لا يكون دينار ولا درهم ، إن كان له عمل صالح أخذ منه بقدر مظلمته، وإن لم يكن له حسنات أخذ من سيئات صاحبه فحمل عليه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1428","bookId":"riyad","type":"hadith","num":1428,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏","matn":"‏ “المسلم من سلم المسلمون من لسانه، ويده، والمهاجر من هجر ما نهى الله عنه” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1429","bookId":"riyad","type":"hadith","num":1429,"kitab":"كتاب المقدمات","isnad":"وعنه رضي الله عنه قال‏:‏ كان على ثقل النبي صلى الله عليه وسلم رجل يقال له كركرة، فمات، فقال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏هو في النار‏\"‏ فذهبوا ينظرون إليه فوجدوا عباءة قد غلها” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1430","bookId":"riyad","type":"hadith","num":1430,"kitab":"كتاب المقدمات","isnad":"وعن أبي بكرة نفيع بن الحارث رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الزمان قد استدار كهيئته يوم خلق الله السموات والأرض‏:‏ السنة اثنا عشر شهرًا، منها أربعة حرم‏:‏ ثلاث متواليات‏:‏ ذو القعدة، وذو الحجة، والمحرم، ورجب مضر الذي بين جمادى وشعبان، أي شهر هذا‏؟‏‏\"‏ قلنا‏:‏ الله ورسوله أعلم، فسكت حتى ظننا أنه سيسميه بغير اسمه، قال‏:‏ أليس ذا الحجة‏؟‏ قلنا بلى‏.‏ قال‏:‏ ‏\"‏فأي بلد هذا‏؟‏‏\"‏ قلنا ‏:‏ الله ورسوله أعلم فسكت حتى ظننا أنه سيسميه بغير اسمه‏.‏ قال‏:‏”أليس البلدة” قلنا‏:‏ بلى ‏.‏ قال‏:‏ ‏\"‏فأي يوم هذا‏؟‏‏\"‏ قلنا‏:‏ الله ورسوله أعلم، فسكت حتى ظننا أن سيسميه بغير اسمه‏.‏ قال‏:‏ “أليس يوم النحر‏؟‏” قلنا بلى‏.‏ قال “فإن دماءكم وأموالكم وأعراضكم عليكم حرام، كحرمة يومكم هذا في بلدكم هذا في شهركم هذا، وستلقون ربكم فيسألكم عن أعمالكم، ألا فلا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض، ألا ليبلغ الشاهد الغائب، فلعل بعض من يبلغه أن يكون أوعى له من بعض من سمعه‏\"‏ ثم قال‏:‏ ‏\"‏ ألا هل بلغت، ألا هل بلغت‏؟‏” قلنا ‏:‏ نعم‏.‏ قال‏:‏ “ اللهم اشهد” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1431","bookId":"riyad","type":"hadith","num":1431,"kitab":"كتاب المقدمات","isnad":"وعن أبي أمامة إياس بن ثعلبة الحارثي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من اقتطع حق امرئ مسلم بيمينه فقد أوجب الله له النار، وحرم عليه الجنة” فقال رجل‏:‏ وإن كان شيئًا يسيرًا يا رسول الله ‏؟‏ فقال‏:‏ “وإن قضيبًا من أراك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1432","bookId":"riyad","type":"hadith","num":1432,"kitab":"كتاب المقدمات","isnad":"وعن عدي ابن عميرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “من استعملناه منكم على عمل، فكتمنا مخيطًا فما فوقه، كان غلولاً يأتي به يوم القيامة” فقام إليه رجل أسود من الأنصار، كأني أنظر إليه ، فقال‏:‏ يا رسول الله اقبل عني عملك، قال‏:‏ “ومالك‏؟‏” قال سمعتك تقول كذا وكذا، قال‏:‏ “وأنا أقوله الآن‏:‏ من استعملناه على عمل فليجئ بقليله وكثيره، فما أوتي منه أخذ، وما نهي عنه انتهى، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1433","bookId":"riyad","type":"hadith","num":1433,"kitab":"كتاب المقدمات","isnad":"وعن عمر بن الخطاب رضي الله عنه قال‏:‏ لما كان يوم خيبر أقبل نفر من أصحاب النبي صلى الله عليه وسلم فقالوا فلان شهيد، وفلان شهيد، حتى مروا على رجل فقالوا ‏:‏ فلان شهيد‏.‏ فقال النبي صلى الله عليه وسلم","matn":"‏:‏ كلا إني رأيته في النار في بردة غلها-أو عباءة-” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1434","bookId":"riyad","type":"hadith","num":1434,"kitab":"كتاب المقدمات","isnad":"وعن أبي قتادة الحارث بن ربعي رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قام فيهم ، فذكر لهم أن الجهاد في سبيل الله، والإيمان بالله أفضل الأعمال، فقام رجل فقال‏:‏ يا رسول الله أرأيت إن قتلت في سبيل الله، تكفر عني خطاياي‏؟‏ فقال له رسول الله صلى الله عليه وسلم‏:‏ “نعم إن قتلت في سبيل الله وأنت صابر محتسب، مقبل غير مدبر” ثم قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “كيف قلت‏؟‏” قال‏:‏ أرأيت إن قتلت في سبيل الله، أتكفر عني خطاياي‏؟‏ فقال رسول الله صلى الله عليه وسلم‏:‏ “نعم وأنت صابر محتسب، مقبل غير مدبر، إلا الدين فإن جبريل قال لي ذلك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1435","bookId":"riyad","type":"hadith","num":1435,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏‏:‏أتدرون من المفلس‏؟‏‏\"‏ قالوا ‏:‏ المفلس فينا من لا درهم له ولا متاع فقال‏:‏ ‏\"‏إن المفلس من أمتي يأتي يوم القيامة بصلاة وصيام وزكاة، ويأتي قد شتم هذا، وقذف هذا وأكل مال هذا، وسفك دم هذا، وضرب هذا، فيعطى هذا من حسناته، وهذا من حسناته، فإن فنيت حسناته قبل أن يقضي ما عليه، أخذ من خطاياهم فطرحت عليه، ثم طرح في النار‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1436","bookId":"riyad","type":"hadith","num":1436,"kitab":"كتاب المقدمات","isnad":"وعن أم سلمة رضي الله عنها، أن رسول الله صلى الله عليه وسلم قال‏:‏","matn":"\"إنما أنا بشر، وإنكم تختصمون إلي، ولعل بعضكم أن يكون ألحن بحجته من بعض، فأقضي له بنحو ما أسمع ، فمن قضيت له بحق أخيه فإنما أقطع له قطعة من النار\" ‏(‏‏(‏متفق عليه‏)‏‏)"},{"id":"riyad:1437","bookId":"riyad","type":"hadith","num":1437,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “ لا يزال المؤمن في فسحة من دينه ما لم يصب دمًا حرًا‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1438","bookId":"riyad","type":"hadith","num":1438,"kitab":"كتاب المقدمات","isnad":"وعن خولة بنت عامر الأنصاري ، وهي امرأة حمزة رضي الله عنه وعنها، قالت ‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن رجالاً يتخوضون في مال الله بغير حق، فلهم النار يوم القيامة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1439","bookId":"riyad","type":"hadith","num":1439,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ المؤمن للمؤمن كالبنيان يشد بعضه بعضًا‏\"‏ وشبك بين أصابعه ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1440","bookId":"riyad","type":"hadith","num":1440,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ “من مر في شيء من مساجدنا، أو أسواقنا، ومعه نبل فليمسك، أو ليقبض على نصالها بكفه أن يصيب أحدًا من المسلمين منها بشيء” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1441","bookId":"riyad","type":"hadith","num":1441,"kitab":"كتاب المقدمات","isnad":"وعن النعمان بن بشير رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ مثل المؤمنين في توادهم وتراحمهم وتعاطفهم، مثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1442","bookId":"riyad","type":"hadith","num":1442,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة رضي الله عنه قال‏:‏ قبل النبي الحسن بن علي رضي الله عنهما، وعنده الأقرع بن حابس، فقال الأقرع‏:‏ إن لي عشرة من الولد ما قبلت منهم أحدًا‏.‏ فنظر إليه رسول الله صلى الله عليه وسلم فقال‏:‏ “من لا يرحم لا يرحم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1443","bookId":"riyad","type":"hadith","num":1443,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قدم ناس من الأعراب على رسول الله صلى الله عليه وسلم، فقالوا ‏:‏ أتقبلون صبيانكم‏؟‏ فقال‏:‏ ‏","matn":"\"‏نعم‏\"‏ قالوا‏:‏ لكنا والله ما نقبل ‏!‏ فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏أو أملك إن كان الله نزع من قلوبكم الرحمة‏؟‏‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1444","bookId":"riyad","type":"hadith","num":1444,"kitab":"كتاب المقدمات","isnad":"وعن جرير بن عبد الله رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ من لا يرحم الناس لا يرحمه الله ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1445","bookId":"riyad","type":"hadith","num":1445,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا صلى أحدكم للناس، فليخفف، فإن فيهم الضعيف والسقيم والكبير‏.‏ وإذا صلى لنفسه فليطول ما شاء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ (10)"},{"id":"riyad:1446","bookId":"riyad","type":"hadith","num":1446,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ إن كان رسول الله صلى الله عليه وسلم ليدع العمل، وهو يحب أن يعمل به، خشية أن يعمل به الناس فيفرض عليهم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1447","bookId":"riyad","type":"hadith","num":1447,"kitab":"كتاب المقدمات","isnad":"وعنها رضي الله عنها قالت‏:‏ نهاهم النبي صلى الله عليه وسلم عن الوصال رحمة لهم، فقالوا‏:‏ إنك تواصل‏؟‏ قال‏:‏ ‏","matn":"\"‏إني لست كهيئتكم، إني أبيت يطعمني ربي ويسقيني ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏.‏ ‏‏معناه يجعل في قوة من أكل وشرب."},{"id":"riyad:1448","bookId":"riyad","type":"hadith","num":1448,"kitab":"كتاب المقدمات","isnad":"وعن أبي قتادة الحارث بن ربعي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إني لأقوم إلى الصلاة، وأريد أن أطول فيها ، فأسمع بكاء الصبي، فأتجوز في صلاتي كراهية أن أشق على أمه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1449","bookId":"riyad","type":"hadith","num":1449,"kitab":"كتاب المقدمات","isnad":"وعن جندب بن عبد الله قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من صلى صلاة الصبح فهو في ذمة الله فلا يطلبنكم الله من ذمته بشيء، فإنه من يطلبه من ذمته بشيء يدركه، ثم يكبه على وجهه في نار جهنم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1450","bookId":"riyad","type":"hadith","num":1450,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏المسلم أخو المسلم، لا يظلمه، ولايسلمه، من كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله يوم القيامة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1451","bookId":"riyad","type":"hadith","num":1451,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “المسلم أخو المسلم لا يخونه ولا يكذبه ولا يخذله، كل المسلم على المسلم حرام عرضه وماله ودمه، التقوى ههنا، بحسب امرئ من الشر أن يحقر أخاه المسلم” ‏(‏‏(‏رواه الترمذي وقال ‏:‏حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1452","bookId":"riyad","type":"hadith","num":1452,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"لا تحاسدوا، ولا تناجشوا، ولا تباغضوا، ولا تدابروا ولا يبع بعضكم على بيع بعض، وكونوا عباد الله إخوانًا‏.‏ المسلم أخو المسلم‏:‏ لا يظلمه ولا يحقره، ولا يخذله‏.‏ التقوى ههنا- ويشير إلى صدره ثلاث مرات- بحسب امرئ من الشر أن يحقر أخاه المسلم كل المسلم على المسلم حرام دمه وماله وعرضه” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1453","bookId":"riyad","type":"hadith","num":1453,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1454","bookId":"riyad","type":"hadith","num":1454,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “انصر أخاك ظالمًا أو مظلومًا” فقال رجل‏:‏ يا رسول الله أنصره إذا كان مظلومًا أرأيت إن كان ظالمًا كيف أنصره‏؟‏ قال‏:‏ ‏","matn":"\"‏تحجزه -أو تمنعه- من الظلم فإن ذلك نصره” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1455","bookId":"riyad","type":"hadith","num":1455,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏حق المسلم على المسلم خمس‏:‏ رد السلام، وعيادة المريض، واتباع الجنائز وإجابة الدعوة، وتشميت العاطس‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ و في رواية لمسلم: \"حق المسلم على المسلم ست: اذا لقيته فسلم عليه، و اذا دعاك فأجبه، و اذا استنصحك فانصح له، و اذا عطس فحمد الله فشمته، و اذا مرض فعده، و اذا مات فاتبعه.\""},{"id":"riyad:1456","bookId":"riyad","type":"hadith","num":1456,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي عمارة البراء بن عازب رضي الله عنهما قال‏:‏ أمرنا رسول الله r بسبع، ونهانا عن سبع‏:‏ أمرنا بعيادة المريض، واتباع الجنازة، وتشميت العاطس، وإبرار المقسم، ونصر المظلوم، وإجابة الداعي، وإفشاء السلام‏.‏ ونهانا عن خواتيم أو تختم بالذهب ، وعن شرب بالفضة، وعن المياثر الحمر، وعن القسي، وعن لبس الحرير والإستبرق والديباج‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1457","bookId":"riyad","type":"hadith","num":1457,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا يستر عبد عبدًا في الدنيا إلا ستره الله يوم القيامة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1458","bookId":"riyad","type":"hadith","num":1458,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏كل أمتي معافًى إلا المجاهرين، وإن من المجاهرة أن يعمل الرجل بالليل عملاً، ثم يصبح وقد ستره الله عليه فيقول‏:‏ يا فلان عملت البارحة كذا وكذا، وقد بات يستره ربه، ويصبح يكشف ستر الله عنه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1459","bookId":"riyad","type":"hadith","num":1459,"kitab":"كتاب المقدمات","isnad":"وعنه النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا زنت الأمة فتبين زناها فليجلدها الحد، ولا يثرب عليها، ثم إن زنت الثانية فليجلدها الحد ولا يثرب عليها، ثم إن زنت الثالثة فليبعها ولو بحبل من شعر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ (15)"},{"id":"riyad:1460","bookId":"riyad","type":"hadith","num":1460,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ أتى النبي صلى الله عليه وسلم برجل قد شرب خمرًا قال‏:‏ ‏","matn":"\"‏اضربوه‏\"‏ قال أبو هريرة ‏:‏ فمنا الضارب بيده، والضارب بنعله، والضارب بثوبه‏.‏ فلما انصرف قال بعض القوم‏:‏ أخزاك الله قال‏:‏ ‏\"‏لا تقولوا هكذا لا تعينوا عليه الشيطان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1461","bookId":"riyad","type":"hadith","num":1461,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏المسلم أخو المسلم لا يظلمه ولا يسلمه‏.‏ من كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله يوم القيامة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1462","bookId":"riyad","type":"hadith","num":1462,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من نفس عن مؤمن كربة من كرب الدنيا، نفس الله عنه كربة من كرب يوم القيامة، ومن يسر على معسر يسر الله عليه في الدنيا والآخرة، ومن ستر مسلمًا ستره الله في الدنيا والآخرة، والله في عون العبد ما كان العبد في عون أخيه، ومن سلك طريقًا يلتمس فيه علمًا سهل الله له طريقًا إلى الجنة‏.‏ وما اجتمع قوم في بيت من بيوت الله تعالى، يتلون كتاب الله، ويتدارسونه بينهم إلا نزلت عليهم السكينة، وغشيتهم الرحمة، وحفتهم الملائكة، وذكرهم الله فيمن عنده‏.‏ ومن بطأ به عمله لم يسرع به نسبه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1463","bookId":"riyad","type":"hadith","num":1463,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري رضي الله عنه قال‏:‏ كان النبي صلى الله عليه وسلم إذا أتاه طالب حاجة أقبل على جلسائه فقال‏:‏ ‏:‏اشفعوا تؤجروا ويقضي الله على لسان نبيه ما أحب‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (16)"},{"id":"riyad:1464","bookId":"riyad","type":"hadith","num":1464,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما في قصة بريرة وزوجها‏.‏ قال‏:‏ قال لها النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لو راجعته‏؟‏‏\"‏ قالت‏:‏ يا رسول الله تأمرني‏؟‏ قال ‏:‏ ‏\"‏إنما أشفع‏\"‏ قالت‏:‏ لا حاجة لي فيه‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1465","bookId":"riyad","type":"hadith","num":1465,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏كل سلامى من الناس عليه صدقة، كل يوم تطلع فيه الشمس‏:‏ تعدل بين الاثنين صدقة، وتعين الرجل على دابته فتحمله عليها، أو ترفع له عليها متاعه صدقة‏.‏ والكلمة الطيبة صدقة، وبكل خطوة تمشيها إلى الصلاة صدقة، وتميط الأذى عن الطريق صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (17)"},{"id":"riyad:1466","bookId":"riyad","type":"hadith","num":1466,"kitab":"كتاب المقدمات","isnad":"وعن أم كلثوم بنت عقبة بن أبي معيط رضي الله عنها قالت سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ليس الكذاب الذي يصلح بين الناس فينمي خيرًا، أو يقول خيرًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ و في رواية مسلم زيادة، قالت: \"و لم اسمعه يرخصه في شيء مما يقوله الناس الا في ثلاث، تعني: الحرب، و الاصلاح بين الناس، و حديث الرجل امراته، و حديث المرأة زوجها\"."},{"id":"riyad:1467","bookId":"riyad","type":"hadith","num":1467,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ سمع رسول الله صلى الله عليه وسلم صوت خصوم بالباب عالية أصواتهما، وإذا أحدهما يستوضع الآخر ويسترفقه في شيء، وهو يقول‏:‏ والله لا أفعل، فخرج عليهما رسول الله صلى الله عليه وسلم فقال‏:‏ “أين المتألي على الله لا يفعل المعروف‏؟‏ ‏","matn":"\"‏ فقال‏:‏ أنا يا رسول الله ، فله أي ذلك أحب ، ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1468","bookId":"riyad","type":"hadith","num":1468,"kitab":"كتاب المقدمات","isnad":"وعن أبي العباس سهل بن سعد الساعدي رضي الله عنه ، أن رسول الله صلى الله عليه وسلم بلغه أن بني عمرو بن عوف كان بينهم شر، فخرج رسول الله صلى الله عليه وسلم يصلح بينهم في أناس معه ، فحبس رسول الله صلى الله عليه وسلم وحانت الصلاة، فهل لك أن تؤم الناس‏؟‏ قال‏:‏ نعم إن شئت، فأقام بلال الصلاة، وتقدم أبو بكر فكبر وكبر الناس،وجاء رسول الله صلى الله عليه وسلم يمشي في الصفوف حتى قام في الصف، فأخذ الناس في التصفيق، وكان أبو بكر رضي الله عنه لا يلتفت في صلاته، فلما أكثر الناس التصفيق التفت، فإذا رسول الله صلى الله عليه وسلم، فأشار إليه رسول الله صلى الله عليه وسلم، فرفع أبو بكر رضي الله عنه يده فحمد الله، ورجع القهقرى وراءه حتى قام في الصف، فتقدم رسول الله صلى الله عليه وسلم، فصلى للناس، فلما فرغ أقبل على الناس فقال‏:‏ ‏","matn":"\"‏أيها الناس ما لكم حين نابكم شيء في الصلاة أخذتم في التصفيق ‏؟‏ إنما التصفيق للنساء‏.‏ من نابه شيء في صلاته فليقل سبحان الله، فإنه لا يسمعه أحد حين يقول سبحان الله إلا التفت، ‏:‏ يا أبا بكر‏:‏ ما منعك أن تصلي الناس حين أشرت إليك‏؟‏‏\"‏ فقال أبو بكر‏:‏ ما كان ينبغي لابن أبي قحافة أن يصلي بالناس بين يدي رسول الله صلى الله عليه وسلم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (20)‏‏.‏"},{"id":"riyad:1469","bookId":"riyad","type":"hadith","num":1469,"kitab":"كتاب المقدمات","isnad":"عن حارثة بن وهب رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “ألا أخبركم بأهل الجنة‏؟‏ كل ضعيف متضعف ، لو أقسم على الله لأبره‏.‏ ألا أخبركم بأهل النار‏؟‏ كل عتل جواظ مستكبر‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ (21)"},{"id":"riyad:1470","bookId":"riyad","type":"hadith","num":1470,"kitab":"كتاب المقدمات","isnad":"وعن أبي العباس سهل بن سعد الساعدي رضي الله عنه قال‏:‏ مر رجل على النبي صلى الله عليه وسلم، فقال لرجل عنده جالس‏:‏ ‏","matn":"\"‏ما رأيك في هذا‏؟‏‏\"‏ فقال‏:‏ رجل من أشراف الناس، هذا والله حري إن خطب أن ينكح، وإن شفع أن يشفع ‏.‏ فسكت رسول الله صلى الله عليه وسلم، ثم مر رجل آخر، فقال له رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ ما رأيك في هذا‏؟‏‏\"‏ فقال‏:‏ يا رسول الله هذا رجل من فقراء المسلمين هذا حري إن خطب أن لا ينكح، وإن شفع أن لا يشفع، وإن قال أن لا يسمع لقوله‏.‏ فقال رسول الله صلى الله عليه وسلم‏:‏ “هذا خير من ملء الأرض مثل هذا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ (22)"},{"id":"riyad:1471","bookId":"riyad","type":"hadith","num":1471,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ احتجت الجنة والنار فقالت النار‏:‏ في الجبارون والمتكبرون، وقالت الجنة‏:‏ في ضعفاء الناس ومساكينهم، فقضى الله بينهما‏:‏ إنك الجنة رحمتي أرحم بك من أشاء، وإنك النار أعذب بك من أشاء، ولكليكما علي ملؤها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1472","bookId":"riyad","type":"hadith","num":1472,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إنه ليأتي الرجل السمين العظيم يوم القيامة لا يزن عند الله جناح بعوضة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1473","bookId":"riyad","type":"hadith","num":1473,"kitab":"كتاب المقدمات","isnad":"وعنه أن امرأة سوداء كانت تقم المسجد، أو شابا، ففقدها، رسول الله صلى الله عليه وسلم، فسأل عنها أو عنه، فقالوا‏:‏ مات‏.‏ قال‏:‏ ‏","matn":"\"‏ أفلا كنتم آذنتموني‏\"‏ فكأنهم صغروا أمرها، أو أمره، فقال‏:‏ ‏\"‏ دلوني على قبره‏\"‏ فدلوه فصلى عليه، ثم قال‏:‏ ‏\"‏ إن هذه القبور مملوءة ظلمة على أهلها، وإن الله تعالى ينورها لهم بصلاتي عليهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (23)"},{"id":"riyad:1474","bookId":"riyad","type":"hadith","num":1474,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏رب أشعث أغبر مدفوع بالأبواب لو أقسم على الله لأبره ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1475","bookId":"riyad","type":"hadith","num":1475,"kitab":"كتاب المقدمات","isnad":"وعن أسامة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ قمت على باب الجنة، فإذا عامة من دخلها المساكين، وأصحاب الجد محبوسون، غير أن أصحاب النار قد أمر بهم إلى النار‏.‏ وقمت على باب النار فإذا عامة من دخلها النساء” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (24)"},{"id":"riyad:1476","bookId":"riyad","type":"hadith","num":1476,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “ لم يتكلم في المهد إلا ثلاثة‏:‏ عيسى ابن مريم، وصاحب جريج، وكان جريج رجلا عابدًا، فاتخذ صومعة فكان فيها، فأتته أمه وهو يصلي فقالت‏:‏ يا جريج، فأتته أمه وهو يصلي فقالت‏:‏ يا جريج، فقال‏:‏ يا رب أمي وصلاتي فأقبل على صلاته فانصرفت‏.‏ فلما كان من الغد أتته وهو يصلي، فقالت‏:‏ يا جريج، فقال‏:‏ أي رب أمي وصلاتي، فأقبل على صلاته، فقالت‏:‏ اللهم لاتمته حتى ينظر إلى وجوه المومسات‏.‏ فتذاكر بنو إسرائيل جريجًا وعبادته، وكانت امرأة بغي يتمثل بحسنها، فقالت‏:‏ إن شئتم لأفتننه، فتعرضت له، فلم يلتفت إليها، فأتت راعيًا كان يأوي إلى صومعته، فأمكنته من نفسها فوقع عليها‏.‏ فحملت، وجعلوا يضربونه، فقال‏:‏ ما شأنكم‏؟‏ قالوا‏:‏ زنيت بهذه البغي فولدت منك‏.‏ قال‏:‏ أين الصبي‏؟‏ فجاءوا به فقال‏:‏ دعوني حتى أصلي، فصلى، فلما انصرف أتى الصبي فطعن في بطنه وقال‏:‏ ياغلام من أبوك‏؟‏ قال‏:‏ فلان الراعي، فأقبلوا على جريج يقبلونه ويتمسحون به وقالوا‏:‏ نبني لك صومعتك من ذهب، قال‏:‏ لا، أعيدوها من طين كما كانت، ففعلوا‏.‏ وبينا صبي يرضع من أمه، فمر رجل راكب على دابة فارهة وشارة حسنة، فقالت‏:‏ “ اللهم اجعل ابني مثل هذا، فترك الثدي وأقبل إليه فنظر إليه فقال‏:‏ اللهم لا تجعلني مثله، ثم أقبل على ثديه فجعل يرتضع‏","matn":"\"‏ فكأني أنظر إلى رسول الله صلى الله عليه وسلم وهو يحكي ارتضاعه بأصبعه السبابة في فيه، فجعل يمصها، قال‏:‏ ‏\"‏ومروا بجارية وهم يضربونها، ويقولون‏:‏ زنيت سرقت، وهي تقول‏:‏ حسبي الله ونعم الوكيل‏.‏ فقالت أمه‏:‏ اللهم لا تجعل ابني مثلها، فترك الرضاع ونظر إليها فقال‏:‏ اللهم اجعلني مثلها، فهناك تراجعا الحديث فقالت‏:‏ مر رجل حسن الهيئة فقلت‏:‏ اللهم اجعل ابني مثله فقلت‏:‏ اللهم لا تجعلني مثله، ومروا بهذه الأمة وهم يضربونها ويقولون‏:‏ زنيت سرقت، فقلت‏:‏ اللهم لا تجعل ابني مثلها فقلت‏:‏ اللهم اجعلني مثلها‏؟‏‏!‏ قال‏:‏ إن ذلك الرجل كان جبارًا فقلت‏:‏ اللهم لا تجعلني مثله، وإن هذه يقولون لها زنيت، ولم تزن وسرقت، ولم تسرق، فقلت‏:‏ اللهم اجعلني مثلها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (25)"},{"id":"riyad:1477","bookId":"riyad","type":"hadith","num":1477,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سعد بن أبي وقاص رضي الله عنه قال‏:‏ كنا مع النبي صلى الله عليه وسلم ستة نفر، فقال المشركون للنبي صلى الله عليه وسلم‏:‏ اطرد هؤلاء لايجترئون علينا، وكنت أنا وابن مسعود ورجلان لست أسميهما، فوقع في نفس رسول الله صلى الله عليه وسلم ما شاء الله أن يقع، فحدث نفسه، فأنزل الله تعالى‏:‏ ‏{‏ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه‏}‏ ‏(‏‏(‏الأنعام‏:‏ 52‏:‏ رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1478","bookId":"riyad","type":"hadith","num":1478,"kitab":"كتاب المقدمات","isnad":"وعن أبي هبيرة عائذ بن عمرو المزني وهو من أهل بيعة الرضوان رضي الله عنه، أن أبا سفيان أتى على سلمان وصهيب وبلال في نفر فقالوا‏:‏ ما أخذت سيوف الله من عدو الله مأخذها، فقال أبو بكر رضي الله عنه‏:‏ أتقولون هذا لشيخ قريش وسيدهم‏؟‏ فأتى النبي صلى الله عليه وسلم، فأخبره فقال‏:‏ ‏","matn":"\"‏يا أبا بكر لعلك أغضبتهم‏؟‏ لئن كنت أغضبتهم لقد أغضبت ربك‏\"‏ فأتاهم فقال‏:‏ ياإخوتاه أغضبتكم‏؟‏ قالوا‏:‏ لا، يغفر الله لك يا أخي‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1479","bookId":"riyad","type":"hadith","num":1479,"kitab":"كتاب المقدمات","isnad":"وعن سهل بن سعيد رضي الله عنه‏:‏ قال رسول صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ أنا وكافل اليتيم في الجنة هكذا‏\"‏ وأشار بالسبابة والوسطى، وفرج بينهما‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1480","bookId":"riyad","type":"hadith","num":1480,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ كافل اليتيم له أو لغيره أنا وهو كهاتين في الجنة‏\"‏ وأشار الراوي وهو مالك ابن أنس بالسبابة والوسطى‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1481","bookId":"riyad","type":"hadith","num":1481,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ ليس المسكين الذي ترده التمرة والتمرتان، ولا اللقمة واللقمتان إنما المسكين الذي يتعفف‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1482","bookId":"riyad","type":"hadith","num":1482,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ الساعي على الأرملة والمسكين كالمجاهد في سبيل الله‏\"‏ وأحسبه قال‏:‏ ‏\"‏ وكالقائم الذي لا يفتر، وكالصائم الذي لا يفطر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1483","bookId":"riyad","type":"hadith","num":1483,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ شر الطعام طعام الوليمة، يمنعها من يأتيها، ويدعى إليها من يأباها، ومن لم يجب الدعوة فقد عصى الله ورسوله‏\"‏ ((رواه مسلم‏))‏.‏ وفي رواية في ‏\"‏ الصحيحين‏\"‏ عن أبي هريرة من قوله‏:‏ ‏\"‏ بئس الطعام طعام الوليمة يدعى إليها الأغنياء ويترك الفقراء‏\"‏‏‏‏(‏(متفق عليه‏)‏‏)‏.‏"},{"id":"riyad:1484","bookId":"riyad","type":"hadith","num":1484,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ “من عال جاريتين حتى تبلغا جاء يوم القيامة أنا وهو كهاتين‏","matn":"\"‏ وضم أصابعه‏.‏‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏(29)"},{"id":"riyad:1485","bookId":"riyad","type":"hadith","num":1485,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ ‏","matn":"\"‏دخلت علي امرأة ومعها ابنتان لها تسأل ، فلم تجد عندي شيئا غير تمرة واحدة، فأعطيتها إياها فقسمتها بين ابنتيها ولم تأكل منها، ثم قامت فخرجت، فدخل النبي صلى الله عليه وسلم علينا، فأخبرته فقال‏:‏ ‏\"‏من ابتلي من هذه البنات بشيء فأحسن إليهن كن له سترًا من النار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1486","bookId":"riyad","type":"hadith","num":1486,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ جاءتني مسكينة تحمل ابنتين لها، فأطعمتها ثلاث تمرات، فأعطت كل واحدة منهما تمرة ورفعت إلى فيها تمرة لتأكلها ، فاستطعمتها ابنتاها، فشقت التمرة التي كانت تريد أن تأكلها بينهما، فأعجبني شأنها، فذكرت الذي صنعت لرسول الله صلى الله عليه وسلم فقال‏:‏ ‏","matn":"\"‏إن الله قد أوجب لها بها الجنة، أو أعتقها بها من النار‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1487","bookId":"riyad","type":"hadith","num":1487,"kitab":"كتاب المقدمات","isnad":"و عن أبي شريح خويلد بن عمرو الخزاعي رضي الله عنه قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏اللهم إني أحرج حق الضعيفين اليتيم والمرأة‏\"‏ ‏(‏‏(‏حديث حسن رواه النسائي بإسناد جيد‏)‏‏)‏‏.‏"},{"id":"riyad:1488","bookId":"riyad","type":"hadith","num":1488,"kitab":"كتاب المقدمات","isnad":"وعن مصعب بن سعد بن أبي وقاص رضي الله عنهما قال‏:‏ رأى سعد أن له فضلا على من دونه، فقال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏هل تنصرون وترزقون إلا بضعفائكم‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ هكذا مرسلا، فإن مصعب بن سعد تابعي، ‏(‏‏(‏ورواه الحافظ أبو بكر البرقاني في صحيحه متصلا عن مصعب عن أبيه رضي الله عنه‏)‏‏)‏‏.‏"},{"id":"riyad:1489","bookId":"riyad","type":"hadith","num":1489,"kitab":"كتاب المقدمات","isnad":"و عن أبي الدرداء عويمر رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ابغوني في الضعفاء ، فإنما تنصرون، وترزقون بضعفائكم‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏"},{"id":"riyad:1490","bookId":"riyad","type":"hadith","num":1490,"kitab":"كتاب المقدمات","isnad":"و عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏استوصوا بالنساء خيرًا، فإن المرأة خلقت من ضلع، وإن أعوج ما في الضلع أعلاه، فإن ذهبت تقيمه كسرته، وإن تركته، لم يزل أعوج، فاستوصوا بالنساء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية في ‏(‏‏(‏الصحيحين‏)‏‏)‏ ‏:‏ ‏\"‏المرأة كالضلع إن أقمتها كسرتها، وإن استمتعت بها، استمتعت وفيها عوج‏\"‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏إن المرأة خلقت من ضلع ، لن تستقيم لك على طريقة، فإن استمعت بها وفيها عوج، وإن ذهبت تقيمها كسرتها ، وكسرها طلاقها‏\"‏‏."},{"id":"riyad:1491","bookId":"riyad","type":"hadith","num":1491,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن زمعة رضي الله عنه ، أنه سمع النبي صلى الله عليه وسلم يخطب، وذكر الناقة والذي عقرها، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏(‏إذ انبعث أشقاها‏)‏ انبعث لها رجل عزيز، عارم منيع في رهطه‏","matn":"\"‏ ثم ذكر النساء، فوعظ فيهن، فقال ‏:‏ ‏\"‏يعمد أحدكم فيجلد امرأته جلد العبد فلعله يضاجعها من آخر يومه‏\"‏ ثم وعظهم في ضحكهم من الضرطة وقال‏:‏ ‏\"‏لم يضحك أحدكم مما يفعل‏؟‏‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1492","bookId":"riyad","type":"hadith","num":1492,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا يفرك مؤمن مؤمنة إن كره منها خُلقا رضي منها آخر‏\"‏ أو قال ‏:‏ ‏\"‏غيره‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1493","bookId":"riyad","type":"hadith","num":1493,"kitab":"كتاب المقدمات","isnad":"وعن عمرو بن الأحوض الجشمي رضي الله عنه أنه سمع النبي صلى الله عليه وسلم في حجة الوداع يقول بعد أن حمد الله تعالى، وأثنى عليه وذكر ووعظ، ثم قال‏:‏ ‏","matn":"\"‏ألا واستوصوا بالنساء خيرًا فإنما هن عوانٍ عندكم ليس تملكون منهن شيئا غير ذلك إلا أن يأتين بفاحشة مبينة، فإن فعلن فاهجروهن في المضاجع، واضربوهن ضربا غير مبرح، فإن أطعنكم فلا تبغوا عليهن سبيلا، ألا إن لكم على نسائكم حقا، ولنسائكم عليكم حقا، فحقكم عليهن أن لا يوطئن فرشكم من تكرهون، ولا يأذن في بيوتكم لمن تكرهون، ألا وحقهن عليكم أن تحسنوا إليهن في كسوتهن وطعامهن‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1494","bookId":"riyad","type":"hadith","num":1494,"kitab":"كتاب المقدمات","isnad":"وعن معاوية بن حيدة رضي الله عنه قال ‏:‏ قلت يا رسول الله صلى الله عليه وسلم ما حق زوجة أحدنا عليه‏؟‏ قال‏:‏ ‏","matn":"\"‏أن تطعمها إذا طعمت ، وتكسوها إذا اكتسيت ولا تضرب الوجه، ولا تقبح، ولا تهجر إلا في البيت ‏\"‏ حديث حسن رواه أبو داود وقال‏:‏ معنى ‏\"‏لاتقبح‏\"‏ أي ‏:‏ لا تقل قبحك الله‏.‏"},{"id":"riyad:1495","bookId":"riyad","type":"hadith","num":1495,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أكمل المؤمنين إيمانا أحسنهم خُلقا، وخياركم خياركم لنسائهم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1496","bookId":"riyad","type":"hadith","num":1496,"kitab":"كتاب المقدمات","isnad":"وعن إياس بن أبي ذباب رضي الله عنه قال‏:‏ قال رسول صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لاتضربوا إماء الله‏\"‏ فجاء عمر رضي الله عنه إلى رسول الله صلى الله عليه وسلم ، فقال ‏:‏ ذئرن النساء على أزواجهن، فرخص في ضربهن، فأطاف بآل رسول الله صلى الله عليه وسلم نساء كثير يشكون أزواجهن، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏لقد أطاف بآل بيت محمد نساء كثير يشكون أزواجهن ليس أولئك بخياركم‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1497","bookId":"riyad","type":"hadith","num":1497,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الدنيا متاع، وخير متاعها المرأة الصالحة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1498","bookId":"riyad","type":"hadith","num":1498,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏إذا دعا الرجل امرأته إلى فراشه فلم تأته فبات غضبان عليها لعنتها الملائكة حتى تصبح‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لها ‏\"‏إذا باتت المرأة هاجرة فراش زوجها لعنتها الملائكة حتى تصبح‏\"‏‏.‏ وفي رواية قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏ والذي نفسي بيده ما من رجل يدعو امرأته إلى فراشه فتأبى عليه إلا كان الذي في السماء ساخطًا عليها حتى يرضي عنها‏\"‏‏.‏"},{"id":"riyad:1499","bookId":"riyad","type":"hadith","num":1499,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أيضًا أن رسول الله صلى الله عليه وسلم قال؛ ‏","matn":"\"‏ لا يحل لامرأة أن تصوم وزوجها شاهد إلا بإذنه، ولا تأذن في بيته إلا بإذنه‏\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1500","bookId":"riyad","type":"hadith","num":1500,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ كلكم راعٍ، وكلكم مسئول عن رعيته، والأمير راعٍ، والرجل راعٍ على أهل بيته؛ والمرأة راعية على بيت زوجها وولده، فكلكم راعٍ، وكلكم مسؤول عن رعيته‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1501","bookId":"riyad","type":"hadith","num":1501,"kitab":"كتاب المقدمات","isnad":"وعن أبي علي طلق بن علي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا دعا الرجل زوجته لحاجته فلتأته وإن كانت على التنور‏\"‏ ‏(‏‏(‏رواه الترمذي والنسائي وقال الترمذي‏.‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1502","bookId":"riyad","type":"hadith","num":1502,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لو كنت آمرًا أحدًا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1503","bookId":"riyad","type":"hadith","num":1503,"kitab":"كتاب المقدمات","isnad":"وعن أم سلمة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ أيما امرأة ماتت، وزوجها عنها راضٍ دخلت الجنة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1504","bookId":"riyad","type":"hadith","num":1504,"kitab":"كتاب المقدمات","isnad":"وعن معاذ بن جبل رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا تؤذي امرأة زوجها في الدنيا إلا قالت زوجة من الحور العين لا تؤذيه قاتلك الله‏!‏ فإنما هو عندك دخيل يوشك أن يفارقك إلينا‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1505","bookId":"riyad","type":"hadith","num":1505,"kitab":"كتاب المقدمات","isnad":"وعن أسامة بن زيد رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ ما تركت بعدي فتنة هي أضر على الرجال من النساء‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1506","bookId":"riyad","type":"hadith","num":1506,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ دينار أنفقته في سبيل الله، ودينار أنفقته في رقبة، ودينار تصدقت به على مسكين، ودينار أنفقته على أهلك، أعظمها أجرًا الذي أنفقته على أهلك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1507","bookId":"riyad","type":"hadith","num":1507,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله - ويقال له‏:‏ أبو عبد الرحمن - ثوبان بن بجدد مولى رسول الله صلى الله عليه وسلم قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ أفضل دينار ينفقه الرجل دينار ينفقه على عياله، ودينار ينفقه على دابته في سبيل الله، ودينار ينفقه على أصحابه في سبيل الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1508","bookId":"riyad","type":"hadith","num":1508,"kitab":"كتاب المقدمات","isnad":"وعن أم سلمة رضي الله عنها قالت‏:‏ قلت يارسول الله، هل لي أجر في بني أبي سلمة أن أنفق عليهم، ولست بتاركتهم هكذا وهكذا إنما هم بني‏؟‏ فقال‏:‏ ‏","matn":"\"‏ نعم لك أجر ما أنفقت عليهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1509","bookId":"riyad","type":"hadith","num":1509,"kitab":"كتاب المقدمات","isnad":"وعن سعد بن أبي وقاص رضي الله عنه في حديثه الطويل الذي قدمناه في أول الكتاب في باب النية أن رسول الله صلى الله عليه وسلم قال له‏:‏ ‏","matn":"\"‏ وإنك لن تنفق تبغي بها وجه الله إلا أجرت بها حتى ما تجعل في في امرأتك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1510","bookId":"riyad","type":"hadith","num":1510,"kitab":"كتاب المقدمات","isnad":"وعن أبي مسعود البدري رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا أنفق الرجل على أهله نفقة يحتسبها فهي له صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1511","bookId":"riyad","type":"hadith","num":1511,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ كفى بالمرء إثمًا أن يضيع من يقوت‏\"‏ حديث صحيح ‏(‏‏(‏رواه أبو داود وغيره‏)‏‏)‏‏.‏ ورواه مسلم في صحيحه بمعناه قال‏:‏ ‏\"‏ كفى بالمرء إثمًا أن يحبس عمن يملك قوته‏\"‏‏.‏"},{"id":"riyad:1512","bookId":"riyad","type":"hadith","num":1512,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ ما من يوم يصبح العباد فيه إلا ملكان ينزلان، فيقول أحدهما‏:‏ اللهم أعط منفقًا خلفًا، ويقول الآخر‏:‏ اللهم أعط ممسكًا تلفًا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1513","bookId":"riyad","type":"hadith","num":1513,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ اليد العليا خير من اليد السفلى وابدأ بمن تعول، وخير الصدقة ما كان عن ظهر غنًى، ومن يستعفف، يعفه الله، ومن يستغن، يغنه الله‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1514","bookId":"riyad","type":"hadith","num":1514,"kitab":"كتاب المقدمات","isnad":"عن أنس رضي الله عنه قال‏:‏ كان أبو طلحة رضي الله عنه أكثر الأنصار بالمدينة مالاً من نخل، وكان أحب أمواله إليه بيرحاء، وكانت مستقبلة المسجد، وكان رسول الله صلى الله عليه وسلم يدخلها ويشرب من ماء فيها طيب قال أنس‏:‏ فلما نزلت هذه الآية‏:‏ ‏{‏لن تنالوا البر حتى تنفقوا مما تحبون‏}‏ قام أبو طلحة إلى رسول الله صلى الله عليه وسلم فقال‏:‏ يارسول إن الله تعالى أنزل عليك‏:‏ ‏{‏ لن تنالوا البر حتى تنفقوا مما تحبون‏}‏ وإن أحب مالي إلي بيرحاء، وإنها صدقة لله تعالى أرجو برها وذخرها عند الله تعالى، فضعها يا رسول الله حيث أراك الله، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ بخٍ‏!‏ ذلك مال رابح، ذلك مال رابح، وقد سمعت ما قلت، وإني أرى أن تجعلها في الأقربين‏\"‏ فقال أبو طلحة‏:‏ أفعل يا رسول الله، فقسمها أبو طلحة في أقاربه، وبني عمه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1515","bookId":"riyad","type":"hadith","num":1515,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة رضي الله عنه قال‏:‏ أخذ الحسن بن على رضي الله عنهما تمرة الصدقة فجعلها في فيه فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ كخ كخ، ارم بها، أما علمت أنَّا لا نأكل الصدقة‏!‏‏؟‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏\"‏ أنَّا لا تحل لنا الصدقة‏\"‏ وقوله‏:‏ ‏\"‏ كخٍْ كخٍْ‏\"‏ يقال بإسكان الخاء، ويقال بكسرها مع التنوين، وهي كلمة زجر للصبي عن المستقذرات‏.‏ وكان الحسن رضي الله عنه صبيًا‏.‏"},{"id":"riyad:1516","bookId":"riyad","type":"hadith","num":1516,"kitab":"كتاب المقدمات","isnad":"وعن أبي حفص عمر بن أبي سلمة عبد الله بن عبد الأسد ربيب رسول الله صلى الله عليه وسلم قال‏:‏ كنت غلامًا في حجر رسول الله صلى الله عليه وسلم وكانت يدي تطيش في الصحفة، فقال لي رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ يا غلام سَمِّ الله تعالى، وكُل بيمينك، وكُل مما يليك‏\"‏ فما زالت تلك طعمتي بعد‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1517","bookId":"riyad","type":"hadith","num":1517,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ كلكم راعٍ، وكلكم مسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها، والخادم راعٍ في مال سيده ومسئول عن رعيته، فكلكم راعٍ ومسئول عن رعيته‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1518","bookId":"riyad","type":"hadith","num":1518,"kitab":"كتاب المقدمات","isnad":"وعن عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ مروا أولادكم بالصلاة وهم أبناء سبع سنين، واضربوهم عليها، وهم أبناء عشر، وفرقوا بينهم في المضاجع‏\"‏ ‏(‏‏(‏حديث حسن رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1519","bookId":"riyad","type":"hadith","num":1519,"kitab":"كتاب المقدمات","isnad":"و عن أبي ثرية سبرة بن معبد الجهني رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ علموا الصبي الصلاة لسبع سنين‏\"‏ واضربوه عليها ابن عشر سنين‏\"‏ حديث حسن رواه أبو داود، والترمذي وقال حديث حسن‏.‏ ولفظ أبي داود‏:‏ ‏\"‏ مروا الصبي بالصلاة إذا بلغ سبع سنين‏\"‏‏.‏"},{"id":"riyad:1520","bookId":"riyad","type":"hadith","num":1520,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر وعائشة رضي الله عنهما قالا‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1521","bookId":"riyad","type":"hadith","num":1521,"kitab":"كتاب المقدمات","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يا أبا ذر إذا طبخت مرقة، فأكثر ماءها، وتعاهد جيرانك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له عن أبي ذر قال‏:‏ إن خليلي صلى الله عليه وسلم أوصاني‏:‏ ‏\"‏ إذا طبخت مرقًا فأكثر ماءها، ثم انظر أهل بيت من جيرانك، فأصبهم منها بمعروف‏\"‏‏.‏"},{"id":"riyad:1522","bookId":"riyad","type":"hadith","num":1522,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ والله لا يؤمن، والله لايؤمن، والله لا يؤمن‏!‏‏\"‏ قيل‏:‏ من يا رسول الله‏؟‏ قال‏:‏ ‏\"‏ الذي لا يأمن جاره بوائقه ‏!‏ ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية لمسلم‏:‏ ‏\"‏ لايدخل الجنة من لا يأمن جاره بوائقه‏\"‏‏.‏"},{"id":"riyad:1523","bookId":"riyad","type":"hadith","num":1523,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ يا نساء المسلمات لا تحقرن جارة لجارتها ولو فرسن شاة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1524","bookId":"riyad","type":"hadith","num":1524,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا يمنع جار جارة أن يغرز خشبة في جداره‏\"‏ ثم يقول أبو هريرة‏:‏ ما لي أراكم عنها معرضين‏!‏ والله لأرمين بها بين أكتافكم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1525","bookId":"riyad","type":"hadith","num":1525,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من كان يؤمن بالله واليوم الآخر، فلا يؤذِ جاره، ومن كان يؤمن بالله واليوم الآخر، فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر، فليقل خيرًا أو ليسكت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1526","bookId":"riyad","type":"hadith","num":1526,"kitab":"كتاب المقدمات","isnad":"و عن أبي شريح الخزاعي رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من كان يؤمن بالله واليوم الآخر، فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر، فليقل خيرًا أو ليسكت‏\"‏ ‏(‏‏(‏رواه مسلم بهذا اللفظ، وروى البخاري بعضه‏)‏‏)‏‏.‏"},{"id":"riyad:1527","bookId":"riyad","type":"hadith","num":1527,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قلت‏:‏ يارسول الله إن لي جارين، فإلى أيهما أُهْدِي‏؟‏ قال‏:‏ ‏","matn":"\"‏ إلى أقربهما منك بابًا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1528","bookId":"riyad","type":"hadith","num":1528,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمر رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏","matn":"\"‏خير الأصحاب عند الله تعالى خيرهم لصاحبه، وخير الجيران عند الله تعالى خيرهم لجاره‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1529","bookId":"riyad","type":"hadith","num":1529,"kitab":"كتاب المقدمات","isnad":"عن أبي عبد الرحمن عبد الله بن مسعود رضي الله عنه قال‏:‏ سألت النبي صلى الله عليه وسلم ‏:‏ أي العمل أحب إلى الله تعالى‏؟‏ قال ‏","matn":"\"‏ الصلاة على وقتها‏\"‏ قلت‏:‏ ثم أي‏؟‏ قال‏:‏ ‏\"‏ بر الوالدين‏\"‏ قلت‏:‏ ثم أي‏؟‏ قال‏:‏ ‏\"‏ الجهاد في سبيل الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1530","bookId":"riyad","type":"hadith","num":1530,"kitab":"كتاب المقدمات","isnad":"عَنْ أَبِي هُرَيْرَةَ رضي الله عنه، قَالَ: قَالَ رَسُولُ الله صلى الله عليه وسلم ‏","matn":"\"‏لاَ يَجْزِي وَلَدٌ وَالِدًا إِلاَّ أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ‏\" ‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1531","bookId":"riyad","type":"hadith","num":1531,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه أيضاً أن رسول الله قَالَ : « مَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيُكْرِمْ ضَيْفَهُ ، وَمَنْ كَانَ يُؤْمِنُ باللهِ وَاليَومِ الآخِرِ ، فَلْيَصِلْ رَحِمَهُ ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَاليَومِ الآخِرِ ، فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ » . مُتَّفَقٌ عَلَيهِ ."},{"id":"riyad:1532","bookId":"riyad","type":"hadith","num":1532,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ إن الله تعالى خلق الخلق حتى إذا فرغ منهم قامت الرحم، فقالت‏:‏ هذا مقام العائذ بك من القطيعة، قال‏:‏ نعم أما ترضين أن أصل من وصلك، وأقطع من قطعك‏؟‏ قالت‏:‏ بلى، قال‏:‏ فذلك لك، ثم قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏ اقرءوا إن شئتم‏:‏ ‏(‏فهل عسيتم إن توليتم أن تفسدوا في الأرض وتقطعوا أرحامكم‏.‏ أولئك الذين لعنهم الله فأصمهم وأعمى أبصارهم‏)‏ ‏‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية للبخاري‏:‏ فقال الله تعالى‏:‏ ‏\"‏ من وصلك، وصلته، ومن قطعك، قطعته‏\"‏‏.‏"},{"id":"riyad:1533","bookId":"riyad","type":"hadith","num":1533,"kitab":"كتاب المقدمات","isnad":"وعنه رضي الله عنه قال‏:‏ جاء رجل إلى رسول الله صلى الله عليه وسلم فقال‏:‏ يا رسول الله من أحق الناس بحسن صحابتي‏؟‏ قال‏:‏ ‏","matn":"\"‏ أمك‏\"‏ قال‏:‏ ثم من‏؟‏ قال‏:‏ ‏\"‏ أمك‏\"‏ قال‏:‏ ثم من‏؟‏ قال‏:‏ ‏\"‏أمك‏\"‏ قال‏:‏ ثم من‏؟‏ قال‏:‏ ‏\"‏ أبوك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ يارسول الله من أحق بحسن الصحبة‏؟‏ قال‏:‏ ‏\"‏ أمك، ثم أمك، ثم أمك، ثم أباك، ثم أدناك أدناك‏\"‏‏.‏"},{"id":"riyad:1534","bookId":"riyad","type":"hadith","num":1534,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ رغم أنف، ثم رغم أنف، ثم رغم أنف من أدرك أبويه عند الكبر، أحدهما أو كليهما، فلم يدخل الجنة‏\"‏ ((رواه مسلم))"},{"id":"riyad:1535","bookId":"riyad","type":"hadith","num":1535,"kitab":"كتاب المقدمات","isnad":"وعنه أن رجلاً قَالَ : يَا رَسُول الله ! إنّ لِي قَرابةً أصِلُهُمْ وَيَقْطَعُوني ، وَأُحْسِنُ إلَيْهِمْ وَيُسِيئُونَ إلَيَّ ، وَأحْلَمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ ، فَقَالَ","matn":"\" لَئِنْ كُنْتَ كَمَا قُلْتَ ، فَكأنَّمَا تُسِفُّهُمْ الْمَلَّ ، وَلا يَزَالُ مَعَكَ مِنَ اللهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذلِكَ \". ((رواه مسلم))."},{"id":"riyad:1536","bookId":"riyad","type":"hadith","num":1536,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ من أحب أن يبسط له في رزقه، وينسأ له في أثره، فليصل رحمه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1537","bookId":"riyad","type":"hadith","num":1537,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ كان أبو طلحة أكثر الأنصار بالمدينة مالاً من نخل، وكان أحب أمواله إليه بيرحاء، وكانت مستقبلة المسجد، وكان رسول الله صلى الله عليه وسلم يدخلها، ويشرب من ماء فيها طيب، فلما نزلت هذه الآية‏:‏ ‏{‏لن تنالوا البر حتى تنفقوا مما تحبون‏}‏ ‏(‏‏(‏آل عمران‏:‏ 92‏)‏‏)‏ قام أبو طلحة إلى رسول الله صلى الله عليه وسلم فقال‏:‏ يا رسول الله إن الله تبارك وتعالى يقول‏:‏ ‏{‏لن تنالوا البر حتى تنفقوا مما تحبون‏} وإن أحب مالي إلي بيرحاء، وإنها صدقة لله تعالى، وأرجو برها وذخرها عند الله تعالى، فضعها يا رسول الله حيث أراك الله‏.‏ فقال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏بخ‏!‏ ذلك مال رابح، وذلك مال رابح‏!‏ وقد سمعت ما قلت، وإني أرى أن تجعلها في الأقربين‏\"‏ فقال أبو طلحة‏:‏ أفعل يا رسول الله، فقسمها أبو طلحة في أقاربه وبني عمه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وسبق بيان ألفاظه في‏:‏ باب الإنفاق مما يحب‏.‏"},{"id":"riyad:1538","bookId":"riyad","type":"hadith","num":1538,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ أقبل رجل إلى نبي الله صلى الله عليه وسلم، فقال‏:‏ أبايعك على الهجرة والجهاد أبتغي الأجر من الله تعالى‏.‏ قال‏:‏ ‏","matn":"\"‏فهل لك من والديك أحد حي‏؟‏‏\"‏ قال‏:‏ نعم بل كلاهما قال‏:‏ ‏\"‏فتبتغي الأجر من الله تعالى‏؟‏‏\"‏ قال‏:‏ نعم‏.‏ قال ‏\"‏فارجع إلى والديك، فأحسن صحبتهما‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ وهذا لفظ مسلم‏)‏‏)‏‏.‏ وفي رواية لهما‏:‏ جاء رجل فاستأذنه في الجهاد فقال ‏\"‏أحي والداك‏؟‏ قال‏:‏ نعم، قال‏:‏ ‏\"‏ففيهما فجاهد‏\"‏‏.‏"},{"id":"riyad:1539","bookId":"riyad","type":"hadith","num":1539,"kitab":"كتاب المقدمات","isnad":"وعنه النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس الواصل بالمكافئ ولكن الواصل الذي إذا قَطَعت رحمُه وصلها‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1540","bookId":"riyad","type":"hadith","num":1540,"kitab":"كتاب المقدمات","isnad":"وعن عائشة قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏الرحم معلقة بالعرش تقول‏:‏ من وصلني، وصله الله، ومن قطعني، قطعه الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1541","bookId":"riyad","type":"hadith","num":1541,"kitab":"كتاب المقدمات","isnad":"وعن أم المؤمنين ميمونة بنت الحارث رضي الله عنها أنها أعتقت وليدة ولم تستأذن النبي صلى الله عليه وسلم، فلما كان يومها الذي يدور عليها فيه، قالت‏:‏ أشعرت يا رسول الله أني أعتقت وليدتي‏؟‏ قال‏:‏ ‏","matn":"\"‏أو فعلت‏؟‏‏\"‏ قالت‏:‏ نعم‏.‏ قال‏:‏ ‏\"‏أما إنك لو أعطيتها أخوالك كان أعظم لأجرك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1542","bookId":"riyad","type":"hadith","num":1542,"kitab":"كتاب المقدمات","isnad":"وعن أسماء بنت أبي بكر الصديق رضي الله عنهما قالت‏:‏ قدمت على أمي وهي مشركة في عهد رسول الله صلى الله عليه وسلم، فاستفتيت رسول الله صلى الله عليه وسلم قلت‏:‏ قدمت علي أمي وهي راغبة، أفأصل أمي‏؟‏ قال‏:‏ ‏","matn":"\"‏نعم صلي أمك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1543","bookId":"riyad","type":"hadith","num":1543,"kitab":"كتاب المقدمات","isnad":"وعن زينب الثقفية امرأة عبد الله بن مسعود رضي الله عنه وعنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏تصدقن يا معشر النساء ولو من حليكن‏\"‏ قالت‏:‏ فرجعت إلى عبد الله بن مسعود فقلت له‏:‏ إنك رجل خفيف ذات اليد وإن رسول الله صلى الله عليه وسلم قد أمرنا بالصدقة فأته، فاسأله، فإن كان ذلك يجزئ عني وإلا صرفتها إلى غيركم‏.‏ فقال عبد الله‏:‏ بل ائتيه أنت، فانطلقت، فإذا امرأة من الأنصار بباب رسول الله صلى الله عليه وسلم حاجتي حاجتها، وكان رسول الله صلى الله عليه وسلم قد ألقيت عليه المهابة، فخرج علينا بلال، فقلنا له‏:‏ ائت رسول الله صلى الله عليه وسلم، فأخبره أن امرأتين بالباب تسألانك‏:‏ أتجزئ الصدقة عنهما على أزواجهما وعلى أيتام في حجورهما‏؟‏ ولا تخبره من نحن، فدخل على أزواجهما وعلى أيتام في حجورهما‏؟‏ ولا تخبره من نحن، فدخل بلال على رسول الله صلى الله عليه وسلم، فسأله، فقال له رسول الله صلى الله عليه وسلم ‏\"‏من هما‏؟‏‏\"‏ قال‏:‏ امرأة من الأنصار وزينب‏.‏ فقال رسول الله صلى الله عليه وسلم ‏\"‏أي الزيانب هي ‏؟‏‏\"‏ قال‏:‏ امرأة عبد الله، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏لهما أجران‏:‏ أجر القرابة وأجر الصدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1544","bookId":"riyad","type":"hadith","num":1544,"kitab":"كتاب المقدمات","isnad":"وعن أبي سفيان صخر بن حرب رضي الله عنه في حديثه الطويل في قصة هرقل أن هرقل قال لأبي سفيان‏:‏ فماذا يأمركم به‏؟‏ يعني النبي صلى الله عليه وسلم قال‏:‏ قلت‏:‏ يقول‏:‏ ‏","matn":"\"‏اعبدوا الله وحده، ولا تشركوا به شيئًا، واتركوا ما يقول آباؤكم، ويأمرنا بالصلاة، والصدق، والعفاف، والصلة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1545","bookId":"riyad","type":"hadith","num":1545,"kitab":"كتاب المقدمات","isnad":"وعن أبي ذر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إنكم ستفتحون أرضًا يذكر فيها القيراط‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏ستفتحون مصر وهي أرض يسمى فيها القيراط، فاستوصوا بأهلها خيرًا، فإن لهم ذمة ورحمًا‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏فإذا افتتحتموها، فأحسنوا إلى أهلها، فإن لهم ذمة ورحمًا‏\"‏ أو قال‏:‏ ‏\"‏ذمة وصهرًا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1546","bookId":"riyad","type":"hadith","num":1546,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ لما نزلت هذه الآية‏:‏ ‏(‏وأنذر عشيرتك الأقربين‏)‏ ‏(‏‏(‏الشعراء‏:‏ 214‏)‏‏)‏ دعا رسول الله صلى الله عليه وسلم قريشًا، فاجتمعوا فعم، وخص وقال‏:‏ ‏","matn":"\"‏يا بني عبد شمس، يا بني كعب بن لؤي، أنقذوا أنفسكم من النار، يا بني مرة بن كعب، أنقذوا أنفسكم من النار، يا بني عبد مناف، أنقذوا أنفسكم من النار، يا بني هاشم أنقذوا أنفسكم من النار، يا بني عبد المطلب أنقذوا أنفسكم من النار، يا فاطمة أنقذي نفسك من النار، فإني لا أملك لكم من الله شيئًا، غير أن لكم رحما سأبلها ببلالها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1547","bookId":"riyad","type":"hadith","num":1547,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله عمرو بن العاص رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم جهارًا غير سر يقول‏:‏ ‏","matn":"\"‏إن آل بني فلان ليسوا بأوليائي، إنما وليي الله وصالح المؤمنين، ولكن لهم رحم أبلها ببلالها‏\"‏ ‏(‏‏(‏متفق عليه‏.‏ واللفظ البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1548","bookId":"riyad","type":"hadith","num":1548,"kitab":"كتاب المقدمات","isnad":"وعن أبي أيوب خالد بن زيد الأنصاري رضي الله عنه أن رجلاً قال‏:‏ يا رسول الله أخبرني بعمل يدخلني الجنة، ويباعدني من النار‏.‏ فقال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏تعبد الله، ولاتشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصل الرحم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1549","bookId":"riyad","type":"hadith","num":1549,"kitab":"كتاب المقدمات","isnad":"وعن سلمان بن عامر رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أفطر أحدكم، فليفطر على تمر، فإنه بركة، فإن لم يجد تمرًا، فالماء، فإنه طهور‏\"‏ وقال‏:‏ ‏\"‏الصدقة على المسكين صدقة، وعلى ذي الرحم ثنتان‏:‏ صدقة وصلة‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1550","bookId":"riyad","type":"hadith","num":1550,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كانت تحتي امرأة، وكنت أحبها، وكان عمر يكرهها، فقال لي‏:‏ طلقها، فأبيت، فأتى عمر رضي الله عنه النبي صلى الله عليه وسلم، فذكر ذلك له، فقال النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏طلقها‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1551","bookId":"riyad","type":"hadith","num":1551,"kitab":"كتاب المقدمات","isnad":"وعن أبي الدرداء رضي الله عنه أن رجلاً أتاه فقال‏:‏ إن لي امرأة وإن أمي تأمرني بطلاقها‏؟‏ فقال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول ‏","matn":"\"‏الوالد أوسط أبواب الجنة، فإن شئت، فأضع ذلك الباب، أو أحفظه‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1552","bookId":"riyad","type":"hadith","num":1552,"kitab":"كتاب المقدمات","isnad":"وعن البراء بن عازب رضي الله عنهما، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الخالة بمنزلة الأم‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏ وفي الباب أحاديث كثيرة في الصحيح مشهورة؛ ومنها حديث أصحاب الغار، وحديث جريج وقد سبقا، وأحاديث مشهورة في الصحيح حذفتها اختصارًا، ومن أهمها حديث عمرو بن عبسة رضي الله عنه الطويل المشتمل على جمل كثيرة من قواعد الإسلام وآدابه، وسأذكره بتمامه إن شاء الله تعالى في باب الرجاء، قال فيه‏:‏ دخلت على النبي صلى الله عليه وسلم بمكة، يعني في أول النبوة، فقلت له‏:‏ ما أنت‏؟‏ قال‏:‏ ‏\"‏نبي‏\"‏ فقلت‏:‏ وما نبي‏؟‏ قال‏:‏ ‏\"‏أرسلني الله تعالى‏\"‏ فقلت‏:‏ بأي شيء أرسلك‏؟‏ قال‏:‏ ‏\"‏أرسلني بصلة الأرحام، وكسر الأوثان، وأن يوحد الله لا يشرك به شيء‏\"‏ ‏(‏‏(‏وذكر تمام الحديث‏.‏ والله أعلم‏)‏‏)‏‏.‏"},{"id":"riyad:1553","bookId":"riyad","type":"hadith","num":1553,"kitab":"كتاب المقدمات","isnad":"و عن أبي بكرة نفيع بن الحارث رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ألا أنبئكم بأكبر الكبائر‏؟‏‏\"‏ ثلاثًا قلنا‏:‏ بلى يا رسول الله‏:‏ قال‏:‏ ‏\"‏الإشراك بالله، وعقوق الوالدين\" وكان متكئاً فجلس، فقال: \"ألا و قول الزور و شهادة الزور\" فما زال يكررها حتى قلنا: ليته سكتز‏ ‏(‏‏(‏متفق عليه‏)‏‏)"},{"id":"riyad:1554","bookId":"riyad","type":"hadith","num":1554,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النَّبيّ قَالَ","matn":"\"الكَبَائِرُ : الإشْرَاكُ بالله ، وَعُقُوقُ الوَالِدَيْنِ ، وَقَتْلُ النَّفْس ، وَاليَمِينُ الغَمُوسُ\" . ((رواه البخاري)) ."},{"id":"riyad:1555","bookId":"riyad","type":"hadith","num":1555,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏من الكبائر شتم الرجل والديه‏!‏‏\"‏ قالوا‏:‏ يا رسول الله وهل يشتم الرجل والديه‏؟‏ ‏!‏ قال‏:‏ ‏\"‏نعم؛ يسب أبا الرجل، فيسب أباه، ويسب أمه، فيسب أمه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية ‏\"‏إن من أكبر الكبائر أن يلعن الرجل والديه‏!‏‏\"‏ قيل ‏:‏ يا رسول الله كيف يلعن الرجل والديه‏؟‏ ‏!‏ قال‏ \"‏يسب أبا الرجل ، فيسب أباه، ويسب أمه، فيسب أمه‏\"‏‏.‏"},{"id":"riyad:1556","bookId":"riyad","type":"hadith","num":1556,"kitab":"كتاب المقدمات","isnad":"وعن أبي محمد جبير من مطعم رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لايدخل الجنة قاطع‏\"‏ قال سفيان في روايته‏:‏ يعني ‏:‏ قاطع رحم ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1557","bookId":"riyad","type":"hadith","num":1557,"kitab":"كتاب المقدمات","isnad":"وعن أبي عيسى المغيرة بن شعبة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن الله تعالى حرم عليكم عقوق الأمهات، ومنعًا وهات، ووأد البنات، وكره لكم قيل وقال، وكثرة السؤال ، وإضاعة المال‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1558","bookId":"riyad","type":"hadith","num":1558,"kitab":"كتاب المقدمات","isnad":"عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إن أبر البر أن يصل الرجل ود أبيه‏\"‏‏.‏"},{"id":"riyad:1559","bookId":"riyad","type":"hadith","num":1559,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن دينار عن عبد الله بن عمر رضي الله عنهما أن رجلاً من الأعراب لقيه بطريق مكة، فسلم عليه عبد الله بن عمر، وحمله على حمار كان يركبه، وأعطاه عمامة كانت على رأسه، قال ابن دينار‏:‏ فقلنا له‏:‏ أصلحك الله إنهم الأعراب وهم يرضون اليسير فقال عبد الله بن عمر‏:‏ إن أبا هذا كان ودًا لعمر بن الخطاب رضي الله عنه وإني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏إن أبر البر صلة الرجل أهل ود أبيه‏\"‏‏.‏ وفي رواية عن ابن دينار عن ابن عمر أنه كان إذا خرج إلى مكة كان له حمار يتروح عليه إذا مل ركوب الراحلة، وعمامة يشد بها رأسه، فبينا هو يومًا على ذلك الحمار إذ مر به أعرابي، فقال‏:‏ ألست ابن فلان بن فلان‏؟‏ قال‏:‏ بلى‏.‏ فأعطاه الحمار، فقال‏:‏ اركب هذا، وأعطاه العمامة وقال‏:‏ اشدد بها رأسك ، فقال له بعض أصحابه‏:‏ غفر الله لك أعطيت هذا الأعرابي حمارًا كنت تروح عليه، وعمامة كنت تشد بها رأسك‏؟‏ فقال‏:‏إني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏إن من أبر البر أن يصل الرجل أهل ود أبيه بعد أن يولي‏\"‏ وإن أباه كان صديقًا لعمر رضي الله عنه ،"},{"id":"riyad:1560","bookId":"riyad","type":"hadith","num":1560,"kitab":"كتاب المقدمات","isnad":"و عن أبي أُسَيد- بضم الهمزة وفتح السين- مالك بن ربيعة الساعدي رضي الله عنه قال‏:‏ بينا نحن جلوس عند رسول الله صلى الله عليه وسلم إذ جاءه رجل من بني سلمة فقال‏:‏ يا رسول الله هل بقي من بر أبوي شيء أبرهما به بعد موتهما‏؟‏ فقال‏:‏ ‏","matn":"\"‏ نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:1561","bookId":"riyad","type":"hadith","num":1561,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ ما غرت على أحد من نساء النبي صلى الله عليه وسلم ما غرت على خديجة رضي الله عنها، وما رأيتها قط، ولكن كان يكثر ذكرها، وربما ذبح الشاة، ثم يقطعها أعضاء، ثم يبعثها في صدائق خديجة، فربما قلت له‏:‏ كأن لم يكن في الدنيا إلا خديجة‏!‏ فيقول‏:‏ ‏","matn":"\"‏إنها كانت وكانت وكان لي منها ولد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية وإن كان ليذبح الشاء، فيُهدي في خلائلها منها ما يسعهن‏.‏ وفي رواية كان إذا ذبح الشاة يقول‏:‏ ‏\"‏أرسلوا بها إلى أصدقاء خديجة‏\"‏‏.‏ وفي رواية قالت‏:‏ استأذنت هالة بنت خويلد أخت خديجة على رسول الله صلى الله عليه وسلم، فعرف استئذان خديجة، فارتاح لذلك فقال‏:‏ اللهم هالة بنت خويلد‏\"‏‏.‏"},{"id":"riyad:1562","bookId":"riyad","type":"hadith","num":1562,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس بن مالك رضي الله عنه قال‏:‏ خرجت مع جرير بن عبد الله البجلي رضي الله عنه في سفر، فكان يخدمني فقلت له‏:‏ لا تفعل، فقال‏:‏ إني قد رأيت الأنصار تصنع برسول الله صلى الله عليه وسلم شيئًا آليت على نفسي أن لا أصحب أحدًا منهم إلا خدمته‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1563","bookId":"riyad","type":"hadith","num":1563,"kitab":"كتاب المقدمات","isnad":"وعن يزيد بن حيان قال‏:‏ انطلقت أنا وحصين بن سبرة، وعمرو بن مسلم إلى زيد بن أرقم رضي الله عنهم، فلما جلسنا إليه قال له حصين‏:‏ لقد لقيت يا زيد خيرًا كثيرًا، رأيت رسول الله صلى الله عليه وسلم وسمعت حديثه، وغزوت معه، وصليت خلفه‏:‏ لقد لقيت يا زيد خيرًا كثيرًا، حدثنا يا زيد ما سمعت من رسول الله صلى الله عليه وسلم قال‏:‏ يا ابن أخى والله لقد كبرت سني، وقدم عهدي، ونسيت بعض الذي كنت أعي من رسول الله صلى الله عليه وسلم، فماحدثتكم ، فاقبلوا، وما لا فلا تكلفونيه ثم قال‏:‏ قام رسول الله صلى الله عليه وسلم يومًا فينا خطيبًا بماء يدعى خماء بين مكة والمدينة، فحمد الله، وأثنى عليه، ووعظ، وذكر، ثم قال‏:‏ ‏","matn":"\"‏أما بعد، ألا أيها الناس، فإنما أنا بشر يوشك أن يأتي رسول ربي فأجيب، وأنا تارك فيكم ثقلين‏.‏ أولهما كتاب الله، فيه الهدى والنور، فخذوا بكتاب الله، واستمسكوا به‏.‏ فحث على كتاب الله، ورغب فيه ثم قال‏:‏ ‏\"‏وأهل بيتي أذكركم الله في أهل بيتي، أذكركم الله في أهل بيتي‏\"‏، فقال له حصين‏:‏ ومن أهل بيته يا زيد، أليس نساؤه من أهل بيته‏؟‏ قال‏:‏ نساؤه من أهل بيته، ولكن أهل بيته من حرم الصدقة بعده، قال‏:‏ ومن هم‏؟‏ قال‏:‏ هم آل علي، وآل عقيل، وآل جعفر، وآل عباس قال‏:‏ كل هؤلاء حرم الصدقة‏؟‏ قال‏:‏ نعم‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية ‏\"‏ ألا وإني تارك فيكم ثقلين‏:‏ أحدهما كتاب الله وحبل الله، ومن أتبعه كان على الهدى، ومن تركه كان على ضلالة‏\"‏‏.‏"},{"id":"riyad:1564","bookId":"riyad","type":"hadith","num":1564,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عمر رضي الله عنهما، عن أبي بكر رضي الله عنه موقوفًا عليه أنه قال ‏:‏ ارقبوا محمدًا صلى الله عليه وسلم في أهل بيته، ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1565","bookId":"riyad","type":"hadith","num":1565,"kitab":"كتاب المقدمات","isnad":"وعن أبي مسعود عقبة بن عمرو البدري الأنصاري رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء، فأعلمهم بالسنة، فإن كانوا في السنة سواء، فأقدمهم هجرة، فإن كانوا في الهجرة سواء، فأقدمهم سنًا، ولا يؤمن الرجل الرجل في سلطانه، ولا يقعد في بيته على تكرمته إلا بإذنه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ ‏\"‏فأقدمهم سلمًا‏\"‏ بدل ‏\"‏سنًا‏\"‏ ‏:‏ أو إسلامًا‏.‏ وفي رواية‏:‏ يؤم القوم أقرؤهم لكتاب الله، وأقدمهم قراءة، فإن كانت قراءتهم فيؤمهم أقدمهم هجرة، فإن كانوا في الهجرة سواء، فليؤمهم أكبرهم سنًا‏\"‏‏.‏"},{"id":"riyad:1566","bookId":"riyad","type":"hadith","num":1566,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ كان رسول الله صلى الله عليه وسلم يمسح مناكبنا في الصلاة ويقول‏:‏ ‏","matn":"\"‏استووا ولا تختلفوا، فتختلف قلوبكم، ليلني منكم أولو الأحلام والنهى، ثم الذين يلونهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1567","bookId":"riyad","type":"hadith","num":1567,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ليلني منكم أولو الأحلام والنهى، ثم الذين يلونهم‏\"‏ ثلاثًا ‏\"‏وإياكم وهيشات الأسوق‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1568","bookId":"riyad","type":"hadith","num":1568,"kitab":"كتاب المقدمات","isnad":"وعن أبي يحيى وقيل‏:‏ أبي محمد سهل بن أبي حَثْمة -بفتح الحاء المهملة وإسكان الثاء المثلثة -الأنصاري رضي الله عنه قال‏:‏ انطلق عبد الله ابن سهل ومحيصة بن مسعود إلى خيبر وهي صلح، فتفرقا، فأتى محيصة إلى عبد الله بن سهل وهو يتشحط في دمه قتيلاً، فدفنه، ثم قدم المدينة فانطلق عبد الرحمن بن سهل ومحيصة وحويصة ابنا مسعود إلى النبي صلى الله عليه وسلم، فذهب عبد الرحمن يتكلم فقال‏:‏ ‏","matn":"\"‏ كبر كبر‏\"‏ وهو أحدث القوم، فسكت، فتكلما فقال‏:‏ ‏\"‏أتحلفون وتستحقون قاتلكم‏؟‏ وذكر تمام الحديث‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1569","bookId":"riyad","type":"hadith","num":1569,"kitab":"كتاب المقدمات","isnad":"وعن جابر رضي الله عنه أن النبي صلى الله عليه وسلم كان يجمع بين الرجلين من قتلى أحد يعني في القبر، ثم يقول‏:‏ أيهما أكثر أخذًا للقرآن‏؟‏‏","matn":"\"‏ فإذا أشير له إلى أحدهما قدمه في اللحد‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1570","bookId":"riyad","type":"hadith","num":1570,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ أراني في المنام أتسوك بسواك، فجاءني رجلان، أحدهما أكبر من الآخر، فناولت السواك الأصغر، فقيل لي‏:‏ كبر، فدفعته إلى الأكبر منهما‏\"‏ ‏(‏‏(‏رواه مسلم والبخاري تعليقًا‏)‏‏)‏‏.‏"},{"id":"riyad:1571","bookId":"riyad","type":"hadith","num":1571,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن من إجلال الله تعالى إكرام ذي الشيبة المسلم، وحامل القرآن غير الغالي فيه، والجافي عنه وإكرام ذي السلطان المقسط‏\"‏ ‏(‏‏(‏حديث حسن رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:1572","bookId":"riyad","type":"hadith","num":1572,"kitab":"كتاب المقدمات","isnad":"وعن عمرو بن شعيب، عن أبيه ، عن جده رضي الله عنهم قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ليس منا من لم يرحم صغيرنا، ويعرف شرف كبيرنا‏\"‏ ‏(‏‏(‏حديث صحيح رواه أبو داود والترمذي، وقال الترمذي‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1573","bookId":"riyad","type":"hadith","num":1573,"kitab":"كتاب المقدمات","isnad":"وعن ميمون بن أبي شبيب رحمه الله أن عائشة رضي الله عنه الإمام مر بها سائل، فأعطته كسرة، ومر بها رجل عليه ثياب وهيئة، فأقعدته، فأكل فقيل لها في ذلك‏:‏ ‏؟‏ فقالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أنزلوا الناس منازلهم‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏ لكن قال ميمون لم يدرك عائشة‏.‏"},{"id":"riyad:1574","bookId":"riyad","type":"hadith","num":1574,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال‏:‏ قدم عيينة بن حصن، فنزل على ابن أخيه الحر بن قيس، وكان من النفر الذين يدنيهم عمر رضي الله عنه ، وكان القراء أصحاب مجلس عمر ومشاورته، كهولاً كانوا أو شبانًا ، فقال عيينة لابن أخيه‏:‏ يا ابن أخي لك وجه عند هذا الأمير، فاستأذن لي عليه، فاستأذن له، فأذن له عمر رضي الله عنه ، فلما دخل‏:‏ قال هي يا ابن الخطاب‏:‏ فوالله ما تعطينا الجزل، ولا تحكم فينا بالعدل، فغضب عمر رضي الله عنه حتى هم أن يوقع به، فقال له الحر‏:‏ يا أمير المؤمنين إن الله تعالى قال لنبيه صلى الله عليه وسلم ‏{‏خذ العفو وأمر بالعرف وأعرض عن الجاهلين‏}‏ وإن هذا من الجاهلين‏.‏ والله ما جاوزها عمر حين تلاها عليه، وكان وقافًا عند كتاب الله تعالى‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1575","bookId":"riyad","type":"hadith","num":1575,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي سعيد سمرة بن جندب رضي الله عنه قال‏:‏ لقد كنت على عهد رسول الله صلى الله عليه وسلم غلامًا ، فكنت أحفظ عنه، فما يمنعني من القول إلا أن ههنا رجالاً أسن مني‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1576","bookId":"riyad","type":"hadith","num":1576,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ما أكرم شاب شيخًا لسنه إلى قيض الله له من يكرمه عند سنه‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث غريب‏)‏‏)‏‏.‏"},{"id":"riyad:1577","bookId":"riyad","type":"hadith","num":1577,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ قال أبو بكر لعمر رضي الله عنهما بعد وفاة رسول الله صلى الله عليه وسلم‏:‏ انطلق بنا إلى أم أيمن رضي الله عنها نزورها كما كان رسول الله صلى الله عليه وسلم يزورهان فلما انتهيا إليها، بكت، فقالا لها، ما يبكيك أما تعلمين أن ما عند الله خير لرسول الله صلى الله عليه وسلم‏؟‏ فقالت‏:‏ إني لا أبكي إني لا أعلم أن ما عند الله تعالى خير لرسول الله صلى الله عليه وسلم ، ولكن أبكي أن الوحي قد انقطع من السماء، فهيجتهما على البكاء، فجعلا يبكيان معها‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1578","bookId":"riyad","type":"hadith","num":1578,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم ‏:‏ أن رجلاً زار أخا له في قرية أخرى، فأرصد الله تعالى على مدرجته ملكًا، فلما أتى عليه قال‏:‏ أين تريد‏؟‏ قال‏:‏ أريد أخًا لي في هذه القرية‏.‏ قال‏:‏ هل لك عليه من نعمة تربها عليه‏؟‏ قال‏:‏ لا غير أني أحببت في الله تعالى، قال‏:‏ فإنى رسول الله إليك بأن الله قد أحبك كما أحببته فيه‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1579","bookId":"riyad","type":"hadith","num":1579,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من عاد مريضًا أو زار أخًا له في الله، ناداه منادٍ، بأن طبت، وطاب ممشاك، وتبوأت من الجنة منزلاً‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن ، وفي بعض النسخ غريب‏)‏‏)‏‏.‏"},{"id":"riyad:1580","bookId":"riyad","type":"hadith","num":1580,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إنما مثل الجليس الصالح وجليس السوء، كحامل المسك، ونافخ الكير، فحامل المسك، إما أن يحذيك، وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبة، ونافخ الكير، إما أن يحرق ثيابك ، وإما أن تجد منه ريحًا منتنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1581","bookId":"riyad","type":"hadith","num":1581,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏تنكح المرأة لأربع‏:‏ لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1582","bookId":"riyad","type":"hadith","num":1582,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال النبي صلى الله عليه وسلم لجبريل‏:‏ ما يمنعك أن تزورنا أكثر مما تزورنا‏؟‏‏","matn":"\"‏ فنزلت ‏:‏‏{‏وما نتنزل إلا بأمر ربك له ما بين أيدينا وما خلفنا وما بين ذلك‏}‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1583","bookId":"riyad","type":"hadith","num":1583,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدري رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ لا تصاحب إلا مؤمنا، ولا يأكل طعامك إلا تقي‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي بإسناد لا بأس به‏)‏‏)‏‏.‏"},{"id":"riyad:1584","bookId":"riyad","type":"hadith","num":1584,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ الرجل على دين خليله، فلينظر أحدكم من يخالل‏\"‏‏.‏ ‏(‏‏(‏رواه أبو داود، والترمذي بإسناد صحيح، وقال الترمذي‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1585","bookId":"riyad","type":"hadith","num":1585,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ المرء مع من أحب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية قال‏:‏ قيل للنبي صلى الله عليه وسلم ‏:‏ الرجل يحب القوم ولما يلحق بهم‏؟‏ قال‏:‏ ‏\"‏المرء مع من أحب‏\"‏‏.‏"},{"id":"riyad:1586","bookId":"riyad","type":"hadith","num":1586,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه أن أعرابيًا قال لرسول الله صلى الله عليه وسلم ‏:‏ متى الساعة‏؟‏ قال رسول الله صلى الله عليه وسلم‏:‏ ما أعددت لها‏؟‏‏","matn":"\"‏ قال‏:‏ حب الله ورسوله قال‏:‏ ‏\"‏أنت مع من أحببت‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وهذا لفظ مسلم‏.‏ وفي رواية لهما‏:‏ ما أعددت لها من كثير صوم، ولا صلاة، ولا صدقة ولكني أحب الله ورسوله‏.‏"},{"id":"riyad:1587","bookId":"riyad","type":"hadith","num":1587,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ جاء رجل إلى رسول الله صلى الله عليه وسلم فقال‏:‏ يا رسول الله كيف تقول في رجل أحب قومًا ولم يلحق بهم‏؟‏ فقال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏ المرء مع من أحب‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1588","bookId":"riyad","type":"hadith","num":1588,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏الناس معادن كمعادن الذهب والفضة، خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا، والأرواح جنود مجندة، فما تعارف منها ائتلف، وما تناكر منها اختلف‏\"‏ ‏(‏‏(‏رواه مسلم‏؟‏‎‏)‏‏)‏‏.‏ ‏(‏‏(‏وروى البخاري‏)‏‏)‏ قوله‏:‏ ‏\"‏الأرواح‏\"‏ من رواية عائشة رضي الله عنها‏"},{"id":"riyad:1589","bookId":"riyad","type":"hadith","num":1589,"kitab":"كتاب المقدمات","isnad":"وعن أُسَير بن عمرو ويقال‏","matn":"\"‏‏:‏ ابن جابر وهو ‏\"‏بضم الهمزة وفتح السين المهملة‏\"‏ قال‏:‏ كان عمر بن الخطاب إذا أتى عليه أمداد أهل اليمن سألهم‏:‏ أفيكم أويس بن عامر‏؟‏ حتى أتى على أويس رضي الله عنه ، فقال له‏:‏ أنت أويس بن عامر‏؟‏ قال‏:‏ نعم، قال‏:‏ من مراد ثم من قرن‏؟‏ قال‏:‏ نعم قال‏:‏ فكان بك برص، فبرأت منه إلا موضع درهم‏؟‏ قال نعم قال‏:‏ لك والدة‏؟‏ قال ‏:‏ نعم، قال ‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول ‏\"‏يأتي عليكم أويس بن عامر مع أمداد أهل اليمن من مراد، ثم من قرن كان به برص، فبرأ منه إلا موضع درهم، له والدة هو بها بر لو أقسم على الله لأبره، فإن استطعت أن يستغفر لك فافعل‏\"‏ فاستغفر لي فاستغفر له، فقال له عمر‏:‏ أين تريد‏؟‏ قال‏:‏ الكوفة، قال‏:‏ ألا أكتب لك إلى عاملها‏؟‏ قال‏:‏ أكون في غبراء الناس أحب إلي، فلما كان من العام المقبل حج رجل من أشرافهم، فوافق عمر، فسأله عن أويس، فقال‏:‏ تركته رث البيت قليل المتاع، قال‏:‏ سمعت رسول الله يقول‏:‏ يأتي عليكم أويس بن عامر مع أمداد من أهل اليمن من مراد ، ثم من قرن، كان به برص فبرأ منه إلا موضع درهم، له والدة هو بها بر لو أقسم على الله لأبره، فإن استطعت أن يستغفر لك ‏:‏ فافعل، فأتى أويسًا، فقال استغفر لي قال‏:‏ أنت أحدث عهدًا بسفر صالح، فاستغفر لي‏.‏ قال‏:‏ لقيت عمر‏؟‏ قال‏:‏ نعم، فاستغفر له، ففطن له الناس، فانطلق على وجهه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية لمسلم أيضًا عن أُسِير بن جابر رضي الله عنه أن أهل الكوفة وفدوا على عمر رضي الله عنه ، وفيهم رجل ممن كان يسخر بأويس، فقال عمر‏:‏ هل هاهنا أحد من القرنين‏؟‏ فجاء ذلك الرجل، فقال عمر‏:‏ إن رسول الله صلى الله عليه وسلم قد قال‏:‏‏\"‏إن رجلا يأتيكم من اليمن يقال له ‏:‏ أويس، لا يدع باليمن غير أم له، قد كان به بياض فدعا الله تعالى، فأذهبه إلا موضع الدينار أو الدرهم ، فمن لقيه منكم، فليستغفر لكم‏\"‏‏.‏ وفي رواية له عن عمر رضي الله عنه قال‏:‏ ‏\"‏إنى سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\"‏إن خير التابعين رجل يقال له‏:‏ أويس‏:‏ وله والدة وكان به بياض، فمروه، فليستغفر لكم‏\"‏‏.‏"},{"id":"riyad:1590","bookId":"riyad","type":"hadith","num":1590,"kitab":"كتاب المقدمات","isnad":"وعن عمر بن الخطاب رضي الله عنه قال‏:‏ استأذنت النبي صلى الله عليه وسلم في العمرة، فأذن لي، وقال‏:‏ ‏","matn":"\"‏لا تنسنا يا أخي من دعائك‏\"‏ فقال كلمة ما يسرني أن لي بها الدنيا‏.‏ وفي رواية قال‏:‏ ‏\"‏أشركنا يا أخي في دعائك‏\"‏‏.‏ حديث صحيح ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1591","bookId":"riyad","type":"hadith","num":1591,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عمر رضي الله عنهما قال‏:‏ كان النبي صلى الله عليه وسلم يزور قباء راكبًا وماشيًا، فيصلي فيه ركعتين، ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية‏:‏ كان النبي صلى الله عليه وسلم يأتي مسجد قباء كل سبت راكبًا وماشيًا وكان ابن عمر يفعله ‏.‏"},{"id":"riyad:1592","bookId":"riyad","type":"hadith","num":1592,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ثلاث من كن فيه وجد بهن حلاوة الإيمان‏:‏ أن يكون الله ورسوله أحب إليه مما سواهما، وأن يحب المرء لا يحبه إلا لله، وأن يكره أن يعود في الكفر بعد أن أنقذه الله منه، كما يكره أن يقذف في النار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1593","bookId":"riyad","type":"hadith","num":1593,"kitab":"كتاب المقدمات","isnad":"و عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ سبعة يظلهم الله في ظله يوم لا ظل إلا ظله‏:‏ إما عادل، وشاب نشأ في عبادة الله عز وجل، ورجل قلبه معلق بالمساجد‏.‏ ورجلان تحابا في الله اجتمعا عليه ، وتفرقا عليه، ورجل دعته امرأة ذات حسن وجمال، فقال‏:‏ إني أخاف الله، ورجل تصدق بصدقة، فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا ففاضت عيناه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1594","bookId":"riyad","type":"hadith","num":1594,"kitab":"كتاب المقدمات","isnad":"وعنه قال قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ إن الله تعالى يقول يوم القيامة أين المتحابون بجلالي‏؟‏ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي‏\"‏ ‏(‏‏(‏ رواه مسلم‏)‏‏)‏ ‏.‏"},{"id":"riyad:1595","bookId":"riyad","type":"hadith","num":1595,"kitab":"كتاب المقدمات","isnad":"وعنه قال قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ والذي نفسي بيده لا تدخلوا الجنة حتى تؤمنوا ولا تؤمنوا حتى تحابوا أولا أدلكم على شيء إذا فعلتموه تحاببتم‏:‏ أفشوا السلام بينكم ‏(‏‏(‏ رواه مسلم‏)‏‏)‏ ‏.‏"},{"id":"riyad:1596","bookId":"riyad","type":"hadith","num":1596,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏أن رجلاً زار أخًا له في قريةٍ أخرى، فأرصد الله له على مدرجته ملكاً‏\"‏ وذكر الحديث إلى قوله‏:‏ ‏\"‏إن الله قد أحبك كما أحببته فيه‏\"‏ ‏(‏‏(‏رواه مسلم،‏ وقد سبق بالباب قبله)).‏"},{"id":"riyad:1597","bookId":"riyad","type":"hadith","num":1597,"kitab":"كتاب المقدمات","isnad":"وعن البراء بن عازب رضي الله عنهما عن النبي صلى الله عليه وسلم أنه قال في الأنصار‏:‏ ‏","matn":"\"‏لا يحبهم إلا مؤمن، ولا يبغضهم إلا منافق، من أحبهم أحبه الله، ومن أبغضهم أبغضه الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1598","bookId":"riyad","type":"hadith","num":1598,"kitab":"كتاب المقدمات","isnad":"وعن معاذ رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏قال الله عز وجل‏:‏ المتحابون في جلالي، لهم منابر من نور يغبطهم النبيون والشهداء‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1599","bookId":"riyad","type":"hadith","num":1599,"kitab":"كتاب المقدمات","isnad":"وعن أبي إدريس الخولاني رحمه الله قال‏:‏ دخلت مسجد دمشق، فإذا فتًى براق الثنايا وإذا الناس معه، فإذا اختلفوا بشيء، أسندوه إليه، وصدروا عن رأيه، فسألت عنه، فقيل‏:‏ هذا معاذ بن جبل رضي الله عنه، فلما كان من الغد، هجرت، فوجدته قد سبقني بالتهجير، ووجدته يصلي، فانتظرته حتى قضى صلاته، ثم جئته من قبل وجهه، فسلمت عليه، ثم قلت‏:‏ والله إني لأحبك، فقال‏:‏ آلله‏؟‏ فقال‏:‏ الله، فقال‏:‏ آلله‏؟‏ فقالت‏:‏ الله، فأخذني بحبوة ردائي، فجبذني إليه، فقال‏:‏أبشر، فإني سمعت رسول الله صلى الله عليه وسلم يقول‏:‏‏","matn":"\"‏ قال الله تعالى وجبت محبتي للمتحابين فيَّ، والمتجالسين فيَّ ، والمتزاورين فيَّ ، والمتباذلين فيَّ ‏\"‏ حديث صحيح ‏(‏‏(‏رواه مالك فيَّ الموطأ بإسناده الصحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1600","bookId":"riyad","type":"hadith","num":1600,"kitab":"كتاب المقدمات","isnad":"عن أبي كريمة المقداد بن معد يكرب رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا أحب الرجل أخاه، فليخبره أنه يحبه‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال ‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1601","bookId":"riyad","type":"hadith","num":1601,"kitab":"كتاب المقدمات","isnad":"وعن معاذ رضي الله عنه، أن رسول الله صلى الله عليه وسلم، أخذ بيده وقال‏:‏ ‏","matn":"\"‏يا معاذ، والله إني لأحبك، ثم أوصيك يا معاذ لا تدعن في دبر كل صلاة تقول‏:‏ اللهم أعني على ذكرك وشكرك، وحسن عبادتك‏\"‏‏.‏ حديث صحيح، ‏(‏‏(‏رواه أبو داود والنسائي بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1602","bookId":"riyad","type":"hadith","num":1602,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه ، أن رجلاً كان عند النبي، صلى الله عليه وسلم، فمر رجل به، فقال‏:‏ يا رسول الله إني لأحب هذا، فقال له النبي صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏أأعلمته‏؟‏‏\"‏ قال‏:‏ لا ‏:‏ قال‏:‏ ‏\"‏أعلمه‏\"‏ فلحقه، فقال ‏:‏ إني أحبك في الله، فقال‏:‏ أحبك الله الذي أحببتني له‏.‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1603","bookId":"riyad","type":"hadith","num":1603,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن الله تعالى قال‏:‏ ‏\"‏من عاد لي وليَّا، فقد آذنته بالحرب، وما تقرب إلي عبدي بشيء أحب إليَّ مما افترضت عليه، وما يزال عبدي يتقرب إليَّ بالنوافل حتى أحبه فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به، ويده التي يبطش بها، ورجله التي يمشي بها، وإن سألني، أعطيته، ولئن استعاذني، لأعيذنه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1604","bookId":"riyad","type":"hadith","num":1604,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي، صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏إذا أحب الله العبد نادى جبريل‏:‏ إن الله تعالى يحب فلانًا، فأحببه، فيحبه جبريل، فينادي في أهل السماء‏:‏ إن الله يحب فلانًا، فأحبوه، فيحبه أهل السماء، ثم يوضع له القبول في الأرض‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لمسلم ‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏إن الله تعالى إذا أحب عبدًا دعا جبريل، فقال ‏:‏ إني أحب فلانًا فأحببه، فيحبه جبريل، ثم ينادي في السماء، فيقول‏:‏ إن الله يحب فلانًا، فأحبوه فيحبه أهل السماء، ثم يوضع له القبول في الأرض، وإذا أبغض عبدًا دعا جبريل فيقول‏:‏ إني أبغض فلانًا، فأبغضه، فيبغضه جبريل، ثم ينادي في أهل السماء، إن الله يبغض فلانًا، فأبغضوه، ثم توضع له البغضاء في الأرض‏\"‏‏.‏"},{"id":"riyad:1605","bookId":"riyad","type":"hadith","num":1605,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها، أن رسول الله صلى الله عليه وسلم، بعث رجلاً على سرية، فكان يقرأ لأصحابه في صلاتهم، فيختم بـ‏{‏قل هو الله أحد‏}‏ فلما رجعوا، ذكروا ذلك لرسول الله، صلى الله عليه وسلم، فقال‏:‏ ‏","matn":"\"‏سلوه لأي شيء كان يصنع ذلك‏؟‏ ‏\"‏ فسألوه، فقال ‏:‏ لأنها صفة الرحمن، فأنا أحب أن أقرأ بها، فقال رسول الله صلى الله عليه وسلم ‏:‏‏\"‏أخبروه أن الله تعالى يحبه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1606","bookId":"riyad","type":"hadith","num":1606,"kitab":"كتاب المقدمات","isnad":"وعن جندب بن عبد الله رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ من صلى صلاة الصبح، فهو في ذمة الله، فلا يطلبنكم الله من ذمته بشئ، فإنه من يطلبه من ذمته بشئ، يدركه، ثم يكبه على وجهه في نار جهنم ‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1607","bookId":"riyad","type":"hadith","num":1607,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله ، وأن محمداً رسول الله ، ويقيموا الصلاة، ويؤتوا الزكاة ، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على الله تعالى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1608","bookId":"riyad","type":"hadith","num":1608,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله طارق بن أشيم ، رضي الله عنه ، قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ من قال لا إله إلا الله ، وكفر بما يعبد من دون الله، حرم ماله ودمه، وحسابه على الله تعالى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1609","bookId":"riyad","type":"hadith","num":1609,"kitab":"كتاب المقدمات","isnad":"وعن أبي المقداد بن الأسود، رضي الله عنه ، قال‏:‏ قلت لرسول الله صلى الله عليه وسلم ‏:‏ أرأيت إن لقيت رجلاً من الكفار، فاقتتلنا، فضرب إحدى يدى بالسيف، فقطعها، ثم لاذ منى بشجرة، فقال أسلمت لله، أأقتله يارسول الله بعد أن قالها‏؟‏ فقال‏:‏ ‏","matn":"\"‏لا تقتله، فإن قتلته، فإنه بمنزلتك قبل أن تقتله، وإنك بمنزلته قبل أن يقول كلمته التى قال‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏ (‏‏(‏ومعنى ‏ ‏ أنه بمنزلتك‏ ‏ أي ‏:‏معصوم الدم محكوم بإسلامه، ومعنى ‏ ‏أنك بمنزلته‏ ‏ أي ‏:‏ مباح الدم بالقصاص لورثته، لا أنه بمنزلته في الكفر؛ والله أعلم‏)‏‏)‏‏.‏"},{"id":"riyad:1610","bookId":"riyad","type":"hadith","num":1610,"kitab":"كتاب المقدمات","isnad":"وعن أسامة بن زيد، رضي الله عنهما، قال‏:‏ بعثنا رسول الله صلى الله عليه وسلم، إلى الحرقة من جهينة ، فصبحنا القوم على مياههم، ولحقت أنا ورجل من الأنصار رجلاً منهم، فلما غشيناه قال‏:‏ لا إله إلا الله ، فكف عنه الأنصاري، وطعنته برمحي حتى قتلته، فلما قدمنا المدينة بلغ ذلك النبي، صلى الله عليه وسلم، فقال لى‏:‏ ‏","matn":"\"‏ يا أسامة أقتلته بعد ما قال لا إله إلا الله‏؟‏‏!‏ قلت يا رسول الله إنما كان متعوذا فقال ” أقتلته بعد ما قال لا إله إلا الله‏؟‏‏!‏‏\"‏ فما زال يكررها على حتى تمنيت أني لم أكن أسلمت قبل ذلك اليوم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية‏:‏ فقال رسول الله صلى الله عليه وسلم ‏\"‏أقال ‏:‏ لا إله إلا الله وقتلته‏؟‏‏!‏ قلت‏:‏ يا رسول الله، إنما قالها خوفاً من السلاح، قال‏:‏ ‏\"‏أفلا شققت عن قلبه حتى تعلم أقالها أم لا‏؟‏‏!‏‏\"‏ فما زال يكررها حتى تمنيت أني أسلمت يومئذ‏.‏"},{"id":"riyad:1611","bookId":"riyad","type":"hadith","num":1611,"kitab":"كتاب المقدمات","isnad":"وعن جندب بن عبد الله، رضي الله عنه ، أن رسول الله صلى الله عليه وسلم، بعث بعثاً من المسلمين إلى قوم من المشركين، وأنهم التقوا فكان رجلاً من المشركين إذا شاء أن يقصد إلى رجل من المسلمين قصد له فقتله، وأن رجلاً من المسلمين قصد غفلته، وكنا نتحدث أنه أسامة بن زيد، فلما رفع عليه السيف ، قال‏:‏ لا إله إلا الله، فقتله، فجاء البشير إلى رسول الله ، صلى الله عليه وسلم فسأله ، وأخبره، حتى أخبره خبر الرجل كيف صنع ، فدعاه فسأله، فقال‏:‏ ‏","matn":"\"‏لم قتلته‏؟‏ فقال‏:‏ يا رسول الله أوجع في المسلمين، وقتل فلانا وفلانا -وسمى له نفراً- وإني حملت عليه، فلما رأى السيف قال‏:‏ لا إله إلا الله‏.‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏اقتلته‏؟‏‏\"‏ قال نعم ‏:‏ قال‏:‏ ‏\"‏فكيف تصنع بلا إله إلا الله، إذا جاءت يوم القيامة‏؟‏ قال‏:‏ يا رسول الله استغفر لي‏.‏ قال‏:‏ ‏\"‏وكيف تصنع بلا إله إلا الله إذا جاءت يوم القيامة‏؟‏ ‏\"‏ فجعل لا يزيد على أن يقول‏:‏ ‏\"‏ كيف تصنع بلا إله إلا الله إذا جاءت يوم القيامة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1612","bookId":"riyad","type":"hadith","num":1612,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عتبة بن مسعود قال‏:‏ سمعت عمر بن الخطاب، رضي الله عنه، يقول‏:‏ ‏","matn":"\"‏إن ناساً كانوا يؤخذون بالوحي في عهد رسول الله صلى الله عليه وسلم وإن الوحى قد انقطع، وإنما نأخذهم الآن بما ظهر لنا من أعمالكم، فمن أظهر لنا خيراً، أمناه وقربناه، وليس لنا من سريرته شئ، الله يحاسبه في سريرته، ومن أظهر لنا سوءاً، لم نأمنه، ولم نصدقه وإن قال‏:‏ إن سريرته حسنة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1613","bookId":"riyad","type":"hadith","num":1613,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود، رضي الله عنه ، قال‏:‏ حدثنا رسول الله صلى الله عليه وسلم، وهو الصادق المصدوق‏:‏ ‏","matn":"\"‏إن أحدكم يجمع خلقه في بطن أمه أربعين يوماً نطفةً، ثم يكون علقة مثل ذلك، ثم يكون مضغةً مثل ذلك، ثم يرسل الملك، فينفخ فيه الروح، ويؤمر بأربع كلمات‏:‏ يكتب رزقه، وأجله، وعمله، وشقى أم سعيد‏.‏ فوالذي لا إله غيره إن أحدكم ليعمل بعمل أهل الجنة حتى ما يكون بينه وبينها إلى ذراع، فيسبق عليه الكتاب ، فيعمل بعمل أهل النار فيدخلها، وإن أحدكم ليعمل بعلم أهل النار حتى ما يكون بينه وبينها إلا ذراع، فيسبق عليه الكتاب فيعمل بعمل أهل الجنة فيدخلها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1614","bookId":"riyad","type":"hadith","num":1614,"kitab":"كتاب المقدمات","isnad":"وعنه قال ‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ يؤتى بجهنم يومئذ لها سبعون ألف زمام مع كل زمام سبعون ألف ملك يجرونها ‏\"‏ ‏(‏‏(‏ رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1615","bookId":"riyad","type":"hadith","num":1615,"kitab":"كتاب المقدمات","isnad":"وعن النعمان بن بشير رضي الله عنهما قال ‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ إن أهون أهل النار عذابا يوم القيامة لرجل يوضع في أخمص قدميه جمرتان يغلي منهما دماغه، ما يرى أن أحد أشد منه عذابا، وإنه لأهونهم عذابا‏","matn":"\"‏ ‏(‏‏(‏ متفق عليه‏)‏‏)‏"},{"id":"riyad:1616","bookId":"riyad","type":"hadith","num":1616,"kitab":"كتاب المقدمات","isnad":"وعن سمرة بن جندب، رضي الله عنه، أن نبى الله، صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ منهم من تأخذه النار إلى كعبيه، ومن من تأخذ إلى ركبتيه، ومنهم من تأخذه إلى حجزته، ومنهم من تأخذه إلى ترقوته‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ('‏‏ ‏الحجزة‏ ‏ ‏:‏ معقد الإزار تحت السرة و‏ ‏الترقوة‏ ‏ بفتح التاء وضم القاف‏:‏ هي العظم الذي عند ثغرة النحر، وللإنسان ترقوتان في جانبى النحر ‏')"},{"id":"riyad:1617","bookId":"riyad","type":"hadith","num":1617,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما أن رسول الله، صلى الله عليه وسلم، قال‏","matn":"\"‏ يقوم الناس لرب العالمين حتى يغيب أحدهم في رشحه إلى أنصاف أذنيه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏(‏‏(‏و‏ ‏الرشح‏ :‏ العرق‏)‏‏)‏‏.‏"},{"id":"riyad:1618","bookId":"riyad","type":"hadith","num":1618,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه، قال‏:‏ خطبنا رسول الله، صلى الله عليه وسلم خطبة ما سمعت مثلها قط، فقال‏:‏ ‏","matn":"\"‏لو تعلمون ما أعلم لضحكتم قليلاً ولبكيتم كثيراً‏\"‏ فغطى أصحاب رسول الله، صلى الله عليه وسلم وجوههم، ولهم خنين‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية‏:‏ بلغ رسول الله، صلى الله عليه وسلم عن أصحابه شئ فخطب ، فقال‏:‏ ‏\"‏عرضت على الجنة والنار، فلم أر كاليوم في الخير والشر، ولو تعلمون ما أعلم لضحكتم قليلا، ولبكيتم كثيراً‏\"‏ فما أتى على أصحاب رسول الله، صلى الله عليه وسلم يوم أشد منه، غطوا رؤوسهم ولهم خنين‏.‏"},{"id":"riyad:1619","bookId":"riyad","type":"hadith","num":1619,"kitab":"كتاب المقدمات","isnad":"وعن المقداد، رضي الله عنه، قال‏:‏ سمعت رسول الله، صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏تدنى الشمس يوم القيامة من الخلق حتى تكون منهم كمقدار ميل‏\"‏ قال سليم بن عامر الراوى عن المقداد‏:‏ فوالله ما أدري ما يعني الميل، أمسافة الأرض أم الميل الذي يكحل به العين ‏\"‏فيكون الناس على قد أعمالهم في العرق، فمنهم من يكون إلى كعبيه، ومنهم من يكون إلى ركبتيه، ومنهم من يكون إلى حقوبه، ومنهم من يلجمه العرق إلجاماً‏\"‏ وأشار رسول الله، صلى الله عليه وسلم، بيده إلى فيه ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1620","bookId":"riyad","type":"hadith","num":1620,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه ، أن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏يعرق الناس يوم القيامة حتى يذهب عرقهم في الأرض سبعين ذراعاً، ويلجمهم حتى يبلغ آذانهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ '‏‏(‏‏(‏ومعنى ‏ ‏يذهب في الأرض‏ ‏ ‏:‏ ينزل ويغوص‏)‏‏)‏‏.‏ ‏'"},{"id":"riyad:1621","bookId":"riyad","type":"hadith","num":1621,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ كنا مع رسول الله، صلى الله عليه وسلم إذا سمع وجبة فقال‏:‏ ‏","matn":"\"‏هل تدرون ما هذا‏؟‏‏\"‏ قلنا‏:‏ الله ورسوله أعلم‏.‏ قال‏:‏ هذا حجر رمى به في النار منذ سبعين خريفاً فهو يهوي في النار الآن حتى انتهي إلى قعره، فسمعتم وجبتها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1622","bookId":"riyad","type":"hadith","num":1622,"kitab":"كتاب المقدمات","isnad":"وعن عدى بن حاتم، رضي الله عنه ، قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏","matn":"\"‏ما منكم من أحد إلا سيكلمه ربه ليس بينه وبينه ترجمان، فينظر أيمن منه، فلا يرى إلا ماقدم، وينظر أشأم منه، فلا يرى إلا ما قدم، وينظر بين يديه، فلا يرى إلا النار تلقاء وجهه، فاتقوا النار ولو بشق تمرة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1623","bookId":"riyad","type":"hadith","num":1623,"kitab":"كتاب المقدمات","isnad":"وعن أبي ذر رضي الله عنه ، قال‏:‏ قال رسول الله ،صلى الله عليه وسلم ‏","matn":"\"‏إنى أرى ما لا ترون؛ أطت السماء وحق لها أن تئط، ما فيها موضع أربع أصابع إلا وملك واضع جبهته ساجداً لله تعالى، والله لو تعلمون ما أعلم، لضحكتم قليلاً، ولبكيتم كثيراً، وما تلذذتم بالنساء على الفرش، ولخرجتم إلى الصعدات تجأورن إلى الله تعالى‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ و‏ ‏أطت‏ ‏ بفتح الهمزة وتشديد الطاء‏ و‏ ‏تئط‏ ‏ بفتح التاء وبعدها همزة مكسورة، والأطيط‏:‏ صوت الرحل والقتب وشبههما، ومعناه‏:‏ أن كثرة من في السماء من الملائكة العابدين قد أثقلتها حتى أطت‏.‏"},{"id":"riyad:1624","bookId":"riyad","type":"hadith","num":1624,"kitab":"كتاب المقدمات","isnad":"وعن أبي برزة -براء ثم زاى- نضلة بن عبيد الأسلمى، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تزول قدما عبد يوم القيامة حتى يسأل عن عمره فيما أفناه ، وعن علمه فيما فعل فيه، وعن ماله من أين اكتسبه، وفيما أنفقه، وعن جسمه فيم أبلاه‏\"‏ ‏(‏‏(‏رواه الترمذي وقاال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1625","bookId":"riyad","type":"hadith","num":1625,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه ، قال‏:‏ قرأ رسول الله، صلى الله عليه وسلم ‏{‏يومئذ تحدث أخبارها‏}‏ ثم قال‏:‏ ‏","matn":"\"‏أتدرون ما أخبارها‏؟‏‏\"‏ قالوا الله ورسوله أعلم‏.‏ قال‏:‏ ‏\"‏فإن أخبارها أن تشهد كل عبد أو أمة بما عمل على ظهرها تقول‏:‏ عملت كذا وكذا في يوم كذا وكذا، فهذه أخبارها‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن‏ صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1626","bookId":"riyad","type":"hadith","num":1626,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعدي الخدرى، رضي الله عنه، قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏","matn":"\"‏كيف أنعم وصاحب القرن قد التقم ، واستمع الإذن متى يؤمر بالنفخ فينفخ‏\"‏ فكأن ذلك ثقل على أصحاب رسول الله ، صلى الله عليه وسلم فقال لهم‏:‏‏\"‏قولوا ‏:‏حسبنا الله ونعم الوكيل‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1627","bookId":"riyad","type":"hadith","num":1627,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏","matn":"\"‏من خاف أدلج ، ومن أدلج، بلغ المنزل، ألا إن سلعة الله غالية، إلا إن سلعة الله الجنة‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1628","bookId":"riyad","type":"hadith","num":1628,"kitab":"كتاب المقدمات","isnad":"وعن عائشة، رضي الله عنها، قالت‏:‏ سمعت رسول الله، صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ يحشر الناس يوم القيامة حفاة عراة غرلا‏\"‏ قلت‏:‏ يا رسول الله الرجال والنساء جميعاً ينظر بعضهم إلى بعض‏؟‏ قال‏:‏ ‏\"‏يا عائشة الأمر أشد من أن يهمهم ذلك‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏الأمر أهم من أن ينظر بعضهم إلى بعض‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1629","bookId":"riyad","type":"hadith","num":1629,"kitab":"كتاب المقدمات","isnad":"وعن عبادة بن الصامت، رضي الله عنه ، قال‏:‏ قال رسول الله، صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من شهد أن لا إله إلا الله وحده لا شريك له، وأن محمداً عبده ورسوله، وأن عيسى عبد الله ورسوله، وكلمته ألقاها إلى مريم وروح منه، وأن الجنة حق والنار حق، أدخله الله الجنة على ما كان من العمل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفي رواية لمسلم‏:‏‏\"‏من شهد أن لا إله إلا الله، وأن محمداً رسول الله، حرم عليه النار‏\"‏‏.‏"},{"id":"riyad:1630","bookId":"riyad","type":"hadith","num":1630,"kitab":"كتاب المقدمات","isnad":"وعن أبي ذر، رضي الله عنه ، قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏يقول الله عز وجل‏:‏ من جاء بالحسنة، فله عشر أمثالها أو أزيد، ومن جاء بالسيئة، فجزاء سيئة سيئة مثلها أوغفر‏.‏ ومن تقرب مني شبراً ، تقربت منها ذراعا، ومن تقرب منى ذراعاً ، تقربت منه باعاً، ومن أتاني يمشي ، أتيته هرولة، ومن لقينى بقراب الأرض خطيئة لايشرك به شيئاً ، لقيته بمثلها مغفرة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1631","bookId":"riyad","type":"hadith","num":1631,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن جابر قَالَ : جاء أعرابي إِلَى النَّبيّ فَقَالَ : يَا رَسُول الله ، مَا الموجِبَتَانِ ؟ قَالَ : « مَنْ مَاتَ لا يُشْرِكُ بالله شَيئاً دَخَلَ الجَنَّةَ ، وَمَنْ مَاتَ يُشْرِكُ بِهِ شَيْئاً دَخَلَ النَّار » . رواه مسلم ."},{"id":"riyad:1632","bookId":"riyad","type":"hadith","num":1632,"kitab":"كتاب المقدمات","isnad":"وعن أنس ، رضي الله عنه ، أن النبي صلى الله عليه وسلم، ومعاذ رديفه على الرحل قال‏:‏ ‏","matn":"\"‏يا معاذ‏\"‏ قال‏:‏ لبيك يا رسول الله وسعديك، قال‏:‏ ‏\"‏يامعاذ‏\"‏ قال ‏:‏لبيك يا رسول الله وسعديك‏.‏ قال‏:‏ ‏\"‏يا معاذ‏\"‏ قال‏:‏ لبيك يا رسول الله وسعديك ثلاثاً، قال‏:‏ ‏\"‏ما من عبد يشهد أن لا إله إلا الله ، وأن محمداً عبده ورسوله صدقاً من قلبه إلا حرمه الله على النار‏\"‏ قال‏:‏ يا رسول الله أفلا أخبر بها الناس فيستبشروا‏؟‏ قال‏:‏ ‏\"‏إذا يتكلوا‏\"‏ فأخبر بها معاذ عند موته تأثما ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1633","bookId":"riyad","type":"hadith","num":1633,"kitab":"كتاب المقدمات","isnad":"-وعن أبي هريرة -أو أبي سعيد الخدرى- رضي الله عنهما‏:‏ شك الراوى، ولا يضر الشك في عين الصحابي‏:‏ لأنهم كلهم عدول، قال لما كان غزوة تبوك، أصاب الناس مجاعة، فقالوا ‏:‏ يا رسول الله لو أذنت لنا فنحرنا نواضحنا، فأكلنا وادهنا‏؟‏ فقال رسول الله، صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏افعلوا‏\"‏ فجاء عمر رضي الله عنه، فقال‏:‏ يا رسول الله إن فعلت، قل الظهر، ولكن ادعهم بفضل أزوادهم، ثم ادع الله لهم عليها بالبركة لعل الله أن يجعل في ذلك البركة‏.‏ فقال رسول الله، صلى الله عليه وسلم‏:‏ “نعم” فدعا بنطع فبسطه، ثم دعا بفضل أزوادهم، فجعل الرجل يجئ بكف ذرة، ويجئ الآخر بكف تمر، ويجئ الآخر بكسرةٍ حتى اجتمع على النطع من ذلك شئ يسير، فدعا رسول الله، صلى الله عليه وسلم بالبركة، ثم قال‏:‏ “خذوا في أوعيتكم فأخذوا في أوعيتهم حتى ما تركوا في العسكر وعاء إلا ملأوه، وأكلوا حتى شبعوا وفضل فضلة، فقال رسول الله صلى الله عليه وسلم ‏:‏”أشهد أن لا إله إلا الله ، وأني رسول الله، لا يلقى الله بهما عبد غير شاك؛ فيحجب عن الجنة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1634","bookId":"riyad","type":"hadith","num":1634,"kitab":"كتاب المقدمات","isnad":"وعن عتبان بن مالك، رضي الله عنه ، وهو ممن شهد بدراً ، قال‏:‏ كنت أصلي لقومي بنى سالم، وكان يحول بيني وبينهم واد إذا جاءت الأمطار، فيشق على اجتيازه قبل مسجدهم ، فجئت رسول الله، صلى الله عليه وسلم، فقلت له ‏:‏ إنى أنكرت بصرى، وإن الوادي الذي بينى وبين قومى يسيل إذا جاءت الأمطار، فيشق على اجتيازه، فوددت أنك تأتي ، فتصلي في بيتي مكاناً أتخذه مصلى، فقال رسول الله صلى الله عليه وسلم ‏:‏‏","matn":"\"‏سأفعل‏\"‏، فغدما على رسول الله ، وأبو بكر، رضي الله عنه بعد ما اشتد النهار، واستأذن رسول الله، صلى الله عليه وسلم ، فأذنت له، فلم يجلس حتى قال‏:‏ ‏\"‏أين تحب أن أصلي من بيتك‏؟‏‏\"‏ فأشرت له إلى المكان الذي أحب أن يصلي فيه، فقام رسول الله ، صلى الله عليه وسلم، فكبر وصففنا وراءه، فصلى ركعتين، ثم سلم وسلمنا حين سلم، فحبسته على خزيرة تصنع له، فسمع أهل الدار أن رسول الله ، صلى الله عليه وسلم في بيتي، فثاب رجال منهم حتى كثر الرجال في البيت، فقال رجل ‏:‏ ما فعل مالك لا أراه‏!‏ فقال رجل‏:‏ ذلك منافق لا يحب الله ورسوله، فقال رسول الله، صلى الله عليه وسلم‏:‏ ‏\"‏ لا تقل ذلك، ألا تراه قال‏:‏ لا إله إلا الله يبتغي بذلك وجه الله تعالى ‏؟‏_ ‏!‏‏\"‏ فقال‏:‏ الله ورسوله أعلم، أما نحن فو الله ما نرى وده، ولا حديثه إلا المنافقين _‏!‏ فقال رسول الله ، صلى الله عليه وسلم، ‏\"‏فإن الله قد حرم على النار من قال ‏:‏ لا إله إلا الله يبتغي بذلك وجه الله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ('‏و‏ ‏عتبان‏ ‏ بكسر العين المهملة، وإسكان التاء المثناة فوق وبعدهما باء موحدة‏.‏ و‏ ‏الخزيرة‏ ‏ بالخاء المعجمة، والزاى‏:‏ هي دقيق يطبخ بشحم‏.‏ وقوله‏:‏ ‏ ‏ثاب رجال ‏ ‏ بالثاء المثلثة، أي ‏:‏ جاؤوا واجتمعوا‏.‏ ‏')"},{"id":"riyad:1635","bookId":"riyad","type":"hadith","num":1635,"kitab":"كتاب المقدمات","isnad":"وعن عمر بن الخطاب، رضي الله عنه ، قال‏:‏ قدم رسول الله ، صلى الله عليه وسلم، بسبي، فإذا امرأة من السبي تسعى، إذ وجدت صبياً في السبي أخذته، فألزقته ببطنها، فأرضعته، فقال رسول الله، صلى الله عليه وسلم‏:‏ “أترون هذه المرأة طارحة ولدها في النار‏؟‏” قلنا لا والله ‏.‏ قال‏:‏ ‏","matn":"\"‏لله أرحم بعباده من هذه الأم بولدها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1636","bookId":"riyad","type":"hadith","num":1636,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه ، قال‏:‏ قال رسول الله ، صلى الله عليه وسلم لما خلق الله الخلق، كتب في كتاب، فهو عنده فوق العرش‏:‏ إن رحمتي تغلب غضبي‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1637","bookId":"riyad","type":"hadith","num":1637,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ سمعت رسول الله ، صلى الله عليه وسلم يقول‏:‏ “جعل الله الرحمة مائة جزء فأمسك عنده تسعة وتسعين، وأنزل في الأرض جزءا واحداً، فمن ذلك الجزء يتراحم الخلائق حتى ترفع الدابة حافرها عن ولدها خشية أن تصيبه‏","matn":"\"‏‏.‏ ‏\"‏وفي رواية‏:‏ ‏\"‏إن لله تعالى مائة رحمة أنزل منها رحمة واحدة بين الجن والإنس والبهائم والهوام، فيها يتعاطفون، وبها يتراحمون، وبها تعطف الوحش على ولدها، وأخر الله تعالى تسعاً وتسعين رحمة يرحم بها عباده يوم القيامة” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ورواه مسلم أيضاً من رواية سلمان الفارسي، رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “إن لله تعالى مائة رحمة فمنها رحمة يتراحم بها الخلق بينهم، وتسع وتسعون ليوم القيامة‏\"‏ ‏\"‏وفي رواية‏:‏ ‏\"‏إن الله تعالى خلق يوم خلق السماوات والأرض مائة رحمة كل رحمة طباق ما بين السماء إلى الأرض، فجعل منها في الأرض رحمة، فيها تعطف الوالدة على ولدها، والوحش والطير بعضها على بعض، فإذا كان يوم القيامة، أكملها بهذه الرحمة”‏.‏"},{"id":"riyad:1638","bookId":"riyad","type":"hadith","num":1638,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه عن النبي صلى الله عليه وسلم، فيما يحكى عن ربه، تبارك وتعالى، قال‏:‏ “أذنب عبدي ذنباً، فقال‏:‏ اللهم اغفر لى ذنبي، فقال الله تبارك وتعالى‏:‏ أذنب عبدى ذنبا، فعلم أن له رباً يغفر الذنب، ويأخذ بالذنب، ثم عاد فأذنب، فقال‏:‏ أي رب اغفر لي ذنبي، فقال تبارك وتعالى‏:‏ أذنب عبدي ذنباً، فعلم أن له رباً يغفر الذنب، ويأخذ بالذنب، ثم عاد فأذنب، فقال‏:‏ أي رب اغفر لى ذنبي، فقال، تبارك وتعالى‏:‏ أذنب عبدي ذنباً، فعلم أن له رباً يغفر الذنب، ويأخذ بالذنب، قد غفرت لعبدى فليفعل ما شاء” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وقوله تعالى‏:‏ “فليفعل ما شاء” أي‏:‏ ما دام يفعل هكذا، يذنب ويتوب اغفر له، فإن التوبة تهدم ما قبلها‏."},{"id":"riyad:1639","bookId":"riyad","type":"hadith","num":1639,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ “والذي نفسي بيده لو لم تذنبوا، لذهب الله بكم، ولجاء بقوم يذنبون، فيستغفرون الله تعالى، فيغفر لهم” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1640","bookId":"riyad","type":"hadith","num":1640,"kitab":"كتاب المقدمات","isnad":"وعن أبي أيوب خالد بن زيد، رضي الله عنه ، قال سمعت رسول الله صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏لولا أنكم تذنبون ؛ لخلق الله خلقاً يذنبون، فيستغفرون، فيغفر لهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1641","bookId":"riyad","type":"hadith","num":1641,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة رضي الله عنه ، قال‏:‏ كنا قعوداً مع رسول الله صلى الله عليه وسلم، معنا أبو بكر وعمر، رضي الله عنهما في نفر، فقام رسول الله، صلى الله عليه وسلم، من بين أظهرنا، فأبطأ علينا، فخشينا أن يقتطع دوننا، ففزعنا، فقمنا، فكنت أول من فزع، فخرجت ابتغي رسول الله صلى الله عليه وسلم، حتى أتيت حائطاً للأنصار -وذكر الحديث بطوله إلى قوله‏:‏ فقال رسول الله، صلى الله عليه وسلم، “اذهب فمن لقيت وراء هذا الحائط يشهد أن لا إله إلا الله ، مستيقناً بها قلبه فبشره بالجنة” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1642","bookId":"riyad","type":"hadith","num":1642,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، أن النبي، صلى الله عليه وسلم، تلا قول الله عز وجل في إبراهيم، صلى الله عليه وسلم‏:‏ ‏{‏رب إنهن أضللن كثيراً من الناس فمن تبعني فإنه مني‏}‏ ‏(‏‏(‏إبراهيم‏:‏36‏)‏‏)‏، وقول عيسى، صلى الله عليه وسلم‏:‏‏{‏إن تعذبهم فإنهم عبادك وإن تغفر لهم فإنك أنت العزيز الحكيم‏}‏ ‏(‏‏(‏المائدة‏:‏ 118‏)‏‏)‏، فرفع يديه وقال‏:‏ ‏","matn":"\"‏اللهم أمتى أمتى” وبكى، فقال الله عز وجل‏:‏‏\"‏ ‏\"‏ يا جبريل اذهب إلى محمد وربك أعلم، فسله ما يبكيه‏؟‏ “ فأتاه جبريل، فأخبره رسول الله صلى الله عليه وسلم، بما قال‏:‏ وهو أعلم، فقال الله تعالى‏:‏ ‏\"‏يا جبريل اذهب إلى محمد فقل‏:‏ إنا سنرضيك في أمتك ولا نسؤوك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1643","bookId":"riyad","type":"hadith","num":1643,"kitab":"كتاب المقدمات","isnad":"وعن معاذ بن جبل ، رضي الله عنه ، قال‏:‏ كنت ردف النبي صلى الله عليه وسلم، على حمار فقال‏:‏ ‏","matn":"\"‏ يا معاذ هل تدري ما حق الله على عباده، وما حق العباد على الله‏.‏ ‏؟‏ قلت‏:‏ الله ورسوله أعلم‏.‏ قال‏:‏‏\"‏فإن حق الله على العباد أن يعبدوه، ولا يشركوا به شيئاً، وحق العباد على الله أن لا يعذب من لا يشرك به شيئاً، فقلت، يا رسول الله أفلا أبشر الناس‏؟‏ قال لا تبشرهم فيتكلوا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1644","bookId":"riyad","type":"hadith","num":1644,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن البراء بن عازب، رضي الله عنهما، عن النبي، صلى الله عليه وسلم، قال‏:‏ “المسلم إذا سئل في القبر يشهد أن لا إله إلا الله، وأن محمداً رسول الله، فذلك قوله تعالى‏:‏ ‏{‏يثبت الله الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة‏}‏ ‏(‏‏(‏إبراهيم‏:‏27‏)‏‏)‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1645","bookId":"riyad","type":"hadith","num":1645,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه ،عن رسول الله، صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏إن الكافر إذا عمل حسنة، أطعم بها طعمة من الدنيا، أما المؤمن، فإن الله تعالى يدخر له حسناته في الآخرة، ويعقبه رزقاً في الدنيا على طاعته‏\"‏‏.‏ وفي رواية‏:‏ ‏\"‏إن الله لا يظلم مؤمنا حسنة يعطى بها في الدنيا، ويجزى بها في الآخرة، وأما الكافر، فيطعم بحسنات ما عمل لله تعالى، في الدنيا حتى إذا أفضى إلى الآخرة، لم يكن له حسنة يجزى بها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1646","bookId":"riyad","type":"hadith","num":1646,"kitab":"كتاب المقدمات","isnad":"وعن جابر، رضي الله عنه قال‏:‏ قال رسول الله ، صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏مثل الصلوات الخمس كمثل نهر جار غمر على باب أحدكم يغتسل منه كل يوم خمس مرات‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ('‏‏الغمر: الكثير‏.‏')"},{"id":"riyad:1647","bookId":"riyad","type":"hadith","num":1647,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس، رضي الله عنهما، قال‏:‏ سمعت رسول الله، صلى الله عليه وسلم، يقول‏:‏ ‏","matn":"\"‏ما من رجل مسلم يموت فيقوم على جنازته أربعون رجلاً لا يشركون بالله شيئاً إلا شفعهم الله فيه‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1648","bookId":"riyad","type":"hadith","num":1648,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود، رضي الله عنه ، قال‏:‏ كنا مع رسول الله صلى الله عليه وسلم في قبة نحوا من أربعين ، فقال‏:‏ ‏","matn":"\"‏أترضون أن تكونوا ربع أهل الجنة‏؟‏‏\"‏ قلنا نعم، قال‏:‏ أترضون أن تكونوا ثلث أهل الجنة‏؟‏ قلنا‏:‏ نعم، قال‏:‏ ‏\"‏والذي نفسى محمد بيده إني لأرجو أن تكونوا نصف أهل الجنة، وذلك أن الجنة لا يدخلها إلا نفس مسلمة، وما أنتم في أهل الشرك إلا كالشعرة البيضاء في جلد الثور الأسود، أو كالشعرة السوداء في جلد الثور الأحمر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1649","bookId":"riyad","type":"hadith","num":1649,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري، رضي الله عنه، قال‏:‏ قال رسول الله، صلى الله عليه وسلم‏:‏ إذا كان يوم القيامة دفع الله إلى كل مسلم يهودياً أونصرانياً فيقول‏:‏ هذا فكاكك من النار‏","matn":"\"‏‏.‏ وفي رواية عنه عن النبي، صلى الله عليه وسلم قال‏:‏ ‏\"‏يجئ يوم القيامة ناس من المسلمين بذنوب أمثال الجبال يغفرها الله لهم ‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1650","bookId":"riyad","type":"hadith","num":1650,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم، يقول‏:‏ يدنى المؤمن يوم القيامة من ربه حتى يضع كنفه عليه، فيقرره بذنوبه، فيقول‏:‏ أتعرف ذنب كذا‏؟‏ أتعرف ذنب كذا‏؟‏ فيقول‏:‏ رب أعرف قال‏:‏ فإني قد سترتها عليك في الدنيا، وأنا أغفرها لك اليوم، فيعطى صحيفة حسناته‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏‏(‏‏(‏كنفه‏:‏ ستره ورحمته‏)‏‏)‏‏.‏"},{"id":"riyad:1651","bookId":"riyad","type":"hadith","num":1651,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود، رضي الله عنه ، أن رجلاً أصاب من امرأة قبلة، فأتى النبي، صلى الله عليه وسلم، فأخبره، فأنزل الله تعالى‏:‏ ‏{‏ وأقم الصلاة طرفي النهار وزلفاً من الليل إن الحسنات يذهبن السيئات ‏}‏ ‏(‏‏(‏هود‏:‏114‏)‏‏)‏ فقال الرجل‏:‏ ألي هذا يا رسول الله‏؟‏ قال ‏","matn":"\"‏ لجميع أمتى كلهم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1652","bookId":"riyad","type":"hadith","num":1652,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه ، قال‏:‏ جاء رجل إلى النبي، صلى الله عليه وسلم فقال‏:‏ يا رسول الله أصبت حداً، فأقمه علي، وحضرت الصلاة، فصلى مع رسول الله، صلى الله عليه وسلم، فلما قضى الصلاة قال ‏:‏ يارسول الله إنى أصبت حداً، فأقم في كتاب الله‏.‏ قال “هل حضرت معنا الصلاة‏؟‏‏","matn":"\"‏ قال‏:‏ نعم ‏.‏ قال‏:‏ قد غفر لك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ('‏وقوله ‏ ‏اصبت حداً‏ ‏ معناه ‏:‏ معصية توجب التعزير، وليس المراد الحد الشرعي الحقيقى كحد الزنا والخمر وغيرهما، فإن هذه الحدود لا تسقط بالصلاة، ولا يجوز للإمام تركها')"},{"id":"riyad:1653","bookId":"riyad","type":"hadith","num":1653,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “إن الله ليرضى عن العبد أن يأكل الأكلة، فيحمده عليها، أو يشرب الشربة، فيحمده عليها‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏‏(‏‏(‏‏الأكلة” بفتح الهمزة وهي المرة الواحدة من الأكل كالغدوة والعشوة، والله أعلم‏)‏‏)‏‏.‏"},{"id":"riyad:1654","bookId":"riyad","type":"hadith","num":1654,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى، رضي الله عنه، عن النبي صلى الله عليه وسلم قال ‏","matn":"\"‏إن الله تعالى يبسط يده بالليل ليتوب مسئ النهار، ويبسط يده بالنهار ليتوب مسئ الليل حتى تطلع الشمس من مغربها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1655","bookId":"riyad","type":"hadith","num":1655,"kitab":"كتاب المقدمات","isnad":"وعن أبي نجيح عمرو بن عبسة -بفتح العين والباء- السلمي، رضي الله عنه ، قال‏:‏ كنت وأنا في الجاهلية أظن أن الناس على ضلالة، وأنهم ليسوا على شئ، وهم يعبدون الأوثان، فسمعت برجل بمكة يخبر أخباراً، فقعدت على راحلتى، فقدمت عليه، فإذا رسول الله ، صلى الله عليه وسلم مستخفياً، جرءاء عليه قومه ، فتلطف حتى دخلت عليه بمكة، فقلت له ‏:‏ ما أنت‏؟‏ قال‏:‏ ‏","matn":"\"‏أنا نبي‏\"‏ قلت‏:‏ وما نبي ‏؟‏ قال‏:‏ ‏\"‏أرسلني الله‏\"‏ قلت‏:‏ وبأي شئ أرسك‏؟‏ قال ‏\"‏أرسلني بصلة الأرحام، وكسر الأوثان وأن يوحد الله لا يشرك به شئ‏:‏ قلت‏:‏ فمن معك على هذا‏؟‏ قال‏:‏ ‏\"‏حر وعبد‏\"‏ ومعه يومئذ أبو بكر وبلال، رضي الله عنهما، قلت‏:‏ إني متبعك، قال‏:‏ ‏\"‏إنك لن تستطيع ذلك يومك هذا، ألا ترى حالي وحال الناس‏؟‏ ولكن ارجع إلى أهلك فإذا سمعت بي قد ظهرت فأتني‏\"‏ قال‏:‏ فذهبت إلى أهلي وقدم رسول الله صلى الله عليه وسلم، المدينة، وكنت في أهلي، فجعلت أتخبر الأخبار، واسأل الناس حين قدم المدينة حتى قدم نفر من أهلي المدينة، فقلت‏:‏ ما فعل هذا الرجل الذي قدم المدينة‏؟‏ فقالوا‏:‏ الناس إليه سراع، وقد أراد قومه قتله، فلم يستطيعوا ذلك، فقدمت المدينة، فدخلت عليه، فقلت‏:‏ يا رسول الله أتعرفني‏؟‏ قال‏:‏ ‏\"‏نعم أنتالذي لقيتني بمكة‏\"‏ قال‏:‏ فقلت يا رسول الله أخبرني عما علمك الله وأجهله، أخبرنى عن الصلاة‏؟‏ قال ‏:‏” صل صلاة الصبح، ثم أقصر عن الصلاة حتى ترتفع الشمس قيد رمح، فإنه تطلع حين تطلع بين قرني شيطان، وحينئذ يسجد لها الكفار، ثم صل فإن الصلاة مشهودة محضورة حتى يستقل الظل بالرمح، ثم أقصر عن الصلاة، فإنه حينئذ تسجر جهنم؛ فإذا أقبل الفيء فصل؛ فإن الصلاة مشهودة محضورة حتى تصلي العصر، ثم اقصر عن الصلاة حتى تغرب الشمس ، فإنها تغرب بين قرني شيطان، وحينئذ يسجد لها الكفار‏\"‏ قال‏:‏ فقلت‏:‏ يا نبى الله ؛ فالوضوء حدثنى عنه‏؟‏ فقال‏:‏ ‏\"‏ما منكم رجل يقرب وضوءه، فيتمضمض ويستنشق فينتثر، إلا خرت خطايا وجهه وفيه وخياشيمه، ثم إذا غسل وجهه كما أمره الله ، إلا خرت خطايا وجهه من أطراف لحيته مع الماء، ثم يغسل يديه إلى المرفقين، إلا خرت خطايا يديه من أنامله مع الماء ثم يمسح رأسه، إلا خرت خطايا يديه من أنامله مع الماء، ثم يغسل يديه إلى المرفقين ، إلاخرت خطايا يديه من أنامله مع الماء، ثم يمسح رأسه، إلا خرت خطايا رأسه من أطراف شعره مع الماء، ثم يغسل قديمه إلى الكعبين إلا خرت خطايا رجليه من أنامله مع الماء، فإن هو قام فصلى، فحمد الله تعالى، وأثنى عليه ومجده بالذي هو له أهل ، وفرغ قلبه لله تعالى، إلا انصرف من خطيئته كهيئته يوم ولدته أمه‏\"‏‏.‏ فحدث عمرو بن عبسة بهذا الحديث أبا أمامة صاحب رسول الله، فقال له أبو أمامة‏:‏ يا عمرو بن عبسة، انظر ما تقول‏!‏ في مقام واحد يعطى هذا الرجل‏؟‏ فقال عمرو‏:‏ يا أبا أمامة لقد كبرت سني، ورق عظمي ، واقترب أجلي، وما بي حاجة أن أكذب على الله تعالى، ولا على رسول الله، صلى الله عليه وسلم، لو لم اسمعه من رسول الله، صلى الله عليه وسلم إلا مرة أو مرتين أو ثلاثاً، حتى عد سبع مرات، ماحدثت أبداً به، ولكني سمعته أكثر من ذلك ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1656","bookId":"riyad","type":"hadith","num":1656,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى الأشعري، رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إذا أراد الله تعالى، رحمة أمةٍ ، قبض نبيها قبلها، فجعله لها فرطاً وسلفاً بين يديها، وإذا أراد هلكة أمةٍ، عذبها ونبيها حي، فأهلكها وهو حى ينظر، فأقر عينه بهلاكها حين كذبوه وعصوا امره‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1657","bookId":"riyad","type":"hadith","num":1657,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه ، عن رسول الله صلى الله عليه وسلم أنه قال‏:‏ “ قال الله، عز وجل‏:‏ أنا عند ظن عبدي بي وأنا معه حيث يذكرني، والله لله أفرح بتوبة عبده من أحدكم يجد ضالته بالفلاة، ومن تقرب إلي شبراً، تقربت إليه ذراعاً، ومن تقرب إلي ذراعاً، تقربت إليه باعاً، وإذا أقبل إلي يمشي، أقبلت إليه أهرول‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وهذا لفظ إحدى روايات مسلم‏.‏ وتقدم شرحه في الباب قبله‏.‏ وروي في الصحيحين ‏:‏ ‏\"‏وأنا معه حين يذكرني‏\"‏ بالنون، وفي هذه الرواية ‏\"‏حيث” بالثاء وكلاهما صحيح‏.‏"},{"id":"riyad:1658","bookId":"riyad","type":"hadith","num":1658,"kitab":"كتاب المقدمات","isnad":"وعن جابر بن عبد الله، رضي الله عنهما ، أنه سمع النبي، صلى الله عليه وسلم، قبل موته بثلاثة أيام يقول ‏:‏ لا يموتن أحدكم إلا وهو يحسن الظن بالله عز وجل‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1659","bookId":"riyad","type":"hadith","num":1659,"kitab":"كتاب المقدمات","isnad":"وعن أنس ، رضي الله عنه قال‏:‏” سمعت رسول الله ، صلى الله عليه وسلم يقول‏:‏ “قال الله تعالى‏:‏ يا ابن آدم، إنك ما دعوتني ورجوتني غفرت لك على ما كان منك ولا أبالي، يا أبن آدم، لو بلغت ذنوبك عنان السماء، ثم استغفرتني غفرت لك ، يا ابن آدم، إنك لو أتيتنى بقراب الأرض خطايا، ثم لقيتني لا تشرك به شيئاً، لأتيتك بقرابها مغفرة‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي‏.‏ وقال حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1660","bookId":"riyad","type":"hadith","num":1660,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال‏","matn":"\"‏ لو يعلم المؤمن ما عند الله من العقوبة، ما طمع بجنته أحد، ولو يعلم الكافر ما عند الله من الرحمة، ما قنط من جنته أحد” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1661","bookId":"riyad","type":"hadith","num":1661,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدري، رضي الله عنه ، أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏إذا وضعت الجنازة واحتملها الناس أو الرجال على أعناقهم، فإن كانت صالحة قالت‏:‏ فدموني قدموني، وإن كانت غير صالحة، قالت يا ويلها‏!‏ أين تذهبون بها‏؟‏ يسمع صوته كل شئ إلا الإنسان، ولو سمعه صعق‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1662","bookId":"riyad","type":"hadith","num":1662,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود، رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم، “الجنة أقرب إلى أحدكم من شراك نعله، والنار مثل ذلك‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1663","bookId":"riyad","type":"hadith","num":1663,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود، رضي الله عنه ، قال‏:‏ قال لي النبي، صلى الله عليه وسلم، “اقرأ علي القرآن” قلت‏:‏ يا رسول الله أقرأ عليك وعليك أنزل ‏؟‏‏!‏ قال‏:‏‏","matn":"\"‏إنى أحب أن أسمعه من غيري” فقرأت عليه سورة النساء، حتى جئت إلى هذه الآية ‏(‏فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيداً‏}‏ ‏(‏‏(‏النساء‏:‏41‏)‏‏)‏ قال‏:‏ ‏\"‏حسبك الآن‏\"‏ فالتفت إليه، فإذا عيناه تذرفان ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1664","bookId":"riyad","type":"hadith","num":1664,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه ، قال‏:‏ خطب رسول الله، صلى الله عليه وسلم، خطبة ما سمعت مثلها قط، فقال‏:‏ ‏","matn":"\"‏لو تعلمون ما أعلم لضحكتم قليلاً ولبكيتم كثيراً‏\"‏ قال ‏:‏ فغطي أصحاب رسول الله صلى الله عليه وسلم وجوههم، ولهم خنين ، ‏(‏‏(‏متفق عليه‏)‏‏)‏ ، وسبق بيان في باب الخوف‏.‏"},{"id":"riyad:1665","bookId":"riyad","type":"hadith","num":1665,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"لا يلج النار رجل بكى من خشية الله حتى يعود اللبن في الضرع، ولا يجتمع غبار في سبيل الله ودخان جهنم” ‏(‏‏(‏رواه الترمذي‏:‏ وقال حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1666","bookId":"riyad","type":"hadith","num":1666,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله ، صلى الله عليه وسلم‏:‏‏","matn":"\"‏سبعة يظلهم الله في ظله يوم لا ظل إلا ظله‏:‏ إمام عادل، وشاب نشأ في عبادة الله ، ورجل قلبه معلق في المساجد، ورجلان تحابا في الله، اجتمعا عليه، وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال، فقال‏:‏ إنى أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خالياً ففاضت عيناه” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1667","bookId":"riyad","type":"hadith","num":1667,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عبد الله بن الشخير، رضي الله عنه ، قال‏:‏ أتيت رسول الله صلى الله عليه وسلم، وهو يصلي ولجوفه أزيز كأزير المرجل من البكاء‏.‏ ‏(‏‏(‏حديث صحيح رواه أبو داود، والترمذي بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1668","bookId":"riyad","type":"hadith","num":1668,"kitab":"كتاب المقدمات","isnad":"وعن أنس، رضي الله عنه ، قال‏:‏ قال رسول الله، صلى الله عليه وسلم، لأبي بن كعب، رضي الله عنه ‏:‏‏","matn":"\"‏إن الله عز وجل أمرني أن أقرأ عليك‏:‏ لم يكن الذين كفرو‏\"‏ قال‏:‏ وسماني‏؟‏ قال‏:‏ “نعم” فبكى أبي‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ ‏(‏‏(‏وفي رواية‏:‏ فجعل أبي يبكى‏)‏‏)‏‏.‏"},{"id":"riyad:1669","bookId":"riyad","type":"hadith","num":1669,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه قال‏:‏ قال أبو بكر لعمر، رضي الله عنهما، بعد وفاة رسول الله، صلى الله عليه وسلم‏:‏ انطلق بنا إلى أم أيمن ، رضي الله عنها، نزورها كما كان يزورها ، فلما انتهينا إليها بكت، فقالا‏:‏ ما يبكيك‏؟‏ أما تعلمين أن ما عند الله تعالى خير لرسول الله، صلى الله عليه وسلم قالت‏:‏ إنى لا أبكي ، أني لا أعلم أن ما عند الله خير لرسول الله صلى الله عليه وسلم ، ولكنى أبكي أن الوحي قد انقطع من السماء، فهيجتهما على البكاء، فجعلا يبكيان معها‏.‏ ‏(‏‏(‏رواه مسلم وقد سبق في باب زيارة أهل الخير‏)‏‏)‏‏.‏"},{"id":"riyad:1670","bookId":"riyad","type":"hadith","num":1670,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر، رضي الله عنهما، قال‏:‏ لما اشتد برسول الله صلى الله عليه وسلم، وجعه، قيل له في الصلاة، فقال‏:‏ مروا أبا بكر فليصل بالناس‏","matn":"\"‏ فقالت عائشة، رضي الله عنها ‏:‏ إن أبا بكر رجل رقيق، إذا قرأ القرآن غلبه البكاء، فقال ‏:‏ ‏\"‏مروه فليصل‏\"‏‏.‏ وفي رواية عن عائشة، رضي الله عنها، قالت‏:‏ قلت‏:‏ إن أبا بكر إذا قام مقامك لم يسمع الناس من البكاء‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1671","bookId":"riyad","type":"hadith","num":1671,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن إبراهيم بن عبد الرحمن بن عوف أن عبد الرحمن بن عوف، رضي الله عنه ، أتي بطعام وكان صائما، فقال‏:‏ قتل مصعب بن عمير رضي الله عنه، وهو خير مني، فلم يوجد له ما يكفن به إلا بردة إن غطى بها رأسه بدت رجلاه، وإن غطى بها رجلاه بدا رأسه، ثم بسط لنا من الدنيا ما بسط -أو قال‏:‏ أعطينا من الدنيا ما أعطينا -قد خشينا أن تكون حسناتنا عجلت لنا‏.‏ ثم جعل يبكي حتى ترك الطعام‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1672","bookId":"riyad","type":"hadith","num":1672,"kitab":"كتاب المقدمات","isnad":"وعن أبي أمامة صدي بن عجلان الباهلي، رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس شئ أحب إلى الله تعالى من قطرتين وأثرين‏:‏ قطرة دموع من خشية الله، وقطرة دم تهراق في سبيل الله، وأما الأثران‏:‏ فأثر في سبيل الله تعالى، وأثر في فريضة من فرائض الله تعالى‏\"‏ ‏(‏‏(‏رواه الترمذي‏.‏وقال حديث حسن‏)‏‏)‏‏.‏ حديث العرباض بن سارية، رضي الله عنه ، قال‏:‏ وعظنا رسول الله صلى الله عليه وسلم، موعظة وجلت منها القلوب، وذرفت منها العيون‏"},{"id":"riyad:1673","bookId":"riyad","type":"hadith","num":1673,"kitab":"كتاب المقدمات","isnad":"","matn":"عن عمرو بن عوف الأنصاري، رضي الله عنه، أن رسول الله صلى الله عليه وسلم، بعث أبا عبيدة بن الجراح، رضي الله عنه ، إلى البحرين يأتي بجزيتها، فقدم بمال من البحرين ، فسمعت الأنصار بقدوم أبو عبيدة، فوافوا صلاة الفجر مع رسول الله ، صلى الله عليه وسلم فلما صلى رسول الله صلى الله عليه وسلم، انصرف فتعرضوا له ، فتبسم رسول الله، صلى الله عليه وسلم حين رآهم، ثم قال‏:‏ “أظنكم سمعتم أن أبا عبيدة قدم بشئ من البحرين‏؟‏” فقالوا‏:‏ أجل يا رسول الله فقال‏:‏ “أبشروا وأملوا ما يسركم ، فوالله ما الفقر أخشى عليكم، ولكني أخشى أن تبسط الدنيا عليكم كما بسطت على من كان قبلكم، فتنافسوها كما تنافسوها ، فتهلككم كما أهلكتهم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1674","bookId":"riyad","type":"hadith","num":1674,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدري، رضي الله عنه ، قال ‏:‏ جلس رسول الله صلى الله عليه وسلم، على المنبر، وجلسنا حوله، فقال‏:‏ ‏","matn":"\"‏إن مما أخاف عليكم من بعدي ما يفتح عليكم من زهرة الدنيا وزينتها” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1675","bookId":"riyad","type":"hadith","num":1675,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله، صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏إن الدنيا حلوة خضرة وإن الله تعالى مستخلفكم فيها، فينظر كيف تعملون، فاتقوا الدنيا واتقوا النساء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1676","bookId":"riyad","type":"hadith","num":1676,"kitab":"كتاب المقدمات","isnad":"وعن أنس ، رضي الله عنه، أن النبي، صلى الله عليه وسلم، قال‏:‏”اللهم لا عيش إلا عيش الآخرة‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1677","bookId":"riyad","type":"hadith","num":1677,"kitab":"كتاب المقدمات","isnad":"وعنه عن رسول الله ، صلى الله عليه وسلم قال‏:‏ “يتبع الميت ثلاثة‏:‏ أهله وماله وعمله‏:‏ فيرجع اثنان ويبقى واحد‏:‏ يرجع أهله وماله ويبقى عمله‏","matn":"\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏‏‏.‏"},{"id":"riyad:1678","bookId":"riyad","type":"hadith","num":1678,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏:‏ “يؤتى بأنعم أهل الدنيا من أهل النار يوم القيامة، فيصبغ في النار صبغة، ثم يقال‏:‏ يا ابن آدم هل رأيت خيراً قط‏؟‏ هل مر بك نعيم قط‏؟‏ فيقول‏:‏ لا والله يا رب‏.‏ ويؤتى بأشد الناس بؤساً في الدنياً من أهل الجنة، فيصبغ صبغة في الجنة، فيقال له‏:‏ يا ابن آدم هل رأيت بؤساً قط‏؟‏ هل مربك شدة قط‏؟‏ فيقول‏:‏ لا، والله، ما مر بى بؤس قط، ولا رأيت شدة قط‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1679","bookId":"riyad","type":"hadith","num":1679,"kitab":"كتاب المقدمات","isnad":"وعن المستورد بن شداد رضي الله عنه ، قال‏:‏ قال رسول الله، صلى الله عليه وسلم‏:‏”ما الدنيا في الآخرة، إلا مثل ما يجعل أحدكم أصبعه في اليم، فلينظر بم يرجع‏؟‏‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1680","bookId":"riyad","type":"hadith","num":1680,"kitab":"كتاب المقدمات","isnad":"وعن جابر، رضي الله عنه أن رسول الله، صلى الله عليه وسلم، مر بالسوق والناس كنفتيه، فمر بجدى أسك ميت، فتناوله، فأخذ بأذنيه، ثم قال‏:‏ ‏","matn":"\"‏أيكم يحب أن يكون هذا له بدرهم‏؟‏ ‏\"‏ فقالوا‏:‏ ما نحب أنه لنا بشئ ومانصنع به‏؟‏ ثم قال‏:‏ “أتحبون أنه لكم‏؟‏ قالوا‏:‏ والله لو كان حياً كان عيباً؛ أنه أسك‏.‏ فكيف وهو ميت _‏!‏ فقال‏:‏ ‏\"‏فوالله للدنيا أهون على الله من هذا عليكم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ('‏قوله‏:‏ ‏ ‏كنفتيه‏ ‏ أي‏:‏ على جانبيه‏.‏ و‏ ‏ الأسك‏ ‏ الصغير الأذن‏.‏')"},{"id":"riyad:1681","bookId":"riyad","type":"hadith","num":1681,"kitab":"كتاب المقدمات","isnad":"وعن أبي ذر رضي الله عنه ، قال كنت أمشى مع النبي صلى الله عليه وسلم في حرة بالمدينة ، فاستقبلنا أحد فقال‏:‏ ‏","matn":"\"‏يا أبا ذر‏\"‏ قلت‏:‏ لبيك يا رسول الله‏.‏ فقال‏:‏ ‏\"‏ما يسرني أن عندي مثل أحد هذا ذهبا تمضى علي ثلاثة أيام وعندي منه دينار، إلا شئ أرصده لدين، إلا أن أقول له به في عباد الله هكذا، وهكذا وهكذا‏\"‏ عن يمينه وعن شماله ومن خلفه، ثم سار فقال‏:‏ ‏\"‏إن الأكثرين هم الأقلون يوم القيامة إلا من قال بالمال هكذا وهكذا وهكذا‏\"‏ عن يمينه وعن شماله ومن خلفه‏\"‏ وقليل ما هم‏\"‏ ثم قال لى ‏\"‏مكانك لا تبرح حتى آتيك‏\"‏ ثم انطلق في سواد الليل حتى توارى، فسمعت صوتا قد ارتفع ، فتخوفت أن يكون أحد عرض للنبى، صلى الله عليه وسلم، فأردت أن آتيه فذكرت قوله‏:‏ ‏\"‏لا تبرح حتى آتيك‏\"‏ فلم أبرح حتى أتانى، فقلت ‏:‏ لقد سمعت صوتاً تخوفت منه، فذكرت له، فقال‏:‏ ‏\"‏وهل سمعته‏؟‏‏\"‏ قلت‏:‏ نعم، قال‏:‏ ‏\"‏ذاك جبريل أتانى فقال‏:‏ من مات من أمتك لا يشرك بالله شيئاً دخل الجنة، قلت‏:‏ وإن زنى وإن سرق‏؟‏ قال‏:‏ وإن زنى وإن سرق‏\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1682","bookId":"riyad","type":"hadith","num":1682,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه، عن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لو كان لي مثل أحد ذهباً، لسرنى أن لا تمر على ثلاث ليال وعندي منه شئ إلا شئ أرصده لدين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1683","bookId":"riyad","type":"hadith","num":1683,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم انظروا إلى من هو أسفل منكم ولا تنظروا إلى من هو فوقكم فهو أجدر أن لا تزدروا نعمة الله عليكم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه وهذا لفظ مسلم‏)‏‏)‏‏.‏ وفي رواية البخاري‏:‏ ‏\"‏إذا نظر أحدكم إلى من فضل عليه في المال والخلق، فلينظر إلى من هو أسفل منه‏\"‏‏.‏ وفي رواية البخاري‏:‏ ‏\"‏إذا نظر أحدكم إلى من فضل عليه في المال والخلق، فلينظر إلى من هو أسفل منه‏\"‏‏.‏"},{"id":"riyad:1684","bookId":"riyad","type":"hadith","num":1684,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم، قال‏:‏ “تعس عبد الدينار والدرهم والقطيفة والخميصة؛ إن أعطى رضي؛ وإن لم يعط لم يرض‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1685","bookId":"riyad","type":"hadith","num":1685,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه، رضي الله عنه، قال‏:‏ لقد رأيت سبعين من أهل الصفة، ما منهم رجل عليه رداء، إما إزار وأما كساء، قد ربطوا في أعناقهم، فمنها ما يبلغ نصف الساقين، ومنها ما يبلغ الكعبين، فيجمعه بيده كراهية أن ترى عورته” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1686","bookId":"riyad","type":"hadith","num":1686,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏الدنيا سجن المؤمن وجنة الكافر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1687","bookId":"riyad","type":"hadith","num":1687,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر، رضي الله عنهما، قال‏:‏ أخذ رسول الله صلى الله عليه وسلم بمنكبي، فقال‏:‏ ‏","matn":"\"‏كن في الدنيا كأنك غريب، أو عابر سبيل‏\"‏‏.‏ وكان ابن عمر، رضي الله عنهما، يقول‏:‏ إذا أمسيت، فلا تنتظر الصباح، وإذا أصبحت لا تنتظر المساء، وخذ من صحتك لمرضك ومن حياتك لموتك‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1688","bookId":"riyad","type":"hadith","num":1688,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي العباس سهل بن سعد الساعدى، رضي الله عنه، قال‏:‏ جاء رجل إلى النبي صلى الله عليه وسلم فقال‏:‏ يا رسول الله دلني على عمل إذا عملته أحبني الله، واحبني الناس، فقال‏:‏ “ازهد في الدنيا يحبك الله، وازهد فيما عند الناس يحبك الناس” ‏(‏‏(‏حديث حسن رواه ابن ماجه وغيره بأسانيد حسنة‏)‏‏)‏‏.‏"},{"id":"riyad:1689","bookId":"riyad","type":"hadith","num":1689,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن النعمان بن بشير، رضي الله عنهما، قال‏:‏ ذكر عمر ابن الخطاب، رضي الله عنه، ما أصاب الناس من الدنيا، فقال‏:‏ لقد رأيت رسول الله، صلى الله عليه وسلم، يظل اليوم يتلوى ما يجد من الدقل ما يملأ به بطنه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏الدقل‏ ‏ بفتح الدال المهملة والقاف‏:‏ ردئ التمر‏.‏"},{"id":"riyad:1690","bookId":"riyad","type":"hadith","num":1690,"kitab":"كتاب المقدمات","isnad":"وعن عائشة، رضي الله عنها، قالت‏:‏ توفي رسول الله صلى الله عليه وسلم وما في بيتي من شئ يأكله ذو كبد إلا شطر شعير في رف لي، فاكلت منه حتى طال علي، فكلته ففنى، ‏(‏‏(‏متفق عليه‏)‏‏)‏‏ ‏شطر شعير","matn":"\" شئ من شعير، كذا فسره الترمذي‏.‏"},{"id":"riyad:1691","bookId":"riyad","type":"hadith","num":1691,"kitab":"كتاب المقدمات","isnad":"وعن عمرو بن الحارث أخي الجويرية بنت الحارث أم المؤمنين، رضي الله عنهما، قال‏:‏ ما ترك رسول الله، صلى الله عليه وسلم، عند موته ديناراً ولا درهماً، ولا عبداً، ولا امة، ولا شيئا إلا بغلته البيضاء التى كان يركبها، وسلاحه، وأرضا جعلها لابن السبيل صدقة‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1692","bookId":"riyad","type":"hadith","num":1692,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن خباب بن الأرت، رضي الله عنه، قال‏:‏ هاجرنا مع رسول الله صلى الله عليه وسلم نلتمس وجه الله تعالى؛ فوقع أجرنا على الله، فمنا من مات ولم يأكل من أجره شيئا، منهم مصعب بن عمير، رضي الله عنه، قتل يوم أحد، وترك نمرة، فكنا إذا غطينا بها رأسه، بدت رجلاه، وإذا غطينا به رجليه، بدا رأسه، فأمرنا رسول الله صلى الله عليه وسلم أن نغطى رأسه، ونجعل على رجليه شيئاً من الإذخر، ومنا من أينعت له ثمرته، فهو يهديها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ النمرة‏ ‏ ‏:‏ كساء ملون من صوف‏.‏ وقوله‏:‏ ‏ ‏أينعت‏ ‏ أي‏:‏ نضجت وأدركت‏.‏ وقوله ‏ ‏يهديها‏ ‏ وهو بفتح الياء وضم الدال وكسرها، لغتان؛ أي‏:‏ يقطفها ويجتنيها، وهذه استعارة لما فتح الله تعالى عليهم من الدنيا وتمكنوا فيها‏.‏"},{"id":"riyad:1693","bookId":"riyad","type":"hadith","num":1693,"kitab":"كتاب المقدمات","isnad":"وعن سهل بن سعد الساعدى، رضي الله عنه، قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ لو كانت الدنيا تعدل عند الله جناح بعوضة ما سقى كافرا منها شربة ماء‏\"‏‏(‏‏(‏رواه الترمذي ‏.‏ وقال حديث حسن صحيح‏)‏‏)‏"},{"id":"riyad:1694","bookId":"riyad","type":"hadith","num":1694,"kitab":"كتاب المقدمات","isnad":"وعن أبي هُرَيْرَة رضي اللَّه عنه ، قال ‏:‏ سمعتُ رسولَ اللَّه صَلّى اللهُ عَلَيْهِ وسَلَّم يقول ألا إن الدنيا ملعونة، ملعون ما فيها، إلا ذكر الله تعالى، وما والاه، وعالماً ومتعلماً‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1695","bookId":"riyad","type":"hadith","num":1695,"kitab":"كتاب المقدمات","isnad":"وعن عَبْدِ اللَّه بنِ مسعودٍ ، رضي اللَّه عنه ، قال ‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"\"‏ لا تتخذوا الضيعة فترغبوا في الدنيا‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديثٌ حسنٌ ‏)‏‏)‏‏.‏"},{"id":"riyad:1696","bookId":"riyad","type":"hadith","num":1696,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال‏:‏ مر علينا رسول الله، صلى الله عليه وسلم ، ونحن نعالج خصاً لنا فقال‏:‏ ‏","matn":"\"‏ ما هذا‏؟‏‏\"‏ فقلنا‏:‏ قد وهي، فنحن نصلحه، فقال‏:‏ ‏\"‏ ما أرى الأمر إلا أعجل من ذلك‏\"‏‏.‏ رواه أبو داود، والترمذي بإسناد البخاري ومسلم، وقال الترمذي‏:‏ ‏(‏‏(‏حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1697","bookId":"riyad","type":"hadith","num":1697,"kitab":"كتاب المقدمات","isnad":"وعن كعب بن عياض، رضي الله عنه، وقال سمعت رسول الله، صلى الله عليه وسلم ، يقول‏:‏ ‏","matn":"\"‏ إن لكل أمة فتنة، وفتنة أمتى المال‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1698","bookId":"riyad","type":"hadith","num":1698,"kitab":"كتاب المقدمات","isnad":"وعن أبي عمرو، ويقال‏:‏ أبو عبد الله‏:‏ ويقال‏:‏ أبو ليلى، عثمان ابن عفان، رضي الله عنه أن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏ ليس لابن آدم حق في سوى هذه الخصال‏:‏ بيت يسكنه، وثوب يواري عورته، وجلف الخبز، والماء‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث صحيح‏)‏‏)‏ ‏.‏ ‏(‏‏(‏قال الترمذي‏:‏ سمعت أبا داود سليمان بن سالم البلخى يقول‏:‏ سمعت النضر بن شميل يقول‏:‏ الجلف‏:‏ الخبز ليس معه إدام‏.‏ قال غيره‏:‏ هو غليظ الخبز‏.‏ وقال الهروي‏:‏ المراد به هنا وعاء الخبز؛ كالجوالق والخرج، والله أعلم‏)‏‏)‏‏.‏"},{"id":"riyad:1699","bookId":"riyad","type":"hadith","num":1699,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن الشخير ‏","matn":"\"‏ بسكر الشين والخاء المشددة المعجمتين‏\"‏ رضي الله عنه، أنه قال‏:‏ أتيت النبي ، صلى الله عليه وسلم، وهو يقرأ‏:‏ ‏{‏ ألهاكم التكاثر‏}‏ قال‏:‏ ‏\"‏ يقول ابن آدم‏:‏ مالي، وهل لك يا ابن آدم من مالك إلا ما أكلت فأفنيت، أو لبست فأبليت، أو تصدقت فأمضيت‏؟‏ ‏!‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1700","bookId":"riyad","type":"hadith","num":1700,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مغفل، رضي الله عنه، قال‏:‏ قال رجل للنبي صلى الله عليه وسلم يارسول الله، والله إنى لأحبك، فقال‏:‏ ‏","matn":"\"‏ انظر ماذ تقول‏؟‏‏\"‏ قال‏:‏ والله إنى لأحبك، ثلاث مرات، فقال‏:‏ ‏\"‏ إن كنت تحبنى فأعد للفقر تجفافاً، فإن الفقر أسرع إلى من يحبنى من السيل إلى منتهاه‏\"‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏ '‏‏التجفاف‏ ‏ بكسر التاء المثناه فوق وإسكان الجيم وبالفاء المكررة، وهو شىء يلبسة الفرس، ليتقي به الأذى، وقد يلبسة الإنسان‏.‏‏'"},{"id":"riyad:1701","bookId":"riyad","type":"hadith","num":1701,"kitab":"كتاب المقدمات","isnad":"وعن كعب بن مالك، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ ما ذئبان جائعان أرسلا في غنم بأفسد لها من حرص المرء على المال والشرف، لدينه‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1702","bookId":"riyad","type":"hadith","num":1702,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مسعود، رضي الله عنه، قال‏:‏ نام رسول الله صلى الله عليه وسلم، على حصير، فقال وقد أثر في جنبه‏.‏ قلنا‏:‏ يا رسول الله لو اتخذنا لك وطاء‏!‏ فقال‏:‏ ‏","matn":"\"‏ مالي وللدنيا‏؟‏ ما أنا في الدنيا إلا كراكب استظل تحت شجرة ثم راح وتركها”‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1703","bookId":"riyad","type":"hadith","num":1703,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ يدخل الفقراء الجنة قبل الأغنياء بخمسمائة عام‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ جديث صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1704","bookId":"riyad","type":"hadith","num":1704,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس، وعمران بن الحصين، رضي الله عنهم، عن النبي ، صلى الله عليه وسلم ‏","matn":"\"‏ قال ‏\"‏ اطلعت في الجنة فرأيت أكثر أهلها الفقراء، واطلعت في النار فرأيت أكثر أهلها النساء‏\"‏ ‏(‏‏(‏متفق عليه من رواية ابن عباس‏)‏‏)‏‏.‏ ‏(‏‏(‏ورواه البخاري أيضاً من رواية عمران بن الحصين‏)‏‏)‏‏.‏"},{"id":"riyad:1705","bookId":"riyad","type":"hadith","num":1705,"kitab":"كتاب المقدمات","isnad":"وعن أسامة بن زيد، رضي الله عنهما، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏قمت على باب الجنة، فكان عامة من دخلها المساكين‏.‏ وأصحاب الجد محبوسون، غير أن أصحاب النار قد أمر بهم إلى النار‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏و‏(‏‏(‏‏ ‏الجد‏:الحظ والغنى‏.‏ وقد سبق بيان هذا الحديث في باب فضل الضعفة‏)‏‏)‏‏.‏"},{"id":"riyad:1706","bookId":"riyad","type":"hadith","num":1706,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه، عن النبي صلى الله عليه وسلم، قال‏:‏ ‏","matn":"\"‏أصدق كلمة قالها شاعر كلمة لبيد‏:‏ ألا كل شئ ما خلا الله باطل‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1707","bookId":"riyad","type":"hadith","num":1707,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة، رضي الله عنها ، قالت‏:‏ ما شبع آل محمد، صلى الله عليه وسلم ، من خبز شعير يومين متتابعين حتى قبض‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ ما شبع آل محمد، صلى الله عليه وسلم ، منذ قدم المدينة من طعام البر ثلاث ليال تباعاً حتى قبض‏.‏"},{"id":"riyad:1708","bookId":"riyad","type":"hadith","num":1708,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عروة عن عائشة، رضي الله عنها، أنها كانت تقول‏:‏ والله يا ابن اختي إن كنا لننظر إلى الهلال، ثم الهلال‏:‏ ثلاثة أهلة في شهرين، وما أوقد في أبيات رسول صلى الله عليه وسلم ، نار‏.‏ قلت‏:‏ يا خالة فما كان يعيشكم‏؟‏ قالت‏:‏ الأسودان‏:‏ التمر والماء، إلا أنه قد كان لرسول الله صلى الله عليه وسلم جيران من الأنصار، وكانت لهم منائح وكانوا يرسلون إلى رسول الله من ألبانها فيسقينا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1709","bookId":"riyad","type":"hadith","num":1709,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي سعيد المقبري عن أبي هريرة رضي الله عنه، أنه مر بقوم بين أيديهم شاة مصلية، فدعوه فأبي أن يأكل، وقال‏:‏ خرج رسول الله صلى الله عليه وسلم من الدنيا ولم يشبع من خبز الشعير‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ '‏مصلية‏'‏ بفتح الميم‏:‏ أي‏:‏ مشوية‏.‏"},{"id":"riyad:1710","bookId":"riyad","type":"hadith","num":1710,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه، قال‏:‏ لم يأكل النبي صلى الله عليه وسلم على خوان حتى مات، وما أكل خبزاً مرققاً حتى مات‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ ‏(‏‏(‏ وفي روايه له‏:‏ ولا رأى شاة سميطاً بعينه قط‏)‏‏)‏‏.‏"},{"id":"riyad:1711","bookId":"riyad","type":"hadith","num":1711,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن النعمان بن بشير رضي الله عنهما قال‏:‏ لقد رأيت نبيكم صلى الله عليه وسلم ، وما يجد من الدقل ما يملأ به بطنه، ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏(‏‏(‏الدقل‏:‏ تمر رديء‏)‏‏)‏‏.‏"},{"id":"riyad:1712","bookId":"riyad","type":"hadith","num":1712,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سهل بن سعد رضي الله عنه، قال‏:‏ ما رأى رسول الله صلى الله عليه وسلم النقي من حين ابتعثة الله تعالى حتى قبضه الله تعالى، فقيل له‏:‏ هل كان لكم في عهد رسول الله صلى الله عليه وسلم مناخل‏؟‏ قال‏:‏ ما رأى رسول الله صلى الله عليه وسلم منخلا من حين ابتعثه الله تعالى حتى قبضه الله تعالى، فقيل له‏:‏ كيف كنتم تأكلون الشعير غير منخول‏؟‏ قال‏:‏ كنا نطحنه وننفخه، فيطير ما طار، وما بقى ثريناه ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ (('‏قوله‏:‏ ‏ ‏ النقي‏ ‏ ‏:‏ هو بفتح النون وكسر القاف وتشديد الياء، وهو الخبز الحواري، وهو‏:‏ الدرمك‏.‏ قوله‏:‏ ‏ ‏ ثريناه‏ ‏ هو بثاء مثلثة، ثم راء مشدده، ثم ياء مثناة من تحت ثم نون، أي‏:‏ بللناه وعجناه‏.‏'))"},{"id":"riyad:1713","bookId":"riyad","type":"hadith","num":1713,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ خرج رسول الله صلى الله عليه وسلم ذات يوم أو ليلة، فإذا هو بأبي بكر وعمر رضي الله عنهما، فقال‏:‏ ‏","matn":"\"‏ ما أخرجكما من بيوتكما هذه الساعة‏؟‏” قالا‏:‏ الجوع يا رسول الله‏.‏ قال‏:‏ ‏\"‏ وأنا، والذي نفسي بيده، لأخرجني الذي أخرجكما‏.‏ قوما‏\"‏ فقاما معه، فأتى رجلا من الأنصار، فإذا هو ليس في بيته، فلما رأته المرأة قالت‏:‏ مرحباً وأهلا، فقال لها رسول الله صلى الله عليه وسلم ‏\"‏أين فلان‏؟‏‏\"‏ قالت ذهب يستعذب لنا الماء، إذ جاء الأنصاري، فنظر إلى رسول الله صلى الله عليه وسلم وصاحبيه، ثم قال‏:‏ الحمد الله، ما أحد اليوم أكرم أضيافاً مني‏.‏ فانطلق فجاءهم بعذق فيه بسر وتمر ورطب، فقال‏:‏ كلوا وأخذ المدية فقال رسول الله صلى الله عليه وسلم ‏\"‏ إياك والحلوب‏\"‏ فذبح لهم فأكلوا من الشاة ومن ذلك العذق وشربوا فلما أن شبعوا ورووا قال رسول الله صلى الله عليه وسلم لأبي بكر وعمر رضي الله عنهما‏:‏ ‏\"‏ والذي نفسي بيده، لتسألن عن هذا النعيم يوم القيامة، أخرجكم من بيوتكم الجوع، ثم لم ترجعوا حتى أصابكم هذا النعيم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏‏(‏‏(‏قولها‏:‏ ‏ ‏ يستعذب‏ ‏ أي‏:‏ يطلب الماء العذب، وهو الطيب‏.‏ و ‏ ‏العذق‏ ‏ بكسر العين وإسكان الذال المعجمة‏:‏ وهو الكباسة، وهي الغضن‏.‏ و‏ ‏ المدية‏ ‏ بضم الميم وكسرها‏:‏ هي السكين‏.‏ و ‏ ‏ الحلوب‏ ‏ ذات اللبن‏.‏ والسؤال عن الأنصاري الذي أتوه هو أبو الهيثم بن التيهان رضي الله عنه، كذا جاء مبيناً في رواية الترمذي وغيره‏)‏‏)‏‏.‏"},{"id":"riyad:1714","bookId":"riyad","type":"hadith","num":1714,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن خالد بن عمر العدوي قال‏:‏ خطبنا عتبة بن غزوان، وكان أمير على البصرة، فحمد الله وأثنى عليه، ثم قال‏:‏ أما بعد؛ فإن الدنيا قد آذنت بصرم، وولت حذاء، ولم يبق منها إلا صبابة كصبابة الإناء يتصابها صاحبها، وإنكم منتقلون منها إلى دار لا زوال لها، فانتقلوا بخير ما بحضرتكم، فإنه قد ذكر لنا أن الحجر يلقى من شفير جنهم فيهوي فيها سبعين عاماً، لا يدرك لها قعراً، والله لتملأن ‏.‏‏.‏‏.‏أفعجبتم‏!‏‏؟‏ ولقد ذكر لنا أن ما بين مصراعين من مصاريع الجنة مسيرة أربعين عاماً، وليأتين عليه يوم وهو كظيظ من الزحام، ولقد رأيتني سابع سبعة مع رسول الله، صلى الله عليه وسلم ما لنا طعام إلا ورق الشجر، حتى قرحت أشداقنا، فالتقطت بردة فشققتها بيني وبين سعد بن مالك، فاتزرت بنصفها، واتزر سعد بنصفها، فما أصبح اليوم منا أحد إلا أصبح أميراً على مصر من الأمصار، وإني أعوذ بالله أن أكون في نفسي عظيماً، وعند الله صغيراً‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏قوله‏:‏ ‏ ‏ آذنت‏ ‏ هو بمد الألف، أي: أعلمت‏.‏ وقوله‏:‏ ‏ ‏ بصرم‏ ‏‏:‏ هو بضم الصاد، أي بانقطاعها وفنائها‏.‏ وقوله ‏ ‏وولت حذاء‏ ‏ هو بحاء مهملة مفتوحة، ثم ذال معجمة مشددة، ثم ألف ممدودة، أي‏:‏ سريعة‏.‏ و‏ ‏الصبابة‏ ‏ بضم الصاد المهملة‏:‏ وهي البقية اليسيرة‏.‏ وقوله‏:‏ ‏ ‏ يتصابها‏ ‏ هو بتشديد الباء قبل الهاء، أي‏:‏ يجمعها‏.‏ و‏ ‏ الكظيظ‏ ‏‏:‏ الكثير الممتليء‏.‏ وقوله‏:‏ ‏ ‏ قرحت‏ ‏ هو بفتح القاف وكسر الراء، أي‏:‏ صارت فيها قروح‏."},{"id":"riyad:1715","bookId":"riyad","type":"hadith","num":1715,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي موسى الأشعري رضي الله عنه قال‏:‏ أخرجت لنا عائشة رضي الله عنها كساء وإزاراً غليظاً قالت‏:‏ قبض رسول الله صلى الله عليه وسلم في هذين ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1716","bookId":"riyad","type":"hadith","num":1716,"kitab":"كتاب المقدمات","isnad":"وعن سعيد بن أبي وقاص، رضي الله عنه، قال‏:‏ إني لأول العرب رمي بسهم في سبيل الله، ولقد كنا نغزو مع رسول الله صلى الله عليه وسلم ما لنا طعام إلا ورق الحلبة، هذا السمر، حتى إن كان أحدنا ليضع كما تضع الشاة ما له خلط‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏","matn":"\"‏ الحلبة‏\"‏ بضم الحاء المهملة وإسكان الباء الموحدة‏:‏ وهي والسمر، نوعان معروفان من شجر البادية‏.‏"},{"id":"riyad:1717","bookId":"riyad","type":"hadith","num":1717,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ قال رسول الله، صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ اللهم اجعل رزق آل محمد قوتاً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ قال أهل اللغة والغريب‏:‏ معنى ‏\"‏ قوتاً‏\"‏ أي‏:‏ ما يسد الرمق‏.‏"},{"id":"riyad:1718","bookId":"riyad","type":"hadith","num":1718,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ والله الذي لا إله إلا هو، إن كنت لأعتمد بكبدي على الأرض من الجوع، وإن كنت لأشد الحجر على بطني من الجوع‏.‏ ولقد قعدت يوماً على طريقهم الذي يخرجون منه، فمر بي النبي، صلى الله عليه وسلم ، فتبسم حين رآني، وعرف ما في وجهي وما في نفسي، ثم قال‏:‏ ‏","matn":"\"‏ أبا هر‏\"‏ قلت لبيك يا رسول الله، قال‏:‏ ‏\"‏ الحق‏\"‏ ومضى فاتبعته، فدخل فاستأذن، فأذن لي فدخلت، فوجد لبنا في قدح فقال‏:‏ ‏\"‏ من أين هذا اللبن‏؟‏‏\"‏ قالوا‏:‏ أهداه لك فلان- أو فلانة- قال‏:‏‏\"‏ أبا هر‏\"‏ قلت‏:‏ لبيك يارسول الله، قال‏:‏ ‏\"‏ الحق إلى أهل الصفة فادعهم لي‏\"‏ قال‏:‏ وأهل الصفة أضياف الإسلام، لا يأوون على أهل، ولا مال، وإذا أتته هدية أرسل إليهم، وأصاب منها وأشركهم فيها، فساءني ذلك فقلت‏:‏ وما هذا اللبن في أهل الصفة‏!‏ كنت أحق أن أصيب من هذا اللبن شربة أتقوى بها، فإذا جأووا وأمرني فكنت أنا أعطيهم؛ وما عسى أن يبلغني من هذا اللبن، ولم يكن من طاعة الله وطاعة رسوله، صلى الله عليه وسلم بد، فأتيتهم فدعوتهم، فأقبلوا واستأذنوا، فأذن لهم وأخذوا مجالسهم من البيت قال‏:‏‏\"‏ يا أبا هر‏\"‏ قلت‏:‏ لبيك يا رسول الله قال‏:‏ ‏\"‏ خذ فأعطهم‏\"‏ قال‏:‏ فأخذت القدح، فجعلت أعطيه الرجل فيشرب حتى يروى، ثم يرد علي القدح، فأعطيه الآخر فيشرب حتى يروى، ثم يرد علي القدح حتى انتيهت إلى النبي صلى الله عليه وسلم ، وقد روي القوم كلهم، فأخذ القدح فوضعه على يده، فنظر إلي فتبسم، فقال‏:‏ ‏\"‏ أبا هر‏\"‏ قلت‏:‏ لبيك يا رسول الله، قال‏:‏ ‏\"‏ بقيت أنا وأنت‏\"‏ قلت‏:‏ صدقت يا رسول الله، قال‏:‏ ‏\"‏ اقعد فاشرب‏\"‏ فقعدت فشربت‏:‏ فقال‏:‏ ‏\"‏ اشرب‏\"‏ فشربت، فما زال يقول‏:‏ ‏\"‏ اشرب‏\"‏ حتى قلت‏:‏ لا والذي بعثك بالحق ما أجد له مسلكاً‏!‏ قال‏:‏ ‏\"‏ فأرني‏\"‏ فأعطيته القدح، فحمد الله تعالى، وسمى وشرب الفضلة‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1719","bookId":"riyad","type":"hadith","num":1719,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن محمد بن سيرين عن أبي هريرة، رضي الله عنه، قال‏:‏ لقد رأيتني وإني لأجر فيما بين منبر رسول الله، صلى الله عليه وسلم، إلى حجرة عائشة رضي الله عنها مغشياً علي، فيجيء الجائي، فيضع رجلة على عنقي، ويرى أني مجنون وما بي من جنون، ما بي إلا الجوع‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1720","bookId":"riyad","type":"hadith","num":1720,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة، رضي الله عنها قالت‏:‏ توفي رسول الله صلى الله عليه وسلم ودرعه مرهونة عند يهودي في ثلاثين صاعاً من شعير‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1721","bookId":"riyad","type":"hadith","num":1721,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ رهن النبي صلى الله عليه وسلم درعه بشعير، ومشيت إلى النبي صلى الله عليه وسلم بخبز شعير، وإهالة سنخة، ولقد سمعته يقول‏:‏ ‏","matn":"\"‏ ما أصبح لآل محمد صاع ولا أمسى‏\"‏ وإنهم لتسعة أبيات‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ (‏‏(‏‏ ‏الإهالة‏ ‏ بكسر الهمزة‏:‏ الشحم الذائب‏.‏ و‏ ‏ السخنة‏ ‏ بالنون والخاء المعجمة؛ وهي‏:‏ المتغيرة‏)‏‏)‏‏.‏"},{"id":"riyad:1722","bookId":"riyad","type":"hadith","num":1722,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة، رضي الله عنه، قال‏:‏ لقد رأيت سبعين من أهل الصفة، ما منهم رجل عليه رداء، إما إزار وإما كساء، قد ربطوا في أعناقهم منها ما يبلغ نصف الساقين، ومنها ما يبلغ الكعبين، فيجمعه بيده كراهية أن ترى عورته‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1723","bookId":"riyad","type":"hadith","num":1723,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان فراش رسول الله صلى الله عليه وسلم من أدم حشوه ليف‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1724","bookId":"riyad","type":"hadith","num":1724,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ كنا جلوساً مع رسول الله صلى الله عليه وسلم ، إذ جاء رجل من الأنصار، فسلم عليه، ثم أدبر الأنصاري، فقال رسول الله‏.‏ صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ يا أخا الأنصار؛ كيف أخي سعد بن عبادة‏؟‏‏\"‏ فقال‏:‏ صالح، فقال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏من يعوده منكم‏؟‏‏\"‏ فقام وقمنا معه، ونحن بضعة عشر، ما علينا نعال، ولا خفاف، ولا قلانس، ولا قمص، نمشي في تلك السباخ، حتى جئناه، فاستأخر قومه من حوله حتى دنا رسول الله صلى الله عليه وسلم وأصحابه الذين معه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1725","bookId":"riyad","type":"hadith","num":1725,"kitab":"كتاب المقدمات","isnad":"وعن عمران بن الحصين رضي الله عنهما، عن النبي صلى الله عليه وسلم أنه قال‏:‏ ‏","matn":"\"‏ خيركم قرني، ثم الذين يلونهم، ثم الذين يلونهم‏\"‏ قال عمران‏:‏ فما أدري قال‏:‏ النبي صلى الله عليه وسلم مرتين أو ثلاثاً ‏\"‏ ثم يكون بعدهم قوم يشهدون ولا يستشهدون، ويخونون ولا يؤتمنون، وينذرون ولا يوفون، ويظهر فيهم السمن‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1726","bookId":"riyad","type":"hadith","num":1726,"kitab":"كتاب المقدمات","isnad":"وعن أبي أمامة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ يا ابن آدم‏:‏ إنك أن تبذل الفضل خير لك، وأن تمسكه شر لك، ولا تلام على كفاف، وابدأ بمن تعول‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1727","bookId":"riyad","type":"hadith","num":1727,"kitab":"كتاب المقدمات","isnad":"وعن عبيد الله بن محصن الأنصاري الخطمي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏ من أصبح منكم آمنا في سربه، معافى في جسده، عنده قوت يومه، فكأنما حيزت له الدنيا بحذافيرها‏\"‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1728","bookId":"riyad","type":"hadith","num":1728,"kitab":"كتاب المقدمات","isnad":"-وعن عبد الله بن عمرو بن العاص رضي الله عنهما ، أن رسول الله صلى الله عليه وسلم قال ‏:‏ ‏","matn":"\"‏ قد أفلح من أسلم ، وكان رزقه كفافا ، وقنعه الله بما آتاه ‏\"‏ ‏(‏‏(‏رواه مسلم ‏)‏‏)‏‏.‏"},{"id":"riyad:1729","bookId":"riyad","type":"hadith","num":1729,"kitab":"كتاب المقدمات","isnad":"-وعن أبي محمد فضاله بن عبيد الأنصاري رضي الله عنه ، أنه سمع رسول الله صلى الله عليه وسلم يقول ‏:‏ ‏","matn":"\"‏طوبى لمن هدي إلى الإسلام ، وكان عيشه كفافا ،وقنع ‏\"‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏حديث حسن صحيح ‏)‏‏)‏‏.‏"},{"id":"riyad:1730","bookId":"riyad","type":"hadith","num":1730,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عباس رضي الله عنهما قال ‏:‏ كان رسول الله صلى الله عليه وسلم يبيت الليالي المتتابعه طاويا، وأهله لايجدون عشاء ، وكان أكثر خبزهم خبز الشعير ‏.‏ ‏(‏‏(‏رواه الترمذي وقال ‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1731","bookId":"riyad","type":"hadith","num":1731,"kitab":"كتاب المقدمات","isnad":"وعن فضالة بن عبيد رضي الله عنه، أن رسول الله صلى الله عليه وسلم كان إذا صلى بالناس، يخر رجال من قامتهم في الصلاة من الخصاصة -وهم أصحاب الصفة- حتى يقول الأعراب‏:‏ هؤلاء مجانين، فإذا صلى رسول الله صلى الله عليه وسلم انصرف إليهم، فقال‏:‏ ‏","matn":"\"‏لو تعلمون ما لكم عند الله تعالى، لأحببتم أن تزدادوا فاقة وحاجة‏\"‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث صحيح‏)‏‏)‏‏.‏ ‏\"‏الخصاصة‏\"‏‏:‏ الفاقة والجوع الشديد‏.‏"},{"id":"riyad:1732","bookId":"riyad","type":"hadith","num":1732,"kitab":"كتاب المقدمات","isnad":"وعن أبي كريمة المقدام بن معديكرب رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول “ما ملأ آدمي وعاء شراً من بطن، بحسب ابن آدم أكلات يقمن صلبه، فإن كان لا محالة؛ فتلث لطعامه وثلث لشرابه، وثلث لنفسه‏","matn":"\"‏‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ ‏\"‏أكلات‏\"‏ أي‏:‏ لقم‏.‏"},{"id":"riyad:1733","bookId":"riyad","type":"hadith","num":1733,"kitab":"كتاب المقدمات","isnad":"وعن أبي أمامة إياس بن ثعلبة الأنصاري الحارثي رضي الله عنه قال‏:‏ ذكر أصحاب رسول الله صلى الله عليه وسلم يوماً عنده الدنيا، فقال رسول الله صلى الله عليه وسلم ‏:‏ “ألا تسمعون‏؟‏ ألا تسمعون‏؟‏ إن البذاذة من الإيمان، إن البذاذة من الإيمان‏","matn":"\"‏ يعني‏:‏ التقحل‏.‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏ ‏\"‏البذاذة‏\"‏ بالباء الموحدة والذالين المعجمتين، وهي رثاثة الهيئة، وترك فاخر اللباس‏.‏ وأما ‏\"‏التقحل‏\"‏ فبالقاف والحاء، قال أهل اللغة‏:‏ المتقحل‏:‏ هو الرجل اليابس الجلد من خشونة العيش، وترك الترفة‏.‏"},{"id":"riyad:1734","bookId":"riyad","type":"hadith","num":1734,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الله جابر بن عبد الله رضي الله عنهما قال‏:‏ بعثنا رسول الله صلى الله عليه وسلم وأمر علينا أبا عبيدة رضي الله عنه، نتلقى عيرا لقريش، وزودنا جراباً من تمر لم يجد لنا غيره، فكان أبوعبيدة يعطينا تمرة تمرة، فقيل كيف كنتم تصنعون بها‏؟‏ قال‏:‏ نمصها كما يمص الصبي، ثم نشرب عليها من الماء، فتكفينا يومنا إلى الليل، وكنا نضرب بعصينا الخبط، ثم نبله بالماء فنأكله‏.‏ قال‏:‏ وانطلقنا على ساحل البحر، فرفع لنا على ساحل البحر كهيئة الكثيب الضخم، فأتيناه فإذا هي دابة تدعى العنبر، فقال أبو عبيدة‏:‏ ميتة، ثم قال‏:‏ لا، بل نحن رسل رسول الله صلى الله عليه وسلم وفي سبيل الله وقد اضطررتم فكلوا، فأقمنا عليه شهرا، ونحن ثلاثمائة، حتى سمنا، ولقد رأيتنا نغترف من وقب عينه بالقلال الدهن ونقطع منه الفدر كالثور أو كقدر الثور، ولقد أخذ منا أبوعبيدة ثلاثة عشر رجلا فأقعدهم في وقب عينه وأخذ ضلعا من أضلاعه فأقامها ثم رحل أعظم بعير معنا فمر من تحتها وتزودنا من لحمه وشائق، فلما قدمنا المدينة أتينا رسول الله صلى الله عليه وسلم فذكرنا ذلك له، فقال‏:‏ ‏","matn":"\"‏هو رزق أخرجه الله لكم، فهل معكم من لحمه شئ فتطعمونا‏؟‏‏\"‏ فأرسلنا إلى رسول الله صلى الله عليه وسلم منه فأكله‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏\"‏الجراب‏\"‏‏:‏ وعاء من جلد معروف، وهو بكسر الجيم وفتحها، والكسر أفصح‏.‏ قوله‏:‏ نمصها‏\"‏ بفتح الميم‏.‏ ‏\"‏والخبط‏\"‏ ورق شجر معروف تأكله الإبل‏.‏ ‏\"‏والكثيب‏\"‏‏:‏ التل من الرمل‏.‏ ‏\"‏والوقب‏\"‏ بفتح الواو وإسكان القاف وبعدها باء موحدة، وهو نقرة العين‏.‏ ‏\"‏بتخفيف الحاء‏:‏ أي جعل عليه الرحل‏.‏ ‏\"‏الشائق‏\"‏ بالشين المعجمة والقاف‏:‏ اللحم الذي اقتطع ليقدد منه، والله اعلم‏.‏"},{"id":"riyad:1735","bookId":"riyad","type":"hadith","num":1735,"kitab":"كتاب المقدمات","isnad":"وعن أسماء بنت يزيد رضي الله عنها قالت‏:‏ كان كم قميص رسول الله صلى الله عليه وسلم إلى الرصغ، ‏(‏‏(‏رواه أبو داود، والترمذي، وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ ‏","matn":"\"‏الرصغ‏:‏ بالصاد والرسغ بالسين أيضاً‏:‏ هو المفصل بين الكف والساعد‏.‏"},{"id":"riyad:1736","bookId":"riyad","type":"hadith","num":1736,"kitab":"كتاب المقدمات","isnad":"وعن جابر رضي الله عنه قال‏:‏ إنا كنا يوم الخندق نحفر، فعرضت كدية شديدة، فجاؤوا إلى النبي صلى الله عليه وسلم فقالوا‏:‏ هذه كدية عرضت في الخندق‏.‏ فقال‏:‏ ‏","matn":"\"‏أنا نازل‏\"‏ ثم قام، وبطنه معصوب بحجر، ولبثنا ثلاثة أيام لا نذوق ذوقاً فأخذ النبي صلى الله عليه وسلم المعول، فضرب، فعاد كثيباً أهيل، أو أهيم، فقلت‏:‏ يا رسول الله ائذن لي إلى البيت، فقلت لامرأتي‏:‏ رأيت بالنبي صلى الله عليه وسلم شيئاً ما في ذلك صبر فعندك شيء‏؟‏ فقالت‏:‏ عندي شعير وعناق، فذبحت العناق وطحنت الشعير حتى جعلنا اللحم في البرمة، ثم جئت النبي صلى الله عليه وسلم والعجين قد انكسر، والبرمة بين الأثاقي قد كادت تنضج، فقلت‏:‏ طعيم لي، فقم أنت يا رسول الله ورجل أو رجلان، قال‏:‏ ‏\"‏كم هو‏؟‏‏\"‏ فذكرت له فقال‏:‏ ‏\"‏كثير طيب، قل لها لا تنزع البرمة، ولا الخبز من التنور حتى آتي” فقال‏:‏ “قوموا” فقام المهاجرون والأنصار، فدخلت عليها فقلت‏:‏ ويحك جاء النبي صلى الله عليه وسلم والمهاجرون والأنصار ومن معهم‏!‏ قالت‏:‏ هل سألك‏؟‏ قلت‏:‏ نعم، قال‏:‏ “ادخلوا ولا تضاغطوا فجعل يكسر الخبز، ويجعل عليه اللحم، ويخمر البرمة والتنور إذا أخذ منه، ويقرب إلى أصحابه ثم ينزع، فلم يزل يكسر ويغرف حتى شبعوا، وبقي منه، فقال‏:‏ كلي هذا وأهدي، فإن الناس أصابتهم مجاعة” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ قال جابر‏:‏ لما حفر الخندق رأيت النبي صلى الله عليه وسلم خمصاً، فانكفأت إلى امراتى فقلت‏:‏ هل عندك شيء؛ فإني رأيت برسول الله صلى الله عليه وسلم خمصاً شديداً فأخرجت إلي جرابا فيه صاع من شعير، ولنا بهيمة داجن فذبحتها، وطحنت الشعير، ففرغت إلى فراغى، وقطعتها في برمتها، ثم وليت إلى رسول الله صلى الله عليه وسلم فقالت‏:‏ لا تفضحني برسول الله صلى الله عليه وسلم ومن معه، فجئته وساررته فقلت‏:‏ يا رسول الله، ذبحنا بهيمة لنا، وطحنت صاعا من شعير، فتعال أنت ونفر معك، فصاح رسول الله صلى الله عليه وسلم فقال‏:‏ يا أهل الخندق إن جابراً قد صنع سؤراً فحيهلا بكم‏\"‏ فقال النبي صلى الله عليه وسلم ‏:‏ ‏\"‏لا تنزلن برمتكم ولا تخبزن عجينكم حتى أجيء‏\"‏ فجئت، وجاء النبي صلى الله عليه وسلم يقدم الناس، حتى جئت امرأتي فقالت‏:‏ بك وبك‏!‏ فقلت‏:‏ قد فعلت الذي قلت‏.‏ فأخرجت عجيناً، فبسق فيه وبارك، ثم عمد إلى برمتنا فبصق وبارك، ثم قال‏:‏ ‏\"‏ادعي خابزة فلتخبز معك، واقدحي من برمتكم ولا تنزلوها‏\"‏وهم ألف، فأقسم بالله لأكلوا حتى تركوه وانحرفوا، وإن برمتنا لتغط كما هي، وإن عجيننا ليخبز كما هو‏.‏ قوله‏:‏ ‏\"‏عرضت كدية‏\"‏ ‏:‏ بضم الكاف وإسكان الدال وبالياء المثناة تحت؛ وهي قطعة غليظة صلبة من الأرض لا يعمل فيها الفأس‏.‏ ‏\"‏والكثيب‏\"‏ أصله تل الرمل، والمراد هنا‏:‏ صارت تراباً ناعماً، وهو معنى “أهيل”‏.‏ ‏\"‏الأثافي‏\"‏ ‏:‏ الأحجار التى يكون عليها القدر‏.‏ و‏\"‏تضاغطوا‏\"‏ ‏:‏ تزاحموا‏.‏ و‏\"‏المجاعة‏\"‏ ‏:‏الجوع، وهو بفتح الميم‏.‏ و‏\"‏الخمص‏\"‏ بفتح الخاء المعجمة والميم‏:‏ الجوع‏.‏ و”انكفأت” ‏:‏ انقلبت ورجعت‏.‏ ‏\"‏البهيمة‏\"‏ بضم الباء‏:‏ تصغير بهمة، وهي العناق -بفتح العين-‏.‏ و‏\"‏الداجن‏\"‏‏:‏ هي التي ألفت البيت‏.‏ و‏\"‏السؤر‏\"‏ ‏:‏الطعام الذي يدعى الناس إليه، وهو بالفارسية‏.‏ و‏\"‏حيهلا‏\"‏ أي‏:‏ تعالوا‏.‏ وقولها‏:‏ ‏\"‏بك وبك‏\"‏ أي‏:‏ خاصمته وسبته، لأنها اعتقدت أن الذي عندها لا يكفيهم، فاستحيت وخفي عليها ما أكرم الله سبحانه وتعالى به نبيه صلى الله عليه وسلم من هذه المعجزة الظاهرة والآية اباهرة‏.‏ “بسق‏\"‏ أي ‏:‏بصق؛ ويقال أيضاً‏:‏ بزق -ثلاث لغات- و‏\"‏عمد‏\"‏ بفتح الميم‏:‏ أي قصد‏.‏ و‏\"‏اقدحي” أي اغرفي؛ والمقدحة‏:‏ المغرفة‏.‏ و”تغط” أي‏:‏ لغليانها صوت، والله اعلم‏.‏"},{"id":"riyad:1737","bookId":"riyad","type":"hadith","num":1737,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال أبو طلحة لأم سليم‏:‏ قد سمعت صوت رسول الله صلى الله عليه وسلم ضعيفاً أعرف فيه الجوع، فهل عندك من شيء‏؟‏ فقالت‏:‏ نعم، فأخرجت أقراصاً من شعير، ثم أخذت خماراً لها، فلفت الخبز ببعضه، ثم دسته تحت ثوبي وردتني ببعضه، ثم أرسلتني إلى رسول الله صلى الله عليه وسلم فذهبت به، فوجدت رسول الله صلى الله عليه وسلم جالساً في المسجد، ومعه الناس، فقمت عليهم، فقال لي رسول الله صلى الله عليه وسلم ‏","matn":"\"‏أرسلك أبو طلحة‏؟‏‏\"‏ فقلت‏:‏ نعم، فقال‏:‏ ‏\"‏ألطعام‏\"‏ فقلت‏:‏ نعم، فقال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏قوموا‏\"‏ فانطلقوا بين أيديهم حتى جئت أبا طلحة فأخبرته، فقال أبو طلحة‏:‏ يا أم سليم‏:‏ قد جاء رسول الله بالناس وليس عندنا ما نطعمهم‏؟‏ فقالت‏:‏ الله ورسوله أعلم‏.‏ فانطلق أبو طلحة حتى لقي رسول الله صلى الله عليه وسلم فأقبل رسول الله صلى الله عليه وسلم معه حتى دخلا، فقال رسول الله صلى الله عليه وسلم‏:‏ “هلمى ما عندك يا أم سليم‏\"‏ فأتت بذلك الخبز، فأمر به رسول الله صلى الله عليه وسلم ففت وعصرت عليه أم سليم عكة فآدمته، ثم قال فيه رسول الله صلى الله عليه وسلم ما شاء الله أن يقول، ثم قال‏:‏ ‏\"‏ائذن لعشرة‏\"‏ فأذن لهم، فأكلوا حتى شبعوا ثم خرجوا، ثم قال‏:‏ ‏\"‏ائذن لعشرة‏\"‏ فأذن لهم، فأكلوا حتى شبعوا، ثم خرجوا، ثم قال‏:‏ ‏\"‏ائذن لعشرة‏\"‏ فأذن لهم حتى أكل القوم كلهم وشبعوا، والقوم سبعون رجلاً أو ثمانون‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وفي رواية‏:‏ فما زال يدخل عشرة ويخرج عشرة، حتى لم يبق منهم أحد إلا دخل، فأكل حتى شبع، ثم هيأها فإذا هي مثلها حين اكلوا منها‏.‏ وفي رواية‏:‏ فأكلوا عشرة عشرة، حتى فعل ذلك بثمانين رجلا، ثم أكل النبي صلى الله عليه وسلم بعد ذلك وأهل البيت، وتركوا سؤراً‏.‏ وفي رواية‏:‏ ثم أفضلوا ما بلغوا جيرانهم‏.‏ وفي رواية عن أنس قال‏:‏ جئت رسول الله صلى الله عليه وسلم يوماً، فوجدته جالساً مع أصحابه، وقد عصب بطنه بعصابة، فقلت لبعض أصحابه‏:‏ لم عصب رسول الله صلى الله عليه وسلم بطنه‏؟‏ فقالوا‏:‏ من الجوع، فذهبت إلى أبي طلحة، وهو زوج أم سليم بنت ملحان، فقلت‏:‏ يا أبتاه، قد رأيت رسول الله صلى الله عليه وسلم عصب بطنه بعصابة، فسألت بعض أصحابه، فقالوا‏:‏ من الجوع‏.‏ فدخل أبو طلحة على أمي فقال‏:‏ هل من شيء ‏؟‏ قالت‏:‏ نعم عندي كسر من خبز وتمرات، فإن جاءنا رسول الله صلى الله عليه وسلم وحده أشبعناه وإن جاء آخر معه قل عنهم، وذكر تمام الحديث‏.‏"},{"id":"riyad:1738","bookId":"riyad","type":"hadith","num":1738,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس الغنى عن كثرة العرض، ولكن الغنى غنى النفس‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏\"‏العرض‏\"‏ بفتح العين والراء‏:‏ هو المال‏.‏"},{"id":"riyad:1739","bookId":"riyad","type":"hadith","num":1739,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏قد أفلح من أسلم، ورزق كفافاً، وقنعه الله بما آتاه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1740","bookId":"riyad","type":"hadith","num":1740,"kitab":"كتاب المقدمات","isnad":"وعن حكيم بن حزام رضي الله عنه قال‏:‏ سألت رسول الله صلى الله عليه وسلم فأعطاني، ثم سألته فأعطاني، ثم سألته فأعطاني ثم قال‏:‏ ‏","matn":"\"‏يا حكيم، إن هذا المال خضر حلو، فمن أخذه بسخاوة نفس بورك له فيه، ومن أخذه بإشراف نفس لم يبارك له فيه، وكان كالذي يأكل ولا يشبع، واليد العليا خير من اليد السفلى‏\"‏ قال حكيم‏:‏ فقلت يا رسول الله والذي بعثك بالحق لا أرزأ أحداً بعدك شيئاً حتى أفارق الدنيا‏.‏ فكان أبو بكر رضي الله عنه يدعو حكيماً ليعطيه العطاء، فيأبى أن يقبل منه شيئاً ثم إن عمر رضي الله عنه دعاه ليعطيه، فأبى أن يقبله‏.‏ فقال‏:‏ يا معشر المسلمين، أشهدكم على حكيم أني أعرض عليه حقه الذي قسمه الله له في هذا الفيء فيأبى أن يأخذه فلم يرزأ حكيم أحداً بعد النبي صلى الله عليه وسلم حتى توفي‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏\"‏يرزأ‏\"‏ براء ثم زاى ثم همزة، أي‏:‏ لم يأخذ من أحد شيئاً، وأصل الرزء‏:‏ النقصان، أي‏:‏ لم ينقص أحداً شيئاً بالأخذ منه‏.‏ و‏\"‏إشراف النفس‏\"‏‏:‏ تطلعها وطمعها بالشيء‏.‏ ‏\"‏سخاوة النفس‏\"‏‏:‏ هي عدم الإشراف إلى الشيء، والطمع فيه، والمبالاة به والشره‏.‏"},{"id":"riyad:1741","bookId":"riyad","type":"hadith","num":1741,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي بردة عن أبي موسى الأشعري رضي الله عنه قال‏:‏ خرجنا مع رسول الله صلى الله عليه وسلم في غزاة، ونحن ستة نفر بيننا بعير نعتقبه، فنقبت أقدامنا ونقبت قدمي، وسقطت أظافري، فكنا نلف على أرجلنا الخرق، فسميت غزوة ذات الرقاع لما كنا نعصب على أرجلنا من الخرق قال أبو بردة‏:‏ فحدث أبوموسى بهذا الحديث، ثم كره ذلك، وقال‏:‏ ما كنت أصنع بأن أذكره‏!‏ قال‏:‏ كأنه كره أن يكون شئياً من عمله أفشاه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1742","bookId":"riyad","type":"hadith","num":1742,"kitab":"كتاب المقدمات","isnad":"وعن عمرو بن تغلب - بفتح التاء المثناة فوق وإسكان الغين المعجمة وكسر اللام - رضي الله عنه أن رسول الله صلى الله عليه وسلم أتي بمال أو سبي فقسمه، فأعطى رجالا، وترك رجالا، فبلغه أن الذين ترك عتبوا ؛فحمد الله ثم أثنى عليه ثم قال، أما بعد فوالله إني لأعطي الرجل وأدع الرجل والذي أدع أحب إلي من الذي أعطي، ولكني إنما أعطي أقواماً لما أرى في قلوبهم من الجزع والهلع، وأكل أقواماً إلى ما جعل الله في قلوبهم من الغنى والخير، منهم عمرو بن تغلب” قال عمرو بن تغلب‏:‏ فوالله ما أحب أن لي بكلمة رسول الله صلى الله عليه وسلم حمر النعم ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ ‏","matn":"\"‏الهلع‏\"‏‏:‏ هو أشد الجزع، وقيل‏:‏ الضجر‏.‏"},{"id":"riyad:1743","bookId":"riyad","type":"hadith","num":1743,"kitab":"كتاب المقدمات","isnad":"وعن حكيم بن حزام رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏اليد العليا خير من اليد السفلى، وابدأ بمن تعول، وخير الصدقة عن ظهر غنى ومن يستعفف يعفه الله، ومن يستغن يغنه الله” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏(‏‏(‏وهذا لفظ البخاري، ولفظ مسلم أخصر‏)‏‏)‏‏.‏"},{"id":"riyad:1744","bookId":"riyad","type":"hadith","num":1744,"kitab":"كتاب المقدمات","isnad":"وعن أبي سفيان صخر بن حرب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا تلحفوا في المسألة، فوالله لا يسألني أحد منكم شئياً، فتخرج له مسألته مني شئا وأنا له كاره، فيبارك له فيما أعطيته‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1745","bookId":"riyad","type":"hadith","num":1745,"kitab":"كتاب المقدمات","isnad":"وعن أبي عبد الرحمن عوف بن مالك الأشجعي رضي الله عنه قال‏:‏ كنا عند رسول الله صلى الله عليه وسلم تسعة أو ثمانية أو سبعة فقال‏:‏ ‏","matn":"\"‏ألا تبايعون رسول الله صلى الله عليه وسلم‏\"‏ وكنا حديثي عهد ببيعة، فقلنا‏:‏ قد بايعناك يا رسول الله، فعلام نبايعك‏؟‏ قال‏:‏ ‏\"‏على أن تعبدوا الله ولا تشركوا به شيئاً، والصلوات الخمس وتطيعوا‏\"‏ وأسر كلمة خفية‏:‏ ‏\"‏ولا تسألوا الناس شيئاً‏\"‏ فلقد رأيت بعض أولئك النفر يسقط سوط أحدهم فما يسأل احداً يناوله اياه‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1746","bookId":"riyad","type":"hadith","num":1746,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ “لا تزال المسألة بأحدكم حتى يلقى الله تعالى وليس في وجهه مزعة لحم‏","matn":"\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏\"‏المزعة‏\"‏ بضم الميم وإسكان الزاى وبالعين المهملة‏:‏ القطعة‏.‏"},{"id":"riyad:1747","bookId":"riyad","type":"hadith","num":1747,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال وهو على المنبر، وذكر الصدقة والتعفف عن المسألة‏:‏ ‏","matn":"\"‏اليد العليا خير من اليد السفلى‏.‏ واليد العليا هي المنفقة، والسفلى هي السائلة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1748","bookId":"riyad","type":"hadith","num":1748,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من سأل الناس تكثراً فإنما يسأل جمراً؛ فليستقل أو ليستكثر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1749","bookId":"riyad","type":"hadith","num":1749,"kitab":"كتاب المقدمات","isnad":"وعن سمرة بن جندب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “إن المسألة كد يكد بها الرجل وجهه، إلا أن يسأل الرجل سلطاناً أو في أمر لا بد منه‏","matn":"\"‏ ‏(‏‏(‏رواه الترمذي، وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏ ‏\"‏الكد‏\"‏ ‏:‏الخدش ونحوه‏.‏"},{"id":"riyad:1750","bookId":"riyad","type":"hadith","num":1750,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من أصابته فاقة فأنزلها بالناس لم تسد فاقته، ومن أنزلها بالله، فيوشك الله له برزق عاجل أو آجل‏\"‏ ‏(‏‏(‏رواه أبو داود، والترمذي وقال‏:‏ حديث حسن‏)‏‏)‏ ‏\"‏يوشك‏\"‏ بكسر الشين‏:‏ أي يسرع‏.‏"},{"id":"riyad:1751","bookId":"riyad","type":"hadith","num":1751,"kitab":"كتاب المقدمات","isnad":"وعن ثوبان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏من تكفل لي أن لا يسأل الناس شيئاً، وأتكفل له الجنة‏؟‏‏\"‏ فقلت‏:‏ أنا؛ فكان لا يسأل أحداً شيئاً، ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1752","bookId":"riyad","type":"hadith","num":1752,"kitab":"كتاب المقدمات","isnad":"وعن أبي بشر قبيصة بن المخارق رضي الله عنه قال‏:‏ تحملت حمالة رسول الله صلى الله عليه وسلم أسأله فيها، فقال‏:‏ ‏","matn":"\"‏أقم حتى تأتينا الصدقة فنأمر لك بها‏\"‏ ثم قال‏:‏ ‏\"‏يا قبيصة إن المسألة لا تحل إلا لأحد ثلاثة‏:‏ رجل تحمل حمالة، فحلت له المسألة حتى يصيبها، ثم يمسك‏.‏ ورجل أصابته جائحة اجتاحت ماله، فحلت له المسألة حتى يصيب قوماً من عيش، أو قال‏:‏ سداداً من عيش، ورجل أصابته فاقة، حتى يقول ثلاثة من ذوى الحجى من قومه‏:‏ لقد أصابت فلاناً فاقة، فحملت له المسألة حتى يصيب قواما من عيش، أو قال‏:‏ سداداً من عيش‏.‏ فما سواهن من المسألة يا قبيصة سحت، يأكلها صاحبها سحتاً‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ ‏\"‏الحمالة‏\"‏ بفتح الحاء‏:‏ أن يقع قتال ونحوه بين فريقين، فيصلح إنسان بينهم على مال يتحمله ويلتزمه على نفسه‏.‏ و‏\"‏الجائحة‏\"‏ ‏:‏ الآفة تصيب مال الإنسان‏.‏ و‏\"‏القوام‏\"‏ بكسر القاف وفتحها‏:‏ هو ما يقوم به أمر الإنسان من مال ونحوه‏.‏ و‏\"‏السداد‏\"‏ بكسر السين‏:‏ ما يسد حاجة المعوز ويكفيه، و‏\"‏الفاقة‏\"‏ ‏:‏ الفقر‏.‏ و‏\"‏الحجى‏\"‏‏:‏ العقل‏.‏"},{"id":"riyad:1753","bookId":"riyad","type":"hadith","num":1753,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ليس المسكين الذي يطوف على الناس ترده اللقمة واللقمتان، والتمرة والتمرتان، ولكن المسكين الذي لا يجد غنى يغنيه، ولا يفطن له، فيتصدق عليه، ولا يقوم فيسأل الناس‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1754","bookId":"riyad","type":"hadith","num":1754,"kitab":"كتاب المقدمات","isnad":"عن سالم بن عبد الله بن عمر، عن أبيه عبد الله بن عمر، عن عمر رضي الله عنهم قال‏:‏ كان رسول الله صلى الله عليه وسلم يعطيني العطاء، فأقول‏:‏ أعطه من هو أفقر إليه مني، فقال‏:‏ ‏","matn":"\"‏خذه؛ إذا جاءك من هذا المال شئ، وأنت غير مشرف ولا سائل، فخذه فتموله فإن شئت كله، وإن شئت تصدق به، وما لا، فلا تتبعه نفسك‏\"‏ قال سالم‏:‏ فكان عبد الله لا يسأل أحداً شيئاً، ولا يرد شيئاً أعطيه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1755","bookId":"riyad","type":"hadith","num":1755,"kitab":"كتاب المقدمات","isnad":"عن أبي عبد الله الزبير بن العوام رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “لأن يأخذ أحدكم أحبله ثم يأتى الجبل فيأتي بحزمة من حطب على ظهره فيبيعها، فيكف الله بها وجهه، خير له من أن يسأل الناس أعطوه أومنعوه‏","matn":"\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1756","bookId":"riyad","type":"hadith","num":1756,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لأن يحتطب أحدكم حزمة على ظهره، خير له من أن يسأل أحداً فيعطيه أو يمنعه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1757","bookId":"riyad","type":"hadith","num":1757,"kitab":"كتاب المقدمات","isnad":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏كان داود عليه السلام لا يأكل إلا من عمل يده‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1758","bookId":"riyad","type":"hadith","num":1758,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “كان زكريا عليه السلام نجاراً” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1759","bookId":"riyad","type":"hadith","num":1759,"kitab":"كتاب المقدمات","isnad":"وعن المقدام بن معد يكرب رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ ما أكل أحد طعاماً قط خيراً من أن يأكل من عمل يده، وإن نبى الله دواد صلى الله عليه وسلم كان يأكل من عمل يده‏\"‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1760","bookId":"riyad","type":"hadith","num":1760,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏لا حسد إلا فى اثنتين‏:‏ رجل آتاه الله مالاً، فسلطه على هلكته فى الحق، ورجل آتاه الله حكمة، فهو يقضي بها ويعلمها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1761","bookId":"riyad","type":"hadith","num":1761,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “أيكم مال وارثه أحب إليه من ماله‏؟‏” قالوا‏:‏ يا رسول الله، ما منا أحد إلا ماله أحب إليه‏.‏ قال‏:‏ ‏","matn":"\"‏فإن ماله ما قدم ومال وارثه ما أخر‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1762","bookId":"riyad","type":"hadith","num":1762,"kitab":"كتاب المقدمات","isnad":"وعن عدى بن حاتم رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏اتقوا النار ولو بشق تمرة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1763","bookId":"riyad","type":"hadith","num":1763,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن جابر رضي الله عنه قال‏:‏ ما سئل رسول الله صلى الله عليه وسلم شيئاً قط فقال‏:‏ لا‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1764","bookId":"riyad","type":"hadith","num":1764,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ ما من يوم يصبح العباد فيه إلا ملكان ينزلان فيقول أحدهما‏:‏ اللهم أعط منفقاً خلفاً، ويقول الآخر‏:‏ اللهم أعط ممسكاً تلفاً‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1765","bookId":"riyad","type":"hadith","num":1765,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “قال الله تعالى‏:‏ انفق يا ابن آدم ينفق عليك” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1766","bookId":"riyad","type":"hadith","num":1766,"kitab":"كتاب المقدمات","isnad":"عن عبد الله بن عمرو بن العاص رضي الله عنهما أن رجلاً سأل رسول الله صلى الله عليه وسلم ‏:‏ أى الإسلام خير‏؟‏ قال‏:‏ ‏","matn":"\"‏تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1767","bookId":"riyad","type":"hadith","num":1767,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"“أربعون خصلة أعلاها منيحة العنز ما من عامل يعمل بخصلة منها رجاء ثوابها وتصديق موعودها إلا أدخله الله تعالى بها الجنة” ‏(‏‏(‏رواه البخاري‏.‏ وقد سبق بيان هذا الحديث فى باب بيان كثرة طرق الخير‏)‏‏)‏‏.‏"},{"id":"riyad:1768","bookId":"riyad","type":"hadith","num":1768,"kitab":"كتاب المقدمات","isnad":"وعن أبي أمامة صدى بن عجلان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ “يا ابن آدم إنك أن تبذل الفضل خير لك، وأن تمسكه شر لك، ولا تلام على كفاف، وابدأ يمن تعول واليد العليا خير من اليد السفلى‏","matn":"\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1769","bookId":"riyad","type":"hadith","num":1769,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ ما سئل رسول الله صلى الله عليه وسلم على الإسلام شيئاً إلا أعطاه، ولقد جاءه رجل، فأعطاه غنماً بين جبلين فرجع إلى قومه فقال‏:‏ يا قوم أسلموا، فإن محمداً يعطى من لا يخشى الفقر، وإن كان الرجل ليسلم ما يريد إلا الدنيا، فما يلبث إلا يسيراً حتى يكون الإسلام أحب إليه من الدنيا وما عليها”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1770","bookId":"riyad","type":"hadith","num":1770,"kitab":"كتاب المقدمات","isnad":"وعن عمر رضي الله عنه قال‏:‏ قسم رسول الله صلى الله عليه وسلم قسماً، فقلت‏:‏ يا رسول الله لغير هؤلاء كانوا أحق به منهم‏؟‏ فقال‏:‏ ‏","matn":"\"‏إنهم خيروني أن يسألوني بالفحش فأعطيهم، أو يبخلوني، ولست بباخل‏\"‏ ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1771","bookId":"riyad","type":"hadith","num":1771,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن جبير بن مطعم رضي الله عنه أنه قال‏:‏ بينما هو يسير مع النبي صلى الله عليه وسلم مقفله من حنين، فعلقه الأعراب يسألونه، حتى اضطروه إلى سمرة، فخطفت رداءه، فوقف النبي صلى الله عليه وسلم فقال‏:‏ “أعطونى ردائى، فلو كان لى عدد هذه العضاة نعماً، لقسمته بينكم، ثم لا تجدونى بخيلاً ولا كذاباً ولا جباناً ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1772","bookId":"riyad","type":"hadith","num":1772,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “ما نقصت صدقة من مال، وما زاد الله عبداً بعفو إلا عزاً، وما تواضع أحد لله إلا رفعه الله عز وجل” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1773","bookId":"riyad","type":"hadith","num":1773,"kitab":"كتاب المقدمات","isnad":"وعن أبي كبشة عمرو بن سعد الأنمارى رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ ‏","matn":"\"‏ثلاثة أقسم عليهن وأحدثكم حديثاً فاحفظوه‏:‏ ما نقص مال عبد من صدقة،ولا ظلم عبد مظلمة صبر عليها إلا زاده الله عزاً، ولا فتح عبد باب مسألة إلا فتح الله عليه باب فقر، أو كلمة نحوها وأحدثكم حديثاً فاحفظوه قال‏:‏ إنما الدنيا لأربعة نفر‏:‏ عبد رزقه الله مالاً وعلماً، فهو يتقى فيه ربه، ويصل فيه رحمه، ويعلم لله فيه حقاً فهذا بأفضل المنازل‏.‏ وعبد رزقه الله علماً، ولم يرزقه مالاً فهو صادق النية يقول‏:‏ لو أن لى مالاً لعملت بعمل فلان، فهو بنيته فأجرهما سواء‏.‏ وعبد رزقه الله مالاً، ولم يرزقه علماً، فهو يخبط فى ماله بغير علم، لا يتقى فيه ربه ولا يصل فيه رحمه، ولا يعلم لله فيه حقاً، فهذا بأخبث المنازل‏.‏ وعبد لم يرزقه الله مالاً ولا علماً، فهو يقول‏:‏ لو أن لى مالاً لعملت فيه بعمل فلان، فهو بنيته، فوزرهما سواء” ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1774","bookId":"riyad","type":"hadith","num":1774,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها أنهم ذبحوا شاة، فقال النبي صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏ما بقى منها‏؟‏‏\"‏ قالت‏:‏ ما بقى منها إلا كتفها، قال‏:‏ “بقى كلها غير كتفها” ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1775","bookId":"riyad","type":"hadith","num":1775,"kitab":"كتاب المقدمات","isnad":"وعن أسماء بنت أبي بكر الصديق رضي الله عنهما قالت‏:‏ قال لى رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏لا توكى فيوكى عليك‏\"‏‏.‏ (‏‏(‏متفق عليه‏)‏‏)‏‏."},{"id":"riyad:1776","bookId":"riyad","type":"hadith","num":1776,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول‏:‏ “مثل البخيل والمنفق، كمثل رجلين عليهما جنتان من حديد من ثديهما إلى ترا قيهما، فأما المنفق، فلا ينفق إلا سبغت، أو وفرت على جلده حتى تخفى بنانه، وتعفو أثره، وأما البخيل، فلا يريد أن ينفق شيئاً إلا لزقت كل حلقةْ مكانها، فهو يوسعها فلا تتسع” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ و”الجنة” الدرع، ومعناه‏:‏ أن المنفق كلما أنفق سبغت، وطالت حتى تجر وارءه، وتخفى رجليه وأثر مشيه وخطواته‏.‏"},{"id":"riyad:1777","bookId":"riyad","type":"hadith","num":1777,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏","matn":"\"‏من تصدق بعدل تمرة من كسب طيب، ولا يقبل إلا الطيب، فإن الله يقبلها بيمينه، ثم يربيها لصاحبها كما يربى أحدكم فلوه حتى تكون مثل الجبل ‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ “الفلو” بفتح الفاء وضم اللام وتشديد الواو، ويقال أيضاً‏:‏ بكسر الفاء وإسكان اللام وتخفيف الواو‏:‏ وهو المهر ‏.‏"},{"id":"riyad:1778","bookId":"riyad","type":"hadith","num":1778,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ “بينما رجل يمشى بفلاة من الأرض، فسمع صوتاً فى سحابة‏:‏ إسق حديقة فلان، فتنحى ذلك السحاب فأفرغ ماءه فى حرة، فإذا شرجة من تلك الشراح قد استوعبت ذلك الماء كله، فتتبع الماء، فإذا رجل قائم فى حديقته يحول الماء بمسحاته، فقال له‏:‏ يا عبد الله ما اسمك ، قال‏:‏ فلان للاسم الذى سمع فى السحابة، فقال له‏:‏ يا عبد الله لم تسألني عن اسمي ‏؟‏ فقال‏:‏ إنى سمعت صوتاً فى السحاب الذى هذا ماؤه يقول‏:‏ اسق حديقة فلان لإسمك، فما تصنع فيها‏؟‏ فقال‏:‏ أما إذا قلت هذا فإنى أنظر إلى ما يخرج منها، فأتصدق بثلثه، وآكل أنا وعيالى ثلثاً، وأرد فيها ثلثه ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ “الحرة” الأرض الملبسة حجارة سوداء‏.‏ “والشرجة” بفتح الشين المعجمة وإسكان الراء وبالجيم‏:‏ هى مسيل الماء‏.‏"},{"id":"riyad:1779","bookId":"riyad","type":"hadith","num":1779,"kitab":"كتاب المقدمات","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ اتقوا الظلم فإن الظلم ظلمات يوم القيامة واتقوا الشح فإن الشح أهلك من كان قبلكم حملهم على أن سفكوا دماءهم واستحلوا محارمهم” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1780","bookId":"riyad","type":"hadith","num":1780,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ جاء رجل إلى النبي صلى الله عليه وسلم فقال‏:‏ إنى مجهود، فأرسل إلى بعض نسائه، فقالت‏:‏ والذى بعثك بالحق ما عندى إلا ماء، ثم أرسل إلى أخرى، فقالت مثل ذلك، حتى قلن كلهن مثل ذلك‏:‏ لا والذى بعثك بالحق ما عندى إلا ماء‏.‏ فقال النبي صلى الله عليه وسلم","matn":"“ من يضيفه هذا الليلة‏؟‏” فقال رجل من الأنصار‏:‏ أنا يا رسول الله، فانطلق به إلى رحله ، فقال لامرأته‏:‏ أكرمي ضيف رسول الله صلى الله عليه وسلم وفى رواية قال لامرأته ‏:‏ هل عندك شئ‏؟‏ قالت‏:‏ لا، إلا قوت صبيانى‏.‏ قال‏:‏ فعلليهن بشئ‏.‏وإذا أرادوا العشاء فنوميهم‏.‏ وإذا دخل ضيفنا فأطفئ السراج وأريه أنا نأكل، فقعدوا وأكل الضيف وبات طاويين، فلما أصبح ، غدا على النبي صلى الله عليه وسلم فقال‏:‏ “لقد عجب الله من صنيعكما بضيفكما الليلة” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1781","bookId":"riyad","type":"hadith","num":1781,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏ طعام الاثنين كافي الثلاثة، وطعام الثلاثة كافي الأربعة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ وفى رواية لمسلم عن جابر رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏:‏ طعام الواحد يكفي الاثنين وطعام الاثنين يكفي الأربعة، وطعام الأربعة يكفي الثمانية‏.‏"},{"id":"riyad:1782","bookId":"riyad","type":"hadith","num":1782,"kitab":"كتاب المقدمات","isnad":"عن أبي سعيد الخدرى قال‏:‏ بينما نحن فى سفر مع النبي صلى الله عليه وسلم إذ جاء رجل على راحلة له ، فجعل يصرف بصره يمينا وشمالاً فقال رسول الله صلى الله عليه وسلم","matn":"‏:‏” من كان معه فضل ظهر فليعد به على من لا ظهر له، ومن كان له فضل من زاد فليعد به على من لا زاد له” فذكر من أصناف المال ما ذكر حتى رأينا أنه لا حق لأحد منا فى فضل‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1783","bookId":"riyad","type":"hadith","num":1783,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سهل بن سعد رضي الله عنه، أن امرأة جاءت إلى رسول الله صلى الله عليه وسلم ببردة منسوجة فقالت‏:‏ نسجتها لأكسوكها، فأخذها النبي صلى الله عليه وسلم محتاجاً إليها ، فخرج إلينا وإنها إزاره، فقال فلان، اكسونيها ما أحسنها‏!‏ فقال‏:‏” نعم” فجلس النبي صلى الله عليه وسلم فى المجلس ثم رجع فطواها ثم أرسل به إليه‏:‏ فقال له القوم‏:‏ ما أحسنت‏!‏ لبسها النبي صلى الله عليه وسلم محتاجاً إليها ثم سألته وعلمت أنه لا يرد سائلاً ، فقال‏:‏ إنى والله ما سألته لألبسها وإنما سألته لتكون كفني، قال سهل‏:‏ فكانت كفنه‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:1784","bookId":"riyad","type":"hadith","num":1784,"kitab":"كتاب المقدمات","isnad":"وعن أبي موسى رضي الله عنه قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ إن الأشعريين إذا أرملوا فى الغزو، أو قل طعام عيالهم بالمدينة جمعوا ما كان عندهم فى ثوب واحد، اقتسموه بينهم فى إناء واحد بالسوية فهم منى وأنا منهم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ “أرملوا” فرغ زادهم أو قارب الفراغ‏.‏"},{"id":"riyad:1785","bookId":"riyad","type":"hadith","num":1785,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم أتي بشراب، فشرب منه وعن يمينه غلام، وعن يساره الأشياخ، فقال للغلام‏:‏” أتأذن لى أن أعطي هؤلاء‏؟‏” فقال الغلام لا والله يا رسول الله، لا أؤثر منك أحداً، فتله رسول الله صلى الله عليه وسلم فى يده ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏ “تله” بالتاء المثناه، فوق ، أى وضعه، وهذا الغلام هو ابن عباس رضي الله عنهما‏.‏"},{"id":"riyad:1786","bookId":"riyad","type":"hadith","num":1786,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه ، عن النبي صلى الله عليه وسلم قال‏","matn":"‏ “بينما أيوب عليه السلام يغتسل عريانا، فخر عليه جراد من ذهب، فجعل أيوب يحثي فى ثوبه فناداه ربه عز وجل يا أيوب ألم أكن أغنيتك عما ترى‏؟‏‏!‏ قال‏:‏بلى وعزتك، ولكن لا غنى بى عن بركتك، ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1787","bookId":"riyad","type":"hadith","num":1787,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ “ لا حسد إلا فى اثنتين ‏:‏ رجل آتاه الله مالاً ، فسلطه على هلكته فى الحق، ورجل آتاه الله حكمة فهو يقضي بها ويعلمها” ‏(‏‏(‏متفق عليه وتقدم شرحه قريباً‏)‏‏)‏ ‏.‏"},{"id":"riyad:1788","bookId":"riyad","type":"hadith","num":1788,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما‏:‏ عن النبي صلى الله عليه وسلم قال ‏:‏‏","matn":"\"‏ لا حسد إلى فى اثنتين‏:‏ رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالاً فهو ينفقه آناء الليل وآناء النهار” ‏(‏‏(‏متفق عليه‏)‏‏)‏ “الآناء”:الساعات .‏"},{"id":"riyad:1789","bookId":"riyad","type":"hadith","num":1789,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن فقراء المهاجرين أتوا رسول الله صلى الله عليه وسلم فقالوا‏:‏ ‏","matn":"\"‏ذهب أهل الدثور بالدرجات العلى والنعيم المقيم، فقال‏:‏ ‏\"‏وما ذاك‏؟‏” فقالو”‏:‏يصلون كما نصلى، ويصومون كما نصوم ويتصدقون ولانتصدق، ويعتقون ولا نعتق فقال‏:‏ رسول الله صلى الله عليه وسلم ‏:‏” أفلا أعلمكم شيئا تدركون به من سبقكم، وتسبقون به من بعدكم ، ولا يكون أحد أفضل منكم إلا من صنع مثل ما صنعتم‏؟‏” قالوا‏:‏ بلى يا رسول الله ، قال‏:‏ تسبحون ، وتكبرون، وتحمدون ، دبر كل صلاة ثلاثاً وثلاثين مرة” فرجع فقراء المهاجرين إلى رسول الله صلى الله عليه وسلم ، فقالو‏:‏ سمع إخواننا أهل الأموال بما فعلنا، ففعلوا مثله‏؟‏ فقال رسول الله صلى الله عليه وسلم “ذلك فضل الله يؤتيه من يشاء” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ، وهذا لفظ ‏رواية مسلم‏.‏"},{"id":"riyad:1790","bookId":"riyad","type":"hadith","num":1790,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ أخذ رسول الله صلى الله عليه وسلم بمنكبي فقال‏:‏ ‏","matn":"\"‏كن فى الدنيا كأنك غريب أو عابر سبيل‏\"‏‏.‏ وكان ابن عمر رضي الله عنهما يقول‏:‏ إذا أمسيت، فلا تنتظر الصباح، وإذا أصبحت، فلا تنتظر المساء، وخذ من صحتك لمرضك، ومن حياتك لموتك “ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1791","bookId":"riyad","type":"hadith","num":1791,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “ ما حق امرئ مسلم ، له شئ يوصي فيه ، يبيت ليلتين إلا ووصيته مكتوبة عنده” ‏(‏‏(‏متفق عليه‏)‏‏)‏ هذا لفظ البخاري‏.‏ وفى رواية لمسلم” يبيت ثلاث ليال‏:‏ قال ابن عمر‏:‏ ما مرت على ليلة منذ سمعت رسول الله صلى الله عليه وسلم قال ذلك إلا وعندي وصيتي‏.‏"},{"id":"riyad:1792","bookId":"riyad","type":"hadith","num":1792,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ خط النبي صلى الله عليه وسلم خطوطا فقال‏:‏ ‏","matn":"\"‏هذا الإنسان، وهذا أجله، فبينما هو كذلك إذ جاء الخط الأقرب” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1793","bookId":"riyad","type":"hadith","num":1793,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن مسعود رضي الله عنه قال‏:‏ خط النبي صلى الله عليه وسلم خطا مربعا، وخط خطاً فى الوسط خارجاً منه، وخط خططاً صغاراً إلى هذا الذى فى الوسط من جانبه الذى فى الوسط، فقال‏:‏ “هذا الإنسان، وهذا أجله محيطا به -أو قد أحاط به- وهذا الذى هو خارج أمله، وهذه الخطط الصغار الأعراض فإن أخطأه هذا ، نهشه هذا، وإن أخطأه هذا نهشه هذا” ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:1794","bookId":"riyad","type":"hadith","num":1794,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم‏:‏ قال‏:‏ “بادروا بالأعمال سبعاً، هل تنتظرون إلا فقراً منسياً، أو غنى مطغياً، أو مرضاً مفسداً، أو هرماً مفنداً، أو موتاً مجهزاً، أو الدجال، فشر غائب ينتظر، أو الساعة، فالساعة أدهى وأمر‏؟‏‏!‏” ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1795","bookId":"riyad","type":"hadith","num":1795,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “أكثروا ذكر هاذم اللذات” ‏(‏‏(‏يعنى الموت‏)‏‏)‏ ‏(‏‏(‏رواه الترمذى وقال‏:‏ حدث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1796","bookId":"riyad","type":"hadith","num":1796,"kitab":"كتاب المقدمات","isnad":"وعن أبي بن كعب رضي الله عنه‏:‏ كان رسول الله صلى الله عليه وسلم‏:‏ إذا ذهب ثلث الليل، قام فقال‏:‏ ‏","matn":"\"‏يا أيها الناس اذكروا الله، جاءت الراجفة، تتبعها الرادفة، جاء الموت بما فيه، جاء الموت بما فيه” قلت‏:‏ يا رسول الله إنى أكثر الصلاة عليك، فكم أجعل لك من صلاتى‏؟‏ قال‏:‏ “ما شئت” قلت‏:‏ الربع‏؟‏ قال‏:‏ “ما شئت، فإن زذت فهو لك” قلت‏:‏ فالنصف‏؟‏ قال‏:‏ ما شئت فإن زذت فهو لك قلت ” فالثلثين‏؟‏ قال‏:‏ ما شئت فإن زدت فهو خير لك” قلت‏:‏ أجعل لك صلاتى كلها‏؟‏ قال‏:‏ “إذا تكفى همك، ويغفر لك ذنبك” ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1797","bookId":"riyad","type":"hadith","num":1797,"kitab":"كتاب المقدمات","isnad":"عن بريدة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم ‏","matn":"\"‏كنت نهيتكم عن زيارة القبور فزوروها‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية ‏\"‏فمن أراد أن يزور القبور فليزر؛ فإنها تذكرنا الآخرة ‏\"‏"},{"id":"riyad:1798","bookId":"riyad","type":"hadith","num":1798,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم كلما كان ليلتها من رسول الله صلى الله عليه وسلم يخرج من آخر الليل إلى البقيع، فيقول‏:‏ السلام عليكم دار قوم مؤمنين، وأتاكم ما توعدون، غداً مؤجلون وإنا إن شاء الله بكم لاحقون، اللهم اغفر لأهل بقيع الغرقد” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1799","bookId":"riyad","type":"hadith","num":1799,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن بريدة رضي الله عنه قال‏:‏ كان النبي صلى الله عليه وسلم يعلمهم إذا خرجوا إلى المقابر أن يقول قائلهم‏:‏ “السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم للاحقون، أسأل الله لنا ولكم العافية” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1800","bookId":"riyad","type":"hadith","num":1800,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن عباس رضي الله عنهما، قال مر رسول الله صلى الله عليه وسلم بقبور بالمدينة فأقبل عليهم بوجهه فقال‏:‏ “السلام عليكم يا أهل القبور، يغفر الله لنا ولكم أنتم سلفنا ونحن بالأثر” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1801","bookId":"riyad","type":"hadith","num":1801,"kitab":"كتاب المقدمات","isnad":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “لا يتمن أحدكم الموت إما محسناً فلعله يزداد، وإما مسيئاً فلعله يستعتب” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏وهذا لفظ البخاري وفى رواية لمسلم عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال‏:‏ “لا يتمن أحدكم الموت، ولا يدع به من قبل أن يأتيه، إنه إذا مات انقطع عمله، وإنه لا يزيد المؤمن عمره إلا خيراً”‏.‏"},{"id":"riyad:1802","bookId":"riyad","type":"hadith","num":1802,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “لا يتمنين أحدكم الموت لضر أصابه فإن كان لابد فاعلاً، فليقل‏:‏ اللهم أحينى ما كانت الحياة خيراً لى، وتوفنى إذا كانت الوفاة خيراً لى” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1803","bookId":"riyad","type":"hadith","num":1803,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن قيس بن أبي حازم قال‏:‏ دخلنا على خباب بن الأرت رضي الله عنه نعوده وقد اكتوى سبع كيات فقال‏:‏ إن أصحابنا الذين سلفوا مضوا، ولم تنقصهم الدنيا، وإنا أصبنا ما لا نجد له موضعاً إلا التراب ولولا أن النبي صلى الله عليه وسلم نهاناً أن ندعوا بالموت لدعوت به، ثم أتيناه مرة أخرى وهو يبنى حائطاً له فقال‏:‏ إن المسلم ليؤجر فى كل شئ ينفقه إلا فى شئ يجعله فى هذا التراب‏.‏ ‏(‏‏(‏متفق عليه وهذا لفظ رواية البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1804","bookId":"riyad","type":"hadith","num":1804,"kitab":"كتاب المقدمات","isnad":"وعن النعمان بن بشير رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “إن الحلال بين، وإن الحرام بين، وبينهما مشتبهات لا يعلمهن كثير من الناس، فمن اتقى الشبهات، استبرأ لدينه وعرضه، ومن وقع فى الشبهات، وقع فى الحرام، كالراعى يرعى حول الحمى يوشك أن يرتع فيه ألا وإن لكل ملك حمى، ألا وإن حمى الله محارمه، ألا وإن فى الجسد مضغة إذا صلحت صلح الجسد كله، وإذا فسدت فسد الجسد كله‏:‏ ألا وهى القلب” ‏(‏‏(‏متفق عليه‏.‏ وروياه من طرق بألفاظ متقاربة‏)‏‏)‏"},{"id":"riyad:1805","bookId":"riyad","type":"hadith","num":1805,"kitab":"كتاب المقدمات","isnad":"","matn":"عن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، وجد تمرة فىالطريق فقال‏:‏ “لولا أنى أخاف أن تكون من الصدقة لأكلتها” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1806","bookId":"riyad","type":"hadith","num":1806,"kitab":"كتاب المقدمات","isnad":"وعن النواس بن سمعان رضي الله عنه عن النبي صلى الله عليه وسلم قال‏","matn":"‏ البر حسن الخلق، والإثم ما حاك فى نفسك، وكرهت أن يطلع عليه الناس” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1807","bookId":"riyad","type":"hadith","num":1807,"kitab":"كتاب المقدمات","isnad":"وعن وابصة بن معبد رضي الله عنه قال‏:‏ أتيت رسول الله صلى الله عليه وسلم فقال‏:‏ “جئت تسأل عن البر‏؟‏” قلت نعم، فقال‏:‏ ‏","matn":"\"‏استفت قلبك البر ما اطمأنت إليه النفس، واطمأن إليه القلب، والإثم ما حاك فى النفس وتردد فىالصدر، وإن أفتاك الناس وأفتوك” ‏(‏‏(‏حديث حسن، رواه أحمد والدارمي فى مسنديهما‏)‏‏)‏‏.‏"},{"id":"riyad:1808","bookId":"riyad","type":"hadith","num":1808,"kitab":"كتاب المقدمات","isnad":"وعن أبي سروعة -كسر السين المهملة ونصبها- عقبة بن الحارث رضي الله عنه أنه تزوج ابنة لأبي إهاب بن عزيز، فأتته امرأة فقالت‏:‏ إنى قد أرضعت عقبة والتى قد تزوج بها، فقال لها عقبة‏:‏ ما أعلم أنك أرضعتني ولا أخبرتني فركب إلى رسول الله صلى الله عليه وسلم بالمدينة فسأله فقال رسول الله صلى الله عليه وسلم‏","matn":"‏ “كيف، وقد قيل‏؟‏‏!‏” ففارقها عقبة ونكحت زوجاً غيره”‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1809","bookId":"riyad","type":"hadith","num":1809,"kitab":"كتاب المقدمات","isnad":"وعن الحسن بن على رضي الله عنهما، قال‏:‏ حفظت من رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏دع ما يريبك إلى ما لا يريبك‏\"‏ ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1810","bookId":"riyad","type":"hadith","num":1810,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة رضي الله عنها، قالت‏:‏ كان لأبي بكر الصديق رضي الله عنه غلام يخرج له الخراج وكان أبو بكر يأكل من خراجه فجاء يوماً بشئ، فأكل منه أبو بكر، فقال له الغلام‏:‏ تدرى ما هذا‏؟‏ فقال أبو بكر‏:‏ ما هو‏؟‏ قال‏:‏ كنت تكهنت لإنسان فى الجاهلية وما أحسن الكهانة إلا أني خدعته فلقيني، فأعطاني بذلك هذا الذى أكلت منه، فأدخل أبو بكر يده فقاء كل شئ فى بطنه” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1811","bookId":"riyad","type":"hadith","num":1811,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن نافع أن عمر بن الخطاب رضي الله عنه كان فرض للمهاجرين الأولين أربعة آلاف وفرض لابنه ثلاثة آلاف وخمسمائة، فقيل له‏:‏ هو من المهاجرين فلم نقصته‏؟‏ فقال‏:‏ إنما هاجر به أبوه، يقول‏:‏ ليس هو كمن هاجر بنفسه” ‏(‏‏(‏رواه البخاري‏)‏‏)‏"},{"id":"riyad:1812","bookId":"riyad","type":"hadith","num":1812,"kitab":"كتاب المقدمات","isnad":"وعن عطية بن عروة السعدى الصحابي رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏لا يبلغ العبد أن يكون من المتقين حتى يدع مالا بأس به حذرا لما به بأس‏\"‏‏.‏ ‏(‏‏(‏رواه الترمذى وقال‏:‏ حديث حسن‏)‏‏)‏‏."},{"id":"riyad:1813","bookId":"riyad","type":"hadith","num":1813,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سعد بن أبي وقاص رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم‏:‏ يقول‏:‏ “إن الله يحب العبد التقي الغني الخفي” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ والمراد‏:‏ بـ “الغني” غني النفس، كما سبق فى الحديث الصحيح‏.‏"},{"id":"riyad:1814","bookId":"riyad","type":"hadith","num":1814,"kitab":"كتاب المقدمات","isnad":"وعن أبي سعيد الخدرى رضي الله عنه قال‏:‏ قال رجل‏:‏ أى الناس أفضل يا رسول الله‏؟‏ قال‏:‏ ‏","matn":"\"‏مؤمن مجاهد بنفسه وماله فى سبيل الله‏\"‏ قال‏:‏ ثم من‏؟‏ قال‏:‏ ‏\"‏ رجل معتزل فى شعب من الشعاب يعبد ربه‏\"‏ وفى رواية‏:‏ ‏\"‏يتقي الله، ويدع الناس من شره‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1815","bookId":"riyad","type":"hadith","num":1815,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏يوشك أن يكون خير مال المسلم غنم يتتبع بها شعف الجبال، ومواقع القطر، يفر بدينه من الفتن‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏ وشعف الجبال ‏:‏أعلاها"},{"id":"riyad:1816","bookId":"riyad","type":"hadith","num":1816,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ما بعث الله نبياً إلا رعى الغنم” فقال أصحابه‏:‏ أنت‏؟‏ قال‏:‏ كنت أرعاها على قراريط لأهل مكة”‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1817","bookId":"riyad","type":"hadith","num":1817,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه عن رسول الله صلى الله عليه وسلم أنه قال‏:‏ “من خير معاش الناس رجل ممسك عنان فرسه فى سبيل الله، يطير على متنه، كلما سمع هيعه أو فزعة، طار عليه يبتغى القتل، أو الموت مظانه، أو رجل فى غنيمة فى رأس شعفة من هذه الشعف، أو بطن واد من هذه الأودية يقيم الصلاة، ويؤتى الزكاة، ويعبد ربه حتى يأتيه اليقين، ليس من الناس إلا فى خير” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1818","bookId":"riyad","type":"hadith","num":1818,"kitab":"كتاب المقدمات","isnad":"وعن عياض بن حمار رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “إن الله أوحى إلي أن تواضعوا حتى لا يفخر أحد على أحد، ولا يبغي أحد على أحد” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1819","bookId":"riyad","type":"hadith","num":1819,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “ما نقصت صدقة من مال، و ما زادالله عبداً بعفو إلا عزاً، وما تواضع أحد لله إلا رفعه الله” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1820","bookId":"riyad","type":"hadith","num":1820,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه أنه مر على صبيان فسلم عليهم وقال‏:‏ كان النبي صلى الله عليه وسلم يفعله‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1821","bookId":"riyad","type":"hadith","num":1821,"kitab":"كتاب المقدمات","isnad":"","matn":"عنه قال‏:‏ إن كانت الأمة من إماء المدينة لتأخذ بيد النبي صلى الله عليه وسلم، فتنطلق به حيث شاءت‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1822","bookId":"riyad","type":"hadith","num":1822,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن الأسود بن يزيد قال‏:‏ سئلت عائشة رضي الله عنها‏:‏ ما كان النبي صلى الله عليه وسلم يصنع فى بيته‏؟‏ قالت‏:‏ كان يكون فى مهنة أهله -يعنى‏:‏ خدمة أهله- فإذا حضرت الصلاة، خرج إلى الصلاة” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1823","bookId":"riyad","type":"hadith","num":1823,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبي رفاعة تميم بن أسيد رضي الله عنه قال‏:‏ انتهيت إلى رسول الله صلى الله عليه وسلم وهو يخطب، فقلت‏:‏ يا رسول الله رجل غريب جاء يسأل عن دينه لا يدرى ما دينه‏؟‏ فأقبل علي رسول الله صلى الله عليه وسلم، وترك خطبته حتى انتهى إلى فأتى بكرسي، فقعد عليه وجعل يعلمني مما علمه الله ثم أتى خطبته فأتم آخرها”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1824","bookId":"riyad","type":"hadith","num":1824,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم كان إذا أكل طعاماً لعق أصابعه الثلاث قال‏:‏ وقال‏:‏ “إذا سقطت لقمة أحدكم، فليمط عنها الأذى، وليأكلها، ولا يدعها للشيطان” وأمر أن تسلت القصعة قال‏:‏ فإنكم لا تدرون فى أى طعامكم البركة” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1825","bookId":"riyad","type":"hadith","num":1825,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال‏","matn":"‏ “ما بعث الله نبياً إلا رعى الغنم” قال أصحابه‏:‏ وأنت‏؟‏ فقال‏:‏ نعم كنت أرعاها على قراريط لأهل مكة” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1826","bookId":"riyad","type":"hadith","num":1826,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه عن النبي صلى الله عليه وسلم قال‏:‏ لو دعيت إلى كراع أو ذراع لأجبت ولو أهدى إلى ذراع أو كراع لقبلت”‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1827","bookId":"riyad","type":"hadith","num":1827,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ كانت ناقة رسول الله صلى الله عليه وسلم‏:‏ العضباء لا تسبق، أو لا تكاد تسبق فجاء أعرابي على قعود له، فسبقها، فشق ذلك على المسلمين حتى عرفه، النبي صلى الله عليه وسلم فقال‏:‏ “حق على الله أن لا يرتفع شئ من الدنيا إلا وضعه” ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏"},{"id":"riyad:1828","bookId":"riyad","type":"hadith","num":1828,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مسعود رضي الله عنه عن النبى صلى الله عليه وسلم قال‏","matn":"‏ “لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر” فقال رجل” إن الرجل يحب أن يكون ثوبه حسناً ونعله حسناً‏؟‏ قال‏:‏ “إن الله جميل يحب الجمال الكبر بطر الحق وغمط الناس” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1829","bookId":"riyad","type":"hadith","num":1829,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن سلمه بن الأكوع رضي الله عنه أن رجلاً أكل عند رسول الله صلى الله عليه وسلم بشماله، فقال‏:‏ “كل بيمينك” قال‏:‏ لا أستطيع‏!‏ قال‏:‏ “لا اتسطعت” ما منعه إلا الكبر‏.‏ قال‏:‏ فما رفعه إلى فيه”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1830","bookId":"riyad","type":"hadith","num":1830,"kitab":"كتاب المقدمات","isnad":"وعن حارثة بن وهب رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ ألا أخبركم بأهل النار‏؟‏‏:‏ كل عتل جواظ مستكبر” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ وتقدم شرحه في باب ضعفة المسلمين‏.‏"},{"id":"riyad:1831","bookId":"riyad","type":"hadith","num":1831,"kitab":"كتاب المقدمات","isnad":"وعن أبى سعيد رضي الله عنه، عن النبى صلى الله عليه وسلم قال‏","matn":"‏ “احتجت الجنة والنار، فقالت النار‏:‏ في الجبارون والمتكبرون، وقالت الجنة‏:‏ في ضعفاء الناس ومساكينهم‏.‏ فقضى الله بينهما‏:‏ إنك الجنة رحمتي، أرحم بك من أشاء، وإنك النار عذابي أعذب بك من أشاء ولكليكما علي ملؤها” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1832","bookId":"riyad","type":"hadith","num":1832,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “لا ينظر الله يوم القيامة إلى من جر إزاره بطراً” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1833","bookId":"riyad","type":"hadith","num":1833,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “ثلاثة لا يكلمهم الله يوم القيامة، ولايزكيهم، ولا ينظر إليهم ، ولهم عذاب أليم‏:‏ شيخ زان وملك كذاب، وعائل مستكبر” ‏(‏‏(‏رواه مسلم‏)‏‏)"},{"id":"riyad:1834","bookId":"riyad","type":"hadith","num":1834,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “قال الله عز وجل‏:‏ العز إزاري والكبرياء ردائي، فمن ينازعني في واحد منهما فقد عذبته” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1835","bookId":"riyad","type":"hadith","num":1835,"kitab":"كتاب المقدمات","isnad":"وعنه أن رسول الله صلى الله عليه وسلم قال‏:‏‏","matn":"\"‏بينما رجل يمشى في حلة تعجبه نفسه، مرجل رأسه، يختال في مشيته، إذ خسف الله به، فهو يتجلجل في الأرض إلى يوم القيامة” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1836","bookId":"riyad","type":"hadith","num":1836,"kitab":"كتاب المقدمات","isnad":"وعن سلمه بن الأكوع رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “لا يزال الرجل يذهب بنفسه حتى يكتب في الجبارين، فيصيبه ما أصابهم” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏.‏ ‏(‏‏(‏“يذهب بنفسه” أى‏:‏ يرتفع ويتكبر)‏‏)‏‏.‏"},{"id":"riyad:1837","bookId":"riyad","type":"hadith","num":1837,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ كان رسول الله صلى الله عليه وسلم أحسن الناس خلقاً ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1838","bookId":"riyad","type":"hadith","num":1838,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه قال‏:‏ ما مسست ديباجاً ولاحريراً ألين من كف رسول الله صلى الله عليه وسلم، ولا شممت رائحة قط أطيب من رائحة رسول الله صلى الله عليه وسلم ولقد خدمت رسول الله صلى الله عليه وسلم عشر سنين، فما قال لي قط ‏:‏أف، ولا قال لشئ فعلته‏:‏ لم فعلته‏؟‏ ولا لشئ لم أفعله‏:‏ ألا فعلت كذا‏؟‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1839","bookId":"riyad","type":"hadith","num":1839,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن الصعب بن جثامة رضي الله عنه قال‏:‏ أهديت رسول الله صلى الله عليه وسلم حماراً وحشياً فرده علي، فلما رأى ما في وجهي قال‏:‏ “إنا لم نرده عليك إلا لأنا حرم” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1840","bookId":"riyad","type":"hadith","num":1840,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن النواس بن سمعان رضي الله عنه قال‏:‏ سألت رسول الله صلى الله عليه وسلم عن البر والإثم فقال‏:‏ “البر حسن الخلق، والإثم‏:‏ ما حاك في نفسك وكرهت أن يطلع عليه الناس” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1841","bookId":"riyad","type":"hadith","num":1841,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ لم يكن رسول الله صلى الله عليه وسلم فاحشاً ولا متفحشاً‏.‏ وكان يقول‏:‏ “إن من خياركم أحسنكم أخلاقاً” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1842","bookId":"riyad","type":"hadith","num":1842,"kitab":"كتاب المقدمات","isnad":"وعن أبى الدرداء رضي الله عنه‏:‏ أن النبى صلى الله عليه وسلم قال‏","matn":"‏ “ما من شئ أثقل في ميزان المؤمن يوم القيامة من حسن الخلق، وإن الله يبغض الفاحش البذي” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏.‏"},{"id":"riyad:1843","bookId":"riyad","type":"hadith","num":1843,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبى هريرة رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم عن أكثر ما يدخل الناس الجنة‏؟‏ قال‏:‏ “تقوى الله وحسن الخلق” وسئل عن أكثر ما يدخل الناس النار، قال‏:‏ “الفم والفرج”‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1844","bookId":"riyad","type":"hadith","num":1844,"kitab":"كتاب المقدمات","isnad":"وعنه قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “أكمل المؤمنين إيماناً أحسنهم خلقاً وخياركم خياركم لنسائهم”‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1845","bookId":"riyad","type":"hadith","num":1845,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة رضي الله عنها، قالت‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ “ إن المؤمن ليدرك بحسن خلقه درجة الصائم القائم” ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏"},{"id":"riyad:1846","bookId":"riyad","type":"hadith","num":1846,"kitab":"كتاب المقدمات","isnad":"وعن أبى أمامه الباهلى رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “أنا زعيم ببيت في ربض الجنة لمن ترك المراء، وإن كان محقاً، وببيت في وسط الجنة لمن ترك الكذب، وإن كان مازحاً، وببيت في أعلى الجنة لمن حسن خلقه” ‏(‏‏(‏حديث صحيح رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏"},{"id":"riyad:1847","bookId":"riyad","type":"hadith","num":1847,"kitab":"كتاب المقدمات","isnad":"وعن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “إن من أحبكم إلي، وأقربكم منى مجلساً يوم القيامة أحاسنكم أخلاقاً، وإن أبغضكم إلي وأبعدكم مني يوم القيامة، الثرثارون والمتشدقون والمتفيهقون” قالوا‏:‏ يا رسول الله قد علمنا “الثرثارون والمتشدون” فما المتفيهقون‏؟‏ قال‏:‏ “المتكبرون” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ ‏","matn":"\"‏الثرثار‏\"‏‏:‏ هو كثير الكلام تكلفاً‏.‏ ‏\"‏والمتشدق‏\"‏‏:‏ المتطاول على الناس بكلامه، ويتكلم بملء فيه تصافحاً وتعظيماً لكلامه؛ “والمتفيهق” ‏:‏أصله من الفهق، وهو الامتلاء، وهو الذى يملأ فمه بالكلام، ويتوسع فيه ويغرب به تكبراً واتفاعاً، وإظهاراً للفضيلة على غيره‏.‏ وروى الترمذي عن عبد الله بن المبارك رحمه الله في تفسير حسن الخلق قال‏:‏ هو طلاقة الوجه، وبذل المعروف، وكف الأذى‏.‏"},{"id":"riyad:1848","bookId":"riyad","type":"hadith","num":1848,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"لأشج عبد القيس‏:‏ “إن فيك خصلتين يحبهما الله‏:‏ الحلم والأناة”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1849","bookId":"riyad","type":"hadith","num":1849,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “ إن الله رفيق يحب الرفق في الأمر كله” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1850","bookId":"riyad","type":"hadith","num":1850,"kitab":"كتاب المقدمات","isnad":"وعنها أن النبى صلى الله عليه وسلم قال‏:‏ ‏","matn":"\"‏ إن الله رفيق يحب الرفق، ويعطى على الرفق ما لا يعطى على العنف ومالا يعطى على ما سواه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1851","bookId":"riyad","type":"hadith","num":1851,"kitab":"كتاب المقدمات","isnad":"وعنها أن النبى صلى الله عليه وسلم قال‏","matn":"‏ “إن الرفق لا يكون في شئ إلا زانه، ولا ينزع من شئ إلا شانه” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1852","bookId":"riyad","type":"hadith","num":1852,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه قال‏:‏ بال أعرابى في المسجد فقام الناس إليه ليقعوا فيه، فقال النبى صلى الله عليه وسلم‏","matn":"‏ “دعوه وأريقوا على بوله سجلاً من ماء، أو ذنوباً من ماء، فإنما بعثتم ميسرين ولم تبعثوا معسرين” ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:1853","bookId":"riyad","type":"hadith","num":1853,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه عن النبى صلى الله عليه وسلم قال‏","matn":"‏ “يسروا ولا تعسروا وبشروا ولا تنفروا ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1854","bookId":"riyad","type":"hadith","num":1854,"kitab":"كتاب المقدمات","isnad":"وعن جرير بن عبد الله رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “من يحرم الرفق يحرم الخير كله” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1855","bookId":"riyad","type":"hadith","num":1855,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبى هريرة رضي الله عنه أن رجلاً قال للنبى صلى الله عليه وسلم‏:‏ أوصنى قال‏:‏ “لا تغضب” فردد مراراً، قال‏:‏ “لا تغضب”‏.‏ ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:1856","bookId":"riyad","type":"hadith","num":1856,"kitab":"كتاب المقدمات","isnad":"وعن أبى يعلى شداد بن أوس رضي الله عنه، عن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “إن الله كتب الإحسان على كل شئ، فإذا قتلتم فأحسنوا القتلة وإذا ذبحتم فأحسنوا الذبحة، وليحد أحدكم شفرته وليرح ذبيحته” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1857","bookId":"riyad","type":"hadith","num":1857,"kitab":"كتاب المقدمات","isnad":"","matn":"عن عائشة رضي الله عنها قالت‏:‏ ما خير رسول الله صلى الله عليه وسلم بين أمرين قط إلا أخذ أيسرهما، ما لم يكن إثماً، فإن كان إثماً، كان أبعد الناس منه، وما انتقم رسول الله صلى الله عليه وسلم لنفسه في شئ قط، إلا أن تنتهك حرمة الله، فينتقم لله تعالى‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1858","bookId":"riyad","type":"hadith","num":1858,"kitab":"كتاب المقدمات","isnad":"وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “ألا أخبركم بمن يحرم على النار -أو بمن تحرم عليه النار‏؟‏- تحرم على كل قريب هين لين سهل”‏.‏ ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏"},{"id":"riyad:1859","bookId":"riyad","type":"hadith","num":1859,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها أنها قالت للنبى صلى الله عليه وسلم‏:‏ هل أتى عليك يوم كان أشد من يوم أحد‏؟‏ قال‏:‏ “لقد لقيت من قومك، وكان أشد ما لقيته منهم يوم العقبة، إذ عرضت نفسي على ابن عبد ياليل بن عبد كلال فلم يجبنى إلى ما أردت، فانطلقت وأنا مهموم على وجهى، فلم أستفق إلا وأنا بقرن الثعالب، فرفعت رأسى، فإذا أنا بسحابة قد أظلتنى، فنظرت فإذا فيها جبريل عليه السلام، فنادانى فقال‏:‏ إن الله تعالى قد سمع قول قومك لك، وما ردوا عليك، وقد بعث إليك ملك الجبال لتأمره بما شئت فيهم فنادانى ملك الجبال، فسلم على ثم قال‏:‏ يا محمد إن الله قد سمع قول قومك لك، وأنا ملك الجبال، وقد بعثنى ربى إليك لتأمرنى بأمرك،فما شئت‏:‏ إن شئت أطبقت عليهم الأخشبين” فقال النبى صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏بل أرجو أن يخرج من أصلابهم من يعبد الله وحده لا يشرك به شيئاً‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1860","bookId":"riyad","type":"hadith","num":1860,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنها قالت‏:‏ ما ضرب رسول الله صلى الله عليه وسلم شيئاً قط بيده، ولا امرأة ولا خادماً، إلا أن يجاهد في سبيل الله، وما نيل منه شئ قط فينتقم من صاحبه، إلا أن ينتهك شئ من محارم الله تعالى، فينتقم لله تعالى‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1861","bookId":"riyad","type":"hadith","num":1861,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه قال‏:‏ كنت أمشى مع رسول الله صلى الله عليه وسلم، وعليه برد نجرانى غليظ الحاشية، فأدركه أعرابى، فجبذه بردائه جبذة شديدة، فنظرت إلى صفحة عاتق النبى صلى الله عليه وسلم، وقد أثرت بها حاشية البرد من شدة فضحك، ثم قال‏:‏ يا محمد مر لى من مال الله الذى عندك، فالتفت إليه فضحك ثم أمر له بعطاء‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1862","bookId":"riyad","type":"hadith","num":1862,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن ابن مسعود رضي الله عنه قال‏:‏ كأنى أنظر إلى رسول الله صلى الله عليه وسلم يحكى نبياً من الأنبياء، صلوات الله وسلامه عليهم، ضربه قومه فأدموه وهو يمسح الدم عن وجهه، ويقول‏:‏ “اللهم اغفر لقومى فإنهم لا يعملون” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1863","bookId":"riyad","type":"hadith","num":1863,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ ليس الشديد بالصرعة، إنما الشديد الذى يملك نفسه عند الغضب” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1864","bookId":"riyad","type":"hadith","num":1864,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبى هريرة رضي الله عنه أن رجلاً قال‏:‏ يا رسول الله إن لى قرابة أصلهم ويقطعونى، وأحسن إليهم ويسيئون إلى، وأحلم عنهم ويجهلون على‏!‏ فقال‏:‏ “لئن كنت كما قلت فكأنما تسفهم المل ولا يزال معك من الله تعالى ظهير عليهم ما دمت على ذلك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏ وقد سبق شرحه في “باب صلة الأرحام”‏.‏"},{"id":"riyad:1865","bookId":"riyad","type":"hadith","num":1865,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أبى مسعود عقبة بن عمرو البدرى رضي الله عنه قال‏:‏ جاء رجل إلى النبى صلى الله عليه وسلم، فقال‏:‏ إنى لأتأخر عن صلاة الصبح من أجل فلان مما يطيل بنا‏!‏ فما رأيت النبى صلى الله عليه وسلم غضب في موعظة قط أشد مما غضب يومئذ، فقال‏:‏ “يا أيها الناس‏:‏ إن منكم منفرين، فأيكم أم الناس فليوجز، فإن من ورائه الكبير والصغير وذا الحاجة” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1866","bookId":"riyad","type":"hadith","num":1866,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عائشة رضي الله عنها قالت‏:‏ قدم رسول الله صلى الله عليه وسلم من سفر وقد سترت سهوة لى بقرام فيه تماثيل، فلما رآه رسول الله صلى الله عليه وسلم هتكه وتلون وجهه وقال‏:‏ “يا عائشة‏:‏ أشد الناس عذابا عند الله يوم القيامة الذين يضاهون بخلق الله” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1867","bookId":"riyad","type":"hadith","num":1867,"kitab":"كتاب المقدمات","isnad":"وعنها أن قريشاً أهمهم شأن المرأة المخزومية التى سرقت فقالوا‏:‏ من يكلم فيها رسول الله صلى الله عليه وسلم‏؟‏ فقالوا‏:‏ من يجترئ عليه إلا أسامة بن زيد حب رسول الله صلى الله عليه وسلم‏؟‏ فكلمة أسامة، فقال رسول الله صلى الله عليه وسلم‏","matn":"‏ “أتشفع في حد من حدود الله تعالى‏؟‏‏!‏” ثم قام فاختطب ثم قال‏:‏ “إنما أهلك من قبلكم أنهم كانوا إذا سرق فيهم الشريف تركوه، وإذا سرق فيهم الضعيف أقاموا عليه الحد‏!‏ وايم الله، لو أن فاطمة بنت محمد سرقت لقطعت يدها” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1868","bookId":"riyad","type":"hadith","num":1868,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن أنس رضي الله عنه أن النبى صلى الله عليه وسلم رأى نخامة في القبلة، فشق ذلك عليه حتى رؤى في وجهه، فقام فحكه بيده فقال‏:‏ “إن أحدكم إذا قام في صلاته فإنه يناجى ربه، وإن ربه بينه وبين القبلة، فلا يبزقن أحدكم في القبلة، ولكن عن يساره، أو تحت قدمه” ثم أخذ طرف ردائه فبصق فيه، ثم رد بعضه على بعض فقال‏:‏ “أو يفعل هكذا” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏"},{"id":"riyad:1869","bookId":"riyad","type":"hadith","num":1869,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “كلكم راع، وكلكم مسئول عن رعيته‏:‏ الإمام راع ومسؤول عن رعيته، والرجل راع في أهله ومسؤول عن رعيته، والمرأة راعية في بيت زوجها ومسؤولة عن رعيتها، والخادم راع في مال سيده ومسؤول عن رعيته وكلكم راع ومسؤول عن رعيته” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1870","bookId":"riyad","type":"hadith","num":1870,"kitab":"كتاب المقدمات","isnad":"وعن أبى يعلى معقل بن يسار رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم‏:‏ يقول‏:‏ “ما من عبد يستر عليه الله رعية، يموت يوم يموت وهو غاش لرعيته، إلا حرم الله عليه الجنة” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏(‏‏(‏وفي رواية‏:‏ ‏","matn":"\"‏فلم يحطها بنصحه لم يجد رائحة الجنة‏\"‏‏)‏‏)‏ وفي رواية لمسلم‏:‏ ‏\"‏ما من أمير يلى أمور المسلمين، ثم لا يجهد لهم وينصح لهم، إلا لم يدخل معهم الجنة‏\"‏‏.‏"},{"id":"riyad:1871","bookId":"riyad","type":"hadith","num":1871,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول","matn":"في بيتى هذا‏:‏ “اللهم من ولى من أمر أمتى شيئاً فشق عليهم، فاشقق عليه ومن ولى من أمر أمتى شيئاً، فرفق بهم، فارفق به” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1872","bookId":"riyad","type":"hadith","num":1872,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏كانت بنو إسرائيل تسوسهم الأنبياء، كلما هلك نبى خلفه نبى، وإنه لا نبى بعدى وسيكون بعدى خلفاء فيكثرون” قالوا‏:‏ يا رسول الله فما تأمرنا‏؟‏ قال‏:‏ ‏\"‏أوفوا ببيعة الأول فالأول، ثم أعطوهم حقهم، واسألوا الله الذى لكم ، فإن الله سائلهم عما استرعاهم” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1873","bookId":"riyad","type":"hadith","num":1873,"kitab":"كتاب المقدمات","isnad":"وعن عائذ بن عمرو رضي الله عنه أنه دخل على عبيد الله بن زياد، فقال له‏:‏ أى بنى، إنى سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “إن شر الرعاء الحطمة” فإياك أن تكون منهم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1874","bookId":"riyad","type":"hadith","num":1874,"kitab":"كتاب المقدمات","isnad":"وعن أبى مريم الأزدى رضي الله عنه أنه قال لمعاوية رضي الله عنه سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “من ولاه الله شيئاً من أمور المسلمين، فاحتجب دون حاجتهم وخلتهم وفقرهم، احتجب الله دون حاجته وخلته وفقره يوم القيامة” فجعل معاوية رجلا على حوائج الناس‏.‏ ‏(‏‏(‏رواه أبو داود والترمذي‏)‏‏)‏‏.‏"},{"id":"riyad:1875","bookId":"riyad","type":"hadith","num":1875,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه، عن النبى صلى الله عليه وسلم قال‏","matn":"‏ “سبعة يظلهم الله في ظله يوم لا ظل إلا ظله‏:‏ إمام عادل، وشاب نشأ في عبادة الله تعالى، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا عليه وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال، فقال‏:‏ إنى أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خالياً ففاضت عيناه” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1876","bookId":"riyad","type":"hadith","num":1876,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏","matn":"\"‏إن المقسطين عند الله على منابر من نور‏:‏ الذين يعدلون في حمكهم وأهليهم وما ولوا‏\"‏ ‏(‏‏(‏رواه مسلم ‏)‏‏)‏‏.‏"},{"id":"riyad:1877","bookId":"riyad","type":"hadith","num":1877,"kitab":"كتاب المقدمات","isnad":"وعن عوف بن مالك رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “خياركم أئمتكم الذين تحبونهم ويحبونكم، وتصلون عليهم ويصلون عليكم، وشرار أئمتكم الذين تبغضونهم ويبغضونكم، وتلعنونهم ويلعنونهم‏!‏” قال‏:‏ قلنا يا رسول الله، أفلا ننابذه‏؟‏ قال‏:‏ لا، ما أقاموا فيكم الصلاة، لا ما أقاموا فيكم الصلاة” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1878","bookId":"riyad","type":"hadith","num":1878,"kitab":"كتاب المقدمات","isnad":"وعن عياض بن حمار رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “أهل الجنة ثلاثة‏:‏ ذو سلطان مقسط موفق، ورجل رحيم رفيق القلب لكل ذي قربى ومسلم، وعفيف متعفف ذو عيال”‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1879","bookId":"riyad","type":"hadith","num":1879,"kitab":"كتاب المقدمات","isnad":"وعن ابن عمر رضي الله عنهما عن النبى صلى الله عليه وسلم قال‏","matn":"‏ “على المرء المسلم السمع والطاعة فيما أحب وكره، إلا أن يؤمر بمعصية، فإذا أمر بمعصية فلا سمع ولا طاعة” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1880","bookId":"riyad","type":"hadith","num":1880,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه قال‏:‏ كنا إذا بايعنا رسول الله صلى الله عليه وسلم على السمع والطاعة يقول لنا‏:‏ “فيما استطعتم” ‏(‏‏(‏متفق عليه‏)‏‏)‏"},{"id":"riyad:1881","bookId":"riyad","type":"hadith","num":1881,"kitab":"كتاب المقدمات","isnad":"وعنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول","matn":"“من خلع يداً من طاعة لقي الله يوم القيامة ولا حجة له، ومن مات وليس في عنقه بيعة مات ميتة جاهلية” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ “ومن مات وهو مفارق للجماعة، فإنه يموت ميتة جاهلية” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له‏:‏ “ومن مات وهو مفارق للجماعة، فإنه يموت ميتة جاهلية”‏.‏"},{"id":"riyad:1882","bookId":"riyad","type":"hadith","num":1882,"kitab":"كتاب المقدمات","isnad":"وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"“اسمعوا وأطيعوا، وإن استعمل عليكم عبد حبشي، كأن رأسه زبيبة” ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:1883","bookId":"riyad","type":"hadith","num":1883,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"“عليك السمع والطاعة في عسرك ويسرك ومنشطك، ومكرهك وأثرة عليك” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1884","bookId":"riyad","type":"hadith","num":1884,"kitab":"كتاب المقدمات","isnad":"","matn":"وعن عبد الله بن عمرو رضي الله عنهما قال‏:‏ كنا مع رسول الله صلى الله عليه وسلم في سفر، فنزلنا منزلاً، فمنا من يصلح خباءه، ومنا من ينتضل، ومنا من هو في جشره، إذ نادى منادي رسول الله صلى الله عليه وسلم الصلاة جامعة‏.‏ فاجتمعنا إلى رسول الله صلى الله عليه وسلم فقال‏:‏ “إنه لم يكن نبي قبلي إلا كان حقاً عليه أن يدل أمته على خير ما يعلمه لهم، وينذرهم شر ما يعلمه لهم، وإن أمتكم هذه جعل عاقبتها في أولها، وسيصيب آخرها بلاء وأمور تنكرونها، وتجئ فتن يرقق بعضها بعضاً، وتجئ الفتنة فيقول المؤمن ‏:‏ هذه مهلكتي، ثم تنكشف؛ وتجئ الفتنة فيقول المؤمن‏:‏ هذه هذه، فمن أحب أن يزحزح عن النار، ويدخل الجنة، فلتأته منيته وهو يؤمن بالله واليوم الأخر، وليأت إلى الناس الذى يحب أن يؤتى إليه‏.‏ ومن بايع إماماً فأعطاه صفقة يده، وثمرة قلبه، فليطعه إن استطاع، فإن جاء آخر ينازعه، فاضربوا عنق الآخر” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏‏.‏ قوله‏:‏ “ينتضل” أى ‏:‏ يسابق بالرمي بالنبل والنشاب‏.‏ “والجشر” بفتح الجيم والشين المعجمة وبالراء‏:‏ وهى الدواب التى ترعى وتبيت مكانها‏.‏ وقوله‏:‏ “يرقق بعضها بعضاً” أى‏:‏ يصير بعضها بعضا رقيقاً، أى ‏:‏خفيفاً لعظم ما بعده، فالثانى يرقق الأول‏.‏ وقيل‏:‏ معناه، يشوق بعضها إلى بعض بتحسينها وتسويليها، وقيل‏:‏ يشبه بعضها بعضاً‏.‏"},{"id":"riyad:1885","bookId":"riyad","type":"hadith","num":1885,"kitab":"كتاب المقدمات","isnad":"وعن أبى هنيدة وائل بن حجر رضي الله عنه قال‏:‏ سأل سلمة بن يزيد الجعفي رسول الله صلى الله عليه وسلم ، فقال‏:‏ يا نبي الله، أرأيت إن قامت علينا امراء يسألونا حقهم، ويمنعونا حقنا، فما تأمرنا‏؟‏ فأعرض عنه، ثم سأله، فقال رسول الله صلى الله عليه وسلم","matn":"“اسمعوا وأطيعو؛ فإنما عليهما حملوا، وعليكم ماحملتم” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1886","bookId":"riyad","type":"hadith","num":1886,"kitab":"كتاب المقدمات","isnad":"وعن عبد الله بن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم","matn":"‏:‏ “إنها ستكون بعدى أثرة، وأمور تنكرونها‏!‏” قالوا‏:‏ يا رسول الله، كيف تأمر من أدرك منا ذلك‏؟‏ قال‏:‏ “تؤدون الحق الذى عليكم، وتسألون الله الذى لكم” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1887","bookId":"riyad","type":"hadith","num":1887,"kitab":"كتاب المقدمات","isnad":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “من أطاعني فقد أطاع الله، ومن عصاني فقد عصى الله، ومن يطع الأمير فقد أطاعني، ومن يعص الأمير فقد عصاني” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1888","bookId":"riyad","type":"hadith","num":1888,"kitab":"كتاب المقدمات","isnad":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “من كره من أميره شيئاً فليصبر، فإنه من خرج من السلطان شبراً مات ميتة جاهلية” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1889","bookId":"riyad","type":"hadith","num":1889,"kitab":"كتاب المقدمات","isnad":"وعن أبى بكرة رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم يقول‏","matn":"‏ “من أهان السلطان أهانه الله” ‏(‏‏(‏رواه الترمذي وقال‏:‏ حديث حسن‏)‏‏)‏‏.‏ وفي الباب أحاديث كثيرة في الصحيح ، وقد سبق بعضها في أبواب‏.‏"},{"id":"riyad:1890","bookId":"riyad","type":"hadith","num":1890,"kitab":"كتاب المقدمات","isnad":"وعن أبى سعيد عبد الرحمن بن سمرة رضي الله عنه ، قال‏:‏ قال رسول الله صلى الله عليه وسلم ، ‏","matn":"\"‏يا عبد الرحمن بن سمرة‏:‏ لا تسأل الإمارة، فإنك إن أعطيتها عن غير مسألة أعنت عليها، وإن أعطيتها عن مسألةٍ وكلت إليها، وإذا حلفت على يمين ، فرأيت غيرها خيراً منها، فأت الذى هو خير ، وكفر عن يمينك” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"},{"id":"riyad:1891","bookId":"riyad","type":"hadith","num":1891,"kitab":"كتاب المقدمات","isnad":"وعن أبى ذر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “ يا أبا ذر إني أراك ضعيفاً، وإنى أحبُّ لك ما أحب لنفسي، لا تأمرن على اثنين ولا تولين مال يتيم” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1892","bookId":"riyad","type":"hadith","num":1892,"kitab":"كتاب المقدمات","isnad":"","matn":"وعنه قال‏:‏ قلت يا رسول الله ألا تستعملني‏؟‏ فضرب بيده على منكبي ثم قال‏:‏ “يا أبا ذر إنك ضعيف، وإنها أمانة، وإنها يوم القيامة خزي وندامة، إلا من أخذها بحقها، وأدى الذى عليه فيها” ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1893","bookId":"riyad","type":"hadith","num":1893,"kitab":"كتاب المقدمات","isnad":"وعن أبى هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏","matn":"‏ “إنكم ستحرصون على الإمارة، وستكون ندامة يوم القيامة” ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:1894","bookId":"riyad","type":"hadith","num":1894,"kitab":"كتاب المقدمات","isnad":"-عن أبي سعيد وأبي هريرة رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال","matn":"‏:‏ “ما بعث الله من نبي، ولا استخلف من خليفة إلا كانت له بطانتان بطانة تأمره بالمعروف وتحضه عليه، وبطانة تأمره بالشر وتحضه عليه، والمعصوم من عصم الله” ‏(‏‏(‏رواه البخارى‏)‏‏)‏‏.‏"},{"id":"riyad:1895","bookId":"riyad","type":"hadith","num":1895,"kitab":"كتاب المقدمات","isnad":"وعن عائشة رضي الله عنها قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏","matn":"‏ “إذا أراد الله بالأمير خيراً، جعل له وزير صدق، إن نسي ذكره، وإن ذكر أعانه، وإذا أراد به غير ذلك جعل له وزير سوء، إن نسي لم يذكره، وإذ ذكر لم يعنه” ‏(‏‏(‏رواه أبو داود بإسناد جيد على شرط مسلم‏)‏‏)‏‏.‏"},{"id":"riyad:1896","bookId":"riyad","type":"hadith","num":1896,"kitab":"كتاب المقدمات","isnad":"","matn":"-عن أبى موسى الأشعري رضي الله عنه قال‏:‏ دخلت على النبى صلى الله عليه وسلم أنا ورجلان من بني عمي، فقال أحدهما‏:‏ يا رسول الله أمرنا على بعض ما ولاك الله، عز وجل، وقال الآخر مثل ذلك، فقال‏:‏ “إنا والله لا نولى هذا العمل أحدا سأله، أو أحدا حرص عليه” ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏"}]};